  async function moveManagedUser(id, destination) {
    const source = findVersion(id);
    const target = destination === 'standalone' ? null : data.groups.find(group => `g:${group.id}` === destination);
    if (!source || (destination !== 'standalone' && !target)
      || (!target && source.standalone) || target === source.group) return;
    const involved = [source.group.id, target?.id].filter(Boolean);
    if (busy || involved.some(groupId => syncingLoreGroups.has(groupId))) {
      notify('正在同步，请稍候再移动。', 'info');
      return;
    }
    const { personaId } = source.version;
    const sharedBook = hasSharedWorldbook(target) ? target.sharedWorldbook : null;
    const person = personaInfo(personaId);
    const originalBook = person?.lorebook || '';
    if (sharedBook !== null && !person) {
      notify('无法核对原生 User 的世界书，请先重新关联。', 'warning');
      return;
    }
    const changeBook = sharedBook !== null && sharedBook !== originalBook;
    if (changeBook && !host.confirm(`移动到「${target.name}」后，此 User 的默认世界书将从${originalBook ? `《${originalBook}》` : '无'}改为${sharedBook ? `《${sharedBook}》` : '无'}。确定移动？`)) return;

    busy = true;
    for (const groupId of involved) syncingLoreGroups.add(groupId);
    try {
      if (changeBook) {
        knownLorebooks.set(personaId, sharedBook);
        await HELPER.bindBook(personaId, sharedBook);
        const updated = personaInfo(personaId);
        if (!updated || (updated.lorebook || '') !== sharedBook) throw new Error('无法确认共用世界书已绑定');
      }
      if (findVersion(id)?.version !== source.version
        || (target && (!data.groups.includes(target) || (hasSharedWorldbook(target) ? target.sharedWorldbook : null) !== sharedBook))) {
        throw new Error('User 或分组设置已经变化，请重试');
      }
      const previous = data;
      const next = structuredClone(data);
      const origin = next.groups.find(group => group.id === source.group.id);
      const nextTarget = next.groups.find(group => group.id === target?.id);
      const version = (origin?.versions || next.standaloneUsers).find(entry => entry.id === id);
      const categoryId = (target || source.group).categoryId || '';
      if (origin) origin.versions = origin.versions.filter(entry => entry.id !== id);
      else next.standaloneUsers = next.standaloneUsers.filter(entry => entry.id !== id);
      if (nextTarget) {
        delete version.categoryId;
        nextTarget.versions.push(version);
        if (currentId() === personaId) nextTarget.lastUsedPersonaId = personaId;
      } else next.standaloneUsers.push({ ...version, categoryId });
      data = next;
      try { pruneAssociationReferences(); saveData(); }
      catch (err) { data = previous; writeConfigMirror(previous); throw err; }
