          if ((personaInfo(personaId)?.lorebook || '') !== originalBook) await HELPER.bindBook(personaId, originalBook);
          const restored = personaInfo(personaId);
          if (!restored || (restored.lorebook || '') !== originalBook) throw new Error('无法确认原绑定已恢复');
        } catch (rollbackError) {
          knownLorebooks.set(personaId, personaInfo(personaId)?.lorebook || '');
          warn('移动失败后的世界书还原未完成', rollbackError);
