      if (!entries.length) { loading.textContent = '这本世界书目前没有条目。'; return; }
      const list = element('div', 'pv-entries');
      list.classList.toggle('pv-entries-exclusive', mode === 'exclusive');
      const otherSelections = mode === 'common' ? indexManagedWorldbookEntries(ver.id).get(currentBook) : null;
      const searchableRows = [];
      const entrySearch = input(entryQuery, '搜索条目名称、UID 或正文');
      entrySearch.type = 'search';
      entrySearch.setAttribute('aria-label', '搜索条目');
      const checkedLabel = element('label', 'pv-preference');
      const checkedOnly = element('input');
      checkedOnly.type = 'checkbox';
      checkedOnly.checked = entryCheckedOnly;
      append(checkedLabel, checkedOnly, element('span', '', '仅看已勾选'));
      const noEntries = empty('没有匹配的条目。');
      function filterEntries() {
        entryQuery = entrySearch.value;
        entryCheckedOnly = checkedOnly.checked;
        const term = entryQuery.trim().toLocaleLowerCase();
        let found = false;
        for (const { row, text, checkbox } of searchableRows) {
          row.hidden = !text.includes(term) || (entryCheckedOnly && !checkbox.checked);
          if (!row.hidden) found = true;
        }
        noEntries.hidden = found;
      }
      for (const ent of entries) {
        const uid = Number(ent.uid);
        const name = ent.name || `条目 ${ent.uid}`;
        const row = element('div', 'pv-entry');
        const choice = element('label', 'pv-entry-choice');
        const checkbox = element('input');
        checkbox.type = 'checkbox';
        checkbox.checked = rule.included.has(uid);
        const entryStatus = element('small');
        const updateEntryStatus = () => {
          const other = !checkbox.checked && otherSelections?.has(uid);
          entryStatus.textContent = `UID ${ent.uid}${ent.enabled ? '' : ' · 原生已禁用'}${other ? ' · 已被其他 User 勾选' : ''}`;
        };
        updateEntryStatus();
        checkbox.addEventListener('change', () => {
          if (editScope === 'chat' && !checkChatScope()) return;
          const included = new Set(rule.included);
          if (checkbox.checked) included.add(uid); else included.delete(uid);
          try {
            if (editScope === 'chat') {
              updateChatScopedRecord(CHAT_ENTRIES_KEY, ver.id, currentBook, {
                ...chatEntryRule(ver.id, currentBook), include: [...included],
              }, originScope);
              syncResetVisibility();
            } else {
              if (included.size) ver.rules[currentBook] = [...included];
              else delete ver.rules[currentBook];
              saveData();
            }
            if (checkbox.checked) rule.included.add(uid); else rule.included.delete(uid);
            updateEntryStatus();
            if (entryCheckedOnly) filterEntries();
          } catch (err) {
            checkbox.checked = !checkbox.checked;
            notify(`保存条目失败：${err?.message || err}`, 'error');
          }
        });
        const detail = element('div', 'pv-entry-name');
        append(detail, element('span', '', name), entryStatus);
        append(choice, checkbox, detail);
        const toggle = button('查看内容', () => {
          const expanded = !preview.hidden;
          preview.hidden = expanded;
          toggle.textContent = expanded ? '查看内容' : '收起';
        }, 'pv-entry-toggle');
        const main = element('div', 'pv-entry-main');
        append(main, choice, toggle);
        const preview = element('div', 'pv-entry-preview');
        preview.hidden = true;
        // getWorldbook() returns a nested position object:
        // {type, role, depth, order}. Never stringify it as [object Object].
        const pos = ent.position;
        const position = pos && typeof pos === 'object' ? pos : { type: pos };
        const positionNames = {
          before_character_definition: '角色定义前',
          after_character_definition: '角色定义后',
          before_example_messages: '示例消息前',
          after_example_messages: '示例消息后',
          before_author_note: '作者注释前',
          after_author_note: '作者注释后',
          at_depth: '指定深度',
          outlet: '出口',
          0: '角色定义前', 1: '角色定义后',
          2: '作者注释前', 3: '作者注释后',
          4: '指定深度', 5: '示例消息前', 6: '示例消息后', 7: '出口',
        };
        const roleNames = { system: '系统', user: '用户', assistant: '助手', 0: '系统', 1: '用户', 2: '助手' };
        const type = position.type;
        const isDepth = type === 'at_depth' || type === 4;
        const positionName = positionNames[type] || (typeof type === 'string' ? type : '未知');
        const displayPosition = isDepth
          ? `${positionName}（${roleNames[position.role] || '系统'}）`
          : positionName;
        const info = [`位置：${displayPosition}`];
        const depth = position.depth ?? ent.depth;
        const order = position.order ?? ent.order;
        if (isDepth && depth != null) info.push(`深度：${depth}`);
        if (order != null) info.push(`顺序：${order}`);
        if (type === 'outlet' || type === 7) {
          const outletName = ent.outletName || ent.extra?.outletName;
          if (outletName) info.push(`出口名称：${outletName}`);
        }
        preview.append(element('small', 'pv-entry-metadata', info.join(' · ')));
        preview.append(element('div', 'pv-entry-content', String(ent.content || '（此条目没有正文）')));
        append(row, main, preview);
        list.append(row);
        searchableRows.push({ row, checkbox, text: [name, `UID ${ent.uid}`, ent.content].join(' ').toLocaleLowerCase() });
      }
      entrySearch.addEventListener('input', filterEntries);
      checkedOnly.addEventListener('change', filterEntries);
      filterEntries();
      loading.replaceWith(entrySearch, checkedLabel, list, noEntries);
    } catch (err) {
      if (!loading.isConnected) return;
      loading.textContent = `读取世界书失败：${err?.message || err}`;
      warn(err);
    }
  }
