    const standalone = group ? null : findStandalone(personaId);
    if (!group && !standalone) return false;
    const categoryId = (group?.categoryId ?? standalone?.categoryId) || '';
    if (categoryFilter && categoryId !== categoryFilter) return false;
    activeCategory = categoryId || (categories().length || standalone ? CATEGORY_UNCLASSIFIED : CATEGORY_ALL);
    activeGroup = group?.id || visibleGroups()[0]?.id || '';
