  function openPanel(preferPersonaId = '', preferCategoryId = '') {
    if (!isOpen) failedThumbnailIds.clear();
    isOpen = true;
    currentView = data.groups.length || standaloneUsers().length ? 'switch' : 'manage';
    const current = currentId();
    const category = categories().find(c => c.id === preferCategoryId);
    if (category) {
      if (!positionPanelOnPersona(current, currentView, category.id)) {
        activeCategory = category.id;
        activeGroup = visibleGroups()[0]?.id || '';
        groupTabScroll = 0;
        categoryTabScroll = 0;
      }
    } else {
      const pressedGroup = preferPersonaId && findByPersona(preferPersonaId)?.groupId;
      const target = pressedGroup && pressedGroup === findByPersona(current)?.groupId
        ? current : preferPersonaId || current;
      if (!positionPanelOnPersona(target, currentView)) positionPanelOnPersona(current, currentView);
    }
    try {
      refresh();
      // Revalidate on open: deleted avatar files should be detected even when
      // a previously verified snapshot exists. No extra native pagination pass.
      void verifyNativePersonaFiles().catch(() => {});
    } catch (err) {
      isOpen = false;
      warn('打开版本菜单失败', err);
      // 发生异常时提供用户可见的错误，不再静默无反应。
      host.alert(`无法打开版本菜单：${err?.message || err}`);
    }
