    try {
      page = Number(pager.pagination('getCurrentPageNum'));
      total = Number(pager.pagination('getTotalPage'));
    } catch (_) { /* Older helper/mocks may expose their model via data(). */ }
    const model = pager.data?.('pagination')?.model;
    if (!Number.isFinite(page) || page < 1) page = Number(model?.pageNumber);
