  function mount() {
    doc.getElementById(ROOT_ID)?.remove();
    root = element('div'); root.id = ROOT_ID;
    doc.addEventListener('keydown', onKeydown, true);
    doc.body.append(root);
    refresh();
  }
  function onKeydown(event) {
    if (event.key !== 'Escape' || !isOpen || event.isComposing) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    closePanel();
  }
  function cleanup() {
    isOpen = false;
    descriptionDrafts.clear();
    reorderState?.cancel();
    nativeSortPanelObserver?.disconnect();nativeSortPanelObserver = null;
    nativeSortMode = false;clearNativeSortPress();clearTimeout(nativeSortRefreshTimer);nativeSortRefreshTimer = null;nativeSortToolbar?.remove();nativeSortToolbar = null;doc?.documentElement?.classList.remove('pv-native-sort-mode');
    clearTimeout(refreshTimer); clearTimeout(nativeRebuildTimer); clearNativePress(); nativeSuppress = null;
    for (const t of extraTimers.splice(0)) clearTimeout(t);
    for (const off of unsubscribers.splice(0)) { try { off(); } catch (_) { /* ignore */ } }
    // The wrapper has been uninstalled: a single native refresh restores all Persona tiles.
    if (paginationOriginal) {
      try { doc?.getElementById('persona_sort_order')?.dispatchEvent(new host.Event('input', { bubbles: true })); }
      catch (err) { warn('原生分页恢复失败',err); }
    }
    if (doc) doc.removeEventListener('keydown', onKeydown, true);
    root?.remove(); style?.remove();
    doc?.documentElement?.classList.remove('pv-hide-chat-lock-hint');
    const cluster = doc?.querySelector('#persona_controls .pv-name-cluster');
    if (cluster) {
      const name = cluster.querySelector('#your_name');
      if (name) cluster.insertAdjacentElement('beforebegin', name);
      cluster.remove();
    }
    doc?.getElementById(INLINE_ID)?.remove(); root = null;
    if (host?.[BRIDGE_KEY]?.dispose === cleanup) delete host[BRIDGE_KEY];
  }
  function init() {
    try {
      host = window.parent;
      doc = host.document;
      if (!doc?.body) throw new Error('无法访问酒馆主页面');
      host[BRIDGE_KEY]?.dispose?.();
      host[BRIDGE_KEY] = { dispose: cleanup };

      // 优先挂载 GUI。旧版酒馆助手缺少 API 时也保留可点击的诊断入口。
      const essentials = ['getPersonaIds', 'getPersona', 'getCurrentPersonaId', 'updatePersonaWith', 'triggerSlash', 'getVariables', 'replaceVariables'];
      const missing = essentials.filter(name => typeof window[name] !== 'function');
      apiReady = missing.length === 0;
      bootError = missing.length
        ? `酒馆助手缺少 ${missing.join('、')} 接口。请更新到 4.8.12 或更新版本，再刷新酒馆。`
        : '';

      mountStyle();
      mount();
      ensureNativeSwitchButton();
      listenNativePersonaAvatars();
      // 在页面加载较迟时，补挂一次入口，不做持续的全局 DOM 扫描。
      for (const delayMs of [350, 1400, 3500]) extraTimers.push(setTimeout(() => {
        ensureNativeSwitchButton();
        if (apiReady) ensureNativeCollectionReady();
      }, delayMs));
      const onPanelInteraction = event => {
        if (event.target?.closest?.('#persona-management-button')) {
          ensureNativeSwitchButton();
          if (apiReady && (!paginationOriginal || nativeRebuildPending || !nativeDisplayedIds)) ensureNativeCollectionReady();
        }
      };
      doc.addEventListener('pointerdown', onPanelInteraction, true);
      unsubscribers.push(() => doc.removeEventListener('pointerdown', onPanelInteraction, true));

      if (!apiReady) {
        warn(bootError);
        notify(bootError, 'warning');
        refresh();
        return;
      }
      loadData();
      // The user currently active in ST is the newest use when the script starts.
      recordRecentPersona(currentId());
      seedKnownLorebooks();
      installNativeCollection();
      watchNativeTiles();
      // Verify real avatar files before ever constructing thumbnail URLs.
      // The request is asynchronous and leaves the native Persona grid alone.
      void verifyNativePersonaFiles().catch(() => {});
      const ctx = currentContext();
      listenWorldInfo();
      if (ctx?.eventSource?.on) {
        const eventNames = ctx.eventTypes || {};
        const personaUpdatedEvent = eventNames.PERSONA_UPDATED;
        if (personaUpdatedEvent) {
          ctx.eventSource.on(personaUpdatedEvent, onNativePersonaUpdated);
          unsubscribers.push(() => ctx.eventSource.removeListener(personaUpdatedEvent, onNativePersonaUpdated));
        }
        for (const [name, shouldRestore] of [['CHAT_CHANGED', true], ['PERSONA_CHANGED', false], ['CHAT_CREATED', true]]) {
          const eventType = eventNames[name];
          if (!eventType) continue;
          const fn = () => { if (name === 'PERSONA_CHANGED') recordRecentPersona(currentId()); scheduleRefresh(shouldRestore); };
          ctx.eventSource.on(eventType, fn);
          unsubscribers.push(() => ctx.eventSource.removeListener(eventType, fn));
        }
      }
      window.addEventListener('pagehide', cleanup, { once: true });
      unsubscribers.push(() => window.removeEventListener('pagehide', cleanup));
      scheduleRefresh(true, { initial: true });
      log('v1.0 已加载。');
    } catch (err) {
      console.error('[Persona Variants] 初始化失败', err);
      bootError = `初始化失败：${err?.message || err}`;
      notify(bootError, 'error');
      // 即便发生异常，也尽量留下原生界面内的入口，便于查看错误。
      try { if (doc?.body) { mountStyle(); mount(); ensureNativeSwitchButton(); } } catch (_) { /* ignore */ }
    }
  }
  if (typeof $ === 'function') $(() => init()); else init();
})();

(function () {
  const NAME = 'Rifugio · 玩具联动';
  const URL = 'https://api.gitcode.com/api/v5/repos/gcw_wrR0hlUX/st-toy/raw/sosexy-toy.json?ref=main';
  // Run inside the Tavern Helper script window so its message APIs remain available.
  const DOC = window.document;
  const ID = 'rifugio-remote-toy-script';

  fetch(URL, { cache: 'no-cache' })
    .then(function (response) {
      if (!response.ok) throw new Error('HTTP ' + response.status);
      return response.json();
    })
    .then(function (pack) {
      if (!pack || typeof pack.content !== 'string' || !pack.content.trim()) {
        throw new Error('远程 JSON 缺少 content 脚本');
      }
      DOC.getElementById(ID)?.remove();
      DOC.getElementById('clawed-remote-script')?.remove();
      // The panel script disposes its previous instance when the replacement starts.
      const blobUrl = window.URL.createObjectURL(new Blob([pack.content], { type: 'text/javascript' }));
      const script = DOC.createElement('script');
      script.id = ID;
      script.src = blobUrl;
      script.onload = function () {
        window.URL.revokeObjectURL(blobUrl);
        console.log('[' + NAME + '] 已载入：' + (pack.name || NAME));
      };
      script.onerror = function () {
        window.URL.revokeObjectURL(blobUrl);
        script.remove();
        alert(NAME + ' 加载失败：浏览器未能载入脚本，请检查网络或页面的脚本限制。');
      };
      DOC.head.appendChild(script);
    })
    .catch(function (error) {
      console.error('[' + NAME + ' 加载器]', error);
      alert(NAME + ' 加载失败：' + error.message + '\n请检查 GitCode 仓库中的 sosexy-toy.json 是否可公开读取，或网络是否正常。');
    });
})();

