.frame-pick {display:block;width:100%;padding:5px;border-radius:9px;}
.frame-pick img {display:block;width:100%;height:54px;object-fit:contain;}
.frame-pick[aria-pressed=true] {border-color:#ddd;background:#ffffff16;}
.frame-delete {position:absolute;right:0;top:0;min-height:22px;width:22px;padding:0;border-radius:50%;background:#333e;font:16px sans-serif;}
.frame-gallery-empty {grid-column:1/-1;margin:0;}

.frame-editor {border:0;padding:0;margin:0;min-width:0;}
.frame-editor:disabled {opacity:.45;}
.frame-editor > .font-options {grid-template-columns:repeat(3,minmax(0,1fr));}
.frame-editor > .font-options button {padding:8px 4px;font-size:12px;}
.frame-preview .sl-avatar-crop {background:#ffffff0c;}
.quick-panel .frame-section,.quick-panel .character-pendant {display:none !important;}
.character-pendant-editor {border:0;padding:0;margin:0;min-width:0;}
.header-preview-dock {flex:0 0 auto;min-width:0;padding:0 24px;}
.header-preview-dock[hidden] {display:none !important;}
.header-preview-dock > .header-preview {position:relative;top:auto;transform:translateZ(0);margin:0 0 10px;}
@media(max-width:600px){.header-preview-dock {padding:0 14px;}}

/* Keep the existing preview visible only while its own adjustments are open. */
.character-pendant-editor:has(> .character-pendant-options:not([hidden]) > details[open]) > .character-header-preview {
  position:sticky;top:0;z-index:3;background:#171717;transform:translateZ(0);
}
/* Give the onscreen keyboard room when editing a numeric value or text. */
.panel:has(input:is([type=text],[type=url],[type=number]):focus,textarea:focus) .header-preview {
  position:relative !important;top:auto !important;z-index:auto !important;
}

.character-pendant {margin:16px 0;padding:14px 0;border-top:1px solid #ffffff12;}
.character-pendant>summary {cursor:pointer;color:#bcbcbc;}
.character-pendant .caption-options {margin:12px 0;}
.header-upload-plus {display:grid;place-items:center;width:70px;max-width:100%;height:57px;font:26px sans-serif;color:#bcbcbc;}
.header-options .header-custom-thumb {object-fit:contain;}
.header-upload-tools {display:flex;gap:8px;align-items:center;margin:9px 0;}
.header-upload-tools button {font-size:11px;padding:5px 9px;}
.header-upload-hint {margin-bottom:10px;}

