  var CSS = "/* ==== 注入宿主样式（脚本版专有） ====\n   变量在这里重新声明一遍，不依赖从酒馆页面继承，\n   免得宿主环境的样式差异把面板配色带偏。 */\n:host{\n  position:fixed;inset:0;z-index:2147483000;display:block;\n  --bg:#120a13;--bg-glow-1:rgba(150,62,156,.22);--bg-glow-2:rgba(214,189,150,.06);\n  --card:rgba(238,222,242,.045);--card-2:rgba(238,222,242,.07);\n  --line:rgba(232,214,236,.10);--line-2:rgba(232,214,236,.18);\n  --hot:#c06cc2;--hot-2:#e2b6df;--hot-deep:#76207a;--cyan:#d6bd96;--amber:#eba866;\n  --cyan-a08:rgba(214,189,150,.08);--cyan-a40:rgba(214,189,150,.40);--cyan-a75:rgba(214,189,150,.75);\n  --hot-a12:rgba(192,108,194,.12);--hot-a20:rgba(192,108,194,.20);--hot-a28:rgba(192,108,194,.28);\n  --hot-a35:rgba(192,108,194,.35);--hot-a45:rgba(192,108,194,.45);--hot-a55:rgba(192,108,194,.55);\n  --hot-a75:rgba(192,108,194,.75);\n  --text:#f4ece3;--dim:#b9a5ad;--dim-2:#958290;\n  --r:16px;--safe-t:env(safe-area-inset-top,0px);--safe-b:env(safe-area-inset-bottom,0px);\n  --font:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Hiragino Sans GB\",\"Source Han Sans SC\",\"Microsoft YaHei\",system-ui,-apple-system,sans-serif;\n}\n#btn-close{display:none}\n\n/* ============================================================\n   TOY·LINK 手机端遥控器\n   单文件前端卡，零构建。运行环境：酒馆助手（Tavern Helper）iframe\n\n   两套主题靠变量切换（和悬浮球一套：梅紫硅胶 · 奶白底盘 · 香槟金环，哑光不反光）：\n     · 遥控器在你手里（默认）→ 梅紫 + 香槟金，底色梅黑\n     · 遥控器在 TA 手里     → 酒红 / 石榴红 + 香槟金，主导权不在你手上\n     · 自己玩（装置和遥控器都在你这）→ 遥控器在你手里，同默认梅紫\n   --cyan 沿用旧名，现在是香槟金（第二强调色：累积环、选中芯片、余像线）。\n   除背景渐变外不写第二套规则，全部靠变量自动跟随。\n   ============================================================ */\n:root{\n  --bg:#120a13;\n  --bg-glow-1:rgba(150,62,156,.22);\n  --bg-glow-2:rgba(214,189,150,.06);\n  --card:rgba(238,222,242,.045);\n  --card-2:rgba(238,222,242,.07);\n  --line:rgba(232,214,236,.10);\n  --line-2:rgba(232,214,236,.18);\n  --hot:#c06cc2;\n  --hot-2:#e2b6df;\n  --hot-deep:#76207a;\n  --hot-a12:rgba(192,108,194,.12);\n  --hot-a20:rgba(192,108,194,.20);\n  --hot-a28:rgba(192,108,194,.28);\n  --hot-a35:rgba(192,108,194,.35);\n  --hot-a45:rgba(192,108,194,.45);\n  --hot-a55:rgba(192,108,194,.55);\n  --hot-a75:rgba(192,108,194,.75);\n  --cyan:#d6bd96;\n  --cyan-a08:rgba(214,189,150,.08);\n  --cyan-a40:rgba(214,189,150,.40);\n  --cyan-a75:rgba(214,189,150,.75);\n  --amber:#eba866;\n  --text:#f4ece3;\n  --dim:#b9a5ad;\n  --dim-2:#958290;\n  --r:16px;\n  --safe-t:env(safe-area-inset-top,0px);\n  --safe-b:env(safe-area-inset-bottom,0px);\n  --font:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Hiragino Sans GB\",\"Source Han Sans SC\",\"Microsoft YaHei\",system-ui,-apple-system,sans-serif;\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%;margin:0}\nbody{\n  font-family:var(--font);\n  color:var(--text);\n  background:var(--bg);\n  overflow:hidden;\n  overscroll-behavior:none;\n  -webkit-font-smoothing:antialiased;\n}\nbutton,input{font-family:inherit;color:inherit}\nbutton{border:0;background:none;cursor:pointer}\n\n/* ---------- 舞台与手机外壳 ---------- */\n#shell{\n  position:relative;\n  width:100%;height:100dvh;height:100vh;min-height:600px;min-height:100vh;\n  display:flex;flex-direction:column;\n  overflow:hidden;\n  font-family:var(--font);\n  color:var(--text);\n  /* 底色用常量，不依赖 CSS 变量；渐变叠在上面，即使变量失效也不会透出底下的内容 */\n  background-color:#120a13;\n  background-image:\n    radial-gradient(120% 70% at 12% -8%, var(--bg-glow-1), transparent 62%),\n    radial-gradient(110% 60% at 92% 6%, var(--bg-glow-2), transparent 58%),\n    linear-gradient(180deg,#1b0e1d 0%, #120a13 55%, #09050a 100%);\n}\n#shell::after{\n  content:\"\";position:absolute;inset:0;pointer-events:none;opacity:.5;\n  background-image:linear-gradient(rgba(232,214,236,.018) 1px,transparent 1px),\n                   linear-gradient(90deg,rgba(232,214,236,.018) 1px,transparent 1px);\n  background-size:26px 26px;\n  mask-image:radial-gradient(120% 80% at 50% 0%,#000 30%,transparent 100%);\n}\n@media (min-width:860px){\n  body{display:grid;place-items:center;background:#060307}\n  #shell{\n    width:404px;height:min(800px,92vh);max-height:92vh;min-height:0;\n    border-radius:34px;\n    border:1px solid rgba(232,214,236,.09);\n    box-shadow:0 40px 120px rgba(0,0,0,.75),0 0 0 10px rgba(232,214,236,.02);\n  }\n}\n/* 全屏模式：窄屏默认就是全屏；宽屏可以手动切换 */\n#shell.fit{\n  width:100%;height:100dvh;height:100vh;max-height:none;min-height:0;\n  border-radius:0;border:0;box-shadow:none;\n}\n\n/* ---------- 顶栏 ---------- */\n.bar{\n  position:relative;z-index:5;flex:none;\n  display:flex;align-items:center;gap:10px;\n  padding:calc(var(--safe-t) + 12px) 16px 12px;\n}\n.brand{display:flex;align-items:center;gap:8px;min-width:0}\n.logo{\n  /* 装置本体（和悬浮球同一只 C 形）：梅紫哑光硅胶 + 香槟金环，不垫底盘、不画高光 */\n  width:30px;height:30px;flex:none;display:grid;place-items:center;\n  filter:drop-shadow(0 1.5px 2px rgba(0,0,0,.5));\n}\n.logo svg{width:30px;height:30px;display:block;overflow:visible}\n.brand b{\n  font-size:12px;letter-spacing:.22em;font-weight:700;text-transform:uppercase;\n  white-space:nowrap;color:var(--text);\n}\n.brand b i{font-style:normal;color:var(--cyan)}\n.brand .ver{\n  font-size:9.5px;letter-spacing:.06em;color:var(--dim-2);\n  white-space:nowrap;margin-left:-2px;\n}\n.conn{\n  margin-left:auto;display:flex;align-items:center;gap:6px;\n  font-size:11px;color:var(--dim);\n  padding:5px 10px;border:1px solid var(--line);border-radius:999px;\n  background:var(--card);white-space:nowrap;\n}\n.dot{width:7px;height:7px;border-radius:50%;background:var(--dim-2);flex:none}\n/* 已连接：固定绿灯闪烁，不跟主题走 —— 它是状态指示，不是装饰。\n   跟着主题变会让「连上了」这件事在两档下颜色不同，反而不好认。 */\n.dot.live{background:#5fd08e;box-shadow:0 0 6px rgba(95,208,142,.55);animation:pulse 1.6s ease-in-out infinite}\n.dot.demo{background:var(--amber);box-shadow:0 0 5px var(--amber)}\n@keyframes pulse{0%,100%{opacity:1}50%{opacity:.25}}\n\n/* 顶栏小按钮 */\n.bar-btn{\n  flex:none;width:30px;height:30px;margin-left:8px;border-radius:10px;\n  border:1px solid var(--line);background:var(--card);color:var(--dim);\n  font-size:12px;line-height:1;display:grid;place-items:center;\n}\n.bar-btn:active{transform:scale(.94)}\n@media (max-width:859px){ .bar-btn.narrow-hide{display:none} }\n\n/* ---------- 作用对象切换（常驻，面板最上方） ----------\n   这一档换的不是参数，是整台机器谁说了算：\n   你操控 = 遥控台（梅紫、可点）；TA 操控 = 只读仪表（酒红、锁住档位）。\n   第三档「自己玩」（1.12.0）：装置和遥控器都在你身上，遥控器在你手里，所以还是梅紫、可点。\n   三列：padding 4 + gap 4×2 = 16px，滑块宽 (100% - 16px) / 3，每挪一格 = 自身宽 + 一个 gap。 */\n.tgtbar{\n  position:relative;z-index:6;flex:none;\n  display:grid;grid-template-columns:repeat(3,1fr);gap:4px;\n  margin:0 16px 12px;padding:4px;border-radius:15px;\n  border:1px solid var(--line);background:rgba(238,222,242,.035);\n}\n.tgt-ind{\n  position:absolute;top:4px;bottom:4px;left:4px;width:calc((100% - 16px) / 3);\n  border-radius:11px;pointer-events:none;\n  background:linear-gradient(180deg,var(--hot-a28),var(--hot-a12));\n  border:1px solid var(--hot-a45);\n  box-shadow:0 2px 10px rgba(0,0,0,.25);\n  transition:transform .3s cubic-bezier(.4,0,.2,1),background .3s,border-color .3s,box-shadow .3s;\n}\n.tgt{\n  position:relative;z-index:1;min-width:0;padding:9px 4px;border-radius:11px;\n  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;\n  color:var(--dim);transition:color .22s;\n}\n.tgt b{font-size:12px;font-weight:700;letter-spacing:.02em;white-space:nowrap}\n/* 三格挤在 ~340px 的面板里：副标题极窄时允许折成两行，不许溢出 */\n.tgt i{font-style:normal;font-size:9px;letter-spacing:.03em;opacity:.7;white-space:normal;text-align:center;line-height:1.3}\n.tgt.on{color:var(--text)}\n.tgt.on i{opacity:.85}\n\n/* 装置运行中：作用对象切换锁住。\n   这不是防误触，是防矛盾 —— 运行中换对象会整本重写世界书，\n   而装置还带着上一个对象的运行状态，AI 会同时收到两套说法。\n   要换就先停。 */\n.tgtbar.locked{opacity:.45}\n.tgtbar.locked .tgt{cursor:not-allowed}\n.tgtbar.locked .tgt-ind{filter:grayscale(.55)}\n.tgtbar.locked .tgt:active{transform:none}\n\n/* 切到 TA 拿着遥控器：主导权不在你手上，整机从梅紫换成酒红 / 石榴红（悬浮球晕光同步变红）。\n   香槟金不变，还是同一个牌子；这里只换变量和背景，其余规则全部靠 var() 自动跟随。 */\n#shell.tgt-user{\n  --hot:#e0566f;\n  --hot-2:#f2b0ba;\n  --hot-deep:#8a1a33;\n  --hot-a12:rgba(224,86,111,.12);\n  --hot-a20:rgba(224,86,111,.20);\n  --hot-a28:rgba(224,86,111,.28);\n  --hot-a35:rgba(224,86,111,.35);\n  --hot-a45:rgba(224,86,111,.45);\n  --hot-a55:rgba(224,86,111,.55);\n  --hot-a75:rgba(224,86,111,.75);\n  --bg-glow-1:rgba(176,34,68,.26);\n  --bg-glow-2:rgba(214,189,150,.06);\n  --card:rgba(250,226,230,.045);\n  --card-2:rgba(250,226,230,.07);\n  --line:rgba(244,214,220,.10);\n  --line-2:rgba(244,214,220,.18);\n  --text:#f6ebe5;\n  --dim:#bfa2a5;\n  --dim-2:#9a7f83;\n  background-color:#13070a;\n  background-image:\n    radial-gradient(120% 70% at 12% -8%, var(--bg-glow-1), transparent 62%),\n    radial-gradient(110% 60% at 92% 6%, var(--bg-glow-2), transparent 58%),\n    linear-gradient(180deg,#1e0a10 0%, #13070a 55%, #0a0305 100%);\n}\n#shell.tgt-user .tgt-ind{transform:translateX(calc(100% + 4px))}\n#shell.tgt-self .tgt-ind{transform:translateX(calc(200% + 8px))}\n/* 圆环渐变：两个停靠点跟着主色走 */\n.ring .s1{stop-color:var(--cyan)}\n.ring .s2{stop-color:var(--hot)}\n.ring .s3{stop-color:var(--hot-2)}\n#v-device.locked .ring .s3{stop-color:var(--hot-2)}\n\n/* 遥控器在 TA 手里时，档位控件整体降级为只读仪表 */\n.lockbar{\n  margin:0 0 12px;padding:10px 13px;border-radius:13px;\n  border:1px dashed var(--hot-a45);background:var(--hot-a12);\n  display:flex;flex-direction:column;gap:3px;\n}\n.lockbar b{font-size:12px;color:var(--hot-2);letter-spacing:.04em}\n.lockbar span{font-size:11px;color:var(--dim);line-height:1.55}\n.lockbar[hidden]{display:none}\n.lockbar.pending{border-style:solid;animation:lockpulse 1.5s ease-in-out infinite}\n@keyframes lockpulse{0%,100%{opacity:1}50%{opacity:.5}}\n\n/* 请求停止：遥控器在 TA 手里时，这是玩家唯一还能做的事。\n   放在电源区上方常驻，不跟着内容滚 —— 做成呼吸的样子，因为它得一直勾着人去按。\n   配色走琥珀而不是主色：主色是\"谁在掌控\"，求饶是另一回事，混在一起两个按钮会糊成一团。 */\n.begbar{flex:none;padding:0 16px 10px}\n.begbar[hidden]{display:none}\n.beg{\n  display:flex;flex-direction:column;align-items:center;gap:3px;\n  width:100%;padding:12px 14px;border-radius:14px;\n  border:1px solid rgba(235,168,102,.48);\n  background:linear-gradient(180deg,rgba(235,168,102,.16),rgba(235,168,102,.06));\n  animation:begbreath 3.2s ease-in-out infinite;\n}\n.beg b{font-size:13.5px;font-weight:700;letter-spacing:.06em;color:#f6d3a8}\n.beg i{font-style:normal;font-size:10.5px;color:var(--dim);letter-spacing:.04em;text-align:center}\n.beg:active{transform:scale(.985)}\n.beg:disabled{animation:none;opacity:.6}\n@keyframes begbreath{\n  0%,100%{box-shadow:0 0 0 0 rgba(235,168,102,.20)}\n  50%{box-shadow:0 0 18px 1px rgba(235,168,102,.20)}\n}\n\n/* 只读态：能看不能碰。当前档位仍然高亮，因为它就是\"TA 现在用的是哪一档\" */\n#v-device.locked .modes{opacity:.5}\n#v-device.locked .mode{cursor:default;transition:none}\n/* 真 disabled 的按钮会被浏览器套上灰字色，会把 currentColor 的图标一起带灰，改回来 */\n#v-device.locked .mode:disabled{color:inherit}\n#v-device.locked .mode:active{transform:none}\n#v-device.locked .mode.on{\n  opacity:1;\n  border-color:var(--hot-a75);\n  background:linear-gradient(180deg,var(--hot-a20),var(--hot-a12));\n  box-shadow:none;\n}\n#v-device.locked .ctl input[type=range]{opacity:.55;pointer-events:none}\n#v-device.locked .ctl input[type=range]::-webkit-slider-thumb{box-shadow:none}\n#v-device.locked #dur-chips{opacity:.5;pointer-events:none}\n#v-device.locked .chip{cursor:default}\n#v-device.locked .chip:active{transform:none}\n\n/* ---------- 主舞台 ---------- */\n.stage{\n  position:relative;z-index:2;flex:1 1 auto;min-height:0;\n  overflow-y:auto;overscroll-behavior:contain;\n  -webkit-overflow-scrolling:touch;\n  padding:2px 16px 20px;\n  scrollbar-width:none;\n}\n.stage::-webkit-scrollbar{display:none}\n.stage[hidden]{display:none}\n\n/* ---------- 圆环仪表 ---------- */\n.hero{\n  position:relative;\n  display:grid;place-items:center;\n  padding:6px 0 4px;\n}\n.ring{position:relative;width:min(232px,56vw,30vh);height:min(232px,56vw,30vh)}\n@media (max-height:700px){\n  .wave-wrap{height:52px}\n  .readout .big{font-size:clamp(30px,10vw,42px)}\n}\n.ring svg{width:100%;height:100%;transform:rotate(-90deg)}\n.ring .trk{fill:none;stroke:rgba(232,214,236,.07);stroke-width:7}\n.ring .val{fill:none;stroke:url(#gr);stroke-width:7;stroke-linecap:round;\n  transition:stroke-dasharray .12s linear}\n.ring .val2{fill:none;stroke:var(--cyan-a75);stroke-width:3;stroke-linecap:round}\n.readout{\n  position:absolute;inset:0;display:grid;place-content:center;text-align:center;gap:2px;\n}\n.readout .big{\n  font-size:clamp(38px,13vw,54px);font-weight:800;line-height:1;letter-spacing:-.02em;\n  font-variant-numeric:tabular-nums;color:var(--text);\n}\n.readout .big small{font-size:.38em;font-weight:600;letter-spacing:.06em;color:var(--dim);margin-left:4px}\n.readout .sub{font-size:11.5px;color:var(--dim);letter-spacing:.14em;font-variant-numeric:tabular-nums}\n.readout .mode-tag{\n  margin-top:6px;font-size:11px;color:var(--hot-2);letter-spacing:.2em;\n  text-transform:uppercase;\n}\n.ring.off .val{stroke:rgba(232,214,236,.10)}\n.ring.off .big{color:var(--dim);text-shadow:none}\n\n/* ---------- 波形 ---------- */\n.wave-wrap{\n  position:relative;margin:10px 0 2px;height:66px;border-radius:14px;\n  border:1px solid var(--line);background:linear-gradient(180deg,rgba(238,222,242,.035),rgba(238,222,242,.01));\n  overflow:hidden;\n}\n.wave-wrap canvas{position:absolute;inset:0;width:100%;height:100%;display:block}\n.wave-tag{\n  position:absolute;left:10px;top:7px;font-size:9.5px;letter-spacing:.2em;\n  color:var(--dim-2);text-transform:uppercase;\n}\n\n/* ---------- 阶段进度 ---------- */\n.phases{display:flex;gap:6px;margin:12px 0 4px}\n.phase{flex:1;height:4px;border-radius:4px;background:rgba(232,214,236,.09);overflow:hidden}\n.phase i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--cyan),var(--hot));transition:width .3s}\n.phase.done i{width:100%}\n.freeze{\n  margin:9px 0 0;padding:7px 12px;border-radius:10px;text-align:center;\n  font-size:11.5px;letter-spacing:.05em;color:var(--cyan);cursor:pointer;\n  border:1px dashed var(--cyan-a40);background:var(--cyan-a08);\n}\n.freeze:active{transform:scale(.99)}\n.freeze[hidden]{display:none}\n.phase-head{display:flex;justify-content:space-between;font-size:11px;color:var(--dim);letter-spacing:.1em}\n.phase-head b{color:var(--text);font-weight:600}\n.phase-head .full-mark{color:var(--amber);font-weight:700;letter-spacing:.14em}\n.phase-head .full-mark[hidden]{display:none}\n\n/* ---------- 「贴上 / 拿起」----------\n   并排两颗、等宽平分。选中的那颗用琥珀色框出来（和主题里的警示色一套），\n   一眼能看出装置现在是在身上还是已经被拿走了。 */\n.gate{display:flex;gap:8px;margin:10px 0 2px}\n.gate button{\n  flex:1 1 0;min-width:0;padding:9px 6px;border-radius:11px;cursor:pointer;\n  font-size:12.5px;letter-spacing:.08em;font-family:inherit;\n  border:1px solid var(--line);background:rgba(238,222,242,.03);color:var(--dim);\n  transition:border-color .18s,background .18s,color .18s,opacity .18s,box-shadow .18s;\n}\n.gate button:active{transform:scale(.98)}\n/* 选中态：琥珀色描边 + 淡底 + 字色跟上 + 一点点外发光，够醒目但不刺眼 */\n.gate button.on{\n  border-color:var(--amber);\n  background:rgba(235,168,102,.14);\n  color:#f6dfc2;\n  box-shadow:0 0 0 1px rgba(235,168,102,.35), 0 4px 14px rgba(235,168,102,.12);\n  font-weight:700;\n}\n\n/* ---------- 模式锁定：临界 / 冲刺 还没到阶段 ----------\n   虚化 + 斜线，一眼看出\"这个档还不能用\"。刻意不用 disabled：\n   那样点击会被整个吞掉，连\"为什么不能点\"都没法提示。 */\n.mode.lk{opacity:.34;pointer-events:auto;border-style:dashed}\n.mode.lk::after{\n  content:\"锁\";position:absolute;right:5px;top:4px;font-size:9px;letter-spacing:.05em;\n  color:var(--amber);opacity:.9;\n}\n\n/* ---------- 通用面板 ---------- */\n.panel{\n  margin-top:14px;padding:14px;border-radius:var(--r);\n  border:1px solid var(--line);background:var(--card);\n  backdrop-filter:blur(6px);\n}\n.panel h3{\n  margin:0 0 11px;font-size:10.5px;letter-spacing:.2em;color:var(--dim-2);\n  text-transform:uppercase;font-weight:700;\n}\n.panel h3 .tag{\n  margin-left:8px;padding:2px 8px;border-radius:999px;\n  font-size:9.5px;letter-spacing:.06em;text-transform:none;font-weight:600;\n  color:var(--amber);background:rgba(235,168,102,.10);\n  border:1px solid rgba(235,168,102,.32);\n}\n.panel h3 .tag:empty{display:none}\n\n/* ---------- 模式网格 ---------- */\n.modes{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}\n@media (max-width:360px){.modes{grid-template-columns:repeat(3,1fr)}}\n.mode{\n  position:relative;padding:11px 4px 9px;border-radius:13px;\n  border:1px solid var(--line);background:rgba(238,222,242,.025);\n  display:flex;flex-direction:column;align-items:center;gap:5px;\n  transition:transform .12s,border-color .18s,background .18s;\n}\n.mode:active{transform:scale(.94)}\n.mode svg{width:26px;height:26px;opacity:.8;color:var(--cyan)}\n.mode span{font-size:10.5px;letter-spacing:.04em;color:var(--dim)}\n.mode.on{\n  border-color:var(--hot-a75);\n  background:linear-gradient(180deg,var(--hot-a20),var(--hot-a12));\n  box-shadow:0 4px 14px rgba(0,0,0,.22);\n}\n.mode.on svg{opacity:1;color:var(--hot-2)}\n.mode.on span{color:var(--text);font-weight:600}\n\n/* ---------- 滑块 ---------- */\n.ctl{display:block;margin-top:14px}\n.ctl:first-of-type{margin-top:0}\n.ctl .row{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}\n.ctl .row span{font-size:12px;color:var(--dim);letter-spacing:.08em}\n.ctl .row b{\n  font-size:15px;font-weight:700;font-variant-numeric:tabular-nums;\n  color:var(--text);letter-spacing:.02em;\n}\n.ctl .row b em{font-style:normal;font-size:10.5px;color:var(--dim);margin-left:2px;letter-spacing:.06em}\ninput[type=range]{\n  -webkit-appearance:none;appearance:none;width:100%;height:30px;background:transparent;\n}\ninput[type=range]::-webkit-slider-runnable-track{\n  height:6px;border-radius:6px;\n  background:linear-gradient(90deg,var(--hot) var(--p,50%),rgba(232,214,236,.10) var(--p,50%));\n}\ninput[type=range]::-webkit-slider-thumb{\n  -webkit-appearance:none;width:22px;height:22px;margin-top:-8px;border-radius:50%;\n  background:#f6efe7;border:3px solid var(--hot);\n  box-shadow:0 2px 6px rgba(0,0,0,.4);\n}\ninput[type=range]::-moz-range-track{height:6px;border-radius:6px;background:rgba(232,214,236,.10)}\ninput[type=range]::-moz-range-progress{height:6px;border-radius:6px;background:var(--hot)}\ninput[type=range]::-moz-range-thumb{\n  width:22px;height:22px;border-radius:50%;background:#f6efe7;border:3px solid var(--hot);\n}\n\n/* ---------- 快捷芯片 ---------- */\n.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n.chip{\n  padding:7px 12px;border-radius:999px;font-size:11.5px;color:var(--dim);\n  border:1px solid var(--line);background:rgba(238,222,242,.025);\n}\n.chip.on{border-color:var(--cyan-a75);color:#efe0c6;background:var(--cyan-a08)}\n.chip:active{transform:scale(.96)}\n/* 保存类按钮：和普通 chip 拉开一点，让人一眼找到\"确认\"在哪 */\n.chip.save{\n  border-color:var(--hot-a45);color:var(--hot-2);\n  background:linear-gradient(180deg,var(--hot-a20),var(--hot-a12));\n  font-weight:700;\n}\n\n/* ---------- 电源键 ---------- */\n/* 「先说一句再催」：底栏上方整行输入。留空就是纯粹的催一下，行为和以前一模一样。 */\n.nowline{flex:none;padding:0 16px 10px}\n.nowline input{\n  width:100%;box-sizing:border-box;padding:9px 11px;border-radius:11px;\n  font-size:13px;border:1px solid var(--line);background:rgba(0,0,0,.35);outline:none;\n  -webkit-appearance:none;appearance:none;\n}\n.nowline input::placeholder{color:var(--dim-2);opacity:1}\n.nowline input:focus{border-color:var(--hot-a55)}\n.powerbar{\n  position:relative;z-index:5;flex:none;display:flex;gap:10px;\n  padding:12px 16px calc(var(--safe-b) + 12px);\n  border-top:1px solid var(--line);\n  background:linear-gradient(180deg,rgba(10,5,10,.35),rgba(10,5,10,.92));\n  backdrop-filter:blur(12px);\n}\n/* 两颗各占一半（flex:1 1 0），宽度随面板走，不需要写死 */\n.power{\n  flex:1 1 0;min-width:0;padding:15px 10px;border-radius:15px;\n  font-size:14.5px;font-weight:700;letter-spacing:.1em;\n  background:linear-gradient(160deg,var(--hot) -35%,var(--hot-deep,#76207a) 90%);\n  color:#fbf6f0;box-shadow:0 6px 18px rgba(0,0,0,.35);\n  transition:transform .12s,filter .2s;\n}\n.power:active{transform:scale(.975)}\n.power.stop{background:linear-gradient(160deg,#352a36,#1f1720);color:var(--text);box-shadow:none;border:1px solid var(--line-2)}\n/* 「立即反应一次」：和启停键平分底栏，字要看得清 */\n.ghost{\n  flex:1 1 0;min-width:0;padding:15px 12px;border-radius:15px;\n  border:1px solid var(--line);background:var(--card);\n  font-size:14px;font-weight:600;letter-spacing:.06em;color:var(--cyan);\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\n}\n.ghost:active{transform:scale(.97);background:var(--card-2)}\n.ghost:disabled{opacity:.45}\n\n/* ---------- 视图切换 ---------- */\n.dock{\n  position:relative;z-index:5;flex:none;display:flex;\n  border-top:1px solid var(--line);\n  padding-bottom:var(--safe-b);background:rgba(10,5,10,.92);\n}\n.tab{\n  flex:1;padding:10px 4px calc(10px + var(--safe-b)/2);font-size:11px;color:var(--dim-2);\n  letter-spacing:.1em;position:relative;\n}\n.tab.on{color:var(--text)}\n.tab.on::after{\n  content:\"\";position:absolute;left:50%;top:0;transform:translateX(-50%);\n  width:26px;height:2px;border-radius:2px;background:var(--cyan);\n}\n.tab b{display:block;font-size:16px;font-weight:400;margin-bottom:3px}\n.tab.on b{color:var(--cyan)}\n\n/* ---------- 反应流 ----------\n   顶部那条是「语音重写栏」：不对 TA 说话，只指挥这一句台词怎么念。 */\n.relay{\n  position:sticky;top:0;z-index:4;\n  margin:0 0 12px;padding:9px 10px;border-radius:14px;\n  border:1px solid var(--line);background:var(--card-2);\n  backdrop-filter:blur(10px);\n}\n.relay .rtarget{\n  font-size:10.5px;color:var(--dim-2);letter-spacing:.03em;\n  margin:0 2px 7px;line-height:1.5;\n}\n.relay .rtarget b{color:var(--cyan);font-weight:600}\n.relay .rtarget.on{color:var(--dim)}\n.relay .rrow{display:flex;gap:8px}\n.relay input{\n  flex:1;min-width:0;padding:10px 13px;border-radius:11px;font-size:15px;\n  border:1px solid var(--line);background:rgba(0,0,0,.42);color:var(--text);outline:none;\n}\n.relay input:focus{border-color:var(--hot-a55)}\n.relay input:disabled{opacity:.5}\n.relay button{\n  flex:none;padding:0 15px;border-radius:11px;font-size:12.5px;font-weight:700;\n  color:#fbf6f0;background:linear-gradient(160deg,var(--hot) -35%,var(--hot-deep) 90%);\n}\n.relay button:active{transform:scale(.96)}\n.relay button:disabled{\n  background:var(--card);color:var(--dim-2);border:1px solid var(--line);font-weight:600;\n}\n.relay .rmini{\n  flex:none;padding:6px 11px;border-radius:999px;font-size:11px;font-weight:600;\n  background:transparent;color:var(--dim);border:1px solid var(--line);\n}\n.relay .rmini:active{transform:scale(.96)}\n\n/* ---------- 语音页：合成记录 ----------\n   条目多，所以做成一页六条 + 翻页；每条只留「播 / 存」两个动作，不堆控件。 */\n.recbar{\n  display:flex;align-items:center;gap:8px;margin-bottom:9px;\n  font-size:10.5px;color:var(--dim-2);\n}\n.recbar span{flex:1;min-width:0}\n.recbar .rmini{\n  flex:none;padding:5px 10px;border-radius:999px;font-size:10.5px;font-weight:600;\n  background:transparent;color:var(--dim);border:1px solid var(--line);\n}\n.recbar .rmini:active{transform:scale(.96)}\n.recbar .rmini:disabled{opacity:.4}\n.reclist{display:flex;flex-direction:column;gap:7px}\n.recl{\n  display:flex;align-items:center;gap:9px;padding:9px 10px;border-radius:11px;\n  border:1px solid var(--line);background:rgba(0,0,0,.22);\n}\n.recl .m{flex:1;min-width:0}\n.recl .t{\n  font-size:12.5px;color:var(--text);line-height:1.5;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.recl .s{\n  font-size:10px;color:var(--dim-2);margin-top:3px;\n  font-family:ui-monospace,SFMono-Regular,Menlo,monospace;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.recl .b{\n  flex:none;padding:6px 10px;border-radius:9px;font-size:11px;font-weight:600;\n  border:1px solid var(--line);background:rgba(238,222,242,.05);color:var(--dim);\n}\n.recl .b:active{transform:scale(.95)}\n.recl .b.on{border-color:var(--hot);color:var(--hot-2);background:var(--hot-a12)}\n\n/* ---------- 语音页：高级项折叠 ----------\n   请求头名、音色字段名这些平时不该出现在主流程里，折叠起来，\n   但遇到\"说不清原因的 400\"要有个明确的地方去对。 */\n.adv{margin:12px 0 4px;border-top:1px solid var(--line);padding-top:11px}\n.adv>summary{\n  font-size:12px;color:var(--dim);letter-spacing:.03em;cursor:pointer;\n  list-style:none;padding:3px 0;\n}\n.adv>summary::-webkit-details-marker{display:none}\n.adv>summary::before{content:\"▸ \";color:var(--cyan)}\n.adv[open]>summary::before{content:\"▾ \"}\n.adv>.inner{padding-top:11px}\n\n/* ---------- 语音页：语气符号模板 ----------\n   标签按类分组，点一下复制到剪贴板。做成小方块而不是长条，\n   因为要一眼扫完十几个符号；中文标签比英文宽，用 auto 宽度让它自己撑。 */\n.tagsec{margin-top:13px}\n.taghead{\n  display:flex;align-items:baseline;gap:8px;\n  font-size:10.5px;color:var(--dim);letter-spacing:.08em;margin:11px 0 6px;\n}\n.taghead span{font-size:10px;color:var(--dim-2);letter-spacing:0}\n.tagrow{display:flex;flex-wrap:wrap;gap:6px}\n.tag{\n  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;\n  font-size:10.5px;padding:5px 9px;border-radius:8px;\n  border:1px solid var(--line-2);background:rgba(238,222,242,.045);\n  color:var(--cyan);cursor:pointer;white-space:nowrap;\n  transition:border-color .15s,background .15s,transform .12s;\n}\n.tag:hover{border-color:var(--hot);color:var(--hot-2)}\n.tag:active{transform:scale(.94)}\n.tag b{\n  font-family:var(--font);font-weight:500;font-size:10px;\n  color:var(--dim-2);margin-left:6px;\n}\n.tag.ok{border-color:#5fd08e;color:#a8e8c2;background:rgba(95,208,142,.12)}\n\n/* ---------- 自动播放的\"社死\"警示 ----------\n   自动播放是唯一会\"在没人点的情况下出声\"的开关，\n   所以它开着的时候必须有存在感：开关脉冲发光 + 一条常驻警示条 + 入口处的红字。 */\n.sw.danger.on{\n  background:linear-gradient(160deg,#ff8a5c,#c23a2a);\n  animation:swglow 2.2s ease-in-out infinite;\n}\n.sw.danger.on i{background:#fff8f0}\n@keyframes swglow{\n  0%,100%{box-shadow:0 0 0 0 rgba(255,120,90,.45)}\n  50%{box-shadow:0 0 0 7px rgba(255,120,90,0)}\n}\n.danger-chip{\n  border-color:rgba(255,120,90,.55)!important;\n  color:#ffb9a3!important;\n  background:linear-gradient(180deg,rgba(255,120,90,.20),rgba(255,120,90,.10))!important;\n  font-weight:700;\n  animation:weakpulse 2.6s ease-in-out infinite;\n}\n@keyframes weakpulse{0%,100%{opacity:1}50%{opacity:.6}}\n.danger-note{\n  margin:9px 0 0;padding:10px 12px;border-radius:11px;\n  border:1px solid rgba(255,120,90,.5);\n  background:linear-gradient(180deg,rgba(255,120,90,.16),rgba(255,120,90,.07));\n  font-size:11.5px;line-height:1.75;color:#ffcbb8;\n}\n.danger-note b{color:#ff9d80}\n.danger-note[hidden]{display:none}\n\n/* ---------- 语音页的运行日志 ----------\n   等宽小字、能滚、滚到底自动跟着走。四种颜色对应 正常/提示/警告/失败。 */\n.vlog{\n  height:150px;overflow:auto;padding:8px 9px;border-radius:11px;\n  border:1px solid var(--line);background:rgba(0,0,0,.45);\n  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;\n  font-size:10.5px;line-height:1.65;color:var(--dim);\n}\n.vlog .lg{display:flex;gap:7px;align-items:baseline}\n.vlog .lg i{flex:none;color:var(--dim-2);font-style:normal;letter-spacing:-.02em}\n.vlog .lg.ok{color:#8fd6a6}\n.vlog .lg.err{color:#f0908a}\n.vlog .lg.warn{color:var(--amber)}\n.vlog .lg.hi{color:var(--cyan)}\n.vlog .lg.step{color:var(--dim-2)}\n.vlog .lgdim{color:var(--dim-2)}\n.vlog::-webkit-scrollbar{width:5px}\n.vlog::-webkit-scrollbar-thumb{background:rgba(232,214,236,.18);border-radius:3px}\n\n.feed{display:flex;flex-direction:column;gap:12px;padding:4px 0 8px}\n.feed-empty{\n  text-align:center;color:var(--dim-2);font-size:12px;line-height:2;\n  padding:56px 20px;letter-spacing:.08em;\n}\n.msg{max-width:100%;animation:rise .45s cubic-bezier(.2,.7,.3,1)}\n@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n.msg .who{\n  display:flex;align-items:center;gap:7px;font-size:10.5px;color:var(--dim-2);\n  letter-spacing:.16em;text-transform:uppercase;margin-bottom:6px;\n}\n.msg .who i{width:16px;height:16px;border-radius:5px;background:linear-gradient(160deg,var(--hot),var(--hot-deep));display:block}\n.msg .bubble{\n  padding:12px 14px;border-radius:14px;font-size:13.5px;line-height:1.75;\n  background:var(--card-2);border:1px solid var(--line);white-space:pre-wrap;word-break:break-word;\n}\n.msg.me .bubble{background:var(--hot-a12);border-color:var(--hot-a28)}\n.msg.sys .bubble{\n  background:transparent;border-style:dashed;color:var(--dim);font-size:11.5px;padding:8px 12px;\n}\n.msg.now .bubble{box-shadow:0 0 0 1px var(--cyan-a40)}\n.blink::after{content:\"▍\";color:var(--cyan);animation:pulse 1s infinite}\n/* 被选中准备重写的那一条：主色描边，一眼看出改的是谁 */\n.msg.relay-on .bubble{box-shadow:0 0 0 2px var(--hot-a55)}\n.msg.relay-on .who{color:var(--hot-2)}\n\n/* ---------- 心声里的语音条 ----------\n   气泡里分两层：.vline 是要念出来的台词（带情绪标记），\n   .sub 是下面那行给眼睛看的说明文字 —— 一眼能分清哪句会出声。 */\n.bubble .vline{\n  font-size:14.5px;line-height:1.7;color:var(--text);\n  letter-spacing:.01em;word-break:break-word;\n}\n.bubble .sub{\n  display:block;margin-top:6px;padding-top:5px;\n  border-top:1px dashed var(--line);font-size:11px;color:var(--dim-2);line-height:1.5;\n}\n.vbar{display:flex;gap:8px;margin-top:7px}\n.ebar{display:flex;gap:8px;margin-top:6px}\n.vplay{\n  padding:6px 12px;border-radius:999px;font-size:11.5px;letter-spacing:.04em;\n  border:1px solid var(--line);background:rgba(238,222,242,.05);color:var(--dim);\n  display:flex;align-items:center;gap:6px;\n}\n.vplay .ico{color:var(--cyan);font-size:10px}\n.vplay:active{transform:scale(.97)}\n.vplay.on{border-color:var(--hot);color:var(--hot-2);background:var(--hot-a12)}\n.vplay.on .ico{color:var(--hot-2)}\n/* 标记本身是给机器读的，界面上压暗一点，别抢台词的视线 */\n.bubble .vline::first-line{}\n\n/* ---------- 设置页 ---------- */\n.field{\n  display:flex;align-items:center;justify-content:space-between;gap:12px;\n  padding:12px 0;border-bottom:1px solid var(--line);\n}\n.field:last-child{border-bottom:0}\n.field .lb{min-width:0}\n.field .lb b{display:block;font-size:13px;font-weight:600;margin-bottom:3px}\n.field .lb small{display:block;font-size:11px;color:var(--dim-2);line-height:1.5}\n.sw{\n  position:relative;width:46px;height:27px;border-radius:999px;flex:none;\n  background:rgba(232,214,236,.10);border:1px solid var(--line);transition:background .2s;\n}\n.sw i{\n  position:absolute;top:2.5px;left:2.5px;width:20px;height:20px;border-radius:50%;\n  background:#f6efe7;transition:transform .2s;\n}\n.sw.on{background:linear-gradient(160deg,var(--hot) -20%,var(--hot-deep) 100%);border-color:transparent}\n.sw.on i{transform:translateX(19px)}\n.mini{\n  flex:none;padding:8px 13px;border-radius:10px;font-size:12px;\n  border:1px solid var(--line);background:var(--card);color:var(--dim);\n}\n.mini:active{transform:scale(.96)}\n\n/* ---------- 音色簿（常驻）----------\n   两行：上面是下拉框（占满宽度，手机上也不用挤），\n   下面是三个操作按钮，等宽平分。\n   以前这块是\"保存过才出现\"，功能藏在保存按钮后面，找不到入口的人不知道有它。 */\n.voicebook{display:flex;flex-direction:column;gap:7px;margin-top:9px}\n.vbrow{display:flex;gap:7px;align-items:center}\n.voicebook select{\n  flex:1;min-width:0;padding:8px 10px;border-radius:10px;font-size:12.5px;\n  color:var(--text);background-color:rgba(0,0,0,.55);color-scheme:dark;\n  border:1px solid var(--line);-webkit-appearance:none;appearance:none;\n}\n.voicebook select option{color:var(--text);background-color:#241a26}\n.voicebook .mini{\n  flex:1 1 0;min-width:0;padding:8px 6px;font-size:11.5px;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\n}\n.voicebook .mini.danger{color:var(--hot-2);border-color:var(--hot-a35)}\n.voicebook .mini:disabled{opacity:.4}\n.num{\n  width:64px;padding:8px 10px;border-radius:10px;text-align:center;font-size:13px;\n  border:1px solid var(--line);background:rgba(0,0,0,.35);\n}\n/* 短文本输入（「对方是谁」）：和 .num 同一套外观，宽一点 */\n.txt{\n  flex:none;width:9em;padding:8px 10px;border-radius:10px;font-size:13px;\n  border:1px solid var(--line);background:rgba(0,0,0,.35);outline:none;\n  -webkit-appearance:none;appearance:none;\n}\n.txt::placeholder{color:var(--dim-2);opacity:1}\n.txt:focus{border-color:var(--hot-a55)}\n/* 下拉框：不写这一组的话，浏览器会用系统默认（黑字）铺在深色面板上，直接看不见。\n   option 也要显式给色 —— 部分安卓浏览器的下拉列表不继承 select 的样式。 */\nselect.txt,select{\n  color:var(--text);\n  background-color:rgba(0,0,0,.55);\n  color-scheme:dark;\n}\nselect option{\n  color:var(--text);\n  background-color:#241a26;\n}\nselect option:disabled{color:var(--dim-2)}\nselect:disabled{opacity:.55}\n/* 令牌框：按密码输入，右侧一个「显示」可以临时看明文（粘贴时确认有没有截断） */\n.txt-wrap{position:relative;width:100%}\n.txt-wrap .txt{padding-right:52px}\n.eye{\n  position:absolute;right:6px;top:50%;transform:translateY(-50%);\n  padding:5px 9px;border-radius:8px;font-size:11px;font-weight:600;\n  color:var(--dim);border:1px solid var(--line);background:rgba(0,0,0,.35);\n  letter-spacing:.04em;\n}\n.eye:active{transform:translateY(-50%) scale(.95)}\n.eye.on{color:var(--hot-2);border-color:var(--hot-a45)}\n/* 标签在上、选项一排在下的设置项（装置形态） */\n.field.col{flex-direction:column;align-items:stretch;gap:0}\n.field.col .chips{margin-top:10px}\ntextarea{\n  width:100%;min-height:96px;margin-top:10px;padding:11px 12px;border-radius:12px;\n  border:1px solid var(--line);background:rgba(0,0,0,.35);color:var(--text);\n  font-size:12.5px;line-height:1.6;font-family:var(--font);resize:vertical;\n}\n.hint{font-size:11px;color:var(--dim-2);line-height:1.7;margin-top:8px}\n\n/* ---------- 吐司 ---------- */\n#toast{position:absolute;left:50%;bottom:12%;transform:translateX(-50%);z-index:99;\n  display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none}\n.tst{\n  padding:9px 16px;border-radius:999px;font-size:12px;\n  background:rgba(24,14,25,.95);border:1px solid var(--line-2);\n  box-shadow:0 8px 30px rgba(0,0,0,.6);animation:tin .25s;max-width:82vw;text-align:center;\n}\n@keyframes tin{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n";
  var HTML = "<div id=\"shell\">\n\n  <header class=\"bar\">\n    <div class=\"brand\">\n      <span class=\"logo\" aria-hidden=\"true\"><svg viewBox=\"7 6 50 50\" xmlns=\"http://www.w3.org/2000/svg\"><defs><linearGradient id=\"lgPod\" x1=\"0\" y1=\"0\" x2=\".35\" y2=\"1\"><stop offset=\"0\" stop-color=\"#b25cb4\"/><stop offset=\".5\" stop-color=\"#8c3291\"/><stop offset=\"1\" stop-color=\"#5e1868\"/></linearGradient><linearGradient id=\"lgArm\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#9c43a1\"/><stop offset=\".6\" stop-color=\"#78247e\"/><stop offset=\"1\" stop-color=\"#561462\"/></linearGradient><linearGradient id=\"lgShade\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\".55\" stop-color=\"#2a0630\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#2a0630\" stop-opacity=\".45\"/></linearGradient><linearGradient id=\"lgGold\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ead9be\"/><stop offset=\".5\" stop-color=\"#cdb391\"/><stop offset=\"1\" stop-color=\"#9f8262\"/></linearGradient></defs><path d=\"M19.4 33 C13.6 35.6 9.6 41.6 12.6 47.4 C15.8 53.6 28 53.4 36.4 47.2 C40.4 44.2 43.2 40.8 44.6 37.6\" fill=\"none\" stroke=\"url(#lgArm)\" stroke-width=\"8.8\" stroke-linecap=\"round\"/><g transform=\"translate(24 31) rotate(-24)\"><path d=\"M0 -5 C6 -6.4 12 -8.6 19.5 -8.5 C27.5 -8.4 32 -4.6 32 0 C32 4.6 27.5 8.4 19.5 8.5 C12 8.6 6 6.4 0 5 Z\" fill=\"url(#lgPod)\"/><path d=\"M0 -5 C6 -6.4 12 -8.6 19.5 -8.5 C27.5 -8.4 32 -4.6 32 0 C32 4.6 27.5 8.4 19.5 8.5 C12 8.6 6 6.4 0 5 Z\" fill=\"url(#lgShade)\"/><path d=\"M-5.6 -4.9 Q-6.5 0 -5.6 4.9 L0.7 5.3 Q1.7 0 0.7 -5.3 Z\" fill=\"url(#lgGold)\"/><path d=\"M0.7 -5.3 Q1.7 0 0.7 5.3\" fill=\"none\" stroke=\"#6b5238\" stroke-opacity=\".45\" stroke-width=\".6\"/></g></svg></span>\n      <b>TOY<i>·</i>LINK</b>\n      <span class=\"ver\" id=\"brand-ver\"></span>\n    </div>\n    <div class=\"conn\" id=\"conn\"><span class=\"dot\" id=\"dot\"></span><span id=\"conn-txt\">待机</span></div>\n    <button class=\"bar-btn\" id=\"btn-size\" type=\"button\" aria-label=\"切换全屏/悬浮\">⤢</button>\n    <button class=\"bar-btn\" id=\"btn-close\" type=\"button\" aria-label=\"收起\">✕</button>\n  </header>\n\n  <!-- ============ 作用对象（常驻在面板最上方） ============\n       这一档决定的不是\"参数\"，而是整台机器谁说了算：\n       你操控 → 它是一台遥控台；TA 操控 → 它是一块只读仪表。 -->\n  <div class=\"tgtbar\" id=\"tgtbar\" data-t=\"char\">\n    <span class=\"tgt-ind\" aria-hidden=\"true\"></span>\n    <button class=\"tgt on\" id=\"tgt-char\" data-t=\"char\" type=\"button\">\n      <b>你拿着遥控器</b><i>装置在 TA 身上</i>\n    </button>\n    <button class=\"tgt\" id=\"tgt-user\" data-t=\"user\" type=\"button\">\n      <b>TA 拿着遥控器</b><i>装置在你身上</i>\n    </button>\n    <button class=\"tgt\" id=\"tgt-self\" data-t=\"self\" type=\"button\" title=\"遥控器和装置都在你这\">\n      <b>自己玩</b><i>装置遥控都在你</i>\n    </button>\n  </div>\n\n  <!-- ============ 设备页 ============ -->\n  <main class=\"stage\" id=\"v-device\">\n    <div class=\"lockbar\" id=\"lockbar\" hidden>\n      <b>遥控器在 TA 手里</b>\n      <span>档位由 TA 决定。下面的按钮只是\"催一下\"，TA 回复到了这里才会更新成现在的档位。</span>\n    </div>\n\n    <section class=\"hero\">\n      <div class=\"ring off\" id=\"ring\">\n        <svg viewBox=\"0 0 120 120\" aria-hidden=\"true\">\n          <defs>\n            <linearGradient id=\"gr\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n              <stop class=\"s1\" offset=\"0%\" stop-color=\"#d6bd96\"/>\n              <stop class=\"s2\" offset=\"55%\" stop-color=\"#c06cc2\"/>\n              <stop class=\"s3\" offset=\"100%\" stop-color=\"#e2b6df\"/>\n            </linearGradient>\n          </defs>\n          <circle class=\"trk\" cx=\"60\" cy=\"60\" r=\"52\"/>\n          <circle class=\"val2\" id=\"ring2\" cx=\"60\" cy=\"60\" r=\"43\"\n                  stroke-dasharray=\"0 999\"/>\n          <circle class=\"val\" id=\"ring1\" cx=\"60\" cy=\"60\" r=\"52\"\n                  stroke-dasharray=\"0 999\"/>\n        </svg>\n        <div class=\"readout\">\n          <div class=\"big\" id=\"big\">0<small>%</small></div>\n          <div class=\"sub\" id=\"sub\">8.4 Hz</div>\n          <div class=\"mode-tag\" id=\"mtag\">待机</div>\n        </div>\n      </div>\n    </section>\n\n    <div class=\"wave-wrap\">\n      <span class=\"wave-tag\">waveform</span>\n      <canvas id=\"wave\"></canvas>\n    </div>\n\n    <div class=\"phase-head\">\n      <span>累积 <b id=\"aro\">0</b>/100</span>\n      <span id=\"stage-name\">第 1 阶段 · 适应</span>\n      <span class=\"full-mark\" id=\"full-mark\" hidden>已满</span>\n    </div>\n    <div class=\"freeze\" id=\"freeze-tip\" hidden>AI 正在生成，剧情时间暂停 · 点这里立即继续</div>\n    <div class=\"phases\" id=\"phases\">\n      <div class=\"phase\"><i></i></div><div class=\"phase\"><i></i></div>\n      <div class=\"phase\"><i></i></div><div class=\"phase\"><i></i></div>\n      <div class=\"phase\"><i></i></div>\n    </div>\n\n    <!-- 装置在不在身上：左「贴上」、右「拿起」，并排两颗，选中的用琥珀色框出来。\n         贴上 = 刺激在走、阶段值累积；拿起 = 刺激停下、阶段值冻结。\n         （「临界」「冲刺」不在这儿 —— 它们是震动模式里的两个档，按阶段解锁。） -->\n    <div class=\"gate\">\n      <button type=\"button\" id=\"btn-put\">贴上</button>\n      <button type=\"button\" id=\"btn-take\">拿起</button>\n    </div>\n\n    <section class=\"panel\">\n      <h3>震动模式<span class=\"tag\" id=\"modes-tag\"></span></h3>\n      <div class=\"modes\" id=\"modes\"></div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>参数<span class=\"tag\" id=\"param-state\"></span></h3>\n      <label class=\"ctl\">\n        <div class=\"row\"><span>频率 FREQ</span><b id=\"fv\">8.4<em>Hz</em></b></div>\n        <input type=\"range\" id=\"freq\" min=\"1\" max=\"100\" value=\"42\">\n      </label>\n      <label class=\"ctl\">\n        <div class=\"row\"><span>强度 POWER</span><b id=\"pv\">62<em>%</em></b></div>\n        <input type=\"range\" id=\"pow\" min=\"1\" max=\"100\" value=\"62\">\n      </label>\n      <label class=\"ctl\">\n        <div class=\"row\"><span>限时 DURATION</span><b id=\"dv\">30<em>分</em></b></div>\n        <input type=\"range\" id=\"dur\" min=\"0\" max=\"90\" value=\"30\">\n      </label>\n      <div class=\"chips\" id=\"dur-chips\">\n        <button class=\"chip\" data-d=\"5\">5 分</button>\n        <button class=\"chip\" data-d=\"15\">15 分</button>\n        <button class=\"chip on\" data-d=\"30\">30 分</button>\n        <button class=\"chip\" data-d=\"60\">60 分</button>\n        <button class=\"chip\" data-d=\"0\">不限制</button>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>联动</h3>\n      <div class=\"chips\">\n        <button class=\"chip on\" id=\"c-auto\">自动反应</button>\n        <button class=\"chip on\" id=\"c-freeze\" title=\"打开后，AI 出字期间累积值暂停推进，等它写完再接着走\">等回复再走</button>\n        <button class=\"chip on\" id=\"c-haptap\" title=\"切模式、启停、切换作用对象时震一下\">按键震动</button>\n        <button class=\"chip\" id=\"c-hapfol\" title=\"装置运行时按实时频率一直震。手机马达分辨不出频率，实际是断续的哒哒声，且费电发热\">跟随震动</button>\n        <button class=\"chip\" id=\"c-audio\">声波模拟</button>\n      </div>\n      <div class=\"hint\" id=\"auto-hint\"></div>\n      <div class=\"hint\" id=\"hap-hint\"></div>\n    </section>\n  </main>\n\n  <!-- ============ 反应页 ============\n       这一页是纯展示：文字 + 语音播放。不对 TA 说话（要说就在酒馆的输入框里说），\n       所以没有输入栏 —— 少了输入栏，整页的高度都留给反应本身。 -->\n  <main class=\"stage\" id=\"v-chat\" hidden>\n    <!-- 语音重写栏：不对 TA 说话，只用来指挥\"这一句台词该怎么念\"。\n         每一条反应下面都有「✎ 重写这句」，点它会把目标挂到这里。 -->\n    <form class=\"relay\" id=\"relay-form\" autocomplete=\"off\">\n      <div class=\"rtarget\" id=\"relay-target\">没选目标 · 点下面任意一条的「✎ 重写这句」</div>\n      <div class=\"rrow\">\n        <input id=\"relay-input\" type=\"text\" placeholder=\"你想要 TA 怎么喘…（例如：语速更慢一点、话再多一点）\" enterkeyhint=\"send\" disabled>\n        <button type=\"submit\" id=\"relay-go\" disabled>重新生成</button>\n      </div>\n      <div class=\"rrow\" style=\"margin-top:6px\">\n        <button type=\"button\" class=\"rmini\" id=\"relay-revert\" hidden>还原这句话</button>\n        <button type=\"button\" class=\"rmini\" id=\"relay-cancel\" hidden>取消选中</button>\n      </div>\n    </form>\n    <div class=\"feed\" id=\"feed\">\n      <div class=\"feed-empty\">\n        还没有声音<br>装置跑起来之后，TA 会发出什么声音会显示在这里</div>\n    </div>\n  </main>\n\n  <!-- ============ 语音设置页 ============\n       参考本地那个独立试音台（工具-TTS试音台.html）重做进面板：\n       连接、音色、合成参数、试听、缓存，都收在这一页。\n       设置页只留开关（是否出声），调试性质的东西不放那儿。 -->\n  <main class=\"stage\" id=\"v-voice\" hidden>\n    <section class=\"panel\">\n      <h3>语音状态<span class=\"tag\" id=\"vs-tag\"></span></h3>\n      <div class=\"hint\" id=\"vs-hint\">—</div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"s-voice\">关</button>\n        <button class=\"chip\" id=\"c-voice-test\">试听一句</button>\n      </div>\n      <div class=\"field\" style=\"border-top:1px solid var(--line);margin-top:12px\">\n        <div class=\"lb\"><b>自动播放</b><small>面板拿到新反应时直接念出来。关掉则每条下面仍可手动点播放。</small></div>\n        <div class=\"sw on danger\" id=\"s-voiceauto\"><i></i></div>\n      </div>\n      <div class=\"danger-note\" id=\"vs-auto-warn\" hidden>\n        <b>自动播放开着</b> —— 面板每出一条新反应都会直接出声，不管你点没点。\n        在外面、戴耳机时忘了它，就是社死现场。不想冒这个险就关掉，需要时手动点「语音播放」。\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>语音音量</b><small>相对装置音的响度。</small></div>\n        <input class=\"num\" id=\"s-voicevol\" type=\"number\" min=\"0\" max=\"100\" step=\"5\">\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>启动时预热</b><small>装置启动后把每档固定的几句先合成好，用起来不卡。<br>注意：这会真的发 5 次合成请求，按你所用平台正常计费 —— 想省额度就别开。</small></div>\n        <div class=\"sw\" id=\"s-voicewarm\"><i></i></div>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>连接</h3>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>连到哪儿</b><small id=\"s-transport-note\"></small></div>\n        <!-- 两个互不相干的模式，各自记着自己的地址：\n             官网直连 = 打 Fish 官方端点；中转 = 打你自己填的中转地址。\n             切换时另一边的地址会被留着，来回切不用重填。 -->\n        <div class=\"gate\" id=\"s-transport\" style=\"margin-top:8px\">\n          <button type=\"button\" id=\"s-tp-official\">官网 api</button>\n          <button type=\"button\" id=\"s-tp-relay\">中转 api</button>\n        </div>\n      </div>\n      <!-- 平台与地址是一回事的两面：平台决定官方地址、音色字段名与请求协议，\n           所以放在同一处双向联动 —— 选平台自动填它的官方地址，手改地址则认回平台。 -->\n      <div class=\"field col\">\n        <div class=\"lb\"><b>合成平台</b><small id=\"s-plat-note\"></small></div>\n        <div class=\"row2\">\n          <select class=\"txt\" id=\"s-platform\" style=\"flex:1;min-width:0\">\n            <option value=\"fish\">Fish Audio（主推）</option>\n            <option value=\"minimax\">MiniMax 语音</option>\n            <option value=\"openai\">OpenAI 兼容</option>\n            <option value=\"custom\">其他 / 自定义协议</option>\n          </select>\n          <button class=\"mini\" id=\"c-open-lib\">音色库</button>\n        </div>\n      </div>\n      <div class=\"field col\">\n        <div class=\"lb\"><b id=\"s-target-lb\">官方地址</b><small id=\"s-target-note\"></small></div>\n        <!-- 地址做成可编辑下拉：三个官方端点填在 datalist 里直接选，也能手打\n             （MiniMax 国内站那种没进列表的只能手填）。选项由脚本按平台生成，见 fillTargetOptions。 -->\n        <input class=\"txt\" id=\"s-tts-target\" type=\"text\" list=\"s-target-list\"\n               placeholder=\"https://api.fish.audio/v1/tts\" autocomplete=\"off\" spellcheck=\"false\" enterkeyhint=\"done\" style=\"width:100%\">\n        <datalist id=\"s-target-list\"></datalist>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b id=\"s-forward-lb\">请求怎么发</b><small id=\"s-forward-note\"></small></div>\n        <button class=\"mini\" id=\"s-tp-forward\">浏览器直打</button>\n      </div>\n      <div id=\"s-direct-box\">\n        <div class=\"field col\">\n          <div class=\"lb\"><b id=\"s-key-lb\">令牌</b><small id=\"s-key-note\"></small></div>\n          <div class=\"txt-wrap\">\n            <input class=\"txt\" id=\"s-tts-key\" type=\"password\" placeholder=\"API Key\" autocomplete=\"new-password\" spellcheck=\"false\" enterkeyhint=\"done\" style=\"width:100%\">\n            <button type=\"button\" class=\"eye\" id=\"c-eye-key\" aria-label=\"显示或隐藏令牌\">显示</button>\n          </div>\n        </div>\n        <div class=\"field\">\n          <div class=\"lb\"><b>鉴权方式</b><small id=\"s-auth-note\">官方与多数中转都走标准 Bearer，不用改。</small></div>\n          <button class=\"mini\" id=\"s-tts-authstyle\">Bearer</button>\n        </div>\n      </div>\n\n      <details class=\"adv\">\n        <summary>高级：请求头与字段名（中转不按标准协议时改这里）</summary>\n        <div class=\"inner\">\n          <div class=\"hint\" style=\"margin-top:0;margin-bottom:10px\">\n            不同中转对\"模型放哪个头、音色字段叫什么\"的要求不一样。遇到说不清原因的\n            400 / 422，先来这里对一遍 —— 这几项保持默认就是标准协议。\n          </div>\n          <div id=\"s-adv-fish\">\n            <div class=\"field col\">\n              <div class=\"lb\"><b>额外请求头</b><small>JSON，例如 <code>{\"X-Token\":\"xxx\"}</code>。中转要求带自定义头时填这儿。</small></div>\n              <input class=\"txt\" id=\"s-tts-extra\" type=\"text\" placeholder='留空即可' autocomplete=\"off\" spellcheck=\"false\" style=\"width:100%\">\n            </div>\n            <div class=\"field\">\n              <div class=\"lb\"><b>模型头名</b><small>标准是 <code>model</code>。</small></div>\n              <input class=\"txt\" id=\"s-tts-modelhdr\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\">\n            </div>\n            <div class=\"field\">\n              <div class=\"lb\"><b>音色字段名</b><small>标准是 <code>reference_id</code>。</small></div>\n              <input class=\"txt\" id=\"s-tts-reffield\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\">\n            </div>\n            <div class=\"field\">\n              <div class=\"lb\"><b>延迟档（latency）</b><small>low 最快、normal 质量最好但慢。</small></div>\n              <button class=\"mini\" id=\"s-tts-latency\">low</button>\n            </div>\n            <div class=\"field\">\n              <div class=\"lb\"><b>不发 model 头</b><small>中转不认这个头时打开。</small></div>\n              <div class=\"sw\" id=\"s-tts-nomodel\"><i></i></div>\n            </div>\n          </div>\n\n          <div id=\"s-adv-openai\" style=\"display:none\">\n            <div class=\"field col\">\n              <div class=\"lb\"><b>额外请求头</b><small>JSON。中转要求带自定义头时填这儿。</small></div>\n              <input class=\"txt\" id=\"s-tts-extra-oai\" type=\"text\" placeholder='留空即可' autocomplete=\"off\" spellcheck=\"false\" style=\"width:100%\">\n            </div>\n            <div class=\"field\">\n              <div class=\"lb\"><b>加语气指令（instructions）</b><small>只有较新的 OpenAI 语音模型吃这个字段。打开后会让它按\"气声、喘息\"来念 —— 成本相同，但对这种台词更贴。</small></div>\n              <div class=\"sw\" id=\"s-tts-langboost\"><i></i></div>\n            </div>\n            <div class=\"hint\">\n              模型名与语速在上面「音色与合成参数」那一栏里。这套协议没有 latency / reference_id 这些字段，\n              所以切到 OpenAI 时那几项会自动收起来。\n            </div>\n          </div>\n        </div>\n      </details>\n\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-voice-ping\">检查通道</button>\n        <button class=\"chip save\" id=\"c-save-conn\">保存</button>\n      </div>\n      <div class=\"hint\" id=\"vs-ping-hint\">\n        <b>检查通道</b>：只发空文本 / 健康接口，零成本 —— 答的是\"网通不通\"。\n        它<b>答不了\"能不能出声\"</b>（账号额度、模型、音色是否可用）：那要真合成一次才知道，点试听即可。\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>运行日志<span class=\"tag\" id=\"vs-log-tag\"></span></h3>\n      <div class=\"hint\" style=\"margin-top:0;margin-bottom:8px\">\n        面板里看不到 console，这一栏就是排错入口：哪一句发出去了、打到哪、几毫秒、多大、缓存中没中。\n      </div>\n      <div id=\"vs-log\" class=\"vlog\"><div class=\"lgdim\">（还没有记录）</div></div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-log-copy\">复制日志</button>\n        <button class=\"chip\" id=\"c-log-clear\">清空日志</button>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>音色与合成参数</h3>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>你拿着遥控器时的音色</b><small id=\"s-voice1-note\">被作用的是 TA，出的是呻吟。</small></div>\n        <div class=\"row2\">\n          <input class=\"txt\" id=\"s-voice-1-input\" type=\"text\" placeholder=\"音色 ID\" autocomplete=\"off\" spellcheck=\"false\" enterkeyhint=\"done\" style=\"flex:1;min-width:0\">\n          <button class=\"mini\" id=\"c-lib-1\">从这里找</button>\n        </div>\n        <!-- 音色簿：常驻显示。存过就列在下拉框里，没存过也能拿当前这套存一条。\n             以前这块是\"保存过才出现\"，结果功能藏在「保存音色与参数」按钮后面，\n             找不到入口的人根本不知道有它。 -->\n        <div class=\"voicebook\" id=\"vb-1\">\n          <div class=\"vbrow\"><select class=\"txt\" id=\"vb-1-sel\"></select></div>\n          <div class=\"vbrow\">\n            <button class=\"mini\" id=\"vb-1-new\">存为新的</button>\n            <button class=\"mini\" id=\"vb-1-ren\">改名</button>\n            <button class=\"mini danger\" id=\"vb-1-del\">删除</button>\n          </div>\n        </div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>TA 拿着遥控器时用另一个音色</b><small>开着才能填下面那个。同一个角色一般不需要，除非你想让\"操控的语气\"听起来是另一个人。</small></div>\n        <div class=\"sw\" id=\"s-voice-two\"><i></i></div>\n      </div>\n      <div class=\"field col\" id=\"s-voice-2-box\" style=\"display:none\">\n        <div class=\"lb\"><b>TA 拿着遥控器时的音色</b><small>被作用的是你，TA 出的是调教对白。</small></div>\n        <div class=\"row2\">\n          <input class=\"txt\" id=\"s-voice-2-input\" type=\"text\" placeholder=\"音色 ID\" autocomplete=\"off\" spellcheck=\"false\" enterkeyhint=\"done\" style=\"flex:1;min-width:0\">\n          <button class=\"mini\" id=\"c-lib-2\">从这里找</button>\n        </div>\n        <div class=\"voicebook\" id=\"vb-2\">\n          <div class=\"vbrow\"><select class=\"txt\" id=\"vb-2-sel\"></select></div>\n          <div class=\"vbrow\">\n            <button class=\"mini\" id=\"vb-2-new\">存为新的</button>\n            <button class=\"mini\" id=\"vb-2-ren\">改名</button>\n            <button class=\"mini danger\" id=\"vb-2-del\">删除</button>\n          </div>\n        </div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>模型</b><small id=\"s-model-hint\">按中转支持的模型名填。</small></div>\n        <!-- 可编辑下拉：候选由脚本按当前平台填（见 fillModelOptions），\n             也能直接手打 —— 官方没有\"列出 TTS 型号\"的接口，那份清单是照文档写死的。 -->\n        <div class=\"txt-wrap\">\n          <input class=\"txt\" id=\"s-tts-model\" type=\"text\" list=\"s-model-list\"\n                 autocomplete=\"off\" spellcheck=\"false\" enterkeyhint=\"done\">\n          <button type=\"button\" class=\"eye\" id=\"c-model-refresh\" aria-label=\"用当前平台的推荐型号\">推荐</button>\n        </div>\n        <datalist id=\"s-model-list\"></datalist>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>格式</b><small>mp3 最通用；wav 音质好、体积大；opus 体积最小。</small></div>\n        <button class=\"mini\" id=\"s-tts-format\">mp3</button>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>语速</b><small>0.7-1.2 比较自然。太快会把气声吞掉。</small></div>\n        <input class=\"num\" id=\"s-tts-speed\" type=\"number\" min=\"0.5\" max=\"1.5\" step=\"0.05\">\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>台词来源</b><small id=\"s-voiceai-note\"></small></div>\n        <button class=\"mini\" id=\"s-voiceai\">正文对白</button>\n      </div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-save-voice\">保存音色与参数</button>\n      </div>\n      <div class=\"hint\">\n        改动本来就是即时存下的，这个按钮是让你确认一次：万一手机上输入法开着、\n        字还没落进输入框，点它会把当前界面上的值再读一遍并写入。\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>缓存</h3>\n      <div class=\"chips\" style=\"margin-top:0\">\n        <button class=\"chip\" id=\"c-voice-warm\">预热音集</button>\n        <button class=\"chip\" id=\"c-voice-clear\">清空语音缓存</button>\n      </div>\n      <div class=\"hint\">\n        <b>预热音集</b>：按当前作用对象抓 5 句现成台词先合成好，之后播这些不再联网、不会卡。\n        代价是 5 次真实合成请求，按你所用平台正常计费 —— 不是必须做的事。\n        <b>清空语音缓存</b>：删掉本地全部音频 —— 等同于「合成记录」那栏的清空，两者是同一份数据。\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>试听<span class=\"tag\" id=\"vs-text-tag\"></span></h3>\n      <div class=\"hint\" style=\"margin-top:0;margin-bottom:10px\">\n        从<b>台词库</b>里挑一句来试音色 —— 换音色、改语速之后用它对比最省事，\n        不用等装置跑起来。库里的句子都自动带情绪标记，念出来就是它本来的样子。\n      </div>\n      <div class=\"hint act\" id=\"vs-try-hint\">试听与预热的反馈显示在这里。</div>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>台词分类</b></div>\n        <select class=\"txt\" id=\"s-voice-kind\" style=\"width:100%\"></select>\n      </div>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>档位</b><small id=\"s-voice-stage-note\"></small></div>\n        <select class=\"txt\" id=\"s-voice-stage\" style=\"width:100%\"></select>\n      </div>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>句子</b></div>\n        <select class=\"txt\" id=\"s-voice-line\" style=\"width:100%\"></select>\n      </div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-preview-line\">试听这一句</button>\n        <button class=\"chip\" id=\"c-preview-next\">换一句</button>\n      </div>\n      <div class=\"hint\" id=\"vs-preview-note\">—</div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>自定义试听<span class=\"tag\" id=\"vs-custom-tag\"></span></h3>\n      <div class=\"hint\" style=\"margin-top:0;margin-bottom:10px\">\n        自己写一段送去合成，用来试音色、试语速最直接。<b>可以写多行</b>，每行开头放一个\n        <b>语气符号</b>（方括号），那一行才会按那个语气念出来；哪行忘写会自动补一个。\n      </div>\n      <textarea id=\"s-custom-text\" spellcheck=\"false\" style=\"min-height:86px;margin-top:0\"\n        placeholder=\"[soft tone][whispering] 你怎么还没睡呀？\n[inhale] 我只是……有点想你了。\n[short pause][chuckling] 好啦，别笑我。\">[soft tone][whispering] 你怎么还没睡呀？\n[inhale] 我只是……有点想你了。\n[short pause][chuckling] 好啦，别笑我。</textarea>\n      <div class=\"row2\" style=\"margin-top:9px\">\n        <button class=\"chip\" id=\"c-custom-say\">试听这段</button>\n        <button class=\"chip\" id=\"c-custom-clear\">清空</button>\n        <button class=\"chip\" id=\"c-custom-len\">0 字 · 0 行</button>\n      </div>\n\n      <div class=\"tagsec\">\n        <div class=\"taghead\">音效<span>喘 / 哭 / 笑 / 叹，直接放句首</span></div>\n        <div class=\"tagrow\" id=\"tag-fx\"></div>\n        <div class=\"taghead\">情绪</div>\n        <div class=\"tagrow\" id=\"tag-emo\"></div>\n        <div class=\"taghead\">语调</div>\n        <div class=\"tagrow\" id=\"tag-tone\"></div>\n        <div class=\"taghead\">中文描述<span>官方允许括号里写自然语言，不限于固定表</span></div>\n        <div class=\"tagrow\" id=\"tag-cn\"></div>\n        <div class=\"taghead\">停顿</div>\n        <div class=\"tagrow\" id=\"tag-pause\"></div>\n      </div>\n      <div class=\"hint\">点一下<b>复制</b>该符号（会弹提示，粘到文本框里用）。一句最多叠 3 个，放在句子最前面最有效。</div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>合成记录<span class=\"tag\" id=\"vs-list-count\"></span></h3>\n      <div class=\"hint\" style=\"margin-top:0;margin-bottom:8px\">\n        每合成一句都会留在这里（含装置自动说话的），可以单条播放、单条下载，也能打包带走。\n        分页显示，一页 6 条。\n      </div>\n      <div class=\"recbar\">\n        <span id=\"vs-page-info\">共 0 条</span>\n        <button class=\"rmini\" id=\"c-page-prev\">上一页</button>\n        <button class=\"rmini\" id=\"c-page-next\">下一页</button>\n      </div>\n      <div class=\"reclist\" id=\"vs-list\"><div class=\"lgdim\" style=\"padding:10px 0\">（还没有合成记录）</div></div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-audio-zip\">打包下载</button>\n        <button class=\"chip\" id=\"c-audio-clear\">清空记录</button>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>振动音<span class=\"tag\">未测试 · 慎用</span></h3>\n      <div class=\"hint\" style=\"margin-top:0\">\n        <b>这一档还没在真机上听过</b>，参数只验证到「代码能跑、数值合法」。它是纯 Web Audio\n        实时合成，不联网、不花钱，频率与强度直接跟着装置走。\n        <br><br>\n        做法是真实低频垫底（听不出来，但会让机身轻震）+ 谐波放在手机能出声的频段，\n        靠听觉补出低沉嗡鸣；吸吮式会自动压低低通，听感更闷更贴。\n        在语音开关里选中它才生效。\n      </div>\n    </section>\n  </main>\n\n  <!-- ============ 设置页 ============ -->\n  <main class=\"stage\" id=\"v-config\" hidden>\n    <section class=\"panel\">\n      <h3>与角色的联动</h3>\n      <div class=\"field\">\n        <div class=\"lb\"><b>回复出现在哪里</b><small>酒馆聊天：状态以系统提示注入，然后触发发言，回复照常进聊天记录。<br>面板内生成：回复流式显示在面板里，同时落库。</small></div>\n        <button class=\"mini\" id=\"s-drive\">酒馆聊天</button>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>对方是谁</b><small>卡里没有固定角色、或者有好几个人时填名字：装置戴在谁身上、遥控器在谁手里都认这个名字。留空＝用角色卡名。</small></div>\n        <input class=\"txt\" id=\"s-holder\" type=\"text\" maxlength=\"24\" autocomplete=\"off\" spellcheck=\"false\" enterkeyhint=\"done\">\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>身体反应</b><small id=\"s-body-note\">女性：没有不应期，一波刚落下一波能接上，顶点之后更敏感。<br>男性：顶点是一次性释放，之后有不应期，继续刺激只会变成酸胀难受。</small></div>\n        <button class=\"mini\" id=\"s-body\">女性</button>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>露骨描写</b><small id=\"s-scale-note\"></small></div>\n        <div class=\"sw on\" id=\"s-explicit\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>TA 会乖乖停手</b><small id=\"s-beg-note\">开：遥控器在 TA 手里时，你开口请求停下，TA 这一轮就答应。<br>关：TA 按自己的性格决定听不听，往往要请求两三次才松口——但求够了一定会松口。</small></div>\n        <div class=\"sw on\" id=\"s-beg\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>发送方式</b><small id=\"s-send-note\">generate：走插件自己的请求，不会撞上酒馆「生成中无法运行 /trigger」的限制。<br>slash：走酒馆原生流程。</small></div>\n        <button class=\"mini\" id=\"s-send\">generate</button>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>自动反应</b><small id=\"s-auto-note\">当前：开。装置状态变化会自动触发 AI 生成。</small></div>\n        <div class=\"sw on\" id=\"s-auto\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>生成期间冻结剧情时间</b><small>默认打开。AI 出字期间累积值暂停推进，生成一结束立刻接着走，免得「换阶段」和「回复」撞在同一刻。波形照常跳动。</small></div>\n        <div class=\"sw on\" id=\"s-freeze\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>反应冷却</b><small>两次生成之间的最小间隔秒数。冷却期间的操作不会被丢掉，会攒起来在冷却结束时用最新状态触发一次。</small></div>\n        <input class=\"num\" id=\"s-cd\" type=\"number\" min=\"5\" max=\"600\" value=\"12\">\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>阶段跃迁必触发</b><small>进入新阶段与临界爆发不受冷却限制。</small></div>\n        <div class=\"sw on\" id=\"s-stage\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>每次生成都告诉 AI 装置状态</b><small>开：点启动、切模式、催反应 —— 只要是脚本发起的那次生成，都会先把当前状态（戴在谁身上、什么模式、频率强度、第几阶段）放在提示词最前，面板和正文才对得上。<br>关：AI 完全不知道装置在跑，正文回到普通的角色扮演。</small></div>\n        <div class=\"sw on\" id=\"s-inject\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>让 AI 一直戴着</b><small>开：这张卡<b>第一次按下「启动」</b>时才装上去 —— 只翻牌看看、没动装置，卡上不会留下任何东西；装上之后，每次启动脚本都跟着你的设置更新它。这条管的是<b>你自己在酒馆输入框里打字</b>时 AI 知不知道（上面那条只管脚本发起的生成）。<br>关：脚本不再碰它。已经挂上的会留着继续生效，彻底卸载用下面那两颗按钮。</small></div>\n        <div class=\"sw on\" id=\"s-wb\"><i></i></div>\n      </div>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>不玩了？</b><small>AI 认不认识这台装置，全看这张角色卡上有没有挂那本「TOY·LINK 装置设定」。<br>拔出来＝解绑并删除；戴上＝重新写好再挂回去。</small></div>\n        <div class=\"chips\" style=\"margin-top:0\">\n          <button class=\"chip\" id=\"s-uninstall\" type=\"button\">拔出来擦干净</button>\n          <button class=\"chip\" id=\"s-wear\" type=\"button\">重新戴上装置</button>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>装置</h3>\n      <div class=\"field col\">\n        <div class=\"lb\"><b>装置形态</b><small id=\"s-dev-note\"></small></div>\n        <div class=\"chips\" id=\"s-dev\">\n          <button class=\"chip on\" data-dev=\"patch\" type=\"button\">贴式</button>\n          <button class=\"chip\" data-dev=\"insert\" type=\"button\">内置</button>\n          <button class=\"chip\" data-dev=\"suck\" type=\"button\">吸吮</button>\n          <button class=\"chip\" data-dev=\"plug\" type=\"button\">后庭</button>\n          <button class=\"chip\" data-dev=\"clamp\" type=\"button\">乳夹</button>\n          <button class=\"chip\" data-dev=\"ring\" type=\"button\">震动环</button>\n        </div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>强度手感倍率</b><small>影响累积速度与临界到来的快慢。</small></div>\n        <input class=\"num\" id=\"s-gain\" type=\"number\" min=\"10\" max=\"400\" value=\"100\" step=\"10\">\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>到达临界后归零</b><small>阶段值满了之后玩家按「临界」时的落点。<br>打开：回到起点重新爬；关闭：停在高原上继续输出。<br>无论哪种，满了都不会自己轮回 —— 往哪走由玩家按。</small></div>\n        <div class=\"sw on\" id=\"s-reset\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>冲刺后累积减速</b><small>冲刺做完了，阶段值从头来，而且之后要更久才爬得回来。这里是那次减速的倍数。<br><code>0.35</code> = 约三倍时间；填 <code>1</code> 就等于不减速。装置重开或换目标时恢复成 1。</small></div>\n        <input class=\"num\" id=\"s-dashrate\" type=\"number\" min=\"0.1\" max=\"1\" step=\"0.05\" value=\"0.35\">\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>切换模式自动推荐频率</b><small>每种模式有自己合适的工作频段。</small></div>\n        <div class=\"sw on\" id=\"s-recfreq\"><i></i></div>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>面板</h3>\n      <div class=\"field\">\n        <div class=\"lb\"><b>全屏</b><small>手机上默认铺满屏幕；关掉就缩成一个小窗，顶栏可以拖着走。顶栏右上角的 ⤢ 是同一个开关——手机状态栏挡住它时就在这里切。</small></div>\n        <div class=\"sw\" id=\"s-fit\"><i></i></div>\n      </div>\n    </section>\n\n    <section class=\"panel\" id=\"s-ball-sec\" hidden>\n      <h3>悬浮球</h3>\n      <div class=\"field\">\n        <div class=\"lb\"><b>大小</b><small>只存在这台设备上，换聊天不变。</small></div>\n        <div class=\"chips\" id=\"s-ball-size\" style=\"margin-top:0\">\n          <button class=\"chip\" data-s=\"44\">小</button>\n          <button class=\"chip on\" data-s=\"58\">中</button>\n          <button class=\"chip\" data-s=\"72\">大</button>\n        </div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>底盘透明度</b><small>只调装置后面那块奶白圆盘，装置本体永远实心。盘透了就不挡字。</small></div>\n        <div class=\"chips\" id=\"s-ball-fade\" style=\"margin-top:0\">\n          <button class=\"chip\" data-f=\"1\">实心</button>\n          <button class=\"chip on\" data-f=\"0.45\">半透</button>\n          <button class=\"chip\" data-f=\"0\">透明</button>\n        </div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>隐藏悬浮球</b><small id=\"s-ball-hide-note\">只用脚本按钮「TOY·LINK 控制器」开面板。按钮在酒馆的快速回复栏里（需开着 QR 栏）；装了 QR 整合插件的，在它的火箭菜单里。</small></div>\n        <div class=\"sw\" id=\"s-ball-hide\"><i></i></div>\n      </div>\n      <div class=\"field\">\n        <div class=\"lb\"><b>贴边半藏（手机）</b><small>球靠着屏幕边几秒没人碰，就半藏进边里变半透明，不挡字。点它、或装置跑起来会出来。电脑上不贴。</small></div>\n        <div class=\"sw on\" id=\"s-ball-tuck\"><i></i></div>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>语音<span class=\"tag\" id=\"voice-tag\"></span></h3>\n      <div class=\"hint\" id=\"voice-hint\" style=\"margin-top:0\">语音目前是关的。</div>\n      <div class=\"danger-note\" id=\"c-voice-auto-warn\" hidden></div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-goto-voice\">打开语音设置 →</button>\n        <button class=\"chip\" id=\"c-voiceauto-quick\">自动播放 · 开</button>\n      </div>\n      <div class=\"hint\">\n        右边那个按钮就是自动播放开关 —— 点亮（脉冲）时说明它开着，新反应会直接出声。\n        <br>开关、音色、合成地址、试听、缓存全在<b>语音设置</b>页里。要出声只需两样：<b>合成地址</b>与<b>令牌</b>。不需要命令行。\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>状态快照（角色能看到的内容）</h3>\n      <textarea id=\"state-box\" readonly></textarea>\n      <div class=\"hint\">\n        这份文本写入聊天变量 <code>toy_state</code>，世界书条目用 <code>{{getvar::toy_state}}</code> 读取。\n      </div>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-sync\">立即同步变量</button>\n        <button class=\"chip\" id=\"c-copy\">复制快照</button>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h3>维护</h3>\n      <div class=\"chips\">\n        <button class=\"chip\" id=\"c-wipe\">清空反应记录</button>\n        <button class=\"chip\" id=\"c-reset\">复位装置</button>\n      </div>\n      <div class=\"hint\" id=\"env-hint\"></div>\n      <div class=\"hint\" id=\"ver-hint\"></div>\n    </section>\n  </main>\n\n  <!-- ============ 请求停止（常驻，遥控器在 TA 手里时才出现） ============\n       它是这一档里玩家唯一还能做的事，所以不能放在会滚动的区域里 ——\n       一滚到参数区就够不着了，「求 TA 放人」也就成了摆设。 -->\n  <div class=\"begbar\" id=\"begbar\" hidden>\n    <button class=\"beg\" id=\"beg-stop\" type=\"button\">\n      <b>请求 TA 停下</b>\n      <i>TA 会松口的</i>\n    </button>\n  </div>\n\n  <!-- ============ 电源区 ============ -->\n  <!-- 两颗各占一半。右边那颗只催一条回复，不动装置状态 ——\n       以前这里是「冲击一次」，同样是生成，却顺手把阶段值 +26，\n       想让 TA 说句话都得先付出状态代价，用起来别扭。 -->\n  <!-- 先打一句话再催反应：文字会作为你说的话进聊天，跟装置状态一起交给 AI。\n       留空点「立即反应一次」就还是老行为 —— 纯粹催一下，不多发任何消息。 -->\n  <div class=\"nowline\">\n    <input id=\"now-text\" type=\"text\" maxlength=\"120\" autocomplete=\"off\"\n           placeholder=\"（可选）先说一句，再催 TA 反应\">\n  </div>\n\n  <div class=\"powerbar\">\n    <button class=\"power\" id=\"power\">启 动</button>\n    <button class=\"ghost act\" id=\"btn-now\" title=\"立刻让 TA 反应一次（不改变装置状态）\">立即反应一次</button>\n  </div>\n\n  <nav class=\"dock\">\n    <button class=\"tab on\" data-go=\"device\"><b>◈</b>装置</button>\n    <button class=\"tab\" data-go=\"chat\"><b>❖</b>TA 的声音</button>\n    <button class=\"tab\" data-go=\"voice\"><b>♪</b>语音</button>\n    <button class=\"tab\" data-go=\"config\"><b>⚙</b>设置</button>\n    <button class=\"tab\" id=\"tab-hide\" type=\"button\" aria-label=\"收起面板\"><b>⌄</b>收起</button>\n  </nav>\n\n  <div id=\"toast\"></div>\n</div>";

  /* ==================== 建面板 ==================== */
  var host = DOC.createElement("div");
