      if (!sh || !sh.classList.contains("fit")) return;
      var p = e.composedPath ? e.composedPath() : [];
      for (var i = 0; i < p.length; i++) { if (p[i] && p[i].classList && p[i].classList.contains("bar")) { swipeY = t.clientY; return; } }
    }, { passive: true });
    root.addEventListener("touchend", function (e) {
      var t = e.changedTouches && e.changedTouches[0];
