    root.addEventListener("touchcancel", function () { swipeY = NaN; }, { passive: true });
  } catch (e) { /* noop */ }
  /* ---------- 生存模式：注册必须在风险代码之前 ----------
   * 事故复盘：一个函数名拼错让 boot 半途抛错，而面板已经铺满整个视口。
   * 手机上用户被一块关不掉、也点不到酒馆菜单的面板锁住，连脚本库都进不去 ——
   * 恢复的门被自己堵死了。
   * 注册位置很关键：以前这个定时器写在 apply() 后面，而抛错就在 apply() 之前，
   * 所以它同样没注册上，等于没做。现在放在挂载段末尾（早于所有可能出错的地方）。
   * 判据是 __toylink_ready —— 它只在真的跑到启动最后一行时才被打上。
   * 2.5 秒后若没这个标记，说明启动没跑完：自动收起面板、把悬浮球留下，
