  setTimeout(function () {
    var ok = false;
    try { ok = !!WIN.__toylink_ready; } catch (e) { ok = false; }
    if (ok) return;   // 启动正常，什么都不做
    try {
      console.error("[TOY·LINK] 启动没有完成，面板已自动收起、悬浮球已放出，免得挡住界面。"
        + "请把控制台里 TOY·LINK 相关的报错发出来。");
      collapse();          // host 不接收事件之后，酒馆界面立刻可以操作
      tkPref.hidden = false;
      tkVisible(true);     // 球留着：用户可以点它重开面板，自己看看到底怎么了
    } catch (e) { /* noop */ }
  }, 2500);

