    }
  };

  /* =========================================================
   * 4b. 语音与振动音（VOC）
   *
   * 一条音频总线管三件事：TTS 语音、振动音、上面那个正弦声波模拟（AUD 原样保留）。
   *
   * 三条链路：
   *   ① TTS 语音  —— 心声/台词的实音。走本机转发拿音频（浏览器直连中转会被跨域拦，实测确认）
   *   ② 振动音    —— 纯 Web Audio 实时合成，频率与强度直接由装置参数驱动，零网络零费用
   *
   * 振动音为什么不用 TTS：频率一变声音必须立刻跟着变，TTS 是固定片段，来不及。
   * 手机小扬声器放不出 100Hz 以下的低频，所以基频×3 取谐波、再垫一层真实低频，
   * 靠大脑的音高知觉补出"低沉嗡鸣"。参数依据见 工具-TTS试音台.html。
   * 吸吮式不是震（上游 S.dev='suck'）：那档声音更闷、更贴，所以低通压低、谐波减弱。
   * ======================================================= */
  var VOC = (function () {
    var ctx = null, bus = null, ana = null, anaBuf = null;
    var bzOn = false, bzLast = 0, bzNodes = null;
    var cache = {}, cacheDb = null, dbTried = false;
    var seq = 0, cur = null, curUrl = '', curSrc = null;

    function AC() { return WIN.AudioContext || WIN.webkitAudioContext; }
    function isSuck() { return String(S.dev || '').indexOf('suck') === 0; }

    function ensure() {
      if (ctx) { if (ctx.state === 'suspended') { try { ctx.resume(); } catch (e) { /* noop */ } } return true; }
      var C = AC();
      if (!C) return false;
      try {
        ctx = new C();
        bus = ctx.createGain();
        bus.gain.value = 0.9;
        ana = ctx.createAnalyser();
        ana.fftSize = 1024;
        ana.smoothingTimeConstant = 0.78;
        anaBuf = new Uint8Array(ana.fftSize);
        bus.connect(ana); ana.connect(ctx.destination);
        return true;
      } catch (e) { ctx = null; return false; }
    }

    /* ---- 振动音 ---- */
    function makeNoise() {
      var len = Math.max(1, Math.floor(ctx.sampleRate * 1.2));
      var buf = ctx.createBuffer(1, len, ctx.sampleRate);
      var d = buf.getChannelData(0);
      for (var i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      var s = ctx.createBufferSource();
      s.buffer = buf; s.loop = true;
      return s;
    }
    function bzBuild() {
      if (bzNodes) return;
      var oscA = ctx.createOscillator(), oscB = ctx.createOscillator(), oscS = ctx.createOscillator();
      oscA.type = 'sawtooth'; oscB.type = 'sawtooth'; oscS.type = 'sine';
      var gD = ctx.createGain(), gS = ctx.createGain(), gT = ctx.createGain();
      var lp = ctx.createBiquadFilter(), nz = makeNoise(), bp = ctx.createBiquadFilter(), ng = ctx.createGain();
      oscA.connect(gD); oscB.connect(gD); oscS.connect(gS);
      gD.connect(lp); gS.connect(lp);
      nz.connect(bp); bp.connect(ng); ng.connect(lp);
      lp.connect(gT); gT.connect(bus);
      gT.gain.value = 0.0001;
      oscA.start(); oscB.start(); oscS.start(); nz.start();
      bzNodes = { oscA: oscA, oscB: oscB, oscS: oscS, gD: gD, gS: gS, gT: gT, lp: lp, ng: ng, bp: bp };
    }
    function bzHz() {
      var v = clamp(S.freq, 1, 100) / 100;
      return 30 * Math.pow(220 / 30, v);
    }
    function bzApply() {
      if (!bzNodes || !ctx) return;
      var t = ctx.currentTime, f = bzHz(), u = clamp(S.pow, 0, 100) / 100, suck = isSuck();
      bzNodes.oscA.frequency.setTargetAtTime(f * 3, t, 0.04);
      bzNodes.oscB.frequency.setTargetAtTime(f * 3.02, t, 0.04);   // 2% 失谐，出"活电机"的拍频
      bzNodes.oscS.frequency.setTargetAtTime(f, t, 0.05);
      // 吸吮式：低通压低、噪声更湿，听感从"嗡"变成"含住又松开"
      bzNodes.lp.frequency.setTargetAtTime(suck ? 1500 : 4200, t, 0.08);
      bzNodes.ng.gain.setTargetAtTime(suck ? (0.08 + u * 0.34) : (0.04 + u * 0.26), t, 0.12);
      bzNodes.bp.frequency.setTargetAtTime((suck ? 420 : 1100) + u * (suck ? 900 : 1900), t, 0.12);
      bzNodes.bp.Q.setTargetAtTime(1.0 + u * 1.4, t, 0.12);
      bzNodes.gD.gain.setTargetAtTime(suck ? (0.22 + u * 0.20) : (0.44 + u * 0.30), t, 0.12);
      bzNodes.gS.gain.setTargetAtTime(suck ? (1.0 - u * 0.15) : (0.90 - u * 0.20), t, 0.12);
    }
    function bzStart() {
      if (bzOn || !ensure()) return;
      bzBuild(); bzApply();
      bzOn = true;
      bzNodes.gT.gain.setTargetAtTime(bzLevel(), ctx.currentTime, 0.08);   // 电机起转
    }
    function bzStop() {
      bzOn = false;
      if (bzNodes && ctx) bzNodes.gT.gain.setTargetAtTime(0.0001, ctx.currentTime, 0.09);
    }
    function bzLevel() { return (0.03 + clamp(S.pow, 0, 100) / 100 * 0.27) * (S.voice ? 0.5 : 1); }

    /* 装置每次推动都调一次：频率、强度、开关在这里统一同步 */
    function tick(env) {
      if (!S.voice || S.voice === 'off') { if (bzOn) bzStop(); return; }
      if (!ensure()) return;
      if (bzMode() && S.on) {
        if (!bzOn) bzStart();
        if (Date.now() - bzLast > 120) {     // 参数不必每帧写，AudioParam 本身就是平滑的
          bzLast = Date.now();
          bzApply();
          if (bzNodes) bzNodes.gT.gain.setTargetAtTime(bzLevel(), ctx.currentTime, 0.1);
        }
      } else if (bzOn) {
        bzStop();
      }
    }

    function bzMode() { return S.voice === 'buzz' || S.voice === 'both'; }
    function voiceOn() { return S.voice === 'tts' || S.voice === 'both'; }

    /* ---- 音频缓存（同一句不重复花钱） ---- */
    function openDb() {
      if (dbTried) return Promise.resolve(cacheDb);
      dbTried = true;
      return new Promise(function (resolve) {
        if (typeof indexedDB === 'undefined') return resolve(null);
        var settled = false;
        function done(v) { if (!settled) { settled = true; resolve(v); } }
        var req;
        try { req = indexedDB.open('toylink_voice', 1); } catch (e) { return done(null); }
        req.onupgradeneeded = function () {
          var d = req.result;
          if (!d.objectStoreNames.contains('v')) d.createObjectStore('v', { keyPath: 'id' });
        };
        req.onsuccess = function () { cacheDb = req.result; done(req.result); };
        req.onerror = function () { done(null); };
        req.onblocked = function () { done(null); };
        setTimeout(function () { done(null); }, 3500);
      });
    }
    function hashStr(s) {
      var h = 5381;
      for (var i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
      return (h >>> 0).toString(36);
    }
    function vkey(text, voice) {
      return hashStr([S.ttsModel, voice || S.ttsVoice, S.ttsFormat, S.ttsSpeed, S.target, text].join('|'));
    }
    function cached(k) {
      if (cache[k]) return Promise.resolve(cache[k]);
      return openDb().then(function (d) {
        if (!d) return null;
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').get(k);
            r.onsuccess = function () { if (r.result) cache[k] = r.result; resolve(r.result || null); };
            r.onerror = function () { resolve(null); };
          } catch (e) { resolve(null); }
        });
      });
    }
    function store(k, blob, meta) {
      var rec = { id: k, blob: blob, meta: meta, at: Date.now() };
      cache[k] = rec;
      // 新合成的进账就刷新"合成记录"那栏 —— 要等落库之后再读，否则读到旧的
      setTimeout(function () { paintAudioList(); }, 160);
      return openDb().then(function (d) {
        if (!d) return;
        try { d.transaction('v', 'readwrite').objectStore('v').put(rec); } catch (e) { /* noop */ }
      });
    }

    /* ---- 运行日志 ----
       面板里看不到 console，排错全靠这一栏。记的是"这一句有没有真的发出去、
       打到哪、几毫秒、多大、缓存中没中"，以及失败的分岔在哪一层。 */
    var LOG = [];
    var LOG_MAX = 60;
    function vlog(msg, cls) {
      var d = new Date();
      var t = pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());
      LOG.push({ t: t, m: String(msg), c: cls || '' });
      if (LOG.length > LOG_MAX) LOG.shift();
      if (S.voiceLog) { try { console.log('[TOY·LINK 语音] ' + msg); } catch (e) { /* noop */ } }
      renderLog();
    }
    function renderLog() {
      var box = $('#vs-log');
      var tag = $('#vs-log-tag');
      if (tag) tag.textContent = LOG.length ? (LOG.length + ' 条') : '';
      if (!box) return;
      if (!LOG.length) { box.innerHTML = '<div class="lgdim">（还没有记录）</div>'; return; }
      var atBottom = (box.scrollTop + box.clientHeight >= box.scrollHeight - 20);
      box.innerHTML = LOG.map(function (x) {
        return '<div class="lg' + (x.c ? ' ' + x.c : '') + '"><i>' + x.t + '</i>' + esc4(x.m) + '</div>';
      }).join('');
      if (atBottom) box.scrollTop = box.scrollHeight;
    }
    function ts() {
      var d = new Date();      return pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());
    }
    function fmtKB(n) { return n < 1024 ? (n + ' B') : ((n / 1024).toFixed(1) + ' KB'); }
    /* UTF-8 字节数 —— 中转按字节计费的场合，这个数就是钱 */
    function nBytes(s) {
      try { return new TextEncoder().encode(String(s)).length; } catch (e) { return String(s).length * 3; }
    }

    /* ---- 合成：两种传输方式
     *
     * 经作者中转：面板带自己的官方 Key，由中转转发到官方端点（它不持有任何 Key）。
     * direct 直连中转（默认）：URL + 令牌都填在面板里，令牌跟着聊天变量走。
     *   —— 少了本机脚本这一步，但令牌会随变量进聊天文件，也会明文落在页面上。
     *   中转自己开了跨域（Access-Control-Allow-Origin）时，直连才跑得通。
     *
     * 两条路的请求体完全一样，差别只在打到哪、谁来带鉴权头。 ---- */
    function buildHeaders(c) {
      var h = { 'Content-Type': 'application/json' };
      /* 经作者的中转服务器转发的是"一份正常的官方请求"，
         所以走官方的鉴权头与请求体，不带 x-toylink-* 那套旧的本机脚本协议头
         （服务器根本不认那些头，带上等于多送一份没人看的元数据）。 */
      if (c.authstyle === 'x-api-key' && c.key) h['x-api-key'] = c.key;
      else if (c.authstyle === 'raw' && c.key) h['Authorization'] = c.key;
      else if (c.authstyle !== 'none' && c.key) h['Authorization'] = 'Bearer ' + c.key;
      if (c.model && !c.noModelHdr) h[c.modelHdr] = c.model;
      // 额外请求头直接合并（作者中转那边会转发白名单内的头）
      if (c.extraRaw) {
        try {
          var ex = JSON.parse(c.extraRaw) || {};
          Object.keys(ex).forEach(function (k) { h[k] = String(ex[k]); });
        } catch (e) { /* 非法 JSON 由界面提示，这里忽略 */ }
      }
      return h;
    }

    function cfgNow() {
      var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
      var direct = !forwarding();
      /* endpoint 是"这一发到底打到哪个地址"，一次算清楚，后面 buildHeaders、
         日志、报错文案全用它，免得各处各判一次判出不一致。
           浏览器直打 → 用户填的地址（官方或第三方中转）
           经作者中转 → 作者的中转服务器（由官方地址固定映射出来） */
      var af = (!direct && usingAF()) ? afURL(S.ttsTarget) : '';
      return {
        transport: S.ttsTransport || 'direct',
        target: S.ttsTarget || '',
        /* via 标出这一发实际走哪条通道，用于日志与请求头构造：
           'direct'＝浏览器直打 ｜ 'af'＝经作者中转 */
        via: direct ? 'direct' : 'af',
        /* afUrl 留一份原始映射：映射不出来说明这条路走不通，要单独报错 */
        afUrl: af,
        afHealth: afHealth(),
        endpoint: direct ? (S.ttsTarget || '') : af,
        key: S.ttsKey || '',
        authstyle: S.ttsAuth || 'bearer',
        model: S.ttsModel || '',
        modelHdr: S.ttsModelHdr || 'model',
        /* 音色字段名与音色字段是否发 model，都随平台走：
           Fish 用 reference_id + model 头；OpenAI 用 voice 字段、不要 model 头。 */
        voiceField: (S.ttsPlatform === 'custom') ? (S.ttsRefField || 'reference_id') : p.voiceField,
        /* 平台级别"不发 model 头"：OpenAI 协议里模型在 body 里；MiniMax 也是 ——
           官方只要 Authorization + Content-Type，多一个 model 头只会给网关添判断余地。
           作者中转那条路也一样不带（它转发的是同一份官方请求）。 */
        noModelHdr: (S.ttsPlatform === 'openai' || S.ttsPlatform === 'minimax') ? true : !!S.ttsNoModelHdr,
        extraRaw: S.ttsExtraHdrs || '',
        latency: S.ttsLatency || 'low',
        format: S.ttsFormat || 'mp3',
        speed: S.ttsSpeed || 1,
        langBoost: !!S.ttsLangBoost,
        plat: S.ttsPlatform || 'fish'
      };
    }
    function buildReqBody(c, text, vv) {
      var p = PLATFORMS[c.plat] || PLATFORMS.fish;
      return p.req(c, text, vv);
    }

    /* ---------- MiniMax 的 hex 音频解包 ----------
       MiniMax T2A 返回 JSON：{ data: { audio: "<hex>", status: 2 },
                                base_resp: { status_code: 0, status_msg: "success" } }
       音频是十六进制字符串，得转回字节数组才喂得进播放器。
       三个容易踩的点：
         ① base_resp.status_code 才是成败判据 —— HTTP 200 也可能失败；
         ② data 可能是 null（官方文档明说要判空）；
         ③ 音频很长时 hex 串能到几十万字符，必须用 typed array 逐字节填，
            别用 push/concat（那样会慢到卡住界面）。 */
    function hexToBytes(hex) {
      var s = String(hex || '').replace(/[\s\r\n]+/g, '');
      if (s.length < 2) return null;
      if (s.length % 2 !== 0) s = s.slice(0, -1);        // 奇数个字符：丢掉最后一个
      var n = s.length >> 1;
      var out = new Uint8Array(n);
      for (var i = 0; i < n; i++) {
        var b = parseInt(s.substr(i * 2, 2), 16);
        if (isNaN(b)) { vlog('hex 音频里有非十六进制字符（第 ' + (i * 2) + ' 个字符），已中断', 'err'); return null; }
        out[i] = b;
      }
      return out;
    }

    function parseMinimaxJSON(tx, ms) {
      var j;
      try { j = JSON.parse(String(tx || '')); }
      catch (e) {
        vlog('MiniMax 回的 JSON 解析不了：' + esc4(String(tx || '').slice(0, 160)), 'err');
        throw new Error('MiniMax 回的 JSON 解析不了');
      }
      var br = j.base_resp || {};
      if (br.status_code !== 0) {
        var how = br.status_code === 1004 ? ' ← 鉴权失败，检查 API key'
          : br.status_code === 1002 ? ' ← 触发限流（并发/配额）'
            : br.status_code === 1039 ? ' ← TPM 限流：一分钟内字符数超了'
              : br.status_code === 1001 ? ' ← 上游超时'
                : br.status_code === 1042 ? ' ← 无效字符超过 10%，被拒'
                  : br.status_code === 2013 ? ' ← 入参不合法（模型名/音色 ID 对不上？）' : '';
        vlog('MiniMax 返回失败 ' + br.status_code + '：' + esc4(String(br.status_msg || '')) + how, 'err');
        throw new Error('MiniMax ' + br.status_code + '：' + String(br.status_msg || ''));
      }
      var d = j.data;
      if (!d) { vlog('MiniMax 回了 status_code=0 但没有 data（官方文档说这种情况要判空）', 'err'); throw new Error('MiniMax 没有返回音频数据'); }
      var bytes = hexToBytes(d.audio);
      if (!bytes || !bytes.length) { vlog('MiniMax 的 data.audio 是空的或不是合法 hex', 'err'); throw new Error('MiniMax 没有返回可用音频'); }
      var ei = j.extra_info || {};
      vlog('MiniMax 解包完成 ' + Math.round(bytes.length / 1024 * 10) / 10 + ' KB · ' + (ms || '?') + 'ms'
        + (ei.audio_length ? ' · 音频 ' + (Math.round(ei.audio_length / 100) / 10) + ' 秒' : '')
        + (ei.usage_characters ? ' · 计费 ' + ei.usage_characters + ' 字符' : ''), 'ok');
      return bytes.buffer;
    }

    /* ---------- 送去合成前，标记怎么处理 ----------
       多数平台（Fish、OpenAI）不认识方括号标记，念出来会变成噪音 —— 一律删掉。
       MiniMax 是例外：它认「（全角括号）」的插词，而且官方只认固定一张表。
       不在表里的（[whispering]、[颤抖] 这类）如果原样转过去会被当正文念出来，
       所以只转换认识的，其余一律删 —— 宁可少一点语气，也不要念出噪音。
       另外这张表只在 speech-2.8 系列上生效，换别的模型全删。 */
    var MM_FX = {
      '气声': 'breath', '喘息': 'pant', '抽气': 'gasps', '吸气': 'inhale', '呼气': 'exhale',
      '笑': 'laughs', '轻笑': 'chuckle', '咳嗽': 'coughs', '清嗓': 'clear-throat',
      '闷哼': 'groans', '抽鼻子': 'sniffs', '叹气': 'sighs', '鼻音': 'snorts',
      '打嗝': 'burps', '咂嘴': 'lip-smacking', '哼': 'humming', '嘶声': 'hissing',
      '沉吟': 'emm', '喷嚏': 'sneezes'
    };
    /* 官方支持的英文标记原样可用，一并放进白名单 */
    ['laughs', 'chuckle', 'coughs', 'clear-throat', 'groans', 'breath', 'pant',
      'inhale', 'exhale', 'gasps', 'sniffs', 'sighs', 'snorts', 'burps',
      'lip-smacking', 'humming', 'hissing', 'emm', 'sneezes'].forEach(function (k) {
      MM_FX[k] = k;
    });

    function stripMarks(s) { return String(s == null ? '' : s).replace(/\[[^\]]*\]\s*/g, ''); }

    function miniMarks(s) {
      var mdl = String(S.ttsModel || '');
      if (mdl.indexOf('2.8') < 0) return stripMarks(s);   // 老模型不认插词，全删
      var out = String(s == null ? '' : s).replace(/\[([^\]]+)\]/g, function (_, inner) {
        var key = String(inner).trim();
        var hit = MM_FX[key] || MM_FX[key.toLowerCase()];
        return hit ? '（' + hit + '）' : ' ';
      });
      /* 标记原来占着位置，替换掉之后会留下空档 —— 行首最明显。
         还有一处：台词库里标记与正文之间本来有一个空格（"[breath] 不行……"），
         换成全角插词后那个空格吊在「）」后面，念出来是多一次停顿。 */
      return out
        .replace(/）[ \t\u3000]+/g, '）')
        .replace(/^[ \t\u3000]+/, '').replace(/[ \t\u3000]{2,}/g, ' ').trim();
    }

    /* 一份台词送去合成前的清洗：去掉方括号标记（MiniMax 换成括号插词），多行并成一句 */
    function speakText(plat, text) {
      var one = (plat === 'minimax') ? miniMarks : stripMarks;
      var s = String(text || '').split(/[\r\n]+/).map(function (l) { return one(l).trim(); })
        .filter(Boolean).join('，');
      if (!s) s = one(text).trim();
      return s;
    }

    function synth(text, voice) {
      var c = cfgNow();
      if (!c.target) { vlog('没填合成地址', 'err'); return Promise.reject(new Error('没填合成地址')); }
      if (!c.endpoint) { vlog('缺合成地址', 'err'); return Promise.reject(new Error('先填「合成地址」')); }
      /* 经作者中转时，实际地址不是"用户填的"而是从官方地址映射出来的 ——
         映射不出来说明这条路走不通，要说清是地址不认。 */
      if (c.via === 'af' && !c.afUrl) {
        vlog('作者中转不认这个官方地址：' + c.target, 'err');
        return Promise.reject(new Error('作者中转只转发 Fish 与 MiniMax 国际站的官方端点，当前地址不在其中'));
      }
      if (c.authstyle !== 'none' && !c.key) {
        vlog(c.via === 'af' ? '经作者中转需要填官方 API Key' : '这一档要填令牌', 'err');
        return Promise.reject(new Error(c.via === 'af'
          ? '经作者中转要用你自己的官方 API Key，先填「官方 API Key」'
          : '先填令牌（或把鉴权改成「不带」）'));
      }
      var url = c.endpoint;
      var vv = voice || S.ttsVoice;
      /* 多行台词原样送去合成（模型会按行/句切分），但每行的情绪标记要先处理掉。
         具体怎么处理见上面 speakText —— MiniMax 换全角括号插词、其余平台删掉。 */
      var speak = speakText(c.plat, text);
      var k = vkey(text, vv);
      var t0 = Date.now();
      vlog('请求 ' + String(text).slice(0, 34) + ' · ' + nBytes(speak) + ' 字节 · '
        + (c.via === 'af' ? '经作者中转' : '直连')
        + (vv ? ' · 音色 ' + vv : ' · 默认音色'), 'hi');
      return cached(k).then(function (hit) {
        if (hit && hit.blob) {
          vlog('缓存命中 ' + k + '（' + fmtKB(hit.blob.size) + '），未联网', 'ok');
          return { cached: true, id: k, blob: hit.blob };
        }
        vlog('缓存未命中，开始联网合成…', 'step');
        // 请求体按平台生成：Fish 用 reference_id + 一堆调参，OpenAI 用 input + voice，两者字段名都不一样
        var body = buildReqBody(c, speak, vv);

        var ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        var timer = ctl ? setTimeout(function () { ctl.abort(); }, S.ttsTimeout) : null;
        var h = buildHeaders(c);

        /* 把"实际发出去的东西"记进日志。
           排错时缺的往往就是这个：光看"请求失败"没用，得看到打到哪个 URL、
           带了哪些头、有没有带鉴权。令牌只记"有没有带"，不记值。 */
        var authHdr = h['Authorization'] ? 'Authorization（' + (h['Authorization'].indexOf('Bearer ') === 0 ? 'Bearer' : '裸值') + '）'
          : (h['x-api-key'] ? 'x-api-key' : '无');
        var hdrNames = Object.keys(h).filter(function (k) {
          return k !== 'Authorization' && k !== 'x-api-key';
        }).join(', ');
        vlog('  → ' + (c.via === 'af' ? 'AF' : c.transport.toUpperCase()) + ' ' + url, 'step');
        vlog('  → 鉴权头：' + authHdr + ' ｜ 其余头：' + (hdrNames || '无'), 'step');
        vlog('  → 请求体字段：' + Object.keys(body).join(', ') + '（' + nBytes(JSON.stringify(body)) + ' 字节）', 'step');
        var lines = String(text || '').split(/[\r\n]+/).filter(function (x) { return x.trim(); });
        if (lines.length > 1) vlog('  → 多行台词 ' + lines.length + ' 行，合成时并成一句（去掉标记）', 'step');

        return fetch(url, {
          method: 'POST', headers: h, body: JSON.stringify(body),
          signal: ctl ? ctl.signal : undefined,
          /* 不带酒馆的 Cookie，也不带网页地址：中转与官方都不需要这两样，
             送过去只是白送一份身份线索。作者中转那边同样不需要凭据型请求。 */
          credentials: 'omit', referrerPolicy: 'no-referrer'
        }).then(function (r) {
          if (timer) clearTimeout(timer);
          var ms = Date.now() - t0;
          /* 报错时把"这一发是谁回的"说准：直连是官方或第三方中转直接回的，
             经作者中转是中转回的（真正的上游错误它也会透传下来）。 */
          var who = (c.via === 'af') ? '作者中转' : '上游';
          if (!r.ok) {
            return r.text().then(function (tx) {
              var detail = String(tx || '').slice(0, 200);
              /* 402 是"官方那边的 API 余额/额度不够"。
                 Fish 特别注明：API credit 与平台 credit 是分开的两套 ——
                 网页版有额度，不代表 API 端口能用，这一点最容易误解。
                 而 s2.1-pro-free 是官方标称 $0 的同一个模型，所以先劝他换过去试。 */
              var isCredit = (r.status === 402) || /credit|balance|quota|insufficient/i.test(detail);
              var freeNow = String(S.ttsModel || '').indexOf('-free') >= 0;
              var how = (r.status === 401 || r.status === 403) ? ' ← 鉴权失败，检查令牌与鉴权方式'
                : r.status === 404 ? ' ← 路径不对，检查合成地址'
                  : r.status === 413 ? ' ← 请求体太大'
                    : r.status === 429 ? ' ← 触发限流（并发/配额），等几秒再试，不要连着重发'
                      : isCredit ? ' ← 官方说 API credit 不足'
                        : '';
              vlog(who + ' 回 ' + r.status + '（' + ms + 'ms）' + how + (detail ? ' · ' + detail : ''), 'err');
              if (isCredit) {
                vlog('  官方说明：API credit 与平台 credit 是分开的两套，'
                  + '网页版有额度不等于 API 端口能用；充值/查余额：'
                  + 'https://fish.audio/app/developers', 'err');
                if (c.plat === 'fish' && !freeNow) {
                  vlog('  现在用的是付费型号 ' + (S.ttsModel || '(空)') + '，'
                    + '把它改成 s2.1-pro-free 就是同一个模型的免费档，先拿它试通路。', 'hi');
                  toast('Fish 的 API 余额不足。模型先换成 s2.1-pro-free（同一个模型的免费档）再试', 7000);
                } else if (c.plat === 'fish' && freeNow) {
                  toast('官方回了余额不足 —— 免费档也被限了，得去官网看 API credit', 7000);
                }
              }
              throw new Error(who + '返回 ' + r.status + '：' + detail);
            }, function () {
              vlog(who + ' 回 ' + r.status + '（' + ms + 'ms）', 'err');
              throw new Error(who + '返回 ' + r.status);
            });
          }
          var ct = r.headers.get('content-type') || '';
          if (ct.indexOf('json') >= 0) {
            /* 有的平台就是回 JSON —— MiniMax 把音频塞在 data.audio 里、还是 hex 字符串。
               这类走各自的解析函数；其余情况照旧按"不是音频"报错。 */
            if (c.plat === 'minimax' || PLATFORMS[c.plat] && PLATFORMS[c.plat].resp === 'minimax') {
              return r.text().then(function (tx) { return parseMinimaxJSON(tx, ms); });
            }
            return r.text().then(function (tx) {
              vlog('上游回的是 JSON 不是音频：' + String(tx || '').slice(0, 160), 'err');
              throw new Error('上游不是音频：' + String(tx || '').slice(0, 200));
            });
          }
          return r.arrayBuffer().then(function (buf) {
            if (timer) clearTimeout(timer);
            /* 少数中转不带 content-type，直接把 JSON 当纯文本发回来。
               这里认一下：开头是 { 就先按 JSON 试，失败再当音频。 */
            if (c.plat === 'minimax' && buf && buf.byteLength > 2) {
              var head = new Uint8Array(buf, 0, 1);
              if (head[0] === 0x7B) {   // '{'
                try {
                  var txt = new TextDecoder('utf-8').decode(buf);
                  return parseMinimaxJSON(txt, ms);
                } catch (e) { /* 认错了，继续当音频处理 */ }
              }
            }
            var total = Date.now() - t0;
            var kb = buf ? Math.round(buf.byteLength / 1024 * 10) / 10 : 0;
            vlog('收到音频 ' + kb + ' KB · ' + total + 'ms · ' + (ct || '无类型'), 'ok');
            return buf;
          });
        }).then(function (buf) {
          if (!buf || !buf.byteLength) { vlog('拿到空音频', 'err'); throw new Error('拿到空音频'); }
          var blob = new Blob([buf], { type: guessMime(S.ttsFormat) });
          return store(k, blob, { text: text, model: S.ttsModel, voice: vv }).then(function () {
            return { cached: false, id: k, blob: blob };
          });
        }, function (e) {
          if (timer) clearTimeout(timer);
          var msg = (e && e.name === 'AbortError') ? '请求超时（' + S.ttsTimeout + 'ms）'
            : String((e && e.message) || e);
          if (/Failed to fetch|NetworkError|Load failed/i.test(msg)) {
            vlog(c.via === 'af'
              ? '连不上作者中转：检查网络，或换成「浏览器直打」再试。'
              : (isOfficial()
                ? '直连被拦：官方端点不给跨域头（CORS），浏览器一定拦下。'
                  + '把走法切到「作者的中转服务器」就能跑通。'
                : '直连被拦：这个地址没开跨域（CORS），或地址写错了。'), 'err');
          } else if (e && e.name !== 'AbortError') {
            vlog('请求失败：' + msg, 'err');
          }
          throw e;
        });
      });
    }

    /* ---- 播放 ---- */
    function play(blob, opts) {
      if (!blob) return;
      if (!ensure()) { toast('这个环境没有 Web Audio，放不了声音'); return; }
      try {
        if (cur) { try { cur.pause(); } catch (e) { /* noop */ } }
        // 上一条的音源节点断开：每播一句都新建一个接到总线上，不断开会越积越多
        if (curSrc) { try { curSrc.disconnect(); } catch (e) { /* noop */ } curSrc = null; }
        if (curUrl) { try { URL.revokeObjectURL(curUrl); } catch (e) { /* noop */ } }
        curUrl = URL.createObjectURL(blob);
        var el = new Audio(curUrl);
        cur = el;
        el.volume = clamp((opts && opts.vol != null ? opts.vol : S.voiceVol / 100), 0, 1);
        try {
          var src = ctx.createMediaElementSource(el);
          src.connect(bus);
          curSrc = src;
        } catch (e) { /* 某些环境接不了总线就退回原生播放 */ }
        var p = el.play();
        if (p && p.catch) p.catch(function () { /* 自动播放被挡，用户手动点 */ });
      } catch (e) { /* noop */ }
    }

    /* 说一句：先查缓存，没有就合成，然后播。voice 可指定音色 */
    function say(text, opts) {
      text = String(text || '').trim();
      if (!text || !voiceOn()) return Promise.resolve(null);
      var voice = (opts && opts.voice) || S.ttsVoice;
      var my = ++seq;
      if (my > 1) vlog('新的播放打断上一条（第 ' + my + ' 次）', 'warn');
      return synth(text, voice).then(function (r) {
        if (my !== seq) return null;      // 期间又来了新的一句，这条丢掉
        play(r.blob, opts);
        return r;
      }).catch(function (e) {
        var msg = (e && e.message) || String(e);
        if (my === seq) {
          // synth 里已经把细节记进日志了，这里只补一句"这一条最终没播出来"
          vlog('这一条没播出来：' + msg, 'err');
          toast('语音没出来：' + msg, 3200);
        }
        return null;
      });
    }
    /* 预热：把固定音集先合成好，之后就不占实时通道 */
    function warm(list) {
      if (!voiceOn() || !list || !list.length) return Promise.resolve(0);
      var n = 0, i = 0;
      vlog('开始预热 ' + list.length + ' 条（串行，间隔 260ms）', 'hi');
      return new Promise(function (resolve) {
        (function step() {
          if (i >= list.length) {
            vlog('预热结束：成功 ' + n + ' / ' + list.length + ' 条', n ? 'ok' : 'warn');
            return resolve(n);
          }
          synth(list[i++]).then(function () { n++; }, function () { /* noop */ }).then(function () {
            setTimeout(step, 260);        // 串行，避开中转的并发上限
          });
        })();
      });
    }
    function clearCache() {
      cache = {};
      return openDb().then(function (d) {
        if (!d) return;
        try { d.transaction('v', 'readwrite').objectStore('v').clear(); } catch (e) { /* noop */ }
      });
    }
    /* 缓存里所有的音频（合成记录就是它）。
       按时间倒序，新的在前 —— 试听时最关心的就是刚合成的那几条。 */
    function listAll() {
      return openDb().then(function (d) {
        if (!d) return [];
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').getAll();
            r.onsuccess = function () {
              var list = r.result || [];
              list.sort(function (a, b) { return b.at - a.at; });
              resolve(list);
            };
            r.onerror = function () { resolve([]); };
          } catch (e) { resolve([]); }
        });
      });
    }
    function getRec(id) {
      return openDb().then(function (d) {
        if (!d) return null;
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').get(id);
            r.onsuccess = function () { resolve(r.result || null); };
            r.onerror = function () { resolve(null); };
          } catch (e) { resolve(null); }
        });
      });
    }
    function cacheCount() {
      return openDb().then(function (d) {
        if (!d) return Object.keys(cache).length;
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').count();
            r.onsuccess = function () { resolve(r.result || 0); };
            r.onerror = function () { resolve(Object.keys(cache).length); };
          } catch (e) { resolve(Object.keys(cache).length); }
        });
      });
    }
    function level() {
      if (!ana) return 0;
      try {
        ana.getByteTimeDomainData(anaBuf);
        var sum = 0;
        for (var i = 0; i < anaBuf.length; i += 4) {
          var v = (anaBuf[i] - 128) / 128;
          sum += v * v;
        }
        return Math.sqrt(sum / (anaBuf.length / 4));
      } catch (e) { return 0; }
    }
    function resume() { if (ensure()) { try { ctx.resume(); } catch (e) { /* noop */ } } }

    return {
      ensure: ensure, resume: resume, tick: tick, say: say, play: play, warm: warm,
      clearCache: clearCache, cacheCount: cacheCount, level: level,
      listAll: listAll, getRec: getRec,
      bzOn: function () { return bzOn; },
      voiceOn: voiceOn, buzzMode: bzMode,
      stopAll: function () { bzStop(); if (cur) { try { cur.pause(); } catch (e) { /* noop */ } } },
      // 实例卸载时关掉音频上下文：它是用酒馆页面的构造器建的，iframe 重载后不会自己消失
      close: function () {
        try { bzStop(); } catch (e) { /* noop */ }
        if (cur) { try { cur.pause(); } catch (e) { /* noop */ } }
        if (ctx) { try { ctx.close(); } catch (e) { /* noop */ } ctx = null; }
      },
      // 日志：面板内部记一份，外面的连通性检查等也往里写
      addLog: vlog,
      repaintLog: renderLog,
      clearLog: function () { LOG.length = 0; renderLog(); },
      logText: function () { return LOG.map(function (x) { return '[' + x.t + '] ' + x.m; }).join('\n'); },
      logCount: function () { return LOG.length; },
    };
  })();

  /* 面板里的运行日志挂一份到 window：手机上没有控制台，排语音问题时
     在酒馆的控制台里敲 __TOYLINK__.logText() 就能把现场整份捞出来。 */
  try {
    WIN.__toylink_log = {
      logText: function () { return VOC.logText(); },
      logCount: function () { return VOC.logCount(); }
    };
  } catch (e) { /* noop */ }

  function guessMime(f) {
    if (f === 'wav') return 'audio/wav';
    if (f === 'opus') return 'audio/ogg';
    return 'audio/mpeg';
  }

  /* =========================================================
   * ZIP 打包（stored 模式，不压缩）
   *
   * 面板是单文件、零依赖，所以自己写一个最小 ZIP。
   * 音频本身已经是压缩格式（mp3/opus），再压一遍收益接近零、还费 CPU，
   * 所以用 stored —— 实现简单，任何解压软件都认。
   * ======================================================= */
  var CRC_TBL = (function () {
    var t = new Uint32Array(256);
    for (var n = 0; n < 256; n++) {
      var c = n;
      for (var k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[n] = c >>> 0;
    }
    return t;
  })();
  function crc32(buf) {
    var c = 0xFFFFFFFF;
    for (var i = 0; i < buf.length; i++) c = CRC_TBL[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
  }
  function u16(a, o, v) { a[o] = v & 255; a[o + 1] = (v >>> 8) & 255; }
  function u32(a, o, v) { a[o] = v & 255; a[o + 1] = (v >>> 8) & 255; a[o + 2] = (v >>> 16) & 255; a[o + 3] = (v >>> 24) & 255; }

  function zipBuild(entries) {
    var enc = new TextEncoder();
    var parts = [], central = [], offset = 0;
    function cat(u8) { parts.push(u8); offset += u8.length; }

    entries.forEach(function (e) {
      var nameB = enc.encode(e.name);
      var data = e.data;
      var crc = crc32(data);
      var lh = new Uint8Array(30 + nameB.length);
      u32(lh, 0, 0x04034b50);          // 局部文件头签名
      u16(lh, 4, 20);                  // 需要的版本
      u16(lh, 6, 0x0800);              // 文件名走 UTF-8
      u16(lh, 8, 0);                   // 压缩方式 0 = stored
      u16(lh, 10, 0);                  // 修改时间
      u16(lh, 12, 0);                  // 修改日期
      u32(lh, 14, crc);
      u32(lh, 18, data.length);        // 压缩后大小
      u32(lh, 22, data.length);        // 原始大小
      u16(lh, 26, nameB.length);
      u16(lh, 28, 0);
      lh.set(nameB, 30);
      cat(lh); cat(data);

      var cd = new Uint8Array(46 + nameB.length);
      u32(cd, 0, 0x02014b50);          // 中央目录签名
      u16(cd, 4, 20);
      u16(cd, 6, 20);
      u16(cd, 8, 0x0800);
      u16(cd, 10, 0);
      u32(cd, 16, crc);
      u32(cd, 20, data.length);
      u32(cd, 24, data.length);
      u16(cd, 28, nameB.length);
      u32(cd, 42, 0);
      cd.set(nameB, 46);
      central.push(cd);
    });

    var cdSize = 0;
    central.forEach(function (c) { cdSize += c.length; });
    var eocd = new Uint8Array(22);
    u32(eocd, 0, 0x06054b50);          // 目录结束记录
    u16(eocd, 8, entries.length);
    u16(eocd, 10, entries.length);
    u32(eocd, 12, cdSize);
    u32(eocd, 16, offset);
    central.forEach(function (c) { parts.push(c); });
    parts.push(eocd);

    var total = 0;
    parts.forEach(function (p) { total += p.length; });
    var out = new Uint8Array(total), at = 0;
    parts.forEach(function (p) { out.set(p, at); at += p.length; });
    return out;
  }
  function safeName(s) {
    return String(s || '').replace(/[\\/:*?"<>|\r\n\t]+/g, '_').replace(/\s+/g, ' ').trim().slice(0, 24) || 'audio';
  }

  /* =========================================================
   * 4b. 阶段值的两个闸门：贴上 / 拿起 / 已满
   *
   * 「贴上 / 拿起」是一道总闸，描述的是"装置还在不在身上"：
   *   贴上 → 装置在，刺激在走，阶段值照常累积
   *   拿起 → 装置被拿走，刺激停下，阶段值停在当前值不动
   *   按钮上写当前状态，点一下就切换。
   *   注意它只拦累积，不拦玩家主动按的「冲击」「临界」「冲刺」——
   *   "拿起"是"不再自己往上涨"，不是"把面板锁死"。
   *
   * 阶段值满了（hi）不再像以前那样自动轮回重头：满值本身是一道锁，
   *   锁住累积，同时解锁「冲刺」。要离开满值只有两条路，都得玩家按：
   *     · 临界 → 回到临界区间或从头开始（按「到达临界后归零」那一档）
   *     · 冲刺 → 装置直冲顶点，完事后阶段值重来，而且之后要花更久才爬得回来
   * ======================================================= */
  function pushAro(d) {
    if (!S.hold || d <= 0) return;              // 装置被拿起了：不涨
    if (S.hi || S.aro >= 100) { S.aro = 100; return; }
    S.aro = clamp(S.aro + d, 0, 100);
  }

  /* 冲刺完成：阶段值从头来，并且这一次更慢 */
  function applyDashSlow() {
    S.aro = 0;
    S.stage = 1;
    S.hi = false;
    S.slow = S.dashRate;
    S.lastEvent = '冲刺完成，' + wearerName() + '被放回到适应的起点，再来一次要慢得多';
    toast('冲刺完成：阶段值归零，之后累积放慢到 ' + Math.round(S.dashRate * 100) + '%', 3600);
    react('peak');
    render();
    syncVars(true);
  }

  /* 满值锁：不自动轮回，同时解锁「冲刺」。pending 要清掉 ——
     满值那一瞬间如果还挂着"等 AI 生成"，会跟玩家的手动选择打架。 */
  function enterHi() {
    if (S.hi) return;
    S.hi = true;
    S.pending = false;
    S.lastEvent = '阶段值已满，' + wearerName()
      + '到了极限 —— 临界与冲刺都已解锁，之后怎么走由玩家按';
    toast('阶段值已满', 2600);
  }

  /* 「贴上 / 拿起」——并排两颗，选中的那颗框出来。
