      toast(S.ttsLangBoost ? '会一起发语气指令（需要较新的语音模型）' : '不发语气指令');
    });
  })();
  bindText('#s-tts-speed', 'ttsSpeed', true);
  bindText('#s-voicevol', 'voiceVol', true);

  // 延迟档：三档循环
  var LAT_ORDER = ['low', 'balanced', 'normal'];
  onEl('#s-tts-latency', 'click', function () {
    var i = LAT_ORDER.indexOf(S.ttsLatency);
    S.ttsLatency = LAT_ORDER[(i + 1) % LAT_ORDER.length];
    this.textContent = S.ttsLatency;
    persist();
    toast('延迟档：' + S.ttsLatency + (S.ttsLatency === 'normal' ? '（质量优先，慢）' : ''));
