  // 半透明色（用于气泡底色/描边）：#RRGGBB + 两位十六进制透明度
  function charColorAlpha(color, alphaHex) {
    return color && /^#[0-9a-fA-F]{6}$/.test(color) ? color + (alphaHex || '1a') : color;
  }

  // ========== 读取玉子手机内部头像与立绘数据库（强化适配 portraits 数据结构） ==========
  function getAvatarFromPhoneStorage(name) {
    if (!name) return '';
    try {
      const lStores = [localStorage, window.parent?.localStorage, window.top?.localStorage].filter(Boolean);
      for (const ls of lStores) {
        for (let i = 0; i < ls.length; i++) {
          const k = ls.key(i);
          if (k && k.startsWith('usb_phone_') && k.endsWith('.json')) {
            const raw = ls.getItem(k);
            if (raw) {
              const pData = JSON.parse(raw);
              const avObj = pData?.value?.avatars || pData?.avatars;
              if (avObj && typeof avObj === 'object') {
                for (const charKey of Object.keys(avObj)) {
                  if (isNameMatch(charKey, name) && avObj[charKey]) {
                    const resolved = resolveAvatarUrl(avObj[charKey]);
                    if (resolved) return resolved;
                  }
                }
              }
            }
          }
          if (k && k.startsWith('usb_portraits_') && k.endsWith('.json')) {
            const raw = ls.getItem(k);
            if (raw) {
              const pData = JSON.parse(raw);
              const val = pData?.value || pData;
              if (val && typeof val === 'object') {
                for (const charKey of Object.keys(val)) {
                  if (isNameMatch(charKey, name)) {
                    const cData = val[charKey];
                    let pUrl = cData?.current;
                    if (!pUrl && Array.isArray(cData?.paths) && cData.paths.length) {
                      pUrl = cData.paths[cData.paths.length - 1];
                    }
                    if (!pUrl && Array.isArray(cData?.portraits) && cData.portraits.length) {
                      const lastP = cData.portraits[cData.portraits.length - 1];
                      pUrl = typeof lastP === 'string' ? lastP : lastP?.path;
                    }
                    if (pUrl) {
                      const resolved = resolveAvatarUrl(pUrl);
                      if (resolved) return resolved;
                    }
                  }
                }
              }
            }
          }
        }
      }
    } catch (e) { /* ignore */ }
    return '';
  }


  // ========== 玉子手机数据适配层（QQ / 广场表 / 正文人物库） ==========
  // 对应原版「统一状态栏存储」：把玉子手机的社交数据读取到 ubStorageCache，
  // 供通讯录、邀请界面与 AI 台词上下文使用。
  let ubStorageCache = null;
  let ubStoragePromise = null;
  let ubStorageGeneration = 0;
  let ubLastPreloadHash = '';
  let ubForceAttemptedHash = '';
  let __phoneDataCache__ = null;
  const yuziMediaUrlCache = new Map();

  function ubPickFromMap(map, name) {
    if (!map || typeof map !== 'object' || !name) return '';
    if (typeof map[name] === 'string' && map[name]) return map[name];
    const key = Object.keys(map).find(k => isNameMatch(k, name));
    return key ? (typeof map[key] === 'string' ? map[key] : '') : '';
  }

  function yuziIdbRequest(request) {
    return new Promise((resolve, reject) => {
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error || new Error('IndexedDB 请求失败'));
    });
  }

  function yuziDbExists(name) {
    return new Promise((resolve) => {
      try {
        if (!indexedDB.databases) { resolve(true); return; }
        indexedDB.databases().then(list => resolve(Array.isArray(list) && list.some(db => db && db.name === name)), () => resolve(true));
      } catch (e) { resolve(true); }
    });
  }

  function yuziOpenDb(name, version) {
    return new Promise((resolve, reject) => {
      let request;
      try {
        request = version ? indexedDB.open(name, version) : indexedDB.open(name);
      } catch (e) { reject(e); return; }
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error || new Error('IndexedDB 打开失败'));
      request.onblocked = () => reject(new Error('IndexedDB 被其它窗口占用'));
    });
  }

  async function yuziOpenExistingDb(name) {
    if (typeof indexedDB === 'undefined') return null;
    if (!(await yuziDbExists(name))) return null;
    try { return await yuziOpenDb(name); } catch (e) { return null; }
  }

  // 玉子 QQ 作用域 ID（与 st-yuzi-phone modules/qq-v2/host/adapter.js 保持一致）
  function yuziResolveQQScopeId(ctx) {
    try {
      if (!ctx) return '';
      const chatId = (typeof ctx.getCurrentChatId === 'function' ? ctx.getCurrentChatId() : '') || ctx.chatId || ctx.chat_id || ctx.chat_file || '';
      const chatFile = ctx.chatFile || ctx.chat_file || chatId;
      const groupId = String(ctx.groupId ?? ctx.group_id ?? '').trim();
      let hostType = '';
      let hostId = '';
      if (groupId) { hostType = 'group'; hostId = groupId; }
      else {
        const chars = Array.isArray(ctx.characters) ? ctx.characters : [];
        const idx = Number.isInteger(ctx.characterId) ? ctx.characterId : -1;
        const ch = chars[idx] || null;
        const avatar = ch && typeof ch.avatar === 'string' ? ch.avatar : '';
        const characterId = (ctx.characterId !== undefined && ctx.characterId !== null) ? String(ctx.characterId) : '';
        if (avatar || characterId) { hostType = 'character'; hostId = avatar || characterId; }
        else { hostType = 'chat'; hostId = String(chatId || ''); }
      }
      if (!hostId) return '';
      const meta = ctx.chatMetadata || ctx.chat_metadata || {};
      const integrity = meta && typeof meta === 'object' ? String(meta.integrity || '') : '';
      return 'st:' + hostType + ':' + hostId + ':' + (integrity || chatFile || chatId);
    } catch (e) { return ''; }
  }

  async function yuziReadQQState() {
    const db = await yuziOpenExistingDb(YUZI_QQ_DB_NAME);
    if (!db) return null;
    try {
      if (!db.objectStoreNames.contains(YUZI_QQ_DB_STORE)) return null;
      const record = await yuziIdbRequest(db.transaction([YUZI_QQ_DB_STORE], 'readonly').objectStore(YUZI_QQ_DB_STORE).get(YUZI_QQ_DB_KEY));
      return record && record.value && typeof record.value === 'object' ? record.value : null;
    } catch (e) {
      return null;
    } finally {
      try { db.close(); } catch (e) { /* ignore */ }
    }
  }

  function yuziPickQQScope(state, ctx) {
    if (!state || !state.scopes || typeof state.scopes !== 'object') return null;
    const sid = yuziResolveQQScopeId(ctx);
    if (sid && state.scopes[sid]) return state.scopes[sid];
    const list = Object.values(state.scopes).filter(Boolean);
    return list.find(s => s.conversations && Object.keys(s.conversations).length) || list[0] || null;
  }

  function yuziBuildQQCache(state, ctx) {
    const out = { conversations: [] };
    const scope = yuziPickQQScope(state, ctx);
    if (!scope) return out;
    const people = scope.people && typeof scope.people === 'object' ? scope.people : {};
    const groups = scope.groups && typeof scope.groups === 'object' ? scope.groups : {};
    const convs = scope.conversations && typeof scope.conversations === 'object' ? scope.conversations : {};
    const messages = scope.messages && typeof scope.messages === 'object' ? scope.messages : {};
    const byConv = {};
    Object.values(messages).forEach(m => {
      if (!m || !m.conversationId) return;
      (byConv[m.conversationId] = byConv[m.conversationId] || []).push(m);
    });
    Object.values(convs).forEach(c => {
      if (!c || !c.conversationId) return;
      if (c.status && c.status !== 'active' && c.status !== 'contact') return;
      const person = c.personId ? people[c.personId] : null;
      const group = c.groupId ? groups[c.groupId] : null;
      const title = String(c.remark || '').trim() || (group && group.name) || (person && person.formalName) || '';
      if (!title) return;
      const list = (byConv[c.conversationId] || []).slice().sort((a, b) => Number(a.sequence || 0) - Number(b.sequence || 0)).slice(-30);
      const msgs = list.map(m => ({
        from: m.senderId === YUZI_QQ_SELF_ID ? 'me' : String(m.senderName || title),
        content: String(m.content == null ? '' : m.content)
      })).filter(m => m.content);
      const last = msgs[msgs.length - 1];
      out.conversations.push({
        id: c.conversationId,
        title: title,
        members: [title],
        personId: c.personId || '',
        groupId: c.groupId || '',
        messages: msgs,
        text: last ? last.content : ''
      });
    });
    return out;
  }

  // 玉子手机小剧场「广场表」→ 动态流（广场替代）
  function yuziReadSquareMoments() {
    const moments = [];
    try {
      const api = getAutoCardAPI();
      if (!api) return moments;
      const all = api.exportTableAsJson();
      if (!all || typeof all !== 'object') return moments;
      for (const key of Object.keys(all)) {
        if (!key.startsWith('sheet_')) continue;
        const table = all[key];
        if (!table || !Array.isArray(table.content) || table.content.length < 2) continue;
        const name = String(table.name || '');
        if (name !== '广场表' && key !== 'sheet_square_posts') continue;
        const header = table.content[0];
        if (!Array.isArray(header)) continue;
        const col = (label) => header.findIndex(h => String(h || '') === label);
        const iAuthor = col('发帖账号名');
        const iBody = col('帖子正文');
        const iTitle = col('帖子标题');
        const iComments = col('评论串');
        const iTime = col('时间文本');
        for (let r = 1; r < table.content.length; r++) {
          const row = table.content[r];
          if (!Array.isArray(row)) continue;
          const author = iAuthor >= 0 ? String(row[iAuthor] || '').trim() : '';
          const body = (iBody >= 0 ? String(row[iBody] || '').trim() : '') || (iTitle >= 0 ? String(row[iTitle] || '').trim() : '');
          if (!author || !body) continue;
          const comments = [];
          if (iComments >= 0) {
            String(row[iComments] || '').split(';').forEach(seg => {
              const m = seg.match(/^\s*([^：:]{1,40})[：:]([\s\S]*)$/);
              if (m && m[1].trim() && m[2].trim()) comments.push({ name: m[1].trim(), text: m[2].trim() });
            });
          }
          moments.push({
            id: 'square_' + r,
            author: author,
            text: body,
            comments: comments,
            timeLabel: iTime >= 0 ? String(row[iTime] || '').trim() : ''
          });
        }
        break;
      }
    } catch (e) { /* ignore */ }
    return moments;
  }

  // 玉子正文人物库（IndexedDB: yuzi-phone-body-dialogue）→ 角色头像
  async function yuziLoadBodyDialogueAvatars(cache) {
    try {
      const ctx = getTavernContext();
      const chars = ctx && Array.isArray(ctx.characters) ? ctx.characters : [];
      const idx = ctx && Number.isInteger(ctx.characterId) ? ctx.characterId : -1;
      const character = chars[idx] || null;
      const card = character && typeof character.avatar === 'string' ? character.avatar : '';
      if (!card) return;
      const db = await yuziOpenExistingDb(YUZI_BODY_DIALOGUE_DB);
      if (!db) return;
      try {
        if (!db.objectStoreNames.contains('people')) return;
        const people = await yuziIdbRequest(db.transaction(['people'], 'readonly').objectStore('people').index('card').getAll(card));
        for (const person of Array.isArray(people) ? people : []) {
          const name = person && String(person.name || '').trim();
          const mediaId = person && person.avatar && String(person.avatar.mediaId || '');
          if (!name || !mediaId) continue;
          let url = yuziMediaUrlCache.get(mediaId);
          if (!url && db.objectStoreNames.contains('media')) {
            try {
              const record = await yuziIdbRequest(db.transaction(['media'], 'readonly').objectStore('media').get(mediaId));
              if (record && record.blob instanceof Blob) url = URL.createObjectURL(record.blob);
            } catch (e) { url = ''; }
            if (url) yuziMediaUrlCache.set(mediaId, url);
          }
          if (url) cache.avatars[name] = url;
        }
      } finally {
        try { db.close(); } catch (e) { /* ignore */ }
      }
    } catch (e) { /* ignore */ }
  }

  async function ubLoadStatusbarStorage(force = false) {
    const now = Date.now();
    if (!force && ubStorageCache && now - (ubStorageCache.loadedAt || 0) < 4000) return ubStorageCache;
    if (ubStoragePromise) return ubStoragePromise;
    const gen = ++ubStorageGeneration;
    ubStoragePromise = (async () => {
      const cache = { hash24: 'yuzi', avatars: {}, portraits: {}, conversations: [], moments: [], loadedAt: Date.now() };
      try {
        const state = await yuziReadQQState();
        if (state) {
          const qq = yuziBuildQQCache(state, getTavernContext());
          cache.conversations = qq.conversations;
        }
      } catch (e) { /* ignore */ }
      try { cache.moments = yuziReadSquareMoments(); } catch (e) { cache.moments = []; }
      try { await yuziLoadBodyDialogueAvatars(cache); } catch (e) { /* ignore */ }
      cache.loadedAt = Date.now();
      __phoneDataCache__ = {
        conversations: cache.conversations,
        social: { moments: cache.moments },
        moments: cache.moments,
        loadedAt: cache.loadedAt
      };
      if (gen === ubStorageGeneration) ubStorageCache = cache;
      return cache;
    })();
    try { return await ubStoragePromise; } finally { ubStoragePromise = null; }
  }

  function getAvatarFromStatusbarStorage(name) {
    if (!name || !ubStorageCache) return '';
    const c = ubStorageCache;
    const av = ubPickFromMap(c.avatars, name);
    if (av) return av;
    return ubPickFromMap(c.portraits, name);
  }

