  // 读取神数据库中的《人物关系表》
  function getCharacterRelationsFromDB() {
    const api = getAutoCardAPI();
    if (!api) return [];
    try {
      const all = api.exportTableAsJson();
      if (!all || typeof all !== 'object') return [];
      for (const key of Object.keys(all)) {
        if (!key.startsWith('sheet_')) continue;
        const table = all[key];
        if (!table || table.name !== '人物关系表' || !Array.isArray(table.content)) continue;
        const rows = table.content;
        if (rows.length < 2) continue;
        const header = rows[0];
        if (!Array.isArray(header)) continue;
        const idxA = header.findIndex(h => typeof h === 'string' && (h.includes('人物A') || h.includes('角色A') || h.includes('主体')));
        const idxB = header.findIndex(h => typeof h === 'string' && (h.includes('人物B') || h.includes('角色B') || h.includes('客体')));
        const idxType = header.findIndex(h => typeof h === 'string' && (h.includes('关系类型') || h.includes('关系') || h.includes('定位')));
        const idxState = header.findIndex(h => typeof h === 'string' && (h.includes('当前状态') || h.includes('状态') || h.includes('描述') || h.includes('细节')));

        const relations = [];
        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (!Array.isArray(row)) continue;
          const a = idxA !== -1 && row[idxA] ? String(row[idxA]).trim() : '';
          const b = idxB !== -1 && row[idxB] ? String(row[idxB]).trim() : '';
          const type = idxType !== -1 && row[idxType] ? String(row[idxType]).trim() : '';
          const state = idxState !== -1 && row[idxState] ? String(row[idxState]).trim() : '';
          if (a && b) {
            relations.push({ a, b, type, state });
          }
        }
        return relations;
      }
      // 玉子恋爱特化参考：关系网络表（关联角色以分号分隔，两两成对）
      for (const key of Object.keys(all)) {
        if (!key.startsWith('sheet_')) continue;
        const table = all[key];
        if (!table || table.name !== '关系网络表' || !Array.isArray(table.content)) continue;
        const rows = table.content;
        if (rows.length < 2 || !Array.isArray(rows[0])) continue;
        const header = rows[0];
        const idxName = header.findIndex(h => typeof h === 'string' && (h.includes('网络名称') || h.includes('名称')));
        const idxLinked = header.findIndex(h => typeof h === 'string' && (h.includes('关联角色') || h.includes('关联人物')));
        const idxStance = header.findIndex(h => typeof h === 'string' && h.includes('立场'));
        const idxDesc = header.findIndex(h => typeof h === 'string' && (h.includes('关系说明') || h.includes('说明') || h.includes('影响')));
        if (idxLinked === -1) continue;
        const relations = [];
        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (!Array.isArray(row)) continue;
          const netName = idxName !== -1 && row[idxName] ? String(row[idxName]).trim() : '';
          const stance = idxStance !== -1 && row[idxStance] ? String(row[idxStance]).trim() : '';
          const desc = idxDesc !== -1 && row[idxDesc] ? String(row[idxDesc]).trim() : '';
          const type = [netName, stance].filter(Boolean).join('·') || '关系网络';
          const linked = String(row[idxLinked] || '').split(/[;；、,，\/|]/).map(s => s.trim()).filter(Boolean);
          for (let x = 0; x < linked.length; x++) {
            for (let y = x + 1; y < linked.length; y++) {
              relations.push({ a: linked[x], b: linked[y], type: type, state: desc });
            }
          }
        }
        if (relations.length) return relations;
      }
    } catch (e) { /* ignore */ }
    return [];
  }

  // 读取好友及真实立绘、身份标注（仅读取恋爱对象表和重要角色表）
  function loadContactsWithAvatars() {
    const api = getAutoCardAPI();
    if (!api) return { contacts: [], error: 'no_api' };
    // contacts / seen 必须在 try 外声明：catch 里要能访问（块级 const 在 catch 中不可见，
    // 旧代码异常时会二次抛出 ReferenceError，导致所有邀请界面直接炸掉）
    const contacts = [];
    const seen = new Set();
    try {
      const allTables = api.exportTableAsJson();
      if (!allTables || typeof allTables !== 'object') return { contacts: [], error: 'invalid' };
      const sheets = {};
      for (const key of Object.keys(allTables)) {
        if (key.startsWith('sheet_')) {
          const table = allTables[key];
          if (table && typeof table === 'object' && Array.isArray(table.content) && table.name) {
            sheets[table.name] = table;
          }
        }
      }
      const targetTables = ['恋爱对象表', '重要角色表'];

      const tableNamesToScan = Object.keys(sheets).filter(tName => {
        return targetTables.includes(tName);
      });

      for (const tableName of tableNamesToScan) {
        const table = sheets[tableName];
        if (!table) continue;
        const rows = table.content;
        if (!Array.isArray(rows)) continue;
        const header = rows[0];
        if (!Array.isArray(header)) continue;
        let nameIdx = header.findIndex(h => typeof h === 'string' && (h.includes('姓名') || h.includes('角色名') || h.includes('人物') || h.includes('名字') || h.includes('称呼') || h.includes('角色') || h.toLowerCase().includes('name')));
        if (nameIdx === -1) nameIdx = 0;
        const avatarIdx = header.findIndex(h => isAvatarHeader(h));

        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          if (!Array.isArray(row)) continue;
          const name = row[nameIdx];
          if (typeof name === 'string' && name.trim() && !seen.has(name.trim())) {
            const trimmedName = name.trim();
            seen.add(trimmedName);
            let avatar = (avatarIdx !== -1 && typeof row[avatarIdx] === 'string' && row[avatarIdx].trim())
              ? resolveAvatarUrl(row[avatarIdx].trim())
              : '';
            if (!avatar) {
              avatar = getCharacterAvatarByName(trimmedName);
            }

            const prof = getCharacterProfile(trimmedName);
            const idStr = prof?.identity || prof?.brief || '';
            contacts.push({ name: trimmedName, avatar: avatar, identity: idStr });
          }
        }
      }
      return { contacts, error: null };
    } catch (e) {
      return { contacts, error: 'exception' };
    }
  }

  // ========== 读取玉子手机 QQ 与广场信息 ==========
  // 数据来自 ubLoadStatusbarStorage 缓存的玉子手机数据：
  //   conversations ← QQ v2 IndexedDB（当前聊天作用域的私聊/群聊最近消息）
  //   moments       ← 小剧场「广场表」（动态流）
  function getPhoneSocialData() {
    const conversations = [];
    const moments = [];
    try {
      const cache = (ubStorageCache && typeof ubStorageCache === 'object')
        ? ubStorageCache
        : (__phoneDataCache__ && typeof __phoneDataCache__ === 'object' ? __phoneDataCache__ : null);
      if (cache) {
        const convs = Array.isArray(cache.conversations) ? cache.conversations : [];
        convs.forEach(c => {
          if (!c || !c.title) return;
          conversations.push({ title: c.title, text: c.text || '', members: c.members || [c.title], messages: c.messages || [] });
        });
        const mms = (cache.moments && Array.isArray(cache.moments))
          ? cache.moments
          : (cache.social && Array.isArray(cache.social.moments) ? cache.social.moments : []);
        mms.forEach(m => { if (m && m.author && m.text) moments.push(m); });
      }
    } catch (e) { /* ignore */ }
    return { conversations, moments };
  }
  // 获取角色与其他角色之间的具体关系、QQ、广场交集摘要
  function getInterPersonalContext(player, otherPlayers) {
    if (!player) return '';
    const allRelations = getCharacterRelationsFromDB();
    const phoneData = getPhoneSocialData();
    const lines = [];

    otherPlayers.forEach(op => {
      if (op.position === player.position) return;
      const relList = allRelations.filter(r => 
        (isNameMatch(r.a, player.name) && isNameMatch(r.b, op.name)) ||
        (isNameMatch(r.b, player.name) && isNameMatch(r.a, op.name))
      );

      let relDesc = '';
      if (relList.length > 0) {
        relDesc = relList.map(r => `${r.type}${r.state ? `(${r.state})` : ''}`).join('、');
      } else if (op.isUser) {
        const prof = getCharacterProfile(player.name);
        if (prof?.attitude) relDesc = prof.attitude;
      }

      let chatHint = '';
      const relevantConv = phoneData.conversations.find(c => 
        (c.title && isNameMatch(c.title, op.name)) ||
        (c.members && c.members.some(m => isNameMatch(m, op.name)))
      );
      if (relevantConv) {
        chatHint = relevantConv.text ? `最近QQ话题：“${relevantConv.text.slice(0, 35)}”` : '';
      }

      let momentHint = '';
      const relevantMoment = phoneData.moments.find(m => isNameMatch(m.author, op.name));
      if (relevantMoment) {
        momentHint = `最近广场发过：“${relevantMoment.text.slice(0, 30)}”`;
      }

      const tag = op.isUser ? '（玩家主角）' : '';
      const infoBits = [relDesc ? `【关系定位】：${relDesc}` : '', chatHint, momentHint].filter(Boolean).join('；');
      if (infoBits) {
        lines.push(`- 与 ${op.position}号位 ${op.name}${tag}：${infoBits}`);
      } else {
        lines.push(`- 与 ${op.position}号位 ${op.name}${tag}：熟人/同局好友，彼此熟悉各自性格。`);
      }
    });

    if (lines.length === 0) return '';
    return `\n【你与场上其他角色的人际关系与QQ/广场过往互动记录（角色间必须有鲜活互动，不能视作空气）】：\n${lines.join('\n')}\n`;
  }

