  //       余额不足最低游玩数量时无法开局。炸金花 / 德州扑克：每一次下注（底注/盲注/跟注/加注/比牌费）实时扣款、
  //       赢池与彩头实时入账，退出牌桌不再统一结算；斗地主：叫分后立即按 赌注×叫分 预扣本金，炸弹/春天
  //       倍数翻倍实时追加预扣，赢了实时回款；麻将：开局按赌注预扣本金、局终按倍数实时多退少补；21点：
  //       发牌主注/加倍/分牌/边注/保险实时扣款、每手结算实时入账。所有动账都会写入金币收支记录。
  const CHIP_GAME_NAMES = { zjh: '炸金花', blackjack: '21点', holdem: '德州扑克', mahjong: '麻将', doudizhu: '斗地主' };
  const ZJH_START_CHIPS = 300;       // （保留常量兼容旧调用；实际启动筹码已改为读取金币）
  const ZJH_MIN_CHIPS = 5;           // 炸金花底注（低于它不能开局）
  // 旧版单一门槛（保留作兜底：未传场次时使用）；实际门槛已改为按「赌场分级厅」的 minBuyIn 计算
  const TREASURY_MIN_PLAY = { zjh: 1000, blackjack: 1000, holdem: 1000 };

  // ========== 赌场分级厅（Table Limits · 参考澳门 / 拉斯维加斯：低 / 中 / VIP 三档） ==========
  // 玩家可在各游戏大厅切换场次：买入门槛、注码与封顶随场次变化（选好场次后底注 / 盲注自动生效）
  const CASINO_TIERS = {
    zjh: [
      { id: 'casual', name: '散客区', minBuyIn: 1000, ante: 200, raiseStep: 500, cap: 800, npcStack: 5000, desc: '底注 200 · 加注 500 · 封顶 800' },
      { id: 'standard', name: '中级厅', minBuyIn: 5000, ante: 1000, raiseStep: 2000, cap: 3000, npcStack: 25000, desc: '底注 1000 · 加注 2000 · 封顶 3000' },
      { id: 'vip', name: 'VIP豪客厅', minBuyIn: 10000, ante: 3000, raiseStep: 5000, cap: 8000, npcStack: 50000, desc: '底注 3000 · 加注 5000 · 封顶 8000' }
    ],
    blackjack: [
      { id: 'casual', name: '大众桌', minBuyIn: 1000, minBet: 100, maxBet: 10000, desc: '注码 100~10000' },
      { id: 'standard', name: '黄金桌', minBuyIn: 5000, minBet: 500, maxBet: 50000, desc: '注码 500~50000' },
      { id: 'vip', name: '黑钻VIP', minBuyIn: 10000, minBet: 1000, maxBet: 100000, desc: '注码 1000~100000' }
    ],
    holdem: [
      { id: 'micro', name: '微盲厅 500/1000', minBuyIn: 1000, sb: 500, bb: 1000, npcStack: 5000, desc: '盲注 500/1000' },
      { id: 'standard', name: '标准厅 2500/5000', minBuyIn: 5000, sb: 2500, bb: 5000, npcStack: 25000, desc: '盲注 2500/5000' },
      { id: 'high', name: '高额厅 5000/10000', minBuyIn: 10000, sb: 5000, bb: 10000, npcStack: 50000, desc: '盲注 5000/10000' }
    ]
  };
  function casinoTierList(gameKey) { return CASINO_TIERS[gameKey] || []; }
  function casinoTier(gameKey, tierId) {
    const list = casinoTierList(gameKey);
    for (const t of list) if (t.id === tierId) return t;
    return list[0] || null;
  }
  // 场次选择条（各游戏大厅通用；按钮 act = chip-tier）
  function casinoTierBarHTML(gameKey, currentId) {
    const list = casinoTierList(gameKey);
    if (!list.length) return '';
    const rows = list.map(t => {
      const on = t.id === currentId;
      return '<button data-ubp-act="chip-tier" data-casino-game="' + gameKey + '" data-casino-tier="' + t.id + '" class="ubp-btn" style="flex:1;min-width:0;padding:6px 4px;font-size:11px;border-radius:8px;' +
        (on ? 'background:#10B981;border:none;color:#fff;font-weight:700;' : 'background:var(--ubp-card-2);border:1px solid var(--ubp-line);') + '">' +
        escapeHtml(t.name) + '<div style="font-size:9.5px;opacity:' + (on ? '0.92' : '0.72') + ';margin-top:2px;">' + escapeHtml(t.desc) + '</div>' +
        '<div style="font-size:9.5px;opacity:' + (on ? '0.92' : '0.7') + ';margin-top:1px;">买入 ≥' + t.minBuyIn + '</div></button>';
    }).join('');
    return '<div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:9px 10px;margin-bottom:12px;border:1px solid var(--ubp-line);">' +
      '<div style="font-size:12.5px;font-weight:600;color:var(--ubp-text);margin-bottom:6px;">🎰 场次（Table Limits）</div>' +
      '<div style="display:flex;gap:6px;">' + rows + '</div></div>';
  }

  // 主角在这两个游戏的跨局筹码（null = 尚未加载，从钱包读取）
  let zjhBankroll = null;
  let thBankroll = null;

  // ---- 金币适配层：优先瑟瑟小金库（__ub_currency_host），否则使用玉子本地金币钱包 ----
  function treasuryHosts() {
    const list = [];
    const push = (h) => { try { if (h && list.indexOf(h) < 0) list.push(h); } catch (e) { /* ignore */ } };
    try { push(typeof window !== 'undefined' ? window : undefined); } catch (e) { /* ignore */ }
    try { push(globalThis); } catch (e) { /* ignore */ }
    try { if (window && window.parent && window.parent !== window) push(window.parent); } catch (e) { /* ignore */ }
    try { if (window && window.top && window.top !== window) push(window.top); } catch (e) { /* ignore */ }
    return list;
  }

  function loadYuziWalletBalance() {
    try {
      const raw = localStorage.getItem(YUZI_WALLET_KEY);
      if (raw !== null) {
        const n = Math.round(Number(JSON.parse(raw)));
        if (Number.isFinite(n)) return Math.max(0, n);
      }
    } catch (e) { /* ignore */ }
    try { localStorage.setItem(YUZI_WALLET_KEY, JSON.stringify(YUZI_WALLET_DEFAULT_BALANCE)); } catch (e) { /* ignore */ }
    return YUZI_WALLET_DEFAULT_BALANCE;
  }

  function saveYuziWalletBalance(n) {
    try { localStorage.setItem(YUZI_WALLET_KEY, JSON.stringify(Math.max(0, Math.round(Number(n) || 0)))); } catch (e) { /* ignore */ }
  }

  // 本地金币钱包：对外暴露与瑟瑟小金库一致的 snapshot()/adjust() 接口
  function createYuziWalletHost() {
    return {
      snapshot() {
        const balance = loadYuziWalletBalance();
        return {
          enabled: true,
          commonId: YUZI_WALLET_CURRENCY.id,
          currencies: [{ id: YUZI_WALLET_CURRENCY.id, name: YUZI_WALLET_CURRENCY.name }],
          balances: { [YUZI_WALLET_CURRENCY.id]: balance }
        };
      },
      adjust(id, delta /*, source, note */) {
        if (id && id !== YUZI_WALLET_CURRENCY.id) return false;
        const d = Math.round(Number(delta) || 0);
        if (!d) return true;
        saveYuziWalletBalance(loadYuziWalletBalance() + d);
        return true;
      }
    };
  }

  function getTreasuryHost() {
    for (const h of treasuryHosts()) {
      try {
        const host = h && h.__ub_currency_host;
        if (host && typeof host.snapshot === 'function') return host;
      } catch (e) { /* ignore */ }
    }
    return createYuziWalletHost();
  }

  // 读取金币：返回 { ok, host, id, name, balance, currencies, reason }
  function getTreasury() {
    const host = getTreasuryHost();
    if (!host) return { ok: false, host: null, id: null, name: '货币', balance: 0, currencies: [], reason: '未检测到金币（需先启用玉子手机的货币系统）' };
    let snap = null;
    try { snap = host.snapshot(); } catch (e) { snap = null; }
    if (!snap || !snap.enabled || !Array.isArray(snap.currencies) || !snap.currencies.length) {
      return { ok: false, host, id: null, name: '货币', balance: 0, currencies: [], reason: '金币还没有货币（请先在手机里获得货币）' };
    }
    const balances = snap.balances || {};
    const id = snap.commonId && balances[snap.commonId] !== undefined ? snap.commonId : snap.currencies[0].id;
    const cur = snap.currencies.find(c => c.id === id) || snap.currencies[0];
    const balance = Math.max(0, Math.round(Number(balances[id]) || 0));
    return { ok: true, host, id, name: cur.name || '货币', balance, currencies: snap.currencies, reason: '' };
  }
  function treasuryBalance() { const t = getTreasury(); return t.ok ? t.balance : 0; }
  // 结算：正数 = 赢得入账，负数 = 支出扣款；写入金币收支记录
  // 专属流水分类：game-buyin 赌场买入 / game-raise 赌场加注 / game-win 赌场赢钱 / game-lose 赌场输钱（未传时按收付方向）
  function treasuryAdjust(delta, note, source) {
    const t = getTreasury();
    if (!t.ok) return false;
    const d = Math.round(Number(delta) || 0);
    if (!d) return true;
    const src = (typeof source === 'string' && source) ? source : (d < 0 ? 'game-lose' : 'game-win');
    try { return !!t.host.adjust(t.id, d, src, String(note || '棋牌对局结算').slice(0, 80)); } catch (e) { return false; }
  }
  // 开局门槛检查：返回 { ok, min, t, msg }
  function treasuryPlayable(gameKey, minBuyIn) {
    const t = getTreasury();
    const min = (Number.isFinite(Number(minBuyIn)) && Number(minBuyIn) > 0) ? Math.round(Number(minBuyIn)) : (TREASURY_MIN_PLAY[gameKey] || 0);
    if (!t.ok) return { ok: false, min, t, msg: '💰 ' + (t.reason || '未检测到金币') };
    if (t.balance < min) return { ok: false, min, t, msg: '💰 金币「' + t.name + '」不足 ' + min + '，无法开局（当前 ' + t.balance + '）' };
    return { ok: true, min, t, msg: '' };
  }
  // ---- 实时动账（炸金花 / 德州扑克 / 斗地主）：主角每一笔下注/进账立即写入金币 ----
  // 说明：不再等退出牌桌时统一结算；isUser 为 false（机器人/角色）时不动金币。
  //       返回实际写入的金额（未写入成功返回 0），便于调用方（如斗地主预扣）跟踪“实际已扣金额”。
  function realtimeFlow(isUser, delta, note, source) {
    if (!isUser) return 0;
    const d = Math.round(Number(delta) || 0);
    if (!d) return 0;
    const ok = treasuryAdjust(d, note, source || (d < 0 ? 'game-lose' : 'game-win'));
    return ok ? d : 0;
  }

  function loadChipWallet() {
    const b = treasuryBalance();
    return { zjh: b, blackjack: b, holdem: b, init: { zjh: true, blackjack: true, holdem: true } };
  }
  function saveChipWallet() { return loadChipWallet(); } // 兼容旧调用：不再本地落盘
  function getChips(gameKey) { return treasuryBalance(); }
  function setChips(gameKey, n) {
    const target = Math.max(0, Math.round(Number(n) || 0));
    const delta = target - treasuryBalance();
    if (delta !== 0) treasuryAdjust(delta, (CHIP_GAME_NAMES[gameKey] || '棋牌') + ' · 对局结算');
    return treasuryBalance();
  }
  function addChips(gameKey, delta) {
    const d = Math.round(Number(delta) || 0);
    if (d) treasuryAdjust(d, (CHIP_GAME_NAMES[gameKey] || '棋牌') + ' · 对局结算');
    return treasuryBalance();
  }
  // 兼容旧调用：不再发放启动筹码，直接返回金币余额
  function ensureStartChips(gameKey, startChips) { return treasuryBalance(); }

  // 当前该游戏「正在使用」的筹码：优先取对局内实时余额，其次取金币
  function chipBankOf(gameKey) {
    if (gameKey === 'zjh') {
      if (zjhBankroll === null || !Number.isFinite(zjhBankroll)) zjhBankroll = ensureStartChips('zjh', ZJH_START_CHIPS);
      return zjhBankroll;
    }
    if (gameKey === 'holdem') {
      if (thBankroll === null || !Number.isFinite(thBankroll)) thBankroll = ensureStartChips('holdem', TH_START_CHIPS);
      return thBankroll;
    }
    if (bjGame && bjGame.phase !== 'sessionEnd' && bjGame.phase !== 'idle') return bjGame.chips;
    return ensureStartChips('blackjack', loadBjConfig().chips);
  }

  // 金币变化后同步到内存里的对局余额
  function syncChipBalance(gameKey) {
    const v = treasuryBalance();
    if (gameKey === 'zjh') zjhBankroll = v;
    else if (gameKey === 'holdem') thBankroll = v;
    else if (gameKey === 'blackjack') {
      if (bjGame && bjGame.phase !== 'sessionEnd' && bjGame.phase !== 'idle') bjGame.chips = v;
    }
    return v;
  }

  function chipsLabelHTML(gameKey, extraStyle) {
    const t = getTreasury();
    return '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:rgba(16,185,129,0.14);border:1px solid rgba(16,185,129,0.5);font-size:11.5px;font-weight:600;color:#10B981;' + (extraStyle || '') + '">💰 ' + (t.ok ? escapeHtml(t.name) + ' ' + t.balance : '金币未开启') + '</span>';
  }

  // 大厅里的「金币」卡片（读取金币余额 · 已移除积分兑换入口）
  function chipCardHTML(gameKey, minChips, tip) {
    const t = getTreasury();
    const min = Math.max(Number(minChips) || 0, TREASURY_MIN_PLAY[gameKey] || 0);
    const bank = t.balance;
    const ok = t.ok && bank >= min;
    const gname = CHIP_GAME_NAMES[gameKey] || '游戏';
    const flowNote = (gameKey === 'zjh' || gameKey === 'holdem')
      ? '对局保留日志与对话；下注（底注/盲注、跟注、加注、比牌费）实时从金币扣款、赢池实时入账，退出牌桌不再统一结算'
      : (gameKey === 'doudizhu'
        ? '对局保留日志与对话；叫分后按 赌注×叫分 实时预扣本金，炸弹/春天倍数翻倍实时追加，赢了实时回款'
        : (gameKey === 'mahjong'
          ? '对局保留日志与对话；开局按 赌注 实时预扣本金（买入底注），局终按 赌注×倍数 实时多退少补、流局退还'
          : (gameKey === 'blackjack'
            ? '对局保留日志与对话；发牌注额/边注/保险实时扣款、每手结算实时入账，退出牌桌不再统一结算'
            : '对局保留日志与对话，点【退出】时统一结算回金币（不再使用积分兑换筹码）')));
    return '' +
      '<div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:10px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;">' +
      '<span style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">💰 金币货币</span>' +
      '<span style="font-size:16px;font-weight:800;color:' + (ok ? '#10B981' : '#EF4444') + ';">' + (t.ok ? bank : '—') + '</span></div>' +
      '<div style="font-size:11px;color:var(--ubp-text-3);margin-top:4px;line-height:1.5;">' +
      (tip ? tip + ' · ' : '') + escapeHtml(gname) + '最低游玩 ' + min + (t.ok ? ' ' + escapeHtml(t.name) : ' 货币') + ' · ' + flowNote + '</div>' +
      (t.ok
        ? (ok ? '' : '<div style="font-size:11.5px;color:#EF4444;margin-top:6px;">⚠️ 金币不足 ' + min + '，无法开局：请先通过剧情 / 手机转账获得货币</div>')
        : '<div style="font-size:11.5px;color:#EF4444;margin-top:6px;">⚠️ ' + escapeHtml(t.reason || '未检测到金币') + '</div>') +
      '</div>';
  }

  // 金币面板（三个游戏通用 · 原「积分兑换筹码」已移除，仅展示余额与说明）
  function renderChipExchange(gameKey, onDone, minOverride) {
    const old = sheet && sheet.querySelector('.chip-exchange-overlay');
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.className = 'chip-exchange-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:72;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    const t = getTreasury();
    const gname = CHIP_GAME_NAMES[gameKey] || '游戏';
    const min = (Number(minOverride) > 0) ? Math.round(Number(minOverride)) : (TREASURY_MIN_PLAY[gameKey] || 0);
    const ok = t.ok && t.balance >= min;
    const curList = (t.ok && t.currencies.length)
      ? t.currencies.map(c => escapeHtml(c.name) + (t.id === c.id ? ' ' + t.balance : '')).join(' · ')
      : '—';
    const flowDesc = (gameKey === 'zjh' || gameKey === 'holdem')
      ? '已改为直接使用玉子手机<b>金币</b>货币游玩：每次下注（底注/盲注、跟注、加注、比牌费）<b>实时扣款</b>、赢池与彩头喜钱<b>实时入账</b>；退出牌桌不再统一结算（对局记录照常写入）；<b>不再提供积分兑换筹码</b>。'
      : (gameKey === 'doudizhu'
        ? '已改为直接使用玉子手机<b>金币</b>货币游玩：叫分确定地主后立即按 赌注×叫分 <b>实时预扣本金</b>，每出炸弹/王炸、春天倍数翻倍时实时追加预扣；赢了实时回款（返还预扣本金+赢钱），输了预扣款即为输款；中途弃局退还预扣；<b>不再提供积分兑换筹码</b>。'
        : (gameKey === 'mahjong'
          ? '已改为直接使用玉子手机<b>金币</b>货币游玩：每局开局立即按 赌注 <b>实时预扣本金</b>（买入底注），局终按 赌注×倍数 <b>实时多退少补</b>（赢了返还本金+赢钱、输了预扣款即输款并补扣不足部分、流局或与你无关退还预扣）；<b>不再提供积分兑换筹码</b>。'
          : (gameKey === 'blackjack'
            ? '已改为直接使用玉子手机<b>金币</b>货币游玩：每次发牌主注、跟加倍/分牌/边注/保险都<b>实时扣款</b>，每手/边注/保险结算<b>实时入账</b>；退出牌桌不再统一结算（对局记录照常写入）；<b>不再提供积分兑换筹码</b>。'
            : '已改为直接使用玉子手机<b>金币</b>货币游玩：货币通过剧情 / 手机转账等获得；整场输赢在退出牌桌时统一结算并写入金币收支记录；<b>不再提供积分兑换筹码</b>。')));
    ov.innerHTML =
      '<div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:16px 14px;width:100%;max-width:310px;box-shadow:0 10px 28px rgba(0,0,0,0.55);">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">' +
      '<span style="font-size:15px;font-weight:700;color:var(--ubp-text);">💰 ' + escapeHtml(gname) + ' · 金币</span>' +
      '<button data-chip-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
      '<div style="display:flex;gap:6px;margin-bottom:9px;">' +
      '<div style="flex:1;background:var(--ubp-card-2);border-radius:9px;padding:7px 9px;text-align:center;">' +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);">金币余额</div>' +
      '<div style="font-size:16px;font-weight:800;color:' + (ok ? '#10B981' : '#EF4444') + ';">' + (t.ok ? t.balance : '—') + '</div></div>' +
      '<div style="flex:1;background:var(--ubp-card-2);border-radius:9px;padding:7px 9px;text-align:center;">' +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);">最低游玩</div>' +
      '<div style="font-size:16px;font-weight:800;color:#F59E0B;">' + min + '</div></div></div>' +
      '<div style="font-size:11.5px;color:var(--ubp-text-2);line-height:1.7;margin-bottom:10px;">' +
      (t.ok
        ? ('货币：<b style="color:#10B981;">' + escapeHtml(t.name) + '</b>（' + curList + '）<br>')
        : ('⚠️ ' + escapeHtml(t.reason || '未检测到金币') + '<br>')) +
      flowDesc + '</div>' +
      '<div style="display:flex;gap:6px;">' +
      '<button data-chip-act="close" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#10B981;border:none;">知道了</button>' +
      '</div></div>';
    ov.querySelectorAll('[data-chip-act]').forEach(el => {
      el.addEventListener('click', () => {
        ov.remove();
        if (typeof onDone === 'function') onDone();
      });
    });
    sheet.appendChild(ov);
  }

  // 内置机器人 / 默认对手的名字（非邀请角色）
  function isBuiltinPlayerName(name) {
