  const SLOT_GAME_NAMES = { gomoku: '五子棋', xiangqi: '象棋', jungle: '斗兽棋', chess: '国际象棋', shogi: '将棋', battleship: '海战棋', go: '围棋', luzhanqi: '军棋', othello: '黑白棋', rps: '石头剪刀布', ttt: '井字棋', minesweeper: '扫雷', blackjack: '21点', doudizhu: '斗地主', liar: '欺诈酒馆', ludo: '飞行棋', richman: '大富翁', mahjong: '麻将', zjh: '炸金花', holdem: '德州扑克', uno: 'UNO', werewolf: '狼人杀', spy: '谁是卧底', murder: '剧本杀', tetris: '俄罗斯方块' };

  function normalizeHistoryLimits(store) {
    const out = {};
    for (const key of Object.keys(store || {})) {
      const list = Array.isArray(store[key]) ? store[key] : [];
      if (!list.length) continue;
      const max = 3;
      out[key] = list.slice(-max);
    }
    return out;
  }

  // ========== 通用对局历史存取（每种游戏单独留存最近 3 场） ==========
  function loadGenericMatchHistory() {
    try {
      const raw = localStorage.getItem(GENERIC_MATCH_HISTORY_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        // 新版：带版本号 { v:2, g:{ 游戏类型: [记录] } }（避免与 chess 等游戏类型键冲突导致误迁移）
        if (parsed && parsed.v === 2 && parsed.g && typeof parsed.g === 'object') {
          return normalizeHistoryLimits(parsed.g);
        }
        if (Array.isArray(parsed)) {
          // 兼容旧版扁平数组
          const store = {};
          parsed.forEach(m => { if (m && m.gameType) { (store[m.gameType] = store[m.gameType] || []).push(m); } });
          return normalizeHistoryLimits(store);
        }
        if (parsed && typeof parsed === 'object') {
          // 兼容旧版 { chess:[], deduction:[] }（分类值，非游戏类型）
          const store = {};
          (Array.isArray(parsed.chess) ? parsed.chess : []).forEach(m => { if (m && m.gameType) { (store[m.gameType] = store[m.gameType] || []).push(m); } });
          (Array.isArray(parsed.deduction) ? parsed.deduction : []).forEach(m => { if (m && m.gameType) { (store[m.gameType] = store[m.gameType] || []).push(m); } });
          return normalizeHistoryLimits(store);
        }
      }
    } catch (e) { /* ignore */ }
    return {};
  }

  function saveGenericMatchHistory(store) {
    try {
      localStorage.setItem(GENERIC_MATCH_HISTORY_KEY, JSON.stringify({ v: 2, g: normalizeHistoryLimits(store) }));
    } catch (e) { /* ignore */ }
  }

  // 记录一场对局（按游戏类型单独留存最近 3 场）
  function recordGenericMatch(match) {
    if (!match || !match.gameType) return;
    const store = loadGenericMatchHistory();
    const max = 3;
    const list = Array.isArray(store[match.gameType]) ? store[match.gameType] : [];
    list.push({ ...match, timestamp: match.timestamp || Date.now() });
    while (list.length > max) list.shift();
    store[match.gameType] = list;
    saveGenericMatchHistory(store);
    if (loadConfig().worldBookLink !== false) {
      syncWorldBookEntry();
    }
  }

  // 回填/更新某场对局的附加字段（高光播报、赛后复盘、广场等）
  function updateGenericMatchRecord(gameType, recordId, patch) {
    if (!gameType || !patch) return false;
    const store = loadGenericMatchHistory();
    const list = Array.isArray(store[gameType]) ? store[gameType] : [];
    let rec = null;
    if (recordId) rec = list.find(m => m && m.id === recordId) || null;
    if (!rec) rec = list[list.length - 1] || null;
    if (!rec) return false;
    Object.assign(rec, patch);
    store[gameType] = list;
    saveGenericMatchHistory(store);
    if (loadConfig().worldBookLink !== false) {
      syncWorldBookEntry();
    }
    return true;
  }

  // 将回放日志格式化为可读文本（供世界书绿灯条目 / 对局记录界面读取）
  function formatReplayAsText(entries) {
    if (!Array.isArray(entries) || !entries.length) return '';
    const lines = [];
    for (const e of entries) {
      if (e == null) continue;
      const text = typeof e === 'object' ? (e.text || '') : String(e);
      const clean = String(text).replace(/<[^>]+>/g, '').replace(/\n+/g, ' ').trim();
      if (clean) lines.push(clean);
    }
    return lines.slice(-80).join('\n');
  }

  function getGameTypeDisplayName(gameType) {
    const typeNameMap = { gomoku: '五子棋', xiangqi: '象棋', jungle: '斗兽棋', chess: '国际象棋', shogi: '将棋', battleship: '海战棋', werewolf: '狼人杀', spy: '谁是卧底', rps: '石头剪刀布', murder: '剧本杀', doudizhu: '斗地主', liar: '欺诈酒馆', mahjong: '麻将', zjh: '炸金花', holdem: '德州扑克', uno: 'UNO', go: '围棋', luzhanqi: '军棋', othello: '黑白棋', minesweeper: '扫雷', blackjack: '21点', tetris: '俄罗斯方块', ttt: '井字棋', ludo: '飞行棋', richman: '大富翁' };
    return typeNameMap[gameType] || gameType || '桌游';
  }

  function listKnownGameTypes(store) {
    const keys = Object.keys(store || {}).filter(k => (store[k] || []).length > 0);
    const known = GAME_TYPE_ORDER.filter(k => keys.includes(k));
    const unknown = keys.filter(k => !GAME_TYPE_ORDER.includes(k)).sort();
    return known.concat(unknown);
  }

  // 生成世界书条目正文（供 AI 读取，只陈述胜负事实，不含情绪）
  // 参考玉子手机「消息记录注入世界书」：保留最近记录 + 体积上限，避免把提示词撑爆。
  // 狼人杀 / 谁是卧底：只注入「结果 + 详情」，不再注入全景复盘（回放仅供界面查看）
  const WORLD_BOOK_NO_REPLAY_TYPES = { werewolf: true, spy: true };
  function buildWorldBookContent() {
    const store = loadGenericMatchHistory();
    const types = listKnownGameTypes(store);
    if (!types.length) return '';
    const MAX_LEN = 4000;
    const lines = [];
    for (const gameType of types) {
      const list = store[gameType] || [];
      const title = getGameTypeDisplayName(gameType);
      list.forEach((m, i) => {
        const when = m.timestamp ? `（${new Date(m.timestamp).toLocaleString('zh-CN', { hour12: false })}）` : '';
        const result = m.result || '';
        const detail = m.detail || '';
        const points = (typeof m.pointsDelta === 'number' && m.pointsDelta !== 0)
          ? `\n  积分：${m.pointsDelta > 0 ? '+' : ''}${m.pointsDelta}${typeof m.pointsTotal === 'number' ? '（累计 ' + m.pointsTotal + '）' : ''}`
          : '';
        const replayText = (!WORLD_BOOK_NO_REPLAY_TYPES[gameType] && m.replay) ? String(m.replay).replace(/<[^>]+>/g, '').replace(/\n+/g, ' ').trim() : '';
        const replay = replayText ? `\n  对局回放：${replayText.slice(0, 600)}${replayText.length > 600 ? '…' : ''}` : '';
        lines.push(`【${title}第${i + 1}场】${result}${when}${detail ? '\n  ' + detail : ''}${points}${replay}`);
      });
    }
    let text = `以下为主角最近参与的小游戏对局胜负记录（由玉子手机游戏系统自动记录，仅陈述客观结果，情感与反应由 AI 依据角色人设自行生成）：\n${lines.join('\n')}`;
    if (text.length > MAX_LEN) text = text.slice(0, MAX_LEN) + '\n…（更多历史对局详情请查看玉子手机游戏【对局记录】）';
    return text;
  }

  // 世界书条目结构（新版 SillyTavern：strategy / position / recursion 对象 + 兼容旧字段）
  function buildWorldBookEntry() {
    const content = buildWorldBookContent();
    const enabled = !!content;
    const strategies = { type: 'constant', keys: WORLD_BOOK_KEYWORDS.slice() };
    const position = { type: 'at_depth', depth: 0, role: 'system', order: 100 };
    const recursion = { prevent_incoming: true, prevent_outgoing: true, delay_until: null };
    return {
      uid: WORLD_BOOK_ENTRY_UID,
      name: WORLD_BOOK_ENTRY_NAME,
      comment: WORLD_BOOK_ENTRY_COMMENT,
      enabled: enabled,
      content: content,
      strategy: strategies,
      position: position,
      recursion: recursion,
      addMemo: true,
      triggers: [],
      // 兼容旧版字段
      key: WORLD_BOOK_KEYWORDS,
      keys: WORLD_BOOK_KEYWORDS.slice(),
      secondary_keys: [],
      constant: true,
      selective: false,
      disabled: !enabled,
      order: 100,
      disable: !enabled,
      exclude_recursion: false,
      prevent_recursion: false,
      delay_until_recursion: false,
      probability: 100,
      useProbability: true,
      depth: 4,
      group: '对局记录',
      group_override: false,
      group_weight: 100,
      global: false,
      caseSensitive: false,
      automation_id: '',
      role: 'system'
    };
  }

  // 获取当前激活角色名（多来源兜底）
  function getActiveCharacterName() {
    try {
      const sts = [window.SillyTavern, window.parent?.SillyTavern, window.TavernHelper?.SillyTavern, window.parent?.TavernHelper?.SillyTavern];
      for (const st of sts) {
        if (!st) continue;
        try {
          if (typeof st.name2 === 'function') { const n = st.name2(); if (n && n !== 'unified-statusbar') return n; }
          else if (typeof st.name2 === 'string' && st.name2 && st.name2 !== 'unified-statusbar') return st.name2;
        } catch (e) { /* ignore */ }
      }
      const ctx = getTavernContext();
      if (ctx) {
        if (typeof ctx.name2 === 'string' && ctx.name2) return ctx.name2;
        if (ctx.name2 && typeof ctx.name2 === 'function') { const n = ctx.name2(); if (n) return n; }
        if (Array.isArray(ctx.characters) && ctx.characters.length) {
          const cid = ctx.characterId;
          if ((typeof cid === 'number' || /^\d+$/.test(String(cid))) && Number(cid) >= 0 && Number(cid) < ctx.characters.length) {
            const c = ctx.characters[Number(cid)];
            if (c && typeof c.name === 'string') return c.name;
            if (c && typeof c.data?.name === 'string') return c.data.name;
          }
          const c0 = ctx.characters[0];
          if (c0 && typeof c0.name === 'string') return c0.name;
          if (c0 && typeof c0.data?.name === 'string') return c0.data.name;
        }
      }
    } catch (e) { /* ignore */ }
    return '';
  }

  // 定位/读取当前角色卡 (SillyTavern)
  function getCurrentCharacter() {
    try {
      const ctx = getTavernContext();
      if (!ctx) return { charData: null, ctx: null };
      const chars = Array.isArray(ctx.characters) ? ctx.characters : [];
      if (!chars.length) return { charData: null, ctx: null };

      let charData = null;
      const cid = ctx.characterId;
      if (typeof cid === 'number' || /^\d+$/.test(String(cid))) {
        const idx = Number(cid);
        if (idx >= 0 && idx < chars.length) charData = chars[idx];
      }
      if (!charData && (typeof cid === 'string' && cid)) {
        charData = chars.find(c => c && (c.name === cid || c.data?.name === cid));
      }
      if (!charData) {
        const nm = getActiveCharacterName();
        if (nm) charData = chars.find(c => c && (c.name === nm || c.data?.name === nm));
      }
      if (!charData) charData = chars[0] || null;

      return { charData, ctx };
    } catch (e) {
      return { charData: null, ctx: null };
    }
  }

  // ========== 参考玉子手机「消息记录注入世界书」：把对局胜负详情写入角色主世界书 ==========
  // 玉子手机是"读角色主世界书 → 有则 updateWorldbookWith / 无则 createWorldbookEntries"，
  // 这里用同一套酒馆助手接口写一条 [玉子手机游戏]对局记录，清空时 deleteWorldbookEntries 硬删。
  const GAME_WB_ENTRY_NAME = '[玉子手机游戏]对局记录';

  function getTavernHelperApi() {
    try {
      const cands = [window.TavernHelper, window.parent?.TavernHelper, window.top?.TavernHelper];
      for (const t of cands) {
        if (!t) continue;
        if (typeof t.getCharWorldbookNames === 'function' && typeof t.getWorldbook === 'function'
          && typeof t.createWorldbookEntries === 'function' && typeof t.updateWorldbookWith === 'function') return t;
      }
    } catch (e) { /* ignore */ }
    return null;
  }

  async function syncWorldBookEntryViaHelper(content) {
    const th = getTavernHelperApi();
    if (!th) return false;
    try {
      const names = th.getCharWorldbookNames('current');
      const book = (names && typeof names.primary === 'string' && names.primary) ? names.primary : '';
      if (!book) return false; // 角色未绑定主世界书：跳过（角色卡 character_book 通道仍然生效）
      const entries = await th.getWorldbook(book);
      if (!Array.isArray(entries)) return false;
      const found = entries.find(e => String(e?.name ?? e?.comment ?? '') === GAME_WB_ENTRY_NAME);
      if (!content) {
        if (found && typeof th.deleteWorldbookEntries === 'function') {
          await th.deleteWorldbookEntries(book, e => String(e?.name ?? e?.comment ?? '') === GAME_WB_ENTRY_NAME);
        }
        return true;
      }
      if (found) {
        if (String(found.content ?? '') !== content) {
          await th.updateWorldbookWith(book, list => (Array.isArray(list) ? list : []).map(e => String(e?.name ?? e?.comment ?? '') === GAME_WB_ENTRY_NAME ? { ...e, content: content } : e));
        }
        return true;
      }
      await th.createWorldbookEntries(book, [{
        name: GAME_WB_ENTRY_NAME,
        enabled: true,
        strategy: { type: 'constant', keys: WORLD_BOOK_KEYWORDS.slice(), keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
        position: { type: 'at_depth', role: 'system', depth: 0, order: 101 },
        recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
        content: content
      }], { render: 'immediate' });
      return true;
    } catch (e) {
      console.warn('[玉子游戏扩展] 酒馆助手世界书注入失败（不影响角色卡通道）:', e);
      return false;
    }
  }

  // 写回当前角色卡世界书绿灯条目（持久化 + 运行时 worldInfo 立即注入）
  async function syncWorldBookEntry() {
    const cfg = loadConfig();
    if (cfg.worldBookLink === false) { removeWorldBookEntry(); return; }
    const { charData, ctx } = getCurrentCharacter();
    const entry = buildWorldBookEntry();
    const contentEmpty = !entry.content;

    if (charData) {
      try {
        const book = charData.data && typeof charData.data === 'object' ? charData.data : {};
        if (!book.character_book || typeof book.character_book !== 'object') {
          book.character_book = { entries: [], extensions: {} };
        }
        if (!Array.isArray(book.character_book.entries)) book.character_book.entries = [];

        const idx = book.character_book.entries.findIndex(e => e && (e.comment === WORLD_BOOK_ENTRY_COMMENT || e.uid === WORLD_BOOK_ENTRY_UID));
        if (idx === -1) {
          if (!contentEmpty) book.character_book.entries.push(entry);
        } else {
          if (contentEmpty) book.character_book.entries.splice(idx, 1);
          else book.character_book.entries[idx] = entry;
        }
      } catch (e) {
        console.warn('[玉子游戏扩展] 写入角色卡 character_book 失败:', e);
      }
    }

    try {
      const charName = getActiveCharacterName();
      if (charName) {
        if (!ctx.worldInfo || typeof ctx.worldInfo !== 'object') ctx.worldInfo = {};
        if (!ctx.worldInfo[charName] || typeof ctx.worldInfo[charName] !== 'object') {
          ctx.worldInfo[charName] = { entries: {}, theirBias: [], mainBias: [] };
        }
        if (!ctx.worldInfo[charName].entries) ctx.worldInfo[charName].entries = {};
        if (contentEmpty) {
          delete ctx.worldInfo[charName].entries[String(WORLD_BOOK_ENTRY_UID)];
        } else {
          ctx.worldInfo[charName].entries[String(WORLD_BOOK_ENTRY_UID)] = entry;
        }
      }
    } catch (e) {
      console.warn('[玉子游戏扩展] 运行时 worldInfo 注入失败:', e);
    }

    try {
      const sts = [window.SillyTavern, window.parent?.SillyTavern, window.TavernHelper?.SillyTavern, window.parent?.TavernHelper?.SillyTavern];
      for (const st of sts) {
        if (!st) continue;
        try {
          if (typeof st.saveCharacterDebounced === 'function') { st.saveCharacterDebounced(); break; }
        } catch (e) { /* ignore */ }
        try {
          if (typeof st.saveCharacter === 'function') { st.saveCharacter(); break; }
        } catch (e) { /* ignore */ }
      }
    } catch (e) { /* ignore */ }

    // 同步写入角色主世界书（与玉子手机「消息记录注入世界书」同一套接口）
    try { syncWorldBookEntryViaHelper(entry.content || ''); } catch (e) { /* ignore */ }
  }

  function removeWorldBookEntry() {
    try {
      const { charData, ctx } = getCurrentCharacter();
      if (charData && charData.data && charData.data.character_book && Array.isArray(charData.data.character_book.entries)) {
        const entries = charData.data.character_book.entries;
        let idx = entries.findIndex(e => e && (e.comment === WORLD_BOOK_ENTRY_COMMENT || e.uid === WORLD_BOOK_ENTRY_UID));
        while (idx !== -1) {
          entries.splice(idx, 1);
          idx = entries.findIndex(e => e && (e.comment === WORLD_BOOK_ENTRY_COMMENT || e.uid === WORLD_BOOK_ENTRY_UID));
        }
      }
      if (ctx && ctx.worldInfo) {
        const nm = getActiveCharacterName();
        if (nm && ctx.worldInfo[nm] && ctx.worldInfo[nm].entries) {
          delete ctx.worldInfo[nm].entries[String(WORLD_BOOK_ENTRY_UID)];
        }
      }
      const st = window.SillyTavern || window.parent?.SillyTavern;
      if (st && typeof st.saveCharacterDebounced === 'function') st.saveCharacterDebounced();
    } catch (e) { /* ignore */ }
    // 同步移除角色主世界书里的对局记录条目
    try { syncWorldBookEntryViaHelper(''); } catch (e) { /* ignore */ }
  }

  // ========== 对局联动写入层：玉子手机 QQ 消息 + 小剧场广场表动态 ==========
  // 原版直接改写瑟瑟小手机的 usb_phone_*.json；玉子手机的 QQ 会话存储在 IndexedDB
  // 「yuzi-phone-qq-v2」的 state.root.scopes[scopeId] 中（私聊/群聊消息 + 人物表）。
  // 这里只做两点：① 追写当前聊天作用域内已有私聊的文本消息；② 新增广场动态行（神·数据库）。
  // 不新建联系人、不覆盖其它字段；写入失败时静默跳过，不影响对局本身。

  function yuziMakeMessageId() {
    return 'message_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10);
  }

  function yuziFindQQPersonByName(scope, name) {
    try {
      const people = scope && scope.people && typeof scope.people === 'object' ? scope.people : {};
      for (const person of Object.values(people)) {
        if (!person) continue;
        const formal = String(person.formalName || '').trim();
        const nick = String(person.nickname || '').trim();
        if ((formal && isNameMatch(formal, name)) || (nick && isNameMatch(nick, name))) return person;
      }
    } catch (e) { /* ignore */ }
    return null;
  }

  function yuziFindQQPrivateConversation(scope, personId) {
    try {
      const convs = scope && scope.conversations && typeof scope.conversations === 'object' ? scope.conversations : {};
      for (const conv of Object.values(convs)) {
        if (!conv) continue;
        if (conv.kind !== 'private' || conv.assistantCharacterId) continue;
        if (conv.status && conv.status !== 'active' && conv.status !== 'contact') continue;
        if (conv.personId && conv.personId === personId) return conv;
      }
    } catch (e) { /* ignore */ }
    return null;
  }

  async function yuziAppendQQMessages(characterName, texts, isUser = false) {
    const list = (Array.isArray(texts) ? texts : []).map(t => String(t || '').trim()).filter(Boolean);
    if (!characterName || !list.length) return false;
    const state = await yuziReadQQState();
    if (!state) return false;
    const scope = yuziPickQQScope(state, getTavernContext());
    if (!scope) return false;
    const person = yuziFindQQPersonByName(scope, characterName);
    if (!person || !person.personId) return false;
    const conv = yuziFindQQPrivateConversation(scope, person.personId);
    if (!conv || !conv.conversationId) return false;
    if (!scope.messages || typeof scope.messages !== 'object') scope.messages = {};
    const storyTime = getStoryTimeText();
    let sequence = Number(conv.nextSequence || 1);
    for (const text of list) {
      const messageId = yuziMakeMessageId();
      scope.messages[messageId] = {
        messageId: messageId,
        scopeId: scope.scopeId || conv.scopeId || '',
        conversationId: conv.conversationId,
        sequence: sequence,
        senderId: isUser ? YUZI_QQ_SELF_ID : person.personId,
        senderType: isUser ? 'self' : 'person',
        senderName: isUser ? '用户' : String(person.formalName || characterName),
        senderAvatarAssetId: isUser ? '' : String(person.avatarAssetId || ''),
        type: 'text',
        content: text,
        storyTime: storyTime || '',
        quoteMessageId: '',
        mentionIds: [],
        mentionAll: false,
        transfer: null,
        stickerId: '',
        assetId: '',
        generatedImagePath: '',
        generatedAt: 0,
        selectedForInjection: false
      };
      conv.lastMessageId = messageId;
      conv.lastSequence = sequence;
      conv.nextSequence = sequence + 1;
      conv.hiddenFromMessages = false;
      if (!isUser) conv.unreadCount = Math.max(0, Number(conv.unreadCount) || 0) + 1;
      sequence += 1;
    }
    const db = await yuziOpenExistingDb(YUZI_QQ_DB_NAME);
    if (!db) return false;
    try {
      if (!db.objectStoreNames.contains(YUZI_QQ_DB_STORE)) return false;
      await new Promise((resolve, reject) => {
        const tx = db.transaction([YUZI_QQ_DB_STORE], 'readwrite');
        tx.objectStore(YUZI_QQ_DB_STORE).put({ id: YUZI_QQ_DB_KEY, value: state });
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error || new Error('QQ 状态写入失败'));
        tx.onabort = () => reject(tx.error || new Error('QQ 状态写入中止'));
      });
      return true;
    } catch (e) {
      console.warn('[玉子游戏扩展] 写入 QQ 消息失败:', e);
      return false;
    } finally {
      try { db.close(); } catch (e) { /* ignore */ }
    }
  }

  // 兼容原QQ写入接口：单条 / 批量
  async function writeWechatMessage(characterName, messageText, isUser = false) {
    return await yuziAppendQQMessages(characterName, [messageText], isUser);
  }
  async function writeWechatMessagesVerified(characterName, texts, isUser = false) {
    return await yuziAppendQQMessages(characterName, texts, isUser);
  }

  // 构造一条广场动态数据结构（字段对齐广场表）
  function buildPhoneMoment(author, text, comments) {
    return {
      id: 's_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8),
      author: String(author || '').slice(0, 40),
      text: String(text || '').slice(0, 400),
      imageDesc: 'none',
      likes: [],
      comments: (Array.isArray(comments) ? comments : [])
        .filter(c => c && c.name && c.text)
        .map(c => ({ name: String(c.name).slice(0, 40), text: String(c.text).slice(0, 200) }))
        .slice(0, 12),
      timeLabel: '刚刚',
      createdAt: Date.now()
    };
  }

  // 把动态写入玉子手机小剧场「广场表」（神·数据库 insertRow，按帖子ID去重）
  async function writeMomentToPhone(moment) {
    if (!moment || !moment.author || !moment.text) return false;
    try {
      const api = getAutoCardAPI();
      if (!api || typeof api.insertRow !== 'function') return false;
      const all = api.exportTableAsJson();
      if (!all || typeof all !== 'object') return false;
      let tableName = '';
      let table = null;
      for (const key of Object.keys(all)) {
        if (!key.startsWith('sheet_')) continue;
        const candidate = all[key];
        if (!candidate || !Array.isArray(candidate.content) || !Array.isArray(candidate.content[0])) continue;
        if (String(candidate.name || '') === '广场表' || key === 'sheet_square_posts') {
          tableName = String(candidate.name || '广场表');
          table = candidate;
          break;
        }
      }
      if (!tableName || !table) return false;
      const header = table.content[0];
      const postId = 'game_' + String(moment.id || Date.now()).slice(0, 60);
      const col = (label) => header.findIndex(h => String(h || '') === label);
      const idCol = col('帖子ID');
      if (idCol >= 0) {
        for (let r = 1; r < table.content.length; r++) {
          const row = table.content[r];
          if (Array.isArray(row) && String(row[idCol] || '') === postId) return true;
        }
      }
      const payload = {};
      const set = (label, value) => {
        if (header.some(h => String(h || '') === label)) payload[label] = value;
      };
      const comments = Array.isArray(moment.comments) ? moment.comments : [];
      set('帖子ID', postId);
      set('发帖账号名', moment.author);
      set('账号标签', '桌游玩家');
      set('帖子标题', '');
      set('帖子正文', moment.text);
      set('话题/附加信息', '#桌游局');
      set('图片描述', 'none');
      set('视频描述', 'none');
      set('评论串', comments.map(c => c.name + '：' + c.text).join(';'));
      set('互动数据', '点赞 ' + (1 + Math.floor(Math.random() * 20)) + ' · 评论 ' + comments.length);
      set('时间文本', moment.timeLabel || '刚刚');
      await api.insertRow(tableName, payload);
      return true;
    } catch (e) {
      console.warn('[玉子游戏扩展] 写入广场表失败:', e);
      return false;
    }
  }

  // 把「对局记录」里已有的动态重新同步到广场（按帖子ID去重）
  async function syncRecordMomentToPhone(record) {
    const m = record && record.moment;
    if (!m || !m.author || !m.text) return false;
    const moment = buildPhoneMoment(m.author, m.text, m.comments || []);
    if (m.id) moment.id = m.id;
    return await writeMomentToPhone(moment);
  }

  // 读取玉子手机内该角色的社交动态（广场/贴吧/小红书）摘要，供台词生成参考
  function getCharacterSocialContext(name) {
    if (!name) return '';
    try {
      const val = __phoneDataCache__;
      if (!val || typeof val !== 'object') return '';
      const social = (val.social && typeof val.social === 'object') ? val.social : val;
      const lines = [];
      const moments = Array.isArray(social.moments) ? social.moments : [];
      moments.filter(m => m && m.author && isNameMatch(m.author, name)).slice(-3).forEach(m => {
        const text = String(m.text || m.content || '').trim();
        if (text) lines.push('【广场】' + text.slice(0, 120) + (m.timeLabel ? '（' + m.timeLabel + '）' : ''));
      });
      const tieba = Array.isArray(social.tieba) ? social.tieba : [];
      tieba.filter(t => t && t.author && isNameMatch(t.author, name)).slice(-3).forEach(t => {
        const title = String(t.title || '').trim();
        const content = String(t.content || t.text || '').trim();
        if (title || content) lines.push('【贴吧·' + (t.bar || '吧') + '】' + (title ? title + '：' : '') + content.slice(0, 100));
      });
      const xhs = Array.isArray(social.xhs) ? social.xhs : [];
      xhs.filter(x => x && x.author && isNameMatch(x.author, name)).slice(-3).forEach(x => {
        const title = String(x.title || '').trim();
        const content = String(x.content || x.text || '').trim();
        if (title || content) lines.push('【小红书】' + (title ? title + '：' : '') + content.slice(0, 100));
      });
      // 该角色发布内容下的他人评论（体现互动）
      const commentLines = [];
      const collectComments = (arr, label) => {
        (Array.isArray(arr) ? arr : []).filter(p => p && p.author && isNameMatch(p.author, name)).slice(-2).forEach(p => {
          (Array.isArray(p.comments) ? p.comments : []).slice(-3).forEach(cm => {
            if (cm && cm.name && cm.text) commentLines.push('【' + label + '评论】' + cm.name + '：' + String(cm.text).slice(0, 80));
          });
        });
      };
      collectComments(moments, '广场');
      collectComments(tieba, '贴吧');
      collectComments(xhs, '小红书');
      lines.push(...commentLines.slice(0, 4));
      // 别人发布、但提到了该角色的内容（有关角色的动态）
      const mentionLines = [];
      const collectMentions = (arr, label, titleKey) => {
        (Array.isArray(arr) ? arr : []).filter(p => p && p.author && !isNameMatch(p.author, name)).forEach(p => {
          const title = String(p[titleKey] || '').trim();
          const body = String(p.text || p.content || '').trim();
          const cmText = (Array.isArray(p.comments) ? p.comments : []).map(cm => cm && cm.text ? String(cm.text) : '').join(' ');
          if (isNameMatch(title, name) || String(title + ' ' + body + ' ' + cmText).includes(name)) {
            const merged = (title && body && title !== body) ? (title + ' ' + body) : (title || body);
            if (merged) mentionLines.push('【' + label + '·提到' + name + '】' + (p.author ? p.author + '：' : '') + merged.slice(0, 90));
          }
        });
      };
      collectMentions(moments, '广场', 'text');
      collectMentions(tieba, '贴吧', 'title');
      collectMentions(xhs, '小红书', 'title');
      lines.push(...mentionLines.slice(0, 4));
      return lines.join('\n');
    } catch (e) { return ''; }
  }

  // 读取玉子手机内该角色的最近QQ聊天/互动记录，供对弈台词生成参考
  function getCharacterWechatContext(name) {
    if (!name) return '';
    const extract = (convs) => {
      if (!Array.isArray(convs)) return '';
      const conv = convs.find(c => {
        const title = c && (typeof c.title === 'string' ? c.title : (Array.isArray(c.members) ? c.members.find(m => m && m !== 'me' && m !== '我') : ''));
        return title && isNameMatch(title, name);
      });
      if (!conv || !Array.isArray(conv.messages) || !conv.messages.length) return '';
      return conv.messages.slice(-12).map(m => {
        const who = m.from === 'me' || m.from === '我' ? '主角' : name;
        return `${who}：${String(m.content ?? '').trim()}`;
      }).filter(s => { const p = s.indexOf('：'); return p > -1 && s.slice(p + 1); }).join('\n');
    };

    const fromCache = extract(__phoneDataCache__ && Array.isArray(__phoneDataCache__.conversations) ? __phoneDataCache__.conversations : null);
    return fromCache;
  }

  function resolveApiConfig(extraCfg) {
    const cfg = loadConfig();
    const merged = {
      apiUrl: (extraCfg?.apiUrl) || cfg.apiUrl || '',
      apiKey: (extraCfg?.apiKey) || cfg.apiKey || '',
      model: (extraCfg?.model) || cfg.model || 'gpt-3.5-turbo'
    };
    return merged;
  }

  // ========== 联动专用 API 配置（与游戏 API 配置相互独立、互不影响） ==========
  function loadLinkageApiConfig() {
    try {
      const raw = localStorage.getItem(LINKAGE_API_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        return {
          apiUrl: typeof p.apiUrl === 'string' ? p.apiUrl : '',
          apiKey: typeof p.apiKey === 'string' ? p.apiKey : '',
          model: typeof p.model === 'string' ? p.model : ''
        };
      }
    } catch (e) { /* ignore */ }
    return { apiUrl: '', apiKey: '', model: '' };
  }

  function saveLinkageApiConfig(cfg) {
    try {
      localStorage.setItem(LINKAGE_API_CONFIG_KEY, JSON.stringify({
        apiUrl: String(cfg?.apiUrl || '').trim(),
        apiKey: String(cfg?.apiKey || '').trim(),
        model: String(cfg?.model || '').trim()
      }));
    } catch (e) { /* ignore */ }
  }

  function hasLinkageApiConfig() {
    const c = loadLinkageApiConfig();
    return !!(c.apiUrl && c.apiUrl.trim());
  }

  // 联动生成通道解析：优先使用联动专属 API；未配置时回退游戏 API
  function ensureLinkageAIBackend() {
    const lk = loadLinkageApiConfig();
    if (lk.apiUrl && String(lk.apiUrl).trim()) return lk;
    return ensureAIBackend();
  }

  // 保证消息条数：不足时把最长的一条按句子边界拆成两条，直到凑够（不编造新内容）
  function ensureMessageCount(lines, want) {
    const out = (Array.isArray(lines) ? lines : []).slice();
    const target = Math.max(1, Number(want) || 3);
    let guard = 0;
    while (out.length < target && guard++ < 16) {
      let li = 0;
      for (let i = 1; i < out.length; i++) if (out[i].length > out[li].length) li = i;
      const s = out[li] || '';
      if (s.length < 10) break;
      const parts = s.split(/(?<=[。！？!?；;…~])\s*/).filter(Boolean);
      if (parts.length >= 2) {
        const half = Math.ceil(parts.length / 2);
        out.splice(li, 1, parts.slice(0, half).join(''), parts.slice(half).join(''));
      } else {
        const mid = Math.floor(s.length / 2);
        out.splice(li, 1, s.slice(0, mid), s.slice(mid));
      }
    }
    return out.slice(0, Math.max(target, out.length));
  }

  // 解析"角色名|消息内容"批量输出（与玉子手机一致：一次请求产出全部角色全部消息）
  function parseWechatBulkLines(raw, targets) {
    const map = new Map();
    const lines = String(raw == null ? '' : raw).replace(/```[a-zA-Z]*/g, '').split(/\r?\n+/);
    for (let line of lines) {
      line = line.trim();
      if (!line) continue;
      line = line.replace(/^\s*(?:第?\s*\d+\s*[.、)\]]|[-*·•])\s*/, '').trim();
      // 分隔符优先识别「|」，AI 偶尔会输出全角冒号「：」，做兜底识别
      let sep = line.indexOf('|');
      if (sep < 0) {
        line = line.replace(/^((?:[^：:\n]{1,20}?)\s*[：:])\s*/, (m, g1) => g1.replace(/\s*[：:]\s*$/, '') + '|');
        sep = line.indexOf('|');
      }
      if (sep < 0) continue;
      let name = line.slice(0, sep).trim().replace(/^[【「\[]+|[】」\]]+$/g, '').trim();
      let text = line.slice(sep + 1).trim();
      name = name.replace(/^(?:QQ消息|消息)\s*[:：]\s*/, '').trim();
      text = text.replace(/^["'“”‘’「」【】]+|["'“”‘’「」【】]+$/g, '').trim();
      if (!name || !text || text.length < 2) continue;
      if (/^(以下|好的|收到|说明|注|备注)$/.test(text)) continue;
      const hit = targets.find(t => t && t.name && isNameMatch(t.name, name));
      if (!hit) continue;
      if (!map.has(hit.name)) map.set(hit.name, []);
      map.get(hit.name).push(text);
    }
    return map;
  }

  // 生成并写入QQ角色反应：与玉子手机一致——**只请求 AI 一次**，一次性产出"所有角色 × 所有消息"再分发。
