        const rels = getCharacterRelationsFromDB();
        const names = players.map(p => p.name);
        if (Array.isArray(rels)) {
          relations = rels.filter(r => r && names.some(n => isNameMatch(n, r.a || r.from || r['角色A'] || '')) && names.some(n => isNameMatch(n, r.b || r.to || r['角色B'] || '')))
            .map(r => `${r.a || r.from || r['角色A']} ↔ ${r.b || r.to || r['角色B']}：${r.type || r.relation || r['关系'] || '关系'}`).join('\n');
