  }

  // 积分结算：棋类等其余游戏 胜利 +1 / 失败 -1（可扣成负数）；牌类游戏只结算金币货币
  function applyMatchPoints(matchInfo) {
    if (!matchInfo || !matchInfo.gameType) return;
    // 炸金花 / 21点 / 德州扑克（退出时结算）· 麻将 / 斗地主（每局按 赌注×倍数 结算）：输赢只走金币货币，不增减积分
    if (matchInfo.gameType === 'zjh' || matchInfo.gameType === 'blackjack' || matchInfo.gameType === 'holdem' || matchInfo.gameType === 'mahjong' || matchInfo.gameType === 'doudizhu') return;
    if (typeof matchInfo.userWon !== 'boolean') return;
    if (matchInfo.isDraw) return;
    const delta = matchInfo.userWon ? 1 : -1;
    const total = addPoints(delta);
    matchInfo.pointsDelta = delta;
    matchInfo.pointsTotal = total;
    showToast((delta >= 0 ? '💎 积分 +' + delta : '💎 积分 ' + delta) + '（当前 ' + total + '）');
  }

// ========== 麻将（逆时针摸牌、顺时针出牌 / 胡>杠>碰>吃 / 136 张） ==========
  // 牌 id：0~8 万, 9~17 筒, 18~26 条, 27~33 东南西北中发白
  const MJ_TILE_NAMES = ['1万','2万','3万','4万','5万','6万','7万','8万','9万','1筒','2筒','3筒','4筒','5筒','6筒','7筒','8筒','9筒','1条','2条','3条','4条','5条','6条','7条','8条','9条','东','南','西','北','中','发','白'];
  const MJ_G = ['🀇','🀈','🀉','🀊','🀋','🀌','🀍','🀎','🀏','🀙','🀚','🀛','🀜','🀝','🀞','🀟','🀠','🀡','🀐','🀑','🀒','🀓','🀔','🀕','🀖','🀗','🀘','🀀','🀁','🀂','🀃','🀄','🀅','🀆'];
  const MJ_CONFIG_KEY = 'werewolf_extension_mj_config';
  let mj = null;
  let mjInvites = [];
  let mjAiTimer = null;
  let mjChatBusy = false;
  let mjGenCounter = 0;
  const MJ_SHANTEN_CACHE = new Map();

  function mjTileName(id) { return MJ_TILE_NAMES[id] || '?'; }
  function mjGlyph(id) { return MJ_G[id] || '🀫'; }
  function mjCounts(hand) { const c = new Array(34).fill(0); (hand || []).forEach(t => { if (t >= 0 && t < 34) c[t]++; }); return c; }
  function mjSort(hand) { return hand.slice().sort((a, b) => a - b); }
  function mjNext(g, s) { return (s + 1) % 4; }
  function mjDraw(g) { return g.wall.length ? g.wall.shift() : -1; }
  function mjKangDraw(g) { return g.wall.length ? g.wall.pop() : -1; }
  function mjMakeWall(version) {
    // 136 张：万/筒/条 + 东南西北中发白；108 张：只保留万/筒/条（无字牌）
    const maxTile = version === '108' ? 27 : 34;
    const wall = [];
    for (let t = 0; t < maxTile; t++) for (let i = 0; i < 4; i++) wall.push(t);
    for (let i = wall.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const tmp = wall[i]; wall[i] = wall[j]; wall[j] = tmp; }
    return wall;
  }
  function mjLog(g, text) { g.log.push(text); if (g.log.length > 60) g.log.splice(0, g.log.length - 60); }

  function loadMjConfig() {
    const def = { aiLevel: 'normal', aiChat: true, speechInterval: 4, version: '136', bet: 100 };
    try {
      const raw = localStorage.getItem(MJ_CONFIG_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p && typeof p === 'object') {
          if (p.aiLevel === 'fast' || p.aiLevel === 'normal' || p.aiLevel === 'strong') def.aiLevel = p.aiLevel;
          if (typeof p.aiChat === 'boolean') def.aiChat = p.aiChat;
          if (Number.isFinite(Number(p.speechInterval)) && Number(p.speechInterval) >= 1) def.speechInterval = Number(p.speechInterval);
          if (p.version === '108' || p.version === '136') def.version = p.version;
          if (Number.isFinite(Number(p.bet)) && Number(p.bet) >= 1) def.bet = Math.round(Number(p.bet));
        }
      }
    } catch (e) { /* ignore */ }
    return def;
  }
  function saveMjConfig(cfg) { try { localStorage.setItem(MJ_CONFIG_KEY, JSON.stringify(cfg || {})); } catch (e) { /* ignore */ } }

  // ---------- 胡牌判定 ----------
  function mjAllMeld(c, i) {
    let p = (i === undefined) ? 0 : i;
    while (p < 34 && c[p] === 0) p++;
    if (p === 34) return true;
    if (c[p] >= 3) { c[p] -= 3; const ok = mjAllMeld(c, p); c[p] += 3; if (ok) return true; }
    if (p < 27 && (p % 9) <= 6 && c[p + 1] > 0 && c[p + 2] > 0) {
      c[p]--; c[p + 1]--; c[p + 2]--;
      const ok = mjAllMeld(c, p);
      c[p]++; c[p + 1]++; c[p + 2]++;
      if (ok) return true;
    }
    return false;
  }
  // 副露（吃/碰/杠）每副消耗门内 3 张：赢牌时门内手牌数 = 14 - 3*meldCount
  // （杠的第 4 张来自补牌，因此同样按 3 张计；输赢判定必须把 g.melds 的副露数传进来）
  function mjWinHandSize(meldCount) { return 14 - 3 * (meldCount || 0); }
  function mjCanWinStandard(hand, meldCount) {
    meldCount = meldCount || 0;
    if (!hand || hand.length !== mjWinHandSize(meldCount)) return false;
    const c = mjCounts(hand);
    for (let pair = 0; pair < 34; pair++) {
      if (c[pair] < 2) continue;
      const cc = c.slice();
      cc[pair] -= 2;
      if (mjAllMeld(cc)) return true;
    }
    return false;
  }
  function mjCanWinSeven(hand, meldCount) {
    if (meldCount || !hand || hand.length !== 14) return false; // 七对只能门清，有副露不成立
    const c = mjCounts(hand);
    let pairs = 0;
    for (let i = 0; i < 34; i++) {
      if (c[i] === 2) pairs++;
      else if (c[i] === 4) pairs += 2;
      else if (c[i] !== 0) return false;
    }
    return pairs === 7;
  }
  function mjCanWinOrphans(hand, meldCount) {
    if (meldCount || !hand || hand.length !== 14) return false; // 十三幺只能门清，有副露不成立
    const orphans = [0, 8, 9, 17, 18, 26, 27, 28, 29, 30, 31, 32, 33];
    const c = mjCounts(hand);
    let distinct = 0, hasPair = false;
    for (const t of orphans) { if (c[t] > 0) distinct++; if (c[t] >= 2) hasPair = true; }
    for (let i = 0; i < 34; i++) { if (c[i] > 0 && orphans.indexOf(i) === -1) return false; }
    return distinct === 13 && hasPair;
  }
  function mjCanWin(hand, meldCount) {
    meldCount = meldCount || 0;
    if (!hand || hand.length !== mjWinHandSize(meldCount)) return false;
    return mjCanWinStandard(hand, meldCount) || mjCanWinSeven(hand, meldCount) || mjCanWinOrphans(hand, meldCount);
  }

  // ---------- 向听数（标准型 / 七对 / 十三幺 取最小） ----------
  function mjDecompose(c) {
    let i = 0;
    while (i < 34 && c[i] === 0) i++;
    if (i === 34) return 0;
    let best = 0, v;
    if (c[i] >= 3) { c[i] -= 3; v = 2 + mjDecompose(c); c[i] += 3; if (v > best) best = v; }
    if (i < 27 && (i % 9) <= 6 && c[i + 1] > 0 && c[i + 2] > 0) { c[i]--; c[i + 1]--; c[i + 2]--; v = 2 + mjDecompose(c); c[i]++; c[i + 1]++; c[i + 2]++; if (v > best) best = v; }
    if (c[i] >= 2) { c[i] -= 2; v = 1 + mjDecompose(c); c[i] += 2; if (v > best) best = v; }
    if (i < 27 && (i % 9) <= 7 && c[i + 1] > 0) { c[i]--; c[i + 1]--; v = 1 + mjDecompose(c); c[i]++; c[i + 1]++; if (v > best) best = v; }
    if (i < 27 && (i % 9) <= 6 && c[i + 2] > 0) { c[i]--; c[i + 2]--; v = 1 + mjDecompose(c); c[i]++; c[i + 2]++; if (v > best) best = v; }
    c[i]--; v = mjDecompose(c); c[i]++;
    if (v > best) best = v;
    return best;
  }
  function mjShanten(hand, meldCount) {
    meldCount = meldCount || 0;
    if (!hand || !hand.length) return 8;
    const key = meldCount + '|' + mjCounts(hand).join(',');
    const hit = MJ_SHANTEN_CACHE.get(key);
    if (hit !== undefined) return hit;
    const c = mjCounts(hand);
    // 每副副露 = 已完成的一组，标准型向听数直接减 2；七对/十三幺只在门清时参与取最小
    let std = 8 - 2 * meldCount - mjDecompose(c);
    let s7 = 99, s13 = 99;
    if (!meldCount) {
      let p = 0, s = 0;
      for (let i = 0; i < 34; i++) { if (c[i] >= 2) p += (c[i] === 4 ? 2 : 1); else if (c[i] === 1) s++; }
      s7 = 6 - p + Math.max(0, 7 - p - s);
      const orphans = [0, 8, 9, 17, 18, 26, 27, 28, 29, 30, 31, 32, 33];
      let d = 0, hasP = false;
      for (const t of orphans) { if (c[t] > 0) d++; if (c[t] >= 2) hasP = true; }
      s13 = 13 - d - (hasP ? 1 : 0);
    }
    const res = Math.max(-1, Math.min(std, s7, s13));
    MJ_SHANTEN_CACHE.set(key, res);
    if (MJ_SHANTEN_CACHE.size > 40000) MJ_SHANTEN_CACHE.clear();
    return res;
  }
  function mjShantenAfter(hand, tile, meldCount) {
    const idx = hand.indexOf(tile);
    if (idx === -1) return 99;
    const c = hand.slice(); c.splice(idx, 1);
    return mjShanten(c, meldCount);
  }
  function mjUniqueTiles(hand) { const out = []; const seen = {}; for (const t of hand) { if (!seen[t]) { seen[t] = 1; out.push(t); } } return out; }
  function mjRemoveNTiles(hand, tile, n) {
    const out = []; let left = n;
    for (const t of hand) { if (t === tile && left > 0) left--; else out.push(t); }
    return out;
  }

  // ---------- 吃牌选项 ----------
  function mjChiOptions(hand, tile) {
    if (tile > 26) return [];
    const suit = Math.floor(tile / 9) * 9;
    const r = tile % 9;
    const has = v => hand.indexOf(suit + v) !== -1;
    const out = [];
    if (r >= 2 && has(suit + r - 2) && has(suit + r - 1)) out.push({ tiles: [suit + r - 2, suit + r - 1, tile], a: suit + r - 2, b: suit + r - 1 });
    if (r >= 1 && r <= 7 && has(suit + r - 1) && has(suit + r + 1)) out.push({ tiles: [suit + r - 1, tile, suit + r + 1], a: suit + r - 1, b: suit + r + 1 });
    if (r <= 6 && has(suit + r + 1) && has(suit + r + 2)) out.push({ tiles: [tile, suit + r + 1, suit + r + 2], a: suit + r + 1, b: suit + r + 2 });
    return out;
  }
  function mjBestChiOption(hand, tile, meldCount) {
    const opts = mjChiOptions(hand, tile);
    let best = null, bestSh = 99;
    for (const o of opts) {
      const rest = mjRemoveNTiles(mjRemoveNTiles(hand, o.a, 1), o.b, 1);
      const sh = mjShanten(rest, (meldCount || 0) + 1); // 吃后副露 +1
      if (sh < bestSh) { bestSh = sh; best = o; }
    }
    return best;
  }

  // ---------- 对局构建 ----------
  function mjBuildGame(names) {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const cfg = loadMjConfig();
    const list = (names || []).map(n => String(n).trim()).filter(Boolean);
    const players = [];
    players.push({ seat: 0, name: '我', isUser: true, avatar: getMainCharAvatar() || '' });
    for (let i = 0; i < 3; i++) {
      const nm = list[i];
      const ct = nm ? contacts.find(c2 => c2 && isNameMatch(c2.name, nm)) : null;
      players.push({ seat: i + 1, name: nm || ('机器人' + (i + 1)), isUser: false, avatar: (ct && ct.avatar) || (nm ? getCharacterAvatarByName(nm) : '') || '' });
    }
    return {
      session: Date.now() + '_' + Math.floor(Math.random() * 100000),
      players, hands: [[], [], [], []], melds: [[], [], [], []], discards: [[], [], [], []],
      version: cfg.version === '108' ? '108' : '136',
      wall: mjMakeWall(cfg.version === '108' ? '108' : '136'), dealer: Math.floor(Math.random() * 4), turn: 0, phase: 'idle',
      last: null, drawn: -1, winner: -1, winType: '', winTiles: [], paoSeat: -1,
