    const escStart = mjEscrowSync(mj, '买入底注（赌注 ' + mj.bet + '）', 'game-buyin');
    if (escStart > 0) mjLog(mj, '💰 金币实时预扣本金 ' + escStart + '（赢：返还本金+赢钱；输：预扣款即为输款；流局/与你无关退还）');
