【基本】逆时针摸牌、顺时针出牌；4 组（顺子/刻子/杠）+ 1 对将，或七对、十三幺（仅 136 张）；打出即可胡时点击【胡】；自摸可胡时点击【自摸胡牌】。
【优先级】胡＞杠＞碰＞吃；吃仅限上家；杠（明杠/暗杠/补杠）后从牌墙末尾补 1 张。
【结束】有人胡牌或牌墙摸完（流局）。实时扣钱：每局开局立即按 赌注 从金币预扣本金（买入底注），局终按 赌注 × 倍数 实时多退少补（自摸 ×2、每个杠 ×2、七对 ×2、十三幺 ×4 可叠加；自摸时三家都付、点炮只由点炮者付）：赢了实时回款（本金+赢钱）、输了预扣款即输款、流局退还预扣；对局自动写入对局记录。</div>
        </details>
      </div>
    `;

    const toggle = sheet.querySelector('#mj-chat-toggle');
    if (toggle) {
      toggle.addEventListener('change', () => {
        const c = loadMjConfig();
        c.aiChat = toggle.checked;
        saveMjConfig(c);
        renderMjLobby();
      });
    }
  }

  function mjSeatSaveName(saved, seat) {
    if (!saved || !saved.players || !saved.players[seat]) return '玩家';
    return saved.players[seat].name;
  }

