  function mjInviteOverlay() {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    const chosen = mjInvites;
    const ov = document.createElement('div');
    ov.className = 'mj-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:58;background:var(--ubp-card);display:flex;flex-direction:column;padding:10px 12px 8px;box-sizing:border-box;';
    const render = () => {
      const list = contacts.map(ct => {
        const on = chosen.some(n => isNameMatch(n, ct.name));
        const av = ct.avatar || getCharacterAvatarByName(ct.name);
        return '<div data-mj-pick="' + escapeHtml(ct.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(217,119,6,0.16)' : 'var(--ubp-card-2)') + ';border:1.5px solid ' + (on ? '#D97706' : 'var(--ubp-line)') + ';">' +
          '<div style="width:34px;height:34px;border-radius:50%;background:#D97706;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:13px;">' + escapeHtml(String(ct.name || '?').slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ubp-text);word-break:break-all;">' + escapeHtml(ct.name) + '</div>' +
          (ct.identity ? '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:2px;word-break:break-all;">' + escapeHtml(ct.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:15px;color:#D97706;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">' +
        '<span style="font-size:15px;font-weight:600;">📨 邀请 3 位角色入座</span>' +
        '<button data-mj-act="mj-invite-close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#D97706;">' + chosen.length + '</b> / 3</div>' +
        '<div style="flex:1;overflow-y:auto;margin-bottom:8px;">' + (list || '<div style="font-size:12px;color:var(--ubp-text-3);">通讯录暂无角色</div>') + '</div>' +
        '<div style="display:flex;justify-content:flex-end;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-mj-act="mj-invite-confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#D97706;border:none;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-mj-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const nm = el.dataset.mjPick;
          const i = chosen.findIndex(n => isNameMatch(n, nm));
          if (i !== -1) chosen.splice(i, 1);
          else { if (chosen.length >= 3) { showToast('最多邀请 3 位角色'); return; } chosen.push(nm); }
          render();
        });
      });
    };
    render();
    sheet.appendChild(ov);
  }

  // ---------- 牌桌 UI ----------
  function mjMeldHTML(m, isUser) {
    const gl = m.hidden && !isUser
      ? '<span style="opacity:0.9;">🀫🀫🀫🀫</span>'
      : m.tiles.map(mjGlyph).join('');
    const label = m.type === 'chi' ? '吃' : m.type === 'peng' ? '碰' : (m.hidden && !isUser ? '暗杠' : '杠');
    return '<span style="display:inline-flex;align-items:center;gap:1px;margin:2px;padding:1px 4px;border-radius:5px;background:rgba(255,255,255,0.08);border:1px solid var(--ubp-line);font-size:8.5px;color:var(--ubp-text-2);">' + label + '<span style="font-size:13px;letter-spacing:-1px;">' + gl + '</span></span>';
  }
  function mjClaimBarHTML(g) {
    const btns = [];
    for (const c of g.pendingClaim.claims) {
      if (!g.players[c.seat] || !g.players[c.seat].isUser) continue; // 只显示"我"可执行的决策按钮
      if (c.type === 'hu') btns.push('<button data-mj-act="mj-claim-hu" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12.5px;background:#10B981;border:none;border-radius:6px;">胡</button>');
      if (c.type === 'gang') btns.push('<button data-mj-act="mj-claim-gang" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12.5px;background:#D97706;border:none;border-radius:6px;">杠</button>');
      if (c.type === 'peng') btns.push('<button data-mj-act="mj-claim-peng" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12.5px;background:#F59E0B;border:none;border-radius:6px;">碰</button>');
      if (c.type === 'chi') (c.options || [c]).forEach((o, i) => btns.push('<button data-mj-act="mj-claim-chi" data-i="' + i + '" class="ubp-btn" style="flex:1;padding:6px 0;font-size:12px;border-radius:6px;">吃 ' + o.tiles.map(mjTileName).join('') + '</button>'));
    }
    if (btns.length) btns.push('<button data-mj-act="mj-pass" class="ubp-btn" style="flex:1;padding:6px 0;font-size:12.5px;border-radius:6px;">过</button>');
    if (!btns.length) return '';
    return '<div style="display:flex;gap:6px;margin-bottom:6px;flex:none;flex-wrap:wrap;">' + btns.join('') + '</div>';
  }
  function renderMjGameUI() {
    const g = mj;
    if (!g) { renderMjLobby(); return; }
    const me = g.players[0];
    const hand = mjSort(g.hands[0]);
    const myTurn = mjDiscardClickable(g);
    const pending = g.phase === 'claim' && g.pendingClaim && Array.isArray(g.pendingClaim.claims);
    const canWin = myTurn && mjCanWin(g.hands[0], g.melds[0].length);
    const ankTiles = myTurn ? mjUniqueTiles(g.hands[0]).filter(t => mjCounts(g.hands[0])[t] === 4) : [];
    const bgTiles = myTurn ? g.melds[0].filter(m => m.type === 'peng' && g.hands[0].indexOf(m.tiles[0]) !== -1).map(m => m.tiles[0]) : [];
    const oppRows = g.players.slice(1).map((p, i) => {
      const s = i + 1;
      const on = g.turn === s && g.phase !== 'end';
      const melds = g.melds[s].map(m => mjMeldHTML(m, false)).join('');
      const river = g.discards[s].slice(-16).map(t => '<span style="font-size:14px;' + (g.last && g.last.seat === s && g.last.tile === t && g.discards[s].length && g.discards[s][g.discards[s].length - 1] === t ? 'outline:2px solid #F59E0B;border-radius:4px;' : '') + '">' + mjGlyph(t) + '</span>').join('');
      return '<div style="display:flex;align-items:center;gap:6px;padding:4px 8px;border-radius:8px;background:var(--ubp-card-2);border:1.5px solid ' + (on ? '#F59E0B' : 'var(--ubp-line)') + ';">' +
        chatAvatarHTML(p.name, false, 28, p.avatar) +
        '<div style="flex:1;min-width:0;"><div style="font-size:12px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(p.name) + ' · 剩 ' + g.hands[s].length + ' 张</div><div style="font-size:10px;color:var(--ubp-text-3);min-height:14px;">' + melds + '</div></div>' +
        '<div style="max-width:118px;white-space:nowrap;overflow:hidden;text-align:right;">' + river + '</div></div>';
    }).join('');
    const claimBar = pending ? mjClaimBarHTML(g) : '';
    const myMelds = g.melds[0].map(m => mjMeldHTML(m, true)).join('');
    let hint = '';
    if (g.phase === 'end') {
      const mjMoneyTip = (g.moneyDelta ? (' · 金币 ' + (g.moneyDelta > 0 ? '+' : '') + g.moneyDelta) : '');
      hint = g.winner === 0 ? ('🎉 你胡了！' + mjMoneyTip) : g.winner >= 0 ? ('💀 ' + escapeHtml(g.players[g.winner].name) + ' 胡牌' + mjMoneyTip) : '🤝 流局（赌注不变）';
    } else if (pending) hint = '👉 上家打出 ' + mjTileName(g.last.tile) + '，选择你的操作';
    else if (myTurn) {
      if (canWin) hint = '🎉 你已听胡——可以自摸！';
      else if (ankTiles.length || bgTiles.length) hint = '👉 轮到你：可以杠，或点手牌出牌';
      else hint = '👉 轮到你出牌（点击手牌）';
    } else hint = '⏳ 等待 ' + escapeHtml(g.players[g.turn].name) + ' 行动…';
    const lastDisc = g.last ? ('<span style="font-size:15px;">' + escapeHtml(g.players[g.last.seat].name) + ' 打出</span> <span style="font-size:22px;">' + mjGlyph(g.last.tile) + '</span> <span style="font-size:10px;color:var(--ubp-text-3);">' + mjTileName(g.last.tile) + '</span>') : '<span style="font-size:10px;color:var(--ubp-text-3);">牌桌就绪</span>';
    const winBtns = [];
    if (canWin) winBtns.push('<button data-mj-act="mj-zimo" class="ubp-btn primary" style="padding:6px 14px;font-size:13px;background:#10B981;border:none;border-radius:6px;">自摸胡牌</button>');
    ankTiles.forEach(t => winBtns.push('<button data-mj-act="mj-ankang" data-tile="' + t + '" class="ubp-btn" style="padding:6px 10px;font-size:12.5px;border-radius:6px;">暗杠 ' + mjTileName(t) + '</button>'));
    bgTiles.forEach(t => winBtns.push('<button data-mj-act="mj-bugang" data-tile="' + t + '" class="ubp-btn" style="padding:6px 10px;font-size:12.5px;border-radius:6px;">补杠 ' + mjTileName(t) + '</button>'));
    const handTiles = hand.map(t => {
      // 轮到自己时手牌始终可点（提示语也写着"可以杠，或点手牌出牌"）；旧代码在可胡/可杠时置灰但仍可点，属于误导
      const active = myTurn;
      return '<button data-mj-act="mj-discard" data-tile="' + t + '" style="width:34px;height:46px;margin:2px 1px;border-radius:5px;background:' + (active ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.05)') + ';border:1px solid ' + (active ? '#F59E0B' : 'var(--ubp-line)') + ';font-size:22px;cursor:' + (active ? 'pointer' : 'default') + ';box-sizing:border-box;padding:0;">' + mjGlyph(t) + '</button>';
    }).join('');
    const logHTML = g.log.slice(-40).map(l => '<div style="margin:1px 0;font-size:11px;color:var(--ubp-text-2);">' + escapeHtml(l) + '</div>').join('');
    // 💰 实时扣钱显示：当前金币余额 + 本局已实时预扣本金
    const tNowM = getTreasury();
    const escrowM = Math.max(0, Math.round(Number(g.escrow) || 0));
    const moneyHUD = ' · 💰 ' + (tNowM.ok ? tNowM.balance : '—') + (escrowM > 0 ? '（本局已预扣 ' + escrowM + '）' : '');
    const endButtons = g.phase === 'end'
      ? '<div style="display:flex;gap:8px;flex:none;margin-top:8px;"><button data-mj-act="mj-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:13px;background:#D97706;border:none;border-radius:8px;">🔄 再来一局</button><button data-mj-act="mj-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:13px;border-radius:8px;">🚪 退出</button></div>'
      : '';
    const mjChatHTML = g.aiChat ? `
      <style>
        #mj-speech-container::-webkit-scrollbar { width: 5px; }
        #mj-speech-container::-webkit-scrollbar-thumb { background: #D97706; border-radius: 4px; }
      </style>
      <div id="mj-speech-container" style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:8px;padding:6px 9px;margin-top:5px;height:76px;max-height:76px;overflow-y:scroll;scrollbar-width:thin;box-sizing:border-box;">
        <div id="mj-speech-text" style="font-size:12px;line-height:1.5;word-break:break-word;">${mjRenderSpeechHTML()}</div>
      </div>
      <div style="display:flex;gap:6px;margin-top:5px;">
        <input id="mj-chat-input" class="ubp-fieldinput" type="text" placeholder="对牌桌上的角色说点什么…（如：这手牌怎么样）" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">
        <button data-mj-act="mj-send-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#D97706;border:none;flex:none;">发送</button>
      </div>` : '';
    sheet.innerHTML = [
