  function unoCardHTML(card, opts) {
    const o = opts || {};
    const bg = UNO_COLOR_HEX[card.c] || '#374151';
    const label = card.c === 'W' ? (card.t === 'w4' ? '+4' : '🌈') : (UNO_TYPE_LABEL[card.t] || card.t);
    const w = o.w || 46, h = o.h || 64;
    const fs = o.fs || 15;
    // 功能牌（如「🚫 跳过」「🔄 反转」）文字保持单行并自动缩小字号，
    // 保证一手牌里所有卡牌的文字都居中在同一列上。
    const labelFs = String(label).length >= 4 ? Math.max(10, fs - 4) : fs;
    const fxCls = o.fx ? ' class="' + o.fx + '"' : '';
    const fxStyle = o.fx ? ';animation-delay:' + Math.max(0, Number(o.delay) || 0) + 'ms;' : '';
    return '<div' + fxCls + ' style="width:' + w + 'px;height:' + h + 'px;border-radius:8px;background:' + bg + ';color:#fff;display:flex;align-items:center;justify-content:center;font-size:' + labelFs + 'px;font-weight:700;border:2px solid ' + (o.border || 'rgba(255,255,255,0.35)') + ';box-shadow:0 2px 6px rgba(0,0,0,0.35);white-space:nowrap;overflow:hidden;' + (o.extra || '') + fxStyle + '">' + label + '</div>';
  }
