  function bjAfterInsurance(meBJ, dealerBJ) {
    const g = bjGame;
    if (!g) return;
    if (dealerBJ) {
      g.dealer.forEach(c => { c.hole = false; });
      if (meBJ) { bjSettleHand(g.hands[0], 'push', g.hands[0].bet, '双方黑杰克，平局退回赌注'); }
      else { bjSettleHand(g.hands[0], 'lose', -g.hands[0].bet, '庄家黑杰克，你输掉赌注'); }
      bjLog(g, '🃏 庄家亮牌：' + g.dealer.map(bjCardText).join(' ') + ' —— 黑杰克！');
      bjEndRound();
      return;
    }
    if (meBJ) {
      bjSettleHand(g.hands[0], 'bj', Math.floor(g.hands[0].bet * 1.5), '黑杰克！赢得 1.5 倍赌注');
      g.dealer.forEach(c => { c.hole = false; });
      bjLog(g, '🃏 你拿到黑杰克（21 点），直接获胜');
      bjEndRound();
      return;
    }
    g.phase = 'play';
    bjRender();
    if (g.round === 1) bjMaybeAutoSpeak('deal', true); else bjMaybeAutoSpeak('deal');
