  // 💠 边注 A：完美对子（Perfect Pairs）——看玩家起手两张：杂色对 6:1 / 同色对 12:1 / 同花对 25:1
  function bjSidePairResult(cards) {
    if (!cards || cards.length < 2) return { odds: 0, name: '' };
    const a = cards[0], b = cards[1];
    if (a.r !== b.r) return { odds: 0, name: '' };
    if (a.s === b.s) return { odds: 25, name: '完全同花对子' };
    const redA = (a.s === 1 || a.s === 3);
    const redB = (b.s === 1 || b.s === 3);
    return redA === redB ? { odds: 12, name: '同色对子' } : { odds: 6, name: '杂色对子' };
  }
  // 💠 边注 B：21+3 —— 玩家两张 + 庄家明牌凑三张：同花 5:1 / 顺子 10:1 / 三条 30:1 / 同花顺 40:1 / 同花三条 100:1
  function bjSideT3Result(cards, up) {
    if (!cards || cards.length < 2 || !up) return { odds: 0, name: '' };
    const trio = [cards[0], cards[1], up];
    const sameSuit = trio[0].s === trio[1].s && trio[1].s === trio[2].s;
    const sameRank = trio[0].r === trio[1].r && trio[1].r === trio[2].r;
    if (sameRank && sameSuit) return { odds: 100, name: '同花三条' };
    const val = (r) => (r === 'A' ? 14 : r === 'K' ? 13 : r === 'Q' ? 12 : r === 'J' ? 11 : parseInt(r, 10));
    const vals = trio.map(x => val(x.r)).sort((x, y) => x - y);
    let straight = (vals[1] === vals[0] + 1 && vals[2] === vals[1] + 1);
    if (!straight && vals[0] === 2 && vals[1] === 3 && vals[2] === 14) straight = true; // A23 顺
    if (straight && sameSuit) return { odds: 40, name: '同花顺' };
    if (sameRank) return { odds: 30, name: '三条' };
    if (straight) return { odds: 10, name: '顺子' };
    if (sameSuit) return { odds: 5, name: '同花' };
    return { odds: 0, name: '' };
  }
  function bjSettleSideBets(g, pairStake, t3Stake) {
    if (pairStake > 0) {
      const r = bjSidePairResult(g.hands[0].cards);
      if (r.odds > 0) {
        g.chips += pairStake * (r.odds + 1); g.netChips += pairStake * r.odds;
        // 💰 实时入账：边注赔付（返还本金 + 赢钱）
        realtimeFlow(true, pairStake * (r.odds + 1), '21点 · 边注完美对子赔付（' + r.name + ' ' + r.odds + ':1）', 'game-win');
        bjLog(g, '💠 边注 完美对子：' + r.name + '！赔付 ' + r.odds + ':1（+' + (pairStake * r.odds) + '）');
      }
      else bjLog(g, '💠 边注 完美对子：未中（-' + pairStake + '）');
    }
    if (t3Stake > 0) {
      const up = g.dealer && g.dealer[1];
      const r = bjSideT3Result(g.hands[0].cards, up);
      if (r.odds > 0) {
        g.chips += t3Stake * (r.odds + 1); g.netChips += t3Stake * r.odds;
        // 💰 实时入账：边注赔付（返还本金 + 赢钱）
        realtimeFlow(true, t3Stake * (r.odds + 1), '21点 · 边注 21+3 赔付（' + r.name + ' ' + r.odds + ':1）', 'game-win');
        bjLog(g, '💠 边注 21+3：' + r.name + '！赔付 ' + r.odds + ':1（+' + (t3Stake * r.odds) + '）');
      }
      else bjLog(g, '💠 边注 21+3：未中（-' + t3Stake + '）');
    }
  }
  function bjSettleHand(h, result, payout, note) {
    if (h.result) return; // 防御：同一手只结算一次（避免重复实时入账）
    h.result = result; h.payout = payout; h.done = true;
    const g = bjGame;
    g.chips += payout;
    g.netChips += payout;
    // 💰 实时入账：返还本手已扣注额 + 结算盈亏（输=入账 0；平=退回本金；赢/黑杰克=本金 + 赢钱）
    const back = Math.max(0, Math.round(Number(h.bet) || 0)) + Math.round(Number(payout) || 0);
    if (back > 0) realtimeFlow(true, back, '21点 · 本手结算（' + note + '）', 'game-win');
    if (result === 'win' || result === 'bj') g.wins++;
    else if (result === 'push') g.pushes++;
    else g.losses++;
    bjLog(g, (result === 'bj' ? '🏆 ' : result === 'win' ? '✅ ' : result === 'push' ? '🤝 ' : '❌ ') + note + '（' + (payout >= 0 ? '+' : '') + payout + '）');
  }
  // 庄家行动：按「荷官难度」决定要牌/停牌（简单＝16 停；标准＝≤16 要；困难＝≤16 要 + 软17 要）
  function bjDealerPlay() {
    const g = bjGame;
    if (!g) return;
    g.dealer.forEach(c => { c.hole = false; });
    let guard = 0;
    while (guard++ < 20) {
      const v = bjHandValue(g.dealer);
      if (bjDealerMustHit(v, g.aiLevel)) { bjDrawTo(g.dealer); continue; }
      break;
    }
    const dv = bjHandValue(g.dealer).total;
    bjLog(g, '🏦 庄家亮牌：' + g.dealer.map(bjCardText).join(' ') + '（' + dv + '）' + (dv > 21 ? ' —— 爆牌！' : ''));
    for (const h of g.hands) {
      if (h.done && h.result) continue;
      const pv = bjHandValue(h.cards).total;
      if (pv > 21) { bjSettleHand(h, 'lose', -h.bet, '你爆牌（' + pv + '）'); continue; }
      if (dv > 21) { bjSettleHand(h, 'win', h.bet, '庄家爆牌，你赢 ' + h.bet); continue; }
      if (pv > dv) bjSettleHand(h, 'win', h.bet, '你的 ' + pv + ' 大于庄家 ' + dv + '，赢 ' + h.bet);
      else if (pv < dv) bjSettleHand(h, 'lose', -h.bet, '你的 ' + pv + ' 小于庄家 ' + dv + '，输 ' + h.bet);
      else bjSettleHand(h, 'push', 0, '双方都是 ' + pv + ' 点，平局退回赌注');
    }
    bjEndRound();
  }
  function bjEndRound() {
    const g = bjGame;
    if (!g) return;
    g.phase = 'roundEnd';
    bjSaveGame();
    bjRender();
    // 保险结算（庄家黑杰克时 2:1 赔付）
    if (g.insuranceTaken && bjIsBlackjack(g.dealer) === false && g.insurance > 0) { /* 已在下面统一处理 */ }
    if (g.insuranceTaken && g.insurance > 0) {
      const dealerBJ = bjIsBlackjack(g.dealer);
      if (dealerBJ) {
        g.chips += g.insurance * 3; g.netChips += g.insurance * 3;
        // 💰 实时入账：保险赔付（返还本金 + 2:1 赢钱）
        realtimeFlow(true, g.insurance * 3, '21点 · 保险赔付（2:1）', 'game-win');
        bjLog(g, '🛡️ 保险赔付 ' + (g.insurance * 3) + '（庄家确为黑杰克）');
      }
      else { bjLog(g, '🛡️ 庄家不是黑杰克，保险金 ' + g.insurance + ' 没收'); }
      g.insuranceTaken = false;
      bjRender();
    }
    // 结算已改为实时写入：每次下注/发牌即从金币扣款、每手/边注/保险赔付实时入账，退出不再统一结算
    if (g.chips < g.baseBet) {
      bjLog(g, '💰 本金不足底注，你已没钱继续，自动离场');
      showToast('💰 金币本金不足底注，自动离场');
      setTimeout(() => {
        if (bjGame === g && g.phase === 'roundEnd') {
          bjEndSession();
          if (bjGame === g) { bjGame = null; renderBjLobby(); }
        }
      }, 1400);
    } else {
      const h0 = g.hands && g.hands[0];
      const scene = h0 && (h0.result === 'win' || h0.result === 'bj') ? 'win' : h0 && h0.result === 'push' ? 'push' : 'lose';
      bjMaybeAutoSpeak(scene);
    }
  }
  function bjNextRound() {
    const g = bjGame;
    if (!g) return;
    g.round++;
    const cfgS = loadBjConfig();
    g.sidePair = !!cfgS.sidePair;
    g.sideT3 = !!cfgS.sideT3;
    g.phase = 'bet';
    bjRender();
  }
  // 弃局（放弃存档）：实时版本退还尚未结算手牌的已扣主注；旧存档把筹码差结算回金币
  function bjSettleSavedAbandon() {
    try {
      const raw = localStorage.getItem(BJ_SAVE_KEY);
      if (!raw) return;
      const d = JSON.parse(raw);
      if (!d) return;
      if (d.realtime === true) {
        // 实时版本：未打完的手牌不判输赢，退还其已扣主注（边注/保险与旧版一致不退还）
        for (const h of (d.hands || [])) {
          const bet = Math.max(0, Math.round(Number(h && h.bet) || 0));
          if (h && !h.done && bet > 0) treasuryAdjust(bet, '21点 · 放弃对局退还未结算主注', 'game-buyin');
        }
        return;
      }
      const chips = Math.max(0, Math.round(Number(d.chips) || 0));
      const start = Number.isFinite(d.sessionStartChips) ? d.sessionStartChips : chips;
      const delta = chips - start;
      if (delta !== 0) treasuryAdjust(delta, '[21点] 弃局结算（旧存档）', delta < 0 ? 'game-lose' : 'game-win');
    } catch (e) { /* ignore */ }
  }
  function bjEndSession() {
    const g = bjGame;
    if (!g || g.recorded) return;
    g.recorded = true;
    g.phase = 'sessionEnd';
    // 💰 实时版：输赢已在每次下注 / 每手结算时实时写回金币，这里不再统一结算；
    //    仅兜底退还未结算手牌的已扣主注（正常在局末所有手牌都已结算）。
    if (g.realtime === true) {
      for (const h of (g.hands || [])) {
        const bet = Math.max(0, Math.round(Number(h && h.bet) || 0));
        if (h && !h.done && bet > 0) {
          treasuryAdjust(bet, '21点 · 未结算主注退还（退出）', 'game-buyin');
          h.done = true;
        }
      }
    }
    const startChips = Number.isFinite(g.sessionStartChips) ? g.sessionStartChips : g.chips;
    const net = Math.round((Number(g.chips) || 0) - startChips);
    const played = Math.max(0, (g.wins || 0) + (g.losses || 0) + (g.pushes || 0));
    if (g.realtime !== true && net !== 0) {
      // 旧版本对局（本次更新前开局）：仍按整场净额统一结算
      treasuryAdjust(net, '[' + (g.tierName || '21点') + '] 21点退出结算（旧存档 · 共 ' + played + ' 手）', net < 0 ? 'game-lose' : 'game-win');
    }
    if (g.realtime !== true) {
      if (net !== 0) showToast('💰 退出结算：金币 ' + (net > 0 ? '+' : '') + net + '（共 ' + played + ' 手）');
