        detail: '共 ' + g.round + ' 局 · 胜 ' + g.wins + ' / 负 ' + g.losses + ' / 平 ' + g.pushes + ' · 牌靴 ' + g.decks + ' 副 · 荷官难度：' + bjDealerLevelName(g.aiLevel),
        players: [{ name: '我', isUser: true, avatar: getMainCharAvatar() }, { name: g.dealerChar.name, isUser: false, avatar: g.dealerChar.avatar || '' }],
