  function bjUserSplit() {
    const g = bjGame;
    if (!g || g.phase !== 'play') return;
    const idx = g.hands.findIndex(x => !x.done);
    const h = g.hands[idx];
    if (!h) return;
    const base = h.cards.filter(c => c && !c.hole);
    if (base.length !== 2 || bjHandValue([base[0]]).total !== bjHandValue([base[1]]).total) { showToast('❌ 只有两张点数相同的牌才能分牌'); return; }
    if (g.hands.length >= 3) { showToast('❌ 最多分牌两次（3 手）'); return; }
