    }).join('');
    const advice = g.phase === 'play' || g.phase === 'insurance' ? bjCurrentAdvice() : null;
    const actName = advice ? ({ hit: '要牌', stand: '停牌', double: '加倍', split: '分牌', insure: '买保险', noinsure: '不买保险' }[advice.act] || advice.act) : '';
    let actions = '';
