        knightDuelUsed: !!game.knightDuelUsed,
        knightPromptActive: !!game.knightPromptActive,
        knightPromptContext: game.knightPromptContext || '',
        knightPromptIsAi: !!game.knightPromptIsAi,
        knightSheriffPromptDone: !!game.knightSheriffPromptDone,
        knightAiAskCount: game.knightAiAskCount || 0,
        boardSize: game.boardSize || game.players.length,
        spectatorNames: (game.spectatorNames || []).slice(),
        spectatorMode: !!game.spectatorMode
      };
      localStorage.setItem(SAVE_GAME_KEY, JSON.stringify(state));
    } catch (e) { /* ignore */ }
  }

  function clearSavedGame() {
    try {
      localStorage.removeItem(SAVE_GAME_KEY);
    } catch (e) { /* ignore */ }
  }

  function hasSavedGame() {
    if (game && !isGameOver && (game.phase === 'night' || game.phase === 'day' || game.phase === 'vote')) {
      return true;
    }
    try {
      const raw = localStorage.getItem(SAVE_GAME_KEY);
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      return parsed && parsed.players && (parsed.players.length === 6 || parsed.players.length === 7 || parsed.players.length === 8 || parsed.players.length === 9 || parsed.players.length === 10 || parsed.players.length === 12) && (parsed.phase === 'night' || parsed.phase === 'day' || parsed.phase === 'vote');
    } catch (e) {
      return false;
    }
  }

  function resumeSavedGame() {
    try {
      if (game && !isGameOver) {
        // 本会话已有进行中的对局：只重绘界面并恢复当前阶段UI（防重复初始化/重复驱动阶段导致跳过发言者）
        renderGameUI();
        resumeCurrentPhase();
        return;
      }
      if (!game || isGameOver) {
        const raw = localStorage.getItem(SAVE_GAME_KEY);
        if (!raw) { renderBoard(); return; }
        const data = JSON.parse(raw);
        currentGameSession++;
        const restoredPlayers = data.players.map(p => ({
          ...p,
          avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name))
        }));
        game = {
          session: currentGameSession,
          spectatorNames: Array.isArray(data.spectatorNames) ? data.spectatorNames.slice() : [],
          spectatorMode: !!data.spectatorMode,
          players: restoredPlayers,
          phase: data.phase,
          day: data.day,
          currentSpeaker: data.currentSpeaker,
          winner: data.winner,
          history: data.history || [],
          historyEntries: data.historyEntries || [],
          userIndex: data.userIndex,
          nightResult: data.nightResult || '',
          nightKill: data.nightKillPos ? restoredPlayers.find(p => p.position === data.nightKillPos) : null,
          nightDeaths: (data.nightDeaths || []).map(d => ({ p: restoredPlayers.find(p => p.position === d.pos), type: d.type })),
          witchAction: data.witchAction,
          witchMenu: false,
          witchMenuReturn: false,
          witchUsedAntidote: !!data.witchUsedAntidote,
          witchUsedPoison: !!data.witchUsedPoison,
          witchSavedPos: data.witchSavedPos,
          seerChecked: data.seerChecked || {},
          votes: data.votes || {},
          replay: data.replay || [],
          pickMode: null,
          pick: { idx: null },
          resolvingFinalWords: null,
          tactics: data.tactics || { ai: '', user: '', custom: '' },
          aiWolfTactics: data.aiWolfTactics || null,
          simNightContext: '',
          isPkVote: !!data.isPkVote,
          aiVotesDone: !!data.aiVotesDone,
          speechesStartedDay: data.speechesStartedDay || 0,
          pkCandidates: (data.pkCandidatesPos || []).map(pos => restoredPlayers.find(p => p.position === pos)).filter(Boolean),
          pkSpeakerQueue: (data.pkSpeakerQueuePos || []).map(pos => restoredPlayers.find(p => p.position === pos)).filter(Boolean),
          pkCurrentSpeakerIdx: data.pkCurrentSpeakerIdx || 0,
          isPkSpeaking: !!data.isPkSpeaking,
          nightStep: data.nightStep || '',
          guardProtectedPos: data.guardProtectedPos || null,
          guardLastPos: data.guardLastPos || null,
          lastWolfKillPos: data.lastWolfKillPos || 0,
          wolfMateChatDone: !!data.wolfMateChatDone,
          wolfNightPhase: data.wolfNightPhase || '',
          wolfNightTalkDone: Array.isArray(data.wolfNightTalkDone) ? data.wolfNightTalkDone.slice() : [],
          wolfNightSpeeches: Array.isArray(data.wolfNightSpeeches) ? data.wolfNightSpeeches.map(x => ({ pos: x.pos, text: x.text })) : [],
          wolfNightDeciderPos: data.wolfNightDeciderPos || 0,
          dayAnnounced: !!data.dayAnnounced,
          sheriffLeadDone: !!data.sheriffLeadDone,
          lastWolfKillDied: !!data.lastWolfKillDied,
          sheriffPos: data.sheriffPos || null,
          sheriffStage: data.sheriffStage || '',
          sheriffDone: !!data.sheriffDone,
          sheriffCandidates: (data.sheriffCandidates || []).slice(),
          sheriffWithdrawn: (data.sheriffWithdrawn || []).slice(),
          sheriffVotes: data.sheriffVotes || {},
          sheriffDirection: data.sheriffDirection || '',
          sheriffDirectionDay: data.sheriffDirectionDay || 0,
          sheriffPkRound: data.sheriffPkRound || 0,
          sheriffPkCandidates: (data.sheriffPkCandidates || []).slice(),
          sheriffPkQueue: (data.sheriffPkQueue || []).slice(),
          sheriffPkIdx: data.sheriffPkIdx || 0,
          sheriffBadgeTorn: !!data.sheriffBadgeTorn,
          sheriffSpeechQueue: (data.sheriffSpeechQueue || []).slice(),
          sheriffSpeechIdx: data.sheriffSpeechIdx || 0,
          sheriffWithdrawQueue: (data.sheriffWithdrawQueue || []).slice(),
          sheriffWithdrawIdx: data.sheriffWithdrawIdx || 0,
          sheriffVoterQueue: (data.sheriffVoterQueue || []).slice(),
          sheriffVoterIdx: data.sheriffVoterIdx || 0,
          sheriffSignDecided: (data.sheriffSignDecided || []).slice(),
          sheriffWithdrawnDecided: (data.sheriffWithdrawnDecided || []).slice(),
          sheriffUserWithdrawDecided: !!data.sheriffUserWithdrawDecided,
          sheriffVotedDecided: (data.sheriffVotedDecided || []).slice(),
          sheriffUserSignDecided: !!data.sheriffUserSignDecided,
          sheriffUserVoted: data.sheriffUserVoted || 0,
          boardVariant: data.boardVariant === 'beauty' ? 'beauty' : (data.boardVariant === 'gods' ? 'gods' : (data.boardVariant === 'guard6' ? 'guard6' : (data.boardVariant === 'wwknight' ? 'wwknight' : (data.boardVariant === 'beauty10' ? 'beauty10' : (data.boardVariant === 'ent8' ? 'ent8' : (data.boardVariant === 'onecut' ? 'onecut' : (data.boardVariant === 'hunter10' ? 'hunter10' : 'classic'))))))),
          judgeName: (data.judgeName && String(data.judgeName) !== '予') ? String(data.judgeName) : '',
          wolfBeautyCharmedPos: data.wolfBeautyCharmedPos || null,
          wolfBeautyLastCharmedPos: data.wolfBeautyLastCharmedPos || 0,
          wolfBeautyChainResolved: !!data.wolfBeautyChainResolved,
          knightDuelUsed: !!data.knightDuelUsed,
          knightPromptActive: !!data.knightPromptActive,
          knightPromptContext: data.knightPromptContext || '',
          knightPromptIsAi: !!data.knightPromptIsAi,
          knightSheriffPromptDone: !!data.knightSheriffPromptDone,
          knightAiAskCount: data.knightAiAskCount || 0,
          boardSize: data.boardSize || (restoredPlayers ? restoredPlayers.length : 6),
          nightToken: 0
        };
        isGameOver = false;
      }
      // 兼容旧存档：法官不能同时作为玩家
      try {
        const resumeJudge = String(game.judgeName || '');
        const resumeUsed = new Set((game.players || []).map(pl => pl.name));
        let resumeFillNo = 1;
        let resumeJudgeReplaced = false;
        (game.players || []).forEach(pl => {
          if (resumeJudge && !pl.isUser && isNameMatch(pl.name, resumeJudge)) {
            let filler = '';
            do { filler = '角色' + (resumeFillNo++); } while (resumeUsed.has(filler) || isNameMatch(filler, resumeJudge));
            resumeUsed.add(filler);
            pl.name = filler;
            pl.avatar = '';
            resumeJudgeReplaced = true;
          }
        });
        if (resumeJudgeReplaced) {
          if (Array.isArray(game.wolfTeammateNames)) game.wolfTeammateNames = game.wolfTeammateNames.filter(n => !isNameMatch(n, resumeJudge));
          if (game.wolfBeautyTeammateName && isNameMatch(game.wolfBeautyTeammateName, resumeJudge)) game.wolfBeautyTeammateName = '';
          showToast('⚖️ 旧存档中法官不能同时作为玩家，已自动补位');
        }
      } catch (e) { /* ignore */ }
      resetWolfBatchGuard();
      renderGameUI();
      resumeCurrentPhase();
    } catch (e) {
      console.error('[狼人杀恢复对局失败]', e);
      clearSavedGame();
      renderBoard();
    }
  }

  function resumeCurrentPhase() {
    if (!game || isGameOver) return;
    if (game.nightToken === undefined) game.nightToken = 0;
    // 后台等待玩家遗言：重进时直接恢复遗言输入界面，不重跑其它流程
    if (typeof game.resolvingFinalWords === 'function') {
      showUserFinalWordsUI();
      return;
    }
    if (game.knightPromptActive) {
      if (game.phase === 'day') { resumeKnightPrompt(); return; }
      game.knightPromptActive = false;
      game.knightPromptContext = '';
      game.knightPromptIsAi = false;
    }
    if (game.phase === 'night') {
      // 按夜晚子步骤续跑，避免重进后验人/刀人/用药整晚重跑
      const step = game.nightStep || 'guard';
      if (step === 'guard') stepGuardAction();
      else if (step === 'wolf') stepWolfAction();
      else if (step === 'wolfbeauty') stepWolfBeautyAction();
      else if (step === 'seer') stepSeerAction();
      else if (step === 'witch') stepWitchAction();
      else if (step === 'end') finishNightAndStartDay();
      else runNightSequence();
    } else if (game.phase === 'day') {
      if (typeof game.currentSpeaker !== 'number' || game.currentSpeaker < 0 || game.currentSpeaker >= game.players.length) game.currentSpeaker = 0;
      // PK 辩解阶段仍处于 day：恢复 PK 进度而不是重开白天发言
      if (game.isPkSpeaking && game.pkCandidates && game.pkCandidates.length) runNextPkSpeaker();
      else if (game.sheriffStage && game.sheriffStage !== 'done') resumeSheriffStage();
      else if (!game.dayAnnounced) afterSheriffElection(!!(game.sheriffPos && !game.sheriffBadgeTorn));
      // 今天尚未开始发言（如警长方向思考中断在重启中丢失）：重新进入方向决定/发言初始化，避免直接续跑导致整轮发言被跳过
      else if (game.speechesStartedDay !== game.day) afterSheriffElection(!!(game.sheriffPos && !game.sheriffBadgeTorn));
      else {
        const cur = game.players[game.currentSpeaker];
        if (!cur || !cur.alive || cur.hasSpoken) nextSpeaker();
        else startSpeaking();
      }
    } else if (game.phase === 'vote') {
      if (game.isPkVote) {
        startPkVote();
      } else {
        startVote();
      }
    }
  }

  // ========== 游戏状态与会话隔离机制 ==========
  let currentGameSession = 0;
  let game = null;
  let wolfBoardTab = null;
  let isGameOver = false;
  let replayLogs = [];
  let replayPlayersSnapshot = [];
  let wolfDiscussion = null; // 狼人杀终局讨论状态：{ session, messages: [{role,pos,name,text}], busy }
  let overlay = null;
  let sheet = null;
  let identityPackOpen = false;

  function getConfiguredJudgeName() {
    try {
      const cfg = loadConfig();
      return cfg.wolfJudgeEnabled === true ? String(cfg.wolfJudgeName || '').trim() : '';
    } catch (e) { return ''; }
  }
  function getActiveJudgeName() {
    if (game) {
      const n = String(game.judgeName || '').trim();
      return n === '予' ? '' : n;
    }
    return getConfiguredJudgeName();
  }

  function isSessionValid(session) {
    return !!game && game.session === session && !isGameOver;
  }

  // ========== 桌面「游戏」图标注入（玉子手机主页 .phone-app-grid） ==========
  // 玉子手机主页每次渲染都会重建 grid，注入在 ensureIconPermanent 与 MutationObserver 中反复兜底；
  // 图标样式沿用玉子「桌面单字图标」规范（色块瓷片 + 单字），名称「游戏」。
  let iconPermanentTimer = null;

  const YUZI_GAME_APP_ID = 'yuzi-game-ext';
  const YUZI_GAME_APP_NAME = '游戏';
  const YUZI_GAME_ICON_START = '#8B5CF6';
  const YUZI_GAME_ICON_END = '#4C1D95';

  function gameIconInnerHTML() {
    // 渐变紫瓷片 + 高光 + 白色手柄线稿 + 星芒；随玉子「桌面图标」圆角与尺寸自适应。
    return '<div class="phone-app-icon-svg" style="position:relative;overflow:hidden;border-radius:inherit;' +
        'background:linear-gradient(145deg,' + YUZI_GAME_ICON_START + ' 0%,#6D28D9 55%,' + YUZI_GAME_ICON_END + ' 100%);' +
        'box-shadow:0 5px 12px rgba(76,29,149,.38),inset 0 1px 0 rgba(255,255,255,.28);">' +
      '<div style="position:absolute;inset:0;background:radial-gradient(120% 90% at 20% 8%,rgba(255,255,255,.42),rgba(255,255,255,0) 48%);pointer-events:none;"></div>' +
      '<div style="position:absolute;left:0;right:0;bottom:0;height:46%;background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,.16));pointer-events:none;"></div>' +
      '<svg viewBox="0 0 48 48" width="100%" height="100%" aria-hidden="true" focusable="false" style="position:relative;display:block;filter:drop-shadow(0 2px 3px rgba(0,0,0,.30));">' +
        '<path d="M35.2 12.4l.85 2.05 2.05.85-2.05.85-.85 2.05-.85-2.05-2.05-.85 2.05-.85z" fill="#FDE68A" opacity="0.95"/>' +
        '<path d="M17 16.8h14c4.6 0 8.3 3.7 8.3 8.3 0 3.2-.7 5.6-2 6.7-1.5 1.3-3.6.9-5.1-.7l-2.4-2.6c-.5-.55-1.2-.85-1.9-.85h-7.8c-.75 0-1.45.3-1.95.85l-2.4 2.6c-1.5 1.6-3.6 2-5.1.7-1.3-1.1-2-3.5-2-6.7 0-4.6 3.7-8.3 8.3-8.3z" fill="none" stroke="#FFFFFF" stroke-width="2.5" stroke-linejoin="round"/>' +
        '<g fill="#FFFFFF">' +
          '<rect x="14.6" y="19.8" width="2.5" height="7.6" rx="1.25"/>' +
          '<rect x="12.05" y="22.35" width="7.6" height="2.5" rx="1.25"/>' +
          '<circle cx="31.1" cy="21.9" r="1.85"/>' +
          '<circle cx="34.7" cy="24.9" r="1.85" opacity="0.9"/>' +
        '</g>' +
        '<circle cx="26.9" cy="26.9" r="1.15" fill="rgba(255,255,255,.55)"/>' +
