  }

  function addGameIcon() {
    const sr = getShadowRoot();
    if (!sr) return false;
    const grid = sr.querySelector('.phone-app-grid');
    if (!grid) return false;
    if (grid.querySelector('[data-yuzi-game-app="game"]')) return true;
    const node = document.createElement('div');
    node.className = 'phone-app-item';
    node.dataset.sheetKey = YUZI_GAME_APP_ID;
    node.setAttribute('data-yuzi-game-app', 'game');
    node.setAttribute('role', 'button');
    node.setAttribute('tabindex', '0');
    node.setAttribute('aria-label', YUZI_GAME_APP_NAME);
    node.draggable = false;
    node.style.webkitTapHighlightColor = 'transparent';
    node.style.touchAction = 'manipulation';
    node.style.userSelect = 'none';
    node.innerHTML = '<div class="phone-app-icon">' + gameIconInnerHTML() + '</div>' +
      '<span class="phone-app-label">' + YUZI_GAME_APP_NAME + '</span>';
    // 始终注入主页网格最后一格（主页重绘后也会被观察器补回末尾）
    grid.appendChild(node);
    return true;
  }

  // ========== 玉子手机没有内置「游戏入口」页：桌面「游戏」图标就是入口（保留空实现兼容旧调用） ==========
  function injectGameCenterExtension() {
    return false;
  }

  // ========== 打开游戏层时：隐藏手机状态栏（时间 / 信号 / Wi-Fi / 电量）并锁定页面滚动 ==========
  function setYuziStatusBarHidden(hidden) {
    const sr = getShadowRoot();
    if (!sr) return;
    const bar = sr.querySelector('.yuzi-phone-status-bar');
    if (!bar) return;
    if (hidden) {
      if (bar.getAttribute('data-yuzi-game-status-hidden') !== '1') {
        bar.setAttribute('data-yuzi-game-status-prev-display', bar.style.display || '');
        bar.setAttribute('data-yuzi-game-status-hidden', '1');
      }
      if (bar.style.display !== 'none') bar.style.display = 'none';
    } else if (bar.getAttribute('data-yuzi-game-status-hidden') === '1') {
      bar.style.display = bar.getAttribute('data-yuzi-game-status-prev-display') || '';
      bar.removeAttribute('data-yuzi-game-status-hidden');
      bar.removeAttribute('data-yuzi-game-status-prev-display');
    }
  }

  function syncOverlayBackdrop() {
    const sr = getShadowRoot();
    if (!sr) return;
    const overlayEl = sr.querySelector('.ubp-game-overlay');
    if (!overlayEl) {
      setYuziStatusBarHidden(false);
      return;
    }
    setYuziStatusBarHidden(true);
    const page = sr.querySelector('.yuzi-phone-screen > .phone-page');
    if (page && page.style.overflow !== 'hidden') {
      page.dataset.yuziGamePrevOverflow = page.style.overflow || '';
      page.style.overflow = 'hidden';
    }
  }

  function closeGameOverlay() {
    if (slotAnimTimer) { clearInterval(slotAnimTimer); slotAnimTimer = null; }
    if (slotMachine && slotMachine.spinning) { slotMachine.spinning = false; slotSaveChances(slotLoadChances() + 1); }
    const sr = getShadowRoot();
    if (!sr) return;
    const ov = sr.querySelector('.ubp-game-overlay');
    if (ov) ov.remove();
    setYuziStatusBarHidden(false);
    const page = sr.querySelector('.yuzi-phone-screen > .phone-page');
    if (page && page.dataset && Object.prototype.hasOwnProperty.call(page.dataset, 'yuziGamePrevOverflow')) {
      page.style.overflow = page.dataset.yuziGamePrevOverflow || '';
      delete page.dataset.yuziGamePrevOverflow;
    }
  }

  function ensureIconPermanent() {
    addGameIcon();
    setupPermanentShadowObserver();
    injectGameCenterExtension();
    syncOverlayBackdrop();
  }

  // 玉子手机容器上的兜底观察：主页重绘 / 路由切换后补回「游戏」图标，并绑定一次点击代理。
  function setupPermanentShadowObserver() {
    const docs = [document, window.parent?.document, window.top?.document].filter(Boolean);
    for (const doc of docs) {
      try {
        const el = doc.getElementById(YUZI_PHONE_CONTAINER_ID);
        if (!el || el._yuzi_game_observer_attached) continue;
        el._yuzi_game_observer_attached = true;
        setupGameCenterClickHandler(el);
        const observer = new MutationObserver(() => {
          addGameIcon();
          setupGameCenterClickHandler(el);
        });
        observer.observe(el, { childList: true, subtree: true });
      } catch (e) { /* ignore */ }
    }
  }

  // 点击代理：桌面「游戏」图标 → 打开扩展界面；点手机 home 条 → 收起游戏层。
  // 说明：玉子手机主页可能随时重绘（图标节点被替换），且脚本可能运行在父/子窗口，
  // 因此不使用 instanceof Element，并同时监听 pointerdown/pointerup 与 click：
  //   · pointerdown 命中图标后记录起点，pointerup 位移 < 16px 且 < 0.9s 即视为点按；
  //   · click 作为键盘/鼠标兜底，并用时间戳去重，避免同一次点按重复开层；
  //   · 位移过大（滚动/拖动）时吞掉随后的 click，避免误开。
  let yuziGameTapOpenedAt = 0;
  function openGameFromIcon(e) {
    const now = Date.now();
    if (now - yuziGameTapOpenedAt < 450) {
      try { if (e) { e.preventDefault(); e.stopPropagation(); } } catch (err) { /* ignore */ }
      return true;
    }
    yuziGameTapOpenedAt = now;
    try { if (e) { e.preventDefault(); e.stopPropagation(); } } catch (err) { /* ignore */ }
    try { openGameApp(); } catch (err) { console.warn('[玉子游戏扩展] 打开游戏界面失败:', err); }
    return true;
  }

  function setupGameCenterClickHandler(sr) {
    if (!sr || sr.__yuzi_game_click_bound) return;
    sr.__yuzi_game_click_bound = true;
    const isElementNode = (node) => !!(node && node.nodeType === 1 && typeof node.closest === 'function');
    const isGameIcon = (node) => {
      try { return !!(node && typeof node.closest === 'function' && node.closest('[data-yuzi-game-app="game"]')); } catch (e) { return false; }
    };
    let tapStart = null;
    let swallowClickUntil = 0;

    sr.addEventListener('pointerdown', (e) => {
      if (isGameIcon(e.target)) {
        tapStart = { x: Number(e.clientX) || 0, y: Number(e.clientY) || 0, t: Date.now(), id: e.pointerId };
      } else {
        tapStart = null;
      }
    }, true);

    sr.addEventListener('pointerup', (e) => {
      const start = tapStart;
      tapStart = null;
      if (!start) return;
      if (start.id !== undefined && e.pointerId !== undefined && start.id !== e.pointerId) return;
      const dx = (Number(e.clientX) || 0) - start.x;
      const dy = (Number(e.clientY) || 0) - start.y;
      if (Math.sqrt(dx * dx + dy * dy) > 16) { swallowClickUntil = Date.now() + 400; return; }
      if (Date.now() - start.t > 900) return;
      swallowClickUntil = Date.now() + 600;
      openGameFromIcon(e);
    }, true);

    sr.addEventListener('pointercancel', () => { tapStart = null; }, true);

    sr.addEventListener('click', (e) => {
      const target = e.target;
      if (!isElementNode(target)) return;
      if (isGameIcon(target)) {
        if (Date.now() < swallowClickUntil) {
          try { e.preventDefault(); e.stopPropagation(); } catch (err) { /* ignore */ }
          return;
        }
        openGameFromIcon(e);
        return;
      }
      if (target.closest('[data-yuzi-phone-home-indicator]') && sr.querySelector('.ubp-game-overlay')) {
        closeGameOverlay();
      }
    }, true);

    sr.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
      if (isGameIcon(e.target)) openGameFromIcon(e);
    }, true);
  }

  // ========== 主界面控制：铺满整个玉子手机屏幕 ==========
  function openGameApp() {
    if (slotAnimTimer) { clearInterval(slotAnimTimer); slotAnimTimer = null; }
    if (slotMachine && slotMachine.spinning) { slotMachine.spinning = false; slotSaveChances(slotLoadChances() + 1); }
    const sr = getShadowRoot();
    if (!sr) return;
    if (sr.querySelector('.ubp-game-overlay')) return;
    const old = sr.querySelector('.ubp-game-overlay');
    if (old) old.remove();
    overlay = document.createElement('div');
    overlay.className = 'ubp-game-overlay';
    // 玉子手机：游戏层挂到 .yuzi-phone-screen（position:relative; overflow:hidden），铺满屏幕；
    // 手机状态栏与 home 条位于屏幕层之上，保持可见。--ubp-* 固定为深色游戏配色，避免浅色主题串色。
    overlay.style.cssText = 'position:absolute;inset:0;z-index:50;background:#0f0f12;display:flex;flex-direction:column;padding:0;margin:0;width:100%;height:100%;overflow:hidden;box-sizing:border-box;' +
      '--ubp-bg:#0f0f12;--ubp-card:#1c1c20;--ubp-card-2:#26262a;--ubp-line:rgba(255,255,255,0.12);--ubp-text:#f2f2f7;--ubp-text-2:rgba(242,242,247,0.78);--ubp-text-3:rgba(242,242,247,0.55);--ubp-accent:#8B5CF6;';
    const baseStyle = document.createElement('style');
    baseStyle.setAttribute('data-yuzi-game-base-style', '1');
    baseStyle.textContent = YUZI_GAME_BASE_CSS;
    overlay.appendChild(baseStyle);
    sheet = document.createElement('div');
    sheet.className = 'ubp-sheet';
    sheet.style.cssText = 'width:100%;height:100%;max-width:100%;max-height:100%;border-radius:0;background:var(--ubp-card, #1c1c20);' +
      'padding:calc((var(--yuzi-phone-status-safe-height, 62px) - var(--yuzi-phone-dynamic-island-height, 24px)) / 2 + var(--yuzi-phone-dynamic-island-height, 24px) + 2px) 10px 8px;' +
      'box-sizing:border-box;display:flex;flex-direction:column;overflow-y:auto;position:relative;flex:1;min-height:0;';
    overlay.appendChild(sheet);
    const screenHost = sr.querySelector('.yuzi-phone-screen') || sr;
    screenHost.appendChild(overlay);
    syncOverlayBackdrop();
    renderSetup();
    ubLoadStatusbarStorage().catch(() => {});
    // 按钮功能提示：鼠标悬停用原生 title；触屏长按 600ms 弹出该按钮/条目的功能说明
    let lpTipTimer = null, lpTipEl = null, lpTipShownAt = 0, lpTipNode = null;
    const hideLpTip = () => {
      if (lpTipTimer) { clearTimeout(lpTipTimer); lpTipTimer = null; }
      if (lpTipNode) { try { lpTipNode.remove(); } catch (err) { /* ignore */ } lpTipNode = null; }
    };
    overlay.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'mouse') return;
      const el = e.target && e.target.closest ? e.target.closest('[title]') : null;
      if (!el) return;
      const tipText = el.getAttribute('title');
      if (!tipText) return;
      lpTipEl = el;
      lpTipTimer = setTimeout(() => {
        lpTipTimer = null;
        if (lpTipEl !== el) return;
        const tip = document.createElement('div');
        let left = 10, top = 10;
        try {
          const rect = el.getBoundingClientRect();
          const vw2 = window.innerWidth || 360, vh2 = window.innerHeight || 640;
          left = Math.max(8, Math.min(vw2 - 236, rect.left + rect.width / 2 - 118));
          top = rect.bottom + 8;
          if (top + 90 > vh2) top = Math.max(8, rect.top - 96);
        } catch (err) { /* ignore */ }
        tip.style.cssText = 'position:fixed;left:' + left + 'px;top:' + top + 'px;z-index:2147483200;width:236px;box-sizing:border-box;background:rgba(0,0,0,0.92);color:#fff;border-radius:8px;padding:8px 10px;font-size:11.5px;line-height:1.5;pointer-events:none;white-space:pre-wrap;';
        tip.textContent = tipText;
        document.body.appendChild(tip);
        lpTipNode = tip;
        lpTipShownAt = Date.now();
      }, 600);
    }, { passive: true });
    overlay.addEventListener('pointerup', () => {
      if (lpTipTimer) { clearTimeout(lpTipTimer); lpTipTimer = null; }
      setTimeout(hideLpTip, 2400);
    }, { passive: true });
    overlay.addEventListener('pointercancel', hideLpTip, { passive: true });
    overlay.addEventListener('pointermove', () => { if (lpTipTimer) { clearTimeout(lpTipTimer); lpTipTimer = null; } }, { passive: true });
    overlay.addEventListener('click', (e) => {
      // 长按查看功能说明后抑制随后的误触点击
      if (lpTipShownAt && Date.now() - lpTipShownAt < 700) {
        lpTipShownAt = 0;
        hideLpTip();
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      const ubTarget = e.target.closest('[data-ubp-act]');
      if (ubTarget) {
        const act = ubTarget.dataset.ubpAct;
        handleAction(act, ubTarget);
        return;
      }
const bgTarget = e.target.closest('[data-bg-act]');
      if (bgTarget) {
        const bgAct = bgTarget.dataset.bgAct;
        handleBoardAction(bgAct, bgTarget);
        return;
      }
      const spyTarget = e.target.closest('[data-spy-act]');
      if (spyTarget) {
        const spyAct = spyTarget.dataset.spyAct;
        handleSpyAction(spyAct, spyTarget);
        return;
      }
      const rpsTarget = e.target.closest('[data-rps-act]');
      if (rpsTarget) {
        const rpsAct = rpsTarget.dataset.rpsAct;
        handleRpsAction(rpsAct, rpsTarget);
        return;
      }
      const tttTarget = e.target.closest('[data-ttt-act]');
      if (tttTarget) {
        const tttAct = tttTarget.dataset.tttAct;
        handleTttAction(tttAct, tttTarget);
        return;
      }
      const bjTarget = e.target.closest('[data-bj-act]');
      if (bjTarget) {
        const bjAct = bjTarget.dataset.bjAct;
        handleBjAction(bjAct, bjTarget);
        return;
      }
      const unoTarget = e.target.closest('[data-uno-act]');
      if (unoTarget) {
        const unoAct = unoTarget.dataset.unoAct;
        handleUnoAction(unoAct, unoTarget);
        return;
      }
      const ddzTarget = e.target.closest('[data-ddz-act]');
      if (ddzTarget) {
        const ddzAct = ddzTarget.dataset.ddzAct;
        handleDDZAction(ddzAct, ddzTarget);
        return;
      }
      const rmTarget = e.target.closest('[data-rm-act]');
      if (rmTarget) {
        const rmAct = rmTarget.dataset.rmAct;
        handleRmAction(rmAct, rmTarget);
        return;
      }
      const ludoTarget = e.target.closest('[data-ludo-act]');
      if (ludoTarget) {
        const ludoAct = ludoTarget.dataset.ludoAct;
        handleLudoAction(ludoAct, ludoTarget);
        return;
      }
      const lieTarget = e.target.closest('[data-lie-act]');
      if (lieTarget) {
        const lieAct = lieTarget.dataset.lieAct;
        handleLieAction(lieAct, lieTarget);
        return;
      }
      const llkTarget = e.target.closest('[data-llk-act]');
      if (llkTarget) {
        const llkAct = llkTarget.dataset.llkAct;
        handleLLKAction(llkAct, llkTarget);
        return;
      }
      const xxlTarget = e.target.closest('[data-xxl-act]');
      if (xxlTarget) {
        const xxlAct = xxlTarget.dataset.xxlAct;
        handleXXLAction(xxlAct, xxlTarget);
        return;
      }
      const mjTarget = e.target.closest('[data-mj-act]');
      if (mjTarget) {
        const mjAct = mjTarget.dataset.mjAct;
        handleMjAction(mjAct, mjTarget);
        return;
      }
      const zjhTarget = e.target.closest('[data-zjh-act]');
      if (zjhTarget) {
        const zjhAct = zjhTarget.dataset.zjhAct;
        handleZjhAction(zjhAct, zjhTarget);
        return;
      }
      const thTarget = e.target.closest('[data-th-act]');
      if (thTarget) {
        const thAct = thTarget.dataset.thAct;
        handleTHAction(thAct, thTarget);
        return;
      }
    });
  }

