      el.addEventListener('contextmenu', (e) => { e.preventDefault(); msToggleFlag(parts[0], parts[1]); });
      el.addEventListener('touchstart', () => { lp = setTimeout(() => { lp = null; lpAt = Date.now(); msToggleFlag(parts[0], parts[1]); }, 450); }, { passive: true });
      el.addEventListener('touchend', () => { if (lp) { clearTimeout(lp); lp = null; } });
    });
  }
