  };
  const SF_WEAPON_KEYS = ['double', 'spread', 'gatling', 'homing', 'laser', 'railgun', 'cannon', 'pierce'];
  const SF_WEAPON_PROFILES = {
    double: { kind: 'bullet', count: 2, spread: 0, damage: 0.8, gap: 0.16, speed: 1.16, r: 0.0065, color: '#67E8F9', color2: '#38BDF8', shape: 'bolt' },
