    laser: { kind: 'beam', laserDps: 10, beamCount: 1, width: 0.008, color: '#22D3EE', color2: '#A5F3FC', pierce: true },
    railgun: { kind: 'beam', railDamage: 30, chargeSec: 1.2, cooldown: 2.1, beamCount: 1, width: 0.024, color: '#C084FC', color2: '#E9D5FF', pierce: true },
    cannon: { kind: 'bullet', count: 1, damage: 2.4, gap: 0.46, speed: 0.8, r: 0.014, color: '#F59E0B', color2: '#FCD34D', shape: 'shell', explosive: true, splash: 0.075 },
    pierce: { kind: 'bullet', count: 1, damage: 1.2, gap: 0.2, speed: 1.3, r: 0.008, color: '#A3E635', color2: '#D9F99D', shape: 'triangle', pierce: true }
  };
  const SF_BASE_PROFILE = { kind: 'bullet', name: '基础机炮', count: 1, spread: 0, damage: 1, gap: 0.18, speed: 1.16, r: 0.0065, color: '#67E8F9', color2: '#38BDF8', shape: 'bolt', base: true };
  const SF_ENEMY_DEFS = {
    scout: { hp: 2, speed: 0.115, r: 0.038, score: 120, fire: 2.2, color: '#FB7185', name: '侦察机' },
    dart: { hp: 1, speed: 0.24, r: 0.030, score: 180, fire: 1.8, color: '#FDE047', name: '突击机' },
    elite: { hp: 8, speed: 0.055, r: 0.060, score: 420, fire: 2.8, color: '#C084FC', name: '重甲精英' }
  };
  const SF_ITEM_DEFS = {
    heal: { color: '#FB7185', color2: '#F43F5E', name: '回血', icon: 'heart' },
    shield: { color: '#38BDF8', color2: '#0284C7', name: '护盾', icon: 'shield' },
    bomb: { color: '#FBBF24', color2: '#D97706', name: '清屏炸弹', icon: 'bomb' },
    weapon: { color: '#A78BFA', color2: '#22D3EE', name: '武器', icon: 'weapon' }
  };
  // 音效加载位置：后续可把函数赋给对应字段，例如：
  // SF_SFX.shoot = (vol) => { const a = new Audio('...'); a.volume = vol || 0.5; a.play(); };
  // 本项目不引用外部资源；没有赋值时 sfPlaySfx 自动静默。
  const SF_SFX = {
    shoot: null, enemyShoot: null, hit: null, explode: null, pickup: null,
    bomb: null, bossWarn: null, bossHit: null, bossExplode: null, playerHit: null, gameOver: null
  };
  // 图片加载位置：后续把 Image 赋给对应字段即可；为空时使用几何图形绘制。
  // SF_ART.player = img; SF_ART.boss = img; SF_ART.enemy.scout = img; ...
  const SF_ART = { player: null, boss: null, enemy: {}, item: {}, background: null };

  // ---- 基础工具 / 音效接口 ----
  let sfGame = null;
  const sfRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const sfCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function sfPlaySfx(name, volume) {
    const fn = SF_SFX[name];
    if (typeof fn === 'function') { try { fn(volume === undefined ? 0.5 : volume); } catch (e) { /* ignore */ } }
  }
  function sfClamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function sfRand(a, b) { return a + Math.random() * (b - a); }
  function sfNow() { return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now(); }
  function sfHitCircle(x1, y1, r1, x2, y2, r2) {
    const dx = x1 - x2, dy = y1 - y2, rr = r1 + r2;
    return dx * dx + dy * dy <= rr * rr;
  }
  function sfLoadBest() {
    try { const n = parseInt(localStorage.getItem(SF_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function sfSaveBest(n) {
    try { if (Number(n) > sfLoadBest()) localStorage.setItem(SF_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function sfHasSave() {
    try {
      const raw = localStorage.getItem(SF_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && d.v === 1 && d.player && Number(d.player.hp) > 0 && (Number(d.score) > 0 || Number(d.time) > 2));
    } catch (e) { return false; }
  }
  function sfLoadSave() {
    try {
      const raw = localStorage.getItem(SF_SAVE_KEY);
      if (!raw) return null;
      const d = JSON.parse(raw);
      if (!d || d.v !== 1 || !d.player || Number(d.player.hp) <= 0) return null;
      return d;
    } catch (e) { return null; }
  }
  function sfClearSave() { try { localStorage.removeItem(SF_SAVE_KEY); } catch (e) { /* ignore */ } }
  // ---- 检查点存档 ----
  function sfSaveGame(g) {
    if (!g || g.over) { sfClearSave(); return false; }
    if (g.time < 1.5) {
      if (!sfHasSave()) { sfClearSave(); return false; }
      return true;
    }
    try {
      const data = {
        v: 1,
        score: Math.floor(g.score),
        nextPointAt: g.nextPointAt,
        time: g.time,
        wave: g.wave,
        bossIndex: g.bossIndex,
        bossKills: g.bossKills,
        kills: g.kills,
        bossT: g.bossT,
        player: {
          hp: g.player.hp,
          shield: g.player.shield,
          bombs: g.player.bombs,
          weapons: (g.player.weapons || []).slice(0, 2).map(w => ({
            type: w.type,
            remain: Math.max(0, Math.round((w.expiresAt - g.time) * 10) / 10)
          }))
        },
        savedAt: Date.now()
      };
      localStorage.setItem(SF_SAVE_KEY, JSON.stringify(data));
      sfSaveBest(g.score);
      return true;
    } catch (e) { return false; }
  }

  function sfNewGame(save) {
    const g = {
      W: 360, H: 640,
      score: 0, best: sfLoadBest(), time: 0, diff: 1, wave: 1,
      nextPointAt: SF_POINT_STEP, kills: 0, bossKills: 0, bossIndex: 0,
      player: {
        x: 180, y: 520, targetX: 180, targetY: 520, prevX: 180, r: 13,
        hp: SF_MAX_HP, maxHp: SF_MAX_HP, shield: 0, weapons: [], bombs: 2,
        fireT: 0.35, railCharge: 0, invuln: 1.4, tilt: 0, exhaustT: 0
      },
      enemies: [], bullets: [], enemyBullets: [], items: [],
      particles: [], rings: [], texts: [], playerBeams: [], enemySeq: 0,
      boss: null, bossWarnT: 0, bossT: SF_BOSS_INTERVAL,
      spawnT: 0.8, autosaveT: 10, bgShift: 0, domT: 0,
      stars: [], nebulas: [], shake: 0, flash: 0,
      over: false, overT: 0, stopped: false, _firstDraw: true,
      keys: { left: false, right: false, up: false, down: false },
      input: { mode: 'pointer', pointerActive: false, pointerType: 'mouse', offsetX: 0, offsetY: 0 },
      canvas: null, stageEl: null, ctx: null, rafId: 0, lastTs: 0,
      doc: null, keyHandler: null, keyUpHandler: null, pointerBindings: null,
      _onWinResize: null, overTimer: null
    };
    if (save) {
      g.score = Math.max(0, Math.round(Number(save.score) || 0));
      g.nextPointAt = Math.max(SF_POINT_STEP, Number(save.nextPointAt) || SF_POINT_STEP);
      g.time = Math.max(0, Number(save.time) || 0);
      g.wave = Math.max(1, Number(save.wave) || 1);
      g.bossIndex = Math.max(0, Number(save.bossIndex) || 0);
      g.bossKills = Math.max(0, Number(save.bossKills) || 0);
      g.kills = Math.max(0, Number(save.kills) || 0);
      g.bossT = sfClamp(Number(save.bossT) || SF_BOSS_INTERVAL, 10, SF_BOSS_INTERVAL);
      const sp = save.player || {};
      g.player.hp = sfClamp(Math.round(Number(sp.hp) || SF_MAX_HP), 1, SF_MAX_HP);
      g.player.shield = sfClamp(Math.round(Number(sp.shield) || 0), 0, SF_MAX_SHIELD);
      g.player.bombs = sfClamp(Math.round(Number(sp.bombs) || 0), 0, SF_MAX_BOMBS);
      const savedWeapons = Array.isArray(sp.weapons) ? sp.weapons : [];
      let remains = [];
      for (const w of savedWeapons) {
        if (!w || !SF_WEAPON_PROFILES[w.type]) continue;
        const remain = sfClamp(Number(w.remain) || 0, 0, SF_WEAPON_DURATION);
        if (remain > 0) remains.push({ type: w.type, remain });
        if (remains.length >= 2) break;
      }
      if (remains.length === 2) {
        const maxRemain = Math.max(remains[0].remain, remains[1].remain);
        remains = remains.map(w => ({ type: w.type, remain: maxRemain }));
      }
      if (remains.length) {
        g.player.weapons = remains.map(w => ({ type: w.type, expiresAt: g.time + w.remain }));
      } else {
        const legacy = Number(sp.weapon) || 1;
        if (legacy >= 2) {
          const legacyType = legacy >= 3 ? 'spread' : 'double';
          g.player.weapons = [{ type: legacyType, expiresAt: g.time + SF_WEAPON_DURATION }];
        }
      }
      g.best = Math.max(g.best, g.score);
    }
    g.diff = Math.min(4, 1 + g.score / 3500);
    return g;
  }

  function sfPlacePlayer(g) {
    const p = g.player;
    p.r = Math.max(9, Math.min(16, Math.min(g.W, g.H) * 0.036));
    p.x = sfClamp(g.W * 0.5, p.r * 1.5, g.W - p.r * 1.5);
    p.y = g.H * 0.82;
    p.targetX = p.x; p.targetY = p.y; p.prevX = p.x;
  }

  // ---- 生命周期 / 界面 ----
  function sfOpenGame(saveData) {
    sfTeardown(false);
    if (!sheet) { renderMiniGameLobby(); return; }
    if (!saveData) sfClearSave();
    const g = sfNewGame(saveData);
    sfGame = g;
    sfRenderUI(g);
    sfPlacePlayer(g);
    sfAttachInput(g);
    sfUpdateDomHud(g);
    g.lastTs = sfNow();
    g.rafId = sfRaf(sfTick);
