    } catch (e) { /* ignore */ }
  }

  // ---- 输入：鼠标 / 触屏拖动 / 键盘 ----
  function sfAttachInput(g) {
    if (!g || !g.canvas) return;
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    const setKey = (k, v) => {
      if (k === 'ArrowLeft' || k === 'a' || k === 'A') g.keys.left = v;
      else if (k === 'ArrowRight' || k === 'd' || k === 'D') g.keys.right = v;
      else if (k === 'ArrowUp' || k === 'w' || k === 'W') g.keys.up = v;
      else if (k === 'ArrowDown' || k === 's' || k === 'S') g.keys.down = v;
      else return false;
      g.input.mode = 'key';
      return true;
    };
    g.keyHandler = (e) => {
      const t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable)) return;
      const k = e.key;
      if (k === 'b' || k === 'B') { e.preventDefault(); if (!e.repeat) sfUseBomb(); return; }
      if (setKey(k, true)) e.preventDefault();
    };
    g.keyUpHandler = (e) => { setKey(e.key, false); };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    try { doc.addEventListener('keyup', g.keyUpHandler); } catch (e) { /* ignore */ }

    const cv = g.canvas;
    const rectOf = () => { try { return cv.getBoundingClientRect(); } catch (e) { return { left: 0, top: 0, width: g.W, height: g.H }; } };
    const pointOf = (e) => { const r = rectOf(); return { x: (e.clientX || 0) - r.left, y: (e.clientY || 0) - r.top }; };
    const clampTarget = () => {
      const p = g.player;
      p.targetX = sfClamp(p.targetX, g.W * 0.055, g.W * 0.945);
      p.targetY = sfClamp(p.targetY, g.H * 0.14, g.H * 0.93);
    };
    const onDown = (e) => {
      if (e.preventDefault) e.preventDefault();
      const pt = pointOf(e);
      g.input.pointerActive = true;
      g.input.pointerType = e.pointerType || 'touch';
      if (g.input.pointerType === 'mouse') {
        g.player.targetX = pt.x;
        g.player.targetY = pt.y;
      } else {
        g.input.offsetX = g.player.x - pt.x;
        g.input.offsetY = g.player.y - pt.y;
        g.player.targetX = pt.x + g.input.offsetX;
        g.player.targetY = pt.y + g.input.offsetY;
      }
      clampTarget();
      g.input.mode = 'pointer';
      try { if (e.pointerId !== undefined) cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
    };
    const onMove = (e) => {
      const pt = pointOf(e);
      const isMouse = (e.pointerType || (e.type === 'mousemove' ? 'mouse' : 'touch')) === 'mouse';
      if (isMouse) {
        g.player.targetX = pt.x;
        g.player.targetY = pt.y;
        g.input.mode = 'pointer';
        clampTarget();
      } else if (g.input.pointerActive) {
        if (e.preventDefault) e.preventDefault();
        g.player.targetX = pt.x + g.input.offsetX;
        g.player.targetY = pt.y + g.input.offsetY;
        g.input.mode = 'pointer';
        clampTarget();
      }
    };
    const onUp = () => { g.input.pointerActive = false; };
    const onBombButtonEnter = (e) => {
      const pt = (e && e.pointerType) || (e && e.type === 'mouseenter' ? 'mouse' : '');
      if (pt === 'mouse' && sfGame) sfUseBomb();
    };
    const bombButton = sheet ? sheet.querySelector('[data-ubp-act="star-bomb"]') : null;
    g.pointerBindings = [];
    const bind = (el, ev, fn) => { try { el.addEventListener(ev, fn, { passive: false }); g.pointerBindings.push([el, ev, fn]); } catch (e) { /* ignore */ } };
    bind(cv, 'contextmenu', (e) => e.preventDefault());
    if (typeof window.PointerEvent !== 'undefined') {
      bind(cv, 'pointerdown', onDown);
      bind(cv, 'pointermove', onMove);
      bind(cv, 'pointerup', onUp);
      bind(cv, 'pointercancel', onUp);
      if (bombButton) bind(bombButton, 'pointerenter', onBombButtonEnter);
    } else {
      bind(cv, 'mousedown', onDown);
      bind(cv, 'mousemove', onMove);
      bind(cv, 'mouseup', onUp);
      bind(cv, 'touchstart', (e) => { if (e.touches[0]) { if (e.preventDefault) e.preventDefault(); onDown(e.touches[0]); } });
      bind(cv, 'touchmove', (e) => { if (e.touches[0]) onMove(e.touches[0]); });
      bind(cv, 'touchend', onUp);
      bind(cv, 'touchcancel', onUp);
      if (bombButton) bind(bombButton, 'mouseenter', onBombButtonEnter);
    }
    g._onWinResize = () => { sfClampWorld(g); };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }

// ---- 武器系统 v2：8 种武器 / 双武器组合 / 持续时间 ----
  function sfWeaponDef(type) { return SF_WEAPON_DEFS[type] || null; }
  function sfWeaponProfileCopy(p) { return Object.assign({}, p); }
  function sfRandomWeaponKey() { return SF_WEAPON_KEYS[Math.floor(Math.random() * SF_WEAPON_KEYS.length)]; }

  function sfSingleWeaponProfile(type) {
    const base = SF_WEAPON_PROFILES[type];
    const def = sfWeaponDef(type);
    if (!base) return sfWeaponProfileCopy(SF_BASE_PROFILE);
    const p = sfWeaponProfileCopy(base);
    p.types = [type];
    p.name = def ? def.name : type;
    p.color = def ? def.color : p.color;
    p.color2 = def ? def.color2 : p.color2;
    return p;
  }

  function sfBuildWeaponProfile(g) {
    const p = g && g.player;
    const types = ((p && p.weapons) || []).map(w => w && w.type).filter(t => !!SF_WEAPON_PROFILES[t]);
    if (!types.length) return sfWeaponProfileCopy(SF_BASE_PROFILE);
    if (types.length === 1) return sfSingleWeaponProfile(types[0]);
    return sfDualWeaponProfile(types[0], types[1]);
  }

  function sfDualWeaponProfile(a, b) {
    const A = SF_WEAPON_PROFILES[a], B = SF_WEAPON_PROFILES[b];
    const da = sfWeaponDef(a), db = sfWeaponDef(b);
    const comboName = (da ? da.name : a) + '+' + (db ? db.name : b);
    if (!A || !B) return sfWeaponProfileCopy(SF_BASE_PROFILE);

    // 光束 / 镭射类组合
    if (A.kind === 'beam' || B.kind === 'beam') {
      const hasLaser = a === 'laser' || b === 'laser';
      const hasRail = a === 'railgun' || b === 'railgun';
      const other = a === 'laser' ? b : (b === 'laser' ? a : (a === 'railgun' ? b : a));
      let beamCount = 1;
      if (other === 'double') beamCount = 2;
      else if (other === 'spread' || other === 'gatling') beamCount = 3;
      let laserDps = hasLaser ? Math.max(A.laserDps || 0, B.laserDps || 0) : 0;
      let railDamage = hasRail ? Math.max(A.railDamage || 0, B.railDamage || 0) : 0;
      const chargeSec = hasRail ? (hasLaser ? 1.05 : (other === 'gatling' ? 0.65 : (other === 'cannon' ? 0.9 : 1.15))) : 0;
      const cooldown = hasRail ? (other === 'gatling' ? 1.4 : 2.1) : 0;
      let width = Math.max(A.width || 0.008, B.width || 0.008);
      if (other === 'pierce' || other === 'double' || other === 'spread' || A.explosive || B.explosive) width *= 1.24;
      const homing = a === 'homing' || b === 'homing';
      const explosive = a === 'cannon' || b === 'cannon';

      // 双武器叠加伤害 / 攻速限制：光束按每秒总伤害与最少发射间隔限制
      if (laserDps > 0) {
        const cap = hasRail ? SF_DUAL_DPS_CAP * 0.55 : SF_DUAL_DPS_CAP;
        if (laserDps * beamCount > cap) laserDps = cap / beamCount;
      }
      if (railDamage > 0) {
        const cap = hasLaser ? SF_DUAL_DPS_CAP * 0.55 : SF_DUAL_DPS_CAP;
        const maxPerShot = (cap * cooldown) / beamCount;
        if (railDamage > maxPerShot) railDamage = maxPerShot;
      }
      if (laserDps > 0 && railDamage > 0) {
        const total = beamCount * (laserDps + railDamage / cooldown);
        if (total > SF_DUAL_DPS_CAP) {
          const k = SF_DUAL_DPS_CAP / total;
          laserDps *= k;
          railDamage *= k;
        }
      }
      return {
        kind: 'beam', types: [a, b], name: comboName, beamCount,
        laserDps, railDamage, chargeSec, cooldown, width, homing, explosive, pierce: true,
        color: da ? da.color : '#22D3EE', color2: db ? db.color : '#C084FC'
      };
    }

    // 弹道类组合：合并弹数、散射、追踪、爆炸、穿透、加特林
    const countBase = Math.max(A.count || 1, B.count || 1);
    const hasSpread = (A.spread || 0) > 0 || (B.spread || 0) > 0;
    let count = hasSpread ? Math.max(5, countBase) : countBase;
    if (!hasSpread && count < 2) count = 2;
    const spread = hasSpread ? Math.max(A.spread || 0, B.spread || 0, 0.5) : 0;
    const homing = !!A.homing || !!B.homing;
    const explosive = !!A.explosive || !!B.explosive;
    const pierce = (a === 'pierce' || b === 'pierce');
    const gatling = !!A.gatling || !!B.gatling;
    let gap = Math.min(A.gap || 0.2, B.gap || 0.2) * 0.9;
    gap = Math.max(SF_DUAL_MIN_GAP, gap);
    let damage = Math.max(A.damage || 1, B.damage || 1) * 1.15;
    const dps = count * damage / gap;
    if (dps > SF_DUAL_DPS_CAP) damage = SF_DUAL_DPS_CAP * gap / count;
    const shape = homing ? 'missile' : (explosive ? 'shell' : (pierce ? 'triangle' : (B.shape || A.shape || 'bolt')));
    return {
      kind: 'bullet', types: [a, b], name: comboName, count, spread, homing, explosive, pierce, gatling,
      gap, damage, shape, speed: Math.max(A.speed || 1.1, B.speed || 1.1),
      r: Math.max(A.r || 0.007, B.r || 0.007) * 1.06,
      splash: Math.max(A.splash || 0, B.splash || 0),
      color: da ? da.color : '#67E8F9', color2: db ? db.color : '#FDE047'
    };
  }

  function sfAddWeapon(g, type) {
    if (!g || !g.player || !SF_WEAPON_PROFILES[type]) return false;
    const p = g.player;
    const now = g.time;
    const def = sfWeaponDef(type);
    p.weapons = (p.weapons || []).filter(w => w && w.expiresAt > g.time);
    if (p.weapons.length >= 2) {
      sfAddText(g, p.x, p.y - p.r * 2.4, '武器槽已满，需等待持续时间结束', '#94A3B8', 0.9, Math.max(11, g.W * 0.03));
      return false;
    }
    if (p.weapons.length === 1 && p.weapons[0].type === type) {
      sfAddText(g, p.x, p.y - p.r * 2.4, '同名武器持续中，暂不可重新拾取', '#94A3B8', 0.9, Math.max(11, g.W * 0.03));
      return false;
    }
    p.weapons.push({ type, expiresAt: now + SF_WEAPON_DURATION });
    p.weapons.forEach(w => { w.expiresAt = now + SF_WEAPON_DURATION; });
    p.fireT = Math.min(p.fireT || 0, 0.12);
    p.railCharge = 0;
    if (Array.isArray(g.playerBeams)) g.playerBeams = [];
    const prof = sfBuildWeaponProfile(g);
    const label = p.weapons.length === 2 ? (prof.name + ' · ' + Math.round(SF_WEAPON_DURATION) + 's') : ((def ? def.name : type) + ' · ' + Math.round(SF_WEAPON_DURATION) + 's');
    sfAddText(g, p.x, p.y - p.r * 2.4, '获得武器 ' + label, def ? def.color : '#22D3EE', 1.15, Math.max(12, g.W * 0.034));
    sfAddRing(g, p.x, p.y, def ? def.color : '#22D3EE', p.r * 4, 0.35);
    sfPlaySfx('pickup', 0.7);
    sfUpdateDomHud(g);
    return true;
  }

  function sfUpdateWeaponState(g) {
    const p = g && g.player;
    if (!p || !Array.isArray(p.weapons) || !p.weapons.length) return;
    const before = p.weapons.length;
    const last = p.weapons[p.weapons.length - 1];
    if (!last || last.expiresAt <= g.time) {
      p.weapons = [];
      p.railCharge = 0;
      if (Array.isArray(g.playerBeams)) g.playerBeams = [];
      sfAddText(g, p.x, p.y - p.r * 2.4, '武器持续时间结束', '#94A3B8', 1.0, Math.max(11, g.W * 0.03));
      return;
    }
    p.weapons = p.weapons.filter(w => w.expiresAt > g.time);
    if (p.weapons.length !== before) {
      p.railCharge = 0;
      if (Array.isArray(g.playerBeams)) g.playerBeams = [];
      if (!p.weapons.length) sfAddText(g, p.x, p.y - p.r * 2.4, '武器持续时间结束', '#94A3B8', 1.0, Math.max(11, g.W * 0.03));
    }
  }

  function sfNearestTargetTo(g, x, y, aboveOnly) {
    let best = null, bestD = Infinity;
    for (const e of g.enemies) {
      if (!e) continue;
      if (aboveOnly && e.y > g.player.y - 12) continue;
      const dx = e.x - x, dy = e.y - y, d = dx * dx + dy * dy;
      if (d < bestD) { bestD = d; best = e; }
    }
    if (g.boss && !g.boss.entering && (!aboveOnly || g.boss.y < g.player.y)) {
      const dx = g.boss.x - x, dy = g.boss.y - y, d = dx * dx + dy * dy;
      if (d < bestD) best = g.boss;
    }
    return best;
  }

  function sfPointSegDist(px, py, x1, y1, x2, y2) {
    const dx = x2 - x1, dy = y2 - y1;
    const len2 = dx * dx + dy * dy;
    if (len2 <= 0.0001) return Math.hypot(px - x1, py - y1);
    let t = ((px - x1) * dx + (py - y1) * dy) / len2;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
  }

  function sfBeamGeometries(g, profile) {
    const p = g.player;
    const count = Math.max(1, Math.floor(profile.beamCount || 1));
    const width = Math.max(2, Math.min(g.W, g.H) * (profile.width || 0.008));
    const target = profile.homing ? sfNearestTargetTo(g, p.x, p.y, true) : null;
    const arr = [];
    const y1 = p.y - p.r * 0.8;
    for (let i = 0; i < count; i++) {
      let x1 = p.x;
      if (count > 1) {
        const span = Math.min(g.W * 0.16, p.r * 3.0);
        if (count === 2) x1 = p.x + (i ? 1 : -1) * span * 0.5;
        else x1 = p.x + (i - (count - 1) / 2) * (span / Math.max(1, count - 1));
      }
      let x2 = x1, y2 = -30;
      if (target) {
        const dx = target.x - x1, dy = target.y - y1;
        const len = Math.hypot(dx, dy) || 1;
        x2 = x1 + (dx / len) * g.H * 1.6;
        y2 = y1 + (dy / len) * g.H * 1.6;
      }
      arr.push({ x1, y1, x2, y2, width });
    }
    return arr;
  }

  function sfSplashDamage(g, x, y, radius, damage, color) {
    if (!g) return;
    const r = Math.max(4, Number(radius) || Math.min(g.W, g.H) * 0.07);
    for (let i = g.enemies.length - 1; i >= 0; i--) {
      const e = g.enemies[i];
      if (!e) continue;
      if (Math.hypot(e.x - x, e.y - y) <= r + e.r) {
        e.hp -= damage;
        e.hitFlash = 0.09;
        if (e.hp <= 0) sfKillEnemy(g, e, true);
      }
    }
    if (g.boss) {
      const b = g.boss;
      if (Math.hypot(b.x - x, b.y - y) <= r + Math.min(b.w, b.h) * 0.45) {
        sfDamageBoss(g, b, damage);
      }
    }
    sfAddParticleBurst(g, x, y, color || '#F59E0B', 16, r * 0.7);
    sfAddRing(g, x, y, color || '#F59E0B', r, 0.35);
  }

  function sfRailHit(g, beam) {
    const dmg = beam.damage;
    for (let i = g.enemies.length - 1; i >= 0; i--) {
      const e = g.enemies[i];
      if (!e) continue;
      const dist = sfPointSegDist(e.x, e.y, beam.x1, beam.y1, beam.x2, beam.y2);
      if (dist <= beam.width / 2 + e.r * 0.9) {
        e.hp -= dmg;
        e.hitFlash = 0.1;
        sfAddParticleBurst(g, e.x, e.y, beam.color || '#C084FC', 8, e.r * 1.8);
        if (beam.explosive) sfSplashDamage(g, e.x, e.y, beam.width * 2.4, dmg * 0.4, beam.color);
        if (e.hp <= 0 && g.enemies.indexOf(e) >= 0) sfKillEnemy(g, e, true);
      }
    }
    if (g.boss) {
      const b = g.boss;
      const dist = sfPointSegDist(b.x, b.y, beam.x1, beam.y1, beam.x2, beam.y2);
      if (dist <= beam.width / 2 + Math.min(b.w, b.h) * 0.45) {
        sfDamageBoss(g, b, dmg);
        if (beam.explosive) sfSplashDamage(g, b.x, b.y, beam.width * 2.4, dmg * 0.4, beam.color);
      }
    }
  }

  function sfUpdateBeams(g, dt) {
    if (!g || g.over) return;
    const p = g.player;
    if (Array.isArray(g.playerBeams) && g.playerBeams.length) {
      for (let i = g.playerBeams.length - 1; i >= 0; i--) {
        g.playerBeams[i].life -= dt;
        if (g.playerBeams[i].life <= 0) g.playerBeams.splice(i, 1);
      }
    }
    const profile = sfBuildWeaponProfile(g);
    if (profile.kind !== 'beam') { p.railCharge = 0; return; }
    if (profile.laserDps > 0) {
      const beams = sfBeamGeometries(g, profile);
      for (const beam of beams) {
        for (let i = g.enemies.length - 1; i >= 0; i--) {
          const e = g.enemies[i];
          if (!e) continue;
          if (e.y > p.y) continue;
          const dist = sfPointSegDist(e.x, e.y, beam.x1, beam.y1, beam.x2, beam.y2);
          if (dist <= beam.width / 2 + e.r * 0.85) {
            e.hp -= profile.laserDps * dt;
            e.hitFlash = 0.04;
            if (e.hp <= 0) sfKillEnemy(g, e, true);
          }
        }
        if (g.boss && !g.boss.entering) {
          const b = g.boss;
          const dist = sfPointSegDist(b.x, b.y, beam.x1, beam.y1, beam.x2, beam.y2);
          if (dist <= beam.width / 2 + Math.min(b.w, b.h) * 0.45) {
            sfDamageBoss(g, b, profile.laserDps * dt);
          }
        }
      }
    }
    if (profile.railDamage > 0) {
      p.railCharge = (p.railCharge || 0) + dt;
      if (p.railCharge >= (profile.chargeSec || 1.2)) {
        p.railCharge = 0;
        const beams = sfBeamGeometries(g, profile);
        for (const beam of beams) {
          const rb = {
            kind: 'rail', x1: beam.x1, y1: beam.y1, x2: beam.x2, y2: beam.y2,
            width: beam.width * 2.2, damage: profile.railDamage, life: 0.3, maxLife: 0.3,
            color: profile.color, color2: profile.color2, explosive: profile.explosive
          };
          if (Array.isArray(g.playerBeams)) {
            if (g.playerBeams.length > 10) g.playerBeams.shift();
            g.playerBeams.push(rb);
          }
          sfRailHit(g, rb);
        }
        sfPlaySfx('rail', 0.8);
      }
    } else {
      p.railCharge = 0;
    }
  }

  function sfDrawPlayerBeams(g, ctx) {
    const p = g.player;
    if (!p) return;
    const profile = sfBuildWeaponProfile(g);
    if (profile.kind !== 'beam') return;
    ctx.save();
    ctx.lineCap = 'round';
    if (profile.laserDps > 0) {
      const beams = sfBeamGeometries(g, profile);
      const pulse = 0.75 + 0.25 * Math.sin(g.time * 22);
      for (const b of beams) {
        ctx.globalAlpha = 0.18 * pulse;
        ctx.strokeStyle = profile.color;
        ctx.lineWidth = b.width * 3.4;
        ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
        ctx.globalAlpha = 0.9;
        ctx.strokeStyle = profile.color2 || '#E0F2FE';
        ctx.lineWidth = Math.max(1, b.width * 0.9);
        ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
        ctx.globalAlpha = 0.75;
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = Math.max(1, b.width * 0.28);
        ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
      }
    }
    if (Array.isArray(g.playerBeams)) {
      for (const b of g.playerBeams) {
        const a = Math.max(0, b.life / b.maxLife);
        ctx.globalAlpha = a * 0.32;
        ctx.strokeStyle = b.color;
        ctx.lineWidth = b.width * 1.8;
        ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
        ctx.globalAlpha = a * 0.95;
        ctx.strokeStyle = b.color2 || '#F5F3FF';
        ctx.lineWidth = Math.max(2, b.width * 0.7);
        ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
        ctx.globalAlpha = a;
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = Math.max(1, b.width * 0.18);
        ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
      }
    }
    if (profile.railDamage > 0) {
      const ratio = Math.max(0, Math.min(1, (p.railCharge || 0) / Math.max(0.1, profile.chargeSec || 1)));
      const cx = p.x, cy = p.y - p.r * 1.1;
      ctx.globalAlpha = 0.35 + ratio * 0.6;
      ctx.strokeStyle = profile.color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(cx, cy, p.r * (0.35 + ratio * 0.9), 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = ratio;
      ctx.fillStyle = profile.color2 || '#F5F3FF';
      ctx.beginPath();
      ctx.arc(cx, cy, p.r * (0.12 + ratio * 0.28), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  function sfDrawItemGlyph(ctx, type, weapon, r) {
    ctx.save();
    ctx.lineWidth = Math.max(1, r * 0.12);
    ctx.strokeStyle = 'rgba(255,255,255,0.78)';
    ctx.fillStyle = '#FFFFFF';
    if (type === 'heal') {
      ctx.fillStyle = '#FB7185';
      ctx.beginPath();
      ctx.moveTo(0, r * 0.55);
      ctx.bezierCurveTo(r * 0.55, r * 0.05, r * 0.82, -r * 0.36, r * 0.35, -r * 0.68);
      ctx.bezierCurveTo(r * 0.1, -r * 0.85, 0, -r * 0.55, 0, -r * 0.35);
      ctx.bezierCurveTo(0, -r * 0.55, -r * 0.1, -r * 0.85, -r * 0.35, -r * 0.68);
      ctx.bezierCurveTo(-r * 0.82, -r * 0.36, -r * 0.55, r * 0.05, 0, r * 0.55);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,.65)';
      ctx.fillRect(-r * 0.06, -r * 0.52, r * 0.12, r * 0.34);
      ctx.fillRect(-r * 0.23, -r * 0.35, r * 0.46, r * 0.12);
    } else if (type === 'shield') {
      ctx.fillStyle = '#38BDF8';
      ctx.beginPath();
      ctx.moveTo(0, -r * 0.88);
      ctx.lineTo(r * 0.72, -r * 0.42);
      ctx.lineTo(r * 0.6, r * 0.32);
      ctx.lineTo(0, r * 0.92);
      ctx.lineTo(-r * 0.6, r * 0.32);
      ctx.lineTo(-r * 0.72, -r * 0.42);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,.75)';
      ctx.beginPath(); ctx.moveTo(0, -r * 0.55); ctx.lineTo(0, r * 0.55); ctx.moveTo(-r * 0.4, -r * 0.05); ctx.lineTo(r * 0.4, -r * 0.05); ctx.stroke();
    } else if (type === 'bomb') {
      ctx.fillStyle = '#FBBF24';
      ctx.beginPath(); ctx.arc(0, r * 0.12, r * 0.62, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.strokeStyle = '#FDE68A';
      ctx.lineWidth = Math.max(1.5, r * 0.16);
      ctx.beginPath(); ctx.moveTo(r * 0.24, -r * 0.38); ctx.lineTo(r * 0.52, -r * 0.82); ctx.stroke();
      ctx.fillStyle = '#FFF7ED';
      ctx.beginPath(); ctx.arc(-r * 0.2, -r * 0.1, r * 0.16, 0, Math.PI * 2); ctx.fill();
    } else if (weapon === 'double') {
      ctx.fillStyle = '#67E8F9';
      ctx.fillRect(-r * 0.55, -r * 0.58, r * 0.32, r * 1.2);
      ctx.fillRect(r * 0.23, -r * 0.58, r * 0.32, r * 1.2);
      ctx.fillStyle = '#E0F2FE';
      ctx.fillRect(-r * 0.47, -r * 0.38, r * 0.16, r * 0.8);
      ctx.fillRect(r * 0.31, -r * 0.38, r * 0.16, r * 0.8);
    } else if (weapon === 'spread') {
      ctx.strokeStyle = '#FDE047';
      ctx.lineWidth = Math.max(1.5, r * 0.18);
      for (let i = -2; i <= 2; i++) {
        ctx.beginPath();
        ctx.moveTo(0, r * 0.55);
        ctx.lineTo(i * r * 0.42, -r * 0.75);
        ctx.stroke();
        ctx.fillStyle = '#FFF7CC';
        ctx.beginPath(); ctx.arc(i * r * 0.42, -r * 0.75, r * 0.1, 0, Math.PI * 2); ctx.fill();
      }
    } else if (weapon === 'gatling') {
      ctx.fillStyle = '#FB923C';
      ctx.beginPath(); ctx.arc(0, r * 0.2, r * 0.48, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#FED7AA';
      for (let i = -1; i <= 1; i++) {
        ctx.fillRect(i * r * 0.25 - r * 0.08, -r * 0.75, r * 0.16, r * 0.7);
      }
      ctx.fillStyle = '#7C2D12';
      ctx.beginPath(); ctx.arc(0, r * 0.2, r * 0.16, 0, Math.PI * 2); ctx.fill();
    } else if (weapon === 'homing') {
      ctx.fillStyle = '#F472B6';
      ctx.beginPath();
      ctx.moveTo(0, -r * 0.9);
      ctx.lineTo(r * 0.34, r * 0.18);
      ctx.lineTo(0, r * 0.5);
      ctx.lineTo(-r * 0.34, r * 0.18);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#FBCFE8';
      ctx.beginPath(); ctx.moveTo(-r * 0.55, r * 0.12); ctx.lineTo(-r * 0.18, r * 0.5); ctx.lineTo(-r * 0.16, r * 0.2); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(r * 0.55, r * 0.12); ctx.lineTo(r * 0.18, r * 0.5); ctx.lineTo(r * 0.16, r * 0.2); ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#FDBA74';
      ctx.beginPath(); ctx.moveTo(-r * 0.18, r * 0.55); ctx.lineTo(0, r * 1.05); ctx.lineTo(r * 0.18, r * 0.55); ctx.closePath(); ctx.fill();
    } else if (weapon === 'laser') {
      ctx.fillStyle = '#22D3EE';
      ctx.fillRect(-r * 0.42, r * 0.28, r * 0.84, r * 0.38);
      ctx.strokeStyle = '#A5F3FC';
      ctx.lineWidth = Math.max(1.5, r * 0.14);
      ctx.beginPath(); ctx.moveTo(0, r * 0.24); ctx.lineTo(0, -r * 0.9); ctx.stroke();
      ctx.fillStyle = '#ECFEFF';
      ctx.beginPath(); ctx.arc(0, -r * 0.9, r * 0.14, 0, Math.PI * 2); ctx.fill();
    } else if (weapon === 'railgun') {
      ctx.strokeStyle = '#C084FC';
      ctx.lineWidth = Math.max(1.5, r * 0.16);
      ctx.beginPath(); ctx.moveTo(-r * 0.48, r * 0.55); ctx.lineTo(-r * 0.48, -r * 0.7); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(r * 0.48, r * 0.55); ctx.lineTo(r * 0.48, -r * 0.7); ctx.stroke();
      ctx.strokeStyle = '#F5D0FE';
      ctx.lineWidth = Math.max(1, r * 0.09);
      ctx.beginPath(); ctx.moveTo(-r * 0.28, -r * 0.5); ctx.lineTo(0, -r * 0.15); ctx.lineTo(r * 0.28, -r * 0.5); ctx.stroke();
      ctx.fillStyle = '#E9D5FF';
      ctx.beginPath(); ctx.arc(0, -r * 0.15, r * 0.14, 0, Math.PI * 2); ctx.fill();
    } else if (weapon === 'cannon') {
      ctx.fillStyle = '#F59E0B';
      ctx.beginPath(); ctx.arc(0, r * 0.2, r * 0.65, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#78350F';
      ctx.fillRect(-r * 0.55, r * 0.04, r * 1.1, r * 0.16);
      ctx.fillStyle = '#FDE68A';
      ctx.beginPath(); ctx.arc(-r * 0.18, -r * 0.05, r * 0.16, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#FDE68A';
      ctx.lineWidth = Math.max(1, r * 0.1);
      ctx.beginPath(); ctx.moveTo(r * 0.32, -r * 0.35); ctx.lineTo(r * 0.55, -r * 0.8); ctx.stroke();
    } else if (weapon === 'pierce') {
      ctx.fillStyle = '#A3E635';
      ctx.beginPath();
      ctx.moveTo(0, -r * 0.95);
      ctx.lineTo(r * 0.52, r * 0.45);
      ctx.lineTo(0, r * 0.18);
      ctx.lineTo(-r * 0.52, r * 0.45);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,.55)';
      ctx.beginPath(); ctx.moveTo(0, -r * 0.65); ctx.lineTo(0, r * 0.6); ctx.stroke();
    }
    ctx.restore();
  }
  // ---- 战斗：玩家开火 / 敌机与 BOSS 生成 ----
  function sfFirePlayer(g) {
    const p = g.player;
    if (g.over) return;
    const profile = sfBuildWeaponProfile(g);
    if (profile.kind !== 'bullet') { p.fireT = 0; return; }
    if (p.fireT > 0) return;
    const count = Math.max(1, Math.floor(profile.count || 1));
    const speedPx = g.H * (profile.speed || 1.15);
    const pr = Math.max(2, Math.min(g.W, g.H) * (profile.r || 0.007));
    const shots = [];
    for (let i = 0; i < count; i++) {
      let xOff = 0, angle = 0;
      if (count === 2 && !(profile.spread > 0)) xOff = (i ? 1 : -1) * p.r * 0.46;
      else if ((profile.spread || 0) > 0 && count > 1) angle = -(profile.spread || 0) / 2 + (profile.spread || 0) * i / (count - 1);
      else if (count > 1) angle = -0.14 + 0.28 * i / (count - 1);
      const b = {
        x: p.x + xOff, y: p.y - p.r * 1.2,
        vx: Math.sin(angle) * speedPx, vy: -Math.cos(angle) * speedPx,
        r: pr, dmg: profile.damage, color: profile.color, color2: profile.color2,
        shape: profile.shape || 'bolt', homing: !!profile.homing, turn: 3.2,
        explosive: !!profile.explosive, splash: (profile.splash || 0) * Math.min(g.W, g.H),
        pierce: !!profile.pierce, gatling: !!profile.gatling,
        life: 2.6, t: 0, hitIds: []
      };
      if (g.bullets.length > 180) g.bullets.shift();
      g.bullets.push(b);
      shots.push(b);
    }
    p.fireT = (profile.gap || 0.18) * sfRand(0.94, 1.06);
    sfPlaySfx('shoot', 0.35);
    for (const b of shots) {
      sfAddParticle(g, b.x, b.y, sfRand(-18, 18), sfRand(-80, -25), 0.12, profile.color2 || '#A5F3FC', 2, 'square');
    }
  }

  function sfSpawnEnemy(g, type, x) {
    const def = SF_ENEMY_DEFS[type] || SF_ENEMY_DEFS.scout;
    const r = Math.max(7, Math.min(g.W, g.H) * def.r);
    const diff = g.diff;
    const hp = Math.max(1, Math.ceil(def.hp * (1 + (diff - 1) * 0.38)));
    g.enemySeq = (g.enemySeq || 0) + 1;
    const e = {
      id: 'e' + g.enemySeq,
      type, x: sfClamp(x, r * 1.6, g.W - r * 1.6), y: -r * 2.2,
      r, hp, maxHp: hp,
      vy: def.speed * g.H * (1 + (diff - 1) * 0.10),
      vx: 0,
      score: Math.round(def.score * (1 + (diff - 1) * 0.08)),
      fireT: sfRand(0.8, def.fire * 1.45),
      fireGap: def.fire,
      t: 0, phase: sfRand(0, Math.PI * 2), hitFlash: 0,
      color: def.color
    };
    if (g.enemies.length > 9) g.enemies.shift();
    g.enemies.push(e);
  }

  function sfSpawnWave(g) {
    if (!g || g.over || g.boss || g.bossWarnT > 0) return;
    const diff = g.diff;
    let count = 1 + (Math.random() < Math.min(0.35, (diff - 1) * 0.18) ? 1 : 0);
    if (diff > 3 && Math.random() < 0.12) count++;
    count = Math.min(2, count);
    const eliteChance = Math.min(0.16, 0.05 + (diff - 1) * 0.035);
    const dartChance = 0.22;
    for (let i = 0; i < count; i++) {
      const roll = Math.random();
      const type = roll < eliteChance ? 'elite' : (roll < eliteChance + dartChance ? 'dart' : 'scout');
      const base = g.W * (0.14 + 0.72 * ((i + 1) / (count + 1)));
      const x = base + sfRand(-g.W * 0.07, g.W * 0.07);
      sfSpawnEnemy(g, type, x);
    }
    g.spawnT = Math.max(0.60, 1.45 - (diff - 1) * 0.13) * sfRand(0.90, 1.25);
  }

  function sfSpawnBoss(g) {
    const idx = ++g.bossIndex;
    const diff = g.diff;
    const w = Math.max(130, g.W * 0.64);
    const h = Math.max(58, g.H * 0.12);
    const hp = Math.round((300 + (idx - 1) * 170) * (1 + (diff - 1) * 0.24));
    g.boss = {
      x: g.W / 2, y: -h * 0.75, w, h, hp, maxHp: hp,
      phase: 1, t: 0, shootT: 1.1, shotCount: 0, spiral: -Math.PI / 2, dropAccum: 0,
      dir: Math.random() < 0.5 ? -1 : 1, entering: true, hitFlash: 0, targetY: Math.max(80, g.H * 0.2)
    };
    g.bossWarnT = 0;
    g.spawnT = 1.4;
    sfPlaySfx('bossWarn', 0.8);
    sfAddText(g, g.W / 2, g.H * 0.32, '⚠ BOSS 接近', '#F43F5E', 1.4, Math.max(16, g.W * 0.055));
    sfAddRing(g, g.W / 2, g.H * 0.32, '#F43F5E', Math.min(g.W, g.H) * 0.28, 0.65);
  }

  function sfEnemyBullet(g, x, y, angle, speed, color, r) {
    if (!g || g.over) return;
    if (g.enemyBullets.length > 150) g.enemyBullets.shift();
    const rr = r || Math.max(3, Math.min(g.W, g.H) * 0.013);
    g.enemyBullets.push({
      x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
      r: rr, color: color || '#F472B6', life: 7
    });
  }

  function sfAimAngle(g, x, y) {
    return Math.atan2(g.player.y - y, g.player.x - x);
  }

  function sfUseBomb() {
    const g = sfGame;
    if (!g || g.over || g.player.bombs <= 0) return;
    const now = sfNow();
    if (g.lastBombAt && now - g.lastBombAt < 350) return;
    g.lastBombAt = now;
    g.player.bombs--;
    g.enemyBullets.length = 0;
    g.flash = Math.max(g.flash, 0.5);
    g.shake = Math.max(g.shake, 1);
    sfPlaySfx('bomb', 0.9);
    sfAddRing(g, g.player.x, g.player.y, '#FBBF24', Math.min(g.W, g.H) * 0.75, 0.55);
    sfAddRing(g, g.player.x, g.player.y, '#38BDF8', Math.min(g.W, g.H) * 0.55, 0.45);
    sfAddText(g, g.player.x, g.player.y - g.player.r * 2.4, '💥 清屏炸弹', '#FBBF24', 1.0, Math.max(14, g.W * 0.045));
    const dmg = 8;
    for (let i = g.enemies.length - 1; i >= 0; i--) {
      const e = g.enemies[i];
      if (!e) continue;
      e.hp -= dmg;
      e.hitFlash = 0.12;
      if (e.hp <= 0) sfKillEnemy(g, e, true);
    }
    if (g.boss) {
      const boss = g.boss;
      const bombDmg = 34 + ((g.player.weapons && g.player.weapons.length) ? g.player.weapons.length * 14 : 0);
      sfDamageBoss(g, boss, bombDmg);
    }
    sfUpdateDomHud(g);
  }

  function sfDamagePlayer(g, amount) {
    if (!g || g.over) return;
    const p = g.player;
    if (p.invuln > 0) return;
    if (p.shield > 0) {
      p.shield--;
      p.invuln = 1.0;
      g.shake = Math.max(g.shake, 0.35);
      sfPlaySfx('hit', 0.5);
      sfAddRing(g, p.x, p.y, '#38BDF8', p.r * 3.2, 0.35);
      sfAddText(g, p.x, p.y - p.r * 2.2, '护盾抵挡', '#38BDF8', 0.8, Math.max(11, g.W * 0.032));
      sfUpdateDomHud(g);
      return;
    }
    p.hp -= Math.max(1, amount || 1);
    p.invuln = 1.5;
    g.shake = Math.max(g.shake, 0.8);
    g.flash = Math.max(g.flash, 0.24);
    sfPlaySfx('playerHit', 0.8);
    sfAddParticleBurst(g, p.x, p.y, '#F43F5E', 14, p.r * 3);
    sfAddText(g, p.x, p.y - p.r * 2.2, '-' + Math.max(1, amount || 1) + ' HP', '#F43F5E', 0.9, Math.max(12, g.W * 0.036));
    if (p.hp <= 0) sfDie(g);
    sfUpdateDomHud(g);
  }

  function sfAddParticle(g, x, y, vx, vy, life, color, size, shape) {
    if (!g) return;
    if (g.particles.length > 180) g.particles.shift();
    g.particles.push({ x, y, vx, vy, life, maxLife: life, color: color || '#fff', size: size || 2, shape: shape || 'square' });
  }
  function sfAddParticleBurst(g, x, y, color, count, radius) {
    const n = count || 12;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = sfRand(radius * 0.5, radius * 2.8);
      sfAddParticle(g, x, y, Math.cos(a) * sp, Math.sin(a) * sp, sfRand(0.25, 0.65), color, sfRand(1.5, 3.5), Math.random() < 0.3 ? 'circle' : 'square');
    }
  }
  function sfAddRing(g, x, y, color, maxR, life) {
    if (!g) return;
    if (g.rings.length > 18) g.rings.shift();
    g.rings.push({ x, y, color: color || '#fff', maxR: maxR || 60, life: life || 0.45, maxLife: life || 0.45 });
  }
  function sfAddText(g, x, y, text, color, life, size) {
    if (!g) return;
    if (g.texts.length > 20) g.texts.shift();
    g.texts.push({ x, y, text, color: color || '#fff', life: life || 1, maxLife: life || 1, size: size || 12, vy: -26 });
  }

  function sfDropItem(g, x, y, type, weaponType) {
    if (!g) return;
    const pick = type ? { type: type, weapon: weaponType } : sfPickItemType(g);
    let t = pick.type;
    let w = pick.weapon;
    if (t === 'weapon' && !SF_WEAPON_DEFS[w]) w = sfRandomWeaponKey();
    const def = t === 'weapon' ? sfWeaponDef(w) : (SF_ITEM_DEFS[t] || SF_ITEM_DEFS.heal);
    if (g.items.length > 30) g.items.shift();
    g.items.push({
      x: sfClamp(x, 20, g.W - 20), y,
      vy: g.H * 0.075, r: Math.max(8, Math.min(g.W, g.H) * 0.024),
      type: t, weapon: w, color: def ? def.color : '#A78BFA', color2: def ? def.color2 : '#22D3EE',
      t: 0, phase: sfRand(0, Math.PI * 2)
    });
  }
  function sfPickItemType(g) {
    const p = g.player;
    const roll = Math.random();
    if ((p.hp <= 2 && roll < 0.32) || roll < 0.12) return { type: 'heal' };
    if (roll < 0.50) return { type: 'weapon', weapon: sfRandomWeaponKey() };
    if (p.shield < SF_MAX_SHIELD && roll < 0.66) return { type: 'shield' };
    if (p.bombs < SF_MAX_BOMBS && roll < 0.82) return { type: 'bomb' };
    return { type: 'weapon', weapon: sfRandomWeaponKey() };
  }
  function sfCollectItem(g, it) {
    const p = g.player;
    const def = it.type === 'weapon' ? sfWeaponDef(it.weapon) : (SF_ITEM_DEFS[it.type] || SF_ITEM_DEFS.heal);
    if (it.type === 'weapon') {
      sfAddWeapon(g, it.weapon);
    } else if (it.type === 'shield') {
      if (p.shield < SF_MAX_SHIELD) {
        p.shield++;
        sfAddText(g, p.x, p.y - p.r * 2.4, '护盾 +1', '#38BDF8', 0.9, Math.max(11, g.W * 0.03));
      } else {
        sfAddScore(g, 200);
        sfAddText(g, p.x, p.y - p.r * 2.4, '护盾已满 +200', '#38BDF8', 0.9, Math.max(11, g.W * 0.03));
      }
    } else if (it.type === 'heal') {
      if (p.hp < p.maxHp) {
        p.hp++;
        sfAddText(g, p.x, p.y - p.r * 2.4, '生命 +1', '#FB7185', 0.9, Math.max(11, g.W * 0.03));
      } else {
        sfAddScore(g, 300);
        sfAddText(g, p.x, p.y - p.r * 2.4, '生命已满 +300', '#FB7185', 0.9, Math.max(11, g.W * 0.03));
      }
    } else if (it.type === 'bomb') {
      if (p.bombs < SF_MAX_BOMBS) {
        p.bombs++;
        sfAddText(g, p.x, p.y - p.r * 2.4, '炸弹 +1', '#FBBF24', 0.9, Math.max(11, g.W * 0.03));
      } else {
        sfAddScore(g, 200);
        sfAddText(g, p.x, p.y - p.r * 2.4, '炸弹已满 +200', '#FBBF24', 0.9, Math.max(11, g.W * 0.03));
      }
    }
    sfAddScore(g, 50);
    sfAddParticleBurst(g, it.x, it.y, def ? def.color : '#A78BFA', 10, it.r * 2.6);
    sfAddRing(g, it.x, it.y, def ? def.color : '#A78BFA', it.r * 4, 0.35);
    sfPlaySfx('pickup', 0.6);
    sfUpdateDomHud(g);
  }

  function sfAddScore(g, n) {
    if (!g) return;
    const add = Math.max(0, Math.round(Number(n) || 0));
    if (!add) return;
    g.score += add;
    if (g.score > g.best) g.best = g.score;
    while (g.score >= g.nextPointAt) {
      g.nextPointAt += SF_POINT_STEP;
      sfAwardPoint(g, '得分突破 ' + (g.nextPointAt - SF_POINT_STEP));
    }
    sfUpdateDomHud(g);
  }
  function sfAwardPoint(g, reason) {
    if (!g) return;
    try { addPoints(1); } catch (e) { /* ignore */ }
    sfAddText(g, g.W / 2, g.H * 0.44, '💎 积分 +1', '#FBBF24', 1.2, Math.max(13, g.W * 0.038));
    sfAddRing(g, g.W / 2, g.H * 0.44, '#FBBF24', Math.min(g.W, g.H) * 0.2, 0.5);
    try { showToast('🎉 ' + (reason || '得分突破') + '！积分 +1（当前 ' + loadPoints() + '）'); } catch (e) { /* ignore */ }
    sfUpdateDomHud(g);
  }

  function sfKillEnemy(g, e, reward) {
    if (!g || !e) return;
    const i = g.enemies.indexOf(e);
    if (i >= 0) g.enemies.splice(i, 1);
    if (reward !== false) sfAddScore(g, e.score);
    g.kills++;
    sfAddParticleBurst(g, e.x, e.y, e.color, e.type === 'elite' ? 22 : 12, e.r * 2.4);
    sfAddRing(g, e.x, e.y, e.color, e.r * 4.2, 0.32);
    sfPlaySfx('explode', e.type === 'elite' ? 0.7 : 0.4);
    if (e.type === 'elite') {
      g.shake = Math.max(g.shake, 0.28);
      sfDropItem(g, e.x, e.y);
      if (Math.random() < 0.55) sfDropItem(g, e.x + sfRand(-e.r, e.r), e.y);
    } else if (Math.random() < 0.12) {
      sfDropItem(g, e.x, e.y);
    }
  }


  function sfDamageBoss(g, b, dmg) {
    if (!g || !b || g.boss !== b) return;
    const d = Math.max(0, Number(dmg) || 0);
    if (!d) return;
    b.hp -= d;
    b.hitFlash = Math.max(b.hitFlash || 0, 0.08);
    b.dropAccum = (b.dropAccum || 0) + d;
    let drops = 0;
    const bossDropTypes = ['heal', 'shield', 'bomb'];
    while (b.dropAccum >= 50 && drops < 8) {
      b.dropAccum -= 50;
      const dropType = bossDropTypes[(b.dropCount || 0) % bossDropTypes.length];
      b.dropCount = (b.dropCount || 0) + 1;
      sfDropItem(g, b.x + sfRand(-b.w * 0.3, b.w * 0.3), b.y + sfRand(0, b.h * 0.35), dropType);
      drops++;
    }
    if (b.hp <= 0) sfKillBoss(g);
  }

  function sfKillBoss(g) {
    const b = g.boss;
    if (!g || !b) return;
    g.boss = null;
    g.bossKills++;
    g.enemyBullets.length = 0;
    const base = 6000 + (g.bossIndex - 1) * 1500;
    sfAddScore(g, base);
    sfAwardPoint(g, '击破 BOSS');
    sfAddParticleBurst(g, b.x, b.y, '#F472B6', 46, b.w * 0.35);
    sfAddParticleBurst(g, b.x, b.y, '#FBBF24', 26, b.w * 0.25);
    sfAddRing(g, b.x, b.y, '#F472B6', Math.min(g.W, g.H) * 0.7, 0.7);
    g.flash = Math.max(g.flash, 0.48);
    g.shake = Math.max(g.shake, 1);
    g.wave++;
    g.bossT = SF_BOSS_INTERVAL * 0.85;
    sfPlaySfx('bossExplode', 1);
    sfAddText(g, g.W / 2, g.H * 0.3, 'BOSS 击破！', '#FBBF24', 1.6, Math.max(18, g.W * 0.06));
  }

  function sfDie(g) {
    if (!g || g.over) return;
    g.over = true;
    g.overT = 1.1;
    g.player.hp = 0;
    g.shake = 1;
    g.flash = 0.5;
    sfClearSave();
    sfSaveBest(g.score);
    sfAddParticleBurst(g, g.player.x, g.player.y, '#F43F5E', 36, g.player.r * 4);
    sfAddParticleBurst(g, g.player.x, g.player.y, '#38BDF8', 26, g.player.r * 3);
    sfAddRing(g, g.player.x, g.player.y, '#F43F5E', Math.min(g.W, g.H) * 0.5, 0.7);
    sfPlaySfx('gameOver', 0.9);
    if (g.overTimer) clearTimeout(g.overTimer);
    g.overTimer = setTimeout(() => { if (sfGame === g) sfShowGameOver(g); }, 1000);
    sfUpdateDomHud(g);
  }

  function sfShowGameOver(g) {
    if (!g || sfGame !== g) return;
    g.stopped = true;
    if (g.rafId) { sfCaf(g.rafId); g.rafId = 0; }
    if (g.overTimer) { clearTimeout(g.overTimer); g.overTimer = null; }
    sfSaveBest(g.score);
    if (!g.stageEl || !g.stageEl.appendChild) return;
    const old = g.stageEl.querySelector ? g.stageEl.querySelector('.sf-gameover') : null;
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.className = 'sf-gameover';
    ov.style.cssText = 'position:absolute;inset:0;z-index:8;background:rgba(2,6,23,0.84);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="width:100%;max-width:300px;text-align:center;background:rgba(15,23,42,0.92);border:1px solid rgba(56,189,248,0.45);border-radius:14px;padding:18px 14px;box-shadow:0 0 28px rgba(56,189,248,0.18);">
        <div style="font-size:22px;font-weight:800;color:#F43F5E;letter-spacing:2px;">💥 战机坠毁</div>
        <div style="font-size:12px;color:#94A3B8;margin-top:5px;">本次得分</div>
        <div style="font-size:30px;font-weight:800;color:#E0F2FE;font-family:'Courier New',monospace;margin-top:2px;">${Math.floor(g.score)}</div>
        <div style="font-size:11.5px;color:#94A3B8;margin-top:6px;">🏆 最高 ${Math.max(sfLoadBest(), Math.floor(g.score))} · 击破 BOSS ${g.bossKills} 次</div>
        <div style="display:flex;gap:8px;justify-content:center;margin-top:14px;">
          <button data-ubp-act="star-restart" class="ubp-btn primary" style="padding:8px 14px;font-size:13px;background:#0EA5E9;border:none;">🔄 再来一局</button>
          <button data-ubp-act="star-exit" class="ubp-btn" style="padding:8px 14px;font-size:13px;">← 返回小游戏大厅</button>
        </div>
      </div>`;
    g.stageEl.appendChild(ov);
  }

  function sfClampWorld(g) {
    if (!g) return;
    const p = g.player;
    if (!p) return;
    p.r = Math.max(9, Math.min(16, Math.min(g.W, g.H) * 0.036));
    p.x = sfClamp(p.x, p.r * 1.4, g.W - p.r * 1.4);
    p.y = sfClamp(p.y, p.r * 2, g.H - p.r * 1.4);
    p.targetX = sfClamp(p.targetX, g.W * 0.055, g.W * 0.945);
    p.targetY = sfClamp(p.targetY, g.H * 0.14, g.H * 0.93);
    for (const e of g.enemies) e.x = sfClamp(e.x, e.r, g.W - e.r);
    if (g.boss) {
      g.boss.w = Math.max(130, g.W * 0.64);
      g.boss.h = Math.max(58, g.H * 0.12);
      g.boss.x = sfClamp(g.boss.x, g.boss.w * 0.5, g.W - g.boss.w * 0.5);
    }
  }

  function sfEnsureStars(g) {
    if (!g) return;
    if (!g.stars.length || g._starW !== g.W || g._starH !== g.H) {
      const count = Math.round(sfClamp(g.W * g.H / 8500, 45, 130));
      g.stars = [];
      for (let i = 0; i < count; i++) {
        g.stars.push({
          x: Math.random() * g.W,
          y: Math.random() * g.H,
          z: Math.random(),
          r: Math.random() < 0.8 ? 1 : 2,
          tw: Math.random() * Math.PI * 2,
          c: Math.random() < 0.12 ? '#A5F3FC' : (Math.random() < 0.12 ? '#C4B5FD' : '#E2E8F0')
        });
      }
      g.nebulas = [
        { x: 0.22, y: 0.28, r: 0.55, c1: 'rgba(76,29,149,0.22)', c2: 'rgba(76,29,149,0)', drift: 0.018, ph: 0.4 },
        { x: 0.78, y: 0.62, r: 0.62, c1: 'rgba(8,145,178,0.16)', c2: 'rgba(8,145,178,0)', drift: 0.014, ph: 2.1 },
        { x: 0.5, y: 0.86, r: 0.5, c1: 'rgba(190,24,93,0.10)', c2: 'rgba(190,24,93,0)', drift: 0.02, ph: 4.4 }
      ];
      g._starW = g.W;
      g._starH = g.H;
    }
  }

  // ---- 每帧更新：移动 / 弹幕 / 碰撞 / 难度 ----
  function sfUpdate(g, dt) {
    if (!g) return;
    g.time += dt;
    g.flash = Math.max(0, g.flash - dt * 1.8);
    g.shake = Math.max(0, g.shake - dt * 2.4);
    g.bgShift += dt * 24;
    if (g.over) {
      g.overT -= dt;
      sfUpdateParticles(g, dt);
      return;
    }
    g.diff = Math.min(4, 1 + g.score / 3500);
    g.autosaveT -= dt;
    if (g.autosaveT <= 0) { g.autosaveT = 10; sfSaveGame(g); }
    sfEnsureStars(g);
    for (const st of g.stars) {
      st.y += (16 + 86 * st.z) * dt * (g.H / 640);
      st.x += Math.sin(g.time * (0.25 + st.z * 0.4) + st.tw) * 6 * dt;
      if (st.y > g.H + 4) { st.y = -4; st.x = Math.random() * g.W; }
      if (st.x < -4) st.x = g.W + 4;
      else if (st.x > g.W + 4) st.x = -4;
    }
    const p = g.player;
    p.invuln = Math.max(0, p.invuln - dt);
    p.fireT = Math.max(0, p.fireT - dt);
    sfUpdateWeaponState(g);
    // 键盘移动：方向键 / WASD
    let kx = 0, ky = 0;
    if (g.keys.left) kx -= 1;
    if (g.keys.right) kx += 1;
    if (g.keys.up) ky -= 1;
    if (g.keys.down) ky += 1;
    if (kx || ky) {
      const len = Math.hypot(kx, ky) || 1;
      p.x += (kx / len) * g.W * 0.62 * dt;
      p.y += (ky / len) * g.H * 0.58 * dt;
      g.input.mode = 'key';
    } else if (g.input.mode === 'pointer') {
      const k = 1 - Math.pow(0.00001, dt);
      p.x += (p.targetX - p.x) * k;
      p.y += (p.targetY - p.y) * k;
    }
    p.x = sfClamp(p.x, g.W * 0.055, g.W * 0.945);
    p.y = sfClamp(p.y, g.H * 0.14, g.H * 0.93);
    p.tilt = sfClamp((p.x - p.prevX) / Math.max(0.001, dt) / (g.W * 1.6), -0.32, 0.32);
    p.prevX = p.x;
    p.exhaustT -= dt;
    if (p.exhaustT <= 0) {
      p.exhaustT = 0.045;
      sfAddParticle(g, p.x + sfRand(-p.r * 0.22, p.r * 0.22), p.y + p.r * 1.05, sfRand(-12, 12), sfRand(90, 190), sfRand(0.18, 0.34), '#38BDF8', sfRand(1.5, 3.2), 'square');
    }
    sfFirePlayer(g);
    sfUpdateBeams(g, dt);

    // BOSS 计时：警告 → 入场；击破后重新计时
    if (g.bossWarnT > 0) {
      g.bossWarnT -= dt;
      if (g.bossWarnT <= 0) { g.bossWarnT = 0; sfSpawnBoss(g); }
    } else if (!g.boss) {
      g.bossT -= dt;
      if (g.bossT <= 0) {
        g.bossWarnT = SF_BOSS_WARN;
        g.bossT = 999;
        sfPlaySfx('bossWarn', 0.9);
        sfAddText(g, g.W / 2, g.H * 0.36, '⚠ BOSS 接近', '#F43F5E', 1.3, Math.max(15, g.W * 0.05));
      }
    }
    if (g.bossWarnT > 0) {
      // 警告期间暂停普通刷新，给玩家准备时间
    } else if (!g.boss) {
      g.spawnT -= dt;
      if (g.spawnT <= 0) sfSpawnWave(g);
    }

    // 敌机
    for (let i = g.enemies.length - 1; i >= 0; i--) {
      const e = g.enemies[i];
      if (!e) continue;
      e.t += dt;
      e.hitFlash = Math.max(0, e.hitFlash - dt);
      if (e.type === 'dart') {
        e.y += e.vy * dt;
        e.x += Math.sin(e.t * 5.2 + e.phase) * g.W * 0.18 * dt;
      } else if (e.type === 'elite') {
        e.y += e.vy * dt;
        e.x += Math.sin(e.t * 0.9 + e.phase) * g.W * 0.055 * dt;
      } else {
        e.y += e.vy * dt;
        e.x += Math.sin(e.t * 1.8 + e.phase) * g.W * 0.025 * dt;
      }
      e.x = sfClamp(e.x, e.r, g.W - e.r);
      if (e.y < g.H * 0.72) {
        e.fireT -= dt;
        if (e.fireT <= 0) {
          const aim = sfAimAngle(g, e.x, e.y);
          const speed = g.H * (e.type === 'dart' ? 0.30 : (e.type === 'elite' ? 0.24 : 0.22));
          if (e.type === 'elite') {
            for (const a of [-1, 1]) sfEnemyBullet(g, e.x, e.y + e.r * 0.7, aim + a * 0.2, speed, '#C084FC', Math.max(4, Math.min(g.W, g.H) * 0.016));
          } else {
            sfEnemyBullet(g, e.x, e.y + e.r * 0.7, aim, speed, e.type === 'dart' ? '#FDE047' : '#FB7185');
          }
          e.fireT = e.fireGap * sfRand(0.86, 1.22) * Math.max(0.75, 1 - (g.diff - 1) * 0.08);
        }
      }
      if (e.y > g.H + e.r * 2.5) g.enemies.splice(i, 1);
    }

    // BOSS
    if (g.boss) {
      const b = g.boss;
      b.t += dt;
      b.hitFlash = Math.max(0, b.hitFlash - dt);
      if (b.entering) {
        b.y += g.H * 0.12 * dt;
        if (b.y >= b.targetY) { b.y = b.targetY; b.entering = false; }
      } else {
        b.x += b.dir * g.W * 0.075 * dt;
        const bl = b.w / 2 + 4, br = g.W - b.w / 2 - 4;
        if (b.x < bl) { b.x = bl; b.dir = 1; }
        else if (b.x > br) { b.x = br; b.dir = -1; }
        const ratio = b.hp / b.maxHp;
        const ph = ratio > 0.66 ? 1 : (ratio > 0.33 ? 2 : 3);
        if (ph !== b.phase) {
          b.phase = ph;
          b.shootT = 0.35;
          g.shake = Math.max(g.shake, 0.7);
          g.flash = Math.max(g.flash, 0.2);
          sfAddRing(g, b.x, b.y, ph === 2 ? '#C084FC' : '#FB7185', b.w * 0.55, 0.5);
          sfAddText(g, b.x, b.y + b.h * 0.75, 'PHASE ' + ph, '#FBBF24', 1.0, Math.max(13, g.W * 0.04));
          sfPlaySfx('bossHit', 0.8);
        }
        b.shootT -= dt;
        if (b.shootT <= 0) sfBossShoot(g, b);
      }
    }

    // 玩家子弹
    for (let i = g.bullets.length - 1; i >= 0; i--) {
      const b = g.bullets[i];
      b.t = (b.t || 0) + dt;
      if (b.homing && b.life > 0) {
        const target = sfNearestTargetTo(g, b.x, b.y, false);
        if (target) {
          const desired = Math.atan2(target.y - b.y, target.x - b.x);
          const cur = Math.atan2(b.vy, b.vx);
          let diff = desired - cur;
          while (diff > Math.PI) diff -= Math.PI * 2;
          while (diff < -Math.PI) diff += Math.PI * 2;
          const turn = (b.turn || 3.2) * dt;
          diff = Math.max(-turn, Math.min(turn, diff));
          const sp = Math.hypot(b.vx, b.vy);
          b.vx = Math.cos(cur + diff) * sp;
          b.vy = Math.sin(cur + diff) * sp;
        }
      }
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.life <= 0 || b.y < -20 || b.x < -20 || b.x > g.W + 20) g.bullets.splice(i, 1);
    }
    // 敌方子弹
    for (let i = g.enemyBullets.length - 1; i >= 0; i--) {
      const b = g.enemyBullets[i];
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.life <= 0 || b.y > g.H + 30 || b.y < -g.H * 0.5 || b.x < -30 || b.x > g.W + 30) g.enemyBullets.splice(i, 1);
    }
    // 道具
    for (let i = g.items.length - 1; i >= 0; i--) {
      const it = g.items[i];
      it.t += dt;
      it.y += it.vy * dt;
      it.x += Math.sin(it.t * 3 + it.phase) * g.W * 0.035 * dt;
      if (it.y > g.H + it.r * 2) g.items.splice(i, 1);
    }
    sfCheckCollisions(g);
    sfUpdateParticles(g, dt);
    if (g.domT <= 0) { g.domT = 0.5; sfUpdateDomHud(g); }
    else g.domT -= dt;
  }

  function sfBossShoot(g, b) {
    const p = g.player;
    const aim = sfAimAngle(g, b.x, b.y + b.h * 0.25);
    const speed = g.H * (0.21 + b.phase * 0.02);
    const color = b.phase === 1 ? '#F472B6' : (b.phase === 2 ? '#C084FC' : '#FB7185');
    b.shotCount++;
    if (b.phase === 1) {
      if (b.shotCount % 4 === 0) {
        for (let i = -3; i <= 3; i++) sfEnemyBullet(g, b.x, b.y + b.h * 0.3, Math.PI / 2 + i * 0.16, speed * 0.80, color, Math.max(4, Math.min(g.W, g.H) * 0.015));
      } else {
        for (let i = -1; i <= 1; i++) sfEnemyBullet(g, b.x, b.y + b.h * 0.3, aim + i * 0.18, speed, color, Math.max(4, Math.min(g.W, g.H) * 0.015));
      }
      b.shootT = 1.4;
    } else if (b.phase === 2) {
      b.spiral += 0.38;
      sfEnemyBullet(g, b.x, b.y + b.h * 0.18, b.spiral, speed * 0.86, color, Math.max(4, Math.min(g.W, g.H) * 0.016));
      if (b.shotCount % 6 === 0) {
        for (let i = -1; i <= 1; i++) sfEnemyBullet(g, b.x, b.y + b.h * 0.3, aim + i * 0.2, speed, color, Math.max(4, Math.min(g.W, g.H) * 0.016));
      }
      b.shootT = 0.5;
    } else {
      for (let i = -1; i <= 1; i++) sfEnemyBullet(g, b.x, b.y + b.h * 0.2, Math.PI / 2 + i * 0.22, speed, color, Math.max(5, Math.min(g.W, g.H) * 0.017));
      if (b.shotCount % 3 === 0) {
        for (const side of [-1, 1]) sfEnemyBullet(g, b.x + side * b.w * 0.42, b.y + b.h * 0.25, Math.PI / 2 + side * 0.12, speed * 0.9, '#FB7185', Math.max(4, Math.min(g.W, g.H) * 0.015));
      }
      b.shootT = 0.8;
    }
  }

  function sfCheckCollisions(g) {
    if (!g || g.over) return;
    const p = g.player;
    for (let i = g.bullets.length - 1; i >= 0; i--) {
      const b = g.bullets[i];
      let remove = false;
      b.hitIds = b.hitIds || [];
      for (let j = g.enemies.length - 1; j >= 0; j--) {
        const e = g.enemies[j];
        if (!e) continue;
        if (b.hitIds.indexOf(e.id) >= 0) continue;
        if (Math.abs(b.x - e.x) <= e.r * 0.95 + b.r && Math.abs(b.y - e.y) <= e.r * 1.05 + b.r) {
          e.hp -= b.dmg;
          e.hitFlash = 0.08;
          b.hitIds.push(e.id);
          sfAddParticle(g, b.x, b.y, sfRand(-30, 30), sfRand(-50, 10), 0.18, b.color || '#A5F3FC', 2, 'square');
          if (b.explosive) sfSplashDamage(g, b.x, b.y, b.splash || Math.min(g.W, g.H) * 0.08, b.dmg * 0.65, b.color);
          if (e.hp <= 0 && g.enemies.indexOf(e) >= 0) sfKillEnemy(g, e, true);
          if (!b.pierce) { remove = true; break; }
        }
      }
      if (!remove && g.boss && !g.boss.entering) {
        const bo = g.boss;
        if (b.hitIds.indexOf('boss') < 0 && Math.abs(b.x - bo.x) <= bo.w * 0.5 + b.r && Math.abs(b.y - bo.y) <= bo.h * 0.5 + b.r) {
          b.hitIds.push('boss');
          sfDamageBoss(g, bo, b.dmg);
          sfAddParticle(g, b.x, b.y, sfRand(-30, 30), sfRand(-40, 20), 0.16, b.color || '#F9A8D4', 2, 'square');
          if (b.explosive) sfSplashDamage(g, b.x, b.y, b.splash || Math.min(g.W, g.H) * 0.08, b.dmg * 0.65, b.color);
          if (!b.pierce) remove = true;
        }
      }
      if (remove) g.bullets.splice(i, 1);
    }
    if (g.over) return;
    for (let i = g.enemyBullets.length - 1; i >= 0; i--) {
      const b = g.enemyBullets[i];
      if (sfHitCircle(p.x, p.y, p.r * 0.72, b.x, b.y, b.r)) {
        g.enemyBullets.splice(i, 1);
        sfDamagePlayer(g, 1);
      }
    }
    if (g.over) return;
    for (let i = g.enemies.length - 1; i >= 0; i--) {
      const e = g.enemies[i];
      if (sfHitCircle(p.x, p.y, p.r * 0.7, e.x, e.y, e.r * 0.85)) {
        sfKillEnemy(g, e, false);
        sfDamagePlayer(g, 1);
      }
    }
    if (g.boss && !g.boss.entering && sfHitCircle(p.x, p.y, p.r * 0.7, g.boss.x, g.boss.y, Math.min(g.boss.w, g.boss.h) * 0.42)) {
      sfDamagePlayer(g, 1);
    }
    if (g.over) return;
    for (let i = g.items.length - 1; i >= 0; i--) {
      const it = g.items[i];
      if (sfHitCircle(p.x, p.y, p.r * 0.9, it.x, it.y, it.r)) {
        const activeWeapons = (p.weapons || []).filter(w => w && w.expiresAt > g.time);
        if (it.type === 'weapon' && (activeWeapons.length >= 2 || (activeWeapons.length === 1 && activeWeapons[0].type === it.weapon))) continue;
        g.items.splice(i, 1);
        sfCollectItem(g, it);
      }
    }
  }

  function sfUpdateParticles(g, dt) {
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const pt = g.particles[i];
      pt.x += pt.vx * dt;
      pt.y += pt.vy * dt;
      pt.vx *= 0.985;
      pt.vy *= 0.985;
      pt.life -= dt;
      if (pt.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.rings.length - 1; i >= 0; i--) {
      const r = g.rings[i];
      r.life -= dt;
      if (r.life <= 0) g.rings.splice(i, 1);
    }
    for (let i = g.texts.length - 1; i >= 0; i--) {
      const t = g.texts[i];
      t.y += t.vy * dt;
      t.life -= dt;
      if (t.life <= 0) g.texts.splice(i, 1);
    }
  }

  function sfTick(ts) {
    const g = sfGame;
    if (!g) return;
    if (!g.canvas || (g.canvas.isConnected === false)) { sfTeardown(false); return; }
    const now = ts || sfNow();
    const dt = Math.min(0.05, Math.max(0.001, ((now - g.lastTs) / 1000) || 0.016));
    g.lastTs = now;
    sfUpdate(g, dt);
    sfDraw(g);
    if (g.stopped) return;
    g.rafId = sfRaf(sfTick);
  }

  // ---- 绘制：星空 / 实体 / 弹幕 / HUD ----
  function sfDraw(g) {
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, (typeof window !== 'undefined' && window.devicePixelRatio) || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.ctx = ctx;
    const sizeChanged = Math.abs(g.W - cssW) > 1 || Math.abs(g.H - cssH) > 1;
    g.W = cssW;
    g.H = cssH;
    if (g._firstDraw) { g._firstDraw = false; sfPlacePlayer(g); }
    else if (sizeChanged) sfClampWorld(g);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    sfEnsureStars(g);
    sfDrawBackground(g, ctx);
    const shakeX = g.shake > 0 ? (Math.random() - 0.5) * 10 * g.shake : 0;
    const shakeY = g.shake > 0 ? (Math.random() - 0.5) * 10 * g.shake : 0;
    ctx.save();
    ctx.translate(shakeX, shakeY);
    sfDrawItems(g, ctx);
    sfDrawEnemies(g, ctx);
    if (g.boss) sfDrawBoss(g, ctx);
    sfDrawPlayerBullets(g, ctx);
    sfDrawPlayerBeams(g, ctx);
    sfDrawEnemyBullets(g, ctx);
    sfDrawPlayer(g, ctx);
    sfDrawParticles(g, ctx);
    sfDrawRings(g, ctx);
    sfDrawTexts(g, ctx);
    ctx.restore();
    if (g.flash > 0) {
      ctx.fillStyle = 'rgba(255,255,255,' + Math.min(0.55, g.flash) + ')';
      ctx.fillRect(0, 0, g.W, g.H);
    }
    sfDrawHud(g, ctx);
  }

  function sfDrawBackground(g, ctx) {
    const W = g.W, H = g.H;
    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#020617');
    bg.addColorStop(0.45, '#050b1f');
    bg.addColorStop(1, '#030712');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    if (SF_ART.background) {
      try { ctx.globalAlpha = 0.55; ctx.drawImage(SF_ART.background, 0, 0, W, H); } catch (e) { /* ignore */ }
      ctx.globalAlpha = 1;
    }
    for (const n of g.nebulas) {
      const nx = n.x * W + Math.sin(g.time * n.drift + n.ph) * W * 0.04;
      const ny = n.y * H;
      const nr = n.r * Math.min(W, H);
      const grd = ctx.createRadialGradient(nx, ny, 0, nx, ny, nr);
      grd.addColorStop(0, n.c1);
      grd.addColorStop(1, n.c2);
      ctx.fillStyle = grd;
      ctx.fillRect(nx - nr, ny - nr, nr * 2, nr * 2);
    }
    // 深空星尘：三层视差
    for (const st of g.stars) {
      const tw = 0.72 + 0.28 * Math.sin(g.time * (1.2 + st.z) + st.tw);
      ctx.globalAlpha = (0.25 + st.z * 0.7) * tw;
      ctx.fillStyle = st.c;
      ctx.fillRect(st.x, st.y, st.r, st.r);
    }
    ctx.globalAlpha = 1;
    // 极淡的扫描线，增强像素科幻质感
    ctx.fillStyle = 'rgba(148,163,184,0.025)';
    for (let y = 0; y < H; y += 4) ctx.fillRect(0, y, W, 1);
  }

  function sfDrawPlayer(g, ctx) {
    const p = g.player;
    if (!p) return;
    const r = p.r;
    const blink = p.invuln > 0 && Math.floor(g.time * 18) % 2 === 0;
    if (blink) ctx.globalAlpha = 0.45;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.tilt || 0);
    if (SF_ART.player) {
      try { ctx.drawImage(SF_ART.player, -r * 1.8, -r * 1.8, r * 3.6, r * 3.6); ctx.restore(); ctx.globalAlpha = 1; return; } catch (e) { /* ignore */ }
    }
    // 尾焰
    const flame = 0.8 + 0.2 * Math.sin(g.time * 34);
    const fg = ctx.createLinearGradient(0, r * 0.6, 0, r * 2.4);
    fg.addColorStop(0, 'rgba(125,211,252,0.95)');
    fg.addColorStop(0.45, 'rgba(56,189,248,0.55)');
    fg.addColorStop(1, 'rgba(56,189,248,0)');
    ctx.fillStyle = fg;
    ctx.beginPath();
    ctx.moveTo(-r * 0.34, r * 0.65);
    ctx.lineTo(0, r * (1.8 + flame * 0.35));
    ctx.lineTo(r * 0.34, r * 0.65);
    ctx.closePath();
    ctx.fill();
    // 能量炮翼
    ctx.fillStyle = 'rgba(56,189,248,0.82)';
    ctx.beginPath();
    ctx.moveTo(-r * 0.3, -r * 0.2);
    ctx.lineTo(-r * 1.55, r * 0.5);
    ctx.lineTo(-r * 0.62, r * 0.74);
    ctx.lineTo(-r * 0.18, r * 0.3);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(r * 0.3, -r * 0.2);
    ctx.lineTo(r * 1.55, r * 0.5);
    ctx.lineTo(r * 0.62, r * 0.74);
    ctx.lineTo(r * 0.18, r * 0.3);
    ctx.closePath();
    ctx.fill();
    // 银蓝色机甲主体
    ctx.fillStyle = '#E2E8F0';
    ctx.beginPath();
    ctx.moveTo(0, -r * 1.3);
    ctx.lineTo(r * 0.56, r * 0.18);
    ctx.lineTo(r * 0.32, r * 0.88);
    ctx.lineTo(-r * 0.32, r * 0.88);
    ctx.lineTo(-r * 0.56, r * 0.18);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(224,242,254,0.95)';
    ctx.lineWidth = Math.max(1, r * 0.08);
    ctx.stroke();
    // 蓝色装甲条
    ctx.fillStyle = '#38BDF8';
    ctx.beginPath();
    ctx.moveTo(0, -r * 0.95);
    ctx.lineTo(r * 0.22, r * 0.2);
    ctx.lineTo(0, r * 0.62);
    ctx.lineTo(-r * 0.22, r * 0.2);
    ctx.closePath();
    ctx.fill();
    // 驾驶舱
    ctx.fillStyle = '#A5F3FC';
    ctx.beginPath();
    ctx.arc(0, -r * 0.32, r * 0.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.8)';
    ctx.beginPath();
    ctx.arc(-r * 0.06, -r * 0.4, r * 0.06, 0, Math.PI * 2);
    ctx.fill();
    // 机炮
    ctx.fillStyle = '#7DD3FC';
    ctx.fillRect(-r * 0.86, r * 0.16, r * 0.18, r * 0.72);
    ctx.fillRect(r * 0.68, r * 0.16, r * 0.18, r * 0.72);
    ctx.restore();
    ctx.globalAlpha = 1;
    // 护盾环
    if (p.shield > 0) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.strokeStyle = 'rgba(56,189,248,0.72)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, r * (1.7 + Math.sin(g.time * 5) * 0.08), 0, Math.PI * 2);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(165,243,252,0.28)';
      ctx.beginPath();
      ctx.arc(0, 0, r * 2.0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
  }

  function sfDrawEnemies(g, ctx) {
    for (const e of g.enemies) {
      const r = e.r;
      ctx.save();
      ctx.translate(e.x, e.y);
      const art = SF_ART.enemy[e.type];
      if (art) {
        try { ctx.drawImage(art, -r * 1.8, -r * 1.8, r * 3.6, r * 3.6); ctx.restore(); continue; } catch (err) { /* ignore */ }
      }
      if (e.type === 'dart') {
        ctx.fillStyle = e.color;
        ctx.beginPath();
        ctx.moveTo(0, r * 1.05);
        ctx.lineTo(r * 0.58, -r * 0.65);
        ctx.lineTo(0, -r * 0.2);
        ctx.lineTo(-r * 0.58, -r * 0.65);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = '#FEF9C3';
        ctx.beginPath();
        ctx.arc(0, -r * 0.18, r * 0.18, 0, Math.PI * 2);
        ctx.fill();
      } else if (e.type === 'elite') {
        ctx.fillStyle = '#3B0764';
        ctx.beginPath();
        ctx.moveTo(0, r * 1.05);
        ctx.lineTo(r * 0.95, r * 0.3);
        ctx.lineTo(r * 0.72, -r * 0.85);
        ctx.lineTo(-r * 0.72, -r * 0.85);
        ctx.lineTo(-r * 0.95, r * 0.3);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = e.color;
        ctx.lineWidth = Math.max(1.5, r * 0.12);
        ctx.stroke();
        ctx.fillStyle = e.color;
        ctx.fillRect(-r * 0.72, -r * 0.18, r * 0.3, r * 0.5);
        ctx.fillRect(r * 0.42, -r * 0.18, r * 0.3, r * 0.5);
        ctx.fillStyle = '#F9A8D4';
        ctx.beginPath();
        ctx.arc(0, 0, r * 0.24 + Math.sin(g.time * 4 + e.phase) * r * 0.04, 0, Math.PI * 2);
        ctx.fill();
        // 精英血条
        const bw = r * 2.2, bh = Math.max(2, r * 0.12);
        ctx.fillStyle = 'rgba(2,6,23,0.65)';
        ctx.fillRect(-bw / 2, -r * 1.35, bw, bh);
        ctx.fillStyle = e.color;
        ctx.fillRect(-bw / 2, -r * 1.35, bw * Math.max(0, e.hp / e.maxHp), bh);
      } else {
        ctx.fillStyle = e.color;
        ctx.beginPath();
        ctx.moveTo(0, r * 1.05);
        ctx.lineTo(r * 0.9, -r * 0.55);
        ctx.lineTo(r * 0.3, -r * 0.95);
        ctx.lineTo(-r * 0.3, -r * 0.95);
        ctx.lineTo(-r * 0.9, -r * 0.55);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = '#FECDD3';
        ctx.beginPath();
        ctx.arc(0, -r * 0.05, r * 0.28, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.55)';
        ctx.fillRect(-r * 0.12, r * 0.32, r * 0.24, r * 0.4);
      }
      if (e.hitFlash > 0) {
        ctx.globalAlpha = Math.min(0.8, e.hitFlash * 9);
        ctx.fillStyle = '#FFFFFF';
        ctx.beginPath();
        ctx.arc(0, 0, r * 1.05, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      ctx.restore();
    }
  }

  function sfDrawBoss(g, ctx) {
    const b = g.boss;
    if (!b) return;
    if (SF_ART.boss) {
      try { ctx.drawImage(SF_ART.boss, b.x - b.w / 2, b.y - b.h / 2, b.w, b.h); return; } catch (e) { /* ignore */ }
    }
    ctx.save();
    ctx.translate(b.x, b.y);
    const w = b.w, h = b.h;
    // 母舰外轮廓
    ctx.fillStyle = 'rgba(244,114,182,0.08)';
    ctx.beginPath();
    ctx.arc(0, 0, w * 0.55, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#111827';
    ctx.beginPath();
    ctx.moveTo(-w * 0.5, -h * 0.1);
    ctx.lineTo(-w * 0.36, -h * 0.56);
    ctx.lineTo(w * 0.36, -h * 0.56);
    ctx.lineTo(w * 0.5, -h * 0.1);
    ctx.lineTo(w * 0.42, h * 0.5);
    ctx.lineTo(-w * 0.42, h * 0.5);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#4B5563';
    ctx.lineWidth = Math.max(1.5, h * 0.04);
    ctx.stroke();
    // 装甲层
    ctx.fillStyle = '#374151';
    ctx.fillRect(-w * 0.38, -h * 0.28, w * 0.76, h * 0.18);
    ctx.fillStyle = '#1F2937';
    ctx.fillRect(-w * 0.3, h * 0.02, w * 0.6, h * 0.16);
    // 侧翼炮台
    ctx.fillStyle = '#4B5563';
    ctx.fillRect(-w * 0.56, -h * 0.05, w * 0.12, h * 0.3);
    ctx.fillRect(w * 0.44, -h * 0.05, w * 0.12, h * 0.3);
    ctx.fillStyle = '#9CA3AF';
    ctx.fillRect(-w * 0.52, h * 0.18, w * 0.07, h * 0.22);
    ctx.fillRect(w * 0.45, h * 0.18, w * 0.07, h * 0.22);
    // 中央核心
    const pulse = 0.8 + 0.2 * Math.sin(g.time * 6.5);
    const coreColor = b.phase === 1 ? '244,114,182' : (b.phase === 2 ? '192,132,252' : '251,113,133');
    const cg = ctx.createRadialGradient(0, 0, 0, 0, 0, w * 0.2);
    cg.addColorStop(0, 'rgba(255,255,255,' + (0.9 * pulse) + ')');
    cg.addColorStop(0.22, 'rgba(' + coreColor + ',0.95)');
    cg.addColorStop(0.6, 'rgba(' + coreColor + ',0.35)');
    cg.addColorStop(1, 'rgba(' + coreColor + ',0)');
    ctx.fillStyle = cg;
    ctx.beginPath();
    ctx.arc(0, 0, w * 0.22 * pulse, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.beginPath();
    ctx.arc(0, 0, w * 0.045, 0, Math.PI * 2);
    ctx.fill();
    // 炮口
    ctx.fillStyle = 'rgba(' + coreColor + ',0.85)';
    for (const side of [-1, 1]) {
      ctx.fillRect(side * w * 0.3 - w * 0.02, h * 0.3, w * 0.04, h * 0.16);
    }
    if (b.hitFlash > 0) {
      ctx.globalAlpha = Math.min(0.55, b.hitFlash * 6);
      ctx.fillStyle = '#FFFFFF';
      ctx.beginPath();
      ctx.arc(0, 0, w * 0.38, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  }

  function sfDrawPlayerBullets(g, ctx) {
    for (const b of g.bullets) {
      const ang = Math.atan2(b.vy, b.vx) + Math.PI / 2;
      ctx.save();
      ctx.translate(b.x, b.y);
      ctx.rotate(ang);
      ctx.globalAlpha = 0.22;
      ctx.fillStyle = b.color || '#22D3EE';
      if (b.shape === 'missile') {
        ctx.beginPath(); ctx.arc(0, 0, b.r * 2.2, 0, Math.PI * 2); ctx.fill();
      } else if (b.shape === 'shell') {
        ctx.beginPath(); ctx.arc(0, 0, b.r * 2.4, 0, Math.PI * 2); ctx.fill();
      } else {
        ctx.fillRect(-b.r * 1.8, -b.r * 3, b.r * 3.6, b.r * 6);
      }
      ctx.globalAlpha = 1;
      if (b.shape === 'missile') {
        ctx.fillStyle = b.color || '#F472B6';
        ctx.beginPath();
        ctx.moveTo(0, -b.r * 2.2);
        ctx.lineTo(b.r * 0.8, b.r * 0.8);
        ctx.lineTo(0, b.r * 1.6);
        ctx.lineTo(-b.r * 0.8, b.r * 0.8);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = b.color2 || '#FB7185';
        ctx.lineWidth = Math.max(1, b.r * 0.25);
        ctx.stroke();
        ctx.fillStyle = '#FDE68A';
        ctx.beginPath(); ctx.moveTo(-b.r * 0.45, b.r * 1.3); ctx.lineTo(0, b.r * 2.8); ctx.lineTo(b.r * 0.45, b.r * 1.3); ctx.closePath(); ctx.fill();
      } else if (b.shape === 'shell') {
        ctx.fillStyle = b.color || '#F59E0B';
        ctx.beginPath(); ctx.arc(0, 0, b.r * 1.25, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#78350F';
        ctx.fillRect(-b.r * 1.1, -b.r * 0.16, b.r * 2.2, b.r * 0.32);
        ctx.fillStyle = b.color2 || '#FCD34D';
        ctx.beginPath(); ctx.arc(-b.r * 0.35, -b.r * 0.35, b.r * 0.32, 0, Math.PI * 2); ctx.fill();
      } else if (b.shape === 'triangle') {
        ctx.fillStyle = b.color || '#A3E635';
        ctx.beginPath();
        ctx.moveTo(0, -b.r * 2.4);
        ctx.lineTo(b.r * 1.1, b.r * 1.4);
        ctx.lineTo(0, b.r * 0.7);
        ctx.lineTo(-b.r * 1.1, b.r * 1.4);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = Math.max(1, b.r * 0.2);
        ctx.stroke();
      } else if (b.shape === 'tiny') {
        ctx.fillStyle = b.color2 || '#F97316';
        ctx.fillRect(-b.r * 0.45, -b.r * 1.7, b.r * 0.9, b.r * 3.4);
        ctx.fillStyle = '#FFF7ED';
        ctx.fillRect(-b.r * 0.22, -b.r * 1.4, b.r * 0.44, b.r * 1.5);
      } else if (b.shape === 'dot') {
        ctx.fillStyle = b.color || '#FDE047';
        ctx.beginPath(); ctx.arc(0, 0, b.r * 1.15, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#FFFDE7';
        ctx.beginPath(); ctx.arc(-b.r * 0.2, -b.r * 0.2, b.r * 0.35, 0, Math.PI * 2); ctx.fill();
      } else {
        ctx.fillStyle = b.color2 || '#38BDF8';
        ctx.fillRect(-b.r * 1.05, -b.r * 2.2, b.r * 2.1, b.r * 4.4);
        ctx.fillStyle = '#E0F2FE';
        ctx.fillRect(-b.r * 0.48, -b.r * 1.7, b.r * 0.96, b.r * 3.4);
        ctx.fillStyle = b.color || '#67E8F9';
        ctx.fillRect(-b.r * 0.3, -b.r * 2.5, b.r * 0.6, b.r * 1.8);
      }
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  }

  function sfDrawEnemyBullets(g, ctx) {
    for (const b of g.enemyBullets) {
      ctx.globalAlpha = 0.2;
      ctx.fillStyle = b.color;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r * 2.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 0.85;
      ctx.fillStyle = b.color;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#FFF1F2';
      ctx.beginPath();
      ctx.arc(b.x - b.r * 0.18, b.y - b.r * 0.18, Math.max(1, b.r * 0.36), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function sfDrawItems(g, ctx) {
    for (const it of g.items) {
      const r = it.r;
      const def = it.type === 'weapon' ? sfWeaponDef(it.weapon) : (SF_ITEM_DEFS[it.type] || SF_ITEM_DEFS.weapon);
      const art = SF_ART.item[it.type === 'weapon' ? it.weapon : it.type];
      if (art) {
        try { ctx.drawImage(art, it.x - r * 1.6, it.y - r * 1.6, r * 3.2, r * 3.2); continue; } catch (e) { /* ignore */ }
      }
      const bob = Math.sin(it.t * 3 + it.phase) * 1.2;
      const color = it.color || (def ? def.color : '#A78BFA');
      ctx.save();
      ctx.translate(it.x, it.y + bob);
      ctx.globalAlpha = 0.22;
      ctx.fillStyle = color;
      ctx.beginPath(); ctx.arc(0, 0, r * 2.3, 0, Math.PI * 2); ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = 'rgba(2,6,23,0.82)';
      ctx.beginPath(); ctx.arc(0, 0, r * 1.18, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = Math.max(1.5, r * 0.16);
      ctx.beginPath(); ctx.arc(0, 0, r * 1.18, 0, Math.PI * 2); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.42)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(0, 0, r * 1.02, 0, Math.PI * 2); ctx.stroke();
      sfDrawItemGlyph(ctx, it.type, it.weapon, r * 0.85);
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  }

  function sfDrawParticles(g, ctx) {
    for (const p of g.particles) {
      const a = Math.max(0, p.life / p.maxLife);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      if (p.shape === 'circle') {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
      }
    }
    ctx.globalAlpha = 1;
  }

  function sfDrawRings(g, ctx) {
    for (const r of g.rings) {
      const a = Math.max(0, r.life / r.maxLife);
      const rr = r.maxR * (1 - a);
      ctx.globalAlpha = a * 0.55;
      ctx.strokeStyle = r.color;
      ctx.lineWidth = Math.max(1, r.maxR * 0.025);
      ctx.beginPath();
      ctx.arc(r.x, r.y, Math.max(1, rr), 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }

  function sfDrawTexts(g, ctx) {
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (const t of g.texts) {
      const a = Math.max(0, t.life / t.maxLife);
      ctx.globalAlpha = a;
      ctx.font = '700 ' + Math.round(t.size) + 'px "Courier New", monospace';
      ctx.fillStyle = t.color;
      ctx.fillText(t.text, t.x, t.y);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  }

  function sfDrawHeart(ctx, x, y, s, filled) {
    ctx.beginPath();
    ctx.moveTo(x, y + s * 0.32);
    ctx.bezierCurveTo(x + s * 0.5, y - s * 0.2, x + s, y + s * 0.2, x, y + s * 0.95);
    ctx.bezierCurveTo(x - s, y + s * 0.2, x - s * 0.5, y - s * 0.2, x, y + s * 0.32);
    ctx.closePath();
    ctx.fillStyle = filled ? '#F43F5E' : 'rgba(244,63,94,0.16)';
    ctx.fill();
    if (filled) {
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }

  function sfDrawBombIcon(ctx, x, y, s, color) {
    ctx.fillStyle = color || '#F59E0B';
    ctx.beginPath();
    ctx.arc(x, y + s * 0.2, s * 0.62, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#FDE68A';
    ctx.lineWidth = Math.max(1, s * 0.16);
    ctx.beginPath();
    ctx.moveTo(x + s * 0.35, y - s * 0.35);
    ctx.lineTo(x + s * 0.62, y - s * 0.8);
    ctx.stroke();
  }

  function sfDrawHud(g, ctx) {
    const W = g.W, H = g.H, p = g.player;
    // 顶部：分数 / 最高分
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '600 ' + Math.max(9, Math.round(W * 0.026)) + 'px "Courier New", monospace';
    ctx.fillStyle = 'rgba(148,163,184,0.9)';
    ctx.fillText('SCORE', 14, 12);
    ctx.font = '700 ' + Math.max(19, Math.round(W * 0.058)) + 'px "Courier New", monospace';
    ctx.fillStyle = '#E0F2FE';
    ctx.fillText(String(Math.floor(g.score)).padStart(6, '0'), 14, 23);
    ctx.textAlign = 'right';
    ctx.font = '600 ' + Math.max(9, Math.round(W * 0.026)) + 'px "Courier New", monospace';
    ctx.fillStyle = 'rgba(148,163,184,0.9)';
    ctx.fillText('BEST', W - 14, 12);
    ctx.font = '700 ' + Math.max(13, Math.round(W * 0.038)) + 'px "Courier New", monospace';
    ctx.fillStyle = '#FBBF24';
    ctx.fillText(String(Math.max(sfLoadBest(), Math.floor(g.score))), W - 14, 24);
    ctx.textAlign = 'left';
    ctx.font = '600 ' + Math.max(9, Math.round(W * 0.024)) + 'px "Courier New", monospace';
    ctx.fillStyle = 'rgba(125,211,252,0.85)';
    ctx.fillText('WAVE ' + g.wave + '  ·  危险度 ' + g.diff.toFixed(1) + 'x', 14, 50);

    // BOSS 血条
    if (g.boss) {
      const b = g.boss;
      const bw = W * 0.7, bh = Math.max(6, Math.round(H * 0.012));
      const bx = (W - bw) / 2;
      const by = Math.max(68, H * 0.115);
      ctx.fillStyle = 'rgba(2,6,23,0.8)';
      ctx.fillRect(bx - 2, by - 2, bw + 4, bh + 4);
      ctx.fillStyle = '#1E293B';
      ctx.fillRect(bx, by, bw, bh);
      const ratio = Math.max(0, Math.min(1, b.hp / b.maxHp));
      const grd = ctx.createLinearGradient(bx, 0, bx + bw, 0);
      grd.addColorStop(0, '#F43F5E');
      grd.addColorStop(0.55, '#E879F9');
      grd.addColorStop(1, '#C084FC');
      ctx.fillStyle = grd;
      ctx.fillRect(bx, by, bw * ratio, bh);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fillRect(bx + bw / 3, by, 1, bh);
      ctx.fillRect(bx + bw * 2 / 3, by, 1, bh);
      ctx.font = '700 ' + Math.max(9, Math.round(W * 0.026)) + 'px "Courier New", monospace';
      ctx.fillStyle = '#FECDD3';
      ctx.fillText('BOSS', bx, by - Math.max(11, W * 0.032));
      ctx.textAlign = 'right';
      ctx.fillText(Math.max(0, Math.ceil(b.hp)) + ' / ' + b.maxHp, bx + bw, by - Math.max(11, W * 0.032));
      ctx.textAlign = 'left';
    }

    // 底部：生命 / 护盾 / 炸弹 / 武器
    const hs = Math.max(7, Math.round(W * 0.021));
    const hy = H - Math.max(46, H * 0.072);
    for (let i = 0; i < p.maxHp; i++) sfDrawHeart(ctx, 14 + i * hs * 2.15, hy, hs, i < p.hp);
    // 护盾
    let sx = 14 + p.maxHp * hs * 2.15 + 6;
    for (let i = 0; i < p.shield; i++) {
      ctx.fillStyle = '#38BDF8';
      ctx.beginPath();
      ctx.moveTo(sx + i * (hs * 1.5), hy + hs * 0.15);
      ctx.lineTo(sx + i * (hs * 1.5) + hs * 0.48, hy + hs * 0.6);
      ctx.lineTo(sx + i * (hs * 1.5), hy + hs * 1.05);
      ctx.lineTo(sx + i * (hs * 1.5) - hs * 0.48, hy + hs * 0.6);
      ctx.closePath();
      ctx.fill();
    }
    // 炸弹
    const by2 = H - Math.max(20, H * 0.032);
    for (let i = 0; i < p.bombs; i++) sfDrawBombIcon(ctx, 16 + i * hs * 1.9, by2, hs * 0.9, '#F59E0B');
    const weaponProfile = sfBuildWeaponProfile(g);
    ctx.textAlign = 'right';
    ctx.textBaseline = 'alphabetic';
    if (p.weapons && p.weapons.length) {
      ctx.font = '600 ' + Math.max(8, Math.round(W * 0.022)) + 'px "Courier New", monospace';
      ctx.fillStyle = 'rgba(148,163,184,0.78)';
      ctx.fillText(weaponProfile.name, W - 14, H - Math.max(54, H * 0.084));
      let wy = H - Math.max(36, H * 0.056);
      for (let wi = 0; wi < p.weapons.length; wi++) {
        const w = p.weapons[wi];
        const wd = sfWeaponDef(w.type);
        const remain = Math.max(0, Math.ceil(w.expiresAt - g.time));
        ctx.font = '700 ' + Math.max(9, Math.round(W * 0.026)) + 'px "Courier New", monospace';
        ctx.fillStyle = wd ? wd.color : '#E0F2FE';
        ctx.fillText((wd ? wd.name : w.type) + ' ' + remain + 's', W - 14, wy + wi * Math.max(12, H * 0.022));
      }
    } else {
      ctx.font = '600 ' + Math.max(10, Math.round(W * 0.028)) + 'px "Courier New", monospace';
      ctx.fillStyle = 'rgba(148,163,184,0.9)';
      ctx.fillText('基础机炮', W - 14, H - Math.max(24, H * 0.04));
    }
    ctx.textAlign = 'left';

    // 低血量红色边缘
    if (p.hp <= 2) {
      const vg = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.28, W / 2, H / 2, Math.max(W, H) * 0.68);
      vg.addColorStop(0, 'rgba(244,63,94,0)');
      vg.addColorStop(1, 'rgba(244,63,94,0.24)');
      ctx.fillStyle = vg;
      ctx.fillRect(0, 0, W, H);
    }
    // BOSS 警报
    if (g.bossWarnT > 0) {
      const a = 0.45 + 0.55 * Math.abs(Math.sin(g.time * 10));
      ctx.save();
      ctx.globalAlpha = a;
      ctx.fillStyle = 'rgba(244,63,94,0.16)';
      ctx.fillRect(0, H * 0.34, W, H * 0.12);
      ctx.strokeStyle = '#F43F5E';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, H * 0.34, W, H * 0.12);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = '800 ' + Math.max(16, Math.round(W * 0.055)) + 'px "Courier New", monospace';
      ctx.fillStyle = '#FB7185';
      ctx.fillText('⚠ BOSS 接近 ⚠', W / 2, H * 0.4);
      ctx.restore();
      ctx.textAlign = 'left';
      ctx.textBaseline = 'alphabetic';
    }
    if (g.over) {
      ctx.save();
      ctx.globalAlpha = 0.75;
      ctx.fillStyle = 'rgba(2,6,23,0.55)';
      ctx.fillRect(0, 0, W, H);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = '800 ' + Math.max(22, Math.round(W * 0.075)) + 'px "Courier New", monospace';
      ctx.fillStyle = '#F43F5E';
      ctx.fillText('GAME OVER', W / 2, H * 0.46);
      ctx.restore();
      ctx.textAlign = 'left';
      ctx.textBaseline = 'alphabetic';
    }
  }
