    else if (!tetrisCollide(g, g.piece.key, nr, g.piece.x - 1, g.piece.y)) { g.piece.rot = nr; g.piece.x -= 1; }
    else if (!tetrisCollide(g, g.piece.key, nr, g.piece.x + 1, g.piece.y)) { g.piece.rot = nr; g.piece.x += 1; }
    tetrisRender();
