      const vh = window.innerHeight || 640;
      const vw = window.innerWidth || 360;
      const wrap = boardEl.parentElement;
      let usableH = (wrap && wrap.clientHeight > 40) ? (wrap.clientHeight - 8) : (vh - 210);
      let usableW = (wrap && wrap.clientWidth > 40) ? wrap.clientWidth : Math.min(vw, 560);
      // 棋盘总高 = 20*cell + 19(间隙) + 8(内边距) + 2(边框)；总宽 = 10*cell + 9 + 8 + 2
      const byH = Math.floor((usableH - 29) / TETRIS_ROWS);
      const byW = Math.floor((usableW - 19) / TETRIS_COLS);
      cell = Math.max(11, Math.min(44, Math.min(byH, byW)));
