        for (let c = 0; c < shape[r].length; c++) {
          if (!shape[r][c]) continue;
          const y = g.piece.y + r, x = g.piece.x + c;
          if (y >= 0 && y < TETRIS_ROWS && x >= 0 && x < TETRIS_COLS) display[y][x] = g.piece.key;
        }
      }
    }
    let html = '';
    for (let r = 0; r < TETRIS_ROWS; r++) {
      for (let c = 0; c < TETRIS_COLS; c++) {
        const k = display[r][c];
        html += '<div style="width:' + cell + 'px;height:' + cell + 'px;border-radius:3px;background:' + (k ? TETRIS_COLORS[k] : 'rgba(255,255,255,0.045)') + ';border:1px solid ' + (k ? 'rgba(255,255,255,0.25)' : 'rgba(255,255,255,0.05)') + ';box-sizing:border-box;"></div>';
