  function tbRenderBattle() {
    const t = tetrisBattle;
    if (!t) return;
    const cell = tbCellSize();
    const upd = (side, idp) => {
      const be = sheet && sheet.querySelector('#tb-' + idp + '-board');
      if (be) {
        be.style.gridTemplateColumns = 'repeat(' + TETRIS_COLS + ', ' + cell + 'px)';
        be.style.gridAutoRows = cell + 'px';
        be.innerHTML = tbBoardHTML(side, cell);
      }
      const ie = sheet && sheet.querySelector('#tb-' + idp + '-info');
      if (ie) ie.innerHTML = '得分 <b>' + side.score + '</b> · 消行 <b>' + side.lines + '</b>' + (side.pending ? ' · <b style="color:#EF4444;">垃圾 +' + side.pending + '</b>' : '');
      const ne = sheet && sheet.querySelector('#tb-' + idp + '-next');
      if (ne) ne.innerHTML = tbNextHTML(side);
    };
    upd(t.sides.ai, 'ai');
    upd(t.sides.user, 'user');
    const ov = sheet && sheet.querySelector('#tb-overlay');
    if (ov) {
      if (t.over) {
        const userWon = !!(t.winner && !t.winner.isAI);
        ov.style.display = 'flex';
        ov.innerHTML = '<div style="background:var(--ubp-card,#1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:18px 16px;text-align:center;max-width:260px;">' +
          '<div style="font-size:32px;margin-bottom:6px;">' + (userWon ? '🏆' : '💀') + '</div>' +
          '<div style="font-size:16px;font-weight:700;color:' + (userWon ? '#34D399' : '#F87171') + ';">' + (userWon ? '你赢了！' : '你输了') + '</div>' +
          '<div style="font-size:11px;color:var(--ubp-text-2);margin:6px 0 12px;line-height:1.5;">' + escapeHtml(t.reason || '') + '<br>得分 我 ' + t.sides.user.score + ' : ' + t.sides.ai.score + ' ' + escapeHtml(tbOppName()) + '</div>' +
          '<div style="display:flex;gap:6px;">' +
          '<button data-ubp-act="tb-again" class="ubp-btn primary" style="flex:1;padding:7px 0;font-size:12.5px;background:#8B5CF6;border:none;">🔄 再来一局</button>' +
          '<button data-ubp-act="tb-lobby" class="ubp-btn" style="flex:1;padding:7px 0;font-size:12.5px;">🏠 小游戏对战大厅</button>' +
          '</div></div>';
      } else {
        ov.style.display = 'none';
        ov.innerHTML = '';
      }
    }
    t.lastHash = tbStateHash();
  }

  // ---------- 对战主循环与出入口 ----------
  function tbStopBattleTimer() { if (tbBattleTimer) { clearInterval(tbBattleTimer); tbBattleTimer = null; } }
  function tbStartBattleTimer() {
    tbStopBattleTimer();
    tbBattleTimer = setInterval(tbMasterTick, 100);
  }
  function tbMasterTick() {
    const t = tetrisBattle;
    if (!t || t.over) { tbStopBattleTimer(); return; }
    if (!sheet || !sheet.querySelector('#tb-user-board')) { tbStopBattleTimer(); tetrisBattle = null; return; }
    const lv = TB_LEVELS[t.level] || TB_LEVELS.normal;
    const u = t.sides.user, a = t.sides.ai;
    u.dropAcc = (u.dropAcc || 0) + 100;
    if (u.dropAcc >= lv.gravityMs) { u.dropAcc = 0; tbStepDown(u, a); }
    if (!t.over) {
      a.aiAcc = (a.aiAcc || 0) + 100;
      if (a.aiAcc >= lv.aiStepMs) { a.aiAcc = 0; tbAIStep(a, u); }
    }
    if (t.over) { tbRenderBattle(); return; }
    const h = tbStateHash();
    if (h !== t.lastHash) tbRenderBattle();
  }
  function startTetrisBattle(wantOpponentName) {
    tetrisStop();
    tbStopBattleTimer();
    const level = tbLevel();
    // 邀请角色作为对手（与石头剪刀布 / 井字棋一致）：不邀请则默认电脑 AI
    const result = wantOpponentName ? loadContactsWithAvatars() : null;
    const contacts = result?.contacts || [];
    const opp = (wantOpponentName && contacts.find(c => c.name === wantOpponentName)) || null;
    tetrisBattle = {
      level: level,
      opponent: opp ? { name: opp.name, avatar: opp.avatar || getCharacterAvatarByName(opp.name) || '', identity: opp.identity || '' } : null,
      over: false, winner: null, reason: '', lastHash: '',
      sides: { ai: tbNewSide(true), user: tbNewSide(false) }
    };
    tbSpawnPiece(tetrisBattle.sides.ai, tetrisBattle.sides.user);
    if (!tetrisBattle.over) tbSpawnPiece(tetrisBattle.sides.user, tetrisBattle.sides.ai);
    renderTetrisBattleUI();
    if (!tetrisBattle.over) tbStartBattleTimer();
  }
  function tbBackToSingle() {
    tbStopBattleTimer();
    tetrisBattle = null;
    if (tetrisGame) {
      renderTetrisGameUI();
      if (tetrisGame.phase === 'play') tetrisResetTimer();
    } else {
      startTetrisGame();
    }
  }
  function tbQuitToLobby() {
    tbStopBattleTimer();
    tetrisBattle = null;
    renderAIBattleLobby();
  }
  function tbUserMove(dx) {
    const t = tetrisBattle;
    if (!t || t.over) return;
    if (tbMovePiece(t.sides.user, dx)) tbRenderBattle();
  }
  function tbUserRotate() {
    const t = tetrisBattle;
    if (!t || t.over) return;
    if (tbRotatePiece(t.sides.user)) tbRenderBattle();
  }
  function tbUserSoftDrop() {
    const t = tetrisBattle;
    if (!t || t.over) return;
    if (tbStepDown(t.sides.user, t.sides.ai)) tbRenderBattle();
    else if (!t.over) tbRenderBattle();
  }
  function tbUserHardDrop() {
    const t = tetrisBattle;
    if (!t || t.over) return;
    const s = t.sides.user;
    if (!s.piece) return;
    while (!tbCollideBoard(s.board, s.piece.key, s.piece.rot, s.piece.x, s.piece.y + 1)) s.piece.y += 1;
    tbLockAndResolve(s, t.sides.ai);
    tbRenderBattle();
  }

  // ========== 对战邀请角色弹窗（俄罗斯方块：可选择角色作为对手，默认电脑 AI） ==========
