      ov.querySelector('[data-tb-pick-ai]')?.addEventListener('click', () => { chosenAI = true; chosenName = ''; renderContent(); });
      ov.querySelectorAll('[data-tb-pick]').forEach(el => {
        el.addEventListener('click', () => {
          chosenAI = false;
          chosenName = el.dataset.tbPick;
          renderContent();
        });
      });
      ov.querySelector('[data-tb-invite="close"]')?.addEventListener('click', () => { ov.remove(); if (tetrisBattle && !tetrisBattle.over) tbStartBattleTimer(); });
      ov.querySelector('[data-tb-invite="confirm"]')?.addEventListener('click', () => {
