          ${(lk.apiUrl || '').trim() ? '<span class="ubp-api-chip on">独立配置</span>' : '<span class="ubp-api-chip off">沿用游戏 API</span>'}
        </div>
        <div class="ubp-api-info">该配置仅用于对局后的联动 AI 生成，与游戏入口的游戏 API 相互独立；三项均留空时自动沿用游戏 API。</div>
        <label class="ubp-api-label" for="linkage-api-url">联动 API 地址</label>
        <input id="linkage-api-url" class="ubp-fieldinput ubp-api-input" type="text" placeholder="https://api.openai.com/v1" value="${escAttr(lk.apiUrl)}">
        <label class="ubp-api-label" for="linkage-api-key">联动 API Key</label>
        <div class="ubp-api-secret">
          <input id="linkage-api-key" class="ubp-fieldinput ubp-api-input" type="password" placeholder="sk-..." value="${escAttr(lk.apiKey)}">
          <button type="button" class="ubp-api-eye" data-secret-target="linkage-api-key" title="显示 / 隐藏密钥">👁</button>
        </div>
        <label class="ubp-api-label" for="linkage-api-model">联动模型</label>
        <input id="linkage-api-model" class="ubp-fieldinput ubp-api-input" type="text" placeholder="gpt-3.5-turbo" value="${escAttr(lk.model)}">
        <div class="ubp-api-actions">
          <button id="linkage-api-use-game" class="ubp-btn ubp-api-secondary" title="把游戏入口当前的游戏 API 配置填入上方输入框">填入游戏配置</button>
          <button id="linkage-api-cancel" class="ubp-btn ubp-api-ghost">取消</button>
          <button id="linkage-api-save" class="ubp-btn primary ubp-api-primary ubp-api-primary--blue">保存</button>
        </div>
      </div>
    `;
    (overlay && overlay.isConnected ? overlay : sheet).appendChild(ov);

    const close = () => ov.remove();
    ov.addEventListener('click', (e) => { if (e.target === ov) close(); });
