      const show = input.type === 'password';
      input.type = show ? 'text' : 'password';
      btn.textContent = show ? '🙈' : '👁';
    }));
    ov.querySelector('#linkage-api-use-game')?.addEventListener('click', () => {
      const urlEl = ov.querySelector('#linkage-api-url');
      const keyEl = ov.querySelector('#linkage-api-key');
      const modelEl = ov.querySelector('#linkage-api-model');
      if (urlEl) urlEl.value = gameCfg.apiUrl || '';
      if (keyEl) keyEl.value = gameCfg.apiKey || '';
      if (modelEl) modelEl.value = gameCfg.model || '';
      if (!gameCfg.apiUrl) showToast('⚠️ 游戏入口尚未配置 API，请手动填写联动 API');
      else showToast('✅ 已填入游戏 API 配置，点击保存后生效');
    });
    ov.querySelector('#linkage-api-save')?.addEventListener('click', () => {
      const apiUrl = (ov.querySelector('#linkage-api-url')?.value || '').trim();
      const apiKey = (ov.querySelector('#linkage-api-key')?.value || '').trim();
