    const cfg0 = loadConfig();
    let mode = cfg0.wolfPromptMode === 'fair' ? 'fair' : 'persona';
    // 两版提示词各自的编辑缓冲：切换版本不丢失未保存内容
    const buffer = {
      persona: cfg0.prompt || DEFAULT_PROMPT,
      fair: cfg0.promptFair || DEFAULT_PROMPT_FAIR
    };
    const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
    const renderInner = () => {
      const tokenSave = (loadConfig().wolfTokenSave !== false);
      const rpm = getWolfRpm();
      const memoryReplay = (loadConfig().memoryReplay !== false);
      const memoryCount = Math.max(1, Math.min(3, Number(loadConfig().memoryReplayCount) || 3));
      const judgeEnabled = (loadConfig().wolfJudgeEnabled === true);
      const judgeName = String(loadConfig().wolfJudgeName || '').trim();
      const modeBtn = (id, label, active) => '<button data-edit-act="' + id + '" class="ubp-btn" style="flex:1;font-size:12.5px;padding:6px 0;' + (active ? 'border-color:var(--ubp-accent);background:rgba(139,92,246,0.16);font-weight:700;' : '') + '">' + label + '</button>';
      editor.innerHTML = `
        <div style="display:flex;justify-content:space-between;margin-bottom:6px;flex-none;">
          <span style="font-size:16px;font-weight:600;">⚙️ 狼人杀设置</span>
          <button data-edit-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="display:flex;gap:6px;margin-bottom:6px;flex:none;">
          ${modeBtn('mode-persona', '🎭 角色人设版', mode === 'persona')}
