            <summary style="cursor:pointer;color:var(--ubp-text-2);font-size:10.5px;outline:none;">功能说明</summary>
            <div style="margin-top:4px;">开启：向AI发送最近若干场狼人杀完整对局记录（供AI了解其他玩家的说话风格、表水习惯、撒谎破绽、站边态度与历史恩怨）。关闭：不再向AI发送任何历史对局记录。</div>
          </details>
          <div id="wolf-memory-row" style="display:${memoryReplay ? 'flex' : 'none'};align-items:center;gap:8px;margin-top:8px;">
            <span style="font-size:12.5px;color:var(--ubp-text);">发送最近几场对局（1-3，默认 3）：</span>
            <input type="number" id="wolf-memory-input" min="1" max="3" value="${memoryCount}" style="width:70px;padding:4px 6px;border-radius:6px;border:1px solid var(--ubp-line);background:var(--ubp-card);color:var(--ubp-text);font-size:13px;">
          </div>
        </div>
        <div style="flex:none;background:var(--ubp-card-2);border-radius:10px;padding:10px;margin-bottom:8px;">
          <label style="display:flex;align-items:center;justify-content:space-between;cursor:pointer;gap:8px;">
            <span style="font-size:13px;font-weight:600;color:var(--ubp-text);">⚖️ 邀请法官（默认关闭）</span>
            <input type="checkbox" id="wolf-judge-enabled" ${judgeEnabled ? 'checked' : ''} style="width:18px;height:18px;cursor:pointer;flex:none;">
          </label>
          <details style="margin-top:4px;font-size:10.5px;color:var(--ubp-text-3);line-height:1.5;">
            <summary style="cursor:pointer;color:var(--ubp-text-2);font-size:10.5px;outline:none;">功能说明</summary>
            <div style="margin-top:4px;">关闭：按原先（无 法官）的模式，系统直接播报。开启：可在板子选择界面邀请一名角色担任法官，系统播报会显示该角色头像并用该角色音色朗读${judgeName && judgeEnabled ? '（当前：' + escapeHtml(judgeName) + '）' : ''}。</div>
          </details>
        </div>
        <div style="display:flex;gap:8px;flex-none;">
          <button data-edit-act="reset" class="ubp-btn" style="flex:1;">恢复当前版本默认</button>
          <button data-edit-act="save" class="ubp-btn primary" style="flex:1;">保存</button>
        </div>
      `;
      const ta = editor.querySelector('#prompt-editor-text');
      const toggle = editor.querySelector('#wolf-token-save');
      if (toggle) {
        toggle.addEventListener('change', () => {
          const row = editor.querySelector('#wolf-rpm-row');
          if (row) row.style.display = toggle.checked ? 'none' : 'flex';
        });
      }
      const memToggle = editor.querySelector('#wolf-memory-replay');
      if (memToggle) {
        memToggle.addEventListener('change', () => {
          const row = editor.querySelector('#wolf-memory-row');
          if (row) row.style.display = memToggle.checked ? 'flex' : 'none';
        });
      }
      editor.querySelector('[data-edit-act="close"]')?.addEventListener('click', () => editor.remove());
      editor.querySelector('[data-edit-act="mode-persona"]')?.addEventListener('click', () => {
        if (ta) buffer[mode] = ta.value;
        mode = 'persona';
        renderInner();
      });
      editor.querySelector('[data-edit-act="mode-fair"]')?.addEventListener('click', () => {
        if (ta) buffer[mode] = ta.value;
        mode = 'fair';
        renderInner();
      });
      editor.querySelector('[data-edit-act="reset"]')?.addEventListener('click', () => {
        buffer[mode] = mode === 'fair' ? DEFAULT_PROMPT_FAIR : DEFAULT_PROMPT;
        if (ta) ta.value = buffer[mode];
        showToast('已恢复当前版本默认提示词（记得点保存生效）');
      });
      editor.querySelector('[data-edit-act="save"]')?.addEventListener('click', () => {
        const c = loadConfig();
        if (ta) buffer[mode] = ta.value;
        c.wolfPromptMode = mode;
        c.prompt = buffer.persona;
        c.promptFair = buffer.fair;
        const tg = editor.querySelector('#wolf-token-save');
        const rpmInput = editor.querySelector('#wolf-rpm-input');
        if (tg) c.wolfTokenSave = !!tg.checked;
        if (typeof c.wolfTokenSave !== 'boolean') c.wolfTokenSave = true;
        const rpmVal = rpmInput ? parseInt(rpmInput.value, 10) : c.wolfRpm;
        c.wolfRpm = Math.max(1, Math.min(20, Number.isFinite(rpmVal) ? rpmVal : 3));
        const memTg = editor.querySelector('#wolf-memory-replay');
        const memInput = editor.querySelector('#wolf-memory-input');
        if (memTg) c.memoryReplay = !!memTg.checked;
        if (typeof c.memoryReplay !== 'boolean') c.memoryReplay = true;
        const memVal = memInput ? parseInt(memInput.value, 10) : c.memoryReplayCount;
        c.memoryReplayCount = Math.max(1, Math.min(3, Number.isFinite(memVal) ? memVal : 3));
        const judgeTg = editor.querySelector('#wolf-judge-enabled');
        if (judgeTg) c.wolfJudgeEnabled = !!judgeTg.checked;
        if (typeof c.wolfJudgeEnabled !== 'boolean') c.wolfJudgeEnabled = false;
        if (game) game.judgeName = c.wolfJudgeEnabled ? String(c.wolfJudgeName || '').trim() : '';
        saveConfig(c);
        editor.remove();
        showToast('✅ 狼人杀设置已保存（' + (mode === 'fair' ? '绝对公平版' : '角色人设版') + (c.wolfTokenSave ? '，节约Token：开' : ('，节约Token：关（RPM=' + c.wolfRpm + '）')) + '，记忆回放：' + (c.memoryReplay ? ('开（最近' + c.memoryReplayCount + '场）') : '关') + '，邀请法官：' + (c.wolfJudgeEnabled ? (String(c.wolfJudgeName || '').trim() || '开（未选择）') : '关') + '）');
        if (sheet) renderBoard();
      });
    };
    renderInner();
    sheet.appendChild(editor);
  }

  function renderJudgePicker() {
    const cfg = loadConfig();
    const current = cfg.wolfJudgeEnabled === true ? String(cfg.wolfJudgeName || '').trim() : '';
    const playerNames = (game && Array.isArray(game.players)) ? game.players.filter(pl => pl && !pl.isUser).map(pl => pl.name) : [];
    const contactMap = {};
    try {
      const result = loadContactsWithAvatars();
      ((result && result.contacts) || []).forEach(ct => { if (ct && ct.name) contactMap[ct.name] = ct; });
    } catch (e) { /* ignore */ }
    const list = [{ name: '', identity: '系统播报（无角色头像与音色）', avatar: '', inPlayers: false, noJudge: true }];
    const seen = {};
    const add = (name, identity) => {
      if (!name || seen[name]) return;
      seen[name] = true;
      const ct = contactMap[name] || {};
      list.push({ name: name, identity: identity || ct.identity || '', avatar: ct.avatar || getCharacterAvatarByName(name) || '', inPlayers: playerNames.some(n => isNameMatch(n, name)) });
    };
    Object.keys(contactMap).forEach(name => add(name, ''));
    let sel = list.some(x => x.name === current) ? current : '';
    const ov = document.createElement('div');
    ov.className = 'judge-picker-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:64;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const rows = list.map(ct => {
        const blocked = !!ct.inPlayers;
        const on = !blocked && sel === ct.name;
        const displayName = ct.noJudge ? '不使用法官' : ct.name;
        const avatarHTML = ct.noJudge
          ? '<span style="display:inline-flex;width:34px;height:34px;border-radius:50%;align-items:center;justify-content:center;background:rgba(245,158,11,0.14);color:#F59E0B;font-size:17px;">⚖️</span>'
          : chatAvatarHTML(ct.name, false, 34, ct.avatar);
        return '<div data-judge-pick="' + escapeHtml(ct.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:' + (blocked ? 'not-allowed' : 'pointer') + ';background:' + (blocked ? 'rgba(107,114,128,0.08)' : (on ? 'rgba(245,158,11,0.16)' : 'var(--ubp-card-2)')) + ';border:1.5px solid ' + (blocked ? 'var(--ubp-line)' : (on ? '#F59E0B' : 'var(--ubp-line)')) + ';' + (blocked ? 'opacity:0.55;' : '') + '">' +
          '<div style="flex:none;">' + avatarHTML + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(displayName) + (blocked ? '<span style="margin-left:6px;font-size:9.5px;color:#6B7280;border:1px solid #6B7280;border-radius:4px;padding:0 3px;">已在玩家席</span>' : '') + '</div>' +
          (ct.identity ? '<div style="font-size:10.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">' + escapeHtml(ct.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:15px;color:#F59E0B;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
        '<span style="font-size:15px;font-weight:600;">⚖️ 邀请法官</span>' +
        '<button data-judge-act="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;line-height:1.5;">选择一个角色担任本局法官：系统播报会显示该角色头像，并用该角色的音色朗读。不选择则使用系统播报；法官不能同时作为玩家。</div>' +
        '<div style="flex:1;overflow-y:auto;margin-bottom:8px;">' + rows + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-judge-act="confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#F59E0B;border:none;border-radius:6px;">确认法官</button></div>';
      ov.querySelectorAll('[data-judge-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const name = el.dataset.judgePick || '';
          const item = list.find(x => x.name === name);
          if (item && item.inPlayers) { showToast('该角色已在玩家席，不能同时担任法官'); return; }
          sel = name;
          renderContent();
        });
      });
      ov.querySelector('[data-judge-act="close"]')?.addEventListener('click', () => { ov.remove(); });
      ov.querySelector('[data-judge-act="confirm"]')?.addEventListener('click', () => {
        const chosen = list.find(x => x.name === sel);
        if (chosen && chosen.inPlayers) { showToast('该角色已在玩家席，不能同时担任法官'); return; }
        cfg.wolfJudgeName = sel || '';
        cfg.wolfJudgeEnabled = true;
        saveConfig(cfg);
        if (game) game.judgeName = sel || '';
        ov.remove();
        renderBoard();
        showToast(sel ? ('⚖️ 本局法官：' + sel) : '⚖️ 未邀请法官，使用系统播报');
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

  function renderInvite(boardSize, boardVariant) {
    identityPackOpen = false;
    boardSize = [6, 7, 8, 9, 10, 12].indexOf(Number(boardSize)) !== -1 ? Number(boardSize) : 6;
    const cfgInv = loadConfig();
    const requestedVariant = String(boardVariant || cfgInv.wolfBoardVariant || 'classic');
    const boardMode = boardSize === 7 ? 'onecut'
      : boardSize === 8 ? 'ent8'
      : boardSize === 10
      ? ((requestedVariant === 'wwknight') ? 'wwknight' : (requestedVariant === 'hunter10' ? 'hunter10' : 'beauty10'))
      : (boardSize === 12 && requestedVariant === 'wwknight') ? 'wwknight'
      : (boardSize === 12 && requestedVariant === 'beauty') ? 'beauty'
      : (boardSize === 6 && requestedVariant === 'guard6') ? 'guard6'
      : 'classic';
    const judgeName = getConfiguredJudgeName();
    if (cfgInv.wolfBoardSize !== boardSize || (cfgInv.wolfBoardVariant || 'classic') !== boardMode) { cfgInv.wolfBoardSize = boardSize; cfgInv.wolfBoardVariant = boardMode; saveConfig(cfgInv); }
    ubPreloadAndRefreshInvite();
    const result = loadContactsWithAvatars();
    if (!result || result.error) {
      sheet.innerHTML = `<div class="ubp-empty">❌ 无法读取通讯录，请确保神数据库已安装。</div>`;
      return;
    }
    // 防止重复打开时旧弹窗叠在新弹窗下（点击穿透会造成选人错乱）
    const oldInv = sheet.querySelector('.invite-overlay');
    if (oldInv) oldInv.remove();
    const contacts = result.contacts || [];
    const inv0 = loadShopInventory();
    const spectatorAvail = (inv0.spectator || 0) > 0;
    let spectatorMode = false;
    let need = boardSize - 1;
    let max = need;
    const listHtml = contacts.filter(c => !judgeName || !isNameMatch(c.name, judgeName)).map(c => {
      const avatar = c.avatar || getCharacterAvatarByName(c.name);
      const idTag = c.identity ? `<span style="font-size:11.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:normal;" title="${escapeAttr(c.identity)}">${escapeHtml(c.identity)}</span>` : '';
      const fallbackInitial = escapeHtml(c.name.slice(0, 1));
      return `
        <label style="display:flex;align-items:center;gap:10px;padding:6px 4px;font-size:14px;border-bottom:1px solid var(--ubp-line);cursor:pointer;">
          <input type="checkbox" value="${escapeAttr(c.name)}" class="friend-check" data-avatar="${escapeAttr(avatar || '')}" style="cursor:pointer;">
          <div style="width:46px;height:46px;border-radius:8px;background:#8B5CF6;display:flex;align-items:center;justify-content:center;overflow:hidden;flex-shrink:0;color:#fff;font-weight:600;font-size:15px;box-shadow:0 1px 4px rgba(0,0,0,0.15);position:relative;">
            ${avatar ? `<img src="${escapeAttr(avatar)}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='flex';"><span style="display:none;width:100%;height:100%;align-items:center;justify-content:center;">${fallbackInitial}</span>` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;">${fallbackInitial}</span>`}
          </div>
          <div style="flex:1;min-width:0;display:flex;align-items:baseline;gap:6px;overflow:hidden;">
            <span style="font-weight:500;white-space:nowrap;color:var(--ubp-text);">${escapeHtml(c.name)}</span>
            ${idTag}
          </div>
        </label>
      `;
    }).join('');
    const ov = document.createElement('div');
    ov.className = 'invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:55;background:var(--ubp-card);display:flex;flex-direction:column;padding:10px 12px 8px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <span style="font-size:15px;font-weight:600;">📨 邀请好友（需选择 <span id="invite-need">${boardSize - 1}</span> 位）</span>
        <button data-ubp-act="close-invite" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      ${judgeName ? '<div style="font-size:11px;color:#F59E0B;background:rgba(245,158,11,0.10);border:1px solid rgba(245,158,11,0.35);border-radius:8px;padding:5px 8px;margin-bottom:6px;flex:none;">⚖️ 本局法官：' + escapeHtml(judgeName) + '（不可同时作为玩家）</div>' : ''}
      <label style="display:flex;align-items:center;gap:8px;padding:6px 9px;margin-bottom:6px;border-radius:8px;background:rgba(14,165,233,0.10);border:1px solid rgba(14,165,233,0.4);cursor:${spectatorAvail ? 'pointer' : 'not-allowed'};flex:none;${spectatorAvail ? '' : 'opacity:0.55;'}">
        <input type="checkbox" id="use-spectator-card" ${spectatorAvail ? '' : 'disabled'} style="cursor:pointer;width:15px;height:15px;">
        <span style="flex:1;font-size:12.5px;color:var(--ubp-text);line-height:1.45;">👁️ 使用观战卡（剩余 ${inv0.spectator || 0} 张）：邀请 ${boardSize} 位角色开局，你以上帝视角观战全部内容</span>
      </label>
      <div id="invite-list" style="flex:1;overflow-y:auto;margin-bottom:4px;">${listHtml}</div>
      <div style="display:flex;justify-content:space-between;align-items:center;padding-top:6px;border-top:1px solid var(--ubp-line);">
        <div style="font-size:12px;color:var(--ubp-text-2);">已选 <span id="invite-count" style="color:var(--ubp-accent,#8B5CF6);font-weight:bold;">0</span> / <span id="invite-max">${boardSize - 1}</span><span style="color:var(--ubp-text-3);">（不足时开局由内置角色补位）</span></div>
        <button data-ubp-act="confirm-invite" class="ubp-btn primary" style="padding:6px 18px;font-size:13px;border-radius:6px;min-width:96px;" disabled>确认邀请</button>
      </div>
    `;
    sheet.appendChild(ov);
    const checks = ov.querySelectorAll('.friend-check');
    const countSpan = ov.querySelector('#invite-count');
    const confirmBtn = ov.querySelector('[data-ubp-act="confirm-invite"]');
    const update = () => {
      need = spectatorMode ? boardSize : boardSize - 1;
      max = need;
      const checked = ov.querySelectorAll('.friend-check:checked');
      countSpan.textContent = checked.length;
      const maxEl = ov.querySelector('#invite-max');
      if (maxEl) maxEl.textContent = String(need);
      const needEl = ov.querySelector('#invite-need');
      if (needEl) needEl.textContent = String(need);
      confirmBtn.disabled = checked.length > need; // 允许不足：开局时由内置角色补位凑满人数
    };
    checks.forEach(cb => cb.addEventListener('change', () => {
      const checkedNow = ov.querySelectorAll('.friend-check:checked');
      if (cb.checked && checkedNow.length > need) {
        cb.checked = false;
        showToast('本局最多邀请 ' + need + ' 位角色（' + boardSize + ' 人场）');
      }
      update();
    }));
    const specToggle = ov.querySelector('#use-spectator-card');
    if (specToggle) {
      specToggle.addEventListener('change', () => {
        spectatorMode = !!specToggle.checked;
        if (spectatorMode && (loadShopInventory().spectator || 0) <= 0) {
          spectatorMode = false;
          specToggle.checked = false;
          showToast('观战卡不足，请到积分商城购买（5 积分/张）');
        } else if (spectatorMode) {
          showToast('👁️ 观战模式：请邀请 ' + boardSize + ' 位角色，开局后你以上帝视角观战');
        }
        update();
      });
    }
    ov.querySelector('[data-ubp-act="close-invite"]').addEventListener('click', () => ov.remove());
    confirmBtn.addEventListener('click', () => {
      const checked = ov.querySelectorAll('.friend-check:checked');
      const expectNeed = spectatorMode ? boardSize : boardSize - 1;
      let selectedNames = Array.from(checked).map(c => c.value);
      const beforeJudgeFilter = selectedNames.length;
      if (judgeName) selectedNames = selectedNames.filter(n => !isNameMatch(n, judgeName));
      if (selectedNames.length !== beforeJudgeFilter) showToast('⚖️ 法官「' + judgeName + '」不能同时作为玩家，已自动移除');
      const allContacts = loadContactsWithAvatars().contacts || [];
      // 人数未达标：由内置角色（角色N）补位，凑满本局人数（观战模式补满全部席位）
      const wolfNeedFill = Math.max(0, expectNeed - selectedNames.length);
      if (wolfNeedFill > 0) {
        let gi = 1, added = 0;
        while (added < wolfNeedFill) {
          const g = '角色' + (gi++);
          if (selectedNames.indexOf(g) >= 0) continue;
          if (judgeName && isNameMatch(g, judgeName)) continue;
          selectedNames.push(g); added++;
        }
        showToast('🪑 人数未达标，已由内置角色补位 ' + wolfNeedFill + ' 位（凑满 ' + boardSize + ' 人场）');
      }
      const selectedContacts = selectedNames.map(nm2 => allContacts.find(c => c && c.name === nm2) || { name: nm2, avatar: getCharacterAvatarByName(nm2) || '', identity: '' });
      const userAvatar = getMainCharAvatar();
      const players = [];
      if (spectatorMode) {
        if (!consumeIdentityCard('spectator', 1)) { showToast('观战卡不足，请到积分商城购买'); return; }
      } else {
        players.push({ name: '我', avatar: userAvatar, isUser: true });
      }
      selectedContacts.forEach(f => {
        const av = f.avatar || getCharacterAvatarByName(f.name);
        players.push({ name: f.name, avatar: av, isUser: false });
      });

      const positions = Array.from({ length: boardSize }, (_, i) => i + 1);
      for (let i = positions.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [positions[i], positions[j]] = [positions[j], positions[i]];
      }
      players.forEach((p, idx) => p.position = positions[idx]);
      players.sort((a, b) => a.position - b.position);

      currentGameSession++;
      game = {
        session: currentGameSession,
        boardSize: boardSize,
        boardVariant: boardMode,
        judgeName: getConfiguredJudgeName(),
        identityCards: [],
        wolfTeammateNames: [],
        wolfBeautyTeammateName: '',
        wolfWwkTeammateName: '',
        spectatorNames: [],
        spectatorMode: !!spectatorMode,
        players: players.map(p => ({
          ...p,
          avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)),
          alive: true,
          role: null,
          votedFor: null,
          hasSpoken: false
        })),
        phase: 'idle',
        day: 0,
        currentSpeaker: 0,
        winner: null,
        history: [],
        historyEntries: [],
        userIndex: players.findIndex(p => p.isUser),
        nightResult: '',
        nightKill: null,
        nightDeaths: [],
        witchAction: null,
        witchMenu: false,
        witchMenuReturn: false,
        witchUsedAntidote: false,
        witchUsedPoison: false,
        witchSavedPos: null,
        guardProtectedPos: null,
        guardLastPos: null,
        lastWolfKillPos: 0,
        lastWolfKillDied: false,
        wolfMateChatDone: false,
        dayAnnounced: false,
        sheriffLeadDone: false,
        sheriffPos: null,
        sheriffStage: '',
        sheriffDone: false,
        sheriffCandidates: [],
        sheriffWithdrawn: [],
        sheriffVotes: {},
        sheriffDirection: '',
        sheriffDirectionDay: 0,
        sheriffPkRound: 0,
        sheriffPkCandidates: [],
        sheriffPkQueue: [],
        sheriffPkIdx: 0,
        sheriffBadgeTorn: false,
        seerChecked: {},
        votes: {},
        replay: [],
        pickMode: null,
        pick: { idx: null },
        resolvingFinalWords: null,
        tactics: { ai: '', user: '', custom: '' },
        aiWolfTactics: null,
        simNightContext: '',
        isPkVote: false,
        aiVotesDone: false,
        speechesStartedDay: 0,
        pkCandidates: null,
        pkSpeakerQueue: [],
        pkCurrentSpeakerIdx: 0,
        isPkSpeaking: false
      };
      isGameOver = false;
      replayLogs = [];
      ov.remove();
      renderPositions();
    });
  }

  function renderPositions() {
    if (!game) return;
    const compact = game.players.length > 6;
    const half = Math.ceil(game.players.length / 2);
    const left = game.players.slice(0, half);
    const right = game.players.slice(half);
    const AV = 52;

    const renderLeftPositionPlayer = (p) => {
      const avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
      if (!p.avatar && avatar) p.avatar = avatar;
