          <div style="writing-mode:vertical-rl;text-orientation:mixed;font-size:12px;max-height:${AV}px;color:var(--ubp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:1px;line-height:1.1;margin-left:0;">${p.name}</div>
          <div style="width:${AV}px;height:${AV}px;border-radius:10px;background:#4CAF50;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${compact ? 15 : 18}px;color:#fff;font-weight:600;border:2px solid var(--ubp-line);flex-shrink:0;box-shadow:0 2px 6px rgba(0,0,0,0.2);position:relative;">
            ${avatar ? `<img src="${avatar}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='flex';"><span style="display:none;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>`}
          </div>
        </div>
      `;
    };

    const renderRightPositionPlayer = (p) => {
      const avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
      if (!p.avatar && avatar) p.avatar = avatar;
      return `
        <div style="display:flex;flex-direction:row;align-items:center;justify-content:flex-end;gap:4px;margin:${compact ? 2 : 8}px 0;padding-right:0;">
          <div style="width:${AV}px;height:${AV}px;border-radius:10px;background:#4CAF50;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${compact ? 15 : 18}px;color:#fff;font-weight:600;border:2px solid var(--ubp-line);flex-shrink:0;box-shadow:0 2px 6px rgba(0,0,0,0.2);position:relative;">
            ${avatar ? `<img src="${avatar}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='flex';"><span style="display:none;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;">${p.position}</span>`}
          </div>
          <div style="writing-mode:vertical-rl;text-orientation:mixed;font-size:12px;max-height:${AV}px;color:var(--ubp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:1px;line-height:1.1;margin-right:0;">${p.name}</div>
        </div>
      `;
    };

    sheet.innerHTML = `
      <div style="display:flex;flex-direction:column;height:100%;min-height:0;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">
          <span style="font-size:17px;font-weight:600;">📋 座位分配</span>
          <button data-ubp-act="back-board" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;width:100%;padding:0;margin:8px 0;flex:1;min-height:0;overflow:hidden;box-sizing:border-box;">
          <div style="display:flex;flex-direction:column;gap:${compact ? 4 : 14}px;">${left.map(p => renderLeftPositionPlayer(p)).join('')}</div>
          <div style="display:flex;flex-direction:column;gap:${compact ? 4 : 14}px;">${right.map(p => renderRightPositionPlayer(p)).join('')}</div>
        </div>
        ${game.spectatorMode
          ? '<div style="margin-top:4px;flex:none;border-top:1px solid var(--ubp-line);padding-top:6px;text-align:center;font-size:11px;color:#0EA5E9;line-height:1.5;">👁️ 上帝视角观战模式 · 本局由 ' + game.players.length + ' 位角色自动对局</div>'
          : '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:4px;flex:none;">' +
              '<div style="flex:1;min-width:0;font-size:10.5px;color:var(--ubp-text-3);line-height:1.4;">身份卡用途：第一张卡决定你的身份；使用狼人阵营卡后，可继续消耗狼人阵营卡邀请狼队友。</div>' +
              '<button data-ubp-act="open-identity-pack" class="ubp-btn" style="flex:none;padding:6px 12px;font-size:12px;background:#F59E0B;color:#fff;border:none;border-radius:8px;">🎴 卡包</button>' +
            '</div>'}
        <div style="display:flex;justify-content:center;margin-top:6px;flex:none;">
          <button data-ubp-act="start-game" class="ubp-btn primary" style="padding:6px 24px;font-size:13px;border-radius:6px;min-width:130px;">🎯 开始游戏</button>
        </div>
      </div>
    `;
    if (identityPackOpen && !game.spectatorMode) renderIdentityCardPackOverlay();
  }

  // ========== 狼人杀：身份卡选择面板（座位分配页） ==========
  // 身份卡与当前板子的兼容判断：守卫仅12人场、猎人仅经典9/10/12人场、愚者仅10人神职局、狼美人/骑士仅狼美人板子
  function isCardAllowedForBoard(key) {
    const n = game ? (game.players || []).length : 6;
    if (isHunterWolfBoard()) return key === 'hunter' || key === 'wolf';
    if (key === 'guard') return n >= 12 || !!(game && game.boardVariant === 'guard6' && n === 6) || isEnt8Board() || isEnt7Board();
    if (key === 'witch') return !((game && game.boardVariant === 'guard6' && n === 6) || isEnt8Board());
    if (key === 'hunter') return isEnt7Board() || (!isBeautyBoard() && n >= 9 && !isWwkBoard());
    if (key === 'fool') return !!(game && (game.boardVariant === 'gods' || game.boardVariant === 'wwknight' || game.boardVariant === 'beauty10') && n === 10);
    if (key === 'knight') return (isBeautyBoard() && n >= 9) || isWwkBoard() || isEnt8Board();
    if (key === 'beauty') return isBeautyBoard() && n >= 9;
    if (key === 'wwk') return isWwkBoard() || isEnt7Board();
    return true;
  }

  function normalizeIdentityCardState() {
    if (!game) return;
    if (!Array.isArray(game.identityCards)) game.identityCards = [];
    const picked = game.identityCards;
    const first = picked[0] || null;
    if (!first) {
      game.identityCards = [];
      game.wolfTeammateNames = [];
      game.wolfBeautyTeammateName = '';
      game.wolfWwkTeammateName = '';
      return;
    }
    if (first === 'wolf') {
      let beautySeen = false;
      let wwkSeen = false;
      game.identityCards = picked.filter(k => {
        if (k === 'wolf') return true;
        if (k === 'beauty' && !beautySeen) { beautySeen = true; return true; }
        if (k === 'wwk' && !wwkSeen) { wwkSeen = true; return true; }
        return false;
      });
    } else if (first === 'wwk') {
      // 白狼王为主角：可继续用狼人卡邀请普通狼队友；本局只有 1 位白狼王，不能再选第二位白狼王
      let wwkSeen = false;
      game.identityCards = picked.filter(k => {
        if (k === 'wwk') { if (!wwkSeen) { wwkSeen = true; return true; } return false; }
        return k === 'wolf';
      });
      if (game.identityCards[0] !== 'wwk') game.identityCards.unshift('wwk');
    } else if (first === 'beauty') {
      let beautySeen = false;
      game.identityCards = picked.filter(k => {
        if (k === 'wolf') return true;
        if (k === 'beauty' && !beautySeen) { beautySeen = true; return true; }
        return false;
      });
      game.wolfBeautyTeammateName = '';
    } else {
      game.identityCards = [first];
      game.wolfTeammateNames = [];
      game.wolfBeautyTeammateName = '';
      game.wolfWwkTeammateName = '';
      return;
    }
    const wolfCap = getWolfCardCap();
    let wolfCount = 0;
    game.identityCards = game.identityCards.filter(k => {
      if (k !== 'wolf') return true;
      wolfCount++;
      return wolfCount <= wolfCap;
    });
    const selfWolf = game.identityCards[0] === 'wolf';
    const selfBeauty = game.identityCards[0] === 'beauty';
    const selfWwk = game.identityCards[0] === 'wwk';
    const wolves = game.identityCards.filter(k => k === 'wolf').length;
    const mateCap = (selfBeauty || selfWwk)
      ? Math.min(wolves, wolfCap)
      : (selfWolf ? Math.max(0, Math.min(wolves - 1, wolfCap - 1)) : 0);
    if (!Array.isArray(game.wolfTeammateNames)) game.wolfTeammateNames = [];
    if (game.wolfTeammateNames.length > mateCap) game.wolfTeammateNames = game.wolfTeammateNames.slice(0, mateCap);
    if (!(selfWolf && game.identityCards.includes('beauty'))) game.wolfBeautyTeammateName = '';
    if (game.wolfBeautyTeammateName && game.wolfTeammateNames.some(n => isNameMatch(n, game.wolfBeautyTeammateName))) {
      game.wolfBeautyTeammateName = '';
    }
    if (!(selfWolf && game.identityCards.includes('wwk'))) game.wolfWwkTeammateName = '';
    if (game.wolfWwkTeammateName && (game.wolfTeammateNames.some(n => isNameMatch(n, game.wolfWwkTeammateName)) || (game.wolfBeautyTeammateName && isNameMatch(game.wolfWwkTeammateName, game.wolfBeautyTeammateName)))) {
      game.wolfWwkTeammateName = '';
    }
  }

  function renderIdentityCardPackOverlay() {
    if (!game || !identityPackOpen) return;
    const old = sheet ? sheet.querySelector('.identity-pack-overlay') : null;
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.className = 'identity-pack-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:61;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = '<div style="width:min(92%,360px);max-height:82%;background:var(--ubp-card);border:1px solid var(--ubp-line);border-radius:14px;box-shadow:0 10px 30px rgba(0,0,0,0.45);display:flex;flex-direction:column;padding:12px;box-sizing:border-box;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
      '<span style="font-size:15px;font-weight:600;">🎴 身份卡包</span>' +
      '<button data-identity-pack-close="1" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
      '<div style="flex:1;min-height:0;overflow-y:auto;padding-right:2px;">' + renderIdentityCardPanel() + '</div></div>';
    sheet.appendChild(ov);
    ov.querySelector('[data-identity-pack-close]')?.addEventListener('click', () => {
      identityPackOpen = false;
      ov.remove();
    });
  }

  function renderIdentityCardPanel() {
    const inv = loadShopInventory();
    const picked = (game && game.identityCards) ? game.identityCards : [];
    const ownKey = picked[0] || null;
    const selfWolf = ownKey === 'wolf';
    const selfBeauty = ownKey === 'beauty';
    const selfWwk = ownKey === 'wwk';
    const beautyTeammateCard = selfWolf && picked.includes('beauty');
    const wwkTeammateCard = selfWolf && picked.includes('wwk');
    const wolvesPicked = picked.filter(k => k === 'wolf').length;
    const wolfCardCap = getWolfCardCap();
    const wolfMateSlots = (selfBeauty || selfWwk)
      ? Math.min(wolvesPicked, wolfCardCap)
      : (selfWolf ? Math.max(0, Math.min(wolvesPicked - 1, wolfCardCap - 1)) : 0);
    const teammates = (game && Array.isArray(game.wolfTeammateNames)) ? game.wolfTeammateNames : [];
    const beautyTeammate = (game && game.wolfBeautyTeammateName) ? String(game.wolfBeautyTeammateName) : '';
    const wwkTeammate = (game && game.wolfWwkTeammateName) ? String(game.wolfWwkTeammateName) : '';
    const cards = IDENTITY_CARD_TYPES.map(t => {
      const owned = inv[t.key] || 0;
      const used = picked.filter(k => k === t.key).length;
      const sel = used > 0;
      const allowed = isCardAllowedForBoard(t.key);
      const gray = (owned <= 0 && !sel) || (!allowed && !sel);
      const count = owned;
      const isOwn = !!ownKey && ownKey === t.key;
      return '<div data-ubp-act="pick-identity-card" data-card="' + t.key + '" style="position:relative;flex:1;min-width:0;min-height:82px;box-sizing:border-box;border:2px solid ' + (sel ? t.color : 'var(--ubp-line)') + ';border-radius:12px;padding:12px 8px 10px;text-align:center;cursor:' + (gray ? 'not-allowed' : 'pointer') + ';background:' + (sel ? t.color + '26' : 'var(--ubp-card-2)') + ';' + (gray ? 'filter:grayscale(100%);opacity:0.5;' : '') + (sel ? 'box-shadow:0 0 10px ' + t.color + '99;' : '') + '">' +
        '<div style="font-size:30px;line-height:1.05;">' + t.icon + '</div>' +
        '<div style="font-size:13px;font-weight:700;color:' + (gray ? 'var(--ubp-text-3)' : t.color) + ';margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + t.name.replace('卡', '') + '</div>' +
        '<div style="position:absolute;right:-5px;bottom:-5px;min-width:20px;height:20px;border-radius:999px;background:' + (count > 0 ? t.color : '#6b7280') + ';color:#fff;font-size:11px;font-weight:700;line-height:20px;text-align:center;padding:0 5px;box-sizing:border-box;">' + count + '</div>' +
        (sel ? '<div style="position:absolute;left:-5px;top:-5px;background:' + (isOwn ? '#F59E0B' : t.color) + ';color:#fff;font-size:10px;border-radius:5px;padding:0 4px;line-height:15px;">' + (isOwn ? '主角' : ('已选' + (used > 1 ? ' ' + used : ''))) + '</div>' : '') +
        ((!allowed && !sel) ? '<div style="position:absolute;left:-5px;top:-5px;background:#6b7280;color:#fff;font-size:10px;border-radius:5px;padding:0 4px;line-height:15px;">无此身份</div>' : '') +
        '</div>';
    }).join('');
    const mateRow = (selfWolf || selfBeauty || selfWwk || teammates.length) ? (
      '<div style="margin-top:7px;">' +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-bottom:4px;">🐺 普通狼队友：可邀请 ' + wolfMateSlots + ' 位（本局普通狼人 ' + wolfCardCap + ' 位' + ((selfBeauty || selfWwk) ? '，主角不是普通狼人、狼人卡全部用于队友' : '，含你自己 1 位') + '）' + (teammates.length ? '：<b style="color:#F44336;">' + teammates.map(n => escapeHtml(n)).join('、') + '</b>' : '') + '</div>' +
      '<button data-ubp-act="invite-wolf-teammate" class="ubp-btn" style="width:100%;padding:5px 0;font-size:11.5px;' + (wolfMateSlots > 0 ? '' : 'opacity:0.5;') + '">🤝 邀请普通狼队友（消耗狼人卡）</button>' +
      '</div>'
    ) : '';
    const beautyRow = beautyTeammateCard ? (
      '<div style="margin-top:7px;padding-top:6px;border-top:1px dashed var(--ubp-line);">' +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-bottom:4px;">💗 狼美人队友：' + (beautyTeammate ? '<b style="color:#EC4899;">' + escapeHtml(beautyTeammate) + '</b>' : '未选择') + '（消耗 1 张狼美人卡，不占普通狼人卡）</div>' +
      '<button data-ubp-act="pick-beauty-teammate" class="ubp-btn" style="width:100%;padding:5px 0;font-size:11.5px;background:#EC4899;color:#fff;border:none;">💗 选择狼美人队友</button>' +
      '</div>'
    ) : '';
    const wwkRow = wwkTeammateCard ? (
      '<div style="margin-top:7px;padding-top:6px;border-top:1px dashed var(--ubp-line);">' +
      '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-bottom:4px;">🃏 白狼王队友：' + (wwkTeammate ? '<b style="color:#7C3AED;">' + escapeHtml(wwkTeammate) + '</b>' : '未选择') + '（消耗 1 张白狼王卡，不占普通狼人卡）</div>' +
      '<button data-ubp-act="pick-wwk-teammate" class="ubp-btn" style="width:100%;padding:5px 0;font-size:11.5px;background:#7C3AED;color:#fff;border:none;">🃏 选择白狼王队友</button>' +
      '</div>'
    ) : '';
    return '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;">' + cards + '</div>' +
      '<div style="font-size:10px;color:var(--ubp-text-3);margin-top:6px;line-height:1.45;">身份卡用途：第一张卡决定你的身份；使用狼人阵营卡后，可继续消耗狼人阵营卡邀请狼队友。</div>' +
      mateRow + beautyRow + wwkRow;
  }

  // 本局狼人总数（6人场2 / 9/10人场3 / 12人场4）
  function getBoardWolfTotal() {
    const n = game ? ((game.players || []).length || (game.boardSize || 0)) : 0;
    if (isEnt8Board()) return 3;
    if (n >= 12) return 4;
    if (n >= 9) return 3;
    return 2;
  }

  // 可消耗狼人卡的上限：狼美人板子只有普通狼人可被狼人卡替换（狼美人固定占 1 个狼位）
  function getWolfCardCap() {
    if (isEnt7Board()) return 1;
    if (isWwkBoard()) {
      const n = game ? ((game.players || []).length || (game.boardSize || 0)) : 0;
      return n >= 12 ? 3 : 2;
    }
    if (isBeautyBoard()) {
      const n = game ? ((game.players || []).length || (game.boardSize || 0)) : 0;
      return n >= 12 ? 3 : 2;
    }
    return getBoardWolfTotal();
  }

  // 狼人队友邀请弹窗（消耗多余狼人卡，邀请角色成为狼人）
  function renderWolfTeammatePicker() {
    if (!game) return;
    const pickedCards = Array.isArray(game.identityCards) ? game.identityCards : [];
    const first = pickedCards[0] || null;
    const selfWolf = first === 'wolf';
    const selfBeauty = first === 'beauty';
    const selfWwk = first === 'wwk';
    const wolvesPicked = pickedCards.filter(k => k === 'wolf').length;
    const wolfCardCap = getWolfCardCap();
    const maxMates = (selfBeauty || selfWwk)
      ? Math.min(wolvesPicked, wolfCardCap)
      : (selfWolf ? Math.max(0, Math.min(wolvesPicked - 1, wolfCardCap - 1)) : 0);
    if (maxMates <= 0) {
      if (selfBeauty || selfWwk) showToast('请先勾选狼人卡：每张狼人卡邀请 1 位普通狼队友');
      else if (selfWolf) showToast('请先勾选足够的狼人卡：自己当狼人用 1 张，多余的才能邀请队友');
      else showToast('请先选择狼人卡、白狼王卡或狼美人卡作为主角身份');
      return;
    }
    const already = (game.wolfTeammateNames || []).slice();
    const beautyMate = game.wolfBeautyTeammateName || '';
    const wwkMate = game.wolfWwkTeammateName || '';
    const contactMap = {};
    try {
      const result = loadContactsWithAvatars();
      ((result && result.contacts) || []).forEach(ct => { if (ct && ct.name) contactMap[ct.name] = ct; });
    } catch (e) { /* ignore */ }
    const candidates = (game.players || []).filter(p => p && !p.isUser && !(beautyMate && isNameMatch(p.name, beautyMate)) && !(wwkMate && isNameMatch(p.name, wwkMate))).map(p => {
      const ct = contactMap[p.name] || {};
      return { name: p.name, avatar: p.avatar || ct.avatar || getCharacterAvatarByName(p.name) || '', identity: ct.identity || '' };
    });
    const ov = document.createElement('div');
    ov.className = 'wolf-teammate-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:62;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const list = candidates.map(ct => {
        const on = already.some(n => isNameMatch(n, ct.name));
        const av = ct.avatar || getCharacterAvatarByName(ct.name);
        return '<div data-wolf-pick="' + escapeHtml(ct.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(244,67,54,0.16)' : 'var(--ubp-card-2)') + ';border:1.5px solid ' + (on ? '#F44336' : 'var(--ubp-line)') + ';">' +
          '<div style="width:34px;height:34px;border-radius:50%;background:#F44336;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:13px;">' + escapeHtml(ct.name.slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(ct.name) + '</div>' +
