  // 观战锐评：以上帝视角（知晓全体底牌）生成一条评论
  function generateSpectatorComment() {
    if (!game || !Array.isArray(game.spectatorNames) || !game.spectatorNames.length) return;
    const speaker = game.spectatorNames[Math.floor(Math.random() * game.spectatorNames.length)];
    const roles = (game.players || []).map(p => p.position + '号位 ' + p.name + (p.isUser ? '（主角）' : '') + '：' + (p.role || '未分配') + '（' + (p.alive ? '存活' : '出局') + '）').join('；');
    const recent = (game.history || []).slice(-10).join('\n');
    const prompt = '你是以「上帝视角」观战的观众【' + speaker + '】，能看到本局所有人的真实底牌与身份。\n' +
      '【全体身份】' + roles + '\n' +
      '【最近进程】\n' + (recent || '（开局阶段）') + '\n' +
      '请以你的身份、性格与口癖，对当前局势发一条犀利、有活人感的观战锐评（发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断；严禁括号、旁白、动作与心理描写）。\n' +
      '【完整出字铁律】只输出：<lines>锐评正文</lines>，不要多余文字。';
    showToast('👁️ ' + speaker + ' 正在思考观战锐评…');
    apiChat([
      { role: 'system', content: '你是熟人桌游局中以「上帝视角」观战的观众，能看到所有人的真实身份，点评锐利、可以调侃，但只是桌游吐槽，不涉及真实伤害。' },
      { role: 'user', content: prompt }
    ], resolveApiConfig(), { maxTokens: 800, temperature: 0.95 }).then(res => {
      const clean = ensureCompleteLine(res);
      if (!clean) return;
      addGameLog('👁️ [观战] ' + speaker + '：' + clean, true, null, '#38BDF8');
      // addGameLog 内部已写入 game.replay，这里不能重复 push（否则回放/世界书里同一句出现两遍）
      showToast('👁️ ' + speaker + ' 的观战锐评已发在下方日志');
    }).catch(() => { showToast('观战锐评生成失败，请稍后再试'); });
  }

  function playerBadgeHTML(p) {
    const user = game.players[game.userIndex];
    if (!user || !user.alive) return '';
    let b = null;
    if (isWolfRole(user.role)) {
      if (p.isUser) b = { t: user.role === '狼美人' ? '狼美人' : '狼人', c: '#F44336' };
      else if (user.role === '狼美人' && p.alive && game.wolfBeautyCharmedPos === p.position) b = { t: '💗魅惑', c: '#EC4899' };
      else if (isWolfRole(p.role)) b = { t: p.role === '狼美人' ? '狼美人' : '狼人', c: '#F44336' };
    } else if (user.role === '预言家') {
      if (p.isUser) b = { t: '预言家', c: '#8B5CF6' };
      else if (game.seerChecked[p.position]) b = { t: isWolfRole(p.role) ? '狼人' : '好人', c: isWolfRole(p.role) ? '#F44336' : '#4CAF50' };
    } else if (user.role === '女巫') {
      if (p.isUser) b = { t: '女巫', c: '#2196F3' };
