    if (n >= 12) {
      return isBeautyBoard()
        ? '4狼人（普通狼人×3、狼美人×1）、4村民、1预言家、1女巫、1守卫、1骑士'
        : '4狼人、4村民、1预言家、1女巫、1猎人、1守卫';
    }
    if (n >= 9) {
      return isBeautyBoard()
        ? '3狼人（普通狼人×2、狼美人×1）、3村民、1预言家、1女巫、1骑士'
        : '3狼人、3村民、1预言家、1女巫、1猎人';
    }
    if (n === 6 && isGuard6Board()) {
      return '2狼人、2村民、1预言家、1守卫';
    }
    return '2狼人、2村民、1预言家、1女巫';
  }
  function getBoardWinRuleDesc() {
    if (isHunterWolfBoard()) return '所有猎人出局时狼人获胜；所有狼人出局时好人获胜';
    return (game && ((game.players || []).length >= 9 || isEnt7Board()))
      ? '狼人需屠边：村民全部出局（屠民）或神职全部出局（屠神）即狼人获胜'
      : '狼人需屠城（好人阵营存活人数≤1即狼人获胜）';
  }
  function getWolfBeautyLastCharmedName() {
    const pos = game ? game.wolfBeautyLastCharmedPos : 0;
    const p = (game && pos) ? game.players.find(x => x.position === pos) : null;
    return p ? (p.position + '号位 ' + p.name) : '无';
  }
  function getWolfBeautyCharmedName() {
    const pos = game ? game.wolfBeautyCharmedPos : 0;
    const p = (game && pos) ? game.players.find(x => x.position === pos) : null;
    return p ? (p.position + '号位 ' + p.name) : '无';
  }

  // 夜晚：狼队刀人结束后，狼美人单独魅惑
  function stepWolfBeautyAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'wolfbeauty';
    game.wolfBeautyCharmedPos = null;
    const beauty = game.players.find(p => p.role === '狼美人');
    if (!beauty || !beauty.alive) {
      addHiddenThought('💗 狼美人已出局，本晚没有魅惑行动。', beauty ? beauty.position : 0);
      game.wolfBeautyLastCharmedPos = 0;
      saveGameRecord();
      afterWolfBeautyAction();
      return;
    }
    const validTargets = game.players.filter(p => p.alive && p.position !== beauty.position && p.position !== game.wolfBeautyLastCharmedPos);
    if (!validTargets.length) {
      addHiddenThought('💗 没有可魅惑的目标（不能魅惑自己或连续两晚魅惑同一人），狼美人本晚选择不魅惑。', beauty.position);
      game.wolfBeautyLastCharmedPos = 0;
      saveGameRecord();
      afterWolfBeautyAction();
      return;
    }

    if (beauty.isUser) {
      addGameLog('💗 狼美人请行动');
      addGameLog('请点击玩家头像选择今晚魅惑的目标（不能连续两晚魅惑同一人，也可选择不魅惑）', false);
      game.pickMode = 'charm';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
      saveGameRecord();
      return;
    }

    addGameLog('⏳ AI 狼美人正在选择魅惑目标...');
    const config = loadConfig();
    const overview = getGamePublicOverview(beauty);
    const history = getPlayerHistoryContext(beauty);
    const mates = game.players.filter(p => isWolfRole(p.role) && p.position !== beauty.position);
    const mateText = mates.length ? mates.map(m => `${m.position}号位 ${m.name}（${m.alive ? '存活' : '出局'}）`).join('、') : '无（孤狼）';
    const targetList = validTargets.map(p => `${p.position}号位(${p.name}${p.isUser ? '，主角本人' : ''})`).join('、');
    const lastText = getWolfBeautyLastCharmedName();
    const prompt = `你正在扮演第${game.day}天夜晚的狼美人（${beauty.position}号位 ${beauty.name}）。${overview}${getIdentitySystemContextSafe(beauty)}${getInfoBoundaryRule()}\n\n【场上历史公开发言与公告】：\n${history}\n\n【狼美人规则】：\n1. 你属于狼人阵营，夜晚先与狼队共同睁眼刀人，刀人结束后单独睁眼魅惑一名存活玩家。\n2. 不能魅惑自己，不能连续两晚魅惑同一个人；上一晚你魅惑的是：${lastText}。\n3. 你可以选择不魅惑（WOLF_BEAUTY_CHARM: 0）。\n4. 禁止自刀、禁止自爆。\n5. 若你被放逐、毒杀、枪杀等方式出局，被你魅惑的玩家会一同殉情出局，且殉情角色的技能无法发动。\n6. 特殊克制：若你被骑士决斗戳死，魅惑失效，不会带人殉情。\n7. 你的狼队友：${mateText}。魅惑目标可以是场上任意存活玩家（包括狼队友），但通常优先魅惑好人阵营的关键角色。\n可选魅惑目标：${targetList}\n\n【魅惑决策指引】：\n1. 你只能依据自己的底牌、狼队共享信息与公开信息推理，严禁开天眼。\n2. 结合白天发言、抿神结果与狼队刀法，选择你最想在出局时带走、且对好人阵营价值最高的玩家。\n3. 在<thinking>中输出完整的魅惑思考；在<WOLF_BEAUTY_ACTION>中输出目标号位。\n\n格式必须为：\n<thinking>\n狼美人魅惑思考...\n</thinking>\n<WOLF_BEAUTY_ACTION>\nWOLF_BEAUTY_CHARM: [被魅惑玩家的号位数字，不魅惑填0]\n</WOLF_BEAUTY_ACTION>`;

    apiChat([
      { role: 'system', content: '你是狼人杀中的狼美人。你与狼队共同刀人后单独魅惑，必须结合公开信息与狼队视角推理，严禁开天眼。严格输出思考与魅惑格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const parsedB = parseWolfSpeechResponse(res);
      addHiddenThought(parsedB.thought || '正在评估今晚最值得魅惑、出局时最能重创好人的目标。', beauty.position);
      let pos = parseWolfTargetPos(res, 'WOLF_BEAUTY_CHARM');
      let target = null;
      if (pos > 0) target = game.players.find(p => p.position === pos && p.alive && p.position !== beauty.position && p.position !== game.wolfBeautyLastCharmedPos) || null;
      if (pos < 0) target = validTargets[Math.floor(Math.random() * validTargets.length)] || null;
      if (target) {
        game.wolfBeautyCharmedPos = target.position;
        game.wolfBeautyLastCharmedPos = target.position;
        addHiddenThought('💗 狼美人魅惑了 ' + target.name + '（' + target.position + '号位）。若狼美人出局，TA将一同殉情。', beauty.position);
      } else {
        game.wolfBeautyCharmedPos = null;
        game.wolfBeautyLastCharmedPos = 0;
        addHiddenThought('💗 狼美人本晚选择不魅惑。', beauty.position);
      }
      saveGameRecord();
      afterWolfBeautyAction();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI狼美人魅惑思考', err, (attemptNo || 1), (n) => stepWolfBeautyAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        const t = validTargets[Math.floor(Math.random() * validTargets.length)] || null;
        if (t) {
          game.wolfBeautyCharmedPos = t.position;
          game.wolfBeautyLastCharmedPos = t.position;
          addHiddenThought('💗 （AI调用失败，狼美人随机魅惑了 ' + t.name + '，' + t.position + '号位）', beauty.position);
        } else {
          game.wolfBeautyCharmedPos = null;
          game.wolfBeautyLastCharmedPos = 0;
        }
        saveGameRecord();
        afterWolfBeautyAction();
      });
    });
  }

  function afterWolfBeautyAction() {
    if (!isSessionValid(game?.session)) return;
    stepGuardAction();
  }

  // 狼队刀人结束后的统一出口：经典板子先结算守卫守护再进女巫；狼美人板子先魅惑再守卫
  function afterWolfKillStep() {
    if (!isSessionValid(game?.session)) return;
    if (isBeautyBoard()) { stepWolfBeautyAction(); return; }
    applyGuardProtection();
    stepWitchAction();
  }

  // 守卫行动结束后的统一出口
  function afterGuardAction() {
    if (!isSessionValid(game?.session)) return;
    if (isBeautyBoard()) {
      applyGuardProtection();
      stepWitchAction();
      return;
    }
    stepSeerAction();
  }

  // 女巫行动结束后的统一出口
  function afterWitchAction() {
    if (!isSessionValid(game?.session)) return;
    if (isBeautyBoard()) { stepSeerAction(); return; }
    finishNightAndStartDay();
  }

  // 预言家行动结束后的统一出口
  function afterSeerAction() {
    if (!isSessionValid(game?.session)) return;
    if ((isEnt8Board() || isHunterWolfBoard()) && game.day === 1) { finishNightAndStartDay(); return; }
    if (isBeautyBoard()) { finishNightAndStartDay(); return; }
    stepWolfAction();
  }

  // 狼美人死亡后的殉情结算：被骑士决斗戳死时魅惑失效，不触发
  async function resolveWolfBeautyChain(session, phase) {
    if (!game || game.wolfBeautyChainResolved) return [];
    const beauty = game.players.find(p => p.role === '狼美人' && !p.alive && p.deathCause !== 'duel');
    if (!beauty) return [];
    const pos = game.wolfBeautyCharmedPos;
    const target = (pos && game.players.find(p => p.position === pos && p.alive)) || null;
    game.wolfBeautyChainResolved = true;
    game.wolfBeautyCharmedPos = null;
    if (!target) return [];
    target.alive = false;
    target.deathCause = 'charm';
    target.noDeathSkill = true;
    if (phase === 'night') {
      game.nightDeaths.push({ p: target, type: '殉情' });
      saveGameRecord();
      return [target];
    } else {
      addGameLog('💔 ' + beauty.name + '（' + beauty.position + '号位）出局，被魅惑的 ' + target.name + '（' + target.position + '号位）一同殉情出局，殉情角色的技能无法发动！', true);
      if (target.position === game.sheriffPos && !game.sheriffBadgeTorn) {
        await resolveSheriffBadgeOnDeath(session, target);
      }
    }
    renderGameUI();
    saveGameRecord();
    return [target];
  }

  // ========== 骑士：白天一次性翻牌决斗 ==========
  function knightDuelPhaseAllowed() {
    if (!game || isGameOver || game.phase !== 'day' || game.knightDuelUsed) return false;
    if (game.sheriffStage === 'speech' || game.sheriffStage === 'pk') return true;
    if ((!game.sheriffStage || game.sheriffStage === 'done') && game.speechesStartedDay === game.day && !game.isPkSpeaking) return true;
    return false;
  }
  function knightCanDuel() {
    const u = game && game.players ? game.players[game.userIndex] : null;
    return !!(u && u.isUser && u.alive && u.role === '骑士' && !game.knightDuelUsed && knightDuelPhaseAllowed() && !game.knightPromptActive && !game.knightManualDuel && !isGameOver);
  }



  function abortSheriffElection() {
    if (!game) return;
    game.sheriffStage = 'done';
    game.sheriffDone = true;
    game.sheriffCandidates = [];
    game.sheriffWithdrawn = [];
    game.sheriffVotes = {};
    game.sheriffPkRound = 0;
    game.sheriffPkCandidates = [];
    game.sheriffPkQueue = [];
    game.sheriffPkIdx = 0;
    game.sheriffSpeechQueue = [];
    game.sheriffSpeechIdx = 0;
    game.sheriffWithdrawQueue = [];
    game.sheriffWithdrawIdx = 0;
    game.sheriffVoterQueue = [];
    game.sheriffVoterIdx = 0;
    game.isPkSpeaking = false;
    game.pkCandidates = null;
    game.pkSpeakerQueue = [];
    game.pkCurrentSpeakerIdx = 0;
  }

  function removeFromSheriffElection(p) {
    if (!game || !p) return;
    const had = arr => (arr || []).filter(pos => pos !== p.position);
    game.sheriffCandidates = had(game.sheriffCandidates);
    game.sheriffPkCandidates = had(game.sheriffPkCandidates);
    const filt = arr => (arr || []).filter(x => x && x.position !== p.position);
    game.sheriffSpeechQueue = filt(game.sheriffSpeechQueue);
    game.sheriffWithdrawQueue = filt(game.sheriffWithdrawQueue);
    game.sheriffVoterQueue = filt(game.sheriffVoterQueue);
    game.sheriffPkQueue = filt(game.sheriffPkQueue);
    if (game.sheriffVotes) delete game.sheriffVotes[p.position];
  }

  async function executeKnightDuel(knight, target, options) {
    options = options || {};
    const session = game?.session;
    if (!isSessionValid(session) || !knight || !target || !knight.alive || !target.alive) return null;
    if (knight.role !== '骑士' || game.knightDuelUsed || game.phase !== 'day' || target.position === knight.position) return null;
    game.knightDuelUsed = true;
    game.knightPromptActive = false;
    game.knightPromptContext = '';
    game.knightPromptIsAi = false;
    game.knightManualDuel = false;
    game.pickMode = null;
    game.pick.idx = null;
    setControlArea('');
    hideActionPopup();
    addGameLog('⚔️ ' + knight.name + '（' + knight.position + '号位）翻牌决斗 ' + target.name + '（' + target.position + '号位）！', true);
    const targetIsWolf = isWolfRole(target.role);
    if (typeof playKnightDuelFx === 'function') {
      await playKnightDuelFx(knight, target, targetIsWolf);
      if (!isSessionValid(session)) return { targetWolf: targetIsWolf, ended: true };
    }
    if (targetIsWolf) {
      target.alive = false;
      target.deathCause = 'duel';
      target.noDeathSkill = true;
      if (target.role === '狼美人') {
        game.wolfBeautyCharmedPos = null;
        game.wolfBeautyChainResolved = true;
        addGameLog('💔 狼美人被骑士决斗戳死，魅惑链失效，不会有人殉情。', true);
      }
      addGameLog('🗡️ 决斗结果：' + target.name + ' 是狼人，立刻出局！', true);
      if (target.position === game.sheriffPos && !game.sheriffBadgeTorn) {
        await resolveSheriffBadgeOnDeath(session, target);
        if (!isSessionValid(session)) return { targetWolf: true, ended: true };
      }
      if (target.role === '白狼王') {
        renderGameUI();
        saveGameRecord();
        await generateFinalWords(target);
        if (!isSessionValid(session)) return { targetWolf: true, ended: true };
      }
      renderGameUI();
      saveGameRecord();
      if (checkWin()) { endGame(); return { targetWolf: true, ended: true }; }
      if (game.sheriffStage && game.sheriffStage !== 'done') abortSheriffElection();
      addGameLog('🌙 白天结束，直接进入黑夜。', true);
      endDayToNight();
      return { targetWolf: true, ended: false };
    }
    knight.alive = false;
    knight.deathCause = 'duel';
    knight.noDeathSkill = true;
    addGameLog('🛡️ 决斗结果：' + target.name + ' 是好人，骑士 ' + knight.name + ' 自己出局。', true);
    if (knight.position === game.sheriffPos && !game.sheriffBadgeTorn) {
      await resolveSheriffBadgeOnDeath(session, knight);
      if (!isSessionValid(session)) return { targetWolf: false, ended: true };
    }
    if (game.sheriffStage && game.sheriffStage !== 'done') removeFromSheriffElection(knight);
    renderGameUI();
    saveGameRecord();
    if (checkWin()) { endGame(); return { targetWolf: false, ended: true }; }
    addGameLog('☀️ 白天流程继续。', true);
    if (typeof options.afterFailedDuel === 'function') {
      options.afterFailedDuel();
      return { targetWolf: false, ended: false };
    }
    if (game.sheriffStage && game.sheriffStage !== 'done') {
      resumeSheriffStage();
      return { targetWolf: false, ended: false };
    }
    if (game.currentSpeaker === game.players.indexOf(knight) && !knight.hasSpoken) nextSpeaker();
    return { targetWolf: false, ended: false };
  }

  // AI 骑士：白天发言结束、投票开始前进行一次决斗判断（每局只询问一次）
  function maybeStartKnightPrompt(context, onContinue) {
    if (game && game.knightManualDuel) return;
    if (!game || game.knightDuelUsed) { if (typeof onContinue === 'function') onContinue(); return; }
    const knight = game.players.find(p => p.role === '骑士');
    if (!knight || !knight.alive) { if (typeof onContinue === 'function') onContinue(); return; }
    game.knightPromptActive = true;
    game.knightPromptContext = context;
    game.knightPromptIsAi = !knight.isUser;
    saveGameRecord();
    if (knight.isUser) {
      showKnightPrompt(context);
    } else {
      askAiKnightDuel(context, onContinue);
    }
  }

  function showKnightPrompt(context) {
    if (!game) return;
    const knight = game.players.find(p => p.role === '骑士');
    if (!knight || !knight.alive || game.knightDuelUsed) { completeKnightPrompt(context); return; }
    game.knightPromptActive = true;
    game.knightPromptContext = context;
    game.knightPromptIsAi = false;
    const isSheriff = context === 'sheriff';
    setControlArea(
      '<div style="border:1.5px solid #F59E0B;background:rgba(245,158,11,0.10);border-radius:10px;padding:8px 9px;">' +
      '<div style="font-size:12px;font-weight:700;color:#F59E0B;margin-bottom:3px;">⚔️ 骑士决斗' + (isSheriff ? '（上警发言结束）' : '（本轮发言结束）') + '</div>' +
      '<div style="font-size:11.5px;color:var(--ubp-text);line-height:1.45;">是否根据刚才的' + (isSheriff ? '上警发言' : '公开发言') + '内容翻牌决斗？</div>' +
      '<div style="font-size:10px;color:var(--ubp-text-3);line-height:1.4;margin-top:2px;">决斗到狼人：目标立刻出局并直接入夜；决斗到好人：你自己出局，白天继续。本局只能发动一次。</div>' +
      '<div style="display:flex;gap:6px;margin-top:6px;">' +
      '<button data-ubp-act="knight-prompt-duel" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12px;background:#F59E0B;border:none;color:#fff;">⚔️ 决斗</button>' +
      '<button data-ubp-act="knight-prompt-cancel" class="ubp-btn" style="flex:1;padding:6px 0;font-size:12px;">取消</button>' +
      '</div></div>'
    );
    saveGameRecord();
  }

  function beginManualKnightPick() {
    if (!game || !knightCanDuel()) return;
    const user = game.players[game.userIndex];
    const targets = game.players.filter(p => p.alive && p.position !== user.position);
    if (!targets.length) { showToast('场上没有可决斗的存活玩家'); return; }
    game.knightManualDuel = true;
    game.pickMode = 'duel';
    game.pick.idx = null;
    renderGameUI();
    setControlArea(
      '<div style="border:1.5px solid #F59E0B;background:rgba(245,158,11,0.10);border-radius:10px;padding:8px 9px;">' +
      '<div style="font-size:12px;font-weight:700;color:#F59E0B;margin-bottom:3px;">⚔️ 请点击玩家头像选择决斗目标</div>' +
      '<div style="font-size:10px;color:var(--ubp-text-3);line-height:1.4;">点击头像后会弹出决斗按钮；取消会返回当前发言环节。</div>' +
      '<button data-ubp-act="knight-manual-cancel" class="ubp-btn" style="width:100%;margin-top:6px;padding:5px 0;font-size:11.5px;">取消（返回当前发言）</button>' +
      '</div>'
    );
    saveGameRecord();
  }

  function resumeAfterManualKnightCancel() {
    if (!game) return;
    renderGameUI();
    if (game.sheriffStage === 'speech' || game.sheriffStage === 'pk') {
      resumeSheriffStage();
      return;
    }
    if (game.phase === 'day') {
      const cur = game.players[game.currentSpeaker];
      if (!cur || !cur.alive || cur.hasSpoken) nextSpeaker();
      else startSpeaking();
    }
  }

  function beginKnightPromptDuel() {
    if (!game || !game.knightPromptActive) return;
    const targets = game.players.filter(p => p.alive && p.position !== (game.players[game.userIndex] || {}).position);
    if (!targets.length) { showToast('场上没有可决斗的存活玩家'); completeKnightPrompt(game.knightPromptContext); return; }
    game.pickMode = 'duel';
    game.pick.idx = null;
    renderGameUI();
    setControlArea(
      '<div style="border:1.5px solid #F59E0B;background:rgba(245,158,11,0.10);border-radius:10px;padding:8px 9px;">' +
      '<div style="font-size:12px;font-weight:700;color:#F59E0B;margin-bottom:3px;">⚔️ 请点击玩家头像选择决斗目标</div>' +
      '<div style="font-size:10px;color:var(--ubp-text-3);line-height:1.4;">点击头像后会弹出决斗按钮；也可以点下面的取消，直接进入之后的环节。</div>' +
      '<button data-ubp-act="knight-prompt-cancel" class="ubp-btn" style="width:100%;margin-top:6px;padding:5px 0;font-size:11.5px;">取消（进入之后的环节）</button>' +
      '</div>'
    );
    saveGameRecord();
  }

  function completeKnightPrompt(context) {
    if (!game) return;
    const ctx = context || game.knightPromptContext || 'day';
    game.knightPromptActive = false;
    game.knightPromptContext = '';
    game.knightPromptIsAi = false;
    game.knightManualDuel = false;
    game.pickMode = null;
    game.pick.idx = null;
    hideActionPopup();
    setControlArea('');
    if (ctx === 'sheriff') {
      game.knightSheriffPromptDone = true;
      if (game.sheriffStage === 'speech') {
        proceedFinishSheriffSpeeches();
      } else if (game.phase === 'day') {
        startVote();
      }
      return;
    }
    if (game.phase === 'day') startVote();
  }

  function resumeKnightPrompt() {
    if (!game || !game.knightPromptActive) return;
    const context = game.knightPromptContext || 'day';
    const knight = game.players.find(p => p.role === '骑士');
    if (!knight || !knight.alive || game.knightDuelUsed) { completeKnightPrompt(context); return; }
    if (game.knightPromptIsAi || !knight.isUser) {
      askAiKnightDuel(context, () => completeKnightPrompt(context));
    } else {
      showKnightPrompt(context);
    }
  }

  function askAiKnightDuel(context, onContinue, attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') { if (typeof onContinue === 'function') onContinue(); return; }
    const knight = game.players.find(p => p.role === '骑士');
    if (!knight || knight.isUser || !knight.alive || game.knightDuelUsed) { if (typeof onContinue === 'function') onContinue(); return; }
    const targets = game.players.filter(p => p.alive && p.position !== knight.position);
    if (!targets.length) { game.knightPromptActive = false; game.knightPromptContext = ''; game.knightPromptIsAi = false; if (typeof onContinue === 'function') onContinue(); return; }
    game.knightPromptActive = true;
    game.knightPromptContext = context;
    game.knightPromptIsAi = true;
    if (!attemptNo) game.knightAiAskCount = (game.knightAiAskCount || 0) + 1;
    const askNo = game.knightAiAskCount || 1;
    const phaseText = context === 'sheriff' ? '上警竞选发言已经结束、退水阶段之前' : '白天公开发言已经结束、投票阶段之前';
    const urgency = askNo <= 1
      ? '这是你本局第一次决斗询问窗口，请认真评估刚才的发言。'
      : '这已经是第' + askNo + '次询问！每多拖一个发言/投票环节，你就越可能在夜里被狼人杀死或在白天被放逐；一旦你出局，决斗技能将永远无法释放！';
    saveGameRecord();
    addGameLog('⏳ AI 骑士正在根据' + (context === 'sheriff' ? '上警发言' : '本轮公开发言') + '思考是否翻牌决斗...');
    const config = loadConfig();
    const overview = getGamePublicOverview(knight);
    const history = getPlayerHistoryContext(knight);
    const targetList = targets.map(p => `${p.position}号位(${p.name}${p.isUser ? '，主角本人' : ''})`).join('、');
    const prompt = `你正在扮演狼人杀中的骑士（${knight.position}号位 ${knight.name}）。当前是第${game.day}天，${phaseText}。\n${urgency}\n\n${overview}${getIdentitySystemContextSafe(knight)}${getInfoBoundaryRule()}\n\n【本局历史公开发言与系统公告】：\n${history}\n\n【骑士决斗规则】：\n1. 你拥有一次性技能：只能在白天上警竞选发言结束后的退水阶段之前，或白天公开发言结束后的投票阶段之前翻牌决斗。\n2. 决斗到狼人：目标立刻出局，白天结束并直接进入黑夜。\n3. 决斗到好人：你自己出局，白天流程继续。\n4. 一旦发动，本局不能再次决斗；也可以选择不发动（KNIGHT_DUEL: 0）。\n可选决斗目标：${targetList}\n\n【决策指引】：\n1. 你只能依据公开信息、自己的底牌与推理判断，严禁开天眼。\n2. 越晚发动，你被狼人夜杀或被放逐的风险越高，技能可能永远无法释放；如果有足够把握，请果断决斗。\n3. 若证据不足，选择不发动，等待下一个询问窗口。\n4. 在<thinking>中输出完整的决斗权衡；在<KNIGHT_ACTION>中输出目标号位。\n\n格式必须为：\n<thinking>\n骑士决斗思考...\n</thinking>\n<KNIGHT_ACTION>\nKNIGHT_DUEL: [决斗目标号位数字，不发动填0]\n</KNIGHT_ACTION>`;
    apiChat([
      { role: 'system', content: '你是狼人杀中的骑士。必须基于公开信息与逻辑推理决定是否翻牌决斗，严禁开天眼。严格输出思考与决斗格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 2500 }).then(res => {
      if (!isSessionValid(session) || game.phase !== 'day') return;
      const parsedK = parseWolfSpeechResponse(res);
      if (parsedK.thought) addHiddenThought(parsedK.thought, knight.position);
      const pos = parseWolfTargetPos(res, 'KNIGHT_DUEL');
      if (pos <= 0) {
        game.knightPromptActive = false;
        game.knightPromptContext = '';
        game.knightPromptIsAi = false;
        addHiddenThought('⚔️ 骑士判断目前证据不足，选择本次不发动决斗，等待下一个询问窗口。', knight.position);
        saveGameRecord();
        if (typeof onContinue === 'function') onContinue();
        return;
      }
      const target = game.players.find(p => p.position === pos && p.alive && p.position !== knight.position) || null;
      if (!target) {
        game.knightPromptActive = false;
        game.knightPromptContext = '';
        game.knightPromptIsAi = false;
        saveGameRecord();
        if (typeof onContinue === 'function') onContinue();
        return;
      }
      executeKnightDuel(knight, target, { afterFailedDuel: onContinue }).then(r => {
        if (!isSessionValid(session)) return;
        if (r && (r.targetWolf || r.ended)) return;
        if (!r && typeof onContinue === 'function') onContinue();
      });
    }).catch(err => {
      if (!isSessionValid(session) || game.phase !== 'day') return;
      handleAiFailure('AI骑士决斗思考', err, (attemptNo || 1), (n) => askAiKnightDuel(context, onContinue, n), () => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        game.knightPromptActive = false;
        game.knightPromptContext = '';
        game.knightPromptIsAi = false;
        addHiddenThought('⚔️ （AI调用失败，骑士本次不发动决斗）', knight.position);
        saveGameRecord();
        if (typeof onContinue === 'function') onContinue();
      });
    });
  }

  function playKnightDuelFx(knight, target) {
    return new Promise(resolve => {
