ius:2px;background:linear-gradient(180deg,transparent,#FDE68A 20%,#F59E0B 50%,#FDE68A 80%,transparent);box-shadow:0 0 14px #F59E0B;animation:ubpKnightFxSlash 1.15s ease forwards;}.ubp-knight-fx-title{position:relative;z-index:2;font-size:20px;font-weight:900;color:#FDE68A;letter-spacing:2px;text-shadow:0 0 16px #F59E0B,0 2px 4px #000;animation:ubpKnightFxTitle 1.15s ease forwards;}';
          (document.head || document.documentElement).appendChild(style);
        }
        const ov = document.createElement('div');
        ov.className = 'ubp-knight-fx-overlay';
        ov.setAttribute('aria-hidden', 'true');
        ov.innerHTML = '<div class="ubp-knight-fx-card">' +
          '<div class="ubp-knight-fx-side left"><div class="ubp-knight-fx-av">' + chatAvatarHTML(knight.name, !!knight.isUser, 54, knight.avatar) + '</div><div class="ubp-knight-fx-name">' + escapeHtml(knight.name) + '</div></div>' +
          '<div class="ubp-knight-fx-center"><div class="ubp-knight-fx-slash"></div><div class="ubp-knight-fx-title">决斗</div></div>' +
          '<div class="ubp-knight-fx-side right"><div class="ubp-knight-fx-av">' + chatAvatarHTML(target.name, !!target.isUser, 54, target.avatar) + '</div><div class="ubp-knight-fx-name">' + escapeHtml(target.name) + '</div></div>' +
          '</div>';
        sheet.appendChild(ov);
        setTimeout(() => { try { ov.remove(); } catch (e) { /* ignore */ } resolve(); }, 1150);
      } catch (e) { resolve(); }
