  }

  function canPickPlayer(p) {
    if (!game || !game.pickMode || isGameOver || !p.alive) return false;
    const user = game.players[game.userIndex];
    if (!user || !user.alive) return false;
    switch (game.pickMode) {
      case 'wolf': return p.role !== '狼美人';
      case 'charm': return p.position !== (user.position) && p.position !== (game.wolfBeautyLastCharmedPos || -1);
      case 'duel': return p.position !== user.position && user.role === '骑士' && !game.knightDuelUsed && (!!game.knightPromptActive || !!game.knightManualDuel);
      case 'seer': return !p.isUser && !game.seerChecked[p.position];
      case 'guard': return p.position !== game.guardLastPos;
      case 'sheriffvote': {
        const u = game.players[game.userIndex];
        if (u && (game.sheriffCandidates || []).indexOf(u.position) !== -1) return false;
        const cands = (game.sheriffPkRound && (game.sheriffPkCandidates || []).length) ? game.sheriffPkCandidates : sheriffRemainingCandidates();
        return cands.indexOf(p.position) !== -1;
      }
      case 'badge': return p.alive && p.position !== (game.sheriffPos || -1);
      case 'poison': return true;
      case 'vote': {
        if (user.role === '愚者' && user.foolFlipped) return false;
        if (p.role === '愚者' && p.foolFlipped) return false;
        if (game.isPkVote) {
          if (game.pkCandidates && game.pkCandidates.some(cp => cp.position === user.position)) return false;
          return game.pkCandidates ? game.pkCandidates.some(cp => cp.position === p.position) : false;
        }
        return true;
      }
      default: return false;
    }
  }

  let wolfFxState = { game: '', sig: '', dead: {}, initialized: false };
  let wolfFxOverlay = null;

  let wolfActionFx = null;
  let wolfActionFxEl = null;
  let wolfActionFxSeq = 0;
  const WOLF_FX_CLASS = { kill: 'ubp-fx-wolfkill', heal: 'ubp-fx-heal', poison: 'ubp-fx-poison', seer: 'ubp-fx-seer', guard: 'ubp-fx-guard', shot: 'ubp-fx-shot', boom: 'ubp-fx-boom' };
  const WOLF_FX_LABEL = { kill: '🗡️ 狼人出刀', heal: '💚 女巫救人', poison: '☠️ 女巫毒杀', seer: '🔮 预言家查验', guard: '🛡️ 守卫守护', shot: '🔫 猎人开枪', boom: '💥 狼人自爆' };
  function playWolfActionFx(kind, player, ms) {
    if (!game || !player || !WOLF_FX_CLASS[kind]) return;
    const idx = game.players.indexOf(player);
    if (idx < 0) return;
    const dur = ms || 1100;
    const seq = ++wolfActionFxSeq;
    wolfActionFx = { kind: kind, idx: idx, until: Date.now() + dur, seq: seq, label: WOLF_FX_LABEL[kind] || '' };
    applyWolfActionFxDOM();
    setTimeout(() => {
      if (wolfActionFx && wolfActionFx.seq === seq) clearWolfActionFx();
    }, dur + 80);
  }
  function applyWolfActionFxDOM() {
    if (!sheet || !wolfActionFx || Date.now() > wolfActionFx.until) return;
    const target = sheet.querySelector('[data-wolf-player-idx="' + wolfActionFx.idx + '"]');
    if (target) {
      Object.keys(WOLF_FX_CLASS).forEach(k => target.classList.remove(WOLF_FX_CLASS[k]));
      target.classList.add(WOLF_FX_CLASS[wolfActionFx.kind]);
    }
    if (!wolfActionFxEl) {
      wolfActionFxEl = document.createElement('div');
      const lab = document.createElement('div');
      lab.className = 'ubp-fx-nightfx-label';
      wolfActionFxEl.appendChild(lab);
    }
    wolfActionFxEl.className = 'ubp-fx-nightfx ubp-fx-nightfx-' + wolfActionFx.kind;
    const lab = wolfActionFxEl.querySelector('.ubp-fx-nightfx-label');
    if (lab) lab.textContent = wolfActionFx.label;
    if (!wolfActionFxEl.isConnected) sheet.appendChild(wolfActionFxEl);
  }
  function clearWolfActionFx() {
    wolfActionFx = null;
    if (wolfActionFxEl) { try { wolfActionFxEl.remove(); } catch (e) { /* ignore */ } wolfActionFxEl = null; }
    if (sheet) {
      sheet.querySelectorAll('[data-wolf-player-idx]').forEach(el => {
        Object.keys(WOLF_FX_CLASS).forEach(k => el.classList.remove(WOLF_FX_CLASS[k]));
      });
    }
  }

  function renderGameUI() {
    if (!game) return;
    if (!sheet) return; // 后台继续：不在狼人杀界面时只推进游戏状态，不做 DOM 渲染
    const fxSession = String(game.session || '');
    if (wolfFxState.game !== fxSession) wolfFxState = { game: fxSession, sig: '', dead: {}, initialized: false };
    const fxSig = String(game.day || 0) + '|' + String(game.phase || '') + '|' + (game.isPkVote ? '1' : '0');
    const fxPhaseChanged = wolfFxState.sig !== fxSig;
