    const boomBtn = canBoom ? `<button data-ubp-act="wolf-boom" style="background:#F44336;color:#fff;border:none;border-radius:6px;padding:4px 10px;font-size:12px;cursor:pointer;margin-right:6px;">🐺 自爆</button>` : '';
    const canWwkBoom = user && user.alive && user.role === '白狼王' && game.phase === 'day' && !game.finalWordsActive;
    const wwkBoomBtn = canWwkBoom ? `<button data-ubp-act="wwk-boom" style="background:#7C3AED;color:#fff;border:none;border-radius:6px;padding:4px 10px;font-size:12px;cursor:pointer;margin-right:6px;">🐺💥 白狼王自爆</button>` : '';
