    sheet.innerHTML = `<style>${UBP_FX_CSS}${UBP_FX2_CSS}${UBP_FX3_CSS}</style>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <div style="display:flex;align-items:center;gap:7px;min-width:0;">
          <button data-ubp-act="wolf-back-board" style="background:none;border:none;font-size:16px;cursor:pointer;color:var(--ubp-text);flex:none;" title="返回板子页（对局自动保存，可在板子页或游戏入口点【继续对局】接着玩）">←</button>
          <span id="game-status-text" style="font-size:15px;font-weight:600;">🐺 第${game.day}天 · ${status}</span>
