          }
          if (item.type === 'wolf_private') {
            if (!isUserWolf && !isGameOver && !godView) return;
            const div = document.createElement('div');
            div.textContent = stripLogTags(item.text);
            div.style.color = '#C084FC';
            log.appendChild(div);
            return;
          }
if (item.type === 'user_private') {
            const div = document.createElement('div');
            div.textContent = stripLogTags(item.text);
            div.style.color = item.color || '#EF4444';
            div.style.fontWeight = '600';
            log.appendChild(div);
            return;
          }
        }
        const text = stripLogTags(typeof item === 'object' ? item.text : item);
        const charColor = (typeof item === 'object' && item.authorPos != null) ? getGamePlayerColorByPos(game, item.authorPos) : '';
