        '<div style="font-size:17px;font-weight:800;letter-spacing:2px;margin-top:4px;text-shadow:0 2px 12px rgba(0,0,0,.7);">' + fxPhaseTitle + '</div>' +
        '<div style="font-size:11.5px;opacity:.8;margin-top:2px;">' + fxPhaseSub + '</div></div>';
      if (wolfFxOverlay && wolfFxOverlay.el) { try { wolfFxOverlay.el.remove(); } catch (e) { /* ignore */ } }
