      sheet.appendChild(wolfFxOverlay.el);
    }
    applyWolfActionFxDOM();
  }

  function addGameLog(msg, isPublic = true, authorPos = null, customColor = null) {
    const explicitColor = customColor || null;
    // 公开发言按角色名恒定配色（对齐玉子手机游戏入口）；系统公告仍用默认色
    const charColor = explicitColor ? '' : (authorPos != null ? getGamePlayerColorByPos(game, authorPos) : '');
    const color = explicitColor || charColor || '#fff';
    const log = sheet?.querySelector('#game-log');
    if (log) {
      // 聊天区只显示正文，剥离 <speech>/<private>/<thinking> 标签；replay/history 仍保留原文供世界书/回放解析
      const displayMsg = stripLogTags(msg);
      const div = document.createElement('div');
      div.classList.add('ubp-fx-log');
      const speaker = (game && authorPos != null) ? getGamePlayerByPos(game, authorPos) : null;
      if (speaker && speaker.name) {
        div.style.display = 'flex';
        div.style.alignItems = 'flex-start';
        div.style.gap = '5px';
        const av = document.createElement('span');
        av.style.cssText = 'flex:none;margin-top:1px;';
        av.innerHTML = chatAvatarHTML(speaker.name, !!speaker.isUser, 20);
        const txt = document.createElement('span');
        txt.textContent = displayMsg;
        txt.style.cssText = 'flex:1;min-width:0;word-break:break-word;';
        div.appendChild(av);
        div.appendChild(txt);
      } else {
        div.textContent = displayMsg;
      }
      div.style.color = color;
      if (explicitColor || charColor) div.style.fontWeight = '600';
      log.appendChild(div);
      log.scrollTop = log.scrollHeight;
    }
    // 语音朗读：公开发言里的 <speech> 台词 → 按角色配置音色朗读（用户本人发言不读）
    if (isPublic && authorPos != null && !explicitColor && msg.indexOf('<speech>') >= 0 && typeof contactsVoiceAutoSpeak === 'function') {
      const vSpeaker = (game && authorPos != null) ? getGamePlayerByPos(game, authorPos) : null;
      const vMatch = String(msg).match(/<speech>([\s\S]*?)<\/speech>/i);
      if (vSpeaker && vSpeaker.name && !vSpeaker.isUser && vMatch && vMatch[1].trim()) contactsVoiceAutoSpeak(vSpeaker.name, vMatch[1].trim());
    }
    if (game) {
      const entryType = explicitColor ? 'user_private' : (isPublic ? 'public' : 'system_private');
      if (game.replay) game.replay.push({ type: entryType, text: msg, authorPos, color: explicitColor || undefined });
      if (isPublic) {
        if (!game.historyEntries) game.historyEntries = [];
        game.historyEntries.push({ type: 'public', text: msg, authorPos, day: game.day, phase: game.phase });
        game.history.push(msg);
      }
      saveGameRecord();
    }
  }

  function addJudgeLog(msg, isPublic = true) {
    const judgeName = getActiveJudgeName();
    if (!judgeName) { addGameLog(msg, isPublic); return; }
    const log = sheet?.querySelector('#game-log');
    if (log) {
      const div = document.createElement('div');
      div.classList.add('ubp-fx-log');
      div.style.display = 'flex';
      div.style.alignItems = 'flex-start';
      div.style.gap = '5px';
      const av = document.createElement('span');
      av.style.cssText = 'flex:none;margin-top:1px;';
      av.innerHTML = chatAvatarHTML(judgeName, false, 20);
      const txt = document.createElement('span');
      txt.textContent = stripLogTags(judgeName + '：' + msg);
      txt.style.cssText = 'flex:1;min-width:0;word-break:break-word;';
      div.appendChild(av);
      div.appendChild(txt);
      div.style.color = 'var(--ubp-text)';
      log.appendChild(div);
      log.scrollTop = log.scrollHeight;
    }
    if (isPublic && typeof contactsVoiceAutoSpeak === 'function') {
      const voiceText = stripLogTags(msg)
        .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '')
        .replace(/\s+/g, ' ')
        .trim();
      if (voiceText) contactsVoiceAutoSpeak(judgeName, voiceText);
    }
    if (game) {
      if (game.replay) game.replay.push({ type: 'judge', text: msg, judgeName });
      if (isPublic) {
        if (!game.historyEntries) game.historyEntries = [];
        game.historyEntries.push({ type: 'public', text: msg, judgeName, day: game.day, phase: game.phase });
        game.history.push(msg);
      }
      saveGameRecord();
    }
  }

  function addHiddenThought(thoughtText, authorPos = null) {
    if (game) {
      if (game.replay) {
        game.replay.push({ type: 'hidden', text: `[隐蔽思考] ${thoughtText}`, authorPos });
      }
      if (!game.historyEntries) game.historyEntries = [];
      game.historyEntries.push({
        type: 'thought',
        authorPos: authorPos,
        text: `<thinking>${thoughtText}</thinking>`,
        day: game.day,
        phase: game.phase
      });
      saveGameRecord();
    }
  }

  function addWolfPrivateLog(msg, authorPos = null) {
    if (!game) return;
    const user = game.players[game.userIndex];
    const isUserWolf = user && isWolfRole(user.role);
    const formatted = msg.startsWith('<private>') ? msg : `<private>${msg}</private>`;
    if (isUserWolf || isGameOver) {
      const log = sheet?.querySelector('#game-log');
      if (log) {
        const div = document.createElement('div');
        div.textContent = stripLogTags(formatted); // 显示层剥离 <private>，存储仍保留原文
        div.style.color = '#C084FC';
        log.appendChild(div);
        log.scrollTop = log.scrollHeight;
      }
    }
    if (game.replay) {
      game.replay.push({ type: 'wolf_private', text: formatted, authorPos });
    }
    if (!game.historyEntries) game.historyEntries = [];
    game.historyEntries.push({ type: 'wolf_private', text: formatted, authorPos, day: game.day, phase: game.phase });
    saveGameRecord();
  }

