  function showPopupForSelection() {
    const mode = game.pickMode;
    let html = '';
    const wrapBtn = (content) => `<div style="display:flex;flex-direction:column;gap:5px;width:100%;max-width:100px;">${content}</div>`;
    const target = (game.pick && game.pick.idx !== null && game.players[game.pick.idx]) ? game.players[game.pick.idx] : null;
    const num = target ? '（' + target.position + '号）' : '';
    if (mode === 'wolf') {
      html = wrapBtn(`<button data-ubp-act="night-wolf" class="ubp-btn" style="background:#F44336;color:#fff;padding:5px 2px;font-size:11px;font-weight:600;border-radius:4px;min-height:26px;line-height:1;">击杀${num}</button><button data-ubp-act="night-skip" class="ubp-btn" style="padding:4px 2px;font-size:11px;border-radius:4px;min-height:24px;line-height:1;">跳过</button>`);
