      html = wrapBtn(`<button data-ubp-act="night-charm" class="ubp-btn" style="background:#EC4899;color:#fff;padding:5px 2px;font-size:11px;font-weight:600;border-radius:4px;min-height:26px;line-height:1;">魅惑${num}</button><button data-ubp-act="night-skip" class="ubp-btn" style="padding:4px 2px;font-size:11px;border-radius:4px;min-height:24px;line-height:1;">不魅惑</button>`);
    } else if (mode === 'duel') {
      html = wrapBtn(`<button data-ubp-act="knight-duel-confirm" class="ubp-btn" style="background:#F59E0B;color:#fff;padding:5px 2px;font-size:11px;font-weight:600;border-radius:4px;min-height:26px;line-height:1;">⚔️ 决斗${num}</button><button data-ubp-act="knight-duel-cancel" class="ubp-btn" style="padding:4px 2px;font-size:11px;border-radius:4px;min-height:24px;line-height:1;">取消</button>`);
    } else if (mode === 'seer') {
      html = wrapBtn(`<button data-ubp-act="night-seer" class="ubp-btn" style="background:#8B5CF6;color:#fff;padding:5px 2px;font-size:11px;font-weight:600;border-radius:4px;min-height:26px;line-height:1;">查验${num}</button><button data-ubp-act="night-skip" class="ubp-btn" style="padding:4px 2px;font-size:11px;border-radius:4px;min-height:24px;line-height:1;">跳过</button>`);
