              ? '（守卫每晚守护1人使其免疫狼刀，可自守，不能连续两晚守护同一人；骑士白天可一次性翻牌决斗；本局没有女巫；首夜无狼刀）'
              : (isGodsBoard()
                ? '（猎人被放逐或被夜杀出局时可开枪带走1人，被女巫毒死或作为最后一位神职出局时不能开枪；愚者只有在白天被公投放逐时才能翻牌，翻牌免疫本次放逐并留在场上，翻牌后永久失去投票权与被投票权但仍可发言，且仍算存活神职，也仍可被狼刀/毒杀等正常杀死；若愚者是警长，翻牌后仍可发表放逐遗言，然后选择移交警徽或放弃警徽）'
                : (isGuard6Board()
                  ? '（守卫每晚守护1人使其免疫狼刀，可自守，不能连续两晚守护同一人；本局没有女巫，没有解药与毒药）'
                  : (boardCount >= 9 ? '（猎人被放逐或被夜杀出局时可开枪带走1人，被女巫毒死或作为最后一位神职出局时不能开枪）' : '')))))))));
    const winRule = getBoardWinRuleDesc();
    const witchRule = (isGuard6Board() || isEnt8Board() || isHunterWolfBoard()) ? '本局没有女巫，没有解药与毒药' : '女巫仅首夜可以自救，其余夜晚中刀不可自救，一晚只用一瓶药';
    return `本局${boardCount}人狼人杀场上存活情况（玩家本人为 ${userPlayer ? `${userPlayer.position}号位 我` : '我'}）：\n${plist}\n规则：${boardDesc}。${witchRule}。${winRule}。${(boardCount >= 10 && !isHunterWolfBoard()) ? '本局有警长与警徽（详见下方警长信息）。' : '本局没有警长、警徽与上警环节。'}平票进入PK辩解与PK投票，二次平票直接进入夜晚。${myRoleInfo}${pastMatchesPrompt}`;
  }

  // 对主角的历史出招统计（本地代码算出来，作为纯文本喂给 LLM）
  // 注意：狼人杀 / 谁是卧底不做难度分档，这些信息始终全部提供给 LLM。
  function getUserTendencyStats() {
    try {
      const history = loadPastMatchesHistory();
      if (!history || !history.length) return '';
      const lines = [];
      let total = 0, wins = 0, asWolf = 0, wolfWins = 0;
      for (const m of history) {
        // 只统计带新字段（userWon / players）的记录：旧存量记录没有这两个字段，
        // 直接计入会把主角胜率错误地算成 0%（给 LLM 喂错误信息比不喂更糟）。
        if (!m || typeof m.userWon !== 'boolean' || !Array.isArray(m.players) || !m.players.length) continue;
        total++;
        const userWon = !!m.userWon;
        if (userWon) wins++;
        const userRole = m.players.find(p => p && p.isUser)?.role;
        if (isWolfRole(userRole)) { asWolf++; if (userWon) wolfWins++; }
      }
      if (!total) return '';
      lines.push(`- 近 ${total} 场对局：主角胜率 ${Math.round((wins / total) * 100)}%`);
      if (asWolf) lines.push(`- 主角拿到狼人牌 ${asWolf} 次（其中获胜 ${wolfWins} 次）：当狼时更偏向隐藏与带节奏`);
      lines.push('- 请据此调整对主角的怀疑权重与话术（主角偏好被记录的弱点要重点针对）');
      return `\n【对主角的历史出招统计（本地统计，仅供参考）】：\n${lines.join('\n')}`;
    } catch (e) { return ''; }
  }

  function getPlayerHistoryContext(player) {
    if (!game) return '';
    // 防全知：只输出该玩家「允许知道」的记录，其余一律不下发
    //  · public       ：全场公开发言 + 系统公告（含白天公布的死亡信息、投票公示）
    //  · thought      ：仅作者本人可见（自己的思考）
    //  · wolf_private ：仅狼人可见（狼队共享的底牌与密谋信息）
    // 严禁下发：他人思考、他人投票理由、他人夜间行动等非本人可见信息
    // 注意：更早轮次的内容必须【完整】下发，不做任何截断/压缩，避免AI忘记前几轮发生过什么
    const filtered = [];
    if (game.historyEntries && game.historyEntries.length > 0) {
      for (const entry of game.historyEntries) {
        if (!entry) continue;
        if (entry.type === 'thought') {
          if (player && entry.authorPos === player.position) filtered.push(entry);
        } else if (entry.type === 'wolf_private') {
          if (player && isWolfRole(player.role)) filtered.push(entry);
        } else if (entry.type === 'public') {
          filtered.push(entry);
        }
      }
    } else if (game.history && game.history.length) {
      // 旧存档兜底：game.history 仅含公开发言
      game.history.forEach(line => {
        const t = String(line || '').replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
        if (t) filtered.push({ type: 'public', text: t });
      });
    }
    if (!filtered.length) return '';
    const dayTagOf = (e) => {
      if (e.day == null) return '';
      const ph = e.phase === 'night' ? '夜' : e.phase === 'vote' ? '投票' : '白天';
      return '【第' + e.day + '天' + ph + '】';
    };
    return filtered.map(e => {
      const text = String(e.text == null ? '' : e.text).trim();
      if (!text) return '';
      return dayTagOf(e) + text;
    }).filter(Boolean).join('\n');
  }

  // 防全知：AI 角色能看到的私有信息只有「属于自己身份的系统内容」，
  // 其他玩家的身份、夜间行动与内心思考一律不可见（公开信息由历史记录提供）。
  function getPlayerIdentitySystemContext(player) {
    if (!player || !game) return '';
    if (isWolfRole(player.role)) {
      const mates = game.players.filter(p => isWolfRole(p.role) && p.position !== player.position);
      let s = '\n【属于你（' + player.role + '）的系统信息】' + (mates.length
        ? '你的狼队友：' + mates.map(m => `${m.position}号位 ${m.name}（${m.role}${m.alive ? '，存活' : '，已出局'}）`).join('、')
        : '你是孤狼，没有存活的狼队友') + '。\n（铁律：除自己的底牌与狼队友外，其他玩家的真实身份与夜间行动对你完全未知，严禁开天眼）';
      if (player.role === '狼美人') {
        s += '\n【狼美人魅惑】你每晚在狼队刀人后单独魅惑1名存活玩家，不能连续两晚魅惑同一人，也可以不魅惑。上一晚你魅惑的是：' + getWolfBeautyLastCharmedName() + '；当前被你魅惑的是：' + getWolfBeautyCharmedName() + '。你被放逐、毒杀、枪杀等方式出局时，被魅惑者会一同殉情且技能无法发动；若你被骑士决斗戳死，魅惑失效、不会带人殉情。禁止自刀、禁止自爆。';
      }
      if (player.role === '白狼王') {
        s += '\n【白狼王自爆】你属于狼人阵营，夜间与狼队共同睁眼刀人并拥有狼队全部夜间视野。你可以在白天发言/上警阶段主动自爆，并指定一名存活玩家与你一同出局；自爆后白天立即结束，直接进入夜晚；自爆者与被带走者均无遗言。投票阶段、遗言阶段不能自爆；若你被公投放逐、被女巫毒、被狼刀、被骑士决斗等非主动自爆方式出局，不能发动带人技能。';
      }
      if (isEnt7Board()) s += '\n【一刀斩目标】本局只有1名平民；狼队应尽量直接找出并刀掉平民，屠民即可获胜。';
      return s;
    }
    if (player.role === '预言家') {
      const checks = Object.keys(game.seerChecked || {}).map(posStr => {
        const pos = parseInt(posStr, 10);
        const t = game.players.find(p => p.position === pos);
        return t ? `${t.position}号位 ${t.name}：${isWolfRole(t.role) ? '狼人（查杀）' : '好人（金水）'}` : '';
      }).filter(Boolean);
      return '\n【属于你（预言家）的系统信息 · 你的真实查验结果】\n' + (checks.length ? checks.join('\n') : '（暂无查验记录）') + '\n（这是只有你知道的私有信息，可用于推理；严禁在公开发言中直接使用未公开的其他信息）';
    }
    if (player.role === '女巫') {
      let s = '\n【属于你（女巫）的系统信息】解药' + (game.witchUsedAntidote ? '已用' : '未用') + '，毒药' + (game.witchUsedPoison ? '已用' : '未用') + '。';
      if (game.witchSavedPos) {
        const t = game.players.find(p => p.position === game.witchSavedPos);
        if (t) s += ' 你救下的银水是 ' + t.position + '号位 ' + t.name + '。';
      }
      return s + '\n（以上为只有你知道的私有信息，严禁开天眼使用其他未公开信息）';
    }
    if (player.role === '猎人') {
      const otherGodsAlive = game.players.some(p => p.alive && p.position !== player.position && isGodRole(p.role));
      return '\n【属于你（猎人）的系统信息】你被投票放逐或被狼人夜杀出局时可以开枪带走 1 人；被女巫毒死则不能开枪；若你是场上最后一位神职，出局后本局立即结束、无法开枪。'
        + (otherGodsAlive ? '' : '（你目前已是场上最后一位神职）');
    }
    if (player.role === '守卫') {
      const lastT2 = game.guardLastPos ? game.players.find(p => p.position === game.guardLastPos) : null;
      return '\n【属于你（守卫）的系统信息】你每晚守护 1 人使其免疫狼刀；可以自守；不能连续两晚守护同一人。'
        + (lastT2 ? '你上一晚守护的是 ' + lastT2.position + '号位 ' + lastT2.name + '（今晚不可再守TA）。' : '你今晚没有连守限制。')
        + '\n（守护目标属于你的隐私，严禁通过公开发言暴露你的守护历史；只有你自己知道守了谁）';
    }
    if (player.role === '骑士') {
      return '\n【属于你（骑士）的系统信息】你拥有一次性翻牌决斗：白天发言阶段、投票之前可决斗1名存活玩家。决斗到狼人则目标立刻出局并直接进入黑夜；决斗到好人则你自己出局、白天流程继续。发动后本局不能再次决斗。'
        + (game.knightDuelUsed ? '（你本局已经发动过决斗，不能再发动）' : '（你本局尚未发动决斗）');
    }
    if (player.role === '愚者') {
      return player.foolFlipped
        ? '\n【属于你（愚者）的系统信息 · 已翻牌】你已翻牌，本局永久失去投票权与被投票权，但仍可正常发言；你依旧算存活神职，也仍会被狼刀、毒杀、枪杀等正常带出局（翻牌不是无敌）。若你此前是警长，翻牌后仍可发表放逐遗言，然后选择移交警徽或放弃警徽。'
        : '\n【属于你（愚者）的系统信息 · 尚未翻牌】你只有在白天被公投放逐时才会翻牌，翻牌免疫本次放逐并留在场上；翻牌后本局永久失去投票权与被投票权，但仍可正常发言，且依旧算存活神职。若你是警长，被投出局翻牌后仍可发表放逐遗言，然后选择移交警徽或放弃警徽。被狼刀、女巫毒、猎人开枪、狼美人带走等非放逐方式出局时不能翻牌，直接出局。';
    }
    if (player.role === '民') {
      return '\n【属于你（村民）的系统信息】你没有夜间技能，只能依据公开发言与投票进行推理。';
    }
    return '';
  }

  // 按字符数软上限裁剪文本（保留最近的部分），避免长对局把提示词撑爆
  function capTextByChars(text, maxChars) {
    const s = String(text == null ? '' : text);
    const max = Math.max(500, Number(maxChars) || 6000);
    if (s.length <= max) return s;
    return '…（更早的记录已省略，以下为最近 ' + max + ' 字）\n' + s.slice(-max);
  }

  // ========== 通用号位解析 / 守卫守护（12人场扩展） ==========
  const WOLF_CN_NUM = { '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10, '十一': 11, '十二': 12 };
  function wolfPosFromStr(v) {
    if (v == null) return 0;
    const s = String(v).trim();
    if (/^\d+$/.test(s)) return parseInt(s, 10) || 0;
    return WOLF_CN_NUM[s] || 0;
  }
  // 从 AI 输出中解析 `TAG: [号位]`（支持 1~12 阿拉伯/中文数字；解析不到返回 -1）
  function parseWolfTargetPos(res, tag) {
    const m = String(res == null ? '' : res).match(new RegExp(tag + '[：:]\\s*[\\[【（(]?\\s*(\\d{1,2}|[一二三四五六七八九十]{1,3})\\s*[\\]】）)]?', 'i'));
    if (!m || !m[1]) return -1;
    return wolfPosFromStr(m[1]);
  }
  // 守卫守护：狼刀目标若被守护，当晚免疫（狼队与其他人不可见，仅隐藏记录）
  function applyGuardProtection() {
    if (!game || !game.nightKill) return false;
    if (game.guardProtectedPos !== game.nightKill.position) return false;
    const guard = game.players.find(p => p.role === '守卫');
    addHiddenThought('🛡️ 守卫成功守护了 ' + game.nightKill.position + '号位 ' + game.nightKill.name + '，狼刀被守护之力化解，今晚这一刀落空。', guard ? guard.position : 0);
    game.nightKill = null;
    return true;
  }

  // ========== 夜晚流程模拟 ==========
  function runNightSequence() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    if (isBeautyBoard()) stepWolfAction();
    else stepGuardAction();
  }

  // 步骤 0：守卫行动（守护目标当晚免疫狼刀；可自守；不能连续两晚守护同一人；无守卫的6/9/10人场自动跳过，6人守卫局除外）
  function stepGuardAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'guard';
    game.guardProtectedPos = null;

    const guard = game.players.find(p => p.role === '守卫');
    // 不管守卫在不在场：夜晚都显示「AI 守卫正在思考守护目标」提示，避免通过是否出现该提示反推本局是否有守卫
    if (!guard) {
      // 无守卫或守卫已出局：不显示守卫相关系统提示，避免误导
      setTimeout(() => { if (isSessionValid(session) && game.nightToken === token) afterGuardAction(); }, 900);
      return;
    }
    if (!guard.alive) {
      addGameLog('⏳ AI 守卫正在思考守护目标...');
      addHiddenThought('🛡️ 守卫已出局，本晚无人守护。', guard.position);
      setTimeout(() => { if (isSessionValid(session) && game.nightToken === token) afterGuardAction(); }, 900);
      return;
    }
    const validTargets = game.players.filter(p => p.alive && p.position !== game.guardLastPos);
    if (!validTargets.length) {
      addGameLog('⏳ AI 守卫正在思考守护目标...');
      setTimeout(() => { if (isSessionValid(session) && game.nightToken === token) afterGuardAction(); }, 900);
      return;
    }

    if (guard.isUser) {
      addGameLog('🛡️ 守卫请行动');
      addGameLog('请点击玩家头像选择今晚守护目标（可自守，不能连续两晚守护同一人）', false);
      game.pickMode = 'guard';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
      saveGameRecord();
      return;
    }

    addGameLog('⏳ AI 守卫正在思考守护目标...');
    const config = loadConfig();
    const overview = getGamePublicOverview(guard);
    const history = getPlayerHistoryContext(guard);
    const lastT = game.guardLastPos ? game.players.find(p => p.position === game.guardLastPos) : null;
    const lastGuardName = lastT ? (lastT.position + '号位 ' + lastT.name) : '无';
    const targetList = validTargets.map(p => p.position + '号位(' + p.name + (p.isUser ? '，主角本人' : '') + ')').join('、');

    const prompt = '你正在扮演第' + game.day + '天夜晚的守卫（' + guard.position + '号位 ' + guard.name + '）。' + overview + getIdentitySystemContextSafe(guard) + getInfoBoundaryRule() + '\n\n【场上历史公开发言与公告】：\n' + history + '\n\n【守卫规则】：\n1. 每晚守护 1 名存活玩家（含自己），被守护者当晚免疫狼刀。\n2. 不能连续两晚守护同一人：你上一晚守护过 ' + lastGuardName + '（今晚不可再守TA）。\n3. 你守护过谁属于你的隐私，绝不能通过公开发言让别人反推出来。\n可选守护目标：' + targetList + '\n\n【守卫思考与守护决策指引】：\n1. 你完全不知道其他玩家的真实身份，必须结合白天发言、狼刀规律与逻辑推理，判断“今晚狼人最可能刀谁”，去守护这个最危险/最关键的人（例如明面上的神职、被抿出好身份的强玩家、或你自己认为会被刀的玩家）。\n2. 这是一场朋友间狼人杀桌游，结合人际关系与你的人设思考守护倾向。\n3. 在<thinking>中输出深度完整的思考思维链，在<GUARD_ACTION>中输出守护目标号位。\n\n格式必须为：\n<thinking>\n守卫思考内容...\n</thinking>\n<GUARD_ACTION>\nGUARD_PROTECT: [被守护玩家的号位数字]\n</GUARD_ACTION>';

    apiChat([
      { role: 'system', content: '你是狼人杀守卫。你只知道自己的身份与守护历史，必须结合公开发言推理狼队刀法，严禁开天眼。严格输出思考与守护格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const parsedG = parseWolfSpeechResponse(res);
      addHiddenThought(parsedG.thought || '正在推演今晚狼队最可能下刀的人，评估守护收益。', guard.position);
      const pos = parseWolfTargetPos(res, 'GUARD_PROTECT');
      let target = pos > 0 ? game.players.find(p => p.position === pos && p.alive) : null;
      if (target && target.position === game.guardLastPos) target = null;
      if (!target) target = validTargets[Math.floor(Math.random() * validTargets.length)];
      game.guardProtectedPos = target.position;
      game.guardLastPos = target.position;
      addHiddenThought('🛡️ 守卫守护了 ' + target.name + '（' + target.position + '号位），狼刀若命中TA将被化解。', guard.position);
      saveGameRecord();
      afterGuardAction();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI守卫思考', err, (attemptNo || 1), (n) => stepGuardAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        const vt = game.players.filter(p => p.alive && p.position !== game.guardLastPos);
        if (!vt.length) { afterGuardAction(); return; }
        const t = vt[Math.floor(Math.random() * vt.length)];
        game.guardProtectedPos = t.position;
        game.guardLastPos = t.position;
        addHiddenThought('🛡️ 守卫守护了 ' + t.name + '（' + t.position + '号位），狼刀若命中TA将被化解。', guard.position);
        saveGameRecord();
        afterGuardAction();
      });
    });
  }

  // 步骤 1：预言家行动
  function stepSeerAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'seer';

    const seer = game.players.find(p => p.role === '预言家');
    if (seer && seer.isUser && seer.alive) {
      // 所有存活对手都已查验过时没有任何可点选目标：必须自动跳过，否则控制区为空、头像不可点，夜晚死锁
      const hasTarget = game.players.some(p => p.alive && !p.isUser && !game.seerChecked[p.position]);
      if (!hasTarget) {
        game.pickMode = null;
        addGameLog('🔮 所有存活玩家都已查验过，本晚无可查验目标，预言家跳过');
        saveGameRecord();
        setTimeout(() => { if (isSessionValid(session) && game.nightToken === token) afterSeerAction(); }, 700);
        return;
      }
      addGameLog('🔮 预言家请行动');
      addGameLog('请点击玩家头像选择查验目标', false);
      game.pickMode = 'seer';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
      saveGameRecord();
      return;
    }

    if (!seer || !seer.alive) {
      setTimeout(() => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        afterSeerAction();
      }, 1500);
      return;
    }
    addGameLog('⏳ AI 预言家正在思考查验目标...');

    const config = loadConfig();
    const overview = getGamePublicOverview(seer);
    const history = getPlayerHistoryContext(seer);
    const aliveOthers = game.players.filter(p => p.alive && p.position !== seer.position).map(p => `${p.position}号位(${p.name})`).join('、');

    const checkedList = Object.keys(game.seerChecked).map(posStr => {
      const pos = parseInt(posStr);
      const target = game.players.find(p => p.position === pos);
      const isWolf = target && isWolfRole(target.role);
      const res = target ? (isWolf ? '狼人(查杀)' : '好人(金水)') : '未知';
      return `${pos}号位(${target ? target.name : ''}${target?.isUser ? '，主角本人' : ''})：${res}`;
    });
    const checkedInfo = checkedList.length > 0 ? `\n【你过往的查验结果】：\n${checkedList.join('\n')}` : '\n【你过往的查验结果】：今晚是第一夜，尚无查验历史';

    const prompt = `你正在扮演第${game.day}天夜晚的预言家（${seer.position}号位 ${seer.name}）。${overview}${checkedInfo}${getIdentitySystemContextSafe(seer)}${getInfoBoundaryRule()}\n\n【场上历史公开发言与公告（你的过往<thinking>对你可见，其他玩家的思考对你不可见）】：\n${history}\n\n可选查验目标：${aliveOthers}\n\n【预言家思考与验人决策指引】：\n1. 除你已知查验的目标外，你对其他玩家的真实身份完全未知，严禁开天眼！结合白天发言疑点进行逻辑推理。\n2. 深刻明白这只是一场朋友间的狼人杀桌游，结合人际关系与QQ聊天进行思考。\n3. 在<thinking>中必须输出深度完整的思考思维链，在<SEER_ACTION>中输出查验目标号位。\n\n格式必须为：\n<thinking>\n预言家思考内容...\n</thinking>\n<SEER_ACTION>\nSEER_CHECK: [被验玩家的号位数字]\n</SEER_ACTION>`;

    apiChat([
      { role: 'system', content: '你是狼人杀预言家。你只知道自己的身份和查验历史，结合游戏认知、角色性格与人际关系进行判断，严禁开天眼。严格输出思考与查验格式。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      const thought = mTh ? mTh[1].trim() : res.replace(/<SEER_ACTION>[\s\S]*?<\/SEER_ACTION>/i, '').trim();
      addHiddenThought(thought || '正在推演场上身份并选择查验目标。', seer.position);
      let targetPos = parseWolfTargetPos(res, 'SEER_CHECK');
      if (targetPos < 0) targetPos = 0;
      if (!targetPos) {
        const others = game.players.filter(p => p.alive && p.position !== seer.position);
        if (others.length) targetPos = others[Math.floor(Math.random() * others.length)].position;
      }
      game.seerChecked[targetPos] = true;
      saveGameRecord();
      afterSeerAction();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      handleAiFailure('AI预言家思考', err, (attemptNo || 1), (n) => stepSeerAction(n), () => {
        if (!isSessionValid(session) || game.nightToken !== token) return;
        const others = game.players.filter(p => p.alive && p.position !== seer.position);
        if (others.length) {
          const t = others[Math.floor(Math.random() * others.length)];
          game.seerChecked[t.position] = true;
          addHiddenThought('（AI调用失败，预言家随机选择了 ' + t.position + '号位 ' + t.name + ' 进行查验）', seer.position);
          addGameLog('🔮 预言家已完成查验', false);
        }
        saveGameRecord();
        afterSeerAction();
      });
    });
  }

  // 步骤 2：狼人行动
  function stepWolfAction(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const token = (game.nightToken = (game.nightToken || 0) + 1);
    game.nightStep = 'wolf';

    const wolves = game.players.filter(p => isWolfRole(p.role) && p.alive);
    if (wolves.length === 0) {
      game.nightKill = null;
      afterWolfKillStep();
      return;
    }
    const userWolf = wolves.find(p => p.isUser);
    if (userWolf) {
      // 后台继续：若狼队友密谋内容已生成过（玩家此前不在界面），直接恢复刀人操作界面，不重复调用 AI
      if (game.wolfMateChatDone) {
        const mate = game.players.find(p => isWolfRole(p.role) && !p.isUser && p.alive) || null;
        showWolfKillSelection(mate);
        return;
      }
      // 玩家是狼人：所有AI狼队友先各自发言并思考（下方显示谁在思考），随后进入玩家战术/击杀操作
      const aiMates = wolves.filter(p => !p.isUser);
      if (!aiMates.length) {
        game.wolfMateChatDone = true;
        saveGameRecord();
        renderWolfTacticsSelection(null);
        return;
      }
      runWolfMateTalkRound(token, session, aiMates);
      return;
    }
    addGameLog('⏳ AI 狼人团队正在密谋刀人决策与战术部署...');
    // AI狼队夜间两阶段：所有狼人先各自发言并思考 → 随机一名狼人根据夜间讨论再次思考并拍板击杀目标
    runWolfNightTalkRound(token, session, wolves);
  }

  // ========== AI狼队夜间密谋：共享上下文 ==========
  function wolfNightSharedContext() {
    const plist = game.players.map(p => `${p.position}号位: ${p.name}（状态: ${p.alive ? '存活' : '已出局'}${(game.players.length >= 10 && !isHunterWolfBoard() && game.sheriffPos === p.position && !game.sheriffBadgeTorn) ? '，警长🎖️' : ''}${(p.role === '愚者' && p.foolFlipped) ? '，愚者已翻牌（无投票权/被投票权）' : ''}${(isHunterWolfBoard() && !p.alive) ? '，已亮牌：' + p.role : ''}${p.isUser ? '，主角本人' : ''}）`).join('\n');
    const wolfBoardDesc = getBoardRoleDesc() + (isBeautyBoard() ? '（狼美人刀人后单独魅惑；狼美人不能自刀/自爆，且不能被狼队击杀；骑士白天可一次性决斗）' : (game.players.length >= 12 ? '（守卫可能守护狼刀目标，导致空刀）' : (isWwkBoard() ? '（白狼王夜间与狼队共同刀人，拥有狼队全部夜间视野；只有白天发言/上警阶段主动自爆才能带走1人，自爆后立即入夜；被放逐/毒/刀/骑士决斗出局不能带人；自爆者与被带走者无遗言）' : (isHunterWolfBoard() ? '（本局有3狼7猎人；首夜无狼刀；所有猎人出局狼人获胜；角色出局亮牌；猎人可开枪并连锁；本局没有女巫/守卫/预言家/村民）' : (isEnt7Board() ? '（本局只有1名平民，狼队尽量直接找出并刀掉平民，屠民即可获胜；白狼王夜间与狼队共同刀人，拥有狼队全部夜间视野；白狼王只有白天发言/上警阶段主动自爆才能带走1人，自爆后立即入夜；被放逐/毒/刀等非主动自爆出局不能带人；自爆者与被带走者无遗言；守卫可能守护狼刀目标，导致空刀；猎人被夜杀出局时可开枪；本局没有骑士/愚者）' : (isEnt8Board() ? '（本局有守卫：守卫可能守护狼刀目标，导致空刀；首夜无狼刀；骑士白天可一次性决斗；本局没有女巫）' : (isGodsBoard() ? '（愚者只有白天被公投放逐时翻牌免放逐，翻牌后失去投票权与被投票权但仍可发言，且仍算存活神职）' : (isGuard6Board() ? '（本局有守卫：守卫可能守护狼刀目标，导致空刀；本局没有女巫，没有解药与毒药）' : ''))))))));
    const wolfWinRule = getBoardWinRuleDesc();
    return { plist: plist, wolfBoardDesc: wolfBoardDesc, wolfWinRule: wolfWinRule, failedKillNote: getWolfFailedKillNote() };
  }

  // ========== 阶段A：所有狼人依次发表夜间密谋发言并思考 ==========
  function runWolfNightTalkRound(token, session, wolves) {
    if (!isSessionValid(session) || game.nightToken !== token) return;
    if (wolfBatchGuard.wolfNight) return; // 该批狼人密谋请求已在途，防止重复发起
    const talkDone = game.wolfNightTalkDone || (game.wolfNightTalkDone = []);
    const talks = game.wolfNightSpeeches || (game.wolfNightSpeeches = []);
    const pendingTalk = wolves.filter(w => talkDone.indexOf(w.position) === -1);
    if (!pendingTalk.length) { runWolfNightDecision(token); return; }
    game.wolfNightPhase = 'talk';
    saveGameRecord();
    wolfBatchGuard.wolfNight = true;
    wolfRunBatch(session, pendingTalk, w => askOneWolfNightTalk(session, w, talkDone, talks, token, 1), () => {
      wolfBatchGuard.wolfNight = false;
      if (!isSessionValid(session) || game.nightToken !== token) return;
      runWolfNightTalkRound(token, session, wolves);
    });
  }

  // ========== 玩家是狼人时：所有AI狼队友先各自发言并思考，随后进入玩家战术/击杀操作 ==========
  function runWolfMateTalkRound(token, session, aiMates) {
    if (!isSessionValid(session) || game.nightToken !== token) return;
    if (wolfBatchGuard.wolfNight) return; // 该批狼人密谋请求已在途，防止重复发起
    const talkDone = game.wolfNightTalkDone || (game.wolfNightTalkDone = []);
    const talks = game.wolfNightSpeeches || (game.wolfNightSpeeches = []);
    const pendingTalk = aiMates.filter(w => talkDone.indexOf(w.position) === -1);
    if (!pendingTalk.length) { finishWolfMateTalk(token); return; }
    game.wolfNightPhase = 'talk';
    saveGameRecord();
    // 玩家是狼人：下方实时显示哪些狼队友正在思考（与发言阶段一致）
    setControlArea('<div style="text-align:center;padding:6px;color:#fff;">' + pendingTalk.map(x => x.name).join('、') + ' 正在思考夜间战术...</div>');
    wolfBatchGuard.wolfNight = true;
    wolfRunBatch(session, pendingTalk, w => askOneWolfNightTalk(session, w, talkDone, talks, token, 1), () => {
      wolfBatchGuard.wolfNight = false;
      if (!isSessionValid(session) || game.nightToken !== token) return;
      runWolfMateTalkRound(token, session, aiMates);
    });
  }

  function finishWolfMateTalk(token) {
    const session = game?.session;
    if (!isSessionValid(session) || game.nightToken !== token) return;
    const firstMate = game.players.find(p => isWolfRole(p.role) && !p.isUser && p.alive) || null;
    game.wolfMateChatDone = true;
    saveGameRecord();
    renderWolfTacticsSelection(firstMate);
  }

  function askOneWolfNightTalk(session, w, talkDone, talks, token, attemptNo) {
    return new Promise(finish => {
      const ctx = wolfNightSharedContext();
      const mates = game.players.filter(p => isWolfRole(p.role) && p.alive).map(p => `${p.position}号位 ${p.name}${p.isUser ? '（玩家本人）' : ''}`).join('、');
      const prompt = `你正在扮演第${game.day}天夜晚的狼人阵营玩家 ${w.position}号位 ${w.name}（底牌：${w.role}；狼队友：${mates}）。\n本局玩家列表：\n${ctx.plist}\n规则：${ctx.wolfBoardDesc}。女巫仅首夜可以自救，其余夜晚不可自救。${ctx.wolfWinRule}。${ctx.failedKillNote}${getInfoBoundaryRule()}\n\n【你的人设】：${getPlayerPersonalityPrompt(w)}\n\n【夜间密谋发言阶段（狼队所有成员分别表态，之后会汇总给拍板狼人）】：\n1. 狼人仅知晓存活狼队友，好人具体身份完全未知！严禁开天眼！根据发言抿神。\n2. 这是一场熟人间狼人杀桌游，刀人淘汰只是游戏出局，在密谋中充分结合人际关系拉扯。\n3. 在<thinking>中输出你今晚的刀人思路与你打算采用的战术（想刀谁、是否悍跳/冲锋/倒钩等）；在<private>中向狼队友发表你的密谋发言（40~80字，完全代入人设口吻，可表态刀谁、以及对战术分工的建议）。\n\n输出格式必须严格为：\n<thinking>你的刀人与战术思考</thinking>\n<private>你对狼队友说的密谋发言</private>`;
      const config = loadConfig();
      apiChat([
        { role: 'system', content: '你是狼人团队中的一员，正在进行夜间密谋发言。必须忠实代入角色性格、人设口癖及角色间情感态度，严禁开天眼。' },
        { role: 'user', content: prompt }
      ], config, { maxTokens: 2000, timeout: 70000 }).then(res => {
        if (!isSessionValid(session) || game.nightToken !== token) { finish(); return; }
        let thought = '';
        let privSpeech = '';
        const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
        if (mTh) thought = mTh[1].trim();
        const mPr = res.match(/<private>([\s\S]*?)<\/private>/i);
        if (mPr) privSpeech = mPr[1].trim();
        else {
          const mSp = res.match(/<speech>([\s\S]*?)<\/speech>/i);
          if (mSp) privSpeech = mSp[1].trim();
        }
        privSpeech = privSpeech.replace(/<\/?thinking>/gi, '').replace(/<\/?private>/gi, '').replace(/<\/?speech>/gi, '').trim();
        if (!thought) thought = `作为${w.role}，今晚我需要和队友统一刀口，并明确白天的战术分工。`;
        if (!privSpeech) privSpeech = '今晚怎么刀？我建议先刀发言威胁最大的那个，白天我们配合好。';
        addHiddenThought(thought, w.position);
        addWolfPrivateLog(`[${w.position}号位 ${w.name}]: ${privSpeech}`, w.position);
        if (talkDone.indexOf(w.position) === -1) talkDone.push(w.position);
        if (!talks.some(x => x.pos === w.position)) talks.push({ pos: w.position, text: privSpeech });
        saveGameRecord();
        finish();
      }).catch(err => {
        if (!isSessionValid(session) || game.nightToken !== token) { finish(); return; }
        handleAiFailure('AI狼人夜间发言（' + w.position + '号位 ' + w.name + '）', err, (attemptNo || 1), (n) => { askOneWolfNightTalk(session, w, talkDone, talks, token, n).then(finish); }, () => {
          if (!isSessionValid(session) || game.nightToken !== token) { finish(); return; }
          const fb = '今晚听大家的，我先跟一刀。';
          addWolfPrivateLog(`[${w.position}号位 ${w.name}]: ${fb}`, w.position);
          if (talkDone.indexOf(w.position) === -1) talkDone.push(w.position);
          if (!talks.some(x => x.pos === w.position)) talks.push({ pos: w.position, text: fb });
          saveGameRecord();
          finish();
        });
      });
    });
  }

  // ========== 阶段B：随机一名狼人根据夜间讨论再次思考并拍板击杀目标与战术 ==========
  function runWolfNightDecision(token, attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session) || game.nightToken !== token) return;
    const wolves = game.players.filter(p => isWolfRole(p.role) && p.alive);
    if (!wolves.length) {
      game.nightKill = null;
      game.wolfNightPhase = '';
      saveGameRecord();
      afterWolfKillStep();
      return;
    }
    let decider = wolves.find(w => w.position === game.wolfNightDeciderPos) || null;
    if (!decider) {
      decider = wolves[Math.floor(Math.random() * wolves.length)];
      game.wolfNightDeciderPos = decider.position;
    }
    game.wolfNightPhase = 'decide';
    saveGameRecord();
    const ctx = wolfNightSharedContext();
    const talks = game.wolfNightSpeeches || [];
    const talkText = talks.length
      ? talks.map(t => { const tp = game.players.find(x => x.position === t.pos); return '[' + t.pos + '号位 ' + (tp ? tp.name : '') + ']: ' + t.text; }).join('\n')
      : '（狼队本轮没有留下有效密谋发言）';
    const wantTactics = game.day === 1;
    const tacticBlock = wantTactics ? '\nTACTIC_LEAP: [悍跳预言家的狼人号位，无填0]\nTACTIC_CHARGE: [冲锋狼人号位，无填0]\nTACTIC_HOOK: [倒钩狼人号位，无填0]' : '';
    const prompt = `你正在扮演第${game.day}天夜晚的狼人阵营玩家 ${decider.position}号位 ${decider.name}（底牌：${decider.role}）——本轮由你根据狼队讨论拍板决定今晚的击杀目标与团队战术。\n本局玩家列表：\n${ctx.plist}\n规则：${ctx.wolfBoardDesc}。女巫仅首夜可以自救，其余夜晚不可自救。${ctx.wolfWinRule}。${ctx.failedKillNote}${getInfoBoundaryRule()}\n\n【你的人设】：${getPlayerPersonalityPrompt(decider)}\n\n【狼队夜间讨论记录】：\n${talkText}\n\n【拍板决策要求】：\n1. 狼人仅知晓存活狼队友，好人具体身份完全未知！严禁开天眼！\n2. 综合队友们的讨论与提议的战术安排，在<thinking>中先逐条明确你对队友安排的战术【执行】或【不执行】的结论（如悍跳/冲锋/倒钩、刀位选择等），再给出今晚的刀人分析（刀谁收益最大、是否要避开守卫）。\n3. 在<private>中输出你的拍板密语（以你的人设口吻向队友宣布最终决定）。\n4. 在<WOLF_ACTION>中输出最终决定。\n\n输出格式必须严格为：\n<thinking>对队友战术安排的执行结论 + 最终刀人分析</thinking>\n<private>你的拍板密语</private>\n<WOLF_ACTION>\nWOLF_KILL: [被刀玩家的号位数字]${tacticBlock}\n</WOLF_ACTION>`;
    const config = loadConfig();
    apiChat([
      { role: 'system', content: '你是狼人团队的拍板决策者。必须忠实代入角色性格，严禁开天眼；必须在思考中明确对队友战术安排执行或不执行。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000, timeout: 70000 }).then(res => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
      const mTh = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      const thought = mTh ? mTh[1].trim() : '';
      if (thought) addHiddenThought(thought, decider.position);
      const mPriv = res.match(/<private>([\s\S]*?)<\/private>/i);
      const privMsg = mPriv ? mPriv[1].trim() : `🐺 [第${game.day}夜] 狼队已拍板夜间刀人决定。`;
      addWolfPrivateLog(`[${decider.position}号位 ${decider.name}] ${privMsg}`, decider.position);
      if (wantTactics) {
        const normT = (v) => (v > 0 ? v : 0);
        game.aiWolfTactics = {
          leap: normT(parseWolfTargetPos(res, 'TACTIC_LEAP')),
          charge: normT(parseWolfTargetPos(res, 'TACTIC_CHARGE')),
          hook: normT(parseWolfTargetPos(res, 'TACTIC_HOOK'))
        };
      }
      let killPos = parseWolfTargetPos(res, 'WOLF_KILL');
      const killable = game.players.filter(p => p.alive && p.role !== '狼美人');
      let killTarget = null;
      if (killPos > 0) {
        killTarget = game.players.find(p => p.position === killPos && p.alive && p.role !== '狼美人') || null;
        if (!killTarget && killable.length) killTarget = killable[Math.floor(Math.random() * killable.length)];
      }
      if (!killTarget && killable.length) {
        killTarget = killable[Math.floor(Math.random() * killable.length)];
      }
      game.nightKill = killTarget;
      game.lastWolfKillPos = killTarget ? killTarget.position : 0;
      game.lastWolfKillDied = false;
      const kTarget = game.nightKill;
      addWolfPrivateLog('🐺 [狼队击杀指令] ' + decider.name + '（' + decider.position + '号位）拍板：' + (kTarget ? ('今晚击杀 ' + kTarget.name + '（' + kTarget.position + '号位）') : '空刀'), decider.position);
      game.wolfNightPhase = '';
      saveGameRecord();
      afterWolfKillStep();
    }).catch(err => {
      if (!isSessionValid(session) || game.nightToken !== token) return;
