  async function finishNightAndStartDay() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.nightStep = 'end'; // 夜晚流程已走完：恢复时不再重跑验人/刀人/用药
    game.nightToken = (game.nightToken || 0) + 1; // 使仍在途的旧夜晚回调失效

    if (game.nightKill && game.nightKill.alive) {
      game.nightKill.alive = false;
      game.nightKill.deathCause = 'kill';
      game.nightDeaths.push({ p: game.nightKill, type: '狼杀' });
      if (game.lastWolfKillPos && game.nightKill.position === game.lastWolfKillPos) game.lastWolfKillDied = true;
    }
    game.nightKill = null;

    await resolveWolfBeautyChain(session, 'night');
    if (!isSessionValid(session)) return;

    if (game.nightDeaths.length) {
      const deadStrs = [...new Set(game.nightDeaths.map(d => `${d.p.name}（${d.p.position}号位）`))];
      const chainCount = (game.nightDeaths || []).filter(d => d && d.type === '殉情').length;
      game.nightResult = `昨夜，${deadStrs.join(' 和 ')} 死亡出局` + (chainCount ? `（其中 ${chainCount} 人因狼美人殉情出局，殉情角色技能无法发动）` : '');
    } else {
      game.nightResult = '昨夜是平安夜，无人死亡';
    }

    // 警长出局：夜间出局的警长（含被毒）需要决定警徽移交或撕毁
    const nightDeadSheriff = (game.sheriffPos && !game.sheriffBadgeTorn)
      ? game.nightDeaths.map(d => d && d.p).find(p => p && p.position === game.sheriffPos)
      : null;
    // 期间若警长夜间出局：先公布天亮与死讯，再进入警徽归属思考，避免头像状态（变灰/警徽移动）先于系统提示出现
    if (nightDeadSheriff && !game.dayAnnounced) {
      game.dayAnnounced = true;
      addJudgeLog(`☀️ 第${game.day}天天亮，公告：${game.nightResult}`, true);
    }

    renderGameUI();
    saveGameRecord();

    if (nightDeadSheriff) {
      await resolveSheriffBadgeOnDeath(session, nightDeadSheriff);
      if (!isSessionValid(session)) return;
    }

    // 猎人技能：夜间出局的猎人（被毒死的除外）可以开枪带走 1 人
    await resolveHunterShots(session);
    if (!isSessionValid(session)) return;

    if (checkWin()) { endGame(); return; }
    startDay();
  }

  // ========== 游戏核心流程 ==========
  function startGame() {
    identityPackOpen = false;
    if (!game) return;
    resetWolfBatchGuard();
    const session = game.session;
    const judgeName = String(game.judgeName || '');
    const usedNames = new Set((game.players || []).map(pl => pl.name));
    let judgeReplaced = false;
    let judgeFillNo = 1;
    (game.players || []).forEach(pl => {
      if (judgeName && !pl.isUser && isNameMatch(pl.name, judgeName)) {
        let filler = '';
        do { filler = '角色' + (judgeFillNo++); } while (usedNames.has(filler) || isNameMatch(filler, judgeName));
        usedNames.add(filler);
        pl.name = filler;
        pl.avatar = '';
        judgeReplaced = true;
      }
    });
    if (judgeReplaced) {
      showToast('⚖️ 法官「' + judgeName + '」不能同时作为玩家，已由内置角色补位');
      if (Array.isArray(game.wolfTeammateNames)) game.wolfTeammateNames = game.wolfTeammateNames.filter(n => !isNameMatch(n, judgeName));
      if (game.wolfBeautyTeammateName && isNameMatch(game.wolfBeautyTeammateName, judgeName)) game.wolfBeautyTeammateName = '';
      if (game.wolfWwkTeammateName && isNameMatch(game.wolfWwkTeammateName, judgeName)) game.wolfWwkTeammateName = '';
    }
    // 身份卡：第一张决定主角身份；狼人卡可邀请普通狼队友，狼美人卡可邀请狼美人队友；其余随机分配剩余身份
    const picked = Array.isArray(game.identityCards) ? game.identityCards.slice() : [];
    const mateNames = Array.isArray(game.wolfTeammateNames) ? game.wolfTeammateNames.slice() : [];
    const userIdx = (typeof game.userIndex === 'number' && game.userIndex >= 0) ? game.userIndex : -1;
    const firstCard = picked[0] || null;
    const selfWolf = firstCard === 'wolf';
    const selfBeauty = firstCard === 'beauty';
    const selfWwk = firstCard === 'wwk';
    const beautyTeammateCard = selfWolf && picked.includes('beauty');
    const wwkTeammateCard = selfWolf && picked.includes('wwk');
    const wolfCardsRaw = picked.filter(k => k === 'wolf').length;
    const wolfCardCap = getWolfCardCap();
    const wolfCards = (selfWolf || selfBeauty || selfWwk) ? Math.min(wolfCardsRaw, wolfCardCap) : 0;
    const normalMateCap = (selfBeauty || selfWwk)
      ? Math.min(wolfCards, wolfCardCap)
      : (selfWolf ? Math.max(0, Math.min(wolfCards - 1, wolfCardCap - 1)) : 0);
    const mateIdxList = [];
    for (const nm of mateNames) {
      if (mateIdxList.length >= normalMateCap) break;
      const idx = game.players.findIndex(p => !p.isUser && isNameMatch(p.name, nm));
      if (idx !== -1) mateIdxList.push(idx);
    }
    // 狼美人队友：仅在「狼人卡为主角 + 已选狼美人卡」时启用；不占普通狼人卡
    let beautyMateIdx = -1;
    if (beautyTeammateCard) {
      const bn = String(game.wolfBeautyTeammateName || '');
      if (bn) {
        beautyMateIdx = game.players.findIndex((p, idx) => idx !== userIdx && !mateIdxList.includes(idx) && isNameMatch(p.name, bn));
      }
      if (beautyMateIdx === -1) {
        const candidates = game.players.map((p, idx) => idx).filter(idx => idx !== userIdx && !mateIdxList.includes(idx));
        if (candidates.length) beautyMateIdx = candidates[Math.floor(Math.random() * candidates.length)];
        showToast('未选择狼美人队友，已随机指定');
      }
    }
    // 白狼王队友：仅在「狼人卡为主角 + 已选白狼王卡」时启用；不占普通狼人卡
    let wwkMateIdx = -1;
    if (wwkTeammateCard) {
      const wn = String(game.wolfWwkTeammateName || '');
      if (wn) {
        wwkMateIdx = game.players.findIndex((p, idx) => idx !== userIdx && !mateIdxList.includes(idx) && idx !== beautyMateIdx && isNameMatch(p.name, wn));
      }
      if (wwkMateIdx === -1) {
        const candidates = game.players.map((p, idx) => idx).filter(idx => idx !== userIdx && !mateIdxList.includes(idx) && idx !== beautyMateIdx);
        if (candidates.length) wwkMateIdx = candidates[Math.floor(Math.random() * candidates.length)];
        showToast('未选择白狼王队友，已随机指定');
      }
    }
    // 角色池：6人场 2狼2民1预1女；9人场 3狼3民1预1女1猎人；10人场 3狼3民1预1女1猎人1愚者；12人场 4狼4民1预1女1猎人1守卫；狼美人板子用狼美人/骑士替换猎人
    const boardN = (game.players || []).length;
    const pool = boardN >= 12
      ? ((boardN === 12 && isWwkBoard())
        ? ['狼人', '狼人', '狼人', '白狼王', '民', '民', '民', '民', '预言家', '女巫', '守卫', '骑士']
        : (isBeautyBoard()
          ? ['狼美人', '狼人', '狼人', '狼人', '民', '民', '民', '民', '预言家', '女巫', '骑士', '守卫']
          : ['狼人', '狼人', '狼人', '狼人', '民', '民', '民', '民', '预言家', '女巫', '猎人', '守卫']))
      : (boardN === 10 && isHunterWolfBoard())
        ? ['狼人', '狼人', '狼人', '猎人', '猎人', '猎人', '猎人', '猎人', '猎人', '猎人']
        : (boardN === 10 && isWwkBoard())
        ? ['狼人', '狼人', '白狼王', '民', '民', '民', '预言家', '女巫', '愚者', '骑士']
        : (boardN === 10 && isBeauty10Board())
          ? ['狼人', '狼人', '狼美人', '民', '民', '民', '预言家', '女巫', '愚者', '骑士']
          : (boardN === 10 && isGodsBoard())
            ? ['狼人', '狼人', '狼人', '民', '民', '民', '预言家', '女巫', '猎人', '愚者']
            : (boardN === 7 && isEnt7Board())
              ? ['狼人', '白狼王', '民', '预言家', '女巫', '守卫', '猎人']
              : (boardN === 8 && isEnt8Board())
                ? ['狼人', '狼人', '狼人', '民', '民', '预言家', '守卫', '骑士']
                : boardN >= 9
          ? (isBeautyBoard()
            ? ['狼美人', '狼人', '狼人', '民', '民', '民', '预言家', '女巫', '骑士']
            : ['狼人', '狼人', '狼人', '民', '民', '民', '预言家', '女巫', '猎人'])
          : (boardN === 6 && isGuard6Board())
            ? ['狼人', '狼人', '民', '民', '预言家', '守卫']
            : ['狼人', '狼人', '民', '民', '预言家', '女巫'];
    const normalWolfNeed = (selfWolf ? 1 : 0) + mateIdxList.length;
    let wolfGuard = 0;
    while (pool.filter(r => r === '狼人').length < normalWolfNeed && wolfGuard++ < 8) {
      const vi = pool.indexOf('民');
      if (vi !== -1) { pool[vi] = '狼人'; continue; }
      break;
    }
    const takeRole = (role) => {
      const i = pool.indexOf(role);
      if (i === -1) return false;
      pool.splice(i, 1);
      return true;
    };
    const finalAssigned = {};
    const consumed = {};
    // 1) 主角身份：第一张卡决定；狼人卡主角走普通狼人，狼美人卡主角走狼美人
    if (selfBeauty && userIdx >= 0) {
      if (takeRole('狼美人')) {
        finalAssigned[userIdx] = '狼美人';
        consumed.beauty = (consumed.beauty || 0) + 1;
      }
    } else if (selfWolf && userIdx >= 0) {
      if (takeRole('狼人')) {
        finalAssigned[userIdx] = '狼人';
        consumed.wolf = (consumed.wolf || 0) + 1;
      }
    } else if (firstCard && userIdx >= 0) {
      const def = IDENTITY_CARD_TYPES.find(t => t.key === firstCard);
      if (def && takeRole(def.role)) {
        finalAssigned[userIdx] = def.role;
        consumed[firstCard] = (consumed[firstCard] || 0) + 1;
      }
    }
    // 2) 普通狼人队友（每消耗 1 张狼人卡）
    for (const idx of mateIdxList) {
      if (takeRole('狼人')) {
        finalAssigned[idx] = '狼人';
        consumed.wolf = (consumed.wolf || 0) + 1;
      }
    }
    // 3) 狼美人队友（消耗 1 张狼美人卡）
    if (beautyMateIdx !== -1 && takeRole('狼美人')) {
      finalAssigned[beautyMateIdx] = '狼美人';
      consumed.beauty = (consumed.beauty || 0) + 1;
    }
    // 3.5) 白狼王队友（消耗 1 张白狼王卡）
    if (wwkMateIdx !== -1 && takeRole('白狼王')) {
      finalAssigned[wwkMateIdx] = '白狼王';
      consumed.wwk = (consumed.wwk || 0) + 1;
    }
    // 4) 其余玩家随机分配剩余身份
    const restIdx = game.players.map((p, i) => i).filter(i => !(i in finalAssigned));
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    restIdx.forEach((idx, i) => { finalAssigned[idx] = pool[i] || '民'; });
    // 5) 消耗身份卡（主角卡 + 普通狼人卡 + 狼美人队友卡）
    let consumeFailed = false;
    for (const key of Object.keys(consumed)) {
      if (!consumeIdentityCard(key, consumed[key])) consumeFailed = true;
    }
    if (consumeFailed) showToast('⚠️ 部分身份卡数量不足，已按现有卡牌开局');
    game.identityCards = [];
    game.wolfTeammateNames = [];
    game.wolfBeautyTeammateName = '';
    game.wolfWwkTeammateName = '';
    game.players.forEach((p, idx) => {
      p.role = finalAssigned[idx] || '民';
      p.foolFlipped = false;
      p.hunterShotDone = false;
      p.roleRevealed = false;
      p.avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
    });
    game.day = 1;
    game.phase = 'night';
    game.replay = [];
    game.history = [];
    game.historyEntries = [];
    game.nightDeaths = [];
    game.witchSavedPos = null;
    game.guardProtectedPos = null;
    game.guardLastPos = null;
    game.lastWolfKillPos = 0;
    game.lastWolfKillDied = false;
    game.wolfBeautyCharmedPos = null;
    game.wolfBeautyLastCharmedPos = 0;
    game.wolfBeautyChainResolved = false;
    game.knightDuelUsed = false;
    game.knightPromptActive = false;
    game.knightPromptContext = '';
    game.knightPromptIsAi = false;
    game.knightSheriffPromptDone = false;
    game.knightAiAskCount = 0;
    game.knightManualDuel = false;
    game.sheriffPos = null;
    game.sheriffStage = '';
    game.sheriffDone = false;
    game.sheriffCandidates = [];
    game.sheriffWithdrawn = [];
    game.sheriffVotes = {};
    game.sheriffDirection = '';
    game.sheriffBadgeTorn = false;
    game.isPkVote = false;
    game.aiVotesDone = false;
    game.speechesStartedDay = 0;
    game.pkCandidates = null;
    renderGameUI();

    const user = game.players[game.userIndex];
    if (user && user.isUser) {
      const cfgDesc = getBoardRoleDesc();
      addGameLog(`游戏开始，请确认自己的身份。场上配置：${cfgDesc} | 你的身份是：【${user.role}】`, false, null, '#EF4444');
    } else if (game.spectatorMode) {
      addGameLog('👁️ 你以上帝视角观战本局：全部身份与夜间行动均可见。', false, null, '#0EA5E9');
    }
    saveGameRecord();
    startNight();
  }

  function startNight() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'night';
    game.finalWordsActive = false;
    game.finalWordsSurvivor = false;
    game.nightKill = null;
    game.nightDeaths = [];
    game.witchAction = null;
    game.wolfMateChatDone = false;
    game.wolfNightPhase = '';
    game.wolfNightTalkDone = [];
    game.wolfNightSpeeches = [];
    game.wolfNightDeciderPos = 0;
    game.guardProtectedPos = null;
    game.pickMode = null;
    game.pick = { idx: null };
    game.witchMenu = false;
    game.witchMenuReturn = false;
    game.isPkVote = false;
    game.pkCandidates = null;
    game.knightPromptActive = false;
    game.knightPromptContext = '';
    game.knightPromptIsAi = false;
    game.knightSheriffPromptDone = false;
    game.knightManualDuel = false;
    game.wolfBeautyCharmedPos = null;
    game.wolfBeautyChainResolved = false;
    game.dayAnnounced = false; // 新的一夜开始：本日天亮公告尚未发布（若夜间警长出局，会在警徽思考前提前公布死讯）
    game.nightStep = isBeautyBoard() ? 'wolf' : 'guard'; // 狼美人板子按法官顺序从狼队开始；经典板子从守卫开始
    game.nightToken = (game.nightToken || 0) + 1;
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 🌙 夜晚`;
    addJudgeLog(`🌙 第${game.day}天夜晚来临`, true);
    renderGameUI();
    saveGameRecord();
    runNightSequence();
  }

  // 天亮播报与首夜遗言（警长竞选结束后才公布死讯）
  async function announceDayAndDeaths() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    const dawnAlreadyAnnounced = !!game.dayAnnounced; // 警长出局流程可能已提前公布死讯，避免重复公告
    game.dayAnnounced = true;
    renderGameUI();
    if (!dawnAlreadyAnnounced) addJudgeLog(`☀️ 第${game.day}天天亮，公告：${game.nightResult}`, true);
    saveGameRecord();
    const firstNightDeaths = game.day === 1 ? game.nightDeaths : [];
    if (firstNightDeaths.length) {
      addJudgeLog('💬 首夜出局玩家发表遗言：', true);
      for (const d of firstNightDeaths) {
        if (!isSessionValid(session)) return;
        await generateFinalWords(d.p);
      }
    }
    // 白狼王未发动自爆而夜间出局：按暗牌普通狼人处理，仍可发表遗言（不公开其白狼王身份）
    const wwkNightDeaths = game.nightDeaths.filter(d => d.p && d.p.role === '白狼王' && !firstNightDeaths.includes(d));
    if (wwkNightDeaths.length) {
      addJudgeLog('💬 出局玩家发表遗言：', true);
      for (const d of wwkNightDeaths) {
        if (!isSessionValid(session)) return;
        await generateFinalWords(d.p);
      }
    }
    if (!isSessionValid(session)) return;
    game.nightDeaths = [];
  }

  // 警长竞选结束后的统一出口：先公布死讯（若尚未公布），再进入发言方向决定/正常发言
  function afterSheriffElection(goDirection) {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    const cont = () => {
      if (!isSessionValid(session) || game.phase !== 'day') return;
      // 警长存活且今天还未决定发言方向：先让警长决定方向；否则直接进入/续跑发言
      if (goDirection && game.sheriffPos && !game.sheriffBadgeTorn && game.sheriffDirectionDay !== game.day) sheriffPickDirection();
      else beginDaySpeeches();
    };
    if (!game.dayAnnounced) {
      announceDayAndDeaths().then(() => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        cont();
      });
      return;
    }
    cont();
  }

  async function startDay() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'day';
    game.pickMode = null;
    game.pick = { idx: null };
    game.finalWordsActive = false;
    game.finalWordsSurvivor = false;
    game.witchMenu = false;
    game.witchMenuReturn = false;
    game.isPkVote = false;
    game.pkCandidates = null;
    hideActionPopup();
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · ☀️ 白天`;
    // 10/12人场首日：先进行警长竞选，竞选结束后才公布死讯
    if (game.day === 1 && game.players.length >= 10 && !isHunterWolfBoard() && !game.sheriffDone && !game.sheriffPos && !game.sheriffBadgeTorn) {
      renderGameUI();
      saveGameRecord();
      startSheriffElection();
      return;
    }
    await announceDayAndDeaths();
    if (!isSessionValid(session)) return;
    beginDaySpeeches();
  }

  function beginDaySpeeches() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    if (game.speechesStartedDay === game.day) { startSpeaking(); return; } // 今天已开始过发言：续跑当前发言者，不重置进度（防重复初始化导致跳过/重来）
    game.speechesStartedDay = game.day;
    game.players.forEach(p => { p.hasSpoken = false; p.votedFor = null; });
    game.sheriffLeadDone = false;
    const sheriff = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    if (sheriff && sheriff.alive && game.sheriffDirectionDay !== game.day) { sheriffPickDirection(); return; }
    let startIdx = -1;
    if (sheriff && sheriff.alive && game.sheriffDirection) {
      startIdx = sheriffNeighborStartIndex(sheriff.position, game.sheriffDirection);
    } else {
      startIdx = 0;
      while (startIdx < game.players.length && !game.players[startIdx].alive) startIdx++;
    }
    if (startIdx < 0 || startIdx >= game.players.length) { endGame(); return; }
    game.currentSpeaker = startIdx;
    renderGameUI();
    addJudgeLog(`💬 从 ${game.players[game.currentSpeaker].position}号位 ${game.players[game.currentSpeaker].name} 开始发言${(sheriff && sheriff.alive && game.sheriffDirection) ? '（警长决定从' + (game.sheriffDirection === 'left' ? '警左' : '警右') + '开始）' : ''}`, true);
    saveGameRecord();
    startSpeaking();
  }

  function startSpeaking() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    if (game.knightManualDuel) return;
    const current = game.players[game.currentSpeaker];
    if (!current || !current.alive || current.hasSpoken) { nextSpeaker(); return; }
    // 每次轮到发言者时刷新发言令牌：过期/重复的生成回调不再推进发言顺序，防止跳过下一位发言者
    const speechToken = (game.speechToken = (game.speechToken || 0) + 1);
    if (current.isUser) {
      setControlArea(`
        <div id="game-speak-area" style="display:flex;gap:4px;margin:6px 0;">
          <input id="game-speak-input" class="ubp-fieldinput" type="text" placeholder="输入你的发言..." style="flex:1;min-width:0;">
          <button data-ubp-act="game-speak" class="ubp-btn primary" style="padding:0 10px;">发言</button>
          <button data-ubp-act="game-speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button>
        </div>
      `);
      const input = sheet?.querySelector('#game-speak-input');
      if (input) input.focus();
    } else {
      setControlArea(`<div style="text-align:center;padding:6px;color:#fff;">${current.name} 正在思考...</div>`);
      generateAISpeech(current, () => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        if (game.speechToken !== speechToken) return; // 过期/重复回调：已被新一轮发言取代
        if (current.hasSpoken) return;
        current.hasSpoken = true;
        saveGameRecord();
        if (game.phase === 'day') nextSpeaker();
      });
    }
  }

  function nextSpeaker() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    if (game.knightManualDuel) return;
    if (typeof game.currentSpeaker !== 'number' || game.currentSpeaker < 0 || game.currentSpeaker >= game.players.length) game.currentSpeaker = 0;
    const area = sheet?.querySelector('#game-speak-area');
    if (area) area.style.display = 'none';
    const total = game.players.length;
    const sheriffOnBoard = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    const dirNow = (sheriffOnBoard && sheriffOnBoard.alive) ? game.sheriffDirection : game.speechDir;
    const step = (dirNow === 'right') ? -1 : 1;
    let next = -1;
    for (let k = 1; k <= total; k++) {
      const idx = ((game.currentSpeaker + step * k) % total + total) % total;
      const cand = game.players[idx];
      if (cand && cand.alive && !cand.hasSpoken) { next = idx; break; }
    }
    if (next === -1) {
      addJudgeLog(`📢 本轮发言结束`, true);
      game.aiVotesDone = false; // 新一轮放逐投票：重置AI投票进度（用户投票后置）
      saveGameRecord();
      maybeStartKnightPrompt('day', () => completeKnightPrompt('day'));
    } else {
      game.currentSpeaker = next;
      saveGameRecord();
      startSpeaking();
    }
  }

  // ========== 狼人杀发言解析：严格区分「思考 / 公开发言」，公开发言里绝不允许残留隐蔽思考内容 ==========
  // 返回 { thought, speech }。兼容模型偷懒/截断导致的未闭合标签、旧版【思考原因】【公开发言】格式。
  function parseWolfSpeechResponse(res) {
    const raw = String(res == null ? '' : res);
    let thought = '';
    let speech = '';

    // 1) 思考：优先 <thinking>…</thinking>（闭合）；未闭合（多为输出被截断）则取到 <speech>/【公开发言】之前
    const mThought = raw.match(/<thinking>([\s\S]*?)<\/thinking>/i);
    if (mThought) {
      thought = mThought[1].trim();
    } else {
      const mAltThought = raw.match(/【思考原因】([\s\S]*?)(?=【公开发言】|<speech>|$)/i);
      if (mAltThought) thought = mAltThought[1].trim();
      else {
        const speechIdx = raw.search(/<speech>|【公开发言】/i);
        const openIdx = raw.search(/<thinking>/i);
        if (openIdx !== -1) {
          const endIdx = (speechIdx !== -1 && speechIdx > openIdx) ? speechIdx : raw.length;
          thought = raw.slice(openIdx, endIdx).replace(/<\/?thinking>/gi, '').replace(/<[^>]+>/g, '').trim();
        } else if (speechIdx > 0) {
          thought = raw.slice(0, speechIdx).replace(/<[^>]+>/g, '').trim();
        }
      }
    }

    // 2) 公开发言：优先 <speech>…</speech>；兼容【公开发言】；最后兜底为「原文剥离所有思考和私聊块」
    const mSpeech = raw.match(/<speech>([\s\S]*?)(?:<\/speech>|$)/i);
    if (mSpeech) {
      speech = mSpeech[1].trim();
    } else {
      const mAltSpeech = raw.match(/【公开发言】([\s\S]*?)$/i);
      if (mAltSpeech) {
        speech = mAltSpeech[1].trim();
      } else {
        speech = raw
          .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
          .replace(/<thinking>[\s\S]*$/gi, '')
          .replace(/<private>[\s\S]*?<\/private>/gi, '')
          .replace(/【思考原因】[\s\S]*?(?=【公开发言】|<speech>|$)/gi, '')
          .trim();
      }
    }

    // 3) 双重保险：公开发言里若混入了思考块/私聊块或裸标签，全部剜掉，防止泄露隐蔽思考
    speech = speech
      .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
      .replace(/<thinking>[\s\S]*$/gi, '')
      .replace(/<private>[\s\S]*?<\/private>/gi, '')
      .replace(/【思考原因】[\s\S]*?(?=【公开发言】|$)/gi, '')
      .replace(/<\/?(thinking|speech|private)>/gi, '')
      .replace(/【思考原因】|【公开发言】|【内心思考】|【隐蔽思考】/g, '')
      .replace(/[*_`~]/g, '')
      .trim();

    return { thought: thought, speech: speech };
  }

  // 公开发言完整收尾：输出被截断（半句/缺标点）时补一句自然结尾，避免半句话直接收尾
  function completeWolfSpeechLine(text, kind) {
    let s = String(text == null ? '' : text).trim();
    if (!s) return s;
    s = s.replace(/[，,、:：；;\-—…\s]+$/, '').trim();
    if (/[。！？!?…～~”"』」）)\]】]$/.test(s)) return s;
    const tail = kind === 'final'
      ? '，剩下的就交给你们继续推理了！'
      : kind === 'pk'
        ? '，请好人看清局势把票归对，别被狼人带节奏！'
        : '，这就是我目前看出来的疑点，后置位继续听发言。';
    return s + tail;
  }

  // ========== AI 发言生成 ==========
  function generateAISpeech(player, callback, attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session)) return;

    const config = loadConfig();
    const overview = getGamePublicOverview(player);
    const history = getPlayerHistoryContext(player);

    let tacticInstruction = '';
    if (isWolfRole(player.role)) {
      if (game.tactics && (game.tactics.ai || game.tactics.user)) {
        tacticInstruction = `\n【狼队夜间商议战术要求】：\nAI狼队友战术是【${game.tactics.ai || '自由发挥'}】，玩家狼队友战术是【${game.tactics.user || '自由发挥'}】。用户战术指示：${game.tactics.custom || '无'}。\n你必须严格按照战术要求执行发言。`;
      } else if (game.aiWolfTactics) {
        let roleTactic = '自由伪装配合';
        if (game.aiWolfTactics.leap === player.position) roleTactic = '悍跳预言家！报出假查验，攻击真预言家，全力争取好人信任！';
        else if (game.aiWolfTactics.charge === player.position) roleTactic = '冲锋站边！坚定支持悍跳狼队友，猛烈质疑真预言家，带节奏冲票！';
        else if (game.aiWolfTactics.hook === player.position) roleTactic = '倒钩好人！假意站边真预言家，通过表水和踩队友做高自身好人面！';
        tacticInstruction = `\n【狼队夜间商定的分工指引】：你的战术角色是【${roleTactic}】。请严格按分工进行公开发言。`;
      }
    } else if (player.role === '预言家') {
      const checkedDetails = Object.keys(game.seerChecked || {}).map(posStr => {
        const pos = parseInt(posStr);
        const target = game.players.find(p => p.position === pos);
        if (!target) return '';
        const isTargetWolf = isWolfRole(target.role);
        return `${target.position}号位 ${target.name}${target.isUser ? '（玩家主角本人）' : ''}：查验底牌真实为【${isTargetWolf ? '狼人（查杀）' : '好人（金水）'}】`;
      }).filter(Boolean);
      const seerRecordStr = checkedDetails.length > 0 ? checkedDetails.join('；') : '目前尚无查验历史';
      tacticInstruction = `\n【重要：你作为真预言家的夜间查验结果库】（此信息真实无误）：\n${seerRecordStr}\n【查验铁律】：如果上述查验结果表明某玩家为狼人，无论该玩家是否为主角（哪怕名字是“我”），TA也是货真价实的狼人！你在公开发言中若跳预言家报查验，必须明确如实通报该玩家为【狼人/查杀】，绝对严禁把拿了狼人牌的玩家错误称呼为好人或发金水！`;
    } else if (player.role === '女巫') {
      let witchInfo = `\n【你作为女巫的夜间用药情况】：解药${game.witchUsedAntidote ? '已用' : '未用'}，毒药${game.witchUsedPoison ? '已用' : '未用'}。`;
      if (game.witchSavedPos) {
        const savedP = game.players.find(p => p.position === game.witchSavedPos);
        if (savedP) witchInfo += `昨夜解药救下的是：${savedP.position}号位 ${savedP.name}（银水）。`;
      }
      tacticInstruction += witchInfo;
    }

    if (player.role === '白狼王') {
      tacticInstruction += getPlayerIdentitySystemContext(player);
      tacticInstruction += '\n【白狼王自爆选项】：你可以在本次发言前主动自爆带走一名存活玩家。你要像骑士决定是否翻牌决斗一样，果断评估收益与风险：如果自爆能带走关键好人、打断警徽流或直接确保轮次优势，就选择自爆；否则隐藏白狼王身份正常发言。若决定自爆，请只输出：<WWK_BOOM>YES</WWK_BOOM><WWK_TARGET>号位</WWK_TARGET>（不要输出<thinking>/<speech>）；若不自爆，严格按正常发言格式输出。自爆后白天立即结束，直接入夜，自爆者与被带走者均无遗言。投票阶段、遗言阶段不能自爆。';
    } else if (player.role === '守卫' || player.role === '猎人' || player.role === '愚者' || player.role === '民' || player.role === '骑士' || player.role === '狼美人') tacticInstruction += getPlayerIdentitySystemContext(player);
    const wolfDayNote = (isWolfRole(player.role)) ? getWolfFailedKillNote('day') : '';
    const prompt = `你正在扮演当前发言玩家：${player.position}号位 ${player.name}。\n你的真实身份是：${player.role}。\n${overview}${tacticInstruction}${getInfoBoundaryRule()}\n\n【本局历史公开发言与思考记录】：\n${history}${wolfDayNote}\n\n【公开发言角色扮演与底牌指令】：\n1. 底牌原则：你必须尊重并全力为你所在的阵营（${isWolfRole(player.role) ? '狼人阵营' : '好人阵营'}）辩护和争取胜利，绝不公然放水认输！\n2. 人设要求：在<speech>中，必须【完全还原角色的说话语气、口癖、性格和神态】，用第一人称像真人一样说出口。积极与场上其他角色互动吐槽，结合你们的过往关系（见上文关系与社交记录）！\n3. 游戏认知：清楚这只是一场朋友间聚会的狼人杀推理桌游，严禁将游戏出局当成真实的死亡！\n4. 【核心强制铁律】：必须同时包含<thinking>思考</thinking>与<speech>公开发言</speech>两部分，严禁缺失思考内容！在<thinking>中必须详尽写出你作为${player.role}在此刻的心理推演、对场上谁可疑的研判与战术意图（逐条列出你对每位玩家发言的怀疑度与下一步战术）。【防全知铁律】只能使用自己的底牌、专属信息与公开信息推理，严禁开天眼提及任何未公开信息。\n5. 【公开发言完整性铁律】：公开发言必须是一段逻辑连贯、语意完整的表述，必须完整说完观点，闭合语义并自然收尾，严禁输出到一半戛然而止，绝对严禁以逗号或半句话直接结尾于</speech>！\n6. 【严格输出格式铁律】：只允许输出下面两个标签，且两个标签都必须【完整闭合】，标签前后不得有任何多余文字、解释或其它标签：\n<thinking>写出你作为${player.role}此刻的内部心理、角色间拉扯、为什么怀疑某人或如何演戏（必须有实质思考内容）</thinking>\n<speech>真正说出口的完整公开发言（口语化自然、长度自然可长可短，严禁包含动作描写或【公开发言】等标记，必须语义完整、自然收尾，严禁半句截断）</speech>\n严禁输出 <private>、<discussion> 等任何其它标签；严禁把 <thinking> 里的思考内容、心理活动或【思考原因】字样写进 <speech>；公开发言必须是完整收尾的一整段话。${player.role === '白狼王' ? '（白狼王例外：若选择自爆，只输出<WWK_BOOM>YES</WWK_BOOM><WWK_TARGET>号位</WWK_TARGET>，取代<thinking>/<speech>格式。）' : ''}`;

    apiChat([
      { role: 'system', content: applyBoardIntro(getActiveWolfPrompt(config)) },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000, timeout: 70000 }).then(res => {
      if (!isSessionValid(session)) return;
      // 白狼王可选择在本次发言前主动自爆带走一人
      if (player.role === '白狼王' && /WWK_BOOM[：:]?\s*(YES|是|自爆)/i.test(String(res || ''))) {
        const boomPos = parseWolfTargetPos(res, 'WWK_TARGET');
        const boomTarget = game.players.find(p => p.position === boomPos && p.alive && p.position !== player.position);
        if (boomTarget) {
          const boomParsed = parseWolfSpeechResponse(res);
          if (boomParsed.thought) addHiddenThought(boomParsed.thought, player.position);
          executeWhiteWolfKingBoom(player, boomTarget);
          return;
        }
      }
      // 严格解析：思考归思考、公开发言归公开发言，兼容未闭合标签与旧格式
      const parsedSpeech = parseWolfSpeechResponse(res);
      let thought = parsedSpeech.thought;
      let speech = completeWolfSpeechLine(parsedSpeech.speech, 'day');

      if (!speech) speech = '我仔细听了前面的发言，大家的疑点都不少。我先给出明确态度：当前我最怀疑的是发言避重就轻、不点具体号位的人；我后面的票也会优先从这些人里出，请后置位把身份和查验相关信息聊清楚。';

      if (!thought) {
        thought = `作为${player.position}号位（身份：${player.role}），我纵观前置位所有发言与当前局势：目前场上局势错综复杂，各位玩家表水与指控各执一词。我必须严守自身${isWolfRole(player.role) ? '狼队隐蔽伪装与引导抗推' : '好人阵营排狼坑'}立场，在公开发言中既要逻辑严谨、指出疑点，又要符合我的性格人设，不能露出破绽。`;
