      callback();
    }).catch(err => {
      if (!isSessionValid(session)) return;
      handleAiFailure('发言生成', err, (attemptNo || 1), (n) => generateAISpeech(player, callback, n), () => {
        addHiddenThought('（发言连续5次生成失败，按默认内容处理）', player.position);
        addGameLog(`🗣️ ${player.name}（${player.position}号位）: <speech>我仔细听了前面的发言，大家的疑点都不少。我先给出明确态度：当前我最怀疑的是发言避重就轻、不点具体号位的人；我后面的票也会优先从这些人里出，请后置位把身份和查验相关信息聊清楚。</speech>`, true, player.position);
        saveGameRecord();
        callback();
      });
    });
  }

