      if (!isSessionValid(session)) { resolve(); return; }
      const survivor = !!(opts && opts.survivor);
      if (game) { game.finalWordsActive = true; game.finalWordsSurvivor = survivor; }
      if (player.isUser) {
        game.resolvingFinalWords = () => {
          if (game) { game.finalWordsActive = false; game.finalWordsSurvivor = false; }
          resolve();
        };
        showUserFinalWordsUI(survivor);
        return;
