        const parsedV = parseWolfSpeechResponse(res);
        addHiddenThought(parsedV.thought || '正在决定把警长票投给谁。', voter.position);
        let votePos = parseWolfTargetPos(res, 'VOTE_SHERIFF');
        if (votePos < 0 || allowed.indexOf(votePos) === -1) votePos = allowed[Math.floor(Math.random() * allowed.length)];
        game.sheriffVotes[votePos] = (game.sheriffVotes[votePos] || 0) + 1;
