        const pkNote = game.sheriffPkRound ? ('\n【当前是平票后的第二轮警长投票】：首轮投票出现平票，' + candList + ' 刚刚完成了 PK 辩解发言。你必须结合他们的 PK 发言【重新思考】后再投一次，投票目标只能是平票候选人之一。') : '';
