  }

  function finishSheriffVote() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'vote') return;
    // 用户投票后置：AI 投票全部完成后，才弹出用户的警长投票界面
    const userVote = game.players ? game.players[game.userIndex] : null;
    const userIsCand = userVote && (game.sheriffCandidates || []).indexOf(userVote.position) !== -1;
    if (userVote && userVote.alive && !userIsCand && !game.sheriffUserVoted) {
      addGameLog(game.sheriffPkRound ? '🚨 全部AI玩家已完成重新投票，请点击平票候选人头像投出你的警长票：' : '🚨 全部AI玩家已投出警长票，请点击候选人的头像投出你的警长票：', false);
      game.pickMode = 'sheriffvote';
      game.pick = { idx: null };
      renderGameUI();
      setControlArea('');
      saveGameRecord();
      return;
    }
    setControlArea('');
    const remaining = sheriffRemainingCandidates();
    let maxV = 0;
    remaining.forEach(pos => { const v = game.sheriffVotes[pos] || 0; if (v > maxV) maxV = v; });
    let tops = remaining.filter(pos => (game.sheriffVotes[pos] || 0) === maxV && maxV > 0);
    if (!tops.length) tops = remaining.slice();
    const voteStr = remaining.map(pos => { const t = game.players.find(x => x.position === pos); return (t ? t.name : pos + '号位') + ' ' + (game.sheriffVotes[pos] || 0) + '票'; }).join('、');
    // 平票：与放逐投票一致——平票角色先 PK 发言，其余玩家重新思考投票；再次平票则警徽流失
    if (tops.length > 1 && !game.sheriffPkRound) {
      game.sheriffPkRound = 1;
      game.sheriffPkCandidates = tops.slice();
      game.sheriffPkQueue = tops.slice();
      game.sheriffPkIdx = 0;
      game.sheriffStage = 'pk';
      addJudgeLog('🚨 警长选举平票（' + voteStr + '）：' + tops.map(pos => pos + '号位').join('、') + ' 进入平票 PK 发言环节！', true);
      saveGameRecord();
      renderGameUI();
      runNextSheriffPkSpeaker();
      return;
    }
    if (tops.length > 1 && game.sheriffPkRound) {
      addJudgeLog('🚨 PK投票再次平票（' + voteStr + '），警徽流失，本局没有警长。', true);
      game.sheriffPos = null;
      game.sheriffStage = 'done';
      game.sheriffDone = true;
      game.sheriffBadgeTorn = true;
      game.sheriffDirection = '';
      game.sheriffDirectionDay = 0;
      saveGameRecord();
      renderGameUI();
      afterSheriffElection(false);
      return;
    }
    const winnerPos = tops[0];
    const winner = game.players.find(p => p.position === winnerPos);
    game.sheriffPos = winnerPos;
    game.sheriffStage = 'done';
    game.sheriffDone = true;
    game.sheriffDirection = '';
    game.sheriffDirectionDay = 0;
    addJudgeLog('🚨 警长选举结果：' + voteStr + '。' + (winner ? winner.name + '（' + winnerPos + '号位）' : winnerPos + '号位') + ' 当选警长！🎖️', true);
    saveGameRecord();
    renderGameUI();
    afterSheriffElection(true);
  }
  // 警长决定每天从警左还是警右开始发言（决定一次并持续生效）
  function sheriffPickDirection(attemptNo) {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'day') return;
    const sheriff = game.sheriffPos ? game.players.find(p => p.position === game.sheriffPos) : null;
    if (!sheriff || !sheriff.alive || game.sheriffBadgeTorn) { beginDaySpeeches(); return; }
    if (sheriff.isUser) {
      addGameLog('🚨 你是警长，请决定从警左还是警右开始发言（警左=号位递增方向，警右=号位递减方向）：', false);
      setControlArea('<div style="display:flex;gap:6px;justify-content:center;padding:6px;"><button data-ubp-act="sheriff-order-left" class="ubp-btn primary" style="padding:6px 18px;">⬅️ 警左先发言</button><button data-ubp-act="sheriff-order-right" class="ubp-btn" style="padding:6px 18px;">➡️ 警右先发言</button></div>');
