    }).catch(err => {
      if (!isSessionValid(session) || game.phase !== 'day') return;
      handleAiFailure('AI警长方向思考', err, (attemptNo || 1), (n) => sheriffPickDirection(n), () => {
        if (!isSessionValid(session) || game.phase !== 'day') return;
        game.sheriffDirection = 'right';
        game.sheriffDirectionDay = game.day;
        addGameLog('🚨 AI警长方向思考失败，默认从警右开始发言。', true);
        saveGameRecord();
        beginDaySpeeches();
      });
    });
  }
  // 警长出局：AI 思考移交警徽或撕毁警徽（用户在 UI 中选择）
  function sheriffNeighborStartIndex(sheriffPos, dir) {
    const n = game.players.length;
    const step = dir === 'left' ? 1 : -1;
    for (let i = 1; i <= n; i++) {
      const pos = ((sheriffPos - 1 + step * i) % n + n) % n + 1;
      const p = game.players.find(x => x.position === pos);
      if (p && p.alive) return game.players.indexOf(p);
    }
    return -1;
  }
  async function resolveSheriffBadgeOnDeath(session, dead, reason = 'death') {
    if (!game || !dead) return;
    if (game.sheriffPos !== dead.position || game.sheriffBadgeTorn) return;
    const stage = game.sheriffStage || 'done';
    if (stage === 'signup' || stage === 'speech' || stage === 'withdraw' || stage === 'vote') return; // 竞选期阶段暂不处理
    const alive = game.players.filter(p => p.alive && p.position !== dead.position);
    if (!alive.length) { game.sheriffPos = null; game.sheriffBadgeTorn = true; return; }
    const reasonText = reason === 'fool' ? '翻牌后仍存活' : (reason === 'wwk' ? '自爆' : (reason === 'wwkTarget' ? '被白狼王带走' : '出局'));
    addJudgeLog('🚨 ' + dead.name + '（' + dead.position + '号位）作为警长' + reasonText + '，需要决定把警徽移交给谁，或者' + (reason === 'fool' ? '放弃警徽' : '撕毁警徽') + '。', true);
    let decision = null;
    if (dead.isUser) {
      const choice = await sheriffUserBadgePick(session, dead, reason);
      if (!isSessionValid(session)) return;
      decision = choice;
    } else {
      decision = await aiSheriffBadgeDecide(session, dead, 1, reason);
      if (!isSessionValid(session)) return;
    }
    if (decision && decision.tear) {
      game.sheriffPos = null;
      game.sheriffBadgeTorn = true;
      addJudgeLog('🚨 ' + (reason === 'fool' ? '警徽被放弃' : '警徽被撕毁') + '，本局不再有警长；之后按普通规则（存活最小号位）决定发言顺序。', true);
    } else if (decision && decision.pos) {
      const t = game.players.find(p => p.position === decision.pos && p.alive && p.position !== dead.position);
      if (t) {
        game.sheriffPos = t.position;
        game.sheriffDirection = '';
        game.sheriffDirectionDay = 0;
        addJudgeLog('🚨 警徽移交给了 ' + t.name + '（' + t.position + '号位），TA 成为新的警长！🎖️', true);
      } else {
        game.sheriffPos = null;
        game.sheriffBadgeTorn = true;
        addJudgeLog('🚨 由于没有合适的移交对象，' + (reason === 'fool' ? '警徽被放弃' : '警徽被撕毁') + '，本局不再有警长。', true);
      }
    } else {
      game.sheriffPos = null;
      game.sheriffBadgeTorn = true;
      addJudgeLog('🚨 ' + (reason === 'fool' ? '警徽被放弃' : '警徽被撕毁') + '，本局不再有警长。', true);
    }
    saveGameRecord();
    renderGameUI();
  }
  function sheriffUserBadgePick(session, sheriff, reason = 'death') {
