    }
    evaluateBoard(color) {
      if (this.winner === color) return 100000;
      if (this.winner === 'draw') return 0;
      if (this.winner && this.winner !== color) return -100000;
      const pieceValues = { P: 100, N: 320, B: 330, R: 500, Q: 900, K: 0 };
      const oppColor = this.enemyColor(color);
      const pstP = [0,0,0,0,0,0,0,0, 50,50,50,50,50,50,50,50, 10,10,20,30,30,20,10,10, 5,5,10,25,25,10,5,5, 0,0,0,20,20,0,0,0, 5,-5,-10,0,0,-10,-5,5, 5,10,10,-20,-20,10,10,5, 0,0,0,0,0,0,0,0];
      const pstN = [-50,-40,-30,-30,-30,-30,-40,-50, -40,-20,0,0,0,0,-20,-40, -30,0,10,15,15,10,0,-30, -30,5,15,20,20,15,5,-30, -30,0,15,20,20,15,0,-30, -30,5,10,15,15,10,5,-30, -40,-20,0,5,5,0,-20,-40, -50,-40,-30,-30,-30,-30,-40,-50];
      // 快速档只算子力分（关掉 PST 位置表）：会走棋但"走得难看"，新手感明显
      const usePST = this.usePST !== false;
      let score = 0;
      for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) {
        const p = this.board[r][c];
        if (!p) continue;
        const type = p.toUpperCase();
        const isMy = this.sameColor(p, color);
        let val = pieceValues[type] || 0;
        if (usePST && type === 'P') {
          val += this.isWhite(p) ? pstP[r * 8 + c] : pstP[(7 - r) * 8 + c];
        } else if (usePST && type === 'N') {
          val += this.isWhite(p) ? pstN[r * 8 + c] : pstN[(7 - r) * 8 + c];
        } else if (type === 'K') {
          val = -20;
        }
        score += isMy ? val : -val;
      }
      if (this.isInCheck(color)) score -= 500;
      if (this.isInCheck(oppColor)) score += 500;
      // 强力档追加：兵型（叠兵/孤兵）、通路兵、国王安全
      // 注意：这里绝不能改用 getAllMoves 算"机动性"——evaluateBoard 在每个叶子与静态搜索节点都会跑，
      // 而 getAllMoves 内部对每个伪合法走法都要做 isKingSafeAfter（落子+全盘 isInCheck+撤销），
      // 单次约 6 万次基本操作；一旦放进评估函数，强力档会在根节点第 2 个走法就被 maxTime 截断，
      // 实际退化成"只看排序第一手"，比标准档更弱。机动性若需要，请在根节点算一次。
      if (usePST && this.strongEval) {
        score += this.evaluateStructure(color);
        score -= this.evaluateStructure(oppColor);
        // 国王安全：己方王前兵被推进/缺失时扣分（开放线惩罚）
        score += this.kingSafetyScore(color);
        score -= this.kingSafetyScore(oppColor);
      }
      return score;
    }
    // 兵型评估：通路兵加分、叠兵减分、孤兵减分（强力档使用）
    evaluateStructure(color) {
      const isMine = p => p && this.sameColor(p, color);
      const pawnFiles = [0, 0, 0, 0, 0, 0, 0, 0];
      const pawnPos = [];
      for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) {
        const p = this.board[r][c];
        if (p && p.toUpperCase() === 'P' && isMine(p)) { pawnFiles[c]++; pawnPos.push({ r, c, white: this.isWhite(p) }); }
      }
      const oppPawnFiles = [0, 0, 0, 0, 0, 0, 0, 0];
      for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) {
        const p = this.board[r][c];
        if (p && p.toUpperCase() === 'P' && !isMine(p)) oppPawnFiles[c]++;
      }
      let s = 0;
      for (const f of pawnFiles) {
        if (f > 1) s -= 18 * (f - 1); // 叠兵
      }
      for (let c = 0; c < 8; c++) {
        if (pawnFiles[c] === 1 && (c === 0 || pawnFiles[c - 1] === 0) && (c === 7 || pawnFiles[c + 1] === 0)) s -= 14; // 孤兵
      }
      for (const pp of pawnPos) {
        let blocked = false;
        for (let dc = -1; dc <= 1; dc++) {
          const fc = pp.c + dc;
          if (fc < 0 || fc > 7) continue;
          if (oppPawnFiles[fc] > 0) {
            const oppIsAhead = this.hasOppPawnAhead(fc, pp.r, pp.white);
            if (oppIsAhead) blocked = true;
          }
        }
        if (!blocked) {
          const advance = pp.white ? (6 - pp.r) : (pp.r - 1); // 越靠对方底线越大
          s += Math.max(0, advance) * 12; // 通路兵：越接近升变越值钱
        }
      }
      return s;
    }
    hasOppPawnAhead(file, row, isWhitePawn) {
      for (let r = 0; r < 8; r++) {
        const p = this.board[r][file];
        if (!p || p.toUpperCase() !== 'P') continue;
        if (isWhitePawn && this.isWhite(p)) continue;
        if (!isWhitePawn && !this.isWhite(p)) continue;
        if (isWhitePawn ? (r < row) : (r > row)) return true;
      }
      return false;
    }
    // 国王安全：王前 3 格兵是否在原位 / 王是否已失去易位保护
    kingSafetyScore(color) {
      let score = 0;
      for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) {
        const p = this.board[r][c];
        if (!p || p.toUpperCase() !== 'K' || !this.sameColor(p, color)) continue;
        const white = this.isWhite(p);
        const dir = white ? -1 : 1; // 王前方向
        for (let dc = -1; dc <= 1; dc++) {
          const cc = c + dc;
          const rr = r + dir;
          if (cc < 0 || cc > 7 || rr < 0 || rr > 7) continue;
          const q = this.board[rr][cc];
          if (q && q.toUpperCase() === 'P' && this.sameColor(q, color)) score += 12;
          else score -= 10;
        }
      }
      return score;
    }
    alphabeta(depth, alpha, beta, isMaximizing, color, startTime, maxTime) {
      if (startTime != null && maxTime != null && Date.now() - startTime > maxTime) { this.searchAborted = true; return this.evaluateBoard(color); }
      const origAlpha = alpha, origBeta = beta;
      const hash = this.getBoardHash();
      const ttEntry = this.tt.get(hash);
      if (ttEntry && ttEntry.depth >= depth) {
        if (ttEntry.flag === 'exact') return ttEntry.score;
        if (ttEntry.flag === 'lower') alpha = Math.max(alpha, ttEntry.score);
        if (ttEntry.flag === 'upper') beta = Math.min(beta, ttEntry.score);
        if (alpha >= beta) return ttEntry.score;
      }
      if (this.winner) return this.evaluateBoard(color);
      if (depth === 0) return this.quiescence(alpha, beta, color, startTime, maxTime, this.qdepth || 6);

      const currentTurn = isMaximizing ? color : this.enemyColor(color);
      const rawMoves = this.getAllMoves(currentTurn);
      if (!rawMoves.length) {
        if (this.isInCheck(currentTurn)) return currentTurn === color ? -99990 : 99990;
        return 0; // 逼和
      }
      const moves = this.orderMoves(rawMoves, depth);
      let bestMove = moves[0];

      if (isMaximizing) {
        let maxEval = -Infinity;
        for (const m of moves) {
          this.executeMove(m);
          const evalVal = this.alphabeta(depth - 1, alpha, beta, false, color, startTime, maxTime);
          this.undo();
          if (evalVal > maxEval) { maxEval = evalVal; bestMove = m; }
          alpha = Math.max(alpha, evalVal);
          if (beta <= alpha) {
            if (!this.killerMoves[depth]) this.killerMoves[depth] = [];
            this.killerMoves[depth].unshift(m);
            if (this.killerMoves[depth].length > 2) this.killerMoves[depth].pop();
            break;
          }
        }
        // 边界标记必须用"进入函数时的原始窗口"判断：alpha/beta 在循环里已被更新，
        // 用更新后的值判断会让最大化分支恒为 upper、最小化分支恒为 lower，永远存不到 exact。
        const flag = maxEval <= origAlpha ? 'upper' : maxEval >= origBeta ? 'lower' : 'exact';
        boardTTStore(this, hash, depth, maxEval, bestMove, flag);
        return maxEval;
      } else {
        let minEval = Infinity;
        for (const m of moves) {
          this.executeMove(m);
          const evalVal = this.alphabeta(depth - 1, alpha, beta, true, color, startTime, maxTime);
          this.undo();
          if (evalVal < minEval) { minEval = evalVal; bestMove = m; }
          beta = Math.min(beta, evalVal);
          if (beta <= alpha) {
            if (!this.killerMoves[depth]) this.killerMoves[depth] = [];
            this.killerMoves[depth].unshift(m);
            if (this.killerMoves[depth].length > 2) this.killerMoves[depth].pop();
            break;
          }
        }
        const flag = minEval <= origAlpha ? 'upper' : minEval >= origBeta ? 'lower' : 'exact';
        boardTTStore(this, hash, depth, minEval, bestMove, flag);
        return minEval;
      }
    }
    quiescence(alpha, beta, color, startTime, maxTime, qdepth = 6) {
      if (startTime != null && maxTime != null && Date.now() - startTime > maxTime) return this.evaluateBoard(color);
      if (qdepth <= 0) return this.evaluateBoard(color);
      const sideToMove = this.turn;
      const standPat = this.evaluateBoard(color);
      if (sideToMove === color) {
        if (standPat >= beta) return beta;
