    }
    noDestination(m) {
      const t = m.piece.toUpperCase();
      const color = this.colorOf(m.piece);
      const lastRank = color === 'S' ? 0 : 8;
      const secondLast = color === 'S' ? 1 : 7;
      if (t === 'P' || t === 'L') return m.toR === lastRank;
      if (t === 'N') return m.toR === lastRank || m.toR === secondLast;
