      startNewBoardGame('gomoku');
      return;
    }
    if (act === 'start-game-xiangqi') {
      if (resumeBoardGameIfSaved('xiangqi')) return;
      startNewBoardGame('xiangqi');
      return;
    }
    if (act === 'start-game-jungle') {
      if (resumeBoardGameIfSaved('jungle')) return;
      startNewBoardGame('jungle');
      return;
    }
    if (act === 'start-game-chess') {
      if (resumeBoardGameIfSaved('chess')) return;
