    if (act === 'start-game-shogi') {
      if (resumeBoardGameIfSaved('shogi')) return;
      startNewBoardGame('shogi');
      return;
    }
    if (act === 'start-game-battleship') {
      if (resumeBoardGameIfSaved('battleship')) return;
      startNewBoardGame('battleship');
      return;
    }
    if (act === 'bs-start') {
      bsStartBattle();
      return;
    }
    if (act === 'start-game-go') {
      if (resumeBoardGameIfSaved('go')) return;
      startNewBoardGame('go');
      return;
    }
    if (act === 'start-game-luzhanqi') {
      if (resumeBoardGameIfSaved('luzhanqi')) return;
      startNewBoardGame('luzhanqi');
      return;
    }
    if (act === 'start-game-othello') {
      if (resumeBoardGameIfSaved('othello')) return;
      startNewBoardGame('othello');
      return;
    }
    if (act === 'lzq-open') { lzqStartBattle('open'); return; }
    if (act === 'lzq-dark') { lzqStartBattle('dark'); return; }
    if (act === 'lzq-back-lobby') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      saveBoardGameState(); // 布阵中途返回：保留布阵进度，可从大厅【🔖 继续对局】接着布阵（布局槽里的布局仍然保留）
      bsClearTurnTimer();
      if (boardGame) { boardGame.gameType = null; boardGame.engine = null; boardGame.lzqSelectedPiece = null; }
      renderBoardLobby();
      if (findSavedBoardGame('luzhanqi')) showToast('💾 布阵进度已保存：大厅点【军棋】开局可接着布阵', null, 3600);
      return;
    }
    if (act === 'lzq-save-layout') { lzqSaveLayout(parseInt(target && target.dataset ? target.dataset.lzqSlot : '0', 10) || 0); return; }
    if (act === 'lzq-rename-layout') { lzqRenameLayout(parseInt(target && target.dataset ? target.dataset.lzqSlot : '0', 10) || 0); return; }
    if (act === 'lzq-load-layout') { lzqLoadLayout(parseInt(target && target.dataset ? target.dataset.lzqSlot : '0', 10) || 0); return; }
    if (act === 'go-pass') {
      goUserPass();
      return;
    }
    if (act === 'go-resign') {
      goUserResign();
      return;
    }
    if (act === 'resume-saved-game') {
      resumeSavedBoardGame();
      return;
    }
    if (act === 'clear-saved-game') {
      clearSavedBoardGame();
      renderBoardLobby();
      return;
    }
    if (act === 'exit-to-lobby') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      boardGame.isReviewingDefeat = false;
      // 返回对弈大厅：保存当前对局进度，之后可从大厅【🔖 继续对局】断点续玩；已结束的对局会自动清档
      saveBoardGameState();
      bsClearTurnTimer(); // 清掉挂起的 AI 回合/结算回调，避免 engine 置空后报错
      const exitSavedType = boardGame ? boardGame.gameType : null;
      if (boardGame) {
        boardGame.gameType = null;
        boardGame.engine = null;
      }
      renderBoardLobby();
      if (exitSavedType && findSavedBoardGame(exitSavedType)) showToast('💾 对局进度已保存：大厅点该棋类【开局】即可回到进度', null, 3600);
      return;
    }
    if (act === 'quit-board-game') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      boardGame.isReviewingDefeat = false;
      const quitType = boardGame ? boardGame.gameType : null;
      if (quitType) clearSavedBoardGame(quitType); // 退出＝结束本局：清掉该棋类的进行中存档（返回←才是保留进度）
      bsClearTurnTimer(); // 清掉挂起的 AI 回合/结算回调，避免 engine 置空后报错
      if (boardGame) {
        boardGame.gameType = null;
        boardGame.engine = null;
      }
      renderBoardLobby();
      showToast('🚪 已结束本局，进度已清除', null, 2800);
      return;
    }
    if (act === 'rematch') {
      boardGame.isReviewingDefeat = false;
      startNewBoardGame(boardGame.gameType);
      return;
    }
    if (act === 'send-user-chat') {
      handleUserChatSend();
      return;
    }
        if (act === 'review-defeat') {
      const modal = sheet?.querySelector('.board-gameover-overlay');
      if (modal) modal.remove();
      boardGame.isReviewingDefeat = true;
      boardGame.resultRecorded = false;
      renderBoardGameUI();
      showToast('⏪ 已返回失败环节，点击下方【刚刚的不算】即可直接撤回重走！');
      return;
    }
    if (act === 'undo-move') { // 刚刚的不算 (悔棋 / 失败回放撤回重走)
      if (!boardGame.engine) return;
      if (boardAITimer) { clearTimeout(boardAITimer); boardAITimer = null; }
      const engine = boardGame.engine;
      boardGame.isReviewingDefeat = false;
      engine.undo();
      if (engine.history.length > 0) {
        engine.undo();
      }
      boardGame.selectedPos = null;
      boardGame.validMoves = [];
      boardGame.selectedDropPiece = null;
      boardGame.validDrops = [];
      boardGame.pendingPromotion = null;
      boardGame.isThinking = false;
      boardGame.lastSpeech = '好啦好啦，这次就算你悔棋一步，重新走吧~';
      saveBoardGameState();
      renderBoardGameUI();

      // 若一路撤销回到开局且 AI 先手，需补上 AI 的先行一手
      const type = boardGame.gameType;
      const aiTurn = type === 'gomoku' ? 2 : getBoardAIColor();
      if (!engine.winner && engine.turn === aiTurn) {
        scheduleBoardAIMove(type, 450);
      }
      return;
    }
    if (act === 'flip-table') {
      boardGame.isReviewingDefeat = false; // 我要掀桌子 (重开)
      if (!boardGame.engine) return;
      const type = boardGame.gameType;
      showToast('💥 啪！桌子被你掀翻了！重新摆好棋盘！', () => {
        startNewBoardGame(type);
      });
      return;
    }
  }


  // ============================================================
  // ========== 谁是卧底 系统 (1卧底 5平民 · 词语描述 · 投票) ==========
  // ============================================================

  // ========== 谁是卧底 本地存储与断点恢复 ==========
  const SPY_SAVE_GAME_KEY = 'werewolf_extension_spy_saved_game';

  function cleanSpyWord(w) {
    if (!w || typeof w !== 'string') return '';
    // 先剥掉 Markdown / 排版符号，再清掉残留的引导标点（LLM 常输出 "**平民词**：牛肉面" 这类脏文本）
    return w
      .replace(/[*_`~]/g, '')
      .replace(/["'“”‘’《》【】「」\[\]（）()]/g, '')
      .replace(/^[：:＝=、,，。.；;！!？?\s]+/g, '')
      .replace(/[：:＝=、,，。.；;！!？?\s]+$/g, '')
      .trim();
  }
  // 从主持人输出里抓词：允许 Markdown 加粗、中英文冒号、书名号/方括号包裹等写法
  function extractSpyWord(res, label) {
    const cleaned = String(res || '').replace(/[*_`~]/g, '');
    const re = new RegExp(label + '\\s*[：:＝=]?\\s*[【「\\[《]?\\s*([^\\n\\r，,；;。】」\\]》]+?)\\s*[】」\\]》]?\\s*(?=[\\n\\r]|$)');
    const m = cleaned.match(re);
    if (!m) return '';
    return cleanSpyWord(m[1]);
  }

  function saveSpyGameRecord() {
    if (!spyGame || spyIsGameOver || spyGame.phase === 'end' || spyGame.phase === 'idle') {
      clearSavedSpyGame();
      return;
    }
    try {
      const state = {
        session: spyGame.session,
        players: spyGame.players,
        phase: spyGame.phase,
        round: spyGame.round,
        currentSpeaker: spyGame.currentSpeaker,
        winner: spyGame.winner,
        civilianWord: spyGame.civilianWord,
        spyWord: spyGame.spyWord,
        userIndex: spyGame.userIndex,
        history: spyGame.history,
        historyEntries: spyGame.historyEntries,
        replay: spyGame.replay,
        votes: spyGame.votes
      };
      localStorage.setItem(SPY_SAVE_GAME_KEY, JSON.stringify(state));
    } catch (e) { /* ignore */ }
  }

  function clearSavedSpyGame() {
    try {
      localStorage.removeItem(SPY_SAVE_GAME_KEY);
    } catch (e) { /* ignore */ }
  }

  function hasSavedSpyGame() {
    if (spyGame && !spyIsGameOver && (spyGame.phase === 'words' || spyGame.phase === 'speak' || spyGame.phase === 'vote')) {
      return true;
    }
    try {
      const raw = localStorage.getItem(SPY_SAVE_GAME_KEY);
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      return parsed && parsed.players && parsed.players.length === 6 && (parsed.phase === 'words' || parsed.phase === 'speak' || parsed.phase === 'vote');
    } catch (e) {
      return false;
    }
  }

  function resumeSavedSpyGame() {
    try {
      if (spyGame && !spyIsGameOver) {
        // 本会话已有进行中的对局：只重绘界面并恢复当前阶段（防止重复驱动流程导致跳过发言者）
        renderSpyGameUI();
        resumeCurrentSpyPhase();
        return;
      }
      if (!spyGame || spyIsGameOver) {
        const raw = localStorage.getItem(SPY_SAVE_GAME_KEY);
        if (!raw) { renderSpyBoard(); return; }
        const data = JSON.parse(raw);
        spySessionCounter++;
        const restoredPlayers = data.players.map(p => ({
          ...p,
          avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name))
        }));
        spyGame = {
          session: spySessionCounter,
          players: restoredPlayers,
          phase: data.phase,
          round: data.round || 1,
          currentSpeaker: data.currentSpeaker || 0,
          winner: data.winner,
          civilianWord: data.civilianWord,
          spyWord: data.spyWord,
          userIndex: data.userIndex,
          history: data.history || [],
          historyEntries: data.historyEntries || [],
          replay: data.replay || [],
          pickMode: null,
          pick: { idx: null },
          votes: data.votes || {}
        };
        spyIsGameOver = false;
      }
      renderSpyGameUI();
      resumeCurrentSpyPhase();
    } catch (e) {
      console.error('[谁是卧底恢复对局失败]', e);
      clearSavedSpyGame();
      renderSpyBoard();
    }
  }

  function resumeCurrentSpyPhase() {
    if (!spyGame || spyIsGameOver) return;
    if (spyGame.phase === 'words') {
      if (spyGame.civilianWord && spyGame.spyWord) {
        spyGame.phase = 'speak';
        startSpySpeaking();
      } else {
        startSpyGame();
      }
    } else if (spyGame.phase === 'speak') {
      runCurrentSpySpeaker();
    } else if (spyGame.phase === 'vote') {
      startSpyVote();
    }
  }

