        userIndex: players.findIndex(p => p.isUser),
        history: [],
        historyEntries: [],
        replay: [],
        pickMode: null,
        pick: { idx: null },
        votes: {}
      };
      spyIsGameOver = false;
      spyReplayLogs = [];
      ov.remove();
      renderSpyPositions();
    });
