  function parseAndAssignSpyWords(res) {
    let civWord = '';
    let spyWord = '';

    civWord = extractSpyWord(res, '平民词');
    spyWord = extractSpyWord(res, '卧底词');

    const playerWords = {};
    spyGame.players.forEach(p => {
      const escapedName = p.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const reg = new RegExp(`(?:${p.position}\\s*号位|${escapedName})[^\\n，,；;。]*?[为是:：=]\\s*[【「\\[]?([^\\n\\r，,；;。】\\]]+)[】\\]]?`, 'i');
      const m = String(res || '').replace(/[*_`~]/g, '').match(reg);
      if (m) {
        playerWords[p.position] = cleanSpyWord(m[1]);
      }
    });

    const assignedList = Object.values(playerWords);
    if ((!civWord || !spyWord) && assignedList.length >= 2) {
      const counts = {};
      assignedList.forEach(w => counts[w] = (counts[w] || 0) + 1);
      const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
      if (sorted.length >= 2) {
        if (!civWord) civWord = cleanSpyWord(sorted[0][0]);
        if (!spyWord) spyWord = cleanSpyWord(sorted[sorted.length - 1][0]);
      }
    }

    if (!civWord || !spyWord || civWord === spyWord) {
      const wordPairs = [
        ['牛肉面', '拉面'],
        ['婚纱', '头纱'],
        ['粽子', '汤圆'],
        ['吉他', '尤克里里'],
        ['麦克风', '话筒'],
        ['口红', '唇膏'],
        ['风扇', '空调'],
        ['眉毛', '睫毛'],
        ['纸巾', '手帕'],
        ['自行车', '电动车']
      ];
      const pair = wordPairs[Math.floor(Math.random() * wordPairs.length)];
      civWord = pair[0];
      spyWord = pair[1];
    }

    civWord = cleanSpyWord(civWord);
    spyWord = cleanSpyWord(spyWord);

    spyGame.civilianWord = civWord;
    spyGame.spyWord = spyWord;

    // 卧底身份由代码随机指定，不再依赖 LLM 输出"XX为YYY"的分配语句（LLM 的分配本来就不可靠，
    // 且不同玩家可能拿到矛盾词）。LLM 只负责生成词对，身份与发词由本地代码决定。
    const spyPos = spyGame.players[Math.floor(Math.random() * spyGame.players.length)].position;

    spyGame.players.forEach(p => {
      p.isSpy = (p.position === spyPos);
      p.role = p.isSpy ? '卧底' : '平民';
      p.word = p.isSpy ? spyWord : civWord;
    });

    const user = spyGame.players[spyGame.userIndex];

    addSpyHiddenThought(`[主持人分词] 平民词:【${civWord}】；卧底词:【${spyWord}】。卧底是: ${spyPos}号位 ${spyGame.players.find(p => p.isSpy)?.name}`, null);

    addSpyLog(`📢 【谁是卧底】游戏正式开始！本局为6人局（1卧底、5平民）。`, true);
    addSpyLog(`🤫 主持人已将词语悄悄私聊分发给每位玩家。拿到词后，请按顺序轮流用一句话描述自己的词语。`, true);

    addSpyLog(`🔑 你的词语是：【${user.word}】`, false, null, '#FBBF24');

    renderSpyGameUI();

    spyGame.phase = 'speak';
    spyGame.round = 1;
    saveSpyGameRecord();
    startSpySpeaking();
  }

  function startSpySpeaking() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session)) return;

    spyGame.phase = 'speak';
    saveSpyGameRecord();
    spyGame.players.forEach(p => {
      p.hasSpoken = false;
      p.votedFor = null;
    });

    spyGame.currentSpeaker = 0;
    while (spyGame.currentSpeaker < spyGame.players.length && !spyGame.players[spyGame.currentSpeaker].alive) {
      spyGame.currentSpeaker++;
    }

    if (spyGame.currentSpeaker >= spyGame.players.length) {
      startSpyVote();
      return;
    }

    renderSpyGameUI();
    addSpyLog(`💬 从 ${spyGame.players[spyGame.currentSpeaker].position}号位 ${spyGame.players[spyGame.currentSpeaker].name} 开始发言描述`, true);
    runCurrentSpySpeaker();
  }

  function runCurrentSpySpeaker() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session) || spyGame.phase !== 'speak') return;

    const current = spyGame.players[spyGame.currentSpeaker];
    if (!current || !current.alive) {
      nextSpySpeaker();
      return;
    }
    // 每次轮到发言者时刷新发言令牌：过期/重复的生成回调不再推进发言顺序，防止跳过下一位发言者
    const spySpeakToken = (spyGame.speakToken = (spyGame.speakToken || 0) + 1);

    if (current.isUser) {
      setSpyControlArea(`
        <div id="spy-speak-box" style="background:rgba(245,158,11,0.1);padding:6px 10px;border-radius:8px;border:1px solid rgba(245,158,11,0.3);margin:4px 0;">
          <div style="color:#FBBF24;font-size:13px;font-weight:bold;margin-bottom:4px;">🔑 你的词语是：${escapeHtml(current.word)}</div>
          <div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:6px;">轮到你的发言回合，请用一句话描述（严禁透露词语本身及字数）：</div>
          <div style="display:flex;gap:4px;">
            <input id="spy-speak-input" class="ubp-fieldinput" type="text" placeholder="你的词语是【${escapeHtml(current.word)}】，请输入描述..." style="flex:1;min-width:0;">
            <button data-spy-act="speak" class="ubp-btn primary" style="padding:0 12px;background:#F59E0B;border:none;font-weight:600;">发言</button>
            <button data-spy-act="speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button>
          </div>
        </div>
      `);
      const input = sheet.querySelector('#spy-speak-input');
      if (input) {
        input.focus();
        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            handleSpyUserSpeak();
          }
        });
      }
    } else {
      setSpyControlArea(`<div style="text-align:center;padding:6px;color:#F59E0B;">${current.name}（${current.position}号位）正在构思描述发言...</div>`);
      generateSpyAISpeech(current, () => {
        if (!isSpySessionValid(session) || spyGame.phase !== 'speak') return;
        if (spyGame.speakToken !== spySpeakToken) return; // 过期/重复回调：已被新一轮发言取代
        if (current.hasSpoken) return;
        current.hasSpoken = true;
        nextSpySpeaker();
      });
    }
  }

  function nextSpySpeaker() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session) || spyGame.phase !== 'speak') return;

    let next = spyGame.currentSpeaker + 1;
    while (next < spyGame.players.length && (!spyGame.players[next].alive || spyGame.players[next].hasSpoken)) {
      next++;
    }

    if (next >= spyGame.players.length) {
      addSpyLog(`📢 全员描述发言完毕，进入投票放逐环节！`, true);
      startSpyVote();
    } else {
      spyGame.currentSpeaker = next;
      runCurrentSpySpeaker();
    }
  }

  function handleSpyUserSpeak() {
    const input = sheet.querySelector('#spy-speak-input');
    if (!input) return;
    if (!spyGame || spyGame.phase !== 'speak') return;
    const current = spyGame.players[spyGame.currentSpeaker];
    if (!current || !current.isUser || current.hasSpoken) return; // 防重复提交（回车+点击等）导致跳过下一位发言者
    const text = input.value.trim();
    if (!text) return;
    addSpyLog(`🗣️ ${current.name}（${current.position}号位）: <speech>${text}</speech>`, true, current.position);
    current.hasSpoken = true;
    input.value = '';
    setSpyControlArea('');
    nextSpySpeaker();
  }

  function handleSpyUserSpeakSkip() {
    if (!spyGame || spyGame.phase !== 'speak') return;
    const current = spyGame.players[spyGame.currentSpeaker];
    if (!current || !current.isUser || current.hasSpoken) return; // 防双击：第二次点击时下一位是AI，直接忽略
    addSpyLog(`🗣️ ${current.name}（${current.position}号位）: <speech>这轮我先过，听听大家怎么说。</speech>`, true, current.position);
    current.hasSpoken = true;
    saveSpyGameRecord();
    setSpyControlArea('');
    nextSpySpeaker();
  }

  function getSpyPlayerPersonalityPrompt(player) {
    if (!player || player.isUser) return '';
    const prof = getCharacterProfile(player.name);
    let info = `\n【你扮演的角色生平与性格底色（必须完全融入此人设进行言行）】：\n- 姓名：${player.name}\n`;
    if (prof) {
      if (prof.identity) info += `- 身份背景：${prof.identity}\n`;
      if (prof.personality) info += `- 性格特质：${prof.personality}\n`;
      if (prof.languageStyle) info += `- 说话习惯与语言口癖：${prof.languageStyle}\n`;
      if (prof.attitude) info += `- 【对主角（玩家本人）的态度与关系】：${prof.attitude}\n`;
      if (prof.brief) info += `- 人物简介：${prof.brief}\n`;
    } else {
      info += `- 基础设定：普通角色，以自然真人风格发挥。\n`;
    }
    if (spyGame?.players) {
      // 谁是卧底不做难度分档：始终提供本局人物关系
      info += getInterPersonalContext(player, spyGame.players);
    }
    return info;
  }

  function generateSpyAISpeech(player, callback) {
    const session = spyGame?.session;
    if (!isSpySessionValid(session)) return;

    const config = loadConfig();
    const persona = getSpyPlayerPersonalityPrompt(player);

    // 谁是卧底不做难度分档：始终提供全部历史发言
    const allSpeeches = (spyGame.historyEntries || [])
      .filter(e => e.type === 'public' && e.text.includes('<speech>'))
      .map(e => e.text.replace(/<\/?speech>/g, ''));
    const roundSpeeches = allSpeeches.join('\n');

    const prompt = `【这是谁是卧底桌游小剧场】
你正在扮演：${player.position}号位 ${player.name}。
当前进行到：第${spyGame.round}轮公开发言描述。
你的词语是：【${player.word}】（注意：请深深刻在心里，绝对不能在发言中直接说出这个词或透露字数！）。

${persona}

【前面所有已经发言玩家的公开发言描述如下】：
${roundSpeeches ? roundSpeeches : '（你是本轮第一个发言的玩家，前面暂无发言）'}

【公开发言描述核心硬性要求】：
1. 【游戏本质认知】：这是朋友间的《谁是卧底》聚会桌游小剧场！发言要有熟人间互动感，自然流露你角色的性格口吻、说话风格与口癖。
2. 【严格保密】：严禁直接说出词语【${player.word}】本身，严禁透露词语字数，绝不能过于直白暴露词汇！
3. 【必须给出全新不同描述】：你已经知道了上面所有玩家说了什么，你【必须生成与上面所有人截然不同的描述】，从不同的用途、特征、感受、场景等角度进行一句话描述！
4. 【格式铁律】：必须包含<thinking>与<speech>两部分：
   - 在<thinking>中分析你的词语特性，并对比上面玩家的发言，构思一个完全不同的描述切入点；
   - 在<speech>中以第一人称角色口吻说出你的一句话描述（20~60字，口语化，语意完整收尾，严禁包含动作描写或引号）。

严格输出格式：
<thinking>
思考你的词语与前面玩家发言的差异，规划不一样的描述切入点
</thinking>
<speech>
真正说出口的一句话描述
</speech>`;

    apiChat([
      { role: 'system', content: '你是谁是卧底桌游玩家。严格忠于角色性格，根据自己的词语给出一句话描述，绝对不能说出词语本身，且必须与前置位玩家的描述角度截然不同。' },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 2000, timeout: 65000 }).then(res => {
      if (!isSpySessionValid(session)) return;
      let thought = '';
      let speech = '';

      const mThought = res.match(/<thinking>([\s\S]*?)<\/thinking>/i);
      if (mThought) {
        thought = mThought[1].trim();
      } else {
        const speechIdx = res.indexOf('<speech>');
        if (speechIdx > 0) {
          thought = res.slice(0, speechIdx).replace(/<[^>]+>/g, '').trim();
        }
      }

      const mSpeech = res.match(/<speech>([\s\S]*?)(?:<\/speech>|$)/i);
      if (mSpeech) {
        speech = mSpeech[1].trim();
      } else {
        speech = res.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
      }

      speech = speech.replace(/【思考原因】/g, '').replace(/【公开发言】/g, '').replace(/<\/?thinking>/gi, '').replace(/<\/?speech>/gi, '').trim();

      if (!speech) speech = '嗯……这个东西大家生活里挺常见的，后置位继续听听看。';
      if (!thought) thought = `我拿到的词语是${player.word}，我需要从一个不易被怀疑、又不同于其他人的角度做描述。`;

      addSpyHiddenThought(thought, player.position);
      addSpyLog(`🗣️ ${player.name}（${player.position}号位）: <speech>${speech}</speech>`, true, player.position);
      callback();
    }).catch(err => {
      if (!isSpySessionValid(session)) return;
      showToast(`AI描述失败: ${err.message}，点击重试`, () => generateSpyAISpeech(player, callback));
    });
  }

  function startSpyVote() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session)) return;

    spyGame.phase = 'vote';
    saveSpyGameRecord();
    spyGame.pickMode = null;
    spyGame.pick = { idx: null };

    const statusEl = sheet?.querySelector('#spy-game-status-text');
    if (statusEl) statusEl.textContent = `🕵️ 谁是卧底 · 第 ${spyGame.round} 轮 · 🗳️ 投票`;

    const user = spyGame.players[spyGame.userIndex];
    if (user && user.alive) {
      addSpyLog('🗳️ 发言完毕，进入投票环节！请点击上方存活玩家头像投票，或点击下方弃票', false);
      spyGame.pickMode = 'vote';
      renderSpyGameUI();
      setSpyControlArea(`
        <div style="background:var(--ubp-card-2);padding:8px 10px;border-radius:8px;text-align:center;">
          <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:6px;">请点击上方头像选择你要投票出局的卧底：</div>
          <button data-spy-act="vote-skip" class="ubp-btn" style="padding:4px 16px;font-size:12px;">弃票</button>
        </div>
      `);
    } else {
      simulateSpyAIVotes();
    }
  }

  function handleSpyPickAvatar(targetEl) {
    if (!spyGame || spyGame.phase !== 'vote' || !spyGame.pickMode) return;
    const user = spyGame.players[spyGame.userIndex];
    if (!user || !user.alive) return;
    const idx = parseInt(targetEl.dataset.targetIdx);
    const targetPlayer = spyGame.players[idx];
    if (!targetPlayer || !targetPlayer.alive) return;

    spyGame.pick.idx = (spyGame.pick.idx === idx) ? null : idx;
    renderSpyGameUI();
    if (spyGame.pick.idx === null) {
      hideSpyActionPopup();
      return;
    }
    spyShowVotePopup();
  }

