  function handleSpyUserVote() {
    if (!spyGame || spyGame.phase !== 'vote' || spyGame.pickMode !== 'vote') return; // 防重复点击导致重复结算
    const idx = spyGame.pick?.idx;
    if (idx === null || idx === undefined) {
      showToast('请先点击选择投票对象');
      return;
    }
    const user = spyGame.players[spyGame.userIndex];
    if (!user || !user.alive) return;
    user.votedFor = idx;
    saveSpyGameRecord();
    spyGame.pick.idx = null;
    spyGame.pickMode = null;
    hideSpyActionPopup();
    renderSpyGameUI();
    simulateSpyAIVotes();
  }

  function handleSpyUserVoteSkip() {
    if (!spyGame || spyGame.phase !== 'vote' || spyGame.pickMode !== 'vote') return; // 防重复点击导致重复结算
    const user = spyGame.players[spyGame.userIndex];
    if (!user || !user.alive) return;
    user.votedFor = null;
    saveSpyGameRecord();
    spyGame.pick.idx = null;
    spyGame.pickMode = null;
    hideSpyActionPopup();
    renderSpyGameUI();
    simulateSpyAIVotes();
  }

