        const textToSearch = actionBlock ? actionBlock[1] : res;

        if (/弃票|放弃|SKIP/i.test(textToSearch)) {
          isSkip = true;
        }

        const mVote = textToSearch.match(/VOTE[：:]\s*[\[【（(]?\s*(\d{1,2}|[一二三四五六七八九十]{1,3}|弃票|SKIP)\s*号?[\]】）)]?/i) || res.match(/VOTE[：:]\s*[\[【（(]?\s*(\d{1,2}|[一二三四五六七八九十]{1,3}|弃票|SKIP)\s*号?[\]】）)]?/i);
        if (mVote && mVote[1]) {
          const vStr = mVote[1];
          if (vStr === '0' || vStr === '弃票' || vStr.toUpperCase() === 'SKIP') {
            isSkip = true;
          } else {
            targetPos = cnNumMap[vStr] ?? parseInt(vStr) ?? 0;
          }
        }

        if (!isSkip && !targetPos) {
          const voteHint = textToSearch.match(/(?:投给|投票给|放逐|归票|票出|投)\s*[\[【（(]?\s*([1-6一二三四五六])\s*号?/i);
          if (voteHint && voteHint[1]) {
            targetPos = cnNumMap[voteHint[1]] ?? parseInt(voteHint[1]) ?? 0;
          }
        }

        if (isSkip || targetPos === 0) {
          p.votedFor = null;
        } else {
          let target = spyGame.players.find(tp => tp.position === targetPos && tp.alive);
          p.votedFor = target ? spyGame.players.indexOf(target) : null;
        }

        if (!thought || thought.length < 30) {
          if (p.votedFor != null) { // != null 同时盖住 undefined（旧存档可能没有该字段）
            const tPlayer = spyGame.players[p.votedFor];
            thought = `【${p.position}号位 ${p.name} 深度投票思考】：仔细比对全场发言，${tPlayer.position}号位 ${tPlayer.name} 的描述与我的词语【${p.word}】明显有违和感，嫌疑最大。因此，我决定投票给 ${tPlayer.position}号位 ${tPlayer.name}。`;
          } else {
            thought = `【${p.position}号位 ${p.name} 深度投票思考】：当前局势各方描述差距微弱，尚未暴露出绝对破绽，因此我决定本轮选择弃票观望。`;
          }
        }

        addSpyHiddenThought(thought, p.position);
      }).catch(err => {
        if (!isSpySessionValid(session)) return;
        addSpyHiddenThought(`[投票思考超时，权衡局势选择弃票]`, p.position);
        p.votedFor = null;
      });
    });

    Promise.all(votePromises).then(() => {
      if (!isSpySessionValid(session)) return;
      setSpyControlArea('');
      finishSpyVote();
    });
  }

  function finishSpyVote() {
    const session = spyGame?.session;
    if (!isSpySessionValid(session)) return;

    const votes = {};
    spyGame.players.forEach(p => {
      if (!p.alive) return;
      if (p.votedFor !== null && p.votedFor !== undefined) {
        const target = spyGame.players[p.votedFor];
        addSpyLog(`🗳️ ${p.name}（${p.position}号位）投给了 ${target.name}（${target.position}号位）`, true);
        votes[p.votedFor] = (votes[p.votedFor] || 0) + 1;
      } else {
        addSpyLog(`🗳️ ${p.name}（${p.position}号位）选择弃票`, true);
      }
    });

    let maxVotes = 0;
    let maxIndices = [];
    for (const [idxStr, count] of Object.entries(votes)) {
      const idx = parseInt(idxStr);
      if (count > maxVotes) {
        maxVotes = count;
        maxIndices = [idx];
      } else if (count === maxVotes && maxVotes > 0) {
        maxIndices.push(idx);
      }
    }

    if (maxVotes === 0 || maxIndices.length === 0) {
      addSpyLog('⚖️ 本轮无人得票，无人出局，直接进入下一轮描述！', true);
      advanceToNextSpyRound();
      return;
    }

    if (maxIndices.length > 1) {
      const tiedNames = maxIndices.map(i => `${spyGame.players[i].position}号位 ${spyGame.players[i].name}`).join('、');
      addSpyLog(`⚖️ 出现平票！（${tiedNames} 均为 ${maxVotes} 票），无人出局，直接进入下一轮描述！`, true);
      advanceToNextSpyRound();
      return;
    }

        const eliminated = spyGame.players[maxIndices[0]];
    eliminated.alive = false;
    renderSpyGameUI();
    const roleText = eliminated.isSpy ? '卧底' : '平民';
    addSpyLog(`💀 ${eliminated.name}（${eliminated.position}号位）以 ${maxVotes} 票最高票出局！【TA的身份是：${roleText}】`, true);
    saveSpyGameRecord();

    const spy = spyGame.players.find(p => p.isSpy);
    const alivePlayers = spyGame.players.filter(p => p.alive);

    if (!spy.alive) {
      spyGame.winner = '平民阵营';
      endSpyGame();
      return;
    }

    if (alivePlayers.length <= 3 && spy.alive) {
      spyGame.winner = '卧底阵营';
      endSpyGame();
      return;
    }

    advanceToNextSpyRound();
  }

  function advanceToNextSpyRound() {
    spyGame.round++;
    saveSpyGameRecord();
    addSpyLog(`📢 ---------------- 第 ${spyGame.round} 轮 描述开始 ----------------`, true);
    renderSpyGameUI();
    startSpySpeaking();
  }

  function endSpyGame() {
    if (spyIsGameOver) return;
    spyIsGameOver = true;
    clearSavedSpyGame();
    spyGame.phase = 'end';
    spyGame.pickMode = null;
    hideSpyActionPopup();
    renderSpyGameUI();

    addSpyLog(`🏆 游戏结束！【${spyGame.winner}】获得胜利！`, true);
    const spy = spyGame.players.find(p => p.isSpy);
    addSpyLog(`🔎 本局词语揭秘：平民词【${spyGame.civilianWord}】 · 卧底词【${spyGame.spyWord}】（卧底为：${spy ? `${spy.position}号位 ${spy.name}` : '未知'}）`, true);
    spyGame.players.forEach(p => {
      addSpyLog(`  ${p.position}号位 ${p.name}：${p.isSpy ? '【卧底】' : '【平民】'}「${p.word}」（${p.alive ? '存活' : '出局'}）`, true);
    });

    spyReplayLogs = (spyGame.replay || []).slice();
    spyReplayPlayersSnapshot = (spyGame.players || []).map(p => ({
      position: p.position, name: p.name, isUser: !!p.isUser,
      avatar: p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)) || ''
    }));

    // ===== 注入：谁是卧底对局结果 → 世界书绿灯条目 + QQ联动 =====
    try {
      const user = spyGame.players[spyGame.userIndex];
      const isUserWon = (user.isSpy && spyGame.winner === '卧底阵营') || (!user.isSpy && spyGame.winner === '平民阵营');
      const spy = spyGame.players.find(p => p.isSpy);
      const detailLines = spyGame.players.map(p => `${p.position}号位 ${p.name}${p.isUser ? '（主角）' : ''}：${p.isSpy ? '【卧底】' : '【平民】'}「${p.word}」，${p.alive ? '存活' : '出局'}`).join('；');
      onGameFinished({
        gameType: 'spy',
        userWon: isUserWon,
        result: `${spyGame.winner}获胜（主角${isUserWon ? '胜' : '负'}；卧底为 ${spy ? spy.name : '未知'}）`,
        detail: `平民词【${spyGame.civilianWord}】 · 卧底词【${spyGame.spyWord}】；${detailLines}`,
        replay: formatReplayAsText(spyReplayLogs),
        replayRich: { logs: spyReplayLogs, players: spyReplayPlayersSnapshot },
        players: spyGame.players.map(p => ({ name: p.name, isUser: p.isUser, avatar: p.avatar || '' }))
      });
    } catch (e) { /* ignore */ }

    setSpyControlArea(`
      <div style="display:flex;gap:8px;">
        <button data-spy-act="exit-game" class="ubp-btn" style="flex:1;padding:8px 0;">🚪 退出游戏</button>
        <button data-spy-act="restart-game" class="ubp-btn primary" style="flex:1;padding:8px 0;background:#F59E0B;border:none;font-weight:600;">🔄 再来一局</button>
        <button data-spy-act="show-replay" class="ubp-btn" style="flex:1;padding:8px 0;">📜 查看看板</button>
      </div>
    `);

    showSpyGameOverModal();
  }

  function showSpyGameOverModal() {
    const isCivilianWon = spyGame.winner === '平民阵营';
    const user = spyGame.players[spyGame.userIndex];
    const isUserWon = (user.isSpy && !isCivilianWon) || (!user.isSpy && isCivilianWon);
    const spy = spyGame.players.find(p => p.isSpy);
    const modal = document.createElement('div');
    modal.className = 'spy-gameover-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 25px rgba(0,0,0,0.5);">
        <div style="font-size:36px;margin-bottom:8px;">${isUserWon ? '🎉' : '💔'}</div>
        <div style="font-size:16.5px;font-weight:bold;color:${isCivilianWon ? '#10B981' : '#F59E0B'};margin-bottom:6px;">
          【${spyGame.winner}】获得了胜利！
        </div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:6px;">
          平民词：<b style="color:#10B981;">${escapeHtml(spyGame.civilianWord)}</b> · 卧底词：<b style="color:#EF4444;">${escapeHtml(spyGame.spyWord)}</b>
        </div>
        <div style="font-size:12px;color:var(--ubp-text-3);margin-bottom:14px;">
          卧底是：${spy ? `${spy.position}号位 ${escapeHtml(spy.name)}` : '未知'}
        </div>
        <div style="display:flex;flex-direction:column;gap:8px;">
          <div style="display:flex;gap:8px;">
            <button data-spy-act="exit-game" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出游戏</button>
            <button data-spy-act="restart-game" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#F59E0B;border:none;">🔄 再来一局</button>
          </div>
          <button data-spy-act="show-replay" class="ubp-btn" style="width:100%;padding:7px 0;font-size:12px;">📜 查看对局回放</button>
        </div>
      </div>
    `;
    sheet.appendChild(modal);
  }

  function restartSpyGame() {
    if (!spyGame) return;
    const prevPlayers = spyGame.players;
    const positions = [1, 2, 3, 4, 5, 6];
    for (let i = positions.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [positions[i], positions[j]] = [positions[j], positions[i]];
    }

    prevPlayers.forEach((p, idx) => p.position = positions[idx]);
    prevPlayers.sort((a, b) => a.position - b.position);

    spySessionCounter++;
    spyGame = {
      session: spySessionCounter,
      players: prevPlayers.map(p => ({
        ...p,
        alive: true,
        role: '平民',
        isSpy: false,
        word: '',
        votedFor: null,
        hasSpoken: false
      })),
      phase: 'idle',
      round: 1,
      currentSpeaker: 0,
      winner: null,
      civilianWord: '',
      spyWord: '',
      userIndex: prevPlayers.findIndex(p => p.isUser),
      history: [],
      historyEntries: [],
      replay: [],
      pickMode: null,
      pick: { idx: null },
      votes: {}
    };
    spyIsGameOver = false;
    spyReplayLogs = [];
    startSpyGame();
  }

  function showSpyReplay() {
    if (!spyReplayLogs.length) {
      showToast('没有游戏记录');
      return;
    }
    const spyReplayRef = { players: spyReplayPlayersSnapshot || [] };
    const html = spyReplayLogs.map(item => {
      if (typeof item === 'object') {
        const cc = (item.authorPos != null) ? getGamePlayerColorByPos(spyReplayRef, item.authorPos) : '';
        if (item.type === 'hidden') {
          const base = cc || '#FFD700';
          return `<div style="color:${base};margin:4px 0;font-size:11px;background:${charColorAlpha(cc, '17') || 'rgba(255,215,0,0.1)'};border-left:3px solid ${base};padding:4px 6px;border-radius:4px;">${escapeHtml(stripLogTags(item.text)).replace(/\n/g, '<br>')}</div>`;
        }
        if (item.type === 'user_private') {
          return `<div style="color:${item.color || '#FBBF24'};margin:4px 0;font-size:12px;font-weight:600;">${escapeHtml(stripLogTags(item.text)).replace(/\n/g, '<br>')}</div>`;
        }
        const isUserLine = item.authorPos != null && (spyReplayPlayersSnapshot || []).some(p => p && p.isUser && p.position === item.authorPos);
        if (isUserLine) {
          return `<div style="color:#fff;margin:4px 0;font-size:12px;font-weight:600;border-left:3px solid rgba(255,255,255,0.55);padding-left:6px;">${escapeHtml(stripLogTags(item.text)).replace(/\n/g, '<br>')}</div>`;
        }
        if (cc) {
          return `<div style="color:${cc};margin:4px 0;font-size:12px;font-weight:600;border-left:3px solid ${charColorAlpha(cc, '99')};padding-left:6px;">${escapeHtml(stripLogTags(item.text)).replace(/\n/g, '<br>')}</div>`;
        }
      }
      const text = typeof item === 'object' ? item.text : item;
      return `<div style="color:#fff;margin:2px 0;">${escapeHtml(stripLogTags(text))}</div>`;
    }).join('');
    const ov = document.createElement('div');
    ov.className = 'spy-replay-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:80;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;margin-bottom:8px;">
        <span style="font-size:15px;font-weight:600;">📜 谁是卧底 · 全景复盘与思考链</span>
        <button data-spy-act="close-replay" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="flex:1;overflow-y:auto;font-size:12px;line-height:1.6;background:var(--ubp-card-2);border-radius:8px;padding:8px;">${html}</div>
    `;
    sheet.appendChild(ov);
  }

