      </div>

      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;flex:none;">
        <div style="width:46px;height:46px;border-radius:50%;overflow:hidden;background:#EF4444;flex-shrink:0;border:2px solid var(--ubp-line);">
          ${oppAvatar ? `<img src="${oppAvatar}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;">${escapeHtml(opp.name.slice(0, 1))}</span>`}
        </div>
        <div style="flex:1;min-width:0;">
          <div style="font-size:14px;font-weight:600;color:var(--ubp-text);">${escapeHtml(opp.name)}<span style="font-size:11px;color:#EF4444;margin-left:6px;">${oppSym} ${g.userFirst ? '后手' : '先手'}</span></div>
          <div style="font-size:11px;color:var(--ubp-text-3);">${escapeHtml(opp.identity || '对手')} · ${statusText}</div>
