  function renderTTTInviteOverlay() {
    const result = loadContactsWithAvatars();
    const contacts = result?.contacts || [];
    let chosenName = tttGame?.opponent?.name || (contacts[0]?.name || '');

    const ov = document.createElement('div');
    ov.className = 'ttt-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';

    const renderContent = () => {
      const listHtml = contacts.map(c => {
        const isSelected = c.name === chosenName;
        const av = c.avatar || getCharacterAvatarByName(c.name);
        return `
          <div data-ttt-pick="${escapeAttr(c.name)}" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${isSelected ? 'rgba(14,165,233,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${isSelected ? '#0EA5E9' : 'var(--ubp-line)'};">
            <div style="width:40px;height:40px;border-radius:50%;background:#0EA5E9;overflow:hidden;flex-shrink:0;box-shadow:0 1px 4px rgba(0,0,0,0.2);">
