      </div>` : '';

    sheet.innerHTML = `
      <style>${UBP_FX_CSS}</style>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">
        <div style="display:flex;align-items:center;gap:7px;">
          <button data-ddz-act="ddz-exit" style="background:none;border:none;font-size:16px;cursor:pointer;color:var(--ubp-text);" title="返回大厅">←</button>
          <span style="font-size:15px;font-weight:bold;color:var(--ubp-text);">🃏 斗地主</span>
          <span style="font-size:10.5px;color:var(--ubp-text-3);">赌注 ${Math.max(1, Math.round(Number(g.bet) || 100))} × 叫分 ${base} × 倍数 ${g.chip || 1}${g.bombCount ? '（炸 ' + g.bombCount + '）' : ''} · ${moneyHUD}</span>
        </div>
        <div style="display:flex;align-items:center;gap:6px;">
          ${userRole ? `<span style="font-size:11px;font-weight:600;color:${userRole === 'landlord' ? '#F59E0B' : '#10B981'};">我 · ${userRole === 'landlord' ? '地主👑' : '农民'}</span>` : '<span style="font-size:11px;color:var(--ubp-text-3);">叫分中</span>'}
        </div>
      </div>

      <div style="display:flex;gap:6px;align-items:stretch;flex:none;margin-bottom:5px;">
        ${ddzRenderOppHTML(2)}
        ${ddzRenderOppHTML(1)}
      </div>

      <div style="background:var(--ubp-card-2, #26262a);border:1px solid var(--ubp-line);border-radius:10px;padding:7px 8px;flex:none;margin-bottom:5px;">
        ${g.phase === 'bidding' ? ddzBidSummaryHTML() : ''}
        <div style="display:flex;flex-direction:column;gap:6px;align-items:center;">
          ${ddzRenderBottomHTML()}
          ${ddzRenderLastPlayHTML()}
        </div>
        <div style="text-align:center;font-size:11.5px;color:${g.turn === 0 && g.phase !== 'ended' ? 'var(--ubp-accent, #10B981)' : 'var(--ubp-text-2)'};margin-top:5px;font-weight:600;">${statusText}</div>
      </div>

