  }

  function ddzHandleUserChatSend() {
    const g = ddzGame;
    if (!g || !g.aiChat) return;
    const input = sheet.querySelector('#ddz-chat-input');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    g.speeches.push({ seat: 0, name: '我', text: msg });
    ddzRefreshSpeechBox();
    let target = (g.phase === 'playing' && g.turn !== 0) ? g.turn : (g.lastSeat && g.lastSeat !== 0 ? g.lastSeat : 1);
    if (!g.players[target] || g.players[target].isUser) target = 1;
    ddzRequestSpeech(target, 'user-chat', msg);
  }

  // ========== 斗地主：结算弹窗 ==========
  function ddzShowResultModal() {
