    const rows = g.players.map(p => {
      const role = g.roles[p.seat] === 'landlord' ? '地主👑' : '农民';
      const isWinner = g.roles[p.seat] === g.roles[g.winnerSeat];
      return `<div style="display:flex;justify-content:space-between;font-size:12px;color:${isWinner ? '#10B981' : 'var(--ubp-text-3)'};padding:3px 0;">
        <span>${escapeHtml(p.name)}${p.isUser ? '（我）' : ''}</span><span>${role} · ${isWinner ? '胜' : '负'} · 剩 ${g.hands[p.seat].length} 张</span>
      </div>`;
    }).join('');
    const modal = document.createElement('div');
    modal.className = 'ddz-result-overlay';
    modal.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML = `
      <div class="ubp-fx-pop" style="background:var(--ubp-card, #1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:18px 15px;width:100%;max-width:290px;box-shadow:0 10px 25px rgba(0,0,0,0.5);">
        <div style="text-align:center;font-size:34px;margin-bottom:4px;">${userWon ? '🎉' : '💔'}</div>
        <div style="text-align:center;font-size:16px;font-weight:bold;color:${userWon ? '#10B981' : '#EF4444'};margin-bottom:4px;">${userWon ? '恭喜你赢了！' : '很遗憾，输了…'}</div>
        <div style="text-align:center;font-size:11.5px;color:var(--ubp-text-2);margin-bottom:10px;">${escapeHtml(ddzPlayerResultLine())}</div>
        <div style="background:var(--ubp-card-2);border-radius:8px;padding:8px 10px;margin-bottom:10px;">
          ${rows}
          <div style="font-size:11px;color:var(--ubp-text-3);margin-top:6px;border-top:1px solid var(--ubp-line);padding-top:5px;">
            底分 ${(g.bid && g.bid.highest) ? g.bid.highest : 1} · 最终倍数 ×${g.chip || 1} · 炸弹 ${g.bombCount} 个${g.spring ? ' · ' + (g.roles[g.winnerSeat] === 'landlord' ? '春天' : '反春天') + '（×2）' : ''}<br>💰 金币 ${(g.moneyDelta || 0) > 0 ? '+' : ''}${g.moneyDelta || 0}（赌注 ${Math.max(1, Math.round(Number(g.bet) || 100))} × 叫分 ${(g.bid && g.bid.highest) ? g.bid.highest : 1} × 倍数 ${g.chip || 1}）
          </div>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ddz-act="ddz-exit" class="ubp-btn" style="flex:1;padding:8px 0;font-size:12.5px;">🚪 退出</button>
          <button data-ddz-act="ddz-rematch" class="ubp-btn primary" style="flex:1;padding:8px 0;font-size:12.5px;background:#10B981;">🔄 再来一局</button>
        </div>
      </div>
    `;
    sheet.appendChild(modal);
  }

  // ========== 斗地主：大厅 / 邀请 / 设置 ==========
  // 💰 斗地主赌注卡片（大厅设置：每局按 赌注×叫分×倍数 结算金币）
  function ddzBetCardHTML() {
    const cfg = loadDDZConfig();
    const t = getTreasury();
    const min = Math.max(1, Math.round(Number(cfg.bet) || 100));
    const ok = t.ok && t.balance >= min;
    return '<div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;">' +
      '<span style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">💰 赌注（金币结算）</span>' +
      '<span style="font-size:15px;font-weight:800;color:' + (ok ? '#10B981' : '#EF4444') + ';">' + (t.ok ? t.balance : '—') + '</span></div>' +
      '<div style="display:flex;gap:6px;align-items:center;margin-top:8px;">' +
      '<input id="ddz-bet-input" class="ubp-fieldinput" type="number" min="1" value="' + min + '" style="flex:1;padding:5px 8px;font-size:13px;">' +
      '<button data-ddz-act="ddz-bet-save" class="ubp-btn" style="padding:5px 12px;font-size:12.5px;background:#DC2626;color:#fff;border:none;">保存赌注</button></div>' +
      '<div style="font-size:11px;color:var(--ubp-text-3);margin-top:6px;line-height:1.6;">💰 实时扣钱：叫分确定地主后立即按 <b>赌注 × 叫分</b> 从金币预扣本金，每出炸弹/王炸、春天倍数翻倍时实时追加预扣；赢了实时回款（返还预扣本金 + 赢钱），输了预扣款即为输款；中途弃局退还预扣。当前余额' + (t.ok ? ' ' + t.balance + ' ' + escapeHtml(t.name) : '：' + escapeHtml(t.reason || '未检测到金币')) + (ok ? '' : '（不足赌注 ' + min + '，无法开局）') + '。</div></div>';
  }
  function renderDDZLobby() {
    const cfg = loadDDZConfig();
    const hasSaved = hasSavedDDZGame();
