    }
    let resumeBanner = '';
    if (savedInfo && savedInfo.players) {
      const turnName = savedInfo.phase === 'bidding'
        ? (savedInfo.bid ? ddzSeatSaveName(savedInfo, savedInfo.bid.turnSeat) : '')
        : ddzSeatSaveName(savedInfo, savedInfo.turn);
      const phaseText = savedInfo.phase === 'bidding' ? '叫分阶段' : '出牌阶段';
      resumeBanner = `
        <div style="background:var(--ubp-card-2, #2a2a30);border:1px solid var(--ubp-line);border-radius:10px;padding:10px 12px;margin-bottom:12px;display:flex;align-items:center;justify-content:space-between;">
          <div style="min-width:0;">
            <div style="font-size:13px;font-weight:600;color:#DC2626;">🔖 发现进行中的斗地主对局</div>
            <div style="font-size:11.5px;color:var(--ubp-text-2);margin-top:2px;">${phaseText} · 轮到 ${escapeHtml(turnName)} · 手牌 ${(savedInfo.hands && savedInfo.hands[0] ? savedInfo.hands[0].length : 0)} 张</div>
          </div>
          <div style="display:flex;gap:6px;flex-shrink:0;">
            <button data-ddz-act="ddz-resume" class="ubp-btn primary" style="padding:4px 10px;font-size:12px;background:#DC2626;">继续对局</button>
            <button data-ddz-act="ddz-discard" class="ubp-btn" style="padding:4px 8px;font-size:12px;">放弃</button>
          </div>
        </div>`;
    }

    const pn = (cfg.partnerNames || []).filter(Boolean);
    const slot = (i) => {
      const nm = pn[i];
      if (!nm) return `<div style="flex:1;border:1.5px dashed var(--ubp-line);border-radius:8px;padding:10px 6px;text-align:center;font-size:11.5px;color:var(--ubp-text-3);">未邀请</div>`;
      const av = getCharacterAvatarByName(nm);
      return `<div style="flex:1;border:1.5px solid #DC2626;border-radius:8px;padding:7px 6px;text-align:center;background:rgba(220,38,38,0.08);">
        <div style="width:34px;height:34px;border-radius:50%;overflow:hidden;background:#DC2626;margin:0 auto 4px;">
          ${av ? `<img src="${av}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:14px;">${escapeHtml(nm.slice(0, 1))}</span>`}
        </div>
        <div style="font-size:11.5px;color:var(--ubp-text);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(nm)}</div>
      </div>`;
    };

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex:none;">
        <div style="display:flex;align-items:center;gap:8px;">
          <button data-ddz-act="ddz-back-center" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回棋牌大厅">←</button>
          <span style="font-size:17px;font-weight:bold;color:var(--ubp-text);">🃏 斗地主 · 牌桌大厅</span>
        </div>
        <div style="display:flex;gap:6px;">
          <button data-ddz-act="ddz-settings" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="设置">⚙️</button>
          <button data-ubp-act="back-setup" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="返回游戏入口">✕</button>
        </div>
      </div>

      <div style="flex:1;overflow-y:auto;padding-right:2px;">
        ${resumeBanner}

        ${ddzBetCardHTML()}

        <div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span style="font-size:14px;font-weight:600;color:var(--ubp-text);">👥 邀请 2 位角色入座</span>
            <button data-ddz-act="ddz-invite" class="ubp-btn" style="padding:3px 10px;font-size:12px;">邀请角色</button>
          </div>
          <div style="display:flex;gap:8px;margin-top:9px;">${slot(0)}${slot(1)}</div>
          <div style="font-size:11px;color:var(--ubp-text-3);margin-top:7px;line-height:1.6;">① 点击右上角【邀请角色】选择 2 位角色 → ② 点击下方【开始对局】入座开局。<br>3 人斗地主：你和 2 位角色同桌，1 人当地主、其余 2 人做农民（农民是队友，一人跑完全队获胜）。</div>
        </div>

        <div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <div style="min-width:0;margin-right:10px;">
              <div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">💬 打牌时角色 AI 陪聊</div>
              <div style="font-size:11px;color:var(--ubp-text-3);margin-top:2px;line-height:1.45;">开启后打牌过程会调用游戏入口配置的 AI，让角色叫分、出牌、被炸时实时聊天吐槽（${cfg.aiChat ? '已开启' : '已关闭'} · ${cfg.aiLevel === 'strong' ? 'AI强' : cfg.aiLevel === 'fast' ? 'AI快' : 'AI标准'}）。</div>
            </div>
            <label style="position:relative;display:inline-block;width:42px;height:24px;cursor:pointer;flex:none;">
              <input type="checkbox" id="ddz-chat-toggle" ${cfg.aiChat ? 'checked' : ''} style="opacity:0;width:0;height:0;">
              <span style="position:absolute;top:0;left:0;right:0;bottom:0;background:${cfg.aiChat ? '#DC2626' : '#4b5563'};border-radius:24px;transition:0.3s;">
                <span style="position:absolute;height:18px;width:18px;left:${cfg.aiChat ? '21px' : '3px'};bottom:3px;background:#fff;border-radius:50%;transition:0.3s;"></span>
              </span>
            </label>
          </div>
        </div>

        <button data-ddz-act="ddz-start" class="ubp-btn primary" style="width:100%;padding:12px;font-size:14px;background:#DC2626;border:none;margin-bottom:12px;">${pn.length === 2 ? '🎮 开始对局（' + escapeHtml(pn[0]) + ' · ' + escapeHtml(pn[1]) + '）' : '🎮 开始对局（未邀请将自动补位）'}</button>

        <details style="font-size:11px;color:var(--ubp-text-3);border-top:1px solid var(--ubp-line);padding-top:8px;">
          <summary style="cursor:pointer;">📖 玩法规则（点击展开）</summary>
          <div style="white-space:pre-wrap;font-size:11.5px;line-height:1.6;background:var(--ubp-card-2);padding:8px;border-radius:6px;margin-top:5px;color:var(--ubp-text-2);">【牌与发牌】一副 54 张（大小王 + 52 张），每人 17 张，剩 3 张底牌；底牌归地主，地主 20 张。
【叫地主】随机一人开始轮流叫分（1/2/3 分或不叫），只能叫更高分，3 分封顶；最高分者当地主；三家都不叫则重新发牌。
【出牌】地主先出；同类型牌才能管，牌型必须一样且更大才能压；一轮里其余两家都不出时，最后出牌者获得下一轮自由出牌权。
【牌型】单张 / 对子 / 三张 / 三带一 / 三带一对 / 顺子（5 张以上连续单牌，不含 2 和王）/ 连对（3 对以上连续对子）/ 飞机（连续三张，可带单或带对）/ 四带二（四张 + 2 单牌或 1 对，不是炸弹）/ 炸弹（四张相同，大于所有普通牌型）/ 王炸（大小王，最大）。
【胜负】谁先出完谁赢：地主先出完则地主胜；任意一个农民先出完则农民方胜（农民是队友）；每局按 赌注 × 叫分 × 倍数 结算金币（炸弹、春天各再 ×2）。</div>
        </details>
      </div>
    `;

    const toggle = sheet.querySelector('#ddz-chat-toggle');
    if (toggle) {
      toggle.addEventListener('change', () => {
        const c = loadDDZConfig();
        c.aiChat = toggle.checked;
        saveDDZConfig(c);
        renderDDZLobby();
      });
    }
  }

  function ddzSeatSaveName(saved, seat) {
    if (!saved || !saved.players || !saved.players[seat]) return '玩家';
    return saved.players[seat].name;
  }

  // 邀请 2 位角色（多选）
  function renderDDZInviteOverlay(onConfirmed) {
    const cfg = loadDDZConfig();
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    let chosen = (cfg.partnerNames || []).filter(n => n && contacts.some(c => isNameMatch(c.name, n))).slice(0, 2);
    if (chosen.length < 2) {
      for (const c of contacts) {
        if (chosen.length >= 2) break;
        if (!chosen.some(n => isNameMatch(n, c.name))) chosen.push(c.name);
      }
    }

    const ov = document.createElement('div');
    ov.className = 'ddz-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';

    const renderContent = () => {
      const listHtml = contacts.map(c => {
        const idx = chosen.findIndex(n => isNameMatch(n, c.name));
        const isSelected = idx !== -1;
        const av = c.avatar || getCharacterAvatarByName(c.name);
        return `
          <div data-ddz-pick="${escapeHtml(c.name).replace(/"/g, '&quot;')}" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${isSelected ? 'rgba(220,38,38,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${isSelected ? '#DC2626' : 'var(--ubp-line)'};">
            <div style="width:38px;height:38px;border-radius:50%;background:#DC2626;overflow:hidden;flex-shrink:0;">
              ${av ? `<img src="${av}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:15px;">${escapeHtml(c.name.slice(0, 1))}</span>`}
            </div>
            <div style="flex:1;min-width:0;">
              <div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(c.name)} ${isSelected ? `<span style="font-size:11px;color:#DC2626;">(${idx === 0 ? '座位1' : '座位2'})</span>` : ''}</div>
              ${c.identity ? `<div style="font-size:11px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">${escapeHtml(c.identity)}</div>` : ''}
            </div>
            <span style="font-size:16px;color:#DC2626;flex-shrink:0;">${isSelected ? '✅' : '○'}</span>
          </div>`;
      }).join('');

      ov.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">
          <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请 2 位角色入座</span>
          <button data-ddz-invite="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#DC2626;">${chosen.length}</b> / 2 位（选满 2 位后点击确认即可入座开局）</div>
        <div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">
          ${listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">通讯录暂无角色，请确保神数据库已添加角色。</div>'}
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">
