        </div>
      `;

      ov.querySelectorAll('[data-ddz-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const name = el.dataset.ddzPick;
          const idx = chosen.findIndex(n => isNameMatch(n, name));
          if (idx !== -1) chosen.splice(idx, 1);
          else {
            if (chosen.length >= 2) chosen.shift();
            chosen.push(name);
          }
          renderContent();
        });
      });
      ov.querySelector('[data-ddz-invite="close"]')?.addEventListener('click', () => {
        ov.remove();
        if (typeof onConfirmed !== 'function') return;
      });
      ov.querySelector('[data-ddz-invite="confirm"]')?.addEventListener('click', () => {
        if (chosen.length !== 2) { showToast('请先选择 2 位角色'); return; }
        const c = loadDDZConfig();
        c.partnerNames = chosen.slice(0, 2);
        saveDDZConfig(c);
        ov.remove();
        if (typeof onConfirmed === 'function') onConfirmed(chosen.slice(0, 2));
        else renderDDZLobby();
      });
    };

    renderContent();
    sheet.appendChild(ov);
  }

