  // 道具目标选择
  function renderLieTargetPicker(itemIdx, key) {
    const st = lieGame;
    if (!st) return;
    const targets = st.players.filter(p => p.alive && p.seat !== 0 && (key !== 'steal' || (p.items && p.items.length)));
    if (!targets.length) { showToast(key === 'steal' ? '其他玩家都没有道具牌' : '没有可选目标'); return; }
