    ov.className = 'lie-target-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:65;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;padding:18px;box-sizing:border-box;';
    const def = LIE_ITEMS[key] || { name: '道具' };
