    if (lvl === 'fast') return moves[Math.floor(rand() * moves.length)];
    const scored = moves.map(function (m) {
      return { m: m, h: ludoHeuristicScore(st, seat, m, { noise: lvl === 'normal' ? D.noise : 0 }), mc: 0, score: 0 };
    });
