      return;
    }
    if (st.phase === 'select') {
      const rng = pickRng(lvl, 'ludo-ai|' + st.turnSeat + '|' + st.dice + '|' + st.players.map(function (x) { return x.color + ':' + x.planes.join(','); }).join('|'));
      const move = ludoAiPickMove(st, seat, st.dice, lvl, rng);
