  // 掷骰（含三连 6 惩罚判定），返回 'select' | 'no-move' | 'three-six'
  function ludoRollFor(seat, preset) {
    const st = ludoGame;
    const d = (typeof preset === 'number' && preset >= 1 && preset <= 6) ? preset : ludoRollValue();
    st.dice = d;
    st.legalMoves = [];
    st.actionCount = (st.actionCount || 0) + 1;
    if (d === 6) {
      st.sixChain = (st.sixChain || 0) + 1;
      ludoLog(st, '🎲 ' + st.players[seat].name + ' 掷出 6 点' + (st.sixChain >= 2 ? '（连续第 ' + st.sixChain + ' 次 6）' : ''), '#F59E0B', { seat: seat, kind: 'roll' });
      if (st.sixChain >= 3 && !st.noThreeSixPenalty) {
        ludoLog(st, '⚠️ 连续三次 6！' + st.players[seat].name + ' 本次回合直接结束，不能行动', '#EF4444', { seat: seat, kind: 'end' });
