      }
    } else {
      ludoLog(st, '🎲 ' + st.players[seat].name + ' 掷出 ' + d + ' 点', '', { seat: seat, kind: 'roll' });
    }
    const moves = ludoLegalMoves(st, seat, d);
    st.legalMoves = moves;
    if (!moves.length) {
      ludoLog(st, '🚫 ' + st.players[seat].name + ' 没有可以移动的飞机' + (d === 6 ? '（掷出 6，可再掷一次）' : '，回合结束'), '', { seat: seat, kind: 'info' });
