  // 投骰子动画：骰子区快速滚动 7 帧后落定；无骰子界面（测试/后台）直接结算
  function ludoRollWithAnimation(seat) {
    const st = ludoGame;
    if (!st || st.phase !== 'roll' || st.moving) return;
    const d = ludoRollValue();
    const gen = ludoGenCounter;
    const box = (sheet && typeof sheet.querySelector === 'function') ? sheet.querySelector('#ludo-dice-box') : null;
    if (!box) { const res = ludoRollFor(seat, d); ludoAfterRoll(seat, res); return; }
    st.moving = true; // 动画期间锁住输入
    let frames = 0;
    const finish = function () {
      const st2 = ludoGame;
      if (!st2) return;
      st2.moving = false;
      const res = ludoRollFor(seat, d);
      ludoAfterRoll(seat, res);
    };
    const step = function () {
      if (gen !== ludoGenCounter || !ludoGame) return; // 已退出/已换局：丢弃本次掷骰
      if (frames >= 7) { finish(); return; }
      frames++;
      const b = (sheet && typeof sheet.querySelector === 'function') ? sheet.querySelector('#ludo-dice-box') : null;
      if (b) b.innerHTML = ludoDiceFaceHTML(1 + Math.floor(Math.random() * 6));
