  // ========== 飞行棋：棋盘与 UI ==========
  function ludoBoardHTML(st) {
    const cellPct = 100 / 15;
    const pct15 = function (v) { return (v / 15 * 100); };
    let html = '';
    // 停机坪（四角大停机坪 32%，居中于 6×6 角落；铺在虚线之上盖住穿过的虚线）
    for (const color of LUDO_COLORS) {
      const b = LUDO_BASE[color];
