      const relPct = function (v) { return ((v - 0.6) / 4.8 * 100).toFixed(2); };
      let pads = '';
      for (let i = 0; i < 4; i++) {
        const off = LUDO_PAD_OFF[i];
        pads += '<div style="position:absolute;left:' + relPct(off[1]) + '%;top:' + relPct(off[0]) + '%;width:24%;height:24%;transform:translate(-50%,-50%);border-radius:50%;background:rgba(255,255,255,.8);border:2px dashed ' + LUDO_COLOR_DARK[color] + ';box-sizing:border-box;"></div>';
      }
