      const isTurnBase = st.phase !== 'ended' && curP && curP.color === color && st.players.length > 1;
      html += '<div style="position:absolute;left:' + (pct15(b.c0) + 4).toFixed(3) + '%;top:' + (pct15(b.r0) + 4).toFixed(3) + '%;width:32%;height:32%;background:' + hex + ';border-radius:12px;box-shadow:inset 0 0 0 2px rgba(0,0,0,.28)' + (isTurnBase ? ',0 0 0 2.5px #fff' : '') + ';z-index:5;box-sizing:border-box;">' +
