      const tColor = ludoTrackColor(g);
      const cHex = LUDO_COLOR_HEX[tColor];
      const startOwner = LUDO_COLORS.find(function (k) { return LUDO_START[k] === g; }) || null;
      html += '<div style="position:absolute;left:' + (rc[1] * cellPct).toFixed(3) + '%;top:' + (rc[0] * cellPct).toFixed(3) + '%;width:calc(' + cellPct.toFixed(3) + '% + 0.7px);height:calc(' + cellPct.toFixed(3) + '% + 0.7px);background:' + cHex + ';display:flex;align-items:center;justify-content:center;z-index:2;">' +
        '<span style="width:56%;height:56%;border-radius:50%;background:#fff;opacity:.95;box-shadow:inset 0 0 2px rgba(0,0,0,.35);' + (startOwner ? 'border:2px solid ' + LUDO_COLOR_HEX[startOwner] + ';' : '') + 'box-sizing:border-box;"></span>' +
        (startOwner ? '<span style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:9px;line-height:1;color:' + LUDO_COLOR_DARK[startOwner] + ';">✈</span>' : '') +
        '</div>';
    }
    // 归家通道 5 格 × 4（浅色 + 指向中心的箭头；同样无缝相连）
    const chev = { yellow: '▶', blue: '▼', red: '◀', green: '▲' };
    for (const color of LUDO_COLORS) {
      LUDO_HOME_LANE[color].forEach(function (rc) {
        html += '<div style="position:absolute;left:' + (rc[1] * cellPct).toFixed(3) + '%;top:' + (rc[0] * cellPct).toFixed(3) + '%;width:calc(' + cellPct.toFixed(3) + '% + 0.7px);height:calc(' + cellPct.toFixed(3) + '% + 0.7px);background:' + LUDO_COLOR_LIGHT[color] + ';display:flex;align-items:center;justify-content:center;z-index:1;">' +
          '<span style="width:56%;height:56%;border-radius:50%;background:#fff;opacity:.95;box-shadow:inset 0 0 2px rgba(0,0,0,.3);box-sizing:border-box;"></span>' +
          '<span style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:9px;line-height:1;color:' + LUDO_COLOR_HEX[color] + ';">' + chev[color] + '</span></div>';
