          <button data-ubp-act="back-setup" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="返回游戏入口">✕</button>
        </div>
      </div>
      <div style="flex:1;overflow-y:auto;padding-right:2px;">
        ${banner}
        <div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">
          <div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">🎨 选择你的颜色</div>
          <div style="font-size:11px;color:var(--ubp-text-3);margin:3px 0 8px;line-height:1.5;">你选好后，其余角色按顺序分配剩下的颜色（2~4 人对局，每人 4 架飞机）。</div>
          <div style="display:flex;gap:6px;">${colorPick}</div>
        </div>
        <div style="background:var(--ubp-card-2, #26262a);border-radius:10px;padding:11px 12px;margin-bottom:12px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span style="font-size:14px;font-weight:600;color:var(--ubp-text);">👥 邀请 1~3 位角色入座</span>
            <button data-ludo-act="ludo-invite" class="ubp-btn" style="padding:3px 10px;font-size:12px;">邀请角色</button>
          </div>
          <div style="display:flex;gap:6px;margin-top:9px;">${slots}</div>
