    st.turnStarted = true;
    st.rolled = false;
    st.remoteDice = 0;
    const status = rmTurnStartStatus(st, p);
    st.actionCount++;
    rmSaveState();
    renderRmGameUI();
    if (status === 'skip') {
      rmDelay(function () { rmEndTurn(); }, 900);
      return;
    }
