    el.innerHTML = rmRenderSpeechHTML();
    if (box && atBottom) box.scrollTop = box.scrollHeight;
  }
  function rmHandleUserChat() {
    const st = rmGame;
    if (!st || !st.aiChat) return;
    const input = sheet.querySelector('#rm-chat-input');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    st.speeches.push({ seat: 0, name: '我', text: msg });
    rmRefreshSpeechBox();
    const target = (st.turnSeat !== 0 && st.players[st.turnSeat] && !st.players[st.turnSeat].isUser && !st.players[st.turnSeat].eliminated) ? st.turnSeat
      : (st.players.find(function (p) { return p && !p.isUser && !p.eliminated; }) || {}).seat;
    if (typeof target === 'number') rmRequestSpeech(target, 'user-chat', msg);
