  // __RM_RUNTIME_END__
  // __RM_UI_BEGIN__
  // ========== 大富翁：棋盘坐标与渲染 ==========
  const RM_TOKEN_COLORS = ['#0EA5E9', '#F59E0B', '#A855F7', '#22C55E'];
  const RM_TOKEN_LABEL = ['我', '二', '三', '四'];
  // 40 格沿玉子手机屏幕四边绕一圈（右下=起点，逆时针）；格子全部等宽等高，围成矩形外框
  function rmCellRC(i, g) {
    const T = g.T, L = g.L;
    if (i < T) return { r: L - 1, c: T - 1 - i };              // 下边：右下角 → 左下角
    if (i < T + L - 2) return { r: L - 2 - (i - T), c: 0 };    // 左边：下 → 上
    const k = i - (T + L - 2);
    if (k < T) return { r: 0, c: k };                          // 上边：左上角 → 右上角
    return { r: k - T + 1, c: T - 1 };                         // 右边：上 → 下
  }
  // 棋盘几何：所有格子等宽等高的正方形。列数 T＋行数 L＝22（保证 2T＋2L−4＝40 格环），
  // 按屏幕宽高比自动选最合适的 T/L；格子宽度铺满屏幕宽度，棋盘高度 = L×格宽（超出屏幕时外层滚动显示）
  let RM_GEOM_CACHE = null;
  function rmBoardGeom() {
    const cw = (sheet && sheet.clientWidth) ? sheet.clientWidth : 360;
    const ch = (sheet && sheet.clientHeight) ? sheet.clientHeight : 620;
    if (RM_GEOM_CACHE && RM_GEOM_CACHE.cw === cw && RM_GEOM_CACHE.ch === ch) return RM_GEOM_CACHE;
    const availW = Math.max(200, cw - 16);   // 滚动容器左右各 6px 内边距 + 外框 2px 边框
    const availH = Math.max(300, ch - 20);   // 滚动容器上下 6/8px 内边距 + 外框 2px 边框
    let T = 8, L = 14, bestErr = Infinity;
    for (let t = 6; t <= 12; t++) {
      const l = 22 - t;
      const err = Math.abs(t / l - availW / availH);
      if (err < bestErr) { bestErr = err; T = t; L = l; }
    }
    const s = availW / T;                    // 格子边长（px），等宽等高
    const boardW = T * s, boardH = L * s;    // 棋盘整体尺寸
    const tokenPx = Math.max(18, Math.min(32, Math.round(s * 0.52)));
    RM_GEOM_CACHE = {
      cw: cw, ch: ch, T: T, L: L, s: s, boardW: boardW, boardH: boardH, availW: availW, availH: availH,
      cellW: 100 / T, cellH: 100 / L, tokenPx: tokenPx, overflow: Math.max(0, boardH - availH)
    };
    return RM_GEOM_CACHE;
  }
  function rmCellGeo(i, g) {
    const rc = rmCellRC(i, g);
    return { x: (rc.c + 0.5) * g.cellW, y: (rc.r + 0.5) * g.cellH, w: g.cellW, h: g.cellH };
  }
  function rmCellXY(i) {
    const g = rmBoardGeom();
    const geo = rmCellGeo(i, g);
    return { x: geo.x, y: geo.y };
  }
  function rmTokenXY(p, pos) {
    const g = rmBoardGeom();
    const geo = rmCellGeo(pos, g);
    const off = [[-1, -1], [1, -1], [-1, 1], [1, 1]][p.seat] || [0, 0];
    return { x: geo.x + off[0] * g.cellW * 0.25, y: geo.y + off[1] * g.cellH * 0.25 };
  }
  // 棋子头像：优先用开局时解析好的头像，缺失时才回查（结果缓存在玩家对象上，避免每帧重查 DOM/数据库）
  function rmPlayerAvatar(p) {
    if (!p) return '';
    if (!p.avatar) {
      try { p.avatar = (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name)) || ''; } catch (e) { p.avatar = ''; }
    }
    return p.avatar;
  }
  function rmCellStyle(cell, land) {
    let bg = 'var(--ubp-card-2, #26262a)', bd = 'rgba(255,255,255,0.10)';
    switch (cell.type) {
      case 'start': bg = 'rgba(34,197,94,0.30)'; bd = 'rgba(34,197,94,0.7)'; break;
      case 'chance': bg = 'rgba(245,158,11,0.22)'; bd = 'rgba(245,158,11,0.55)'; break;
      case 'destiny': bg = 'rgba(168,85,247,0.22)'; bd = 'rgba(168,85,247,0.55)'; break;
      case 'bank': bg = 'rgba(14,165,233,0.20)'; bd = 'rgba(14,165,233,0.5)'; break;
      case 'tax': bg = 'rgba(239,68,68,0.20)'; bd = 'rgba(239,68,68,0.5)'; break;
      case 'prison': case 'hospital': bg = 'rgba(107,114,128,0.22)'; bd = 'rgba(107,114,128,0.55)'; break;
      case 'shop': bg = 'rgba(236,72,153,0.20)'; bd = 'rgba(236,72,153,0.5)'; break;
      case 'stock': bg = 'rgba(34,197,94,0.18)'; bd = 'rgba(34,197,94,0.5)'; break;
      case 'company': bg = 'rgba(148,163,184,0.16)'; bd = 'rgba(148,163,184,0.5)'; break;
      case 'land': case 'bigland': {
        if (land && land.owner >= 0) { bg = RM_TOKEN_COLORS[land.owner] + '3D'; bd = RM_TOKEN_COLORS[land.owner] + 'CC'; }
        else { bg = 'rgba(255,255,255,0.05)'; bd = 'rgba(255,255,255,0.16)'; }
        break;
      }
    }
    return { bg: bg, bd: bd };
  }
  function rmCellIcon(cell, land) {
    if (cell.type === 'start') return '🏁';
    if (cell.type === 'chance') return '❓';
    if (cell.type === 'destiny') return '❗';
    if (cell.type === 'bank') return '🏦';
    if (cell.type === 'tax') return '🏛️';
    if (cell.type === 'prison') return '🚓';
    if (cell.type === 'hospital') return '🏥';
    if (cell.type === 'shop') return '🛒';
    if (cell.type === 'stock') return '📈';
    if (cell.type === 'company') return cell.icon || '🏢';
    if (cell.type === 'bigland') return land && land.owner >= 0 ? (land.build !== 'none' ? RM_BIG_BUILDS[land.build].icon : '🏬') : '🏙️';
    // 普通地：房屋层数
    if (land && land.owner >= 0) {
      if (land.houses >= 5) return '🏰';
      if (land.houses >= 1) return '🏠'.repeat(Math.min(3, land.houses));
      return '🏠';
    }
    return '▫️';
  }
  // 格名压缩成 2~4 字，保证放大后的小格子里也能看清
  function rmCellShortName(cell) {
    switch (cell.type) {
      case 'start': return '起点';
      case 'chance': return '机会';
      case 'destiny': return '命运';
      case 'bank': return '银行';
      case 'tax': return '税务';
      case 'prison': return '监狱';
      case 'hospital': return '医院';
      case 'shop': return '商店';
      case 'stock': return '股市';
    }
    return cell.name.slice(0, 4);
  }
  function rmCellHTML(st, i, g) {
    const cell = RM_MAP[i];
    const land = st.lands[i];
    const sty = rmCellStyle(cell, land);
    const geo = rmCellGeo(i, g);
    const mk = String(i);
    const k = Math.max(0.72, Math.min(1.35, g.s / 32)); // 字号随格子实际边长缩放，小屏不糊、大屏更清楚
    const fs = function (base, min) { return Math.max(min || 5, Math.round(base * k * 10) / 10) + 'px'; };
    const fx = (st.cellEffects[mk] || []);
    let fxHTML = '';
    for (const e of fx) {
      const def = RM_ITEMS[e.type];
      if (def) fxHTML += '<span style="position:absolute;right:0.5px;bottom:0.5px;font-size:' + fs(7) + ';line-height:1;">' + def.icon + '</span>';
    }
    const moneyHTML = st.cellMoney[mk] ? '<span style="position:absolute;left:0.5px;top:0.5px;font-size:' + fs(7) + ';line-height:1;">💵</span>' : '';
    const godHTML = st.boardGods[mk] ? '<span style="position:absolute;left:0.5px;bottom:0.5px;font-size:' + fs(7) + ';line-height:1;">' + RM_GODS[st.boardGods[mk]].icon + '</span>' : '';
    const seizeHTML = land && land.seized ? '<span style="position:absolute;right:0.5px;top:0.5px;font-size:' + fs(7) + ';line-height:1;">🚫</span>' : '';
    const name = rmCellShortName(cell);
    const nameFont = fs(name.length >= 4 ? 7.4 : 9, 5.4);
    const sub = (function () {
      if ((cell.type === 'land' || cell.type === 'bigland') && land && land.owner >= 0) return rmFmtMoney(rmRent(st, i));
      if (cell.type === 'land' || cell.type === 'bigland') return rmFmtMoney(cell.price);
      if (cell.type === 'company') { const comp = st.companies[i]; return comp.owner >= 0 ? st.players[comp.owner].name.slice(0, 2) + '董' : rmFmtMoney(cell.price); }
      return '';
    })();
    const click = (cell.type === 'land' || cell.type === 'bigland' || cell.type === 'company') ? ' data-rm-act="rm-cell" data-cell="' + i + '"' : '';
    return '<div' + click + ' title="' + escapeHtml(cell.name) + '" style="position:absolute;left:' + (geo.x - geo.w / 2).toFixed(3) + '%;top:' + (geo.y - geo.h / 2).toFixed(3) + '%;width:' + geo.w.toFixed(3) + '%;height:' + geo.h.toFixed(3) + '%;background:' + sty.bg + ';border:1px solid ' + sty.bd + ';box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;cursor:pointer;user-select:none;z-index:3;">' +
      '<span style="font-size:' + fs(10.5) + ';line-height:1;">' + rmCellIcon(cell, land) + '</span>' +
      '<span style="font-size:' + nameFont + ';line-height:1.1;color:var(--ubp-text-2);margin-top:1px;white-space:nowrap;max-width:100%;overflow:hidden;">' + escapeHtml(name) + '</span>' +
      (sub ? '<span style="font-size:' + fs(7.4, 5) + ';line-height:1;color:var(--ubp-text-3);margin-top:0.5px;">' + escapeHtml(sub) + '</span>' : '') +
      moneyHTML + fxHTML + godHTML + seizeHTML +
      '</div>';
  }
  // 棋盘＝等宽等高格子围成的矩形外框，中间方框是全部游玩内容；高度超出屏幕时由外层滚动栏上下滚动查看上下边
  function rmBoardHTML(st, centerHTML) {
    const g = rmBoardGeom();
    let html = '';
    for (let i = 0; i < RM_MAP_LEN; i++) html += rmCellHTML(st, i, g);
    // 中央游玩面板：左右内缩一格宽、上下内缩一格高
    html += '<div style="position:absolute;left:' + g.cellW.toFixed(3) + '%;top:' + g.cellH.toFixed(3) + '%;width:' + (100 - g.cellW * 2).toFixed(3) + '%;height:' + (100 - g.cellH * 2).toFixed(3) + '%;background:var(--ubp-card, #1c1c20);border:1.5px solid var(--ubp-line);border-radius:10px;box-sizing:border-box;display:flex;flex-direction:column;overflow:hidden;z-index:2;">' + (centerHTML || '') + '</div>';
    // 棋子：角色头像（固定像素直径，保持正圆）
    const tokenPx = g.tokenPx;
    for (const p of st.players) {
      if (p.eliminated) continue;
      const pt = rmTokenXY(p, p.pos);
