      const isTurn = st.turnSeat === p.seat && st.phase !== 'ended';
      html += '<div data-rm-act="rm-token" data-seat="' + p.seat + '" title="' + escapeHtml(p.name) + (p.isUser ? '（我）' : '') + '" style="position:absolute;left:' + pt.x.toFixed(3) + '%;top:' + pt.y.toFixed(3) + '%;width:' + tokenPx + 'px;height:' + tokenPx + 'px;transform:translate(-50%,-50%);border-radius:50%;background:' + RM_TOKEN_COLORS[p.seat] + ';border:2px solid ' + (isTurn ? '#fff' : 'rgba(255,255,255,0.72)') + ';box-shadow:0 1px 4px rgba(0,0,0,.65)' + (isTurn ? ',0 0 0 2px ' + RM_TOKEN_COLORS[p.seat] : '') + ';overflow:hidden;display:flex;align-items:center;justify-content:center;z-index:8;transition:left .12s linear,top .12s linear;box-sizing:border-box;user-select:none;">' +
        (av ? '<img src="' + av + '" alt="" style="width:100%;height:100%;object-fit:cover;display:block;">' : '<span style="color:#fff;font-size:' + Math.round(tokenPx * 0.38) + 'px;font-weight:bold;line-height:1;">' + RM_TOKEN_LABEL[p.seat] + '</span>') +
