    return '<div style="position:relative;width:100%;padding-top:' + (g.L / g.T * 100).toFixed(4) + '%;">' +
      '<div style="position:absolute;inset:0;background:var(--ubp-card, #1c1c20);border:2px solid var(--ubp-line);border-radius:12px;overflow:hidden;box-sizing:border-box;">' + html + '</div></div>';
  }

