  function renderRmInviteOverlay(onConfirmed) {
    const cfg = loadRmConfig();
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    let chosen = (cfg.partnerNames || []).filter(function (n) { return n && contacts.some(function (c) { return isNameMatch(c.name, n); }); }).slice(0, 3);
    if (!chosen.length) for (const c of contacts) { if (chosen.length >= 3) break; if (!chosen.some(function (n) { return isNameMatch(n, c.name); })) chosen.push(c.name); }
    const ov = document.createElement('div');
    ov.className = 'rm-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = function () {
      const listHtml = contacts.map(function (c) {
        const idx = chosen.findIndex(function (n) { return isNameMatch(n, c.name); });
        const on = idx !== -1;
        const av = c.avatar || getCharacterAvatarByName(c.name);
        return '<div data-rm-pick-name="' + escapeHtml(c.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(14,165,233,0.16)' : 'var(--ubp-card-2, #26262a)') + ';border:1.5px solid ' + (on ? '#0EA5E9' : 'var(--ubp-line)') + ';">' +
          '<div style="width:36px;height:36px;border-radius:50%;background:#0EA5E9;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:14px;">' + escapeHtml(c.name.slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(c.name) + (on ? ' <span style="font-size:11px;color:#0EA5E9;">(座位' + (idx + 1) + ')</span>' : '') + '</div>' +
          (c.identity ? '<div style="font-size:11px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">' + escapeHtml(c.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:16px;color:#0EA5E9;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
        '<span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请角色入座（1~3 位）</span>' +
        '<button data-rm-invite="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#0EA5E9;">' + chosen.length + '</b> / 3 位（含你共 ' + (chosen.length + 1) + ' 人对局）</div>' +
        '<div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">' + (listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">通讯录暂无角色，请确保神·数据库已添加角色。</div>') + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-rm-invite="confirm" class="ubp-btn primary" style="padding:6px 20px;background:' + (chosen.length ? '#0EA5E9' : '#6b7280') + ';font-size:13px;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-rm-pick-name]').forEach(function (el) {
        el.addEventListener('click', function () {
          const name = el.getAttribute('data-rm-pick-name');
          const i = chosen.findIndex(function (n) { return isNameMatch(n, name); });
          if (i !== -1) chosen.splice(i, 1);
          else { if (chosen.length >= 3) chosen.shift(); chosen.push(name); }
          renderContent();
        });
      });
      const closeBtn = ov.querySelector('[data-rm-invite="close"]');
      if (closeBtn) closeBtn.addEventListener('click', function () { ov.remove(); });
      const okBtn = ov.querySelector('[data-rm-invite="confirm"]');
      if (okBtn) okBtn.addEventListener('click', function () {
        if (!chosen.length) { showToast('请至少邀请 1 位角色'); return; }
        const c = loadRmConfig();
        c.partnerNames = chosen.slice(0, 3);
        saveRmConfig(c);
        ov.remove();
        if (typeof onConfirmed === 'function') onConfirmed(chosen.slice(0, 3));
        else renderRmLobby();
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

