    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EDC22E;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:6px;">🎉</div>
        <div style="font-size:15.5px;font-weight:700;color:#EDC22E;margin-bottom:6px;">合成 2048 通关！</div>
        <div style="font-size:12.5px;color:var(--ubp-text-2);line-height:1.7;margin-bottom:14px;">
          积分 <b style="color:#F59E0B;">+1</b>（当前 💎 ${loadPoints()}）· 得分 <b style="color:#38BDF8;">${g.score}</b><br>
          可继续挑战 4096 / 8192 等更高数字
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="g2048-continue" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#EDC22E;border:none;color:#3C3A32;border-radius:10px;cursor:pointer;">► 继续挑战</button>
          <button data-ubp-act="g2048-restart" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
        </div>
        <div style="margin-top:8px;">
          <button data-ubp-act="g2048-exit" class="ubp-btn" style="width:100%;padding:8px 0;font-size:12px;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function g2048GameOver(g) {
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('2048'); } } catch (e) { /* ignore */ }
    g2048ClearSave();
    const stage = sheet ? sheet.querySelector('#g2048-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.g2048-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    const best = Math.max(startBest, g.score);
    if (g.score > g2048LoadBest()) g2048SaveBest(g.score);
    const ov = document.createElement('div');
    ov.className = 'g2048-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EF4444;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : '游戏结束'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#38BDF8;font-size:17px;">${g.score}</b><br>
          步数：<b style="color:#F59E0B;">${g.moves}</b><br>
          最高分：<b style="color:#F59E0B;">${Math.max(best, g.score)}</b><br>
          最大方块：<b style="color:#F59E0B;">${g2048MaxTile(g)}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="g2048-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#38BDF8;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="g2048-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">棋盘占满且四方向都无法滑动时结束</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function g2048MaxTile(g) {
    let m = 0;
    for (const t of g.tiles) if (t.v > m) m = t.v;
    return m || '-';
  }

  function g2048AttachInput(g) {
    // 键盘方向键（输入框 / 文本框聚焦时自动忽略）
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      const dir = map[e.key];
      if (!dir) return;
      e.preventDefault();
      g2048Move(dir);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      // 方向按钮
      sheet.querySelectorAll('[data-g2048-dir]').forEach(btn => {
        btn.addEventListener('click', (e) => { e.preventDefault(); g2048Move(btn.dataset.g2048Dir); });
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      // 滑动棋盘
      const board = g.boardEl;
      if (board) {
        let sx = 0;
        let sy = 0;
        let tracking = false;
        const start = (x, y) => { sx = x; sy = y; tracking = true; };
        const finish = (x, y) => {
          if (!tracking) return;
          tracking = false;
          const dx = x - sx;
          const dy = y - sy;
          if (Math.max(Math.abs(dx), Math.abs(dy)) < 24) return;
          if (Math.abs(dx) > Math.abs(dy)) g2048Move(dx > 0 ? 'right' : 'left');
          else g2048Move(dy > 0 ? 'down' : 'up');
        };
        if (typeof window.PointerEvent !== 'undefined') {
          board.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            try { board.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
            start(e.clientX, e.clientY);
          });
          board.addEventListener('pointerup', (e) => { e.preventDefault(); finish(e.clientX, e.clientY); });
          board.addEventListener('pointercancel', () => { tracking = false; });
          board.addEventListener('contextmenu', (e) => e.preventDefault());
        } else {
          board.addEventListener('touchstart', (e) => { if (e.touches[0]) start(e.touches[0].clientX, e.touches[0].clientY); });
          board.addEventListener('touchend', (e) => { if (e.changedTouches[0]) finish(e.changedTouches[0].clientX, e.changedTouches[0].clientY); });
          board.addEventListener('mousedown', (e) => start(e.clientX, e.clientY));
          board.addEventListener('mouseup', (e) => finish(e.clientX, e.clientY));
        }
      }
    }
    // 面板尺寸自适应
    if (typeof ResizeObserver !== 'undefined') {
      try {
        g._ro = new ResizeObserver(() => g2048Resize());
        if (g.stageEl) g._ro.observe(g.stageEl);
      } catch (e) { /* ignore */ }
    }
    g._onWinResize = () => g2048Resize();
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __G2048_ENGINE_END__

  // __SUIKA_ENGINE_BEGIN__
  // ========== 合成大西瓜（水果下落合并 · 拖动 / 滑动选择落点 · 松手投放） ==========
  // 规则：顶部待投放水果可左右移动选择落点，松手 / 点击垂直落下；两个相同水果接触立刻合并为下一级，
  //       合并会连锁触发：葡萄→樱桃→橘子→柠檬→猕猴桃→番茄→桃子→菠萝→椰子→西瓜；
  //       每次投放的水果从低级水果（葡萄~猕猴桃）随机生成，并提前预览下一个；
  //       合成出西瓜达成目标 +1 积分（每局一次），游戏不结束可继续刷分；原版规则两个西瓜不会继续合并；
  //       任意水果静止后仍越过顶部红线即本局结束（下落途中短暂经过不算）。
  // 说明：本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const SUIKA_BEST_KEY = 'werewolf_extension_suika_best';
  const SUIKA_PENDING_Y = 38;
  const SUIKA_GRAVITY = 2400;
  const SUIKA_EMOJI = ['🍇', '🍒', '🍊', '🍋', '🥝', '🍅', '🍑', '🍍', '🥥', '🍉'];
  const SUIKA_NAMES = ['葡萄', '樱桃', '橘子', '柠檬', '猕猴桃', '番茄', '桃子', '菠萝', '椰子', '西瓜'];
  const SUIKA_COLORS = ['#8E44AD', '#E74C3C', '#E67E22', '#F1C40F', '#8DA845', '#D64541', '#F5A9A9', '#E9C46A', '#B08968', '#2ECC71'];
  // 各级半径 = 比例 × 画布宽度（比例基准宽度 360）
  const SUIKA_RATIOS = [0.048, 0.057, 0.068, 0.080, 0.092, 0.104, 0.117, 0.131, 0.146, 0.163];
  // 合成得分（三角数）：合成出樱桃 +1、橘子 +3、柠檬 +6 …… 西瓜 +45
  const SUIKA_GAIN = [0, 1, 3, 6, 10, 15, 21, 28, 36, 45];
  const SUIKA_NEXT_WEIGHTS = [0.30, 0.26, 0.20, 0.14, 0.10];

  let suikaGame = null;
  const suikaRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const suikaCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function suikaLoadBest() {
    try { const n = parseInt(localStorage.getItem(SUIKA_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function suikaSaveBest(n) {
    try { localStorage.setItem(SUIKA_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function suikaRadius(g, level) {
    return SUIKA_RATIOS[level] * (g.W || 380);
  }
  function suikaRandomNextLevel() {
    const r = Math.random();
    let acc = 0;
    for (let i = 0; i < SUIKA_NEXT_WEIGHTS.length; i++) {
      acc += SUIKA_NEXT_WEIGHTS[i];
      if (r < acc) return i;
    }
    return 0;
  }
  function suikaMakeFruit(g, level, x, y) {
    const r = suikaRadius(g, level);
    return { id: g.nextId++, level, x, y, vx: 0, vy: 0, r, inv: 1 / (r * r), omega: 0, rot: 0, appear: 0 };
  }

  const SUIKA_SAVE_KEY = 'werewolf_extension_suika_save';
  function suikaHasSave() { try { const raw = localStorage.getItem(SUIKA_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && (d.score > 0 || d.drops > 0 || (d.fruits && d.fruits.length > 0))); } catch (e) { return false; } }
  function suikaClearSave() { try { localStorage.removeItem(SUIKA_SAVE_KEY); } catch (e) { /* ignore */ } }
  function suikaSaveGame(g) {
    try {
      if (!g || g.over) { suikaClearSave(); return false; }
      localStorage.setItem(SUIKA_SAVE_KEY, JSON.stringify({
        v: 1, score: g.score, drops: g.drops, merges: g.merges, maxLevel: g.maxLevel, won: g.won, rewarded: g.rewarded,
        pendingLevel: g.pendingLevel, previewLevel: g.previewLevel, W: g.W,
        fruits: g.fruits.map(f => ({ level: f.level, x: f.x, y: f.y, vx: f.vx, vy: f.vy, rot: f.rot, omega: f.omega }))
      }));
      return true;
    } catch (e) { return false; }
  }
  function suikaResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(SUIKA_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data) { suikaOpenGame(); return; }
    suikaOpenGame(data);
    showToast('🔖 已恢复进行中的合成大西瓜（得分 ' + (data.score || 0) + '）');
  }

  function suikaOpenGame(saveData) {
    suikaTeardown(false);
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      fruits: [],
      nextId: 1,
      score: 0,
      startBest: suikaLoadBest(),
      drops: 0,
      merges: 0,
      maxLevel: -1,
      won: false,
      rewarded: false,
      over: false,
      paused: false,
      overTimer: 0,
      dropLock: 0,
      aimX: 0,
      aimInit: false,
      pressing: false,
      pendingLevel: suikaRandomNextLevel(),
      previewLevel: suikaRandomNextLevel(),
      W: 380,
      H: 520,
      lineY: 84,
      accum: 0,
      time: 0,
      particles: [],
      floats: [],
      canvas: null,
      stageEl: null,
      rafId: 0,
      lastTs: 0,
      doc: null,
      keyHandler: null,
      _onWinResize: null,
      _ro: null
    };
    if (saveData && saveData.fruits) {
      g.score = saveData.score || 0;
      g.drops = saveData.drops || 0;
      g.merges = saveData.merges || 0;
      g.maxLevel = (saveData.maxLevel === undefined || saveData.maxLevel === null) ? -1 : saveData.maxLevel;
      g.won = !!saveData.won;
      g.rewarded = !!saveData.rewarded;
      g.pendingLevel = (saveData.pendingLevel >= 0 && saveData.pendingLevel <= 4) ? saveData.pendingLevel : suikaRandomNextLevel();
      g.previewLevel = (saveData.previewLevel >= 0 && saveData.previewLevel <= 4) ? saveData.previewLevel : suikaRandomNextLevel();
      if (saveData.W) g.W = saveData.W;
      for (const f of saveData.fruits) {
        const nf = suikaMakeFruit(g, Math.max(0, Math.min(9, f.level || 0)), f.x, f.y);
        nf.vx = f.vx || 0;
        nf.vy = f.vy || 0;
        nf.rot = f.rot || 0;
        nf.omega = f.omega || 0;
        nf.x = Math.max(nf.r, Math.min(g.W - nf.r, nf.x));
        nf.y = Math.max(nf.r, Math.min(g.H - nf.r, nf.y));
        g.fruits.push(nf);
      }
      g._rescaleW = saveData.W || g.W;
    }
    suikaGame = g;
    suikaRenderUI();
    suikaAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = suikaRaf(suikaTick);
  }

  function suikaTeardown(renderLobby) {
    const g = suikaGame;
    suikaGame = null;
    if (g) {
      if (g.rafId) suikaCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._ro) { try { g._ro.disconnect(); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function suikaExitToLobby() {
    const saved = !!(suikaGame && suikaSaveGame(suikaGame));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    suikaTeardown(true);
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }
  function suikaQuitToCenter() {
    suikaClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    suikaTeardown(false);
    renderSetup();
    showToast('🚪 已结束本局合成大西瓜');
  }

  function suikaRenderUI() {
    const g = suikaGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = suikaLoadBest();
    sheet.innerHTML = `
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="suika-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🍉 合成大西瓜</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="suika-points-label">${pointsLabelHTML()}</span>
            <span id="suika-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="suika-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏入口（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="suika-score-text" style="color:#FBBF24;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="suika-max-text" style="font-size:12px;color:var(--ubp-text-2);">最大: <b style="color:#F59E0B;">—</b></div>
          <div id="suika-next-text" style="font-size:12px;color:var(--ubp-text-2);">下一个: <b id="suika-next-emoji" style="font-size:14px;">🍇</b></div>
        </div>
        <div id="suika-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#0E3A46;">
          <canvas id="suika-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;line-height:1.6;">按住 / 拖动选择落点 · 松手投放 · 相同水果相撞合并<br>合成西瓜 +1 积分（每局一次）· 水果静止后越过红线本局结束</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#suika-stage');
    g.canvas = sheet.querySelector('#suika-canvas');
    suikaUpdateHud(g);
  }

  function suikaUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#suika-score-text');
    if (s) s.textContent = String(g.score);
    const mx = sheet.querySelector('#suika-max-text');
    if (mx) {
      if (g.maxLevel >= 0) mx.innerHTML = '最大: <b style="color:#F59E0B;">' + SUIKA_EMOJI[g.maxLevel] + ' ' + SUIKA_NAMES[g.maxLevel] + '</b>';
      else mx.innerHTML = '最大: <b style="color:#F59E0B;">—</b>';
    }
    const nx = sheet.querySelector('#suika-next-emoji');
    if (nx) nx.textContent = SUIKA_EMOJI[g.previewLevel];
    const best = suikaLoadBest();
    if (g.score > best) suikaSaveBest(g.score);
    const bl = sheet.querySelector('#suika-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
  }

  function suikaDrop() {
    const g = suikaGame;
    if (!g || g.over || g.paused || g.dropLock > 0 || g.pendingLevel < 0) return null;
    if (!g.canvas || !g.canvas.isConnected) { suikaTeardown(true); return null; }
    const r = suikaRadius(g, g.pendingLevel);
    const x = Math.max(r + 2, Math.min(g.W - r - 2, g.aimInit ? g.aimX : g.W / 2));
    const f = suikaMakeFruit(g, g.pendingLevel, x, SUIKA_PENDING_Y + 4);
    g.fruits.push(f);
    g.drops += 1;
    g.dropLock = 0.35;
    g.pendingLevel = g.previewLevel;
    g.previewLevel = suikaRandomNextLevel();
    suikaUpdateHud(g);
    return f;
  }

  function suikaTick(ts) {
    const g = suikaGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { suikaTeardown(false); return; }
    const dtReal = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    g.time += dtReal;
    if (!g.paused && !g.over) {
      if (g.dropLock > 0) g.dropLock = Math.max(0, g.dropLock - dtReal);
      g.accum += dtReal;
      const STEP = 1 / 120;
      let steps = 0;
      while (g.accum >= STEP && steps < 10 && !g.paused && !g.over) {
        suikaPhysicsStep(g, STEP);
        g.accum -= STEP;
        steps++;
      }
      if (steps >= 10) g.accum = 0;
    }
    // 粒子 / 飘字
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const p = g.particles[i];
      p.x += p.vx * dtReal;
      p.y += p.vy * dtReal;
      p.vy += 900 * dtReal;
      p.life -= dtReal;
      if (p.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.y += ft.vy * dtReal;
      ft.life -= dtReal;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
    suikaDraw();
    g.rafId = suikaRaf(suikaTick);
  }

  // 一步物理（固定步长）：重力 → 位置积分 → 多次约束求解（墙壁 / 圆-圆碰撞）→ 合并 → 出局检测
  function suikaPhysicsStep(g, dt) {
    const fruits = g.fruits;
    for (const f of fruits) {
      f.vy += SUIKA_GRAVITY * dt;
      f.vx *= 0.999;
      f.vy *= 0.999;
      const sp = Math.sqrt(f.vx * f.vx + f.vy * f.vy);
      if (sp > 3500) { f.vx *= 3500 / sp; f.vy *= 3500 / sp; }
      f.x += f.vx * dt;
      f.y += f.vy * dt;
      f.rot += f.omega * dt;
      f.omega *= 0.995;
      if (f.omega > 9) f.omega = 9;
      if (f.omega < -9) f.omega = -9;
      if (f.appear > 0) f.appear = Math.max(0, f.appear - dt * 5);
    }
    const ITER = 5;
    for (let it = 0; it < ITER; it++) {
      for (const f of fruits) {
        if (f.x - f.r < 0) { f.x = f.r; if (f.vx < 0) f.vx = -f.vx * 0.1; }
        if (f.x + f.r > g.W) { f.x = g.W - f.r; if (f.vx > 0) f.vx = -f.vx * 0.1; }
        if (f.y + f.r > g.H) {
          f.y = g.H - f.r;
          if (f.vy > 0) f.vy = -f.vy * 0.05;
          f.vx *= 0.94;
          f.omega += (f.vx / f.r - f.omega) * 0.3;
          if (Math.abs(f.vx) < 4) f.vx *= 0.8;
        }
      }
      for (let i = 0; i < fruits.length; i++) {
        const a = fruits[i];
        for (let j = i + 1; j < fruits.length; j++) {
          const b = fruits[j];
          const dx = b.x - a.x;
          const dy = b.y - a.y;
          const rr = a.r + b.r;
          const d2 = dx * dx + dy * dy;
          if (d2 >= rr * rr || d2 < 1e-9) continue;
          const d = Math.sqrt(d2);
          const nx = dx / d;
          const ny = dy / d;
          const overlap = rr - d;
          const invSum = a.inv + b.inv;
          const ca = a.inv / invSum;
          const cb = b.inv / invSum;
          a.x -= nx * overlap * ca;
          a.y -= ny * overlap * ca;
          b.x += nx * overlap * cb;
          b.y += ny * overlap * cb;
          const rvx = b.vx - a.vx;
          const rvy = b.vy - a.vy;
          const vn = rvx * nx + rvy * ny;
          if (vn < 0) {
            const jimp = -(1 + 0.06) * vn / invSum;
            a.vx -= jimp * nx * a.inv;
            a.vy -= jimp * ny * a.inv;
            b.vx += jimp * nx * b.inv;
            b.vy += jimp * ny * b.inv;
            const tx = -ny;
            const ty = nx;
            const vt = rvx * tx + rvy * ty;
            const jt = -vt * 0.16 / invSum;
            a.vx -= jt * tx * a.inv;
            a.vy -= jt * ty * a.inv;
            b.vx += jt * tx * b.inv;
            b.vy += jt * ty * b.inv;
            a.omega -= (vt / Math.max(8, a.r)) * 0.25;
            b.omega += (vt / Math.max(8, b.r)) * 0.25;
          }
        }
      }
    }
    // 合并（同一水果每轮最多合并一次；一轮内允许连锁，最多 3 轮）
    let pass = 0;
    let merged = true;
    while (merged && pass < 3) {
      merged = false;
      pass++;
      const queue = [];
      const dead = new Set();
      for (let i = 0; i < fruits.length; i++) {
        const a = fruits[i];
        if (dead.has(a) || a.level >= 9) continue;
        for (let j = i + 1; j < fruits.length; j++) {
          const b = fruits[j];
          if (dead.has(b) || b.level !== a.level) continue;
          const dx = b.x - a.x;
          const dy = b.y - a.y;
          const rr = a.r + b.r + 1;
          if (dx * dx + dy * dy <= rr * rr) {
            dead.add(a);
            dead.add(b);
            queue.push([a, b]);
            break;
          }
        }
      }
      for (const pair of queue) {
        suikaMergeFruits(g, pair[0], pair[1]);
        merged = true;
      }
    }
    suikaCheckGameOver(g, dt);
  }

  function suikaMergeFruits(g, a, b) {
    const ia = g.fruits.indexOf(a);
    if (ia >= 0) g.fruits.splice(ia, 1);
    const ib = g.fruits.indexOf(b);
    if (ib >= 0) g.fruits.splice(ib, 1);
    const level = a.level + 1;
    const x = (a.x + b.x) / 2;
    const y = (a.y + b.y) / 2;
    const f = suikaMakeFruit(g, level, x, y);
    f.vx = (a.vx + b.vx) * 0.25;
    f.vy = (a.vy + b.vy) * 0.25 - 30;
    f.appear = 1;
    g.fruits.push(f);
    const gain = SUIKA_GAIN[level] || 10;
    g.score += gain;
    g.merges += 1;
    g.maxLevel = Math.max(g.maxLevel, level);
    suikaBurst(g, x, y, SUIKA_COLORS[level]);
    suikaFloat(g, x, y - f.r - 6, '+' + gain);
    if (level === 9 && !g.won) {
      g.won = true;
      if (!g.rewarded) {
        g.rewarded = true;
        addPoints(1);
        const pl = sheet ? sheet.querySelector('#suika-points-label') : null;
        if (pl) pl.innerHTML = pointsLabelHTML();
      }
      g.paused = true;
      suikaShowVictory(g);
    }
    suikaUpdateHud(g);
  }

  // 出局检测：任意水果静止后顶部仍越过红线，持续 1.2 秒即结束（下落途中短暂经过不算）
  function suikaCheckGameOver(g, dt) {
    if (g.over) return;
    let violation = false;
    for (const f of g.fruits) {
      const speed = Math.sqrt(f.vx * f.vx + f.vy * f.vy);
      if (f.y - f.r < g.lineY - 2 && speed < 70) { violation = true; break; }
    }
    if (violation) {
      g.overTimer += dt;
      if (g.overTimer >= 1.2) {
        g.over = true;
        g.paused = true;
        suikaGameOver(g);
      }
    } else {
      g.overTimer = 0;
    }
  }

  function suikaBurst(g, x, y, color) {
    for (let i = 0; i < 12; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = 60 + Math.random() * 180;
      g.particles.push({ x, y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp - 60, life: 0.45 + Math.random() * 0.3, r: 1.5 + Math.random() * 2.4, color });
    }
  }
  function suikaFloat(g, x, y, text) {
    g.floats.push({ x, y, text, life: 0.9, vy: -40 });
  }

  function suikaContinue() {
    const g = suikaGame;
    if (!g) return;
    if (sheet) sheet.querySelectorAll('.suika-overlay').forEach(el => el.remove());
    g.paused = false;
    g.accum = 0;
    g.lastTs = performance.now();
    showToast('🎮 继续挑战！合成更多西瓜刷更高分');
  }

  function suikaShowVictory(g) {
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('合成大西瓜'); } } catch (e) { /* ignore */ }
    const stage = sheet ? sheet.querySelector('#suika-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.suika-overlay').forEach(el => el.remove());
    const ov = document.createElement('div');
    ov.className = 'suika-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #2ECC71;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:40px;margin-bottom:6px;">🍉</div>
        <div style="font-size:15.5px;font-weight:700;color:#2ECC71;margin-bottom:6px;">合成西瓜达成目标！</div>
        <div style="font-size:12.5px;color:var(--ubp-text-2);line-height:1.7;margin-bottom:14px;">
          积分 <b style="color:#F59E0B;">+1</b>（当前 💎 ${loadPoints()}）· 得分 <b style="color:#FBBF24;">${g.score}</b><br>
          游戏不会结束，可继续投放合成更多西瓜刷高分
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="suika-continue" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#2ECC71;border:none;color:#fff;border-radius:10px;cursor:pointer;">► 继续挑战</button>
          <button data-ubp-act="suika-restart" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
        </div>
        <div style="margin-top:8px;">
          <button data-ubp-act="suika-exit" class="ubp-btn" style="width:100%;padding:8px 0;font-size:12px;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function suikaGameOver(g) {
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('合成大西瓜'); } } catch (e) { /* ignore */ }
    suikaClearSave();
    const stage = sheet ? sheet.querySelector('#suika-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.suika-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    if (g.score > suikaLoadBest()) suikaSaveBest(g.score);
    const maxLabel = g.maxLevel >= 0 ? (SUIKA_EMOJI[g.maxLevel] + ' ' + SUIKA_NAMES[g.maxLevel]) : '—';
    const ov = document.createElement('div');
    ov.className = 'suika-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EF4444;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : '水果越过红线，本局结束'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#FBBF24;font-size:17px;">${g.score}</b><br>
          最大水果：<b style="color:#F59E0B;">${maxLabel}</b><br>
          投放 ${g.drops} 次 · 合并 ${g.merges} 次<br>
          最高分：<b style="color:#F59E0B;">${Math.max(startBest, g.score)}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="suika-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#FBBF24;border:none;color:#3C2A00;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="suika-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">水果静止后仍越过顶部红线即结束（下落途中短暂经过不算）</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function suikaDraw() {
    const g = suikaGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.W = cssW;
    g.H = cssH;
    g.lineY = Math.max(64, Math.min(112, Math.round(cssH * 0.16)));
    if (!g.aimInit) { g.aimX = cssW / 2; g.aimInit = true; }
    if (g._rescaleW && Math.abs(cssW - g._rescaleW) > 1) {
      const k = cssW / g._rescaleW;
      for (const f of g.fruits) {
        f.r = f.r * k;
        f.inv = 1 / (f.r * f.r);
        f.x = Math.max(f.r, Math.min(cssW - f.r, f.x * k));
        f.y = Math.max(f.r, Math.min(cssH - f.r, f.y));
      }
      if (g.aimInit) g.aimX = Math.max(0, Math.min(cssW, g.aimX * k));
      g._rescaleW = 0;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);
    // 背景（水色渐变）
    const bg = ctx.createLinearGradient(0, 0, 0, cssH);
    bg.addColorStop(0, '#0E3A46');
    bg.addColorStop(0.55, '#123A58');
    bg.addColorStop(1, '#0B2440');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);
    // 底部微光
    const bottomGlow = ctx.createLinearGradient(0, cssH - 90, 0, cssH);
    bottomGlow.addColorStop(0, 'rgba(94,234,212,0)');
    bottomGlow.addColorStop(1, 'rgba(94,234,212,0.08)');
    ctx.fillStyle = bottomGlow;
    ctx.fillRect(0, cssH - 90, cssW, 90);
    // 侧壁
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(0, 0, 3, cssH);
    ctx.fillRect(cssW - 3, 0, 3, cssH);
    // 红线（危险时闪烁加强）
    const danger = Math.min(1, g.overTimer / 1.2);
    ctx.save();
    ctx.setLineDash([9, 7]);
    ctx.lineWidth = 2.5;
    const blink = 0.62 + 0.18 * Math.sin(g.time * 4);
    ctx.strokeStyle = 'rgba(239,68,68,' + Math.min(1, blink + danger * 0.38).toFixed(2) + ')';
    ctx.beginPath();
    ctx.moveTo(6, g.lineY);
    ctx.lineTo(cssW - 6, g.lineY);
    ctx.stroke();
    ctx.restore();
    if (danger > 0.03) {
      ctx.fillStyle = 'rgba(239,68,68,' + (danger * 0.1).toFixed(2) + ')';
      ctx.fillRect(0, 0, cssW, cssH);
    }
    // 待投放水果 + 落点参考线
    if (!g.over && !g.paused && g.pendingLevel >= 0) {
      const pr = suikaRadius(g, g.pendingLevel);
      const px = Math.max(pr + 2, Math.min(cssW - pr - 2, g.aimX));
      ctx.save();
      ctx.setLineDash([5, 7]);
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(px, SUIKA_PENDING_Y + pr);
      ctx.lineTo(px, cssH - 4);
      ctx.stroke();
      ctx.restore();
      suikaDrawFruit(ctx, g, { x: px, y: SUIKA_PENDING_Y + Math.sin(g.time * 3) * 1.5, r: pr, level: g.pendingLevel, rot: 0, appear: 0 }, 0.95);
    }
    // 水果（按 y 排序，下方的先画）
    const sorted = g.fruits.slice().sort((a, b) => a.y - b.y);
    for (const f of sorted) suikaDrawFruit(ctx, g, f, 1);
    // 粒子
    for (const p of g.particles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, p.life / 0.5));
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      ctx.globalAlpha = Math.max(0, Math.min(1, ft.life / 0.9));
      ctx.font = '700 14px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      ctx.strokeText(ft.text, ft.x, ft.y);
      ctx.fillStyle = '#FBBF24';
      ctx.fillText(ft.text, ft.x, ft.y);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
  }

  function suikaDrawFruit(ctx, g, f, alpha) {
    const r = f.r * (1 + 0.28 * (f.appear || 0));
    const color = SUIKA_COLORS[f.level] || '#2ECC71';
    ctx.globalAlpha = alpha;
    // 圆体
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(f.x, f.y, r, 0, Math.PI * 2);
    ctx.fill();
    // 果肉高光
    const grad = ctx.createRadialGradient(f.x - r * 0.32, f.y - r * 0.38, r * 0.12, f.x, f.y, r);
    grad.addColorStop(0, 'rgba(255,255,255,0.45)');
    grad.addColorStop(0.45, 'rgba(255,255,255,0.08)');
    grad.addColorStop(1, 'rgba(0,0,0,0.16)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(f.x, f.y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.35)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(f.x, f.y, r - 0.75, 0, Math.PI * 2);
    ctx.stroke();
    // 表情（滚动旋转）
    ctx.save();
    ctx.translate(f.x, f.y);
    if (f.rot) ctx.rotate(f.rot);
    ctx.font = Math.round(r * 1.9) + 'px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(SUIKA_EMOJI[f.level] || '🍉', 0, r * 0.05);
    ctx.restore();
    ctx.textBaseline = 'alphabetic';
    ctx.globalAlpha = 1;
  }

  function suikaAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        e.preventDefault();
        const step = e.key === 'ArrowLeft' ? -14 : 14;
        const r = suikaRadius(g, g.pendingLevel >= 0 ? g.pendingLevel : 0);
        g.aimX = Math.max(r + 2, Math.min(g.W - r - 2, (g.aimInit ? g.aimX : g.W / 2) + step));
        g.aimInit = true;
      } else if (e.key === 'ArrowDown' || e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        suikaDrop();
      }
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    const cv = g.canvas;
    if (cv) {
      const toX = (clientX) => {
        try {
          const rect = cv.getBoundingClientRect();
          return clientX - rect.left;
        } catch (e) { return clientX; }
      };
      cv.addEventListener('contextmenu', (e) => e.preventDefault());
      if (typeof window.PointerEvent !== 'undefined') {
        cv.addEventListener('pointerdown', (e) => {
          e.preventDefault();
          g.pressing = true;
          g.aimX = toX(e.clientX);
          g.aimInit = true;
          try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
        });
        cv.addEventListener('pointermove', (e) => {
          if (e.pointerType === 'touch' && !g.pressing) return;
          g.aimX = toX(e.clientX);
          g.aimInit = true;
        });
        cv.addEventListener('pointerup', (e) => {
          g.aimX = toX(e.clientX);
          g.aimInit = true;
          if (!g.pressing) return;
          g.pressing = false;
          suikaDrop();
        });
        cv.addEventListener('pointercancel', () => { g.pressing = false; });
      } else {
        cv.addEventListener('touchstart', (e) => { if (e.touches[0]) { g.pressing = true; g.aimX = toX(e.touches[0].clientX); g.aimInit = true; } });
        cv.addEventListener('touchmove', (e) => { if (e.touches[0]) { g.aimX = toX(e.touches[0].clientX); g.aimInit = true; } });
        cv.addEventListener('touchend', () => { if (g.pressing) { g.pressing = false; suikaDrop(); } });
        cv.addEventListener('mousemove', (e) => { g.aimX = toX(e.clientX); g.aimInit = true; });
        cv.addEventListener('mousedown', (e) => { g.pressing = true; g.aimX = toX(e.clientX); g.aimInit = true; });
        cv.addEventListener('mouseup', (e) => { g.aimX = toX(e.clientX); g.aimInit = true; if (g.pressing) { g.pressing = false; suikaDrop(); } });
      }
    }
    if (typeof ResizeObserver !== 'undefined') {
      try {
        g._ro = new ResizeObserver(() => { /* 尺寸由绘制循环自适应 */ });
        if (g.stageEl) g._ro.observe(g.stageEl);
      } catch (e) { /* ignore */ }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __SUIKA_ENGINE_END__

  // __SNAKE_ENGINE_BEGIN__
  // ========== 贪吃蛇（20×20 网格 · 自动前进 · 方向键 / 方向按钮 / 滑动转向 · 加速 + 可选穿墙） ==========
  // 规则：开局 3 节，地图随机刷 1 个食物；吃到食物 +10 分并变长一节，随后在空白格重刷食物；
  //       蛇不能直接掉头（向右时按左无效，只能转上/下）；蛇持续朝当前方向自动移动，不是按一次动一格；
  //       撞墙（或开启穿墙时穿到对面）与撞到自己身体即结束；无尽模式，吃得越多移动越快；
  //       自选变体：底部可开关「穿墙」（经典诺基亚）；每累计 100 分自动 +1 积分。
  // 说明：本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const SNAKE_BEST_KEY = 'werewolf_extension_snake_best';
  const SNAKE_SAVE_KEY = 'werewolf_extension_snake_save';
  const SNAKE_WRAP_KEY = 'werewolf_extension_snake_wrap';
  const SNAKE_ACCEL_KEY = 'werewolf_extension_snake_accel';
  const SNAKE_GRID = 20;
  const SNAKE_START_LEN = 3;
  const SNAKE_BASE_MS = 175;        // 初始移动间隔（毫秒）
  const SNAKE_MIN_MS = 65;          // 最快移动间隔
  const SNAKE_SPEEDUP_PER_FOOD = 5; // 每吃 1 个食物提速
  const SNAKE_FOOD_SCORE = 10;
  const SNAKE_REWARD_STEP = 100;    // 每累计 100 分 +1 积分
  const SNAKE_DIRS = { up: { r: -1, c: 0 }, down: { r: 1, c: 0 }, left: { r: 0, c: -1 }, right: { r: 0, c: 1 } };

  let snakeGame = null;
  const snakeRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const snakeCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function snakeLoadBest() {
    try { const n = parseInt(localStorage.getItem(SNAKE_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function snakeSaveBest(n) {
    try { localStorage.setItem(SNAKE_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function snakeLoadWrap() {
    try { return localStorage.getItem(SNAKE_WRAP_KEY) === '1'; } catch (e) { return false; }
  }
  function snakeSaveWrap(v) {
    try { localStorage.setItem(SNAKE_WRAP_KEY, v ? '1' : '0'); } catch (e) { /* ignore */ }
  }
  function snakeLoadAccel() {
    try { const v = localStorage.getItem(SNAKE_ACCEL_KEY); return v === null ? true : v === '1'; } catch (e) { return true; }
  }
  function snakeSaveAccel(v) {
    try { localStorage.setItem(SNAKE_ACCEL_KEY, v ? '1' : '0'); } catch (e) { /* ignore */ }
  }
  function snakeTickMs(g) {
    if (g.accel === false) return SNAKE_BASE_MS; // 关闭加速：保持恒速
    return Math.max(SNAKE_MIN_MS, SNAKE_BASE_MS - (g.eaten || 0) * SNAKE_SPEEDUP_PER_FOOD);
  }
  function snakeHasSave() {
    try { const raw = localStorage.getItem(SNAKE_SAVE_KEY); if (!raw) return false; const d = JSON.parse(raw); return !!(d && !d.over && Array.isArray(d.body) && d.body.length >= SNAKE_START_LEN); } catch (e) { return false; }
  }
  function snakeClearSave() { try { localStorage.removeItem(SNAKE_SAVE_KEY); } catch (e) { /* ignore */ } }
  function snakeSaveGame(g) {
    try {
      if (!g || g.over) { snakeClearSave(); return false; }
      localStorage.setItem(SNAKE_SAVE_KEY, JSON.stringify({
        v: 1, body: g.snake, dir: g.dir, food: g.food, score: g.score, eaten: g.eaten,
        rewards: g.rewards, nextRewardAt: g.nextRewardAt, wrap: g.wrap, accel: g.accel !== false, over: false
      }));
      return true;
    } catch (e) { return false; }
  }
  function snakeResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(SNAKE_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !Array.isArray(data.body) || data.body.length < SNAKE_START_LEN) { snakeOpenGame(); return; }
    snakeOpenGame(data);
    showToast('🔖 已恢复进行中的贪吃蛇（得分 ' + (data.score || 0) + '）');
  }

  // 打开 / 重开一局（saveData 存在时恢复存档）
  function snakeOpenGame(saveData) {
    snakeTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const mid = Math.floor(SNAKE_GRID / 2);
    const g = {
      snake: [],
      dir: 'right',
      pending: [],
      food: { r: mid, c: mid + 4 },
      score: 0,
      startBest: snakeLoadBest(),
      eaten: 0,
      rewards: 0,
      nextRewardAt: SNAKE_REWARD_STEP,
      wrap: snakeLoadWrap(),
      accel: snakeLoadAccel(),
      over: false,
      ended: false,
      time: 0,
      lastTs: 0,
      accum: 0,
      shake: 0,
      pop: 0,
      particles: [],
      floats: [],
      canvas: null,
      stageEl: null,
      rafId: 0,
      doc: null,
      keyHandler: null,
      _onWinResize: null
    };
    if (saveData && Array.isArray(saveData.body) && saveData.body.length >= SNAKE_START_LEN) {
      g.snake = saveData.body.map(s => ({ r: Math.max(0, Math.min(SNAKE_GRID - 1, s.r | 0)), c: Math.max(0, Math.min(SNAKE_GRID - 1, s.c | 0)) }));
      g.dir = SNAKE_DIRS[saveData.dir] ? saveData.dir : 'right';
      g.food = (saveData.food && Number.isFinite(saveData.food.r) && Number.isFinite(saveData.food.c))
        ? { r: Math.max(0, Math.min(SNAKE_GRID - 1, saveData.food.r | 0)), c: Math.max(0, Math.min(SNAKE_GRID - 1, saveData.food.c | 0)) }
        : { r: mid, c: mid + 4 };
      g.score = saveData.score || 0;
      g.eaten = saveData.eaten || 0;
      g.rewards = saveData.rewards || 0;
      g.nextRewardAt = saveData.nextRewardAt || (Math.floor(g.score / SNAKE_REWARD_STEP) + 1) * SNAKE_REWARD_STEP;
      g.wrap = !!saveData.wrap;
      g.accel = saveData.accel === undefined ? snakeLoadAccel() : !!saveData.accel;
    } else {
      for (let i = 0; i < SNAKE_START_LEN; i++) g.snake.push({ r: mid, c: mid - i });
      snakeSpawnFood(g);
    }
    snakeGame = g;
    snakeRenderUI();
    snakeAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = snakeRaf(snakeTick);
  }

  function snakeTeardown(renderLobby) {
    const g = snakeGame;
    snakeGame = null;
    if (g) {
      if (g.rafId) snakeCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function snakeExitToLobby() {
    const g = snakeGame;
    const saved = !!(g && snakeSaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    snakeTeardown();
    renderMiniGameLobby();
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }

  function snakeQuitToCenter() {
    snakeClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    snakeTeardown();
    renderSetup();
    showToast('🚪 已结束本局贪吃蛇');
  }

  function snakeRenderUI() {
    const g = snakeGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = snakeLoadBest();
    sheet.innerHTML = `
      <style>
        @keyframes snake-shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-3px); } 75% { transform: translateX(3px); } }
      </style>
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="snake-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="保存进度并返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🐍 贪吃蛇</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="snake-points-label">${pointsLabelHTML()}</span>
            <span id="snake-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="snake-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏入口（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="snake-score-text" style="color:#4ADE80;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="snake-eaten-text" style="font-size:12px;color:var(--ubp-text-2);">食物: <b style="color:#4ADE80;">0</b></div>
          <div id="snake-speed-text" style="font-size:12px;color:var(--ubp-text-2);">速度: <b style="color:#F59E0B;">LV.1</b></div>
        </div>
        <div id="snake-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#0E1A12;">
          <canvas id="snake-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:22px;">
            <div style="display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(2,36px);gap:6px;">
              <span></span>
              <button data-snake-dir="up" class="ubp-btn" style="padding:0;font-size:15px;">▲</button>
              <span></span>
              <button data-snake-dir="left" class="ubp-btn" style="padding:0;font-size:15px;">◀</button>
              <button data-snake-dir="down" class="ubp-btn" style="padding:0;font-size:15px;">▼</button>
              <button data-snake-dir="right" class="ubp-btn" style="padding:0;font-size:15px;">▶</button>
            </div>
            <div style="display:flex;flex-direction:column;gap:6px;">
              <button data-ubp-act="snake-wrap-toggle" id="snake-wrap-btn" class="ubp-btn" style="padding:8px 12px;font-size:12px;">🌀 穿墙: ${g.wrap ? '开' : '关'}</button>
              <button data-ubp-act="snake-accel-toggle" id="snake-accel-btn" class="ubp-btn" style="padding:8px 12px;font-size:12px;">⚡ 加速: ${g.accel === false ? '关' : '开'}</button>
              <button data-ubp-act="snake-restart" class="ubp-btn" style="padding:8px 12px;font-size:12px;">🔄 重开</button>
            </div>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">方向键 ↑↓←→ / 点按方向按钮 / 滑动棋盘转向 · 不能直接掉头 · 每 100 分 +1 积分</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#snake-stage');
    g.canvas = sheet.querySelector('#snake-canvas');
    snakeUpdateHud(g);
  }

  function snakeUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#snake-score-text');
    if (s) s.textContent = String(g.score);
    const e = sheet.querySelector('#snake-eaten-text');
    if (e) e.innerHTML = '食物: <b style="color:#4ADE80;">' + g.eaten + '</b>';
    const sp = sheet.querySelector('#snake-speed-text');
    if (sp) {
      const lv = Math.max(1, Math.round((SNAKE_BASE_MS - snakeTickMs(g)) / SNAKE_SPEEDUP_PER_FOOD) + 1);
      sp.innerHTML = '速度: <b style="color:#F59E0B;">LV.' + lv + '</b>';
    }
    const best = snakeLoadBest();
    if (g.score > best) snakeSaveBest(g.score);
    const bl = sheet.querySelector('#snake-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
    const wb = sheet.querySelector('#snake-wrap-btn');
    if (wb) wb.textContent = '🌀 穿墙: ' + (g.wrap ? '开' : '关');
    const ab = sheet.querySelector('#snake-accel-btn');
    if (ab) ab.textContent = '⚡ 加速: ' + (g.accel === false ? '关' : '开');
  }

  // 转向（禁止 180° 掉头；最多缓存 2 个转向，支持快速连续拐弯）
  function snakeSetDirection(dir) {
    const g = snakeGame;
    if (!g || g.over || !SNAKE_DIRS[dir]) return;
    const last = g.pending.length ? g.pending[g.pending.length - 1] : g.dir;
    if (dir === last) return;
    const a = SNAKE_DIRS[last];
    const b = SNAKE_DIRS[dir];
    if (a.r + b.r === 0 && a.c + b.c === 0) return;
    if (g.pending.length < 2) g.pending.push(dir);
  }

  function snakeToggleWrap() {
    const g = snakeGame;
    if (g) {
      g.wrap = !g.wrap;
      snakeSaveWrap(g.wrap);
      snakeUpdateHud(g);
      showToast(g.wrap ? '🌀 穿墙模式：拖到边界从对面穿出' : '🚧 经典模式：碰到边界即结束');
      return;
    }
    const v = !snakeLoadWrap();
    snakeSaveWrap(v);
    showToast(v ? '🌀 穿墙模式已开启（下一局生效）' : '🚧 已关闭穿墙（下一局生效）');
  }

  function snakeToggleAccel() {
    const g = snakeGame;
    const cur = g ? g.accel !== false : snakeLoadAccel();
    const v = !cur;
    snakeSaveAccel(v);
    if (g) { g.accel = v; snakeUpdateHud(g); }
    showToast(v ? '⚡ 加速已开启：吃得越多蛇越快' : '🐢 加速已关闭：蛇保持恒速');
  }

  function snakeSpawnFood(g) {
    const occupied = new Set();
    for (const s of g.snake) occupied.add(s.r * SNAKE_GRID + s.c);
    const empties = [];
    for (let r = 0; r < SNAKE_GRID; r++) {
      for (let c = 0; c < SNAKE_GRID; c++) {
        if (!occupied.has(r * SNAKE_GRID + c)) empties.push({ r, c });
      }
    }
    if (!empties.length) { g.food = { r: -1, c: -1 }; return; }
    g.food = empties[Math.floor(Math.random() * empties.length)];
  }

  function snakeCheckMilestones(g) {
    let crossed = false;
    while (g.score >= g.nextRewardAt) {
      g.nextRewardAt += SNAKE_REWARD_STEP;
      g.rewards += 1;
      addPoints(1);
      crossed = true;
    }
    if (crossed) {
      const pl = sheet ? sheet.querySelector('#snake-points-label') : null;
      if (pl) pl.innerHTML = pointsLabelHTML();
      showToast('🎉 累计得分 ' + g.score + '！积分 +1（当前 ' + loadPoints() + '）');
    }
  }

  function snakeBurst(g, r, c) {
    for (let i = 0; i < 10; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = 40 + Math.random() * 140;
      g.particles.push({ r, c, x: 0, y: 0, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, life: 0.5, max: 0.5 });
    }
  }

  function snakeFloat(g, r, c, text) {
    g.floats.push({ r, c, text, life: 1, vy: -34 });
  }

  function snakeDie(g, reason) {
    if (g.over) return;
    g.over = true;
    g.shake = 1;
    snakeClearSave();
    showToast(reason);
    const ref = g;
    setTimeout(() => { if (snakeGame === ref) snakeGameOver(ref); }, 420);
  }

  function snakeStep(g) {
    if (g.pending.length) g.dir = g.pending.shift();
    const d = SNAKE_DIRS[g.dir];
    let nr = g.snake[0].r + d.r;
    let nc = g.snake[0].c + d.c;
    if (g.wrap) {
      nr = (nr + SNAKE_GRID) % SNAKE_GRID;
      nc = (nc + SNAKE_GRID) % SNAKE_GRID;
    } else if (nr < 0 || nr >= SNAKE_GRID || nc < 0 || nc >= SNAKE_GRID) {
      snakeDie(g, '💥 撞到墙了！');
      return;
    }
    const willEat = (nr === g.food.r && nc === g.food.c);
    const body = willEat ? g.snake : g.snake.slice(0, g.snake.length - 1);
    for (const s of body) {
      if (s.r === nr && s.c === nc) {
        snakeDie(g, '💥 撞到自己了！');
        return;
      }
    }
    g.snake.unshift({ r: nr, c: nc });
    if (willEat) {
      g.eaten += 1;
      g.score += SNAKE_FOOD_SCORE;
      g.pop = 1;
      snakeBurst(g, nr, nc);
      snakeFloat(g, nr, nc, '+' + SNAKE_FOOD_SCORE);
      snakeCheckMilestones(g);
      snakeSpawnFood(g);
      snakeUpdateHud(g);
    } else {
      g.snake.pop();
    }
  }

  function snakeTick(ts) {
    const g = snakeGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { snakeTeardown(false); return; }
    const dt = Math.min(0.1, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    g.time += dt;
    if (!g.over) {
      g.accum += dt * 1000;
      const stepMs = snakeTickMs(g);
      let guard = 0;
      while (g.accum >= stepMs && guard < 5 && !g.over) {
        snakeStep(g);
        g.accum -= stepMs;
        guard++;
      }
      if (guard >= 5) g.accum = 0;
    }
    if (g.pop > 0) g.pop = Math.max(0, g.pop - dt * 4);
    if (g.shake > 0) g.shake = Math.max(0, g.shake - dt * 2.4);
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const p = g.particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 420 * dt;
      p.life -= dt;
      if (p.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.vy *= Math.max(0, 1 - dt * 1.8);
      ft.life -= dt;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
    snakeDraw();
    g.rafId = snakeRaf(snakeTick);
  }

  function snakeDraw() {
    const g = snakeGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);
    const pad = 6;
    const board = Math.max(120, Math.min(cssW, cssH) - pad * 2);
    const cell = board / SNAKE_GRID;
    const ox = Math.round((cssW - board) / 2);
    const oy = Math.round((cssH - board) / 2);
    // 背景
    const bg = ctx.createLinearGradient(0, 0, 0, cssH);
    bg.addColorStop(0, '#0C1B12');
    bg.addColorStop(1, '#0A140E');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);
    ctx.save();
    if (g.shake > 0) ctx.translate((Math.random() - 0.5) * 7 * g.shake, (Math.random() - 0.5) * 7 * g.shake);
    // 棋盘与网格
    ctx.fillStyle = '#10261A';
    ctx.fillRect(ox - 3, oy - 3, board + 6, board + 6);
    ctx.strokeStyle = 'rgba(74,222,128,0.14)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(ox - 3, oy - 3, board + 6, board + 6);
    ctx.strokeStyle = 'rgba(255,255,255,0.045)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 1; i < SNAKE_GRID; i++) {
      const x = ox + i * cell;
      const y = oy + i * cell;
      ctx.moveTo(x, oy);
      ctx.lineTo(x, oy + board);
      ctx.moveTo(ox, y);
      ctx.lineTo(ox + board, y);
    }
    ctx.stroke();
    // 食物（脉动）
    if (g.food.r >= 0) {
      const pulse = 1 + 0.08 * Math.sin(g.time * 6);
      const fx = ox + (g.food.c + 0.5) * cell;
      const fy = oy + (g.food.r + 0.5) * cell;
      ctx.save();
      ctx.translate(fx, fy);
      ctx.scale(pulse, pulse);
      ctx.font = Math.round(cell * 0.92) + 'px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🍎', 0, cell * 0.05);
      ctx.restore();
    }
    // 蛇（头 → 尾渐变）
    const n = g.snake.length;
    for (let i = n - 1; i >= 0; i--) {
      const s = g.snake[i];
      const t = n <= 1 ? 0 : i / (n - 1);
      const x = ox + s.c * cell;
      const y = oy + s.r * cell;
      const inset = Math.max(0.8, cell * 0.06);
      const rad = Math.max(2, cell * 0.28);
      const grow = i === 0 ? g.pop * cell * 0.12 : 0;
      const r0 = 0.31 - 0.11 * t;
      const g0 = 0.85 - 0.35 * t;
      const b0 = 0.5 - 0.17 * t;
      ctx.fillStyle = 'rgb(' + Math.round(255 * r0) + ',' + Math.round(255 * g0) + ',' + Math.round(255 * b0) + ')';
      snakeRoundRect(ctx, x + inset - grow, y + inset - grow, cell - inset * 2 + grow * 2, cell - inset * 2 + grow * 2, rad);
      ctx.fill();
      if (i === 0) snakeDrawHead(ctx, g, x, y, cell);
    }
    // 粒子
    for (const p of g.particles) {
      ctx.globalAlpha = Math.max(0, p.life / p.max);
      ctx.fillStyle = '#F87171';
      ctx.beginPath();
      ctx.arc(ox + (p.c + 0.5) * cell + p.x, oy + (p.r + 0.5) * cell + p.y, Math.max(1.4, cell * 0.1), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      const a = Math.max(0, Math.min(1, ft.life));
      const rise = (1 - ft.life) * 34;
      ctx.globalAlpha = a;
      ctx.font = '700 14px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      ctx.strokeText(ft.text, ox + (ft.c + 0.5) * cell, oy + ft.r * cell - 6 - rise);
      ctx.fillStyle = '#4ADE80';
      ctx.fillText(ft.text, ox + (ft.c + 0.5) * cell, oy + ft.r * cell - 6 - rise);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    ctx.restore();
  }

  function snakeDrawHead(ctx, g, x, y, cell) {
    const d = SNAKE_DIRS[g.dir] || SNAKE_DIRS.right;
    const cx = x + cell / 2;
    const cy = y + cell / 2;
    const ex = d.c * cell * 0.16;
    const ey = d.r * cell * 0.16;
    const px = -d.r * cell * 0.17;
    const py = d.c * cell * 0.17;
    ctx.fillStyle = '#052E16';
    ctx.beginPath();
    ctx.arc(cx + ex + px, cy + ey + py, Math.max(1.6, cell * 0.11), 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(cx + ex - px, cy + ey - py, Math.max(1.6, cell * 0.11), 0, Math.PI * 2);
    ctx.fill();
    // 舌头
    ctx.strokeStyle = '#F87171';
    ctx.lineWidth = Math.max(1.2, cell * 0.07);
    ctx.beginPath();
    ctx.moveTo(cx + d.c * cell * 0.3, cy + d.r * cell * 0.3);
    ctx.lineTo(cx + d.c * cell * 0.48, cy + d.r * cell * 0.48);
    ctx.stroke();
  }

  function snakeRoundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function snakeGameOver(g) {
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('贪吃蛇'); } } catch (e) { /* ignore */ }
    snakeClearSave();
    const stage = sheet ? sheet.querySelector('#snake-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.snake-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    const best = Math.max(startBest, g.score);
    if (g.score > snakeLoadBest()) snakeSaveBest(g.score);
    const bl = sheet ? sheet.querySelector('#snake-best-label') : null;
    if (bl) bl.textContent = '🏆 最高 ' + best;
    const ov = document.createElement('div');
    ov.className = 'snake-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #22C55E;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : '游戏结束'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#4ADE80;font-size:17px;">${g.score}</b><br>
          吃到食物：<b style="color:#F59E0B;">${g.eaten}</b> 个<br>
          蛇身长度：<b style="color:#F59E0B;">${g.snake.length}</b> 节<br>
          最高分：<b style="color:#F59E0B;">${best}</b><br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.rewards}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="snake-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#22C55E;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="snake-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">撞墙（未开穿墙）或撞到自己身体即结束 · 每 100 分 +1 积分</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function snakeAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      const dir = map[e.key];
      if (!dir) return;
      e.preventDefault();
      snakeSetDirection(dir);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      sheet.querySelectorAll('[data-snake-dir]').forEach(btn => {
        btn.addEventListener('click', (e) => { e.preventDefault(); snakeSetDirection(btn.dataset.snakeDir); });
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      const cv = g.canvas;
      if (cv) {
        const toPos = (clientX, clientY) => {
          try {
            const rect = cv.getBoundingClientRect();
            return { x: clientX - rect.left, y: clientY - rect.top };
          } catch (e) { return { x: clientX, y: clientY }; }
        };
        let sx = 0;
        let sy = 0;
        let tracking = false;
        const start = (x, y) => { sx = x; sy = y; tracking = true; };
        const finish = (x, y) => {
          if (!tracking) return;
          tracking = false;
          const dx = x - sx;
          const dy = y - sy;
          if (Math.max(Math.abs(dx), Math.abs(dy)) < 22) return;
          if (Math.abs(dx) > Math.abs(dy)) snakeSetDirection(dx > 0 ? 'right' : 'left');
          else snakeSetDirection(dy > 0 ? 'down' : 'up');
        };
        cv.addEventListener('contextmenu', (e) => e.preventDefault());
        if (typeof window.PointerEvent !== 'undefined') {
          cv.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
            start(pos.x, pos.y);
          });
          cv.addEventListener('pointerup', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            finish(pos.x, pos.y);
          });
          cv.addEventListener('pointercancel', () => { tracking = false; });
        } else {
          cv.addEventListener('touchstart', (e) => { if (e.touches[0]) start(e.touches[0].clientX, e.touches[0].clientY); });
          cv.addEventListener('touchend', (e) => { if (e.changedTouches[0]) finish(e.changedTouches[0].clientX, e.changedTouches[0].clientY); });
          cv.addEventListener('mousedown', (e) => start(e.clientX, e.clientY));
          cv.addEventListener('mouseup', (e) => finish(e.clientX, e.clientY));
        }
      }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __SNAKE_ENGINE_END__

  // __PAC_ENGINE_BEGIN__
  // ========== 吃豆人（19×21 迷宫 · 幽灵独立 AI · 传送隧道 · 能量豆反吃 · 香蕉关卡提速） ==========
  // 规则：方向键 / 方向按钮 / 滑动控制黄色吃豆人；小点 +10、能量豆 +50（四角闪烁）；吃能量豆后幽灵变蓝逃跑，
  //       反吃幽灵 200→400→800→1600；幽灵被吃只剩眼睛跑回鬼屋重生；每关随机短暂出现水果拿额外高分；
  //       4 只幽灵（红直接追 / 粉预判 / 青包夹 / 橙远追近躲），追击与分散模式交替；左右两侧传送隧道；
  //       正常状态碰到幽灵损失 1 条命（共 3 条），吃光全部小点+能量豆进入下一关（幽灵更快、能量时间更短）；
  //       每通关一关 +1 积分。本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const PAC_BEST_KEY = 'werewolf_extension_pac_best';
  const PAC_SAVE_KEY = 'werewolf_extension_pac_save';
  const PAC_W = 19;
  const PAC_H = 21;
  const PAC_MAZE = [
    '###################',
    '#........#........#',
    '#.##.###.#.###.##.#',
    '#o.#.###.#.###.#.o#',
    '#.................#',
    '#.##.#.#####.#.##.#',
    '####.#.#.#.#.#.####',
    '####.#...#...#.####',
    '####.#.#####.#.####',
    '####.#.......#.####',
    ' .....###=###..... ',
    '####.##HHHHH##.####',
    '####.#########.####',
    '####.#.......#.####',
    '####.#.#####.#.####',
    '#........#........#',
    '#.##.###.#.###.##.#',
    '#o.#.###.#.###.#.o#',
    '##.#.#.#####.#.#.##',
    '#.................#',
    '###################'
  ];
  const PAC_PLAYER_START = { r: 19, c: 9 };
  const PAC_GATE = { r: 9, c: 9 };   // 鬼屋门前格
  const PAC_DOOR = { r: 10, c: 9 };
  const PAC_HOUSE = { r: 11, c: 9 };
  const PAC_DIRS = { up: { r: -1, c: 0 }, down: { r: 1, c: 0 }, left: { r: 0, c: -1 }, right: { r: 0, c: 1 } };
  const PAC_OPP = { up: 'down', down: 'up', left: 'right', right: 'left' };
  const PAC_PLAYER_SPEED = 7.6;
  const PAC_WALL_COLORS = ['#2563EB', '#16A34A', '#9333EA', '#EA580C', '#DC2626', '#0891B2'];
  const PAC_GHOST_DEFS = [
    { id: 'blinky', color: '#EF4444', start: { r: 9, c: 9 }, dir: 'left', scatter: { r: 1, c: 17 }, release: 0 },
    { id: 'pinky', color: '#F9A8D4', start: { r: 11, c: 7 }, dir: 'up', scatter: { r: 1, c: 1 }, release: 2 },
    { id: 'inky', color: '#22D3EE', start: { r: 11, c: 9 }, dir: 'up', scatter: { r: 17, c: 17 }, release: 5 },
    { id: 'clyde', color: '#FB923C', start: { r: 11, c: 11 }, dir: 'up', scatter: { r: 17, c: 1 }, release: 8 }
  ];
  const PAC_FRUITS = [
    { emoji: '🍒', name: '樱桃', score: 100 },
    { emoji: '🍓', name: '草莓', score: 300 },
    { emoji: '🍊', name: '橘子', score: 500 },
    { emoji: '🍎', name: '苹果', score: 700 },
    { emoji: '🍈', name: '蜜瓜', score: 1000 }
  ];

  let pacGame = null;
  const pacRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const pacCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function pacLoadBest() {
    try { const n = parseInt(localStorage.getItem(PAC_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function pacSaveBest(n) {
    try { localStorage.setItem(PAC_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function pacFrightTime(level) { return Math.max(2.5, 8 - (level - 1) * 0.8); }
  function pacScatterTime(level) { return Math.max(3, 7 - (level - 1) * 0.5); }
  function pacGhostSpeed(g, gh) {
    if (gh.state === 'eaten' || gh.state === 'entering') return 16;
    if (gh.frightened) return 4.6;
    return Math.min(8.4, 6.7 + (g.level - 1) * 0.3);
  }
  function pacFruitForLevel(level) { return PAC_FRUITS[Math.min(Math.max(0, level - 1), PAC_FRUITS.length - 1)]; }
  function pacWrapC(c) { if (c < 0) return PAC_W - 1; if (c >= PAC_W) return 0; return c; }
  function pacCharAt(g, r, c) {
    if (r < 0 || r >= PAC_H) return '#';
    return g.grid[r][pacWrapC(c)];
  }
  function pacAdvanceTile(tile, name) {
    const d = PAC_DIRS[name];
    return { r: tile.r + d.r, c: pacWrapC(tile.c + d.c) };
  }
  function pacIsEdgeWrap(tile, name) {
    const d = PAC_DIRS[name];
    return d.c !== 0 && (tile.c + d.c < 0 || tile.c + d.c >= PAC_W);
  }
  function pacPlayerWalkable(g, r, c) {
    const ch = pacCharAt(g, r, c);
    return ch === '.' || ch === 'o' || ch === ' ';
  }
  function pacGhostWalk(g, gh, r, c) {
    const ch = pacCharAt(g, r, c);
    if (ch === '.' || ch === 'o' || ch === ' ') return true;
    if (ch === '=' || ch === 'H') return gh.state === 'eaten' || gh.state === 'entering' || gh.state === 'leaving' || gh.state === 'house';
    return false;
  }
  function pacCanMove(g, tile, name) {
    if (!PAC_DIRS[name]) return false;
    const nt = pacAdvanceTile(tile, name);
    return pacPlayerWalkable(g, nt.r, nt.c);
  }
  function pacEntityPx(e) {
    const d = PAC_DIRS[e.dir] || PAC_DIRS.left;
    return { x: e.tile.c + d.c * e.prog, y: e.tile.r + d.r * e.prog };
  }
  function pacPixelDist2(a, b) {
    const pa = pacEntityPx(a);
    const pb = pacEntityPx(b);
    const dx = pa.x - pb.x;
    const dy = pa.y - pb.y;
    return dx * dx + dy * dy;
  }

  function pacCountDots(grid) {
    let n = 0;
    for (const row of grid) for (const ch of row) if (ch === '.' || ch === 'o') n++;
    return n;
  }
  function pacResetMaze(g) {
    g.grid = PAC_MAZE.map(row => row.split(''));
    g.grid[PAC_PLAYER_START.r][PAC_PLAYER_START.c] = ' ';
    g.dotsLeft = pacCountDots(g.grid);
    g.dotsEaten = 0;
    g.fruit = { active: false, type: 0, emoji: '🍒', value: 100, r: 13, c: 9, timer: 0 };
    g.fruitSpawns = 0;
  }
  function pacMakeGhost(g, def) {
    return {
      id: def.id, color: def.color, scatter: def.scatter,
      tile: { r: def.start.r, c: def.start.c }, dir: def.dir,
      prog: 0, moving: false,
      state: def.release > 0 ? 'house' : 'normal',
      releaseLeft: def.release, frightened: false, forceReverse: false
    };
  }
  function pacResetRound(g) {
    g.player.tile = { r: PAC_PLAYER_START.r, c: PAC_PLAYER_START.c };
    g.player.dir = 'left';
    g.player.want = null;
    g.player.prog = 0;
    g.player.moving = false;
    g.ghosts = PAC_GHOST_DEFS.map(def => pacMakeGhost(g, def));
    g.frightLeft = 0;
    g.chain = 1;
    g.mode = 'scatter';
    g.modeLeft = pacScatterTime(g.level);
  }

  function pacHasSave() {
    try {
      const raw = localStorage.getItem(PAC_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && Array.isArray(d.grid) && d.grid.length === PAC_H && (d.lives | 0) > 0);
    } catch (e) { return false; }
  }
  function pacClearSave() { try { localStorage.removeItem(PAC_SAVE_KEY); } catch (e) { /* ignore */ } }
  function pacSaveGame(g) {
    try {
      if (!g || g.over) { pacClearSave(); return false; }
      const payload = {
        v: 1, level: g.level, score: g.score, lives: g.lives, rewards: g.rewards,
        dotsLeft: g.dotsLeft, dotsEaten: g.dotsEaten,
        grid: g.grid.map(row => row.join('')),
        player: { tile: { r: g.player.tile.r, c: g.player.tile.c }, dir: g.player.dir, want: g.player.want },
        ghosts: g.ghosts.map(gh => ({ id: gh.id, state: gh.state, frightened: !!gh.frightened, tile: { r: gh.tile.r, c: gh.tile.c }, dir: gh.dir, releaseLeft: gh.releaseLeft })),
        frightLeft: g.frightLeft, chain: g.chain, mode: g.mode, modeLeft: g.modeLeft,
        fruit: { active: g.fruit.active, type: g.fruit.type, r: g.fruit.r, c: g.fruit.c, timer: g.fruit.timer },
        fruitSpawns: g.fruitSpawns
      };
      localStorage.setItem(PAC_SAVE_KEY, JSON.stringify(payload));
      return true;
    } catch (e) { return false; }
  }
  function pacResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(PAC_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !Array.isArray(data.grid) || data.grid.length !== PAC_H) { pacOpenGame(); return; }
    pacOpenGame(data);
    showToast('🔖 已恢复进行中的吃豆人（第 ' + data.level + ' 关 · 得分 ' + (data.score || 0) + '）');
  }

  function pacOpenGame(saveData) {
    pacTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      level: 1, score: 0, startBest: pacLoadBest(), lives: 3, rewards: 0,
      grid: [], dotsLeft: 0, dotsEaten: 0,
      player: { tile: { r: PAC_PLAYER_START.r, c: PAC_PLAYER_START.c }, dir: 'left', want: null, prog: 0, moving: false },
      ghosts: [],
      state: 'ready', readyLeft: 1.8, dyingLeft: 0, clearLeft: 0,
      frightLeft: 0, chain: 1, mode: 'scatter', modeLeft: 0,
      fruit: { active: false, type: 0, emoji: '🍒', value: 100, r: 13, c: 9, timer: 0 },
      fruitSpawns: 0,
      over: false, time: 0, lastTs: 0,
      particles: [], floats: [],
      canvas: null, stageEl: null, rafId: 0, doc: null, keyHandler: null, _onWinResize: null
    };
    if (saveData && Array.isArray(saveData.grid) && saveData.grid.length === PAC_H) {
      g.grid = saveData.grid.map(row => String(row).split(''));
      g.level = Math.max(1, saveData.level | 0);
      g.score = saveData.score || 0;
      g.lives = Math.max(1, saveData.lives | 0);
      g.rewards = saveData.rewards || 0;
      g.dotsLeft = saveData.dotsLeft | 0;
      g.dotsEaten = saveData.dotsEaten | 0;
      g.frightLeft = saveData.frightLeft || 0;
      g.chain = saveData.chain || 1;
      g.mode = saveData.mode === 'chase' ? 'chase' : 'scatter';
      g.modeLeft = saveData.modeLeft || pacScatterTime(g.level);
      g.fruitSpawns = saveData.fruitSpawns || 0;
      const ft = pacFruitForLevel(saveData.fruit && saveData.fruit.type != null ? saveData.fruit.type + 1 : g.level);
      g.fruit = {
        active: !!(saveData.fruit && saveData.fruit.active),
        type: (saveData.fruit && saveData.fruit.type) || 0,
        emoji: ft.emoji, value: ft.score,
        r: (saveData.fruit && saveData.fruit.r) || 13,
        c: (saveData.fruit && saveData.fruit.c) || 9,
        timer: (saveData.fruit && saveData.fruit.timer) || 0
      };
      g.ghosts = PAC_GHOST_DEFS.map(def => {
        const saved = (saveData.ghosts || []).find(x => x && x.id === def.id);
        const gh = pacMakeGhost(g, def);
        if (saved) {
          gh.state = saved.state || gh.state;
          gh.frightened = !!saved.frightened;
          if (saved.tile && Number.isFinite(saved.tile.r) && Number.isFinite(saved.tile.c)) gh.tile = { r: saved.tile.r | 0, c: saved.tile.c | 0 };
          if (PAC_DIRS[saved.dir]) gh.dir = saved.dir;
          if (Number.isFinite(saved.releaseLeft)) gh.releaseLeft = saved.releaseLeft;
        }
        return gh;
      });
      if (saveData.player && saveData.player.tile) {
        g.player.tile = { r: saveData.player.tile.r | 0, c: saveData.player.tile.c | 0 };
        if (PAC_DIRS[saveData.player.dir]) g.player.dir = saveData.player.dir;
        g.player.want = PAC_DIRS[saveData.player.want] ? saveData.player.want : null;
      }
      g.state = 'ready';
      g.readyLeft = 1.6;
    } else {
      pacResetMaze(g);
      pacResetRound(g);
    }
    pacGame = g;
    pacRenderUI();
    pacAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = pacRaf(pacTick);
  }

  function pacTeardown(renderLobby) {
    const g = pacGame;
    pacGame = null;
    if (g) {
      if (g.rafId) pacCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function pacExitToLobby() {
    const g = pacGame;
    const saved = !!(g && pacSaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    pacTeardown();
    renderMiniGameLobby();
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }

  function pacQuitToCenter() {
    pacClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    pacTeardown();
    renderSetup();
    showToast('🚪 已结束本局吃豆人');
  }

  function pacRenderUI() {
    const g = pacGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = pacLoadBest();
    sheet.innerHTML = `
      <style>
        @keyframes pac-ready-pop { 0% { transform: scale(0.8); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
      </style>
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="pac-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="保存进度并返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🟡 吃豆人</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="pac-points-label">${pointsLabelHTML()}</span>
            <span id="pac-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="pac-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏入口（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="pac-score-text" style="color:#FDE047;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="pac-level-text" style="font-size:12px;color:var(--ubp-text-2);">第 <b style="color:#F59E0B;">1</b> 关</div>
          <div id="pac-lives-text" style="font-size:12px;color:var(--ubp-text-2);">❤️❤️❤️</div>
        </div>
        <div id="pac-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#08081A;">
          <canvas id="pac-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:22px;">
            <div style="display:grid;grid-template-columns:repeat(3,42px);grid-template-rows:repeat(2,36px);gap:6px;">
              <span></span>
              <button data-pac-dir="up" class="ubp-btn" style="padding:0;font-size:15px;">▲</button>
              <span></span>
              <button data-pac-dir="left" class="ubp-btn" style="padding:0;font-size:15px;">◀</button>
              <button data-pac-dir="down" class="ubp-btn" style="padding:0;font-size:15px;">▼</button>
              <button data-pac-dir="right" class="ubp-btn" style="padding:0;font-size:15px;">▶</button>
            </div>
            <button data-ubp-act="pac-restart" class="ubp-btn" style="padding:9px 14px;font-size:12.5px;">🔄 重开</button>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">方向键 / 方向按钮 / 滑动迷宫 · 能量豆后反吃幽灵 200→1600 · 清空豆子进入下一关（每关 +1 积分）</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#pac-stage');
    g.canvas = sheet.querySelector('#pac-canvas');
    pacUpdateHud(g);
  }

  function pacUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#pac-score-text');
    if (s) s.textContent = String(g.score);
    const lv = sheet.querySelector('#pac-level-text');
    if (lv) lv.innerHTML = '第 <b style="color:#F59E0B;">' + g.level + '</b> 关';
    const li = sheet.querySelector('#pac-lives-text');
    if (li) li.textContent = '❤️'.repeat(Math.max(0, g.lives)) || '—';
    const best = pacLoadBest();
    if (g.score > best) pacSaveBest(g.score);
    const bl = sheet.querySelector('#pac-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.max(best, g.score);
  }

  function pacSetDirection(dir) {
    const g = pacGame;
    if (!g || g.over || !PAC_DIRS[dir]) return;
    if (g.state !== 'play' && g.state !== 'ready') return;
    const p = g.player;
    p.want = dir;
    if (g.state !== 'play') return;
    if (dir === p.dir) return;
    if (p.moving && p.prog > 0) {
      if (dir === PAC_OPP[p.dir]) {
        // 两格之间原地掉头
        p.tile = pacAdvanceTile(p.tile, p.dir);
        p.prog = 1 - p.prog;
        p.dir = dir;
        return;
      }
      // 转向容错（cornering）：距格中心较近时按方向立即生效，不必等到下一格
      const CORNER = 0.42;
      if (p.prog <= CORNER && pacCanMove(g, p.tile, dir)) {
        p.prog = 0;
        p.dir = dir;
        p.moving = true;
        return;
      }
      const ahead = pacAdvanceTile(p.tile, p.dir);
      if ((1 - p.prog) <= CORNER && pacCanMove(g, ahead, dir)) {
        p.tile = ahead;
        p.prog = 0;
        p.dir = dir;
        p.moving = true;
        pacPlayerArrive(g); // 提前吸附到下一格中心：补算吃豆 / 水果
        return;
      }
      return; // 记住转向意图，到下一格中心再转
    }
    if (!p.moving && p.prog <= 0) p.dir = dir;
  }

  function pacFloat(g, r, c, text) {
    g.floats.push({ r, c, text, life: 1.1, vy: -30 });
  }
  function pacBurst(g, r, c) {
    for (let i = 0; i < 8; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = 30 + Math.random() * 90;
      g.particles.push({ r, c, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, life: 0.45 });
    }
  }

  function pacPlayerArrive(g) {
    const p = g.player;
    const ch = g.grid[p.tile.r][p.tile.c];
    if (ch === '.') {
      g.grid[p.tile.r][p.tile.c] = ' ';
      g.score += 10;
      g.dotsLeft -= 1;
      g.dotsEaten += 1;
      pacMaybeSpawnFruit(g);
      pacUpdateHud(g);
      if (g.dotsLeft <= 0) { pacLevelClear(g); return; }
    } else if (ch === 'o') {
      g.grid[p.tile.r][p.tile.c] = ' ';
      g.score += 50;
      g.dotsLeft -= 1;
      g.dotsEaten += 1;
      pacFloat(g, p.tile.r, p.tile.c, '+50');
      g.frightLeft = pacFrightTime(g.level);
      g.chain = 1;
      for (const gh of g.ghosts) {
        if (gh.state === 'normal') { gh.frightened = true; gh.forceReverse = true; }
      }
      pacMaybeSpawnFruit(g);
      pacUpdateHud(g);
      if (g.dotsLeft <= 0) { pacLevelClear(g); return; }
    }
    if (g.fruit.active && g.fruit.r === p.tile.r && g.fruit.c === p.tile.c) {
      g.score += g.fruit.value;
      pacFloat(g, p.tile.r, p.tile.c, g.fruit.emoji + ' +' + g.fruit.value);
      g.fruit.active = false;
      pacUpdateHud(g);
    }
  }

  function pacMaybeSpawnFruit(g) {
    if (g.fruitSpawns >= 2) return;
    if (g.dotsEaten !== 40 && g.dotsEaten !== 110) return;
    const t = pacFruitForLevel(g.level);
    g.fruit = { active: true, type: Math.min(g.level - 1, PAC_FRUITS.length - 1), emoji: t.emoji, value: t.score, r: 13, c: 9, timer: 9 };
    g.fruitSpawns += 1;
    showToast(t.emoji + ' 水果出现！吃掉 +' + t.score + ' 分（限时 ' + 9 + ' 秒）');
  }

  function pacLevelClear(g) {
    g.state = 'levelclear';
    g.clearLeft = 1.5;
    g.rewards += 1;
    addPoints(1);
    const pl = sheet ? sheet.querySelector('#pac-points-label') : null;
    if (pl) pl.innerHTML = pointsLabelHTML();
    showToast('🎉 第 ' + g.level + ' 关通关！积分 +1（当前 ' + loadPoints() + '）');
  }

  function pacNextLevel(g) {
    g.level += 1;
    pacResetMaze(g);
    pacResetRound(g);
    g.state = 'ready';
    g.readyLeft = 1.7;
    pacUpdateHud(g);
    showToast('🚀 进入第 ' + g.level + ' 关：幽灵更快、能量豆时间更短');
  }

  function pacPlayerDie(g) {
    if (g.state !== 'play') return;
    g.state = 'dying';
    g.dyingLeft = 1.5;
    g.frightLeft = 0;
    for (const gh of g.ghosts) gh.frightened = false;
  }

  function pacAfterDeath(g) {
    g.lives -= 1;
    pacUpdateHud(g);
    if (g.lives <= 0) {
      g.over = true;
      pacClearSave();
      g.state = 'over';
      pacGameOver(g);
      return;
    }
    pacResetRound(g);
    g.state = 'ready';
    g.readyLeft = 1.7;
    showToast('💔 损失一条命！剩余生命 ' + g.lives);
  }

  function pacUpdatePlay(g, dt) {
    // 模式计时（惊吓期间暂停）
    if (g.frightLeft > 0) {
      g.frightLeft = Math.max(0, g.frightLeft - dt);
      if (g.frightLeft === 0) {
        for (const gh of g.ghosts) gh.frightened = false;
      }
    } else {
      g.modeLeft -= dt;
      if (g.modeLeft <= 0) {
        g.mode = g.mode === 'scatter' ? 'chase' : 'scatter';
        g.modeLeft = g.mode === 'scatter' ? pacScatterTime(g.level) : 20;
        for (const gh of g.ghosts) { if (gh.state === 'normal') gh.forceReverse = true; }
      }
    }
    // 水果限时
    if (g.fruit.active) {
      g.fruit.timer -= dt;
      if (g.fruit.timer <= 0) g.fruit.active = false;
    }
    // 鬼屋释放
    for (const gh of g.ghosts) {
      if (gh.state === 'house') {
        gh.releaseLeft -= dt;
        if (gh.releaseLeft <= 0) { gh.state = 'leaving'; }
      }
    }
    // 移动
    pacStepEntity(g, g.player, PAC_PLAYER_SPEED, dt, pacPlayerDecide);
    for (const gh of g.ghosts) {
      pacStepEntity(g, gh, pacGhostSpeed(g, gh), dt, pacGhostDecide);
    }
    pacCheckCollisions(g);
  }

  function pacStepEntity(g, e, speed, dt, decide) {
    let dist = speed * dt;
    let guard = 0;
    while (dist > 1e-9 && guard++ < 10) {
      if (!e.moving) {
        decide(g, e);
        if (!e.moving) { e.prog = 0; break; }
      }
      const remain = 1 - e.prog;
      if (dist < remain) {
        e.prog += dist;
        dist = 0;
      } else {
        dist -= remain;
        e.tile = pacAdvanceTile(e.tile, e.dir);
        e.prog = 0;
        e.moving = false;
        if (e === g.player) pacPlayerArrive(g);
        if (g.state !== 'play') return;
      }
    }
  }

  function pacPlayerDecide(g, e) {
    if (e.want && pacCanMove(g, e.tile, e.want)) e.dir = e.want;
    if (pacCanMove(g, e.tile, e.dir)) e.moving = true;
    else e.moving = false;
  }

  function pacGhostTarget(g, gh) {
    const p = g.player;
    const pd = PAC_DIRS[p.dir] || PAC_DIRS.left;
    if (g.mode === 'scatter') return gh.scatter;
    if (gh.id === 'blinky') return { r: p.tile.r, c: p.tile.c };
    if (gh.id === 'pinky') return { r: p.tile.r + pd.r * 4, c: p.tile.c + pd.c * 4 };
    if (gh.id === 'inky') {
      const blinky = g.ghosts.find(x => x.id === 'blinky');
      const piv = { r: p.tile.r + pd.r * 2, c: p.tile.c + pd.c * 2 };
      const br = blinky ? blinky.tile.r : piv.r;
      const bc = blinky ? blinky.tile.c : piv.c;
      return { r: piv.r * 2 - br, c: piv.c * 2 - bc };
    }
    // clyde：距离远追、靠近回角落
    const dr = gh.tile.r - p.tile.r;
    const dc = gh.tile.c - p.tile.c;
    return (dr * dr + dc * dc) > 64 ? { r: p.tile.r, c: p.tile.c } : gh.scatter;
  }

  function pacGhostChoose(g, gh, target, flee) {
    const opp = PAC_OPP[gh.dir];
    const opts = [];
    for (const name of ['up', 'left', 'down', 'right']) {
      if (name === opp) continue;
      const nt = pacAdvanceTile(gh.tile, name);
      if (!pacGhostWalk(g, gh, nt.r, nt.c)) continue;
      opts.push({ name, nt });
    }
    if (!opts.length) {
      const nt = pacAdvanceTile(gh.tile, opp);
      if (pacGhostWalk(g, gh, nt.r, nt.c)) { gh.dir = opp; gh.moving = true; }
      else gh.moving = false;
      return;
    }
    let best = opts[0];
    let bestScore = Infinity;
    for (const o of opts) {
      let score;
      if (flee) {
        const dr = o.nt.r - g.player.tile.r;
        const dc = o.nt.c - g.player.tile.c;
        score = -(dr * dr + dc * dc) + Math.random() * 0.8;
      } else {
        const dr = o.nt.r - target.r;
        const dc = o.nt.c - target.c;
        score = dr * dr + dc * dc;
      }
      if (score < bestScore) { bestScore = score; best = o; }
    }
    gh.dir = best.name;
    gh.moving = true;
  }

  function pacGhostDecide(g, gh) {
    if (gh.state === 'house') { gh.moving = false; return; }
    if (gh.state === 'leaving') {
      if (gh.tile.r === 9 && gh.tile.c === 9) {
        gh.state = 'normal';
        gh.frightened = g.frightLeft > 0;
        gh.forceReverse = false;
        // 落到下面继续按普通 AI 决策
      } else {
        let dir = null;
        if (gh.tile.r === 11 && gh.tile.c !== 9) dir = gh.tile.c < 9 ? 'right' : 'left';
        else if (gh.tile.r >= 10) dir = 'up';
        if (dir) { gh.dir = dir; gh.moving = true; return; }
        gh.moving = false;
        return;
      }
    }
    if (gh.state === 'entering') {
      if (gh.tile.r < 11) { gh.dir = 'down'; gh.moving = true; return; }
      gh.state = 'house';
      gh.releaseLeft = 1.0;
      gh.frightened = false;
      gh.moving = false;
      return;
    }
    if (gh.state === 'eaten') {
      if (gh.tile.r === PAC_GATE.r && gh.tile.c === PAC_GATE.c) {
        gh.state = 'entering';
        gh.dir = 'down';
        gh.moving = true;
        return;
      }
      pacGhostChoose(g, gh, PAC_GATE, false);
      return;
    }
    if (gh.frightened) {
      gh.forceReverse = false;
      pacGhostChoose(g, gh, null, true);
      return;
    }
    if (gh.forceReverse) {
      gh.forceReverse = false;
      const opp = PAC_OPP[gh.dir];
      const nt = pacAdvanceTile(gh.tile, opp);
      if (pacGhostWalk(g, gh, nt.r, nt.c)) { gh.dir = opp; gh.moving = true; return; }
    }
    pacGhostChoose(g, gh, pacGhostTarget(g, gh), false);
  }

  function pacCheckCollisions(g) {
    const p = g.player;
    for (const gh of g.ghosts) {
      if (gh.state === 'eaten' || gh.state === 'entering' || gh.state === 'house') continue;
      const same = gh.tile.r === p.tile.r && gh.tile.c === p.tile.c && gh.prog === 0 && p.prog === 0;
      if (!same && pacPixelDist2(p, gh) > 0.36) continue;
      if (gh.state === 'normal' && gh.frightened) {
        const pts = Math.min(200 * Math.pow(2, g.chain - 1), 1600);
        g.chain = Math.min(g.chain + 1, 5);
        g.score += pts;
        gh.state = 'eaten';
        gh.frightened = false;
        gh.forceReverse = false;
        pacFloat(g, gh.tile.r, gh.tile.c, '+' + pts);
        pacBurst(g, gh.tile.r, gh.tile.c);
        pacUpdateHud(g);
      } else if (!gh.frightened) {
        pacPlayerDie(g);
        return;
      }
    }
  }

  function pacUpdate(g, dt) {
    if (!g) return;
    g.time += dt;
    if (g.state === 'ready') {
      g.readyLeft -= dt;
      if (g.readyLeft <= 0) g.state = 'play';
    } else if (g.state === 'play') {
      pacUpdatePlay(g, dt);
    } else if (g.state === 'dying') {
      g.dyingLeft -= dt;
      if (g.dyingLeft <= 0) pacAfterDeath(g);
    } else if (g.state === 'levelclear') {
      g.clearLeft -= dt;
      if (g.clearLeft <= 0) pacNextLevel(g);
    }
    for (let i = g.particles.length - 1; i >= 0; i--) {
      const pt = g.particles[i];
      pt.r += pt.vy * dt * 0.01;
      pt.life -= dt;
      if (pt.life <= 0) g.particles.splice(i, 1);
    }
    for (let i = g.floats.length - 1; i >= 0; i--) {
      const ft = g.floats[i];
      ft.vy *= Math.max(0, 1 - dt * 1.8);
      ft.life -= dt;
      if (ft.life <= 0) g.floats.splice(i, 1);
    }
  }

  function pacGameOver(g) {
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('吃豆人'); } } catch (e) { /* ignore */ }
    pacClearSave();
    const stage = sheet ? sheet.querySelector('#pac-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.pac-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const isNew = g.score > startBest;
    const best = Math.max(startBest, g.score);
    if (g.score > pacLoadBest()) pacSaveBest(g.score);
    const bl = sheet ? sheet.querySelector('#pac-best-label') : null;
    if (bl) bl.textContent = '🏆 最高 ' + best;
    const ov = document.createElement('div');
    ov.className = 'pac-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.78);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #FDE047;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '💀'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : 'GAME OVER'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#FDE047;font-size:17px;">${g.score}</b><br>
          到达关卡：<b style="color:#F59E0B;">第 ${g.level} 关</b><br>
          最高分：<b style="color:#F59E0B;">${best}</b><br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.rewards}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="pac-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#FDE047;border:none;color:#422006;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="pac-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">生命耗尽即结束 · 每通关一关 +1 积分</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function pacTick(ts) {
    const g = pacGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { pacTeardown(false); return; }
    const dt = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    pacUpdate(g, dt);
    pacDraw();
    g.rafId = pacRaf(pacTick);
  }

  function pacRoundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function pacDraw() {
    const g = pacGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const bg = ctx.createLinearGradient(0, 0, 0, cssH);
    bg.addColorStop(0, '#08081A');
    bg.addColorStop(1, '#0B0B22');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);
    const pad = 6;
    const cell = Math.min((cssW - pad * 2) / PAC_W, (cssH - pad * 2) / PAC_H);
    const ox = Math.round((cssW - cell * PAC_W) / 2);
    const oy = Math.round((cssH - cell * PAC_H) / 2);
    // 墙壁
    const wallColor = PAC_WALL_COLORS[(g.level - 1) % PAC_WALL_COLORS.length];
    for (let r = 0; r < PAC_H; r++) {
      for (let c = 0; c < PAC_W; c++) {
        if (g.grid[r][c] !== '#') continue;
        const x = ox + c * cell;
        const y = oy + r * cell;
        ctx.fillStyle = wallColor;
        pacRoundRect(ctx, x + cell * 0.06, y + cell * 0.06, cell * 0.88, cell * 0.88, cell * 0.2);
        ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,255,0.16)';
        ctx.lineWidth = Math.max(1, cell * 0.05);
        pacRoundRect(ctx, x + cell * 0.18, y + cell * 0.18, cell * 0.64, cell * 0.64, cell * 0.14);
        ctx.stroke();
      }
    }
    // 鬼屋门
    ctx.fillStyle = '#F9A8D4';
    ctx.fillRect(ox + PAC_DOOR.c * cell + cell * 0.08, oy + PAC_DOOR.r * cell + cell * 0.42, cell * 0.84, Math.max(2, cell * 0.16));
    // 豆子
    for (let r = 0; r < PAC_H; r++) {
      for (let c = 0; c < PAC_W; c++) {
        const ch = g.grid[r][c];
        if (ch !== '.' && ch !== 'o') continue;
        const x = ox + (c + 0.5) * cell;
        const y = oy + (r + 0.5) * cell;
        if (ch === '.') {
          ctx.fillStyle = 'rgba(252,211,77,0.9)';
          ctx.beginPath();
          ctx.arc(x, y, Math.max(1, cell * 0.11), 0, Math.PI * 2);
          ctx.fill();
        } else {
          const blink = 0.5 + 0.5 * Math.sin(g.time * 6);
          ctx.globalAlpha = 0.5 + 0.5 * blink;
          ctx.fillStyle = '#FDE047';
          ctx.beginPath();
          ctx.arc(x, y, cell * 0.28, 0, Math.PI * 2);
          ctx.fill();
          ctx.globalAlpha = 1;
        }
      }
    }
    // 水果
    if (g.fruit.active) {
      const fx = ox + (g.fruit.c + 0.5) * cell;
      const fy = oy + (g.fruit.r + 0.5) * cell;
      const blink = g.fruit.timer < 3 ? (Math.floor(g.time * 6) % 2 === 0 ? 1 : 0.35) : 1;
      ctx.globalAlpha = blink;
      ctx.font = Math.round(cell * 1.05) + 'px "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(g.fruit.emoji, fx, fy);
      ctx.globalAlpha = 1;
      ctx.textBaseline = 'alphabetic';
    }
    // 玩家
    if (!g.over) pacDrawPlayer(ctx, g, cell, ox, oy);
    // 幽灵
    for (const gh of g.ghosts) pacDrawGhost(ctx, g, gh, cell, ox, oy);
    // 粒子
    for (const pt of g.particles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, pt.life / 0.45));
      ctx.fillStyle = '#A5B4FC';
      ctx.beginPath();
      ctx.arc(ox + (pt.c + 0.5) * cell, oy + (pt.r + 0.5) * cell, Math.max(1.2, cell * 0.08), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const ft of g.floats) {
      const a = Math.max(0, Math.min(1, ft.life));
      const rise = (1.1 - ft.life) * 34;
      ctx.globalAlpha = a;
      ctx.font = '700 14px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 3;
      const tx = ox + (ft.c + 0.5) * cell;
      const ty = oy + ft.r * cell - 6 - rise;
      ctx.strokeText(ft.text, tx, ty);
      ctx.fillStyle = '#FDE047';
      ctx.fillText(ft.text, tx, ty);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    // READY!
    if (g.state === 'ready') {
      ctx.textAlign = 'center';
      ctx.font = '800 ' + Math.round(cell * 1.05) + 'px -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif';
      ctx.fillStyle = '#FDE047';
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 4;
      const ty = oy + 13.5 * cell;
      ctx.strokeText('READY!', ox + PAC_W * cell / 2, ty);
      ctx.fillText('READY!', ox + PAC_W * cell / 2, ty);
      ctx.textAlign = 'left';
    }
    // 通关闪白
    if (g.state === 'levelclear') {
      const k = 0.5 + 0.5 * Math.sin(g.time * 22);
      ctx.fillStyle = 'rgba(255,255,255,' + (0.16 * k).toFixed(3) + ')';
      ctx.fillRect(0, 0, cssW, cssH);
    }
  }

  function pacDrawPlayer(ctx, g, cell, ox, oy) {
    const p = g.player;
    const d = PAC_DIRS[p.dir] || PAC_DIRS.left;
    const x = ox + (p.tile.c + d.c * p.prog + 0.5) * cell;
    const y = oy + (p.tile.r + d.r * p.prog + 0.5) * cell;
    const r = cell * 0.42;
    let mouth;
    let alpha = 1;
    if (g.state === 'dying') {
      const k = 1 - Math.max(0, g.dyingLeft / 1.5);
      mouth = Math.min(Math.PI, k * Math.PI * 1.35);
      alpha = Math.max(0.1, 1 - k * 0.5);
    } else {
      mouth = (0.12 + 0.23 * (0.5 + 0.5 * Math.sin(g.time * 13))) * Math.PI;
    }
    const ang = { right: 0, down: Math.PI / 2, left: Math.PI, up: -Math.PI / 2 }[p.dir] || 0;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = '#FDE047';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.arc(x, y, r, ang + mouth, ang + Math.PI * 2 - mouth);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(253,224,71,0.5)';
    ctx.lineWidth = Math.max(1, cell * 0.06);
    ctx.stroke();
    ctx.restore();
  }

  function pacDrawGhost(ctx, g, gh, cell, ox, oy) {
    const d = PAC_DIRS[gh.dir] || PAC_DIRS.up;
    const bob = gh.state === 'house' ? Math.sin(g.time * 5 + gh.id.length) * cell * 0.06 : 0;
    const x = ox + (gh.tile.c + d.c * gh.prog + 0.5) * cell;
    const y = oy + (gh.tile.r + d.r * gh.prog + 0.5) * cell + bob;
    const r = cell * 0.44;
    const eyesOnly = gh.state === 'eaten';
    if (!eyesOnly) {
      const flashing = gh.frightened && g.frightLeft < 2 && Math.floor(g.time * 6) % 2 === 0;
      const color = gh.frightened ? (flashing ? '#F8FAFC' : '#2563EB') : gh.color;
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, r, Math.PI, 0);
      ctx.lineTo(x + r, y + r * 0.7);
      const zig = 3;
      for (let i = 0; i < zig; i++) {
        const x1 = x + r - (2 * r * (i + 0.5)) / zig;
        const x2 = x + r - (2 * r * (i + 1)) / zig;
        ctx.quadraticCurveTo(x1, y + r * 0.32, x2, y + r * 0.7);
      }
      ctx.closePath();
      ctx.fill();
      if (gh.frightened) {
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(x - r * 0.34, y - r * 0.12, r * 0.14, 0, Math.PI * 2);
        ctx.arc(x + r * 0.34, y - r * 0.12, r * 0.14, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(1, r * 0.12);
        ctx.beginPath();
        const my = y + r * 0.3;
        ctx.moveTo(x - r * 0.5, my);
        for (let i = 0; i < 3; i++) {
          ctx.lineTo(x - r * 0.5 + (r * (i * 2 + 1)) / 3, my + (i % 2 === 0 ? -r * 0.18 : r * 0.18));
        }
        ctx.lineTo(x + r * 0.5, my);
        ctx.stroke();
        return;
      }
    }
    // 眼睛
    const ex = x + d.c * r * 0.12;
    const ey = y + d.r * r * 0.12;
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.ellipse(ex - r * 0.34, ey - r * 0.1, r * 0.28, r * 0.32, 0, 0, Math.PI * 2);
    ctx.ellipse(ex + r * 0.34, ey - r * 0.1, r * 0.28, r * 0.32, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#1E3A8A';
    ctx.beginPath();
    ctx.arc(ex - r * 0.34 + d.c * r * 0.12, ey - r * 0.1 + d.r * r * 0.12, r * 0.14, 0, Math.PI * 2);
    ctx.arc(ex + r * 0.34 + d.c * r * 0.12, ey - r * 0.1 + d.r * r * 0.12, r * 0.14, 0, Math.PI * 2);
    ctx.fill();
  }

  function pacAttachInput(g) {
    let doc = null;
    try { doc = (typeof getAppendDoc === 'function' ? getAppendDoc() : null) || document; } catch (e) { doc = document; }
    g.doc = doc;
    g.keyHandler = (e) => {
      const tgt = e.target;
      if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT' || tgt.isContentEditable)) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
      const dir = map[e.key];
      if (!dir) return;
      e.preventDefault();
      pacSetDirection(dir);
    };
    try { doc.addEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ }
    if (sheet) {
      sheet.querySelectorAll('[data-pac-dir]').forEach(btn => {
        btn.addEventListener('click', (e) => { e.preventDefault(); pacSetDirection(btn.dataset.pacDir); });
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      const cv = g.canvas;
      if (cv) {
        const toPos = (clientX, clientY) => {
          try {
            const rect = cv.getBoundingClientRect();
            return { x: clientX - rect.left, y: clientY - rect.top };
          } catch (e) { return { x: clientX, y: clientY }; }
        };
        let sx = 0;
        let sy = 0;
        let tracking = false;
        const start = (x, y) => { sx = x; sy = y; tracking = true; };
        const finish = (x, y) => {
          if (!tracking) return;
          tracking = false;
          const dx = x - sx;
          const dy = y - sy;
          if (Math.max(Math.abs(dx), Math.abs(dy)) < 22) return;
          if (Math.abs(dx) > Math.abs(dy)) pacSetDirection(dx > 0 ? 'right' : 'left');
          else pacSetDirection(dy > 0 ? 'down' : 'up');
        };
        cv.addEventListener('contextmenu', (e) => e.preventDefault());
        if (typeof window.PointerEvent !== 'undefined') {
          cv.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            try { cv.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
            start(pos.x, pos.y);
          });
          cv.addEventListener('pointerup', (e) => {
            e.preventDefault();
            const pos = toPos(e.clientX, e.clientY);
            finish(pos.x, pos.y);
          });
          cv.addEventListener('pointercancel', () => { tracking = false; });
        } else {
          cv.addEventListener('touchstart', (e) => { if (e.touches[0]) start(e.touches[0].clientX, e.touches[0].clientY); });
          cv.addEventListener('touchend', (e) => { if (e.changedTouches[0]) finish(e.changedTouches[0].clientX, e.changedTouches[0].clientY); });
          cv.addEventListener('mousedown', (e) => start(e.clientX, e.clientY));
          cv.addEventListener('mouseup', (e) => finish(e.clientX, e.clientY));
        }
      }
    }
    g._onWinResize = () => { /* 尺寸由绘制循环自适应 */ };
    try { (doc.defaultView || window).addEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ }
  }
  // __PAC_ENGINE_END__

  // __DINO_ENGINE_BEGIN__
  // ========== 恐龙游戏（Chrome 离线小恐龙 · 黑白像素无尽跑酷） ==========
  // 规则：恐龙持续向右奔跑、背景向左滚动；空格 / ↑ / 点击画面上半部跳跃（空中可再跳一次=二段跳），↓ / 按住画面下半部下蹲（碰撞盒变矮）；
  //       障碍：仙人掌（小/大、成组，需跳跃跨越）、翼龙（两种高度：低空的跳过去，头顶高度的蹲下去）；
  //       速度随得分递增、障碍间隔变小；每 700 分昼夜切换；持续跑动自动加分（每段距离 +1，封顶 99999）；
  //       任何部位碰到障碍立即结束；每累计 500 分自动 +1 积分。本游戏为纯单机休闲小游戏，只结算积分，不写入【对局记录】。
  const DINO_BEST_KEY = 'werewolf_extension_dino_best';
  const DINO_SAVE_KEY = 'werewolf_extension_dino_save';
  const DINO_REWARD_STEP = 500;
  const DINO_MAX_SCORE = 99999;
  const DINO_REF_W = 400;
  const DINO_DAY_NIGHT_STEP = 700;

  let dinoGame = null;
  const dinoRaf = (cb) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(cb) : setTimeout(() => cb(performance.now()), 16));
  const dinoCaf = (id) => { try { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); } catch (e) { /* ignore */ } };

  function dinoLoadBest() {
    try { const n = parseInt(localStorage.getItem(DINO_BEST_KEY), 10); return Number.isFinite(n) ? n : 0; } catch (e) { return 0; }
  }
  function dinoSaveBest(n) {
    try { localStorage.setItem(DINO_BEST_KEY, String(Math.round(Number(n) || 0))); } catch (e) { /* ignore */ }
  }
  function dinoHasSave() {
    try {
      const raw = localStorage.getItem(DINO_SAVE_KEY);
      if (!raw) return false;
      const d = JSON.parse(raw);
      return !!(d && d.dino && Array.isArray(d.obstacles) && (d.score | 0) > 0);
    } catch (e) { return false; }
  }
  function dinoClearSave() { try { localStorage.removeItem(DINO_SAVE_KEY); } catch (e) { /* ignore */ } }
  function dinoSaveGame(g) {
    try {
      if (!g || g.over) { dinoClearSave(); return false; }
      localStorage.setItem(DINO_SAVE_KEY, JSON.stringify({
        v: 1, score: g.score, rewards: g.rewards, nextRewardAt: g.nextRewardAt, time: g.time, bgShift: g.bgShift, night: g.night,
        dino: { y: g.dino.y, vy: g.dino.vy, duck: g.dino.duck, jumpsLeft: g.dino.jumpsLeft, runT: g.dino.runT },
        obstacles: g.obstacles.map(o => ({ type: o.type, x: o.x, w: o.w, h: o.h, bottom: o.bottom, group: o.group, frame: o.frame })),
        pebbles: g.pebbles.map(p => ({ x: p.x, len: p.len, y: p.y })),
        clouds: g.clouds.map(c => ({ x: c.x, y: c.y, s: c.s })),
        nextSpawnIn: g.nextSpawnIn, over: false
      }));
      return true;
    } catch (e) { return false; }
  }
  function dinoResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(DINO_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !data.dino || !Array.isArray(data.obstacles)) { dinoOpenGame(); return; }
    dinoOpenGame(data);
    showToast('🔖 已恢复进行中的恐龙跑酷（得分 ' + Math.floor(data.score || 0) + '）');
  }

  function dinoSizes(g) {
    const W0 = Math.max(26, Math.round((g.W || DINO_REF_W) * 0.105));
    return { W0, H0: Math.round(W0 * 1.07) };
  }
  function dinoGroundY(g) { return (g.H || 480) * 0.78; }
  function dinoFactor(g) { return Math.min(2.7, 1 + g.score / 2200); }
  function dinoSpeed(g) { return (g.W || DINO_REF_W) * 0.55 * dinoFactor(g); }
  function dinoTheme(g) {
    const night = !!g.night;
    return night
      ? { bg: '#1B1B22', fg: '#D8D8E0', dim: '#8A8A96', ground: '#D8D8E0' }
      : { bg: '#F5F5F3', fg: '#4B4B4B', dim: '#9A9A97', ground: '#535353' };
  }
  function dinoPlayerBox(g) {
    const { W0, H0 } = dinoSizes(g);
    const grounded = g.dino.y <= 0.5;
    const duck = g.dino.duck && grounded;
    const w = duck ? W0 * 1.25 : W0;
    const h = duck ? H0 * 0.6 : H0;
    const top = dinoGroundY(g) - g.dino.y - h;
    return { x: g.dinoX + 4, y: top + 3, w: w - 8, h: h - 4 };
  }
  function dinoObstacleBox(g, ob) {
    const groundY = dinoGroundY(g);
    if (ob.type === 'ptero') return { x: ob.x + 3, y: groundY - ob.bottom - ob.h + 3, w: ob.w - 6, h: ob.h - 6 };
    return { x: ob.x + 2, y: groundY - ob.h + 2, w: ob.w - 4, h: ob.h - 2 };
  }
  function dinoOverlap(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }
  function dinoNextGap(g) {
    const speed = dinoSpeed(g);
    const hard = Math.min(0.28, g.score / 10000);
    const t = (0.62 + Math.random() * 0.55) * (1 - hard);
    return Math.max((g.W || DINO_REF_W) * 0.35, speed * t);
  }

  function dinoSpawnObstacle(g) {
    const { W0, H0 } = dinoSizes(g);
    const r = Math.random();
    const canPtero = g.score > 300;
    let ob;
    if (canPtero && r < 0.28) {
      const low = Math.random() < 0.5;
      const h = H0 * 0.55;
      const bottom = low ? H0 * 0.30 : H0 * 0.80; // 低空=需跳；头顶=需蹲（80% 站立身高：站立必撞、下蹲可过）
      ob = { type: 'ptero', x: (g.W || DINO_REF_W) + 20, bottom, h, w: W0 * 1.0, group: 1, frame: 0 };
    } else {
      const large = g.score > 150 && Math.random() < 0.45;
      let group;
      if (large) group = Math.random() < 0.25 ? 2 : 1;
      else group = Math.random() < 0.22 ? 3 : (Math.random() < 0.5 ? 2 : 1);
      const wSingle = large ? W0 * 0.55 : W0 * 0.36;
      const h = large ? H0 * 1.05 : H0 * 0.72;
      const w = wSingle * group + (group - 1) * 3;
      ob = { type: large ? 'cactus_large' : 'cactus_small', x: (g.W || DINO_REF_W) + 20, w, h, group, frame: 0 };
    }
    g.obstacles.push(ob);
  }

  function dinoResetWorld(g) {
    const W = g.W || DINO_REF_W;
    const H = g.H || 480;
    g.obstacles = [];
    g.pebbles = [];
    for (let i = 0; i < 12; i++) {
      g.pebbles.push({ x: Math.random() * W, len: 4 + Math.random() * 10, y: 3 + Math.random() * 7 });
    }
    g.clouds = [];
    for (let i = 0; i < 3; i++) {
      g.clouds.push({ x: Math.random() * W, y: H * (0.08 + Math.random() * 0.24), s: 0.7 + Math.random() * 0.6 });
    }
    g.stars = [];
    for (let i = 0; i < 46; i++) {
      g.stars.push({ x: Math.random(), y: Math.random() * 0.52, r: 1 + Math.random() * 1.4 });
    }
    g.nextSpawnIn = W * 0.9;
    g.time = 0;
    g.bgShift = 0;
    g.flash = 0;
    g.night = false;
    g.hudT = 0;
    g.shake = 0;
  }

  function dinoOpenGame(saveData) {
    dinoTeardown();
    if (!sheet) { renderMiniGameLobby(); return; }
    const g = {
      W: DINO_REF_W, H: 480,
      score: 0, startBest: dinoLoadBest(), rewards: 0, nextRewardAt: DINO_REWARD_STEP,
      dinoX: DINO_REF_W * 0.10,
      dino: { y: 0, vy: 0, duck: false, jumpsLeft: 2, runT: 0 },
      obstacles: [], pebbles: [], clouds: [], stars: [],
      nextSpawnIn: DINO_REF_W * 0.9,
      night: false, flash: 0, shake: 0, over: false, time: 0, bgShift: 0, hudT: 0,
      canvas: null, stageEl: null, rafId: 0, lastTs: 0, doc: null, keyHandler: null, keyUpHandler: null, _onWinResize: null
    };
    dinoResetWorld(g);
    if (saveData && saveData.dino) {
      g.score = saveData.score || 0;
      g.rewards = saveData.rewards || 0;
      g.nextRewardAt = saveData.nextRewardAt || (Math.floor(g.score / DINO_REWARD_STEP) + 1) * DINO_REWARD_STEP;
      g.time = saveData.time || 0;
      g.bgShift = saveData.bgShift || 0;
      g.night = !!saveData.night;
      g.nextSpawnIn = saveData.nextSpawnIn || DINO_REF_W * 0.9;
      g.dino = {
        y: saveData.dino.y || 0,
        vy: saveData.dino.vy || 0,
        duck: !!saveData.dino.duck,
        jumpsLeft: saveData.dino.jumpsLeft === undefined ? 2 : saveData.dino.jumpsLeft,
        runT: saveData.dino.runT || 0
      };
      g.obstacles = (saveData.obstacles || []).map(o => ({ type: o.type, x: o.x, w: o.w, h: o.h, bottom: o.bottom, group: o.group, frame: o.frame || 0 }));
      if (Array.isArray(saveData.pebbles) && saveData.pebbles.length) g.pebbles = saveData.pebbles.map(p => ({ x: p.x, len: p.len, y: p.y }));
      if (Array.isArray(saveData.clouds) && saveData.clouds.length) g.clouds = saveData.clouds.map(c => ({ x: c.x, y: c.y, s: c.s }));
    }
    dinoGame = g;
    dinoRenderUI();
    dinoAttachInput(g);
    g.lastTs = performance.now();
    g.rafId = dinoRaf(dinoTick);
  }

  function dinoTeardown(renderLobby) {
    const g = dinoGame;
    dinoGame = null;
    if (g) {
      if (g.rafId) dinoCaf(g.rafId);
      if (g.keyHandler && g.doc) { try { g.doc.removeEventListener('keydown', g.keyHandler); } catch (e) { /* ignore */ } }
      if (g.keyUpHandler && g.doc) { try { g.doc.removeEventListener('keyup', g.keyUpHandler); } catch (e) { /* ignore */ } }
      if (g._onWinResize && g.doc) { try { (g.doc.defaultView || window).removeEventListener('resize', g._onWinResize); } catch (e) { /* ignore */ } }
    }
    if (renderLobby) renderMiniGameLobby();
  }

  function dinoExitToLobby() {
    const g = dinoGame;
    const saved = !!(g && dinoSaveGame(g));
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    dinoTeardown();
    renderMiniGameLobby();
    showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回小游戏大厅');
  }

  function dinoQuitToCenter() {
    dinoClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
    dinoTeardown();
    renderSetup();
    showToast('🚪 已结束本局恐龙游戏');
  }

  function dinoRenderUI() {
    const g = dinoGame;
    if (!g || !sheet) { renderMiniGameLobby(); return; }
    const best = dinoLoadBest();
    sheet.innerHTML = `
      <div style="display:flex;flex-direction:column;height:100%;width:100%;box-sizing:border-box;overflow:hidden;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 0 6px;flex:none;border-bottom:1px solid var(--ubp-line);">
          <div style="display:flex;align-items:center;gap:8px;">
            <button data-ubp-act="dino-exit" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="保存进度并返回小游戏大厅">←</button>
            <span style="font-size:16px;font-weight:700;color:var(--ubp-text);">🦖 恐龙游戏</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span id="dino-points-label">${pointsLabelHTML()}</span>
            <span id="dino-best-label" style="font-size:11.5px;font-weight:600;color:#F59E0B;background:rgba(245,158,11,0.12);padding:2px 8px;border-radius:999px;border:1px solid rgba(245,158,11,0.35);">🏆 最高 ${best}</span>
            <button data-ubp-act="dino-quit" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);" title="结束本局并返回游戏入口（不保存进度）">✕</button>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;flex:none;">
          <div style="font-size:13px;color:var(--ubp-text);">得分: <b id="dino-score-text" style="color:#38BDF8;font-size:18px;vertical-align:-1px;">0</b></div>
          <div id="dino-mode-text" style="font-size:12px;color:var(--ubp-text-2);">☀️ 白天</div>
          <div id="dino-speed-text" style="font-size:12px;color:var(--ubp-text-2);">速度: <b style="color:#F59E0B;">LV.1</b></div>
        </div>
        <div id="dino-stage" style="position:relative;flex:1;min-height:0;border-radius:12px;overflow:hidden;border:1px solid var(--ubp-line);background:#F5F5F3;">
          <canvas id="dino-canvas" style="width:100%;height:100%;display:block;touch-action:none;"></canvas>
        </div>
        <div style="flex:none;padding:8px 2px 2px;">
          <div style="display:flex;justify-content:center;align-items:center;gap:10px;">
            <button id="dino-jump-btn" data-dino-act="jump" class="ubp-btn primary" style="flex:1;max-width:150px;padding:11px 0;font-size:13.5px;font-weight:700;">⬆ 跳跃</button>
            <button id="dino-duck-btn" data-dino-act="duck" class="ubp-btn" style="flex:1;max-width:150px;padding:11px 0;font-size:13.5px;">⬇ 下蹲（按住）</button>
            <button data-ubp-act="dino-restart" class="ubp-btn" style="padding:11px 12px;font-size:13px;">🔄</button>
          </div>
          <div style="font-size:11px;color:var(--ubp-text-3);text-align:center;margin-top:6px;">空格 / ↑ 跳跃（空中可再跳一次）· ↓ 按住下蹲 · 低空翼龙跳、头顶翼龙蹲 · 每 500 分 +1 积分</div>
        </div>
      </div>
    `;
    g.stageEl = sheet.querySelector('#dino-stage');
    g.canvas = sheet.querySelector('#dino-canvas');
    dinoUpdateHud(g);
  }

  function dinoUpdateHud(g) {
    if (!g || !sheet) return;
    const s = sheet.querySelector('#dino-score-text');
    if (s) s.textContent = String(Math.floor(g.score));
    const md = sheet.querySelector('#dino-mode-text');
    if (md) md.textContent = g.night ? '🌙 夜晚' : '☀️ 白天';
    const sp = sheet.querySelector('#dino-speed-text');
    if (sp) {
      const lv = Math.min(10, Math.floor((dinoFactor(g) - 1) / 0.2) + 1);
      sp.innerHTML = '速度: <b style="color:#F59E0B;">LV.' + lv + '</b>';
    }
    const best = dinoLoadBest();
    if (g.score > best) dinoSaveBest(g.score);
    const bl = sheet.querySelector('#dino-best-label');
    if (bl) bl.textContent = '🏆 最高 ' + Math.round(Math.max(best, g.score));
  }

  function dinoJump() {
    const g = dinoGame;
    if (!g || g.over) return;
    const d = g.dino;
    if (d.y <= 0) {
      d.vy = 1.5 * (g.W || DINO_REF_W);
      d.jumpsLeft = 1;
      d.y = 0.0001;
    } else if (d.jumpsLeft > 0) {
      d.vy = 1.35 * (g.W || DINO_REF_W);
      d.jumpsLeft -= 1;
    }
  }

  function dinoSetDuck(held) {
    const g = dinoGame;
    if (!g || g.over) return;
    g.dino.duck = !!held;
  }

  function dinoCheckMilestones(g) {
    let crossed = false;
    while (g.score >= g.nextRewardAt) {
      g.nextRewardAt += DINO_REWARD_STEP;
      g.rewards += 1;
      addPoints(1);
      crossed = true;
    }
    if (crossed) {
      const pl = sheet ? sheet.querySelector('#dino-points-label') : null;
      if (pl) pl.innerHTML = pointsLabelHTML();
      showToast('🎉 累计得分 ' + Math.floor(g.score) + '！积分 +1（当前 ' + loadPoints() + '）');
    }
  }

  function dinoDie(g) {
    if (g.over) return;
    g.over = true;
    g.shake = 1;
    dinoClearSave();
    const ref = g;
    setTimeout(() => { if (dinoGame === ref) dinoGameOver(ref); }, 480);
  }

  function dinoUpdate(g, dt) {
    if (!g) return;
    g.time += dt;
    if (g.flash > 0) g.flash = Math.max(0, g.flash - dt);
    if (g.shake > 0) g.shake = Math.max(0, g.shake - dt * 2.2);
    if (g.over) return;
    const W = g.W || DINO_REF_W;
    const speed = dinoSpeed(g);
    // 计分（封顶 99999）
    if (g.score < DINO_MAX_SCORE) {
      g.score = Math.min(DINO_MAX_SCORE, g.score + dt * 10 * dinoFactor(g));
      dinoCheckMilestones(g);
    }
    // 昼夜切换
    const night = Math.floor(g.score / DINO_DAY_NIGHT_STEP) % 2 === 1;
    if (night !== g.night) {
      g.night = night;
      g.flash = 0.35;
      if (sheet) {
        const md = sheet.querySelector('#dino-mode-text');
        if (md) md.textContent = night ? '🌙 夜晚' : '☀️ 白天';
      }
    }
    // 背景层
    g.bgShift += speed * 0.2 * dt;
    for (const p of g.pebbles) {
      p.x -= speed * dt;
      if (p.x < -30) { p.x += W + 40 + Math.random() * 80; p.len = 4 + Math.random() * 10; p.y = 3 + Math.random() * 7; }
    }
    for (const c of g.clouds) {
      c.x -= speed * 0.45 * dt;
      if (c.x < -90) { c.x += W + 100 + Math.random() * 140; c.y = (g.H || 480) * (0.08 + Math.random() * 0.24); }
    }
    // 障碍生成与移动
    g.nextSpawnIn -= speed * dt;
    if (g.nextSpawnIn <= 0) {
      dinoSpawnObstacle(g);
      g.nextSpawnIn = dinoNextGap(g);
    }
    for (let i = g.obstacles.length - 1; i >= 0; i--) {
      const ob = g.obstacles[i];
      ob.x -= speed * dt;
      if (ob.type === 'ptero') ob.frame = Math.floor(g.time * 8) % 2;
      if (ob.x + ob.w < -30) g.obstacles.splice(i, 1);
    }
    // 恐龙物理
    const G = 6.5 * W;
    const d = g.dino;
    if (d.y > 0 || d.vy !== 0) {
      let grav = G;
      if (d.duck) grav *= 1.9; // 空中按住 ↓ 快速下落
      d.vy -= grav * dt;
      d.y += d.vy * dt;
      if (d.y <= 0) { d.y = 0; d.vy = 0; d.jumpsLeft = 2; }
    } else {
      d.jumpsLeft = 2;
    }
    d.runT += dt;
    // 碰撞
    const pb = dinoPlayerBox(g);
    for (const ob of g.obstacles) {
      if (dinoOverlap(pb, dinoObstacleBox(g, ob))) { dinoDie(g); return; }
    }
    // HUD 节流刷新
    g.hudT += dt;
    if (g.hudT >= 0.25) {
      g.hudT = 0;
      dinoUpdateHud(g);
    }
  }

  function dinoGameOver(g) {
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('恐龙游戏'); } } catch (e) { /* ignore */ }
    dinoClearSave();
    const stage = sheet ? sheet.querySelector('#dino-stage') : null;
    if (!stage) return;
    stage.querySelectorAll('.dino-overlay').forEach(el => el.remove());
    const startBest = g.startBest || 0;
    const scoreI = Math.floor(g.score);
    const isNew = scoreI > startBest;
    const best = Math.max(startBest, scoreI);
    if (scoreI > dinoLoadBest()) dinoSaveBest(scoreI);
    const bl = sheet ? sheet.querySelector('#dino-best-label') : null;
    if (bl) bl.textContent = '🏆 最高 ' + best;
    const ov = document.createElement('div');
    ov.className = 'dino-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box;';
    ov.innerHTML = `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #38BDF8;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${isNew ? '🏆' : '🦴'}</div>
        <div style="font-size:15.5px;font-weight:700;color:var(--ubp-text);margin-bottom:8px;">${isNew ? '新纪录！' : 'GAME OVER'}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          本局得分：<b style="color:#38BDF8;font-size:17px;">${scoreI}</b><br>
          速度等级：<b style="color:#F59E0B;">LV.${Math.min(10, Math.floor((dinoFactor(g) - 1) / 0.2) + 1)}</b><br>
          最高分：<b style="color:#F59E0B;">${best}</b><br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.rewards}</b>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="dino-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#38BDF8;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="dino-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">碰到仙人掌 / 翼龙即结束 · 每 500 分 +1 积分</div>
      </div>
    `;
    stage.appendChild(ov);
  }

  function dinoTick(ts) {
    const g = dinoGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { dinoTeardown(false); return; }
    const dt = Math.min(0.05, Math.max(0.001, ((ts || performance.now()) - g.lastTs) / 1000 || 0.016));
    g.lastTs = ts || performance.now();
    dinoUpdate(g, dt);
    dinoDraw();
    g.rafId = dinoRaf(dinoTick);
  }

  function dinoDraw() {
    const g = dinoGame;
    if (!g) return;
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.W = cssW;
    g.H = cssH;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const theme = dinoTheme(g);
    const W = g.W;
    const H = g.H;
    const groundY = dinoGroundY(g);
    ctx.fillStyle = theme.bg;
    ctx.fillRect(0, 0, W, H);
    // 夜晚：星星 + 月亮
    if (g.night) {
      ctx.fillStyle = '#F5F5C8';
      for (const st of g.stars) {
        const sx = ((st.x * W - g.bgShift * 0.6) % W + W) % W;
        ctx.globalAlpha = 0.75;
        ctx.fillRect(Math.round(sx), Math.round(st.y * H * 0.8), Math.max(1, Math.round(st.r)), Math.max(1, Math.round(st.r)));
      }
      ctx.globalAlpha = 1;
      const mx = W * 0.82;
      const my = H * 0.16;
      const mr = Math.max(10, H * 0.045);
      ctx.fillStyle = '#F5F5C8';
      ctx.beginPath();
      ctx.arc(mx, my, mr, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = theme.bg;
      ctx.beginPath();
      ctx.arc(mx - mr * 0.45, my - mr * 0.2, mr * 0.85, 0, Math.PI * 2);
      ctx.fill();
    }
    // 云朵
    ctx.fillStyle = theme.dim;
    for (const c of g.clouds) {
      const ch = Math.max(6, H * 0.022 * c.s);
      const cw = ch * 3.2;
      ctx.globalAlpha = g.night ? 0.5 : 0.9;
      ctx.fillRect(Math.round(c.x), Math.round(c.y), Math.round(cw), Math.round(ch));
      ctx.fillRect(Math.round(c.x + cw * 0.2), Math.round(c.y - ch * 0.7), Math.round(cw * 0.5), Math.round(ch * 0.8));
      ctx.fillRect(Math.round(c.x + cw * 0.55), Math.round(c.y - ch * 0.4), Math.round(cw * 0.34), Math.round(ch * 0.5));
    }
    ctx.globalAlpha = 1;
    // 地面
    ctx.fillStyle = theme.ground;
    ctx.fillRect(0, Math.round(groundY), W, 2);
    for (const p of g.pebbles) {
      ctx.fillStyle = theme.dim;
      ctx.fillRect(Math.round(p.x), Math.round(groundY + p.y), Math.round(p.len), 1);
    }
    // 障碍
    for (const ob of g.obstacles) {
