  var thgStockOpenFn = null, thgStockCloseFn = null, thgStockDetachFn = null, thgStockApiRef = null;

// __SFARM_ENGINE_BEGIN__
  // ============================================================
  // 星田小铺 STARFARM v2 · 竖屏休闲种田（💰 挣钱大厅）
  // ------------------------------------------------------------
  // 【设计文档摘要】
  // 角色：农场主（玩家）、12 种作物、蜂箱/蜜蜂、自动浇水器、风车、集市/种子商店。
  // 关卡：3×3 农田，初始 4 块，金币解锁其余地块；作物分种子→发芽→生长→成熟四阶段。
  // 数值：12 种作物各自有种子成本、基础售价、成熟时间、需水时间；收获时按品质结算。
