    const q = sfarmQualityDef(key);
    const text = q.icon + q.name + (count === undefined ? '' : '×' + count);
    return `<span class="sfarm-quality q-${q.key}">${text}</span>`;
  }
  function sfarmQualityLegendHTML() {
    return SFARM_QUALITIES.map(q => `<span class="sfarm-quality q-${q.key}">${q.icon}${q.name} ${Math.round(q.chance * 100)}% · ×${q.mul}</span>`).join('');
  }
  function sfarmSellMul(g) { return g && g.upgrades && g.upgrades.decor ? 1.1 : 1; }
  function sfarmSellValue(g, type, qty, quality) {
    const def = sfarmCropDef(type), q = sfarmQualityDef(quality);
    if (!def || !q) return 0;
    return Math.max(0, Math.floor(def.sell * Math.max(0, Number(qty) || 0) * q.mul * sfarmSellMul(g)));
  }
  function sfarmCropValue(g, type) {
    const inv = g && g.inventory && g.inventory[type];
    if (!inv) return 0;
    let total = 0;
    for (const key of SFARM_QUALITY_KEYS) total += sfarmSellValue(g, type, inv[key] || 0, key);
    return total;
  }
  function sfarmBagCount(g) {
    let n = 0;
    for (const type of SFARM_CROP_ORDER) {
      const inv = g.inventory && g.inventory[type];
      if (!inv) continue;
      for (const key of SFARM_QUALITY_KEYS) n += inv[key] || 0;
    }
    return n;
  }
  function sfarmBagValue(g) {
    let total = 0;
    for (const type of SFARM_CROP_ORDER) total += sfarmCropValue(g, type);
    return total;
  }
  function sfarmCropVisualHTML(type, stage) {
    const def = sfarmCropDef(type);
    if (!def) return '';
    const art = SFARM_ART.crops[type];
    if (art) {
      let src = '';
      if (typeof art === 'string') src = art;
      else if (typeof art === 'object' && art !== null) src = art[stage] || art[String(stage)] || '';
      if (src) return `<img src="${src}" style="width:34px;height:34px;object-fit:contain;display:block;margin:0 auto;" alt="">`;
    }
    if (stage <= 0) return '🌱';
    if (stage === 1) return '🌿';
    if (stage === 2) return def.icon;
    return def.icon + '<span class="sfarm-spark">✨</span>';
  }

  // ---- 时间来源：内置 / 数据库 ----
  function sfarmCurrentStoryDay() {
    const now = Date.now();
    if (now - sfarmStoryDayCache.at < 3000 && sfarmStoryDayCache.key) return sfarmStoryDayCache.key;
    let key = '';
    try { if (typeof getStoryDayKey === 'function') key = getStoryDayKey() || ''; } catch (e) { key = ''; }
    sfarmStoryDayCache = { at: now, key: key };
    return key;
  }
  function sfarmDayDiff(oldKey, newKey) {
    if (!oldKey || !newKey || oldKey === newKey) return 0;
    const a = String(oldKey), b = String(newKey);
    let am = /day:(\d+)/.exec(a), bm = /day:(\d+)/.exec(b);
    if (am && bm) { const d = Number(bm[1]) - Number(am[1]); return d > 0 ? Math.min(7, d) : 0; }
    am = /(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})/.exec(a);
    bm = /(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})/.exec(b);
    if (am && bm) {
      const da = Date.UTC(Number(am[1]), Number(am[2]) - 1, Number(am[3]));
      const db = Date.UTC(Number(bm[1]), Number(bm[2]) - 1, Number(bm[3]));
      const d = Math.round((db - da) / 86400000);
      return d > 0 ? Math.min(7, d) : 0;
    }
    return 1;
  }
  function sfarmDbOffset() {
    try {
      const key = sfarmCurrentStoryDay();
      const raw = localStorage.getItem(SFARM_DB_CLOCK_KEY);
      let c = raw ? JSON.parse(raw) : null;
      const now = Date.now();
      if (!c || typeof c !== 'object') c = { dayKey: key, offset: 0, savedAt: now };
      else if (key && c.dayKey && key !== c.dayKey) {
        const diff = sfarmDayDiff(c.dayKey, key);
        if (diff > 0) c.offset = (Number(c.offset) || 0) + diff * 86400000;
        c.dayKey = key;
      } else if (key && !c.dayKey) c.dayKey = key;
      c.savedAt = now;
      localStorage.setItem(SFARM_DB_CLOCK_KEY, JSON.stringify(c));
      return Number(c.offset) || 0;
    } catch (e) { return 0; }
  }
  function sfarmNow(mode) { return mode === 'db' ? Date.now() + sfarmDbOffset() : Date.now(); }
  function sfarmTimeLabel(g) { return g && g.timeMode === 'db' ? '🗄 数据库时间' : '⏱ 内置时间'; }

  // ---- 存档 / 迁移 ----
  function sfarmEmptyInventory() {
    const inv = {};
    for (const type of SFARM_CROP_ORDER) {
      inv[type] = { bronze: 0, silver: 0, gold: 0, rainbow: 0 };
    }
    return inv;
  }
  function sfarmDefaultState() {
    const plots = [];
    for (let i = 0; i < SFARM_GRID; i++) plots.push({ unlocked: i < 4, tilled: false, crop: null });
    const seeds = {};
    for (const t of SFARM_CROP_ORDER) seeds[t] = 0;
    seeds.radish = 3;
    seeds.tomato = 1;
    const beeBoxes = [];
    for (let i = 0; i < 6; i++) beeBoxes.push({ box: false, beeExpiresAt: 0 });
    return {
      v: SFARM_VERSION, coins: 120, plots, inventory: sfarmEmptyInventory(), seeds,
      selectedSeed: 'radish', upgrades: { autoWater: false, decor: false },
      batteryMs: 0, batteries: 0, beehives: 0, bees: [], beeBoxes,
      timeMode: 'local', lastTick: Date.now(), saveTick: 0,
      stats: { harvested: 0, sold: 0, planted: 0, autoPlanted: 0 }
    };
  }
  function sfarmInitialState() {
    const g = sfarmDefaultState();
    g.lastTick = sfarmNow('local');
    return g;
  }
  function sfarmNormalizeCrop(crop) {
    if (!crop || !sfarmCropDef(crop.type)) return null;
    const ms = sfarmCropMs(crop.type);
    return {
      type: crop.type,
      growth: sfarmClamp(Number(crop.growth) || 0, 0, ms),
      water: sfarmClamp(Number(crop.water) || 0, 0, 100),
      plantedAt: Number(crop.plantedAt) || 0,
      wateredAt: Number(crop.wateredAt) || 0
    };
  }
  function sfarmNormalizeInvEntry(raw, isV1) {
    const out = { bronze: 0, silver: 0, gold: 0, rainbow: 0 };
    if (isV1 && (typeof raw === 'number' || typeof raw === 'string')) {
      out.bronze = Math.max(0, Math.floor(Number(raw) || 0));
      return out;
    }
    if (raw && typeof raw === 'object') {
      for (const k of SFARM_QUALITY_KEYS) out[k] = Math.max(0, Math.floor(Number(raw[k]) || 0));
    }
    return out;
  }
  function sfarmNormalize(raw) {
    if (!raw || typeof raw !== 'object' || (raw.v !== 1 && raw.v !== 2)) return null;
    const isV1 = raw.v === 1;
    const g = sfarmDefaultState();
    g.coins = Number.isFinite(Number(raw.coins)) ? Math.max(0, Math.floor(Number(raw.coins))) : 120;
    g.plots = [];
    for (let i = 0; i < SFARM_GRID; i++) {
      const p = (raw.plots && raw.plots[i]) || {};
      g.plots.push({
        unlocked: p.unlocked !== undefined ? !!p.unlocked : i < 4,
        tilled: !!p.tilled,
        crop: sfarmNormalizeCrop(p.crop)
      });
    }
    if (!g.plots.some(p => p.unlocked)) g.plots[0].unlocked = true;
    g.inventory = sfarmEmptyInventory();
    for (const t of SFARM_CROP_ORDER) {
      g.inventory[t] = sfarmNormalizeInvEntry(raw.inventory && raw.inventory[t], isV1);
      g.seeds[t] = Math.max(0, Math.floor(Number(raw.seeds && raw.seeds[t]) || 0));
    }
    g.selectedSeed = sfarmCropDef(raw.selectedSeed) ? raw.selectedSeed : 'radish';
    g.upgrades.autoWater = !!(raw.upgrades && raw.upgrades.autoWater);
    g.upgrades.decor = !!(raw.upgrades && raw.upgrades.decor);
    g.batteryMs = sfarmClamp(Number(raw.batteryMs) || 0, 0, SFARM_BATTERY_MS);
    g.batteries = Math.max(0, Math.floor(Number(raw.batteries) || 0));
    g.beehives = Math.max(0, Math.floor(Number(raw.beehives) || 0));
    g.bees = [];
    if (Array.isArray(raw.bees)) {
      for (const b of raw.bees) {
        if (b && Number(b.expiresAt) > 0) g.bees.push({ id: String(b.id || ('bee' + Math.random().toString(36).slice(2))), expiresAt: Number(b.expiresAt) });
        if (g.bees.length >= 20) break;
      }
    }
    g.beeBoxes = [];
    for (let i = 0; i < 6; i++) {
      const b = (raw.beeBoxes && raw.beeBoxes[i]) || {};
      g.beeBoxes.push({ box: !!b.box, beeExpiresAt: b.box ? Math.max(0, Number(b.beeExpiresAt) || 0) : 0 });
    }
    g.timeMode = raw.timeMode === 'db' ? 'db' : 'local';
    g.lastTick = Number.isFinite(Number(raw.lastTick)) ? Number(raw.lastTick) : Date.now();
    g.stats = {
      harvested: Math.max(0, Math.floor(Number(raw.stats && raw.stats.harvested) || 0)),
      sold: Math.max(0, Math.floor(Number(raw.stats && raw.stats.sold) || 0)),
      planted: Math.max(0, Math.floor(Number(raw.stats && raw.stats.planted) || 0)),
      autoPlanted: Math.max(0, Math.floor(Number(raw.stats && raw.stats.autoPlanted) || 0))
    };
    if (isV1) {
      // v1 → v2：旧作物默认为铜星；旧的自动浇水器赠送一块电池；旧的蜜蜂升级转换为 1 个带蜜蜂的蜂箱。
      if (g.upgrades.autoWater && g.batteryMs <= 0) g.batteryMs = SFARM_BATTERY_MS;
      if (raw.upgrades && raw.upgrades.bee) {
        g.beeBoxes[0] = { box: true, beeExpiresAt: Date.now() + SFARM_BEE_BOX_MS };
      }
    }
    return g;
  }
  function sfarmLoad() {
    try {
      const raw = localStorage.getItem(SFARM_SAVE_KEY);
      if (!raw) return null;
      return sfarmNormalize(JSON.parse(raw));
    } catch (e) { return null; }
  }
  function sfarmPeekCoins() {
    try {
      const raw = localStorage.getItem(SFARM_SAVE_KEY);
      if (raw) {
        const d = JSON.parse(raw);
        if (d && (d.v === 1 || d.v === 2) && Number.isFinite(Number(d.coins))) return Math.max(0, Math.floor(Number(d.coins)));
      }
    } catch (e) { /* ignore */ }
    return 120;
  }
  function sfarmSave(g) {
    if (!g) return;
    try {
      const data = {
        v: SFARM_VERSION,
        coins: Math.max(0, Math.floor(g.coins)),
        plots: g.plots.map(p => ({
          unlocked: !!p.unlocked, tilled: !!p.tilled,
          crop: p.crop ? { type: p.crop.type, growth: p.crop.growth, water: p.crop.water, plantedAt: p.crop.plantedAt, wateredAt: p.crop.wateredAt } : null
        })),
        inventory: g.inventory, seeds: g.seeds, selectedSeed: g.selectedSeed,
        upgrades: g.upgrades, batteryMs: g.batteryMs, batteries: g.batteries,
        beehives: g.beehives, bees: g.bees, beeBoxes: g.beeBoxes,
        timeMode: g.timeMode, lastTick: g.lastTick, stats: g.stats
      };
      localStorage.setItem(SFARM_SAVE_KEY, JSON.stringify(data));
      g.saveTick = 0;
    } catch (e) { /* ignore */ }
  }
  // 资金互通兑换用：直接增减星田小铺农场金币（无存档时按初始存档建立；负数不足则失败）
  function sfarmCoinAdjust(delta) {
    const d = Math.round(Number(delta) || 0);
    if (!d) return true;
    try {
      let g = sfarmLoad();
      if (!g) g = sfarmInitialState();
      if (d < 0 && g.coins + d < 0) return false;
      g.coins = Math.max(0, Math.floor(g.coins + d));
      sfarmCommit(g);
      return true;
    } catch (e) { return false; }
  }
  function sfarmEnsurePlayable(g) {
    if (!g) return false;
    const hasCrop = g.plots.some(p => p.crop);
    const hasSeed = SFARM_CROP_ORDER.some(t => (g.seeds[t] || 0) > 0);
    const hasBag = sfarmBagCount(g) > 0;
    if (!hasCrop && !hasSeed && !hasBag && g.coins < SFARM_CROPS.radish.cost) {
      g.coins += 20;
      showToast('🎁 农场补给：金币 +20，先去商店买点萝卜种子吧');
      return true;
    }
    return false;
  }

  // ---- 生长 / 电池 / 蜜蜂 ----
  function sfarmActiveBeeCount(g, at) {
    if (!g) return 0;
    const now = at === undefined ? sfarmNow(g.timeMode) : at;
    return g.beeBoxes.filter(b => b.box && b.beeExpiresAt > now).length;
  }
  function sfarmLiveBagBees(g, at) {
    if (!g) return [];
    const now = at === undefined ? sfarmNow(g.timeMode) : at;
    return g.bees.filter(b => b.expiresAt > now);
  }
  function sfarmBeeSpeed(g, elapsedSec, startAt) {
    if (!g || elapsedSec <= 0) return 1;
    let beeSec = 0;
    for (const b of g.beeBoxes) {
      if (b.box && b.beeExpiresAt > startAt) {
        const sec = Math.min(elapsedSec, Math.max(0, (b.beeExpiresAt - startAt) / 1000));
        if (sec > 0) beeSec += sec;
      }
    }
    return 1 + 0.05 * Math.min(6, beeSec / elapsedSec);
  }
  function sfarmAutoActive(g) { return !!(g && g.upgrades && g.upgrades.autoWater && g.batteryMs > 0); }
  function sfarmGrow(g, elapsedMs, startAt) {
    if (!g || elapsedMs <= 0) return;
    const elapsedSec = Math.min(elapsedMs / 1000, 7 * 86400);
    if (elapsedSec <= 0) return;
    const begin = Number.isFinite(Number(startAt)) ? Number(startAt) : sfarmNow(g.timeMode) - elapsedMs;
    const speed = sfarmBeeSpeed(g, elapsedSec, begin);
    const autoDevice = !!(g.upgrades && g.upgrades.autoWater);
    const batterySec = autoDevice && g.batteryMs > 0 ? Math.min(elapsedSec, g.batteryMs / 1000) : 0;
    if (autoDevice) g.batteryMs = Math.max(0, g.batteryMs - elapsedSec * 1000);
    for (const p of g.plots) {
      if (!p.unlocked || !p.crop) continue;
      const def = sfarmCropDef(p.crop.type);
      if (!def) continue;
      const ms = def.growSec * 1000;
      if (p.crop.growth >= ms) { if (batterySec > 0) p.crop.water = 100; continue; }
      let remainSec = Math.max(0, (ms - p.crop.growth) / 1000 / speed);
      let autoSec = batterySec;
      if (autoSec > 0) {
        const eff = Math.min(autoSec, remainSec);
        p.crop.water = 100;
        p.crop.growth = Math.min(ms, p.crop.growth + eff * 1000 * speed);
        remainSec -= eff;
        autoSec -= eff;
      }
      if (p.crop.growth >= ms) continue;
      const normalSec = elapsedSec - batterySec;
      if (normalSec > 0 && remainSec > 0) {
        const waterSec = Math.max(0, (p.crop.water / 100) * def.waterSec);
        const eff = Math.min(normalSec, waterSec, remainSec);
        if (def.waterSec > 0) p.crop.water = Math.max(0, p.crop.water - (eff / def.waterSec) * 100);
        p.crop.growth = Math.min(ms, p.crop.growth + eff * 1000 * speed);
      }
    }
  }
  function sfarmExpire(g, now, notify) {
    if (!g) return { bag: 0, box: 0 };
    const n = now === undefined ? sfarmNow(g.timeMode) : now;
    const beforeBag = g.bees.length;
    g.bees = g.bees.filter(b => b && b.expiresAt > n);
    let expiredBox = 0;
    for (const b of g.beeBoxes) {
      if (b.box && b.beeExpiresAt > 0 && b.beeExpiresAt <= n) { b.beeExpiresAt = 0; expiredBox++; }
    }
    const expiredBag = beforeBag - g.bees.length;
    if (notify) {
      if (expiredBag > 0) showToast('🐝 背包里的蜜蜂飞走了 ×' + expiredBag);
      if (expiredBox > 0) showToast('🐝 蜂箱里的蜜蜂飞走了 ×' + expiredBox);
    }
    return { bag: expiredBag, box: expiredBox };
  }
  function sfarmAdvance(g) {
    if (!g) return;
    const now = sfarmNow(g.timeMode);
    const last = Number(g.lastTick) || now;
    const elapsed = now - last;
    if (elapsed > 0) sfarmGrow(g, elapsed, last);
    g.lastTick = now;
  }
  function sfarmCommit(g) {
    if (!g) return;
    sfarmAdvance(g);
    sfarmExpire(g, sfarmNow(g.timeMode), false);
    sfarmSave(g);
  }
  function sfarmApplyOffline(g) {
    if (!g) return { battery: false, bag: 0, box: 0 };
    const now = sfarmNow(g.timeMode);
    const last = Number(g.lastTick) || now;
    const elapsed = now - last;
    const batteryBefore = g.batteryMs;
    if (elapsed > 0) sfarmGrow(g, elapsed, last);
    g.lastTick = now;
    const exp = sfarmExpire(g, now, false);
    return { battery: batteryBefore > 0 && g.batteryMs <= 0 && g.upgrades.autoWater, bag: exp.bag, box: exp.box };
  }

  // ---- 购买 / 安装 / 蜜蜂播种 ----
  function sfarmBuySeed(g, type) {
    const def = sfarmCropDef(type);
    if (!def) return false;
    if (g.coins < def.cost) { sfarmPlaySfx('error', 0.4); showToast('🪙 金币不足，购买 ' + def.name + '种子需要 ' + def.cost); return false; }
    g.coins -= def.cost;
    g.seeds[type] = (g.seeds[type] || 0) + 1;
    g.selectedSeed = type;
    sfarmPlaySfx('coin', 0.5);
    sfarmCommit(g);
    sfarmUpdateHud(g);
    showToast('🌰 购买了 ' + def.name + '种子 ×1（当前 ' + g.seeds[type] + '）');
    return true;
  }
  function sfarmBuyTool(g, key) {
    const tool = SFARM_TOOLS[key];
    if (!tool) return false;
    if ((key === 'autoWater' && g.upgrades.autoWater) || (key === 'windmill' && g.upgrades.decor)) { showToast('✅ ' + tool.name + ' 已拥有'); return false; }
    if ((key === 'battery' && g.batteries >= 99) || (key === 'beehive' && g.beehives >= 6) || (key === 'bee' && g.bees.length >= 20)) {
      showToast('🎒 ' + tool.name + ' 背包已满，先使用一些再来买吧');
      return false;
    }
    if (g.coins < tool.price) { sfarmPlaySfx('error', 0.4); showToast('🪙 金币不足，购买 ' + tool.name + ' 需要 ' + tool.price); return false; }
    g.coins -= tool.price;
    if (key === 'autoWater') {
      g.upgrades.autoWater = true;
      showToast('💧 已购买自动浇水器；请再购买电池并点击自动浇水器安装');
    } else if (key === 'windmill') {
      g.upgrades.decor = true;
      showToast('🎏 风车已放置，集市售价 +10%');
    } else if (key === 'battery') {
      g.batteries++;
      showToast('🔋 电池进入背包 ×1；点击自动浇水器安装');
    } else if (key === 'beehive') {
      g.beehives++;
      showToast('📦 蜂箱进入背包 ×1；点击农田两侧的空蜂箱格放置');
    } else if (key === 'bee') {
      const now = sfarmNow(g.timeMode);
      g.bees.push({ id: 'bee' + now.toString(36) + Math.random().toString(36).slice(2, 5), expiresAt: now + SFARM_BEE_BAG_MS });
      showToast('🐝 蜜蜂进入背包；3 分钟内放入蜂箱，否则会飞走');
    }
    sfarmPlaySfx('upgrade', 0.8);
    sfarmCommit(g);
    sfarmUpdateHud(g);
    return true;
  }
  function sfarmInstallBattery(g) {
    if (!g.upgrades.autoWater) {
      showToast('💧 请先购买自动浇水器');
      sfarmShopTab = 'tools';
      sfarmOpenOverlay('shop');
      return false;
    }
    if (g.batteryMs > 0) { showToast('🔋 自动浇水器还有电，剩余 ' + sfarmFmtCountdown(g.batteryMs)); return false; }
    if (g.batteries <= 0) {
      showToast('🔋 背包里没有电池，先去商店购买');
      sfarmShopTab = 'tools';
      sfarmOpenOverlay('shop');
      return false;
    }
    g.batteries--;
    g.batteryMs = SFARM_BATTERY_MS;
    sfarmCommit(g);
    sfarmUpdateHud(g);
    showToast('🔋 已装上电池，自动浇水器可工作 10 分钟');
    return true;
  }
  function sfarmInstallHive(g, idx) {
    if (g.beeBoxes[idx].box) return false;
    if (g.beehives <= 0) {
      showToast('📦 背包里没有蜂箱，先去商店购买');
      sfarmShopTab = 'tools';
      sfarmOpenOverlay('shop');
      return false;
    }
    g.beehives--;
    g.beeBoxes[idx].box = true;
    g.beeBoxes[idx].beeExpiresAt = 0;
    sfarmCommit(g);
    sfarmRender(g);
    showToast('📦 已在 ' + (idx < 3 ? '左侧' : '右侧') + '第 ' + ((idx % 3) + 1) + ' 格放置蜂箱；再放入蜜蜂即可工作');
    return true;
  }
  function sfarmPlaceBee(g, idx) {
    if (!g.beeBoxes[idx].box) return sfarmInstallHive(g, idx);
    const now = sfarmNow(g.timeMode);
    if (g.beeBoxes[idx].beeExpiresAt > now) { showToast('🐝 这个蜂箱里已经有蜜蜂了'); return false; }
    const live = sfarmLiveBagBees(g, now);
    if (!live.length) {
      showToast('🐝 背包里没有蜜蜂，先去商店购买');
      sfarmShopTab = 'tools';
      sfarmOpenOverlay('shop');
      return false;
    }
    const bee = live[0];
    g.bees = g.bees.filter(b => b.id !== bee.id);
    g.beeBoxes[idx].beeExpiresAt = now + SFARM_BEE_BOX_MS;
    sfarmPlaySfx('bee', 0.7);
    sfarmCommit(g);
    sfarmRender(g);
    showToast('🐝 蜜蜂已放入蜂箱，可工作 10 分钟；可把种子拖到蜂箱让它自动播种');
    return true;
  }
  function sfarmHiveAction(g, idx) {
    sfarmAdvance(g);
    sfarmExpire(g, sfarmNow(g.timeMode), false);
    const state = sfarmHiveState(g, idx, sfarmNow(g.timeMode));
    if (state === 'empty') return sfarmInstallHive(g, idx);
    if (state === 'box') return sfarmPlaceBee(g, idx);
    if ((g.seeds[g.selectedSeed] || 0) > 0) return sfarmBeeSow(g, idx, g.selectedSeed);
    showToast('🐝 把种子拖到蜂箱，或先选种子再点击蜂箱');
    return false;
  }
  function sfarmBeeSow(g, idx, seedType) {
    sfarmAdvance(g);
    sfarmExpire(g, sfarmNow(g.timeMode), false);
    const now = sfarmNow(g.timeMode);
    const box = g.beeBoxes[idx];
    if (!box || !box.box || box.beeExpiresAt <= now) { showToast('🐝 这个蜂箱里没有正在工作的蜜蜂'); return false; }
    const def = sfarmCropDef(seedType);
    if (!def) return false;
    if ((g.seeds[seedType] || 0) <= 0) { showToast('🌰 背包里没有 ' + def.name + '种子'); return false; }
    const pi = g.plots.findIndex(p => p.unlocked && !p.crop && p.tilled);
    if (pi < 0) { showToast('🟫 没有已翻土的空地，蜜蜂无法播种'); return false; }
    g.seeds[seedType]--;
    g.plots[pi].crop = { type: seedType, growth: 0, water: 0, plantedAt: now, wateredAt: 0 };
    g.stats.planted = (g.stats.planted || 0) + 1;
    g.stats.autoPlanted = (g.stats.autoPlanted || 0) + 1;
    sfarmPlaySfx('plant', 0.6);
    sfarmCommit(g);
    sfarmRender(g);
    showToast('🐝 蜜蜂在 ' + (pi + 1) + ' 号地块自动播种了 ' + def.name);
    return true;
  }

  // ---- 地块 / 收割 / 集市 ----
  function sfarmTryUnlock(g, i, silent) {
    const p = g.plots[i];
    if (!p || p.unlocked) return false;
    const cost = SFARM_PLOT_COSTS[i] || 0;
    if (g.coins < cost) { sfarmPlaySfx('error', 0.4); showToast('🪙 金币不足，解锁地块需要 ' + cost + '（当前 ' + g.coins + '）'); return false; }
    g.coins -= cost;
    p.unlocked = true;
    p.tilled = false;
    sfarmPlaySfx('upgrade', 0.7);
    sfarmCommit(g);
    sfarmUpdateHud(g);
    if (!silent) sfarmRender(g);
    showToast('🌱 已解锁地块 ' + (i + 1) + '，花费 🪙 ' + cost);
    return true;
  }
  function sfarmHarvest(g, p) {
    const def = sfarmCropDef(p.crop.type);
    if (!def) return;
    const q = sfarmRollQuality();
    const qdef = sfarmQualityDef(q);
    g.inventory[p.crop.type][q] = (g.inventory[p.crop.type][q] || 0) + 1;
    g.stats.harvested = (g.stats.harvested || 0) + 1;
    p.crop = null;
    p.tilled = true;
    sfarmPlaySfx('harvest', 0.8);
    sfarmCommit(g);
    sfarmRender(g);
    showToast('🧺 收割了 1 个 ' + def.name + ' · ' + qdef.icon + qdef.name + '（已放入背包）');
  }
  function sfarmPlotAction(g, i) {
    const p = g.plots[i];
    if (!p) return;
    sfarmAdvance(g);
    sfarmExpire(g, sfarmNow(g.timeMode), false);
    const now = sfarmNow(g.timeMode);
    if (!p.unlocked) { sfarmTryUnlock(g, i); return; }
    if (p.crop) {
      if (sfarmIsMature(p.crop)) { sfarmHarvest(g, p); return; }
      if (p.crop.water < 100) {
        p.crop.water = 100;
        p.crop.wateredAt = now;
        sfarmPlaySfx('water', 0.6);
        sfarmCommit(g);
        sfarmRender(g);
        showToast('💧 已浇水，作物继续生长');
        return;
      }
      showToast('🌿 作物正在生长，水分充足');
      return;
    }
    if (!p.tilled) {
      p.tilled = true;
      sfarmPlaySfx('plant', 0.4);
      sfarmCommit(g);
      sfarmRender(g);
      showToast('🪓 已翻土，选择种子后再点击播种');
      return;
    }
    const type = g.selectedSeed;
    const def = sfarmCropDef(type);
    if (!def) { showToast('请先选择种子'); return; }
    if ((g.seeds[type] || 0) <= 0) {
      showToast('🌰 ' + def.name + '种子不足，去商店购买');
      sfarmShopTab = 'seeds';
      sfarmOpenOverlay('shop');
      return;
    }
    g.seeds[type]--;
    p.crop = { type, growth: 0, water: 0, plantedAt: now, wateredAt: 0 };
    g.stats.planted = (g.stats.planted || 0) + 1;
    sfarmPlaySfx('plant', 0.7);
    sfarmCommit(g);
    sfarmRender(g);
    showToast('🌱 播种了 ' + def.name + '，点击地块浇水');
  }
  function sfarmSellAll(g) {
    const total = sfarmBagValue(g);
    if (total <= 0) { showToast('🛒 集市里没有可卖的作物，先去收割吧'); return 0; }
    g.coins += total;
    g.stats.sold = (g.stats.sold || 0) + total;
    for (const t of SFARM_CROP_ORDER) for (const q of SFARM_QUALITY_KEYS) g.inventory[t][q] = 0;
    sfarmPlaySfx('sell', 0.9);
    sfarmCommit(g);
    sfarmUpdateHud(g);
    showToast('🛒 一键卖出全部作物，获得 🪙 ' + total);
    return total;
  }
  function sfarmSellCrop(g, type) {
    const total = sfarmCropValue(g, type);
    if (total <= 0) return 0;
    const def = sfarmCropDef(type);
    g.coins += total;
    g.stats.sold = (g.stats.sold || 0) + total;
    for (const q of SFARM_QUALITY_KEYS) g.inventory[type][q] = 0;
    sfarmPlaySfx('sell', 0.7);
    sfarmCommit(g);
    sfarmUpdateHud(g);
    showToast('🛒 卖出 ' + (def ? def.name : type) + ' 全部品质，获得 🪙 ' + total);
    return total;
  }

  // ---- 时间切换 / 资金兑换 ----
  function sfarmSetTimeMode(g, mode) {
    const next = mode === 'db' ? 'db' : 'local';
    if (g.timeMode === next) { showToast('⏱ 当前已经是' + (next === 'db' ? '数据库时间' : '内置时间')); return; }
    g.timeMode = next;
    // 切换时以新时间源重置基准，避免重复叠加数据库偏移；跨天补生长在之后的推进中生效。
    g.lastTick = sfarmNow(next);
    sfarmCommit(g);
    sfarmUpdateHud(g);
    showToast(next === 'db' ? '🗄 已切换数据库时间（三文件共享时钟与存档）' : '⏱ 已切换内置时间（按本机真实时间）');
  }
  function sfarmGlobalFundName() {
    return '股市资金';
  }
  function sfarmGlobalFundBalance() {
    try { if (typeof treasuryBalance === 'function') return Math.max(0, Math.floor(Number(treasuryBalance()) || 0)); } catch (e) { /* ignore */ }
    return 0;
  }
  function sfarmGlobalFundAdjust(delta) {
    const d = Math.round(Number(delta) || 0);
    if (!d) return true;
    try {
      if (typeof treasuryAdjust === 'function') {
        return !!treasuryAdjust(d, '星田小铺 · 资金兑换', d > 0 ? 'game-win' : 'game-buyin');
      }
    } catch (e) { /* ignore */ }
    return false;
  }
  function sfarmPointsBalance() {
    try { if (typeof loadPoints === 'function') return Math.max(0, Math.floor(Number(loadPoints()) || 0)); } catch (e) { /* ignore */ }
    return 0;
  }
  function sfarmPointsAdjust(delta) {
    const d = Math.round(Number(delta) || 0);
    if (!d) return true;
    try { if (typeof addPoints === 'function') { addPoints(d); return true; } } catch (e) { /* ignore */ }
    return false;
  }
  function sfarmExchange(g, dir, amt) {
    if (!g) return false;
    const n = Number(amt);
    if (dir === 'farm-fund') {
      const coins = n < 0 ? g.coins : Math.min(g.coins, Math.max(0, Math.floor(n)));
      if (coins < 1) { showToast('请输入至少 1 农场金币'); return false; }
      const gain = coins * SFARM_FUND_PER_COIN;
      if (!sfarmGlobalFundAdjust(gain)) { showToast('💱 资金入账失败，请检查当前环境是否支持资金接口'); return false; }
      g.coins -= coins;
      sfarmCommit(g); sfarmUpdateHud(g);
      showToast('💱 ' + coins + ' 农场金币 → 🪙 ' + sfarmFmtNum(gain) + ' ' + sfarmGlobalFundName());
      return true;
    }
    if (dir === 'fund-farm') {
      const bal = sfarmGlobalFundBalance();
      const amount = n < 0 ? bal : Math.min(bal, Math.max(0, Math.floor(n)));
      const gain = Math.floor(amount / SFARM_FUND_PER_COIN_BUY);
      if (gain < 1) { showToast('💱 资金不足，至少需要 ' + sfarmFmtNum(SFARM_FUND_PER_COIN_BUY)); return false; }
      const cost = gain * SFARM_FUND_PER_COIN_BUY;
      if (!sfarmGlobalFundAdjust(-cost)) { showToast('💱 资金扣款失败或余额不足'); return false; }
      g.coins += gain;
      sfarmCommit(g); sfarmUpdateHud(g);
      showToast('💱 ' + sfarmFmtNum(cost) + ' ' + sfarmGlobalFundName() + ' → 🪙 ' + gain + ' 农场金币');
      return true;
    }
    if (dir === 'farm-points') {
      const coins = n < 0 ? g.coins : Math.min(g.coins, Math.max(0, Math.floor(n)));
      const pts = Math.floor(coins / SFARM_POINTS_PER_COIN);
      if (pts < 1) { showToast('💱 至少需要 ' + SFARM_POINTS_PER_COIN + ' 农场金币才能兑换 1 积分'); return false; }
      const cost = pts * SFARM_POINTS_PER_COIN;
      if (!sfarmPointsAdjust(pts)) { showToast('💱 积分入账失败'); return false; }
      g.coins -= cost;
      sfarmCommit(g); sfarmUpdateHud(g);
      showToast('💱 ' + cost + ' 农场金币 → 💎 ' + pts + ' 积分');
      return true;
    }
    if (dir === 'points-farm') {
      const bal = sfarmPointsBalance();
      const pts = n < 0 ? bal : Math.min(bal, Math.max(0, Math.floor(n)));
      if (pts < 1) { showToast('💱 积分不足，至少需要 1 积分'); return false; }
      if (!sfarmPointsAdjust(-pts)) { showToast('💱 积分扣款失败'); return false; }
      const gain = pts * SFARM_COINS_PER_POINT;
      g.coins += gain;
      sfarmCommit(g); sfarmUpdateHud(g);
      showToast('💱 ' + pts + ' 积分 → 🪙 ' + gain + ' 农场金币');
      return true;
    }
    return false;
  }

  // ---- 主界面渲染 ----
  function sfarmSeedChipHTML(g, type) {
    const def = sfarmCropDef(type);
    if (!def) return '';
    const n = g.seeds[type] || 0;
    return `<button draggable="true" data-sfarm-act="seed" data-seed="${type}" data-sfarm-drag-seed="${type}" class="sfarm-chip ${g.selectedSeed === type ? 'selected' : ''} ${n <= 0 ? 'dim' : ''}" title="${def.name}种子 ×${n}；成熟 ${sfarmFmtGrow(def.growSec)}，基础售价 🪙 ${def.sell}"><span>${def.icon}</span><span>${def.name}</span><span style="opacity:.7;">×${n}</span></button>`;
  }
  function sfarmPlotHTML(g, i) {
    const p = g.plots[i];
    const cost = SFARM_PLOT_COSTS[i] || 0;
    if (!p.unlocked) {
      return `<div id="sfarm-card-${i}" data-sfarm-act="plot" data-idx="${i}" class="sfarm-plot locked" title="解锁需要 ${cost} 金币"><div style="font-size:22px;">🔒</div><div style="font-size:10px;font-weight:800;">地块 ${i + 1}</div><div style="font-size:9px;margin-top:1px;">🪙 ${cost} 解锁</div></div>`;
    }
    if (!p.crop) {
      const seed = sfarmCropDef(g.selectedSeed);
      const label = p.tilled ? ('点击播种 ' + (seed ? seed.icon : '🌰')) : '点击翻土';
      return `<div id="sfarm-card-${i}" data-sfarm-act="plot" data-idx="${i}" class="sfarm-plot ${p.tilled ? 'tilled' : ''}" title="${label}"><div style="font-size:22px;text-align:center;">${p.tilled ? '🟫' : '🌾'}</div><div style="font-size:9.5px;text-align:center;font-weight:800;color:#fff3dc;">${p.tilled ? '已翻土' : '荒地'}</div><div style="font-size:8.5px;text-align:center;color:#fde68a;">${label}</div></div>`;
    }
    const def = sfarmCropDef(p.crop.type);
    if (!def) return `<div class="sfarm-plot" data-sfarm-act="plot" data-idx="${i}">?</div>`;
    const ratio = sfarmClamp(p.crop.growth / sfarmCropMs(p.crop.type), 0, 1);
    const stage = sfarmCropStage(p.crop);
    const mature = sfarmIsMature(p.crop);
    const water = sfarmClamp(p.crop.water, 0, 100);
    const mult = sfarmBeeSpeed(g, 1, sfarmNow(g.timeMode));
    const remainSec = Math.max(0, Math.ceil((sfarmCropMs(p.crop.type) - p.crop.growth) / 1000 / mult));
    const hint = mature ? '✨ 点击收割' : (water <= 0 ? '💧 缺水 · 点击浇水' : (water < 100 ? '🌿 ' + remainSec + 's · 💧' : '🌿 ' + remainSec + 's'));
    return `<div id="sfarm-card-${i}" data-sfarm-act="plot" data-idx="${i}" class="sfarm-plot ${mature ? 'mature' : ''}" style="border-color:${def.color}88;" title="${def.name} · ${sfarmStageLabel(stage)}">
      <div class="sfarm-plot-head"><span>${def.name}</span><span id="sfarm-stage-${i}">${sfarmStageLabel(stage)}</span></div>
      <div class="sfarm-plot-mid"><div id="sfarm-crop-${i}" data-stage="${stage}" class="sfarm-crop stage-${stage}">${sfarmCropVisualHTML(p.crop.type, stage)}</div></div>
      <div class="sfarm-bar"><i id="sfarm-prog-${i}" style="width:${(ratio * 100).toFixed(1)}%;background:${def.color};"></i></div>
      <div class="sfarm-bar"><i id="sfarm-water-${i}" style="width:${water.toFixed(1)}%;background:#38BDF8;"></i></div>
      <div id="sfarm-hint-${i}" class="sfarm-hint">${hint}</div>
    </div>`;
  }
  function sfarmHiveState(g, idx, now) {
    const b = g.beeBoxes[idx];
    if (!b || !b.box) return 'empty';
    return b.beeExpiresAt > now ? 'active' : 'box';
  }
  function sfarmHiveHTML(g, idx, now) {
    const state = sfarmHiveState(g, idx, now);
    const b = g.beeBoxes[idx];
    const remain = state === 'active' ? sfarmFmtCountdown(b.beeExpiresAt - now) : '';
    const title = state === 'empty' ? '空蜂箱格：需要蜂箱' : (state === 'box' ? '蜂箱缺蜜蜂：需要放入蜜蜂' : '蜜蜂工作中：可把种子拖到此格自动播种');
    return `<div id="sfarm-hive-${idx}" data-sfarm-act="hive" data-idx="${idx}" data-sfarm-drop="1" class="sfarm-hive ${state}" title="${title}">
      <span class="sfarm-hive-plus">＋</span>
      <span class="sfarm-hive-box">📦</span>
      <span class="sfarm-hive-bee">🐝</span>
      <span class="sfarm-hive-no">🚫</span>
      <span id="sfarm-hive-time-${idx}" class="sfarm-hive-time">${remain}</span>
    </div>`;
  }
  function sfarmAutoTileHTML(g) {
    const owned = !!g.upgrades.autoWater;
    const active = owned && g.batteryMs > 0;
    const cls = !owned ? 'locked' : (active ? 'on' : 'off');
    const status = !owned ? '商店购买 · 自动浇水' : (active ? ('自动浇水中 · 电池 ' + sfarmFmtCountdown(g.batteryMs)) : ('缺电池 · 点击安装（电池 ' + g.batteries + '）'));
    return `<div id="sfarm-autowater" data-sfarm-act="autowater" class="sfarm-tool ${cls}" title="自动浇水器：需要电池；点击安装电池">
      <div class="sfarm-tool-icons"><span class="sfarm-device">💧</span><span class="sfarm-battery">🔋</span><span class="sfarm-no">🚫</span></div>
      <div style="min-width:0;"><div class="sfarm-tool-name">自动浇水器</div><div id="sfarm-auto-status" class="sfarm-tool-status">${status}</div></div>
    </div>`;
  }
  function sfarmBeeBagTileHTML(g, now) {
    const live = sfarmLiveBagBees(g, now);
    const cls = live.length ? 'on' : 'off';
    const nearest = live.length ? Math.min(...live.map(b => b.expiresAt)) : 0;
    const status = live.length ? ('背包蜜蜂 ×' + live.length + ' · 最快 ' + sfarmFmtCountdown(nearest - now) + ' 飞走') : '背包无蜜蜂 · 点击商店';
    return `<div id="sfarm-beebag" data-sfarm-act="beebag" class="sfarm-tool ${cls}" title="蜜蜂背包：3 分钟不放入蜂箱会飞走">
      <div class="sfarm-tool-icons"><span class="sfarm-device">🐝</span><span class="sfarm-no">🚫</span></div>
      <div style="min-width:0;"><div class="sfarm-tool-name">蜜蜂背包</div><div id="sfarm-beebag-status" class="sfarm-tool-status">${status}</div></div>
    </div>`;
  }
  function sfarmWindmillTileHTML(g) {
    const owned = !!g.upgrades.decor;
    return `<div id="sfarm-windmill" data-sfarm-act="windmill" class="sfarm-tool ${owned ? 'on' : ''}" title="风车：集市售价 +10%">
      <div class="sfarm-tool-icons"><span class="sfarm-device" style="${owned ? 'animation:sfarmPulse 1.6s ease-in-out infinite;' : ''}">🎏</span></div>
      <div style="min-width:0;"><div class="sfarm-tool-name">风车装饰</div><div class="sfarm-tool-status">${owned ? '售价 +10% · 已生效' : '未购买 · 点击商店'}</div></div>
    </div>`;
  }
  function sfarmPageHTML(g) {
    const now = sfarmNow(g.timeMode);
    return SFARM_STYLE + `
      <div class="sfarm-page">
        <div class="sfarm-top">
          <div style="display:flex;align-items:center;gap:5px;min-width:0;">
            <button data-sfarm-act="back" class="sfarm-icon-btn" style="border:none;background:none;box-shadow:none;font-size:18px;width:26px;" title="保存并返回挣钱大厅">←</button>
            <span class="sfarm-title">🌾 星田小铺</span>
          </div>
          <div style="display:flex;align-items:center;gap:4px;flex:none;">
