          <div class="sfarm-field-wrap">
            <div class="sfarm-side">${[0, 1, 2].map(i => sfarmHiveHTML(g, i, now)).join('')}</div>
            <div class="sfarm-grid">${g.plots.map((_, i) => sfarmPlotHTML(g, i)).join('')}</div>
            <div class="sfarm-side">${[3, 4, 5].map(i => sfarmHiveHTML(g, i, now)).join('')}</div>
          </div>
          <div class="sfarm-big-actions">
            <button data-sfarm-act="shop" class="sfarm-bigbtn shop"><span class="sfarm-bigicon">🏪</span><span class="sfarm-bigtext"><b>种子商店</b><small>12 种作物 · 工具 · 地块</small></span></button>
            <button data-sfarm-act="market" class="sfarm-bigbtn market"><span class="sfarm-bigicon">🛒</span><span class="sfarm-bigtext"><b>集市</b><small>按品质卖出 · 一键清仓</small></span></button>
          </div>
        </div>
      </div>`;
  }
  function sfarmUpdatePlotDom(g, i) {
    if (!sheet || !sheet.querySelector) return;
    const p = g.plots[i];
    if (!p || !p.crop) return;
    const def = sfarmCropDef(p.crop.type);
    if (!def) return;
    const ratio = sfarmClamp(p.crop.growth / sfarmCropMs(p.crop.type), 0, 1);
    const stage = sfarmCropStage(p.crop);
    const mature = sfarmIsMature(p.crop);
    const water = sfarmClamp(p.crop.water, 0, 100);
    const card = sheet.querySelector('#sfarm-card-' + i);
    if (card) card.classList.toggle('mature', mature);
    const prog = sheet.querySelector('#sfarm-prog-' + i);
    if (prog) prog.style.width = (ratio * 100).toFixed(1) + '%';
    const w = sheet.querySelector('#sfarm-water-' + i);
    if (w) w.style.width = water.toFixed(1) + '%';
    const st = sheet.querySelector('#sfarm-stage-' + i);
    if (st) st.textContent = sfarmStageLabel(stage);
    const cropEl = sheet.querySelector('#sfarm-crop-' + i);
    if (cropEl) {
      cropEl.className = 'sfarm-crop stage-' + stage;
      if (cropEl.dataset.stage !== String(stage)) {
        cropEl.dataset.stage = String(stage);
        cropEl.innerHTML = sfarmCropVisualHTML(p.crop.type, stage);
      }
    }
    const mult = sfarmBeeSpeed(g, 1, sfarmNow(g.timeMode));
    const remainSec = Math.max(0, Math.ceil((sfarmCropMs(p.crop.type) - p.crop.growth) / 1000 / mult));
    const hint = sheet.querySelector('#sfarm-hint-' + i);
    if (hint) {
      hint.textContent = mature ? '✨ 点击收割' : (water <= 0 ? '💧 缺水 · 点击浇水' : (water < 100 ? '🌿 ' + remainSec + 's · 💧' : '🌿 ' + remainSec + 's'));
    }
  }
  function sfarmUpdateHud(g) {
    if (!g || !sheet || !sheet.querySelector) return;
    const q = sel => sheet.querySelector(sel);
    const set = (sel, text) => { const el = q(sel); if (el) el.textContent = text; };
    set('#sfarm-coins', String(g.coins));
    for (let i = 0; i < SFARM_GRID; i++) sfarmUpdatePlotDom(g, i);
    const now = sfarmNow(g.timeMode);
    for (let i = 0; i < 6; i++) {
      const el = q('#sfarm-hive-' + i);
      if (el) el.className = 'sfarm-hive ' + sfarmHiveState(g, i, now);
      const time = q('#sfarm-hive-time-' + i);
      const b = g.beeBoxes[i];
      if (time) time.textContent = b && b.box && b.beeExpiresAt > now ? sfarmFmtCountdown(b.beeExpiresAt - now) : '';
    }
    const auto = q('[data-sfarm-act="autowater"]');
    if (auto) {
      const owned = !!g.upgrades.autoWater;
      auto.className = 'sfarm-tool ' + (!owned ? 'locked' : (g.batteryMs > 0 ? 'on' : 'off'));
      set('#sfarm-auto-status', !owned ? '商店购买 · 自动浇水' : (g.batteryMs > 0 ? ('自动浇水中 · 电池 ' + sfarmFmtCountdown(g.batteryMs)) : ('缺电池 · 点击安装（电池 ' + g.batteries + '）')));
    }
    const bag = q('[data-sfarm-act="beebag"]');
    if (bag) {
      const live = sfarmLiveBagBees(g, now);
      bag.className = 'sfarm-tool ' + (live.length ? 'on' : 'off');
      const nearest = live.length ? Math.min(...live.map(b => b.expiresAt)) : 0;
      set('#sfarm-beebag-status', live.length ? ('背包蜜蜂 ×' + live.length + ' · 最快 ' + sfarmFmtCountdown(nearest - now) + ' 飞走') : '背包无蜜蜂 · 点击商店');
    }
  }
  function sfarmRender(g) {
    if (!g || !sheet) return;
    let top = 0;
    try { const sc = sheet.querySelector('.sfarm-scroll'); if (sc) top = sc.scrollTop || 0; } catch (e) { /* ignore */ }
    sheet.innerHTML = sfarmPageHTML(g);
    try { const sc2 = sheet.querySelector('.sfarm-scroll'); if (sc2) sc2.scrollTop = top; } catch (e) { /* ignore */ }
    sfarmUpdateHud(g);
  }

  // ---- 商店 / 设置 / 兑换 / 集市弹层 ----
