  function sfarmShopBody(g) {
    const tabs = `<div class="sfarm-tabs">
      <button data-sfarm-panel="tab" data-tab="seeds" class="sfarm-tab ${sfarmShopTab === 'seeds' ? 'on' : ''}">🌱 种子</button>
