  }
  function sfarmSettingsBody(g) {
    const now = sfarmNow(g.timeMode);
    const activeBees = sfarmActiveBeeCount(g, now);
    const bagBees = sfarmLiveBagBees(g, now).length;
    const boxes = g.beeBoxes.filter(b => b.box).length;
    const unlocked = g.plots.filter(p => p.unlocked).length;
    return `
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">⏱ 时间来源</div><div class="sfarm-settings-line">默认内置时间：本机真实时间，离线会补生长。数据库时间：读取全局数据表日期/天，三份扩展共享农场存档与时钟偏移，剧情跨天会补生长。</div><div style="display:flex;gap:6px;margin-top:6px;"><button data-sfarm-panel="set-time" data-mode="local" class="sfarm-btn ${g.timeMode === 'local' ? 'primary' : 'soft'}" style="flex:1;">⏱ 内置时间</button><button data-sfarm-panel="set-time" data-mode="db" class="sfarm-btn ${g.timeMode === 'db' ? 'primary' : 'soft'}" style="flex:1;">🗄 数据库时间</button></div><div class="sfarm-settings-line" style="margin-top:4px;">当前：<b>${sfarmTimeLabel(g)}</b></div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🌿 农场状态</div><div class="sfarm-settings-line">金币：🪙 ${g.coins} · 已解锁地块：${unlocked}/9 · 已收割：${g.stats.harvested || 0} · 已售出：🪙 ${g.stats.sold || 0}<br>自动浇水器：${g.upgrades.autoWater ? (g.batteryMs > 0 ? '工作中 · 电池 ' + sfarmFmtCountdown(g.batteryMs) : '缺电池') : '未购买'} · 电池：${g.batteries}<br>蜂箱：${boxes}/6 · 工作蜜蜂：${activeBees} · 背包蜜蜂：${bagBees} · 蜂箱库存：${g.beehives}<br>风车：${g.upgrades.decor ? '已拥有 · 售价 +10%' : '未购买'} · 已播种：${g.stats.planted || 0} · 蜜蜂自动播种：${g.stats.autoPlanted || 0}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">⭐ 品质概率 / 售价倍率</div><div class="sfarm-legend">${sfarmQualityLegendHTML()}</div><div class="sfarm-settings-line">每次收割会随机品质；品质倍率按作物基础售价计算，风车再额外 +10%。</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🌱 作物表</div><table class="sfarm-crop-table"><tbody>${SFARM_CROP_ORDER.map(t => { const d = sfarmCropDef(t); return `<tr><td>${d.icon} ${d.name}</td><td>🪙${d.cost}</td><td>售🪙${d.sell}</td><td>${sfarmFmtGrow(d.growSec)}</td><td>水${sfarmFmtGrow(d.waterSec)}</td></tr>`; }).join('')}</tbody></table></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">📖 玩法说明</div><div class="sfarm-settings-line">1. 点击荒地翻土，选种子后点击已翻土地块播种，再点一次浇水。<br>2. 作物只在有水时生长，水耗尽会暂停；成熟后点击地块收割，随机获得品质。<br>3. 自动浇水器需要电池：商店买电池后点击自动浇水器安装；电池没电会停止并显示禁止图标。<br>4. 农田两侧各 3 格蜂箱：先买蜂箱放在空格，再买蜜蜂放入；背包蜜蜂 3 分钟会飞走，蜂箱蜜蜂工作 10 分钟。<br>5. 有蜜蜂的蜂箱可接收拖入的种子自动播种；每只工作蜜蜂 +5% 生长速度，最多 +30%。<br>6. 农场金币是小铺独立货币，可在 💱 兑换所与其他游戏资金 / 积分按比例兑换。<br>7. 三份扩展共用农场存档与数据库时钟；X 离开会自动保存。</div></div>`;
  }
  function sfarmExchangeBody(g) {
    const fundName = sfarmGlobalFundName();
    const fund = sfarmGlobalFundBalance();
    const pts = sfarmPointsBalance();
    const quick = (dir, amounts) => `<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:5px;">${amounts.map(a => `<button data-sfarm-panel="exchange" data-dir="${dir}" data-amt="${a[0]}" class="sfarm-btn soft">${a[1]}</button>`).join('')}</div>`;
    return `<div class="sfarm-settings-card"><div class="sfarm-settings-title">💰 当前余额</div><div class="sfarm-settings-line">农场金币：🪙 ${g.coins}<br>${fundName}：${sfarmFmtNum(fund)}<br>积分：💎 ${pts}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🪙 农场金币 → ${fundName}</div><div class="sfarm-settings-line">1 农场金币 = ${sfarmFmtNum(SFARM_FUND_PER_COIN)} ${fundName}${quick('farm-fund', [[10, '10'], [50, '50'], [100, '100'], [-1, '全部']])}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">${fundName} → 🪙 农场金币</div><div class="sfarm-settings-line">${sfarmFmtNum(SFARM_FUND_PER_COIN_BUY)} ${fundName} = 1 农场金币${quick('fund-farm', [[10000, '1万'], [50000, '5万'], [100000, '10万'], [-1, '全部']])}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🪙 农场金币 → 💎 积分</div><div class="sfarm-settings-line">${SFARM_POINTS_PER_COIN} 农场金币 = 1 积分${quick('farm-points', [[5000, '5000'], [10000, '1万'], [20000, '2万'], [-1, '全部']])}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">💎 积分 → 🪙 农场金币</div><div class="sfarm-settings-line">1 积分 = ${SFARM_COINS_PER_POINT} 农场金币${quick('points-farm', [[1, '1'], [5, '5'], [10, '10'], [-1, '全部']])}</div></div>
      <div class="sfarm-note">兑换立即生效；农场金币为小铺独立货币，不影响棋牌筹码 / 股市资金 / 小金库的原有规则。</div>`;
  }
  function sfarmMarketBody(g) {
    const total = sfarmBagValue(g);
    const rows = SFARM_CROP_ORDER.filter(t => sfarmCropValue(g, t) > 0).map(t => {
      const d = sfarmCropDef(t);
      const inv = g.inventory[t];
      const badges = SFARM_QUALITY_KEYS.map(k => { const n = inv[k] || 0; return n > 0 ? (sfarmQualityBadgeHTML(k, n) + '<span style="font-size:8.5px;color:#8b7862;margin-right:4px;">🪙' + sfarmSellValue(g, t, n, k) + '</span>') : ''; }).join('');
      const count = SFARM_QUALITY_KEYS.reduce((s, k) => s + (inv[k] || 0), 0);
      const val = sfarmCropValue(g, t);
      return `<div class="sfarm-market-row"><div class="sfarm-shop-icon">${d.icon}</div><div class="sfarm-market-main"><div class="sfarm-market-name">${d.name} ×${count}</div><div class="sfarm-legend">${badges}</div><div class="sfarm-market-val">可卖 🪙 ${val}</div></div><button data-sfarm-panel="sell" data-crop="${t}" class="sfarm-btn gold">卖</button></div>`;
    }).join('');
    return `<div class="sfarm-settings-card"><div style="display:flex;justify-content:space-between;align-items:center;gap:7px;"><div class="sfarm-settings-title">🛒 背包作物</div><button data-sfarm-panel="sell-all" class="sfarm-btn primary" ${total > 0 ? '' : 'disabled'}>一键卖出 🪙 ${total}</button></div><div class="sfarm-settings-line">按品质计价：铜星 ×1.0 · 银星 ×1.5 · 金星 ×2.5 · 彩心 ×5.0${g.upgrades.decor ? '；风车 +10%' : ''}</div><div class="sfarm-legend">${sfarmQualityLegendHTML()}</div>${rows || '<div class="sfarm-note" style="padding:6px 0;">背包空空，去田里收割吧。</div>'}</div>`;
  }
  function sfarmOverlayContent(g, type) {
    const titles = { shop: '🏪 种子商店', settings: '⚙️ 农场设置', exchange: '💱 资金兑换', market: '🛒 集市' };
    let body = '';
    if (type === 'shop') body = sfarmShopBody(g);
    else if (type === 'settings') body = sfarmSettingsBody(g);
    else if (type === 'exchange') body = sfarmExchangeBody(g);
    else body = sfarmMarketBody(g);
    return `<div class="sfarm-panel"><div class="sfarm-panel-head"><span class="sfarm-panel-title">${titles[type] || '星田小铺'} <span style="font-size:11px;opacity:.75;">🌼</span></span><span class="sfarm-coin-pill">🪙 <b>${g.coins}</b></span><button data-sfarm-panel="close" class="sfarm-icon-btn" style="width:28px;height:28px;font-size:16px;">✕</button></div><div class="sfarm-panel-scroll">${body}</div></div>`;
  }
  function sfarmOpenOverlay(type, tab) {
    if (!sheet || !sfarmGame) return;
    const old = sheet.querySelector('.sfarm-overlay');
    if (old) old.remove();
    sfarmOverlayType = type;
    if (type === 'shop' && tab) sfarmShopTab = tab;
    const ov = document.createElement('div');
    ov.className = 'sfarm-overlay';
    ov.innerHTML = sfarmOverlayContent(sfarmGame, type);
    ov.addEventListener('click', sfarmOverlayClick);
    sheet.appendChild(ov);
  }
  function sfarmRefreshOverlay() {
    if (!sheet || !sheet.querySelector || !sfarmGame || !sfarmOverlayType) return;
    const ov = sheet.querySelector('.sfarm-overlay');
    if (!ov) return;
    let top = 0;
    try { const sc = ov.querySelector('.sfarm-panel-scroll'); if (sc) top = sc.scrollTop || 0; } catch (e) { /* ignore */ }
    ov.innerHTML = sfarmOverlayContent(sfarmGame, sfarmOverlayType);
    try { const sc2 = ov.querySelector('.sfarm-panel-scroll'); if (sc2) sc2.scrollTop = top; } catch (e) { /* ignore */ }
  }
  function sfarmCloseOverlay() {
    if (!sheet || !sheet.querySelector) return;
    const ov = sheet.querySelector('.sfarm-overlay');
    if (ov) ov.remove();
    sfarmOverlayType = null;
    if (sfarmGame) sfarmRender(sfarmGame);
  }
  function sfarmOverlayClick(e) {
    if (!e || !e.target) return;
    const g = sfarmGame;
    if (!g) return;
    const ov = sheet && sheet.querySelector ? sheet.querySelector('.sfarm-overlay') : null;
    if (e.target === ov) { if (e.preventDefault) e.preventDefault(); sfarmCloseOverlay(); return; }
    const el = e.target.closest ? e.target.closest('[data-sfarm-panel]') : null;
    if (!el) return;
    if (e.preventDefault) e.preventDefault();
    const act = el.dataset.sfarmPanel;
    if (act === 'close') { sfarmCloseOverlay(); return; }
    if (act === 'tab') { sfarmShopTab = el.dataset.tab || 'seeds'; sfarmRefreshOverlay(); return; }
    if (act === 'buy-seed') { sfarmBuySeed(g, el.dataset.seed); sfarmRefreshOverlay(); return; }
    if (act === 'buy-tool') { sfarmBuyTool(g, el.dataset.tool); sfarmRefreshOverlay(); return; }
    if (act === 'unlock') { sfarmTryUnlock(g, parseInt(el.dataset.idx, 10), true); sfarmRefreshOverlay(); return; }
    if (act === 'set-time') { sfarmSetTimeMode(g, el.dataset.mode); sfarmRefreshOverlay(); return; }
    if (act === 'exchange') { sfarmExchange(g, el.dataset.dir, parseInt(el.dataset.amt, 10)); sfarmRefreshOverlay(); return; }
    if (act === 'sell-all') { sfarmSellAll(g); sfarmRefreshOverlay(); return; }
    if (act === 'sell') { sfarmSellCrop(g, el.dataset.crop); sfarmRefreshOverlay(); return; }
  }

  // ---- 主界面点击 / 拖拽 ----
  function sfarmClick(e) {
    if (!e || !e.target) return;
    const el = e.target.closest ? e.target.closest('[data-sfarm-act]') : null;
    if (!el) return;
    const g = sfarmGame;
    if (!g) return;
    const act = el.dataset.sfarmAct;
    if (e.preventDefault) e.preventDefault();
    if (act === 'back') { sfarmExitToLobby(); return; }
    if (act === 'close') { sfarmQuitToCenter(); return; }
    if (act === 'settings') { sfarmOpenOverlay('settings'); return; }
    if (act === 'exchange') { sfarmOpenOverlay('exchange'); return; }
    if (act === 'shop') { sfarmOpenOverlay('shop', 'seeds'); return; }
    if (act === 'market') { sfarmOpenOverlay('market'); return; }
    if (act === 'seed') {
      const type = el.dataset.seed;
      if (!sfarmCropDef(type)) return;
      g.selectedSeed = type;
      sfarmUpdateHud(g);
      sfarmRender(g);
      if ((g.seeds[type] || 0) <= 0) showToast('🌰 ' + sfarmCropDef(type).name + '种子不足，点击商店购买');
      return;
    }
    if (act === 'plot') { sfarmPlotAction(g, parseInt(el.dataset.idx, 10)); return; }
    if (act === 'hive') {
      const idx = parseInt(el.dataset.idx, 10);
      if (!Number.isFinite(idx)) return;
      sfarmHiveAction(g, idx);
      return;
    }
    if (act === 'autowater') { sfarmInstallBattery(g); return; }
    if (act === 'beebag' || act === 'windmill') { sfarmOpenOverlay('shop', 'tools'); return; }
  }
  function sfarmDragStart(e) {
    const el = e.target && e.target.closest ? e.target.closest('[data-sfarm-drag-seed]') : null;
    if (!el) return;
    sfarmDragSeed = el.dataset.sfarmDragSeed || el.dataset.seed || null;
    if (sfarmDragSeed && e.dataTransfer) {
      try { e.dataTransfer.setData('text/plain', sfarmDragSeed); e.dataTransfer.effectAllowed = 'copy'; } catch (err) { /* ignore */ }
    }
  }
  function sfarmDragOver(e) {
    const el = e.target && e.target.closest ? e.target.closest('[data-sfarm-drop]') : null;
    if (!el) return;
    if (e.preventDefault) e.preventDefault();
    if (e.dataTransfer) { try { e.dataTransfer.dropEffect = 'copy'; } catch (err) { /* ignore */ } }
  }
  function sfarmDrop(e) {
    const el = e.target && e.target.closest ? e.target.closest('[data-sfarm-drop]') : null;
    if (!el) return;
    if (e.preventDefault) e.preventDefault();
    const idx = parseInt(el.dataset.idx, 10);
    let seed = '';
    try { seed = e.dataTransfer ? e.dataTransfer.getData('text/plain') : ''; } catch (err) { seed = ''; }
    seed = seed || sfarmDragSeed || '';
    sfarmDragSeed = null;
    if (sfarmGame && sfarmCropDef(seed)) sfarmBeeSow(sfarmGame, idx, seed);
  }

  // ---- 生命周期 ----
  function sfarmOpenGame() {
    sfarmStop();
    if (!sheet) { renderEarnLobby(); return; }
    let g = sfarmLoad();
    if (!g) g = sfarmInitialState();
    const off = sfarmApplyOffline(g);
    sfarmEnsurePlayable(g);
    const now = sfarmNow(g.timeMode);
    g.lastTick = now;
    sfarmGame = g;
    sfarmSave(g);
    sfarmRender(g);
    sfarmClickHandler = (e) => sfarmClick(e);
    sfarmDragHandlers = [
      [(el, ev, fn) => el.addEventListener(ev, fn), 'dragstart', sfarmDragStart],
      [(el, ev, fn) => el.addEventListener(ev, fn), 'dragover', sfarmDragOver],
      [(el, ev, fn) => el.addEventListener(ev, fn), 'drop', sfarmDrop]
    ];
    try {
      sheet.addEventListener('click', sfarmClickHandler);
      sheet.addEventListener('dragstart', sfarmDragStart);
      sheet.addEventListener('dragover', sfarmDragOver);
      sheet.addEventListener('drop', sfarmDrop);
    } catch (e) { /* ignore */ }
    sfarmTimer = setInterval(sfarmTick, 1000);
    sfarmUpdateHud(g);
    if (off.battery) showToast('🔋 自动浇水器电池已耗尽，需要重新购买并安装');
    if (off.bag > 0 || off.box > 0) showToast('🐝 离线期间有蜜蜂飞走了，记得补充蜜蜂');
  }
  function sfarmTick() {
    const g = sfarmGame;
    if (!g) return;
    if (!sheet || !sheet.querySelector || !sheet.querySelector('.sfarm-page')) { sfarmCommit(g); sfarmStop(); return; }
    const now = sfarmNow(g.timeMode);
    const last = Number(g.lastTick) || now;
    const elapsed = now - last;
    const batteryBefore = g.batteryMs;
    if (elapsed > 0) sfarmGrow(g, elapsed, last);
    g.lastTick = now;
    const exp = sfarmExpire(g, now, true);
    if (g.upgrades.autoWater && batteryBefore > 0 && g.batteryMs <= 0) showToast('🔋 自动浇水器电池没电了，自动浇水已停止');
    g.saveTick = (g.saveTick || 0) + 1;
