    if (v >= 1e8) s = trim(Math.round(v / 1e6) / 100) + '亿';
    else if (v >= 1e4) {
      const w = Math.round(v / 100) / 100;
      s = w >= 10000 ? (trim(Math.round(v / 1e6) / 100) + '亿') : (w + '万');
