  function buildTableText(tables, startIdx, endIdx) {
    var parts = [];
    for (var i = startIdx; i <= endIdx && i < tables.length; i++) {
      var sh = tables[i];
      var lines = [];
      var content = sh.content;
      var maxRows = Math.min(content.length, 61);
      for (var r = 0; r < maxRows; r++) {
        var row = content[r];
        if (!Array.isArray(row)) continue;
        var cells = [];
        for (var cix = 0; cix < row.length && cix < 8; cix++) {
          var v = row[cix];
          var s = (v == null ? '' : String(v)).trim();
          if (s.length > 60) s = s.slice(0, 60) + '…';
          cells.push(s);
        }
        while (cells.length && cells[cells.length - 1] === '') cells.pop();
        if (!cells.length) continue;
        lines.push(cells.join(' | '));
        if (lines.length >= 60) break;
      }
      if (!lines.length) continue;
      var block = '【表 ' + (i + 1) + '：' + sh.name + '】\n' + lines.join('\n');
      parts.push(block);
      if (parts.join('\n\n').length > 15000) break;
    }
    var text = parts.join('\n\n');
    if (text.length > 16000) text = text.slice(0, 16000);
    return text;
  }
  function buildSheetBlock(sh, opts) {
    opts = opts || {};
    var content = (sh && sh.content) || [];
    var lines = [];
    var header = Array.isArray(content[0]) ? ('（表头：' + content[0].slice(0, 8).join(' | ') + '）') : '';
    var lo = opts.lo != null ? opts.lo : 1;
    var hi = opts.hi != null ? opts.hi : content.length - 1;
    if (hi >= content.length) hi = content.length - 1;
    var maxRows = opts.maxRows || 60;
    for (var r = lo; r <= hi; r++) {
      var row = content[r];
      if (!Array.isArray(row)) continue;
      var cells = [];
      for (var c = 0; c < row.length && c < 8; c++) {
        var s = (row[c] == null ? '' : String(row[c])).trim();
        if (s.length > 80) s = s.slice(0, 80) + '…';
        cells.push(s);
      }
      while (cells.length && cells[cells.length - 1] === '') cells.pop();
      if (!cells.length) continue;
      lines.push((opts.numbered ? ('第' + r + '条 | ') : '') + cells.join(' | '));
      if (lines.length >= maxRows) break;
    }
    if (!lines.length) return '';
    return '【' + sh.name + '】\n' + (header ? header + '\n' : '') + lines.join('\n');
  }
  // 数据库生成固定读取：恋爱对象表、重要角色表、人物关系表、纪要表（纪要表可选条数范围）
  function buildKeyTablesText(chronicleRange) {
    var tables = listTables();
    if (!tables.length) return { error: '未读取到数据库表格（请确认主项目数据库已加载）' };
    var byName = {};
    for (var i = 0; i < tables.length; i++) byName[tables[i].name] = tables[i];
    var cf = 0, ct = 0;
    if (chronicleRange) { cf = Math.round(Number(chronicleRange[0]) || 0); ct = Math.round(Number(chronicleRange[1]) || 0); }
    var useChronicle = cf >= 1 || ct >= 1;
    if (useChronicle) { if (cf < 1) cf = 1; if (ct < cf) ct = cf; }
    if (useChronicle && !byName['纪要表']) return { error: '数据库中未找到「纪要表」' };
    var names = ['恋爱对象表', '重要角色表', '人物关系表', '纪要表'];
    var blocks = [];
    for (var n = 0; n < names.length; n++) {
      var sh = byName[names[n]];
      if (!sh) continue;
      if (names[n] === '纪要表') {
        var blk;
        if (useChronicle) {
          var maxRow = sh.content.length - 1;
          if (ct > maxRow) ct = maxRow;
          blk = buildSheetBlock(sh, { lo: cf, hi: ct, numbered: true, maxRows: 60 });
          if (!blk) return { error: '纪要表所选条数区间没有内容' };
        } else {
          blk = buildSheetBlock(sh, { numbered: true, maxRows: 40 });
        }
        if (blk) blocks.push(blk);
      } else {
        var b = buildSheetBlock(sh, { maxRows: 60 });
        if (b) blocks.push(b);
      }
    }
    if (!blocks.length) return { error: '关键表中没有可读取的内容' };
    var text = blocks.join('\n\n');
    if (text.length > 16000) text = text.slice(0, 16000);
    return {
      text: text,
      title: '数据库关键表（恋爱对象表 / 重要角色表 / 人物关系表' + (useChronicle ? ' / 纪要表第 ' + cf + ' 条至第 ' + ct + ' 条' : ' / 纪要表') + '）',
      label: useChronicle ? ('数据库（纪要表第' + cf + '-' + ct + '条）') : '数据库关键表'
    };
  }
