  // ---------- 交易 ----------
  function doBuy(companyId, qty) {
    var co = findCompany(companyId);
    if (!co) return { ok: false, msg: '找不到该公司' };
    if (co.bankrupt) return { ok: false, msg: '该公司已破产退市，无法买入' };
    qty = Math.round(clampNum(qty, 1, 999999, 0));
    if (qty <= 0) return { ok: false, msg: '请输入买入数量' };
    var cost = Math.round(co.price * qty);
    if (cost <= 0) cost = 1;
    var t = getTreasury();
    if (!t.ok) return { ok: false, msg: t.reason || '未检测到小金库' };
    if (t.balance < cost) return { ok: false, msg: '小金库余额不足：需要 ' + fmtNum(cost) + '，当前 ' + fmtNum(t.balance) };
    if (!treasuryAdjust(-cost, '买入 ' + co.name + '×' + qty + ' @' + fmtNum(co.price), 'stock-buy')) {
      return { ok: false, msg: '小金库扣款失败' };
    }
    var totalCost = co.avgCost * co.shares + cost;
    co.shares += qty;
    co.avgCost = co.shares > 0 ? round2(totalCost / co.shares) : 0;
    co.myInvested = Math.round((Number(co.myInvested) || 0) + cost);
    co.updatedAt = nowTs();
    state.tradeNet = Math.round((Number(state.tradeNet) || 0) - cost);
    var hs = updateHolderStatus(co, true);
    var bs = updateBossStatus(co, true);
    saveState();
    return { ok: true, msg: '买入成功：' + co.name + ' ×' + qty + '，花费 ' + fmtNum(cost) + (hs === 'gain' ? '；已达到总股本 ' + HOLDER_KEEP_PCT + '%，恢复股东身份' : '') + (bs === 'boss' ? '；持股占比超过 50%，你成为公司老板' : '') };
  }
  function doSell(companyId, qty) {
    var co = findCompany(companyId);
    if (!co) return { ok: false, msg: '找不到该公司' };
    if (co.bankrupt) return { ok: false, msg: '该公司已破产退市，持股已清零' };
    if (co.shares <= 0) return { ok: false, msg: '你没有该公司的股票' };
    qty = Math.round(clampNum(qty, 1, co.shares, 0));
    if (qty <= 0) return { ok: false, msg: '请输入卖出数量' };
    var revenue = Math.round(co.price * qty);
    var t = getTreasury();
    if (!t.ok) return { ok: false, msg: t.reason || '未检测到小金库' };
    if (!treasuryAdjust(revenue, '卖出 ' + co.name + '×' + qty + ' @' + fmtNum(co.price), 'stock-sell')) {
      return { ok: false, msg: '小金库入账失败' };
    }
    var profit = Math.round((co.price - co.avgCost) * qty);
    co.shares -= qty;
    if (co.shares <= 0) { co.shares = 0; co.avgCost = 0; }
    co.myInvested = Math.max(0, Math.round((Number(co.myInvested) || 0) - revenue));
    co.updatedAt = nowTs();
    state.tradeNet = Math.round((Number(state.tradeNet) || 0) + revenue);
    var hs = updateHolderStatus(co, true);
    updateBossStatus(co, true);
    saveState();
    return { ok: true, msg: '卖出成功：' + co.name + ' ×' + qty + '，入账 ' + fmtNum(revenue) + '（' + (profit >= 0 ? '盈利 +' : '亏损 ') + fmtNum(profit) + '）' + (hs === 'lose' ? '；总持股低于总股本 ' + HOLDER_KEEP_PCT + '%，已失去股东身份（权益保留）' : '') };
  }
  function doInject(companyId, qty) {
    var co = findCompany(companyId);
    if (!co) return { ok: false, msg: '找不到该公司' };
    if (co.bankrupt) return { ok: false, msg: '该公司已破产退市' };
    if (!co.isHolder) return { ok: false, msg: '你不是该公司股东，无法投入（需持股达到总股本 ' + HOLDER_KEEP_PCT + '% 恢复股东身份）' };
    if (!(co.holderShares > 0)) return { ok: false, msg: '没有可投入的股东权益' };
    qty = Math.round(clampNum(qty, 1, co.holderShares, 0));
    if (qty <= 0) return { ok: false, msg: '请输入投入数量' };
    // 投入 = 用股东权益为该公司注资：消耗权益 → 股价按注资额拉升（单次最多 +20%），不产生普通持股
    var priceBefore = co.price;
    var value = Math.round(qty * priceBefore);
    var cap = Math.max(1, Math.round(priceBefore * (Number(co.totalShares) || 0)));
    var pct = value / cap;
    if (pct > 0.2) pct = 0.2;
    if (pct < 0.005) pct = 0.005;
    var newPrice = round2(priceBefore * (1 + pct));
    co.holderShares -= qty;
    co.myInvested = Math.round((Number(co.myInvested) || 0) + value);
    var res = applyPriceUpdate(co, newPrice, '股东注资拉升');
    if (!res) {
      co.history.push(newPrice);
      while (co.history.length > MAX_HISTORY) co.history.shift();
      co.price = newPrice;
      co.updatedAt = nowTs();
    }
    var hs = updateHolderStatus(co, true);
    updateBossStatus(co, true);
    saveState();
    var realPct = priceBefore > 0 ? (((co.price - priceBefore) / priceBefore) * 100).toFixed(2) : '0.00';
    return { ok: true, msg: '投入成功：' + co.name + ' 股价 ' + fmtNum(priceBefore) + ' → ' + fmtNum(co.price) + '（+' + realPct + '%），消耗股东权益 ' + fmtShares(qty) + (hs === 'lose' ? '；总持股低于 ' + HOLDER_KEEP_PCT + '%，失去股东身份（权益保留）' : '') };
  }
  // 主角为老板（或自家公司）时可分配股东股权
  function doAllotHolders(companyId, list) {
    var co = findCompany(companyId);
    if (!co) return { ok: false, msg: '找不到该公司' };
    if (co.bankrupt) return { ok: false, msg: '该公司已破产退市' };
    if (!(co.userBoss || co.mine)) return { ok: false, msg: '只有你是老板时才能分配股东股权' };
    if (!Array.isArray(list)) return { ok: false, msg: '参数错误' };
    var holders = co.holders || (co.holders = []);
