  // ---------- 图形 ----------
  function hexA(hex, a) {
    var h = hex.replace('#', '');
    if (h.length === 3) h = h.charAt(0) + h.charAt(0) + h.charAt(1) + h.charAt(1) + h.charAt(2) + h.charAt(2);
    var r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
  }
  function sparkSvg(hist, w, h, up) {
    if (!hist || hist.length < 2) return '<svg class="ubp-gstk-spark" viewBox="0 0 ' + w + ' ' + h + '"></svg>';
    var min = Infinity, max = -Infinity;
    for (var i = 0; i < hist.length; i++) { if (hist[i] < min) min = hist[i]; if (hist[i] > max) max = hist[i]; }
    if (max - min < 1e-9) max = min + 1;
    var n = hist.length;
    var pts = [];
    for (var j = 0; j < n; j++) {
      var x = (j / (n - 1)) * (w - 2) + 1;
      var y = h - 3 - ((hist[j] - min) / (max - min)) * (h - 8);
      pts.push([x, y]);
    }
    var d = '';
    for (var k = 0; k < pts.length; k++) d += (k ? 'L' : 'M') + pts[k][0].toFixed(1) + ' ' + pts[k][1].toFixed(1) + ' ';
    var color = up ? SKIN.up : SKIN.down;
    var cid = 'stkG' + Math.random().toString(36).slice(2, 9);
    return '<svg class="ubp-gstk-spark" viewBox="0 0 ' + w + ' ' + h + '">'
      + '<defs><linearGradient id="' + cid + '" x1="0" y1="0" x2="0" y2="1">'
      + '<stop offset="0%" stop-color="' + hexA(color, 0.34) + '"/><stop offset="100%" stop-color="' + hexA(color, 0) + '"/>'
      + '</linearGradient></defs>'
      + '<path d="' + d + 'L' + (w - 1) + ' ' + h + ' L1 ' + h + ' Z" fill="url(#' + cid + ')"/>'
      + '<path d="' + d + '" fill="none" stroke="' + color + '" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>'
      + '</svg>';
  }
  function bigChartSvg(hist, w, h) {
    var out = '<svg class="ubp-gstk-chart" viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none">';
    if (!hist || hist.length < 2) return out + '</svg>';
    var min = Infinity, max = -Infinity;
    for (var i = 0; i < hist.length; i++) { if (hist[i] < min) min = hist[i]; if (hist[i] > max) max = hist[i]; }
    if (max - min < 1e-9) max = min + 1;
    var padT = 16, padB = 14, usableH = h - padT - padB;
    var n = hist.length;
    var px = function (j) { return (j / (n - 1)) * (w - 8) + 4; };
    var py = function (v) { return padT + (1 - (v - min) / (max - min)) * usableH; };
    // 网格
    for (var g = 0; g <= 3; g++) {
      var gy = (padT + (usableH * g / 3)).toFixed(1);
      out += '<line x1="4" y1="' + gy + '" x2="' + (w - 4) + '" y2="' + gy + '" stroke="rgba(255,255,255,.07)" stroke-width="1" stroke-dasharray="2 4"/>';
    }
    var d = '';
    for (var k = 0; k < n; k++) d += (k ? 'L' : 'M') + px(k).toFixed(1) + ' ' + py(hist[k]).toFixed(1) + ' ';
    var up = hist[n - 1] >= hist[0];
    var color = up ? SKIN.up : SKIN.down;
    out += '<defs><linearGradient id="stkBig' + w + '" x1="0" y1="0" x2="0" y2="1">'
      + '<stop offset="0%" stop-color="' + hexA(color, 0.30) + '"/><stop offset="100%" stop-color="' + hexA(color, 0) + '"/>'
      + '</linearGradient></defs>';
    out += '<path d="' + d + 'L' + (w - 4) + ' ' + (h - 2) + ' L4 ' + (h - 2) + ' Z" fill="url(#stkBig' + w + ')"/>';
    out += '<path d="' + d + '" fill="none" stroke="' + color + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>';
    // 局部峰值点（峰值链）
    for (var p = 1; p < n - 1; p++) {
      if (hist[p] > hist[p - 1] && hist[p] >= hist[p + 1]) {
        out += '<circle cx="' + px(p).toFixed(1) + '" cy="' + py(hist[p]).toFixed(1) + '" r="2.4" fill="' + hexA(SKIN.up, 0.85) + '"/>';
      } else if (hist[p] < hist[p - 1] && hist[p] <= hist[p + 1]) {
        out += '<circle cx="' + px(p).toFixed(1) + '" cy="' + py(hist[p]).toFixed(1) + '" r="2.4" fill="' + hexA(SKIN.down, 0.85) + '"/>';
      }
    }
    // 端点
    out += '<circle cx="' + px(n - 1).toFixed(1) + '" cy="' + py(hist[n - 1]).toFixed(1) + '" r="3.4" fill="#fff" stroke="' + color + '" stroke-width="2"/>';
    // 最高/最低标注
    out += '<text x="6" y="' + (py(max) - 4).toFixed(1) + '" font-size="9" fill="' + hexA(SKIN.up, 0.9) + '">峰 ' + fmtNum(max) + '</text>';
    out += '<text x="6" y="' + Math.min(h - 4, py(min) + 11).toFixed(1) + '" font-size="9" fill="' + hexA(SKIN.down, 0.9) + '">谷 ' + fmtNum(min) + '</text>';
    return out + '</svg>';
  }

