  function render() {
    if (!overlay || !appEl) return;
    refreshSkin();
    ensureCss(overlay.getRootNode());
    var html;
    if (view.page === 'list') html = listHtml();
    else if (view.page === 'settings') html = settingsHtml();
    else {
      var c = API.findCompany(view.code);
      if (!c) { view.page = 'list'; html = listHtml(); }
      else html = detailBodyHtml(c);
    }
    var scrollTop = 0;
    if (view.page === lastRenderedPage) scrollTop = overlay.scrollTop || 0;
    lastRenderedPage = view.page;
    appEl.innerHTML = headerHtml() + (view.page === 'list' ? statsHtml() : '') + html;
    try { overlay.scrollTop = scrollTop; } catch (e) {}
  }
  function showToast(msg, isErr) {
    var host = uiHost();
    if (!host) return;
    try {
      var old = host.querySelector('.ubp-gstk-toast');
      if (old) old.remove();
      var el = DOC.createElement('div');
      el.className = 'ubp-gstk-toast' + (isErr ? ' err' : '');
      el.textContent = msg;
      host.appendChild(el);
      if (toastTimer) clearTimeout(toastTimer);
      toastTimer = setTimeout(function () { try { el.remove(); } catch (e) {} }, isErr ? 4200 : 3000);
    } catch (e) {}
  }
  var genBarEl = null;
  // 后台生成提示：宿主页面顶部悬浮胶囊（不遮挡、不阻断操作；股市窗口关闭时同样可见）
  function genBar(on, text) {
    try {
      if (!on) {
        if (genBarEl) { try { genBarEl.remove(); } catch (e) {} genBarEl = null; }
        return;
      }
      var host = uiHost();
      if (!host) return;
      if (!genBarEl || !genBarEl.parentNode || genBarEl.parentNode !== host) {
        if (genBarEl) { try { genBarEl.remove(); } catch (e) {} }
        genBarEl = DOC.createElement('div');
        genBarEl.className = 'ubp-gstk-genbar fixed';
        genBarEl.innerHTML = '<span class="sp"></span><p></p>';
        host.appendChild(genBarEl);
      }
      var p = genBarEl.querySelector('p');
      if (p) p.textContent = text || '正在生成…';
    } catch (e) {}
  }
  // 短暂顶部提示（用于股市窗口关闭时的完成 / 失败提醒）
  function genBarFlash(text) {
    try { showToast(text); } catch (e) {}
  }
  function closeModal() {
    if (modalEl) { try { modalEl.remove(); } catch (e) {} modalEl = null; }
  }
  function openModal(html, center) {
    closeModal();
    var host = uiHost();
    if (!host) return null;
    modalEl = DOC.createElement('div');
    modalEl.className = 'ubp-gstk-modal' + (center ? ' center' : '');
    modalEl.innerHTML = html;
    host.appendChild(modalEl);
    modalEl.addEventListener('click', handleActClick);
    modalEl.addEventListener('pointerdown', lpDown);
    modalEl.addEventListener('pointerup', lpUp);
    modalEl.addEventListener('pointercancel', lpUp);
    modalEl.addEventListener('pointerleave', lpUp);
    modalEl.addEventListener('click', function (e) { if (e.target === modalEl) closeModal(); });
    return modalEl;
  }
