  // ---------- 执行流程 ----------
  function readNumInput(sel, dft) {
    var el = modalEl ? modalEl.querySelector(sel) : null;
    var n = el ? Number(el.value) : NaN;
    if (!isFinite(n)) return dft;
    return n;
  }
  function readNoteInput() {
    var el = modalEl ? modalEl.querySelector('[data-stk-note]') : null;
    return el ? String(el.value || '').trim().slice(0, 300) : '';
  }
  function doSaveSettings(silent) {
    var s = API.state();
    var q = function (k) { var el = appEl ? appEl.querySelector('[data-stk-in="' + k + '"]') : null; return el ? el.value : undefined; };
    var v;
    v = q('apiUrl'); if (v !== undefined) s.apiUrl = String(v).trim();
    v = q('apiKey'); if (v !== undefined) s.apiKey = String(v).trim();
    v = q('model'); if (v !== undefined) s.model = String(v).trim();
    v = q('jailbreak'); if (v !== undefined) s.jailbreak = String(v).trim().slice(0, 600);
    v = q('everyMinutes'); if (v !== undefined && isFinite(Number(v))) s.everyMinutes = Math.round(Math.min(1440, Math.max(1, Number(v))));
    v = q('everyFloors'); if (v !== undefined && isFinite(Number(v))) s.everyFloors = Math.round(Math.min(200, Math.max(1, Number(v))));
    v = q('contextFloors'); if (v !== undefined && isFinite(Number(v))) s.contextFloors = Math.round(Math.min(200, Math.max(0, Number(v))));
    API.saveState();
    if (!silent) showToast('✅ 设置已保存');
  }
  function runUpdateFlow(label, note) {
    if (API.isBusy()) { showToast('正在处理中，请稍候'); return; }
    genBar(true, note ? '正在按你的要求生成股市变化…' : '正在生成股市变化…');
    API.setBusy(true);
    API.runUpdatePrices(label || '手动', note || '').then(function (r) {
      API.setBusy(false);
      genBar(false);
      render();
      if (!r.applied && r.rawCount) {
        showToast('⚠ AI 返回了 ' + r.rawCount + ' 条行情，但未匹配到任何公司（请检查更新内容或重试）', true);
        return;
      }
      var msg = '✅ 更新完成：' + r.applied + ' 家变动（涨 ' + r.ups + ' / 跌 ' + r.downs + '），可点「↩ 撤回」撤销本场';
      if (r.bankrupt && r.bankrupt.length) msg += '；' + r.bankrupt.join('、') + ' 连续下跌 ' + API.BANKRUPT_STREAK + ' 次破产退市';
      showToast(msg);
    }, function (err) {
      API.setBusy(false);
      genBar(false);
      showToast('❌ ' + (err && err.message ? err.message : err), true);
    });
  }
  function runTextGen(companyId) {
