      else showToast('✅ 生成完成：新增 ' + r.added + ' 家' + (r.updated ? '，重估 ' + r.updated + ' 家' : '') + (r.coFound ? '，血缘共同开设 ' + r.coFound + ' 家' : '') + '公司');
