  function loadModels() {
    var m = appEl;
    if (!m) return;
    var urlEl = m.querySelector('[data-stk-in="apiUrl"]');
    var keyEl = m.querySelector('[data-stk-in="apiKey"]');
    var statusEl = m.querySelector('[data-stk-modelstatus]');
    var listEl = m.querySelector('[data-stk-modellist]');
    if (!statusEl || !listEl) return;
    var apiUrl = urlEl ? urlEl.value.trim() : '';
    var apiKey = keyEl ? keyEl.value.trim() : '';
    if (!apiUrl) { statusEl.textContent = '⚠️ 请先填写 API 地址'; return; }
    statusEl.textContent = '⏳ 加载模型列表中…';
    listEl.style.display = 'none';
    listEl.innerHTML = '';
    var endpoints = [apiUrl.replace(/\/+$/, '') + '/v1/models', apiUrl.replace(/\/+$/, '') + '/models'];
    var models = [];
    var finish = function () {
      if (!models.length) { statusEl.textContent = '❌ 未能获取模型列表，请检查 API 地址和密钥'; return; }
      statusEl.textContent = '✅ 找到 ' + models.length + ' 个模型，点击选择';
      listEl.style.display = 'block';
      listEl.innerHTML = models.map(function (mm) {
        return '<div class="mi" data-stk-model="' + escAttr(mm) + '">' + esc(mm) + '</div>';
      }).join('');
    };
    var tryNext = function (i) {
      if (i >= endpoints.length) { finish(); return; }
      fetch(endpoints[i], { headers: apiKey ? { 'Authorization': 'Bearer ' + apiKey } : {} })
        .then(function (resp) { if (!resp.ok) throw new Error('http'); return resp.json(); })
        .then(function (data) {
          if (data && data.data && Array.isArray(data.data)) models = data.data.map(function (it) { return it.id; }).filter(function (id) { return typeof id === 'string'; });
          else if (data && Array.isArray(data.models)) models = data.models.map(function (it) { return it.id; }).filter(function (id) { return typeof id === 'string'; });
          if (models.length) finish();
          else tryNext(i + 1);
        })
        .catch(function () { tryNext(i + 1); });
    };
    tryNext(0);
  }

  // ---------- 打开 / 关闭（渲染进游戏大厅本体界面） ----------
  function detachStockUI() {
    closeModal();
    lpUp();
    if (overlay) { try { overlay.remove(); } catch (e) {} }
    overlay = null;
    appEl = null;
  }
  function openStockApp() {
    var D = DOC;
    if (!D || !D.body) return;
    if (typeof sheet === 'undefined' || !sheet) {
      try { if (typeof openGameApp === 'function') openGameApp(); } catch (e) {}
    }
    if (typeof sheet === 'undefined' || !sheet) return;
    detachStockUI();
    sheet.innerHTML = '';
    try { sheet.scrollTop = 0; } catch (e) {}
    var ov = DOC.createElement('div');
    ov.className = 'ubp-gstk-overlay';
    ov.style.cssText = 'flex:1;min-height:0;border-radius:12px;overflow-y:auto;overflow-x:hidden;box-sizing:border-box;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column;background:var(--ubp-bg,#101014);';
    var app = DOC.createElement('div');
    app.className = 'ubp-gstk-root';
    ov.appendChild(app);
    sheet.appendChild(ov);
    overlay = ov;
    appEl = app;
    view.page = 'list';
    view.tab = 'all';
    view.code = '';
    lastRenderedPage = '';
    ensureCss(D);
    ov.addEventListener('click', handleActClick);
    ov.addEventListener('pointerdown', lpDown);
    ov.addEventListener('pointerup', lpUp);
    ov.addEventListener('pointercancel', lpUp);
    ov.addEventListener('pointerleave', lpUp);
    render();
  }
  function closeStockApp() {
    detachStockUI();
    // 返回挣钱大厅（游戏大厅本体界面）
    try { if (typeof renderEarnLobby === 'function') renderEarnLobby(); } catch (e) {}
  }

  // ---------- 长按「更新行情」= 自定义输入 ----------
  var lpState = { timer: null, fired: false };
  function lpDown(e) {
    var t = e.target;
    if (!t || !t.closest) return;
    var btn = t.closest('[data-stk-act="refresh"], [data-stk-act="update-now"]');
    if (!btn) return;
    lpState.fired = false;
    if (lpState.timer) clearTimeout(lpState.timer);
    lpState.timer = setTimeout(function () {
      lpState.timer = null;
      lpState.fired = true;
      openUpdateNote();
      // 防止个别无 pointerdown 的点击路径被误吞：1.5 秒后自动解除
      setTimeout(function () { lpState.fired = false; }, 1500);
    }, 550);
  }
  function lpUp() {
    if (lpState.timer) { clearTimeout(lpState.timer); lpState.timer = null; }
  }

  // ---------- 事件处理 ----------
  function handleActClick(e) {
    var t = e.target;
    if (!t || !t.closest) return;
    var closeBtn = t.closest('[data-stk-mclose]');
    if (closeBtn) { closeModal(); return; }
    var modelItem = t.closest('[data-stk-model]');
    if (modelItem) {
      var mi = modelItem.getAttribute('data-stk-model') || '';
      var inp = appEl ? appEl.querySelector('[data-stk-in="model"]') : null;
      if (inp) inp.value = mi;
      var s = API.state();
      s.model = mi;
      API.saveState();
      var st = appEl.querySelector('[data-stk-modelstatus]');
      if (st) st.textContent = '已选择：' + mi;
      var l = appEl.querySelector('[data-stk-modellist]');
      if (l) l.style.display = 'none';
      return;
    }
    var tblItem = t.closest('[data-stk-tbl]');
    if (tblItem && modalEl) {
      var idx = Math.round(Number(tblItem.getAttribute('data-stk-tbl')) || 1);
      var fEl = modalEl.querySelector('[data-stk-tfrom]');
      var tEl = modalEl.querySelector('[data-stk-tto]');
      if (fEl && tEl) {
        var f = Math.round(Number(fEl.value) || 0), tt = Math.round(Number(tEl.value) || 0);
        if (!f || !tt || f === tt) { fEl.value = Math.min(f || idx, idx); tEl.value = Math.max(tt || idx, idx); }
        else { fEl.value = idx; tEl.value = idx; }
        var items = modalEl.querySelectorAll('.ubp-gstk-titem');
        var fv = Math.round(Number(fEl.value) || 1), tv = Math.round(Number(tEl.value) || 1);
        for (var i = 0; i < items.length; i++) {
          var cur = Math.round(Number(items[i].getAttribute('data-stk-tbl')) || 0);
          items[i].classList.toggle('on', cur >= Math.min(fv, tv) && cur <= Math.max(fv, tv));
        }
      }
      return;
    }
    var actEl = t.closest('[data-stk-act]');
    var openEl = t.closest('[data-stk-open]');
    if (actEl) {
      var act = actEl.getAttribute('data-stk-act');
      var id = actEl.getAttribute('data-id') || '';
      if (act === 'back') {
        if (view.page !== 'list') {
          if (view.page === 'settings') doSaveSettings(true); // 离开设置自动保存，避免重开丢失
          view.page = 'list'; view.code = ''; render();
        } else closeStockApp();
        return;
      }
      if (act === 'settings') { doSaveSettings(true); view.page = 'settings'; render(); return; }
