  function loadConfig() {
    try {
      const raw = localStorage.getItem(CONFIG_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (!parsed.prompt) parsed.prompt = DEFAULT_PROMPT;
        // 狼人杀两版提示词：persona=角色人设版（默认，原版风格）/ fair=绝对公平版
        if (parsed.prompt === OLD_DEFAULT_PROMPT) parsed.prompt = DEFAULT_PROMPT; // 旧版默认自动升级（仅未自定义时）
        if (!parsed.promptFair) parsed.promptFair = DEFAULT_PROMPT_FAIR;
        const strictWolfInstruction = '请严格遵守下面的狼人杀规则、角色设定与发言格式，认真进行狼人杀游戏，并扮演好一名真实、投入的狼人杀游戏玩家。';
        const stripLegacyBoardParagraph = (s) => typeof s === 'string' ? s.replace(/本局板子可能是[\s\S]*?没有警长、警徽流、上警环节。/, strictWolfInstruction) : s;
        parsed.prompt = stripLegacyBoardParagraph(parsed.prompt);
        parsed.promptFair = stripLegacyBoardParagraph(parsed.promptFair);
        if (parsed.wolfPromptMode !== 'fair' && parsed.wolfPromptMode !== 'persona') parsed.wolfPromptMode = 'persona';
        // 节约Token开关（默认开启）：开启=沿用现有分批请求方式；关闭=按 RPM 并发上限逐条请求
        if (typeof parsed.wolfTokenSave !== 'boolean') parsed.wolfTokenSave = true;
        if (!(Number.isFinite(parsed.wolfRpm) && parsed.wolfRpm >= 1 && parsed.wolfRpm <= 20)) parsed.wolfRpm = 3;
        // 记忆回放开关（默认开启）：开启=向AI发送最近N场完整对局记录；关闭=不发送任何历史对局
        if (typeof parsed.memoryReplay !== 'boolean') parsed.memoryReplay = true;
        if (!(Number.isFinite(parsed.memoryReplayCount) && parsed.memoryReplayCount >= 1 && parsed.memoryReplayCount <= 3)) parsed.memoryReplayCount = 3;
        if (typeof parsed.wechatLink !== 'boolean') parsed.wechatLink = true;
        if (typeof parsed.worldBookLink !== 'boolean') parsed.worldBookLink = true;
        if (typeof parsed.socialLink !== 'boolean') parsed.socialLink = true;
        // 狼人杀 / 谁是卧底「完整注入」：开启后写入各自独立世界书，不再进【游戏】对局记录
        if (typeof parsed.wolfFullInject !== 'boolean') parsed.wolfFullInject = false;
        if (typeof parsed.spyFullInject !== 'boolean') parsed.spyFullInject = false;
        if ([6, 7, 8, 9, 10, 12].indexOf(parsed.wolfBoardSize) === -1) parsed.wolfBoardSize = 6;
        if (parsed.wolfBoardSize === 9 && parsed.wolfBoardVariant === 'beauty') {
          parsed.wolfBoardSize = 10;
          parsed.wolfBoardVariant = 'beauty10';
        }
        if (['classic', 'beauty', 'gods', 'guard6', 'wwknight', 'beauty10', 'ent8', 'onecut', 'hunter10'].indexOf(parsed.wolfBoardVariant) === -1) parsed.wolfBoardVariant = 'classic';
        if (parsed.wolfBoardSize === 7) {
          parsed.wolfBoardVariant = 'onecut';
        } else if (parsed.wolfBoardSize === 8) {
          parsed.wolfBoardVariant = 'ent8';
        } else if (parsed.wolfBoardSize === 10) {
          if (parsed.wolfBoardVariant !== 'wwknight' && parsed.wolfBoardVariant !== 'beauty10' && parsed.wolfBoardVariant !== 'hunter10') parsed.wolfBoardVariant = 'beauty10';
        } else if (parsed.wolfBoardSize === 12) {
          if (parsed.wolfBoardVariant !== 'wwknight' && parsed.wolfBoardVariant !== 'beauty') parsed.wolfBoardVariant = 'classic';
        } else if (parsed.wolfBoardVariant === 'gods' || parsed.wolfBoardVariant === 'wwknight' || parsed.wolfBoardVariant === 'beauty10' || parsed.wolfBoardVariant === 'ent8' || parsed.wolfBoardVariant === 'onecut' || parsed.wolfBoardVariant === 'hunter10') {
          parsed.wolfBoardVariant = 'classic';
        }
        if (parsed.wolfBoardSize !== 12 && parsed.wolfBoardVariant === 'beauty') parsed.wolfBoardVariant = 'classic';
        if (parsed.wolfBoardSize === 6) {
          if (parsed.wolfBoardVariant !== 'guard6') parsed.wolfBoardVariant = 'classic';
        } else if (parsed.wolfBoardVariant === 'guard6') parsed.wolfBoardVariant = 'classic';
        if (typeof parsed.wolfJudgeEnabled !== 'boolean') parsed.wolfJudgeEnabled = false;
        if (typeof parsed.wolfJudgeName !== 'string') parsed.wolfJudgeName = '';
        if (parsed.wolfJudgeName === '予') parsed.wolfJudgeName = '';
        return parsed;
      }
    } catch (e) { /* ignore */ }
    return { apiUrl: '', apiKey: '', model: 'gpt-3.5-turbo', prompt: DEFAULT_PROMPT, promptFair: DEFAULT_PROMPT_FAIR, wolfPromptMode: 'persona', wolfTokenSave: true, wolfRpm: 3, wechatLink: true, worldBookLink: true, socialLink: true, wolfBoardSize: 6, wolfBoardVariant: 'classic', wolfJudgeEnabled: false, wolfJudgeName: '', wolfFullInject: false, spyFullInject: false, memoryReplay: true, memoryReplayCount: 3 };
  }

