  // ---------- 牌桌 UI ----------
  function mjMeldHTML(m, isUser) {
    const gl = m.hidden && !isUser
      ? '<span style="opacity:0.9;">🀫🀫🀫🀫</span>'
      : m.tiles.map(mjGlyph).join('');
    const label = m.type === 'chi' ? '吃' : m.type === 'peng' ? '碰' : (m.hidden && !isUser ? '暗杠' : '杠');
    return '<span style="display:inline-flex;align-items:center;gap:1px;margin:2px;padding:1px 4px;border-radius:5px;background:rgba(255,255,255,0.08);border:1px solid var(--ubp-line);font-size:8.5px;color:var(--ubp-text-2);">' + label + '<span style="font-size:13px;letter-spacing:-1px;">' + gl + '</span></span>';
  }
  function mjClaimBarHTML(g) {
    const btns = [];
    for (const c of g.pendingClaim.claims) {
      if (!g.players[c.seat] || !g.players[c.seat].isUser) continue; // 只显示"我"可执行的决策按钮
      if (c.type === 'hu') btns.push('<button data-mj-act="mj-claim-hu" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12.5px;background:#10B981;border:none;border-radius:6px;">胡</button>');
      if (c.type === 'gang') btns.push('<button data-mj-act="mj-claim-gang" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12.5px;background:#D97706;border:none;border-radius:6px;">杠</button>');
      if (c.type === 'peng') btns.push('<button data-mj-act="mj-claim-peng" class="ubp-btn primary" style="flex:1;padding:6px 0;font-size:12.5px;background:#F59E0B;border:none;border-radius:6px;">碰</button>');
      if (c.type === 'chi') (c.options || [c]).forEach((o, i) => btns.push('<button data-mj-act="mj-claim-chi" data-i="' + i + '" class="ubp-btn" style="flex:1;padding:6px 0;font-size:12px;border-radius:6px;">吃 ' + o.tiles.map(mjTileName).join('') + '</button>'));
    }
    if (btns.length) btns.push('<button data-mj-act="mj-pass" class="ubp-btn" style="flex:1;padding:6px 0;font-size:12.5px;border-radius:6px;">过</button>');
    if (!btns.length) return '';
    return '<div style="display:flex;gap:6px;margin-bottom:6px;flex:none;flex-wrap:wrap;">' + btns.join('') + '</div>';
  }
  function renderMjGameUI() {
    const g = mj;
    if (!g) { renderMjLobby(); return; }
    const me = g.players[0];
    const hand = mjSort(g.hands[0]);
    const myTurn = mjDiscardClickable(g);
    const pending = g.phase === 'claim' && g.pendingClaim && Array.isArray(g.pendingClaim.claims);
    const canWin = myTurn && mjCanWin(g.hands[0], g.melds[0].length);
    const ankTiles = myTurn ? mjUniqueTiles(g.hands[0]).filter(t => mjCounts(g.hands[0])[t] === 4) : [];
    const bgTiles = myTurn ? g.melds[0].filter(m => m.type === 'peng' && g.hands[0].indexOf(m.tiles[0]) !== -1).map(m => m.tiles[0]) : [];
    const oppRows = g.players.slice(1).map((p, i) => {
      const s = i + 1;
      const on = g.turn === s && g.phase !== 'end';
      const melds = g.melds[s].map(m => mjMeldHTML(m, false)).join('');
      const river = g.discards[s].slice(-16).map(t => '<span style="font-size:14px;' + (g.last && g.last.seat === s && g.last.tile === t && g.discards[s].length && g.discards[s][g.discards[s].length - 1] === t ? 'outline:2px solid #F59E0B;border-radius:4px;' : '') + '">' + mjGlyph(t) + '</span>').join('');
      return '<div style="display:flex;align-items:center;gap:6px;padding:4px 8px;border-radius:8px;background:var(--ubp-card-2);border:1.5px solid ' + (on ? '#F59E0B' : 'var(--ubp-line)') + ';">' +
        chatAvatarHTML(p.name, false, 28, p.avatar) +
        '<div style="flex:1;min-width:0;"><div style="font-size:12px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(p.name) + ' · 剩 ' + g.hands[s].length + ' 张</div><div style="font-size:10px;color:var(--ubp-text-3);min-height:14px;">' + melds + '</div></div>' +
        '<div style="max-width:118px;white-space:nowrap;overflow:hidden;text-align:right;">' + river + '</div></div>';
    }).join('');
    const claimBar = pending ? mjClaimBarHTML(g) : '';
    const myMelds = g.melds[0].map(m => mjMeldHTML(m, true)).join('');
    let hint = '';
    if (g.phase === 'end') {
      const mjMoneyTip = (g.moneyDelta ? (' · 筹码 ' + (g.moneyDelta > 0 ? '+' : '') + g.moneyDelta) : '');
      hint = g.winner === 0 ? ('🎉 你胡了！' + mjMoneyTip) : g.winner >= 0 ? ('💀 ' + escapeHtml(g.players[g.winner].name) + ' 胡牌' + mjMoneyTip) : '🤝 流局（赌注不变）';
    } else if (pending) hint = '👉 上家打出 ' + mjTileName(g.last.tile) + '，选择你的操作';
    else if (myTurn) {
      if (canWin) hint = '🎉 你已听胡——可以自摸！';
