    const lastDisc = g.last ? ('<span style="font-size:15px;">' + escapeHtml(g.players[g.last.seat].name) + ' 打出</span> <span style="font-size:22px;">' + mjGlyph(g.last.tile) + '</span> <span style="font-size:10px;color:var(--ubp-text-3);">' + mjTileName(g.last.tile) + '</span>') : '<span style="font-size:10px;color:var(--ubp-text-3);">牌桌就绪</span>';
