        <input id="mj-chat-input" class="ubp-fieldinput" type="text" placeholder="对牌桌上的角色说点什么…（如：这手牌怎么样）" style="flex:1;font-size:12px;padding:4px 8px;border-radius:6px;height:26px;">
        <button data-mj-act="mj-send-chat" class="ubp-btn primary" style="padding:0 10px;font-size:12px;height:26px;background:#D97706;border:none;flex:none;">发送</button>
