      '    <span style="font-size:14.5px;font-weight:600;">🀄 麻将 · <span style="font-size:11px;color:var(--ubp-text-3);">' + (g.version === '108' ? '108张' : '136张') + ' · 牌墙剩 ' + g.wall.length + ' 张 · 赌注 ' + Math.max(1, Math.round(Number(g.bet) || 10)) + '</span></span>',
      '  </div>',
      '</div>',
      '<div style="display:flex;flex-direction:column;gap:5px;flex:none;">' + oppRows + '</div>',
      '<div style="display:flex;align-items:center;justify-content:center;gap:8px;padding:6px;border-radius:8px;background:rgba(245,158,11,0.08);border:1px dashed rgba(245,158,11,0.4);flex:none;margin:6px 0;">' + lastDisc + '</div>',
