      '<div style="flex:none;min-height:22px;margin-top:4px;font-size:11px;color:var(--ubp-text-2);">' + (myMelds || '') + '</div>',
      '<div style="flex:none;margin-top:2px;font-size:12px;color:var(--ubp-text);font-weight:600;text-align:center;">' + hint + '</div>',
      claimBar,
      (winBtns.length ? '<div style="display:flex;gap:6px;flex:none;margin-bottom:6px;flex-wrap:wrap;">' + winBtns.join('') + '</div>' : ''),
      '<div style="display:flex;justify-content:center;flex-wrap:wrap;flex:none;margin:2px 0 4px;">' + handTiles + '</div>',
