          '<span style="font-size:15px;color:#0F766E;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">' +
        '<span style="font-size:15px;font-weight:600;">📨 邀请角色入座（0~3 位）</span>' +
        '<button data-th-act="th-invite-close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#0F766E;">' + chosen.length + '</b> / 3（邀请几位就几位开局，不邀请则补 1 位陪玩）</div>' +
        '<div style="flex:1;overflow-y:auto;margin-bottom:8px;">' + (list || '<div style="font-size:12px;color:var(--ubp-text-3);">暂无可用角色（请先在大厅工作台创建自定义角色，或安装数据库本体）</div>') + '</div>' +
        '<div style="display:flex;justify-content:flex-end;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-th-act="th-invite-confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#0F766E;border:none;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-th-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const nm = el.dataset.thPick;
          const i = chosen.findIndex(n => isNameMatch(n, nm));
          if (i !== -1) chosen.splice(i, 1);
          else { if (chosen.length >= 3) { showToast('最多邀请 3 位角色'); return; } chosen.push(nm); }
          render();
        });
      });
    };
    render();
    sheet.appendChild(ov);
  }

  // 德州扑克设置（AI 陪聊 / 角色搭话频率 / AI 打牌强度 / 注释）
