        actionBar += '<button data-uno-act="uno-call-zero" class="ubp-btn" style="padding:6px 12px;font-size:12.5px;background:#E11D48;color:#fff;border:none;font-weight:700;">📣 喊 UNO！（0 变体 · 5 秒内）</button>';
      }
    }
    const endButtons = g.phase === 'end' ? ('<div style="display:flex;gap:8px;flex-wrap:wrap;padding:6px 0;">' +
      '<button data-uno-act="uno-rematch" class="ubp-btn" style="padding:6px 14px;font-size:13px;">🔄 再来一局</button>' +
