    const logHTML = (g.log || []).slice(-14).map(t => '<div style="font-size:11.5px;line-height:1.5;color:var(--ubp-text-2);">' + escapeHtml(t) + '</div>').join('');
    sheet.innerHTML = '<style>' + UBP_FX_CSS + UBP_FX2_CSS + '</style>' + [
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex:none;">',
