    const input = sheet.querySelector('#uno-chat-input');
    if (input) input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); unoHandleUserChatSend(); } });
    scheduleUnoGameStateSave();
  }

  // ---------- 角色 AI 陪聊 ----------
  function unoPushSpeech(seat, text) {
    const g = unoGame;
    if (!g || !text) return;
    g.speeches.push({ seat: seat, name: g.players[seat] ? g.players[seat].name : '角色', text: text });
    if (g.speeches.length > 30) g.speeches = g.speeches.slice(-30);
    if (typeof contactsVoiceAutoSpeak === 'function') contactsVoiceAutoSpeak(g.speeches.length ? g.speeches[g.speeches.length - 1].name : '', text);
  }

  function unoMaybeAutoSpeak(scene, seat, force) {
    const g = unoGame;
    if (!g || !g.aiChat) return;
    if (unoChatBusy) return;
    if (!force) {
      if (Date.now() - (g.lastSpeechAt || 0) < 7000) return;
      if ((g.userActions || 0) % (g.speechInterval || 4) !== 0) return;
    }
    let target = seat;
    if (target === undefined || target === null || target < 0 || !g.players[target] || g.players[target].isUser || g.players[target].hand.length === 0) {
      target = (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    }
    if (target === undefined) return;
    unoRequestSpeech(target, scene, null);
  }
  function unoRequestSpeech(seat, scene, userMsg) {
    const g = unoGame;
    if (!g || !g.aiChat) return;
    const p = g.players[seat];
    if (!p || p.isUser) return;
    const apiCfg = ensureAIBackend();
    if (!apiCfg) return;
    if (unoChatBusy) return;
    const gen = unoGenCounter;
    const prof = getCharacterProfile(p.name) || {};
    const phoneCtx = getCharacterWechatContext(p.name);
    const socialCtx = getCharacterSocialContext(p.name);
    const others = g.players.filter(x => x.seat !== seat).map(x => x.name + (x.isUser ? '（主角）' : '')).join('、');
    const recentEvents = (g.log || []).slice(-8).join('\n');
    const sceneText = {
      start: 'UNO 牌局刚刚开始，每人 7 张牌',
      play: '刚才有人出牌了',
      draw: '刚才有人摸牌了',
      plus: '刚才有人被 +2/+4 罚牌了',
      reverse: '刚才有人打出反转',
      skip: '刚才有人被跳过',
      win: '本局刚刚结束',
      'user-chat': '主角正在牌桌上对你说话，你需要回应主角'
    }[scene] || '牌桌上的闲聊时刻';
    const system = '你和主角、其他好友正在玩一局《UNO》（108 张，红黄蓝绿四色 + 数字牌/跳过/反转/+2/变色/+4；剩 1 张要喊 UNO；没有可出的牌只能摸牌跳过）。你扮演【' + p.name + '】，牌桌上的自然聊天。\n' +
      '【角色档案（来自小手机/神数据库）】\n' +
      '- 身份：' + (prof.identity || '好友') + '\n' +
      '- 性格：' + (prof.personality || '自然活泼') + '\n' +
      '- 说话风格与口癖：' + (prof.languageStyle || '口语化') + '\n' +
      '- 对主角态度：' + (prof.attitude || '友好亲近') + '\n' +
      '【小手机内你们最近的微信聊天记录】\n' + (phoneCtx || '（暂无，按人物关系自然发挥）') + '\n\n' +
      '【' + p.name + ' 在小手机里的近期社交动态（朋友圈/贴吧/小红书）】\n' + (socialCtx || '（暂无）') + '\n\n' +
      '【牌局信息】\n' +
      '- 同局玩家：' + others + '\n' +
      '- 当前颜色：' + UNO_COLOR_NAME[g.currentColor] + '；弃牌堆顶：' + unoCardText(g.discard[g.discard.length - 1]) + '；你的手牌 ' + p.hand.length + ' 张' + (g.drawStack > 0 ? '（罚牌累计 ' + g.drawStack + '）' : '') + '\n' +
      '- 当前场景：' + sceneText + '\n' +
      '- 牌桌最近发生的事情（从旧到新）：\n' + (recentEvents || '（开局阶段）') + '\n' +
      '- 你上一句说过的话：' + (((g.speeches || []).filter(s => s.seat === seat).slice(-1)[0] || {}).text || '（暂无）') + '\n\n' +
      '【台词要求】\n' +
      '1. 完全代入【' + p.name + '】的身份、性格、语言风格与对主角的态度，说出生动自然的真人台词。\n' +
      '2. 【重点】必须围绕牌桌刚才发生了什么来发言：吐槽被 +2/+4、炫耀手上的好牌、喊 UNO 的得意或紧张、催主角出牌，或顺势聊你们在小手机微信/朋友圈里的互动。严禁直接报出自己手牌的具体牌面。\n' +
      '3. 要有活人感：可带情绪、开玩笑、抱怨、撒娇、炫耀或关心主角，严禁空洞复读。\n' +
      '4. 严禁使用括号、旁白、动作与心理描写，只输出角色说出口的话。\n' +
      '5. 【完整出字铁律】只输出：<lines>台词正文</lines>，不要多余文字；发言长度自然，可长可短，口语化；必须语义完整、自然收尾，严禁半句截断、严禁空回复。';
    const messages = [{ role: 'system', content: system }];
    if (userMsg) messages.push({ role: 'user', content: '【主角对你说】' + userMsg + '\n请以【' + p.name + '】的口吻回一句。' });
    else messages.push({ role: 'user', content: '请以【' + p.name + '】的口吻说一段完整的牌桌台词（发言长度自然，可长可短，口语化；必须语义完整、自然收尾）。' });
    unoChatBusy = true;
    g.lastSpeechAt = Date.now();
    apiChat(messages, apiCfg, { maxTokens: 900, temperature: 0.95 }).then(res => {
      if (gen !== unoGenCounter || !unoGame || unoGame.session !== g.session) return;
      let clean = ensureCompleteLine(String(res || '').replace(/<lines>|<\/lines>/gi, '').replace(/["'「」]/g, '').trim());
      if (p.name) clean = clean.replace(new RegExp('^' + p.name + '[：:]\\s*'), '');
      if (!clean || clean.length < 4) return;
      if (!/[。！？…]$/.test(clean)) clean += '。';
      unoPushSpeech(seat, clean);
      unoRefreshSpeechBox();
    }).catch(() => { /* 静默失败 */ }).finally(() => { if (gen === unoGenCounter) unoChatBusy = false; });
  }
  function unoRefreshSpeechBox() {
    const el = sheet?.querySelector('#uno-speech-text');
    const container = sheet?.querySelector('#uno-speech-container');
    if (!el || !unoGame) return;
    el.innerHTML = unoRenderSpeechHTML();
    if (container) container.scrollTop = container.scrollHeight;
  }
  function unoRenderSpeechHTML() {
    const g = unoGame;
    if (!g) return '';
    const conv = (g.speeches || []).slice(-24);
    if (!conv.length) return '<span style="color:var(--ubp-text-3);">（牌桌上很安静，大家都在盯牌…）</span>';
    return conv.map(sp => chatSpeechRowHTML(sp.name, sp.text, sp.seat === 0)).join('');
  }
  function unoHandleUserChatSend() {
    const g = unoGame;
    if (!g || !g.aiChat) return;
    const input = sheet.querySelector('#uno-chat-input');
    if (!input) return;
    const msg = input.value.trim();
    if (!msg) return;
    input.value = '';
    g.speeches.push({ seat: 0, name: '我', text: msg });
    unoRefreshSpeechBox();
    let target = (g.phase === 'playing' && g.turn !== 0) ? g.turn : (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    if (!g.players[target] || g.players[target].isUser) target = (function () { for (let i2 = 1; i2 < g.players.length; i2++) if (g.players[i2] && !g.players[i2].isUser) return i2; return undefined; })();
    if (target === undefined) return;
    unoRequestSpeech(target, 'user-chat', msg);
  }

  // ---------- 操作分发 ----------
  function handleUnoAction(act, target) {
    const g = unoGame;
    if (act === 'uno-open') {
      if (g && g.phase === 'playing') renderUnoGameUI();
      else if (hasSavedUnoGame()) resumeSavedUnoGame();
      else renderUnoLobby();
      return;
    }
    if (act === 'uno-back') { if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); renderTableGameLobby(); return; }
    if (act === 'uno-settings') { renderUnoSettings(); return; }
    if (act === 'uno-invite') { unoInviteOverlay(); return; }
    if (act === 'uno-invite-close') { const ov = sheet.querySelector('.uno-invite-overlay'); if (ov) ov.remove(); return; }
    if (act === 'uno-invite-confirm') { const ov = sheet.querySelector('.uno-invite-overlay'); if (ov) ov.remove(); renderUnoLobby(); return; }
    if (act === 'uno-start') {
      if (aiChatInviteGate({
        chatOn: loadUnoConfig().aiChat,
        invited: unoInvites.filter(Boolean).length,
        label: 'UNO',
        onInvite: () => unoInviteOverlay(),
        onDisableAndStart: () => { const c2 = loadUnoConfig(); c2.aiChat = false; saveUnoConfig(c2); handleUnoAction('uno-start', null); }
      })) return;
      const n = unoInvites.filter(Boolean).length;
      if (n < 3) showToast('🪑 入座 ' + n + '/3，其余席位由机器人补位');
      unoStartMatch(unoInvites.slice());
      return;
    }
    if (act === 'uno-exit') {
      if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll(); // 离开游戏：清空排队语音并切断在读语音
      if (g && g.phase === 'playing') saveUnoGameState();
      else clearSavedUnoGame();
      if (unoAiTimer) clearTimeout(unoAiTimer);
      unoGenCounter++;
      unoGame = null;
      renderUnoLobby();
      return;
    }
    if (act === 'uno-resume') { resumeSavedUnoGame(); return; }
    if (act === 'uno-discard') { clearSavedUnoGame(); renderUnoLobby(); showToast('🗑️ 已放弃进行中的 UNO 对局'); return; }
    // 设置项与"返回 UNO 大厅"必须放在"进行中对局"守卫之前：
    // 否则从大厅进入设置后，难度/变体/关闭按钮会被守卫直接 return 掉，全部失效。
    if (act === 'uno-set-level') {
      const lvl = target && target.dataset ? target.dataset.level : null;
      if (!lvl) return;
      const c = loadUnoConfig();
      c.aiLevel = lvl;
      saveUnoConfig(c);
      renderUnoSettings();
      showToast('🧠 UNO AI 难度已切换：' + (lvl === 'strong' ? '高级（蒙特卡洛）' : lvl === 'fast' ? '基础（新手）' : '进阶'));
      return;
    }
    if (act === 'uno-settings-done') { renderUnoLobby(); return; }
    if (act === 'uno-rematch') {
      const names = (g && g.players) ? g.players.slice(1).map(p => p.name).filter(n => n && n.indexOf('牌友') !== 0) : unoInvites.slice();
      if (aiChatInviteGate({
        chatOn: loadUnoConfig().aiChat,
        invited: names.filter(n2 => !isBuiltinPlayerName(n2)).length,
        label: 'UNO',
        onInvite: () => renderUnoLobby(),
        onDisableAndStart: () => { const c2 = loadUnoConfig(); c2.aiChat = false; saveUnoConfig(c2); handleUnoAction('uno-rematch', null); }
      })) return;
      if (unoAiTimer) clearTimeout(unoAiTimer);
      unoStartMatch(names.length >= 3 ? names.slice(0, 3) : names.concat(unoInvites.slice(0, 3)));
      return;
    }
    if (act === 'uno-send-chat') { unoHandleUserChatSend(); return; }
    if (!g || g.phase !== 'playing') return;
    if (act === 'uno-call') {
      const me = g.players[0];
      if (me.hand.length === 1 && !me.saidUno) {
        if (g.pendingUno && g.pendingUno.deadline && Date.now() > g.pendingUno.deadline) { showToast('⌛ 超过 5 秒，喊 UNO 失败！'); return; }
        me.saidUno = true;
        if (g.pendingUno && g.pendingUno.seat === 0) g.pendingUno = null;
        unoLog(g, '📣 你在 5 秒内喊了 UNO！');
        saveUnoGameState();
        renderUnoGameUI();
      }
      return;
    }
    if (act === 'uno-call-zero') {
      const pz = g.pendingZero;
      if (!pz || !(pz.pendingSeats || []).includes(0)) return;
      if (pz.deadline && Date.now() > pz.deadline) { showToast('⌛ 超过 5 秒，喊 UNO 失败！'); return; }
      pz.pendingSeats = pz.pendingSeats.filter(s => s !== 0);
      unoLog(g, '📣 你在 5 秒内喊了 UNO！');
      if (!pz.pendingSeats.length) g.pendingZero = null;
      saveUnoGameState();
      renderUnoGameUI();
      return;
    }
    if (act === 'uno-take-penalty') {
      if (g.turn !== 0 || (g.drawStack || 0) <= 0) return;
      if (!unoBeginTurn(g, 0)) return; // 无叠牌时会自动认罚并跳到下家
      const amt = g.drawStack;
      if ((g.drawStack || 0) > 0) { unoDrawToHand(g, 0, amt); unoLog(g, '😭 你认罚摸 ' + amt + ' 张并跳过。'); g.drawStack = 0; g.stackType = null; g.turn = unoNextSeat(g, 0); saveUnoGameState(); renderUnoGameUI(); if (g.turn !== 0) unoScheduleAi(unoDelayFor(g)); }
      return;
    }
    if (act === 'uno-color') {
      const color = target && target.dataset ? target.dataset.color : null;
      if (!color || !g.pendingColor) return;
      const idx = g.pendingColor.idx;
      g.pendingColor = null;
      if (!unoPlayCard(0, idx, color, false)) { showToast('❌ 这张牌现在不能出'); renderUnoGameUI(); }
      return;
    }
    if (g.turn !== 0) { showToast('⏳ 还没轮到你'); return; }
    if (act === 'uno-draw') {
      if (!unoBeginTurn(g, 0)) return;
      const playableBefore = unoPlayableList(g, 0).length > 0;
      if (playableBefore) { showToast('💡 你有能出的牌，也可以选择主动摸牌（摸牌后跳过回合）'); }
      const drawn = unoDrawToHand(g, 0, 1);
      g.actionCount++;
      g.userActions = (g.userActions || 0) + 1;
      if (!drawn) { showToast('牌库空了'); return; }
      unoLog(g, '🖐 你摸了一张牌，回合结束（摸牌后不能出牌）。');
      unoMaybeAutoSpeak('draw', 0);
      g.turn = unoNextSeat(g, 0);
      saveUnoGameState();
      renderUnoGameUI();
      if (g.turn !== 0) unoScheduleAi(unoDelayFor(g));
      return;
    }
    if (act === 'uno-play') {
      const idx = target && target.dataset ? parseInt(target.dataset.idx, 10) : -1;
      if (!(idx >= 0)) return;
      if (!unoBeginTurn(g, 0)) return;
      const playable = unoPlayableForUser(g);
      const item = playable.find(x => x.idx === idx);
      if (!item) { showToast('❌ 只能出与当前颜色/数字相同的牌，或黑色万能牌'); return; }
      if (unoIsWild(item.card)) {
        g.pendingColor = { idx: idx, card: item.card };
        renderUnoGameUI();
        showToast('🌈 请选择下一轮的颜色');
        return;
      }
      unoPlayCard(0, idx, null, false);
      return;
    }
  }

  // ---------- 大厅 / 邀请 / 设置 ----------
  function renderUnoLobby() {
    const cfg = loadUnoConfig();
    const pn = unoInvites.filter(Boolean);
    const hasSaved = hasSavedUnoGame();
    let savedInfo = null;
    if (hasSaved) { try { savedInfo = JSON.parse(localStorage.getItem(UNO_SAVE_KEY)); } catch (e) { /* ignore */ } }
    let resumeBanner = '';
    if (savedInfo && savedInfo.players) {
