  function unoInviteOverlay() {
    const result = loadContactsWithAvatars();
    const contacts = (result && result.contacts) || [];
    if (!contacts.length) { showToast('资料库没有可用角色（需要瑟瑟灵感数据库的恋爱对象表/重要角色表）'); return; }
    const picked = unoInvites.filter(Boolean).slice();
    const MAX = 3;
    const ov = document.createElement('div');
    ov.className = 'uno-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:66;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';
    const renderContent = () => {
      const list = contacts.map(ct => {
        const on = picked.some(n => isNameMatch(n, ct.name));
        const av = ct.avatar || getCharacterAvatarByName(ct.name);
        return '<div data-uno-pick="' + escapeHtml(ct.name).replace(/"/g, '&quot;') + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:' + (on ? 'rgba(225,29,72,0.16)' : 'var(--ubp-card-2)') + ';border:1.5px solid ' + (on ? '#E11D48' : 'var(--ubp-line)') + ';">' +
          '<div style="width:34px;height:34px;border-radius:50%;background:#E11D48;overflow:hidden;flex-shrink:0;">' +
          (av ? '<img src="' + av + '" style="width:100%;height:100%;object-fit:cover;">' : '<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:13px;">' + escapeHtml(ct.name.slice(0, 1)) + '</span>') + '</div>' +
          '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(ct.name) + '</div>' +
          (ct.identity ? '<div style="font-size:10.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">' + escapeHtml(ct.identity) + '</div>' : '') + '</div>' +
          '<span style="font-size:15px;color:#E11D48;flex-shrink:0;">' + (on ? '✅' : '○') + '</span></div>';
      }).join('');
      ov.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">' +
        '<span style="font-size:15px;font-weight:600;">👥 邀请 UNO 牌友（最多 3 位）</span>' +
        '<button data-uno-inv="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button></div>' +
        '<div style="font-size:11.5px;color:var(--ubp-text-2);margin-bottom:8px;">已选 <b style="color:#E11D48;">' + picked.length + '</b> / ' + MAX + ' 位（邀请几位就几位开局，不邀请则补 1 位陪玩）</div>' +
        '<div style="flex:1;overflow-y:auto;margin-bottom:8px;">' + list + '</div>' +
        '<div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">' +
        '<button data-uno-inv="confirm" class="ubp-btn primary" style="padding:6px 20px;font-size:13px;background:#E11D48;border:none;border-radius:6px;">确认邀请</button></div>';
      ov.querySelectorAll('[data-uno-pick]').forEach(el => {
        el.addEventListener('click', () => {
          const nm = el.dataset.unoPick;
          const i = picked.findIndex(n => isNameMatch(n, nm));
          if (i !== -1) picked.splice(i, 1);
          else {
            if (picked.length >= MAX) { showToast('最多邀请 ' + MAX + ' 位牌友'); return; }
            picked.push(nm);
          }
          renderContent();
        });
      });
      ov.querySelector('[data-uno-inv="close"]')?.addEventListener('click', () => { ov.remove(); });
      ov.querySelector('[data-uno-inv="confirm"]')?.addEventListener('click', () => {
        unoInvites = picked.slice();
        ov.remove();
        renderUnoLobby();
        showToast('🪑 已入座：' + (picked.join('、') || '（全机器人补位）'));
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }
