  // ---------- 断点保存 / 恢复 ----------
  function saveUnoGameState() {
    const g = unoGame;
    if (!g || g.phase === 'end' || g.phase === 'idle') { clearSavedUnoGame(); return; }
    try {
      const state = {
        session: g.session, players: g.players, deck: g.deck, discard: g.discard, currentColor: g.currentColor,
        turn: g.turn, dir: g.dir, dealer: g.dealer, phase: g.phase, drawStack: g.drawStack, stackType: g.stackType,
        pendingColor: g.pendingColor, pendingUno: g.pendingUno, pendingZero: g.pendingZero || null,
        round: g.round, winner: g.winner, log: g.log, history: g.history,
