      bjLog(g, '🪙 筹码不足底注，自动离场结算');
      g.phase = 'roundEnd';
      bjSaveGame();
      bjRender();
      showToast('🪙 筹码不足底注，自动离场结算');
      setTimeout(() => {
        if (bjGame === g && g.phase === 'roundEnd') {
          bjEndSession();
          if (bjGame === g) { bjGame = null; renderBjLobby(); }
        }
      }, 1200);
      return;
    }
    g.phase = 'play';
    g.hands = [{ cards: [], bet: g.baseBet, doubled: false, done: false, split: false, result: null, payout: 0 }];
    g.dealer = [];
    g.insurance = 0; g.insuranceTaken = false; g.insuranceOffered = false;
    bjDrawTo(g.hands[0].cards); bjDrawTo(g.dealer);
    bjDrawTo(g.hands[0].cards); bjDrawTo(g.dealer);
    if (g.dealer[0]) g.dealer[0].hole = true; // 庄家首张为暗牌
    const meBJ = bjIsBlackjack(g.hands[0].cards);
    const dealerBJ = bjIsBlackjack(g.dealer);
    bjLog(g, '🃏 第 ' + g.round + ' 局发牌：你 ' + g.hands[0].cards.map(bjCardText).join(' ') + '（' + bjHandValue(g.hands[0].cards).total + '） · 庄家明牌 ' + bjCardText(g.dealer[1]));
    // 保险：庄家明牌是 A
    if (g.insuranceAllowed && g.dealer[1] && g.dealer[1].r === 'A' && g.chips >= g.baseBet / 2 && !meBJ) {
      g.insuranceOffered = true;
      g.phase = 'insurance';
      bjRender();
      return;
    }
    bjAfterInsurance(meBJ, dealerBJ);
  }
  function bjAfterInsurance(meBJ, dealerBJ) {
    const g = bjGame;
    if (!g) return;
    if (dealerBJ) {
      g.dealer.forEach(c => { c.hole = false; });
      if (meBJ) { bjSettleHand(g.hands[0], 'push', g.hands[0].bet, '双方黑杰克，平局退回赌注'); }
      else { bjSettleHand(g.hands[0], 'lose', -g.hands[0].bet, '庄家黑杰克，你输掉赌注'); }
      bjLog(g, '🃏 庄家亮牌：' + g.dealer.map(bjCardText).join(' ') + ' —— 黑杰克！');
      bjEndRound();
      return;
    }
    if (meBJ) {
      bjSettleHand(g.hands[0], 'bj', Math.floor(g.hands[0].bet * 1.5), '黑杰克！赢得 1.5 倍赌注');
      g.dealer.forEach(c => { c.hole = false; });
      bjLog(g, '🃏 你拿到黑杰克（21 点），直接获胜');
      bjEndRound();
      return;
    }
    g.phase = 'play';
    bjRender();
    if (g.round === 1) bjMaybeAutoSpeak('deal', true); else bjMaybeAutoSpeak('deal');
  }
  function bjSettleHand(h, result, payout, note) {
    h.result = result; h.payout = payout; h.done = true;
    const g = bjGame;
    g.chips += payout;
    g.netChips += payout;
    if (result === 'win' || result === 'bj') g.wins++;
    else if (result === 'push') g.pushes++;
    else g.losses++;
    bjLog(g, (result === 'bj' ? '🏆 ' : result === 'win' ? '✅ ' : result === 'push' ? '🤝 ' : '❌ ') + note + '（' + (payout >= 0 ? '+' : '') + payout + '）');
  }
  // 庄家行动：按「荷官难度」决定要牌/停牌（简单＝16 停；标准＝≤16 要；困难＝≤16 要 + 软17 要）
  function bjDealerPlay() {
    const g = bjGame;
    if (!g) return;
    g.dealer.forEach(c => { c.hole = false; });
    let guard = 0;
    while (guard++ < 20) {
      const v = bjHandValue(g.dealer);
      if (bjDealerMustHit(v, g.aiLevel)) { bjDrawTo(g.dealer); continue; }
      break;
    }
    const dv = bjHandValue(g.dealer).total;
    bjLog(g, '🏦 庄家亮牌：' + g.dealer.map(bjCardText).join(' ') + '（' + dv + '）' + (dv > 21 ? ' —— 爆牌！' : ''));
    for (const h of g.hands) {
      if (h.done && h.result) continue;
      const pv = bjHandValue(h.cards).total;
      if (pv > 21) { bjSettleHand(h, 'lose', -h.bet, '你爆牌（' + pv + '）'); continue; }
      if (dv > 21) { bjSettleHand(h, 'win', h.bet, '庄家爆牌，你赢 ' + h.bet); continue; }
      if (pv > dv) bjSettleHand(h, 'win', h.bet, '你的 ' + pv + ' 大于庄家 ' + dv + '，赢 ' + h.bet);
      else if (pv < dv) bjSettleHand(h, 'lose', -h.bet, '你的 ' + pv + ' 小于庄家 ' + dv + '，输 ' + h.bet);
      else bjSettleHand(h, 'push', 0, '双方都是 ' + pv + ' 点，平局退回赌注');
    }
    bjEndRound();
  }
  function bjEndRound() {
    const g = bjGame;
    if (!g) return;
    g.phase = 'roundEnd';
    bjSaveGame();
    bjRender();
    // 保险结算（庄家黑杰克时 2:1 赔付）
    if (g.insuranceTaken && bjIsBlackjack(g.dealer) === false && g.insurance > 0) { /* 已在下面统一处理 */ }
    if (g.insuranceTaken && g.insurance > 0) {
      const dealerBJ = bjIsBlackjack(g.dealer);
      if (dealerBJ) { g.chips += g.insurance * 3; g.netChips += g.insurance * 3; bjLog(g, '🛡️ 保险赔付 ' + (g.insurance * 3) + '（庄家确为黑杰克）'); }
      else { bjLog(g, '🛡️ 庄家不是黑杰克，保险金 ' + g.insurance + ' 没收'); }
      g.insuranceTaken = false;
      bjRender();
    }
    // 结算改为在点【退出】时统一写回筹码钱包（对局中不再实时写回、每局不再单独结算）
    if (g.chips < g.baseBet) {
      bjLog(g, '🪙 筹码不足底注，你已没钱继续，自动离场结算');
      showToast('🪙 筹码不足底注，自动离场结算');
      setTimeout(() => {
        if (bjGame === g && g.phase === 'roundEnd') {
          bjEndSession();
          if (bjGame === g) { bjGame = null; renderBjLobby(); }
        }
      }, 1400);
    } else {
      const h0 = g.hands && g.hands[0];
      const scene = h0 && (h0.result === 'win' || h0.result === 'bj') ? 'win' : h0 && h0.result === 'push' ? 'push' : 'lose';
      bjMaybeAutoSpeak(scene);
    }
  }
  function bjNextRound() {
    const g = bjGame;
    if (!g) return;
    g.round++;
    bjStartRound();
    bjRender();
  }
  // 弃局（放弃存档）：静默把筹码差结算回钱包，不写对局记录
  function bjSettleSavedAbandon() {
    try {
      const raw = localStorage.getItem(BJ_SAVE_KEY);
      if (!raw) return;
      const d = JSON.parse(raw);
      if (!d) return;
      const chips = Math.max(0, Math.round(Number(d.chips) || 0));
      const start = Number.isFinite(d.sessionStartChips) ? d.sessionStartChips : chips;
      const delta = chips - start;
      if (delta !== 0) addChips('blackjack', delta);
    } catch (e) { /* ignore */ }
  }
  function bjEndSession() {
    const g = bjGame;
    if (!g || g.recorded) return;
    g.recorded = true;
    g.phase = 'sessionEnd';
    // 🪙 退出结算：整场（主注 + 保险）净额统一写回筹码钱包，只写一条结算
    const startChips = Number.isFinite(g.sessionStartChips) ? g.sessionStartChips : g.chips;
    const net = Math.round((Number(g.chips) || 0) - startChips);
    const played = Math.max(0, (g.wins || 0) + (g.losses || 0) + (g.pushes || 0));
    if (net !== 0) {
      const total = addChips('blackjack', net);
      showToast('🪙 退出结算：筹码 ' + (net > 0 ? '+' : '') + net + '（共 ' + played + ' 手，现有 ' + total + '）');
    }
    bjSaveGame();
    const userWon = net > 0;
    bjLog(g, '📊 本场结束：共 ' + (g.round - (g.phase === 'roundEnd' ? 0 : 1)) + ' 局 · 胜 ' + g.wins + ' / 负 ' + g.losses + ' / 平 ' + g.pushes + ' · 净筹码 ' + (net >= 0 ? '+' : '') + net);
    try {
      onGameFinished({
        gameType: 'blackjack',
        userWon: userWon,
        isDraw: net === 0,
        result: (userWon ? '21点获胜' : net === 0 ? '21点平手' : '21点落败') + '：净筹码 ' + (net >= 0 ? '+' : '') + net,
        detail: '共 ' + g.round + ' 局 · 胜 ' + g.wins + ' / 负 ' + g.losses + ' / 平 ' + g.pushes + ' · 牌靴 ' + g.decks + ' 副 · 荷官难度：' + bjDealerLevelName(g.aiLevel),
        players: [{ name: '我', isUser: true, avatar: getMainCharAvatar() }, { name: g.dealerChar.name, isUser: false, avatar: g.dealerChar.avatar || '' }],
        replay: (g.history || []).slice(-60).join('\n')
      });
    } catch (e) { /* ignore */ }
    bjSaveGame();
    bjRender();
  }
  function bjUserHit() {
    const g = bjGame;
    if (!g || g.phase !== 'play') return;
    const h = g.hands.find(x => !x.done);
    if (!h) return;
    bjDrawTo(h.cards);
    const v = bjHandValue(h.cards);
    g.userActions = (g.userActions || 0) + 1;
    bjLog(g, '👉 你要牌：' + bjCardText(h.cards[h.cards.length - 1]) + ' → ' + h.cards.map(bjCardText).join(' ') + '（' + v.total + '）');
    if (v.total > 21) { bjSettleHand(h, 'lose', -h.bet, '你爆牌（' + v.total + '），本手直接输'); bjMaybeAutoSpeak('bust'); bjAfterHandDone(); return; }
    if (v.total === 21) { h.done = true; bjLog(g, '✅ 21 点，自动停牌'); bjAfterHandDone(); return; }
    bjSaveGame(); bjRender();
    bjMaybeAutoSpeak('hit');
  }
  function bjUserStand() {
    const g = bjGame;
    if (!g || g.phase !== 'play') return;
    const h = g.hands.find(x => !x.done);
    if (!h) return;
    h.done = true;
    g.userActions = (g.userActions || 0) + 1;
    bjLog(g, '✋ 你停牌（' + bjHandValue(h.cards).total + ' 点）');
    bjMaybeAutoSpeak('stand');
    bjAfterHandDone();
  }
  function bjUserDouble() {
    const g = bjGame;
    if (!g || g.phase !== 'play') return;
    const h = g.hands.find(x => !x.done);
    if (!h || h.cards.filter(c => c && !c.hole).length !== 2 || g.chips < h.bet) { showToast('❌ 加倍只能在开局两张牌时使用，且筹码要够'); return; }
    h.bet *= 2; h.doubled = true;
    g.userActions = (g.userActions || 0) + 1;
    bjLog(g, '💥 你选择加倍：赌注翻倍为 ' + h.bet + '，只能再拿 1 张牌');
    bjDrawTo(h.cards);
    const v = bjHandValue(h.cards);
    bjLog(g, '👉 加倍补牌：' + bjCardText(h.cards[h.cards.length - 1]) + ' → ' + h.cards.map(bjCardText).join(' ') + '（' + v.total + '）');
    h.done = true;
    if (v.total > 21) bjSettleHand(h, 'lose', -h.bet, '加倍后爆牌（' + v.total + '）');
    bjMaybeAutoSpeak('double');
    bjAfterHandDone();
  }
  function bjUserSplit() {
    const g = bjGame;
    if (!g || g.phase !== 'play') return;
    const idx = g.hands.findIndex(x => !x.done);
    const h = g.hands[idx];
    if (!h) return;
    const base = h.cards.filter(c => c && !c.hole);
    if (base.length !== 2 || bjHandValue([base[0]]).total !== bjHandValue([base[1]]).total) { showToast('❌ 只有两张点数相同的牌才能分牌'); return; }
    if (g.hands.length >= 3) { showToast('❌ 最多分牌两次（3 手）'); return; }
    if (g.chips < h.bet) { showToast('❌ 筹码不足以再下一注完成分牌'); return; }
    const moved = base.pop();
    const nh = { cards: [moved], bet: h.bet, doubled: false, done: false, split: true, result: null, payout: 0 };
    h.cards = base;
