    const fxRoundKey = String(g.session || '') + '|' + g.round;
    const fxNewRound = bjFxState.key !== fxRoundKey;
    if (fxNewRound) { bjFxState.key = fxRoundKey; bjFxState.dealerSig = []; bjFxState.handSigs = []; bjFxState.resultSigs = []; }
    const fxDealerSig = (g.dealer || []).map(c => (c.hole ? '?' : bjCardText(c)));
    const fxDealerPrev = bjFxState.dealerSig || [];
    const fxDealerMore = fxDealerSig.length > fxDealerPrev.length;
    const fxDealerReveal = fxDealerSig.length === fxDealerPrev.length && fxDealerPrev.some((s, i) => s === '?' && fxDealerSig[i] !== '?');
    bjFxState.dealerSig = fxDealerSig;
    const dealerCards = (g.dealer || []).map((c, i) => bjCardFxHTML(c, {
      hidden: !!c.hole
    }, (fxNewRound || (fxDealerMore && i >= fxDealerPrev.length)) ? 'ubp-fx-deal' : ((fxDealerReveal && fxDealerPrev[i] === '?' && !c.hole) ? 'ubp-fx-flip' : ''), i * 80)).join('');
