      const fxPrevSig = bjFxState.handSigs[i] || [];
      const fxSig = h.cards.map(bjCardText);
      const fxNewCards = fxNewRound || !fxPrevSig.length;
      const fxMoreCards = fxSig.length > fxPrevSig.length;
