      return '<div' + fxHandCls + ' style="border:1.5px solid ' + (active ? '#F59E0B' : 'var(--ubp-line)') + ';border-radius:9px;padding:7px 9px;margin-bottom:7px;background:var(--ubp-card-2, #26262a);">' +
