  function clearSavedGame() {
    try {
      localStorage.removeItem(SAVE_GAME_KEY);
    } catch (e) { /* ignore */ }
  }

  function hasSavedGame() {
    if (game && !isGameOver && (game.phase === 'night' || game.phase === 'day' || game.phase === 'vote')) {
      return true;
    }
    try {
      const raw = localStorage.getItem(SAVE_GAME_KEY);
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      return parsed && parsed.players && (parsed.players.length === 6 || parsed.players.length === 7 || parsed.players.length === 8 || parsed.players.length === 9 || parsed.players.length === 10 || parsed.players.length === 12) && (parsed.phase === 'night' || parsed.phase === 'day' || parsed.phase === 'vote');
    } catch (e) {
      return false;
    }
  }

