          wolfBeautyCharmedPos: data.wolfBeautyCharmedPos || null,
          wolfBeautyLastCharmedPos: data.wolfBeautyLastCharmedPos || 0,
          wolfBeautyChainResolved: !!data.wolfBeautyChainResolved,
          knightDuelUsed: !!data.knightDuelUsed,
          knightPromptActive: !!data.knightPromptActive,
          knightPromptContext: data.knightPromptContext || '',
          knightPromptIsAi: !!data.knightPromptIsAi,
          knightSheriffPromptDone: !!data.knightSheriffPromptDone,
          knightAiAskCount: data.knightAiAskCount || 0,
          nightToken: 0
        };
        isGameOver = false;
      }
      // 兼容旧存档：法官不能同时作为玩家
      try {
        const resumeJudge = String(game.judgeName || '');
        const resumeUsed = new Set((game.players || []).map(pl => pl.name));
        let resumeFillNo = 1;
        let resumeJudgeReplaced = false;
        (game.players || []).forEach(pl => {
          if (resumeJudge && !pl.isUser && isNameMatch(pl.name, resumeJudge)) {
            let filler = '';
            do { filler = '角色' + (resumeFillNo++); } while (resumeUsed.has(filler) || isNameMatch(filler, resumeJudge));
            resumeUsed.add(filler);
            pl.name = filler;
            pl.avatar = '';
            resumeJudgeReplaced = true;
          }
        });
        if (resumeJudgeReplaced) {
          if (Array.isArray(game.wolfTeammateNames)) game.wolfTeammateNames = game.wolfTeammateNames.filter(n => !isNameMatch(n, resumeJudge));
          if (game.wolfBeautyTeammateName && isNameMatch(game.wolfBeautyTeammateName, resumeJudge)) game.wolfBeautyTeammateName = '';
          showToast('⚖️ 旧存档中法官不能同时作为玩家，已自动补位');
        }
      } catch (e) { /* ignore */ }
      resetWolfBatchGuard();
      renderGameUI();
      resumeCurrentPhase();
    } catch (e) {
      console.error('[狼人杀恢复对局失败]', e);
      clearSavedGame();
      renderBoard();
    }
  }

  function resumeCurrentPhase() {
    if (!game || isGameOver) return;
    if (game.nightToken === undefined) game.nightToken = 0;
    // 后台等待玩家遗言：重进时直接恢复遗言输入界面，不重跑其它流程
    if (typeof game.resolvingFinalWords === 'function') {
      showUserFinalWordsUI();
      return;
    }
    if (game.knightPromptActive) {
      if (game.phase === 'day') { resumeKnightPrompt(); return; }
      game.knightPromptActive = false;
      game.knightPromptContext = '';
      game.knightPromptIsAi = false;
    }
    if (game.phase === 'night') {
      // 按夜晚子步骤续跑，避免重进后验人/刀人/用药整晚重跑
      const step = game.nightStep || 'guard';
      if (step === 'guard') stepGuardAction();
      else if (step === 'wolf') stepWolfAction();
      else if (step === 'wolfbeauty') stepWolfBeautyAction();
      else if (step === 'seer') stepSeerAction();
      else if (step === 'witch') stepWitchAction();
      else if (step === 'end') finishNightAndStartDay();
      else runNightSequence();
    } else if (game.phase === 'day') {
      if (typeof game.currentSpeaker !== 'number' || game.currentSpeaker < 0 || game.currentSpeaker >= game.players.length) game.currentSpeaker = 0;
      // PK 辩解阶段仍处于 day：恢复 PK 进度而不是重开白天发言
      if (game.isPkSpeaking && game.pkCandidates && game.pkCandidates.length) runNextPkSpeaker();
      else if (game.sheriffStage && game.sheriffStage !== 'done') resumeSheriffStage();
      else if (!game.dayAnnounced) afterSheriffElection(!!(game.sheriffPos && !game.sheriffBadgeTorn));
      // 今天尚未开始发言（如警长方向思考中断在重启中丢失）：重新进入方向决定/发言初始化，避免直接续跑导致整轮发言被跳过
      else if (game.speechesStartedDay !== game.day) afterSheriffElection(!!(game.sheriffPos && !game.sheriffBadgeTorn));
      else {
        const cur = game.players[game.currentSpeaker];
        if (!cur || !cur.alive || cur.hasSpoken) nextSpeaker();
        else startSpeaking();
      }
    } else if (game.phase === 'vote') {
      if (game.isPkVote) {
        startPkVote();
      } else {
        startVote();
      }
    }
  }

