      });
      fabRing.appendChild(item);
    });
    const fabBtn = document.createElement('button');
    fabBtn.className = 'thgame-fab-btn';
    fabBtn.title = '游戏大厅（可拖动）';
    fabBtn.style.cssText = 'position:absolute;left:-26px;top:-26px;width:52px;height:52px;border-radius:50%;border:2px solid rgba(255,255,255,0.85);background:radial-gradient(circle at 30% 30%, #a78bfa, #7c3aed 60%, #5b21b6);box-shadow:0 5px 14px rgba(0,0,0,0.55);cursor:grab;touch-action:none;display:flex;align-items:center;justify-content:center;font-size:24px;line-height:1;color:#fff;padding:0;animation:thgame-pulse 2.4s infinite;';
    fabBtn.textContent = '🕹️';
    fabBtn.addEventListener('pointerdown', (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      fabDragRef = { x: e.clientX, y: e.clientY, rect: fabRoot.getBoundingClientRect() };
      fabMoved = false;
      e.preventDefault();
    });
    fabBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (fabMoved) return;
      const open = fabRing.style.display !== 'none';
      if (open) closeFabRing();
      else {
        layoutFabRing();
        fabRing.style.display = 'block';
        fabBtn.textContent = '✕';
      }
    });
    doc.addEventListener('pointermove', (e) => {
      if (!fabDragRef) return;
      const vw2 = doc.defaultView || window;
      const vwW = vw2.innerWidth || window.innerWidth || 1024;
      const vwH = vw2.innerHeight || window.innerHeight || 768;
      const dx = e.clientX - fabDragRef.x;
      const dy = e.clientY - fabDragRef.y;
      if (!fabMoved && Math.hypot(dx, dy) > 6) fabMoved = true;
      if (fabMoved) {
        fabRoot.style.right = 'auto';
        fabRoot.style.bottom = 'auto';
        fabRoot.style.left = Math.max(4, Math.min(vwW - 30, fabDragRef.rect.left + dx)) + 'px';
        fabRoot.style.top = Math.max(4, Math.min(vwH - 30, fabDragRef.rect.top + dy)) + 'px';
      }
    });
    const endDrag = () => {
      if (fabDragRef && fabMoved && fabRoot) {
        const r = fabRoot.getBoundingClientRect();
        savePos(FAB_POS_KEY, r.left, r.top);
      }
      fabDragRef = null;
    };
    doc.addEventListener('pointerup', endDrag);
    doc.addEventListener('pointercancel', endDrag);

    fabRoot.appendChild(fabRing);
    fabRoot.appendChild(fabBtn);
    doc.body.appendChild(fabRoot);
    const style = doc.createElement('style');
    style.id = 'thgame-fab-style';
    style.textContent = '@keyframes thgame-pulse { 0%,100% { box-shadow: 0 5px 14px rgba(0,0,0,0.55), 0 0 0 0 rgba(167,139,250,0.5); } 50% { box-shadow: 0 5px 14px rgba(0,0,0,0.55), 0 0 0 10px rgba(167,139,250,0); } }';
    doc.head.appendChild(style);
    const outside = (e) => {
      if (fabRoot && !fabRoot.contains(e.target)) {
        closeFabRing();
        resetFabBtnFace();
      }
    };
    doc.addEventListener('pointerdown', outside, true);
    return true;
  }

