    // 四向箭头拖动把手：按住拖动可调整游戏大厅窗口位置
    const moveHandle = document.createElement('div');
    moveHandle.className = 'thgame-move-handle';
    moveHandle.title = '拖动调整大厅位置';
    moveHandle.style.cssText = 'position:absolute;top:7px;left:50%;transform:translateX(-50%);z-index:300;background:rgba(28,28,32,0.72);border:1px solid rgba(255,255,255,0.25);border-radius:999px;padding:3px 10px;cursor:move;user-select:none;display:flex;align-items:center;justify-content:center;';
    moveHandle.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="#ffffff" style="opacity:0.9;"><path d="M10 9h4V6h3l-5-5-5 5h3v3zm-1 1H6V7l-5 5 5 5v-3h3v-4zm14 2-5-5v3h-3v4h3v3l5-5zm-9 3h-4v3H7l5 5 5-5h-3v-3z"/></svg>';
    moveHandle.addEventListener('pointerdown', (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      const dragRef = { x: e.clientX, y: e.clientY, lx: hallWindowPos.x, ly: hallWindowPos.y };
      e.preventDefault();
      e.stopPropagation();
      const onMove = (ev) => {
        const dx = ev.clientX - dragRef.x;
        const dy = ev.clientY - dragRef.y;
        hallWindowPos.x = Math.max(4, Math.min(vwW - 60, dragRef.lx + dx));
        hallWindowPos.y = Math.max(4, Math.min(vwH - 48, dragRef.ly + dy));
        overlay.style.left = hallWindowPos.x + 'px';
        overlay.style.top = hallWindowPos.y + 'px';
      };
      const onUp = () => {
        savePos(HALL_POS_KEY, hallWindowPos.x, hallWindowPos.y);
        doc.removeEventListener('pointermove', onMove);
        doc.removeEventListener('pointerup', onUp);
        doc.removeEventListener('pointercancel', onUp);
      };
      doc.addEventListener('pointermove', onMove);
      doc.addEventListener('pointerup', onUp);
      doc.addEventListener('pointercancel', onUp);
    });
    overlay.appendChild(moveHandle);

    doc.body.appendChild(overlay);
    renderSetup();
    // 按钮功能提示：鼠标悬停用原生 title；触屏长按 600ms 弹出该按钮/条目的功能说明
    let lpTipTimer = null, lpTipEl = null, lpTipShownAt = 0, lpTipNode = null;
    const hideLpTip = () => {
      if (lpTipTimer) { clearTimeout(lpTipTimer); lpTipTimer = null; }
      if (lpTipNode) { try { lpTipNode.remove(); } catch (err) { /* ignore */ } lpTipNode = null; }
    };
    overlay.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'mouse') return;
      const el = e.target && e.target.closest ? e.target.closest('[title]') : null;
      if (!el) return;
      if (el.closest('#ms-grid')) return; // 扫雷棋盘：长按用于插旗，不做功能提示
      const tipText = el.getAttribute('title');
      if (!tipText) return;
      lpTipEl = el;
      lpTipTimer = setTimeout(() => {
        lpTipTimer = null;
        if (lpTipEl !== el) return;
        const tip = document.createElement('div');
        let left = 10, top = 10;
        try {
          const rect = el.getBoundingClientRect();
          const vw2 = window.innerWidth || 360, vh2 = window.innerHeight || 640;
          left = Math.max(8, Math.min(vw2 - 236, rect.left + rect.width / 2 - 118));
          top = rect.bottom + 8;
          if (top + 90 > vh2) top = Math.max(8, rect.top - 96);
        } catch (err) { /* ignore */ }
        tip.style.cssText = 'position:fixed;left:' + left + 'px;top:' + top + 'px;z-index:2147483200;width:236px;box-sizing:border-box;background:rgba(0,0,0,0.92);color:#fff;border-radius:8px;padding:8px 10px;font-size:11.5px;line-height:1.5;pointer-events:none;white-space:pre-wrap;';
        tip.textContent = tipText;
        document.body.appendChild(tip);
        lpTipNode = tip;
        lpTipShownAt = Date.now();
      }, 600);
    }, { passive: true });
    overlay.addEventListener('pointerup', () => {
      if (lpTipTimer) { clearTimeout(lpTipTimer); lpTipTimer = null; }
      setTimeout(hideLpTip, 2400);
    }, { passive: true });
    overlay.addEventListener('pointercancel', hideLpTip, { passive: true });
    overlay.addEventListener('pointermove', () => { if (lpTipTimer) { clearTimeout(lpTipTimer); lpTipTimer = null; } }, { passive: true });
    overlay.addEventListener('click', (e) => {
      // 长按查看功能说明后抑制随后的误触点击
      if (lpTipShownAt && Date.now() - lpTipShownAt < 700) {
        lpTipShownAt = 0;
        hideLpTip();
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      const ubTarget = e.target.closest('[data-ubp-act]');
      if (ubTarget) {
        const act = ubTarget.dataset.ubpAct;
        handleAction(act, ubTarget);
        return;
      }
const bgTarget = e.target.closest('[data-bg-act]');
      if (bgTarget) {
        const bgAct = bgTarget.dataset.bgAct;
        handleBoardAction(bgAct, bgTarget);
        return;
      }
      const spyTarget = e.target.closest('[data-spy-act]');
      if (spyTarget) {
        const spyAct = spyTarget.dataset.spyAct;
        handleSpyAction(spyAct, spyTarget);
        return;
      }
      const rpsTarget = e.target.closest('[data-rps-act]');
      if (rpsTarget) {
        const rpsAct = rpsTarget.dataset.rpsAct;
        handleRpsAction(rpsAct, rpsTarget);
        return;
      }
      const tttTarget = e.target.closest('[data-ttt-act]');
      if (tttTarget) {
        const tttAct = tttTarget.dataset.tttAct;
        handleTttAction(tttAct, tttTarget);
        return;
      }
      const bjTarget = e.target.closest('[data-bj-act]');
      if (bjTarget) {
        const bjAct = bjTarget.dataset.bjAct;
        handleBjAction(bjAct, bjTarget);
        return;
      }
      const unoTarget = e.target.closest('[data-uno-act]');
      if (unoTarget) {
        const unoAct = unoTarget.dataset.unoAct;
        handleUnoAction(unoAct, unoTarget);
        return;
      }
      const ddzTarget = e.target.closest('[data-ddz-act]');
      if (ddzTarget) {
        const ddzAct = ddzTarget.dataset.ddzAct;
        handleDDZAction(ddzAct, ddzTarget);
        return;
      }
      const rmTarget = e.target.closest('[data-rm-act]');
      if (rmTarget) {
        const rmAct = rmTarget.dataset.rmAct;
        handleRmAction(rmAct, rmTarget);
        return;
      }
      const ludoTarget = e.target.closest('[data-ludo-act]');
      if (ludoTarget) {
        const ludoAct = ludoTarget.dataset.ludoAct;
        handleLudoAction(ludoAct, ludoTarget);
        return;
      }
      const lieTarget = e.target.closest('[data-lie-act]');
      if (lieTarget) {
        const lieAct = lieTarget.dataset.lieAct;
        handleLieAction(lieAct, lieTarget);
        return;
      }
      const llkTarget = e.target.closest('[data-llk-act]');
      if (llkTarget) {
