      ctx.font = '800 ' + Math.max(22, Math.round(W * 0.075)) + 'px "Courier New", monospace';
      ctx.fillStyle = '#F43F5E';
      ctx.fillText('GAME OVER', W / 2, H * 0.46);
      ctx.restore();
      ctx.textAlign = 'left';
      ctx.textBaseline = 'alphabetic';
