      if (!g2.piece) { tetrisSpawn(g2); tetrisResetTimer(); return; }
      if (!tetrisCollide(g2, g2.piece.key, g2.piece.rot, g2.piece.x, g2.piece.y + 1)) { g2.piece.y += 1; tetrisRender(); }
