      const byW = Math.floor((Math.min(vw, 560) - 30 - (TETRIS_COLS - 1)) / TETRIS_COLS);
      cell = Math.max(18, Math.min(44, Math.min(byH, byW)));
    } catch (e) { /* ignore */ }
    const display = g.board.map(row => row.slice());
    if (g.piece && g.phase === 'play') {
      const shape = tetrisShapeOf(g.piece.key, g.piece.rot);
      for (let r = 0; r < shape.length; r++) {
        for (let c = 0; c < shape[r].length; c++) {
          if (!shape[r][c]) continue;
