  function tbRenderBattle() {
    const t = tetrisBattle;
    if (!t) return;
    const cell = tbCellSize();
    const upd = (side, idp) => {
      const be = sheet && sheet.querySelector('#tb-' + idp + '-board');
      if (be) {
        be.style.gridTemplateColumns = 'repeat(' + TETRIS_COLS + ', ' + cell + 'px)';
        be.style.gridAutoRows = cell + 'px';
        be.innerHTML = tbBoardHTML(side, cell);
      }
      const ie = sheet && sheet.querySelector('#tb-' + idp + '-info');
      if (ie) ie.innerHTML = '得分 <b>' + side.score + '</b> · 消行 <b>' + side.lines + '</b>' + (side.pending ? ' · <b style="color:#EF4444;">垃圾 +' + side.pending + '</b>' : '');
      const ne = sheet && sheet.querySelector('#tb-' + idp + '-next');
      if (ne) ne.innerHTML = tbNextHTML(side);
    };
    upd(t.sides.ai, 'ai');
    upd(t.sides.user, 'user');
    const ov = sheet && sheet.querySelector('#tb-overlay');
    if (ov) {
      if (t.over) {
        const userWon = !!(t.winner && !t.winner.isAI);
        ov.style.display = 'flex';
        ov.innerHTML = '<div style="background:var(--ubp-card,#1c1c20);border:1px solid var(--ubp-line);border-radius:14px;padding:18px 16px;text-align:center;max-width:260px;">' +
          '<div style="font-size:32px;margin-bottom:6px;">' + (userWon ? '🏆' : '💀') + '</div>' +
          '<div style="font-size:16px;font-weight:700;color:' + (userWon ? '#34D399' : '#F87171') + ';">' + (userWon ? '你赢了！' : '你输了') + '</div>' +
          '<div style="font-size:11px;color:var(--ubp-text-2);margin:6px 0 12px;line-height:1.5;">' + escapeHtml(t.reason || '') + '<br>得分 我 ' + t.sides.user.score + ' : ' + t.sides.ai.score + ' ' + escapeHtml(tbOppName()) + '</div>' +
          '<div style="display:flex;gap:6px;">' +
          '<button data-ubp-act="tb-again" class="ubp-btn primary" style="flex:1;padding:7px 0;font-size:12.5px;background:#8B5CF6;border:none;">🔄 再来一局</button>' +
          '<button data-ubp-act="tb-lobby" class="ubp-btn" style="flex:1;padding:7px 0;font-size:12.5px;">🏠 小游戏对战大厅</button>' +
          '</div></div>';
      } else {
        ov.style.display = 'none';
        ov.innerHTML = '';
      }
    }
    t.lastHash = tbStateHash();
  }

  // ---------- 对战主循环与出入口 ----------
  function tbStopBattleTimer() { if (tbBattleTimer) { clearInterval(tbBattleTimer); tbBattleTimer = null; } }
  function tbStartBattleTimer() {
    tbStopBattleTimer();
    tbBattleTimer = setInterval(tbMasterTick, 100);
  }
  function tbMasterTick() {
    const t = tetrisBattle;
    if (!t || t.over) { tbStopBattleTimer(); return; }
    if (!sheet || !sheet.querySelector('#tb-user-board')) { tbStopBattleTimer(); tetrisBattle = null; return; }
    const lv = TB_LEVELS[t.level] || TB_LEVELS.normal;
    const u = t.sides.user, a = t.sides.ai;
    u.dropAcc = (u.dropAcc || 0) + 100;
    if (u.dropAcc >= lv.gravityMs) { u.dropAcc = 0; tbStepDown(u, a); }
    if (!t.over) {
      a.aiAcc = (a.aiAcc || 0) + 100;
      if (a.aiAcc >= lv.aiStepMs) { a.aiAcc = 0; tbAIStep(a, u); }
    }
    if (t.over) { tbRenderBattle(); return; }
    const h = tbStateHash();
    if (h !== t.lastHash) tbRenderBattle();
  }
  function startTetrisBattle(wantOpponentName) {
    tetrisStop();
    tbStopBattleTimer();
    const level = tbLevel();
    // 邀请角色作为对手（与石头剪刀布 / 井字棋一致）：不邀请则默认电脑 AI
    const result = wantOpponentName ? loadContactsWithAvatars() : null;
    const contacts = result?.contacts || [];
    const opp = (wantOpponentName && contacts.find(c => c.name === wantOpponentName)) || null;
    tetrisBattle = {
      level: level,
      opponent: opp ? { name: opp.name, avatar: opp.avatar || getCharacterAvatarByName(opp.name) || '', identity: opp.identity || '' } : null,
      over: false, winner: null, reason: '', lastHash: '',
      sides: { ai: tbNewSide(true), user: tbNewSide(false) }
    };
    tbSpawnPiece(tetrisBattle.sides.ai, tetrisBattle.sides.user);
    if (!tetrisBattle.over) tbSpawnPiece(tetrisBattle.sides.user, tetrisBattle.sides.ai);
    renderTetrisBattleUI();
    if (!tetrisBattle.over) tbStartBattleTimer();
  }
  function tbBackToSingle() {
    tbStopBattleTimer();
    tetrisBattle = null;
    if (tetrisGame) {
      renderTetrisGameUI();
      if (tetrisGame.phase === 'play') tetrisResetTimer();
    } else {
      startTetrisGame();
    }
  }
  function tbQuitToLobby() {
    tbStopBattleTimer();
    tetrisBattle = null;
    renderAIBattleLobby();
  }
  function tbUserMove(dx) {
    const t = tetrisBattle;
    if (!t || t.over) return;
    if (tbMovePiece(t.sides.user, dx)) tbRenderBattle();
  }
  function tbUserRotate() {
    const t = tetrisBattle;
    if (!t || t.over) return;
    if (tbRotatePiece(t.sides.user)) tbRenderBattle();
  }
  function tbUserSoftDrop() {
    const t = tetrisBattle;
    if (!t || t.over) return;
    if (tbStepDown(t.sides.user, t.sides.ai)) tbRenderBattle();
    else if (!t.over) tbRenderBattle();
  }
  function tbUserHardDrop() {
    const t = tetrisBattle;
    if (!t || t.over) return;
    const s = t.sides.user;
    if (!s.piece) return;
    while (!tbCollideBoard(s.board, s.piece.key, s.piece.rot, s.piece.x, s.piece.y + 1)) s.piece.y += 1;
    tbLockAndResolve(s, t.sides.ai);
    tbRenderBattle();
  }

  // ========== 对战邀请角色弹窗（俄罗斯方块：可选择角色作为对手，默认电脑 AI） ==========
  function renderTBBattleInviteOverlay() {
    const t = tetrisBattle;
    if (!t) return;
    tbStopBattleTimer(); // 打开邀请面板时暂停对战，避免选人期间自己的棋盘被自动落块顶爆
    const result = loadContactsWithAvatars();
    const contacts = result?.contacts || [];
    let chosenName = (t.opponent && t.opponent.name) ? t.opponent.name : '';
    let chosenAI = !t.opponent;

    const ov = document.createElement('div');
    ov.className = 'tb-invite-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:60;background:var(--ubp-card, #1c1c20);display:flex;flex-direction:column;padding:12px 10px 8px;box-sizing:border-box;';

    const renderContent = () => {
      const aiSelected = chosenAI;
      const aiRow = `
        <div data-tb-pick-ai="1" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${aiSelected ? 'rgba(139,92,246,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${aiSelected ? '#8B5CF6' : 'var(--ubp-line)'};">
          <div style="width:40px;height:40px;border-radius:50%;background:#8B5CF6;display:flex;align-items:center;justify-content:center;font-size:19px;flex-shrink:0;">🤖</div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:14px;font-weight:600;color:var(--ubp-text);">电脑 AI${aiSelected ? ' 👑 (当前对手)' : ''}</div>
            <div style="font-size:11.5px;color:var(--ubp-text-3);margin-top:2px;">默认对手 · 不邀请角色</div>
          </div>
        </div>`;
      const listHtml = contacts.map(c => {
        const isSelected = !chosenAI && c.name === chosenName;
        const av = c.avatar || getCharacterAvatarByName(c.name);
        return `
          <div data-tb-pick="${escapeAttr(c.name)}" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;margin-bottom:6px;cursor:pointer;background:${isSelected ? 'rgba(139,92,246,0.15)' : 'var(--ubp-card-2, #26262a)'};border:1.5px solid ${isSelected ? '#8B5CF6' : 'var(--ubp-line)'};">
            <div style="width:40px;height:40px;border-radius:50%;background:#8B5CF6;overflow:hidden;flex-shrink:0;box-shadow:0 1px 4px rgba(0,0,0,0.2);">
              ${av ? `<img src="${escapeAttr(av)}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:15px;">${escapeHtml(c.name.slice(0, 1))}</span>`}
            </div>
            <div style="flex:1;min-width:0;">
              <div style="font-size:14px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(c.name)} ${isSelected ? '👑 (已选对手)' : ''}</div>
              ${c.identity ? `<div style="font-size:11.5px;color:var(--ubp-text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;">${escapeHtml(c.identity)}</div>` : ''}
            </div>
          </div>
        `;
      }).join('');

      ov.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">
          <span style="font-size:16px;font-weight:bold;color:var(--ubp-text);">👥 邀请对战对手</span>
          <button data-tb-invite="close" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
        <div style="font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;">请选择 1 位角色作为俄罗斯方块对战的对手（显示其头像与名字；选「电脑 AI」则恢复默认）：</div>
        <div style="flex:1;overflow-y:auto;padding-right:2px;margin-bottom:8px;">
          ${aiRow}
          ${listHtml || '<div style="font-size:12px;color:var(--ubp-text-3);">通讯录暂无角色，请确保神数据库已添加角色。</div>'}
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--ubp-line);flex:none;">
          <button data-tb-invite="confirm" class="ubp-btn primary" style="padding:6px 20px;background:#8B5CF6;font-size:13px;border-radius:6px;">确认邀请</button>
        </div>
      `;

      ov.querySelector('[data-tb-pick-ai]')?.addEventListener('click', () => { chosenAI = true; chosenName = ''; renderContent(); });
      ov.querySelectorAll('[data-tb-pick]').forEach(el => {
        el.addEventListener('click', () => {
          chosenAI = false;
          chosenName = el.dataset.tbPick;
          renderContent();
        });
      });
      ov.querySelector('[data-tb-invite="close"]')?.addEventListener('click', () => { ov.remove(); if (tetrisBattle && !tetrisBattle.over) tbStartBattleTimer(); });
      ov.querySelector('[data-tb-invite="confirm"]')?.addEventListener('click', () => {
        const g = tetrisBattle;
        if (g) {
          if (chosenAI || !chosenName) {
            g.opponent = null;
          } else {
            const c = contacts.find(x => x.name === chosenName);
            if (c) g.opponent = { name: c.name, avatar: c.avatar || getCharacterAvatarByName(c.name) || '', identity: c.identity || '' };
          }
        }
        ov.remove();
        renderTetrisBattleUI();
        if (g && !g.over) tbStartBattleTimer();
        if (g) showToast(g.opponent ? '👥 已邀请「' + g.opponent.name + '」作为俄罗斯方块对战对手' : '🤖 已恢复与电脑 AI 对战');
      });
    };

    renderContent();
    sheet.appendChild(ov);
  }

