  // ========== 对局记录查看界面 ==========
  function renderRecordView() {
    const store = loadGenericMatchHistory();
    const types = listKnownGameTypes(store);

    const refreshIcon = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-2.64-6.36"/><path d="M21 3v6h-6"/></svg>`;

    const renderEntry = (gameType, m, i) => {
      const title = getGameTypeDisplayName(gameType);
      const when = m.timestamp ? new Date(m.timestamp).toLocaleString('zh-CN', { hour12: false }) : '';
      const result = m.result || '';
      const detail = m.detail || '';
      const hasReplay = !!(m.replay || m.highlight || m.afterparty || m.moment);
      return `
        <div style="background:var(--ubp-card-2);border-radius:10px;padding:10px 12px;margin-bottom:8px;border:1px solid var(--ubp-line);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span style="font-size:13.5px;font-weight:600;color:var(--ubp-text);">🎮 ${title} · 第${i + 1}场</span>
            <div style="display:flex;align-items:center;gap:6px;flex:none;">
              <span style="font-size:11px;color:var(--ubp-text-3);">${when}</span>
              <button data-ubp-act="record-delete" data-game="${gameType}" data-idx="${i}" style="background:none;border:none;cursor:pointer;color:#EF4444;font-size:15px;line-height:1;padding:2px;" title="删除该场对局记录">✕</button>
            </div>
          </div>
          <div style="font-size:12px;color:var(--ubp-text-2);margin-top:4px;line-height:1.5;">${escapeHtml(result)}</div>
          ${detail ? `<div style="font-size:11.5px;color:var(--ubp-text-2);margin-top:3px;line-height:1.4;">${escapeHtml(detail)}</div>` : ''}
          <div style="display:flex;justify-content:flex-end;margin-top:6px;">
            <button data-ubp-act="record-detail" data-game="${gameType}" data-idx="${i}" class="ubp-btn" style="padding:3px 12px;font-size:11.5px;${hasReplay ? '' : 'opacity:0.45;'}" ${hasReplay ? '' : 'disabled'}>📜 查看详情</button>
          </div>
        </div>
      `;
    };

    let body = '';
    for (const gameType of types) {
      const list = store[gameType] || [];
      const isDeduction = isDeductionGame(gameType);
      body += `<div style="font-size:13px;font-weight:600;color:var(--ubp-text);margin:8px 0 6px;">${isDeduction ? '🕵️' : '♟️'} ${getGameTypeDisplayName(gameType)}（最近 ${list.length} 场）</div>`;
      body += list.map((m, i) => renderEntry(gameType, m, i)).join('');
    }
    if (!body) body = `<div class="ubp-empty" style="padding:28px 0;text-align:center;">暂无对局记录，快去游戏中心开一局吧~</div>`;

    sheet.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex:none;">
        <span style="font-size:17px;font-weight:600;">📋 对局记录</span>
        <div style="display:flex;gap:4px;">
          <button data-ubp-act="record-settings" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);" title="对局记录设置">⚙️</button>
          <button data-ubp-act="close-record" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ubp-text);">✕</button>
        </div>
      </div>
      <div style="flex:1;overflow-y:auto;">${body}</div>
    `;
  }

// 渲染赛后复盘群聊：按「名字：内容」分行，每行角色名使用该角色的专属配色
  // players 传入本局玩家时使用「局内互不相同」的配色表，避免撞色
    function renderReplayRichHTML(logs, playersSnapshot) {
    const snap = Array.isArray(playersSnapshot) ? playersSnapshot : [];
    const colorMap = buildDistinctColorMap(snap.map(p => ({ name: p && p.name })));
    const colorOfPos = (pos) => {
      const p = snap.find(x => x && x.position === pos);
      if (!p || !p.name) return '';
      return colorMap.get(p.name) || getCharacterColor(p.name) || '';
    };
    const isUserPos = (pos) => snap.some(x => x && x.isUser && x.position === pos);
    const list = Array.isArray(logs) ? logs : [];
    if (!list.length) return '<div class="ubp-empty" style="padding:20px 0;text-align:center;color:var(--ubp-text-3);">（本局暂无回放内容）</div>';
    return list.map(item => {
      if (!item || typeof item !== 'object') {
        return '<div style="color:#fff;margin:2px 0;">' + escapeHtml(stripLogTags(String(item == null ? '' : item))) + '</div>';
      }
      const textHTML = escapeHtml(stripLogTags(item.text || '')).replace(/\n/g, '<br>');
      const judgeName = item.judgeName && String(item.judgeName) !== '予' ? String(item.judgeName) : '';
      const userLine = !judgeName && item.authorPos != null && isUserPos(item.authorPos);
      const cc = (!judgeName && !userLine && item.authorPos != null) ? colorOfPos(item.authorPos) : '';
      const authorName = (() => {
        if (judgeName) return judgeName;
        if (item.authorPos == null) return '';
        const p = snap.find(x => x && x.position === item.authorPos);
        return p && p.name ? p.name : '';
      })();
      const authorAvatar = (() => {
        if (judgeName) return getCharacterAvatarByName(judgeName) || '';
        if (item.authorPos == null) return '';
        const p = snap.find(x => x && x.position === item.authorPos);
        return (p && p.avatar) ? p.avatar : '';
      })();
      const avatarHTML = authorName ? chatAvatarHTML(authorName, userLine, 24, authorAvatar) : '';
      const rowOpen = authorName ? '<div style="display:flex;align-items:flex-start;gap:6px;margin:4px 0;"><div style="flex:none;">' + avatarHTML + '</div><div style="flex:1;min-width:0;">' : '';
      const rowClose = authorName ? '</div></div>' : '';
      if (item.type === 'judge') {
        if (!judgeName) return '<div style="color:#FBBF24;font-size:12px;background:rgba(251,191,36,0.10);border-left:3px solid #FBBF24;padding:4px 6px;border-radius:4px;">' + textHTML + '</div>';
        return rowOpen + '<div style="color:#FBBF24;font-size:12px;background:rgba(251,191,36,0.10);border-left:3px solid #FBBF24;padding:4px 6px;border-radius:4px;"><b style="color:#FBBF24;">' + escapeHtml(judgeName) + '：</b>' + textHTML + '</div>' + rowClose;
      }
      if (item.type === 'hidden') {
        const base = cc || '#FFD700';
        return rowOpen + '<div style="color:' + base + ';font-size:11px;background:' + (charColorAlpha(cc, '17') || 'rgba(255,215,0,0.1)') + ';border-left:3px solid ' + base + ';padding:4px 6px;border-radius:4px;">' + textHTML + '</div>' + rowClose;
      }
      if (item.type === 'wolf_private') {
        return rowOpen + '<div style="color:#C084FC;font-size:12px;background:rgba(168,85,247,0.12);padding:4px;border-radius:4px;">' + textHTML + '</div>' + rowClose;
      }
      if (item.type === 'user_private') {
        return rowOpen + '<div style="color:' + (item.color || '#FBBF24') + ';font-size:12px;font-weight:600;">' + textHTML + '</div>' + rowClose;
      }
      if (userLine) {
        return rowOpen + '<div style="color:#fff;font-size:12px;font-weight:600;border-left:3px solid rgba(255,255,255,0.55);padding-left:6px;">' + textHTML + '</div>' + rowClose;
      }
      if (cc) {
        return rowOpen + '<div style="color:' + cc + ';font-size:12px;font-weight:600;border-left:3px solid ' + charColorAlpha(cc, '99') + ';padding-left:6px;">' + textHTML + '</div>' + rowClose;
      }
      return '<div style="color:#fff;margin:2px 0;">' + textHTML + '</div>';
    }).join('');
  }

  // 旧版纯文本回放兜底渲染：按「名字：内容」匹配角色专属配色，主角发言白色
  function renderReplayTextColored(text, players) {
    const list = String(text || '').split(/\n+/);
    if (!list.length) return '';
    const colorMap = buildDistinctColorMap(players || []);
    return list.map(line => {
      const t = line.trim();
      if (!t) return '<div style="height:4px;"></div>';
      const m = t.match(/^(.{1,24}?)[：:]\s*([\s\S]*)$/);
      if (m) {
        const rawName = m[1].replace(/^\d+\s*号位\s*/, '').trim();
        const p = (players || []).find(x => x && x.name && isNameMatch(x.name, rawName));
        if (p) {
          const isUser = !!p.isUser;
          const col = isUser ? '#fff' : (colorMap.get(p.name) || getCharacterColor(p.name) || '');
          if (col) {
            return '<div style="color:' + col + ';margin:4px 0;font-size:12px;font-weight:600;border-left:3px solid ' + (isUser ? 'rgba(255,255,255,0.55)' : charColorAlpha(col, '99')) + ';padding-left:6px;">' + escapeHtml(t) + '</div>';
          }
        }
      }
      return '<div style="color:var(--ubp-text);margin:2px 0;">' + escapeHtml(t) + '</div>';
    }).join('');
  }

  function showRecordDetail(gameType, idx) {
    const list = loadGenericMatchHistory()[gameType] || [];
    const rec = list[idx];
    if (!rec) return;
    const replay = rec.replay || '';
    const ov = document.createElement('div');
    ov.className = 'record-detail-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:70;background:var(--ubp-card);display:flex;flex-direction:column;padding:12px;box-sizing:border-box;';
    const tabs = [
      { key: 'replay', label: '📜 全景复盘' }
    ];
    ov.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex:none;">
        <span style="font-size:15px;font-weight:600;">📜 ${getGameTypeDisplayName(rec.gameType || gameType)} · 对局详情</span>
        <button data-ubp-act="close-record-detail" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--ubp-text);">✕</button>
      </div>
      <div style="flex:none;font-size:12px;color:var(--ubp-text-2);margin-bottom:8px;line-height:1.5;">
        <b style="color:var(--ubp-text);">结果：</b>${escapeHtml(rec.result || '')}
        ${rec.detail ? `<br><b style="color:var(--ubp-text);">详情：</b>${escapeHtml(rec.detail)}` : ''}
        ${(rec.spectators && rec.spectators.length) ? `<br><b style="color:#0EA5E9;">👁️ 观战席：</b>${escapeHtml(rec.spectators.join('、'))}` : ''}
      </div>
      <div class="record-detail-tabs" style="display:flex;gap:6px;margin-bottom:8px;flex:none;overflow-x:auto;">
        ${tabs.map(t => `<button class="record-detail-tab" data-tab="${t.key}" style="flex:none;padding:4px 10px;border-radius:8px;border:1px solid var(--ubp-line);background:var(--ubp-card-2);color:var(--ubp-text);font-size:11.5px;cursor:pointer;white-space:nowrap;">${t.label}</button>`).join('')}
      </div>
      <div id="record-detail-body" style="flex:1;overflow-y:auto;font-size:12px;line-height:1.6;background:var(--ubp-card-2);border-radius:8px;padding:8px;"></div>
    `;
    sheet.appendChild(ov);

    const bodyEl = ov.querySelector('#record-detail-body');
    const tabBtns = ov.querySelectorAll('.record-detail-tab');
    const renderTab = (key) => {
      tabBtns.forEach(b => {
        const on = b.dataset.tab === key;
        b.style.background = on ? 'var(--ubp-accent, #10B981)' : 'var(--ubp-card-2)';
        b.style.color = on ? '#fff' : 'var(--ubp-text)';
        b.style.borderColor = on ? 'transparent' : 'var(--ubp-line)';
      });
      if (rec.replayRich && Array.isArray(rec.replayRich.logs) && rec.replayRich.logs.length) {
        bodyEl.innerHTML = renderReplayRichHTML(rec.replayRich.logs, rec.replayRich.players);
      } else if (isDeductionGame(gameType) && replay) {
        bodyEl.innerHTML = renderReplayTextColored(replay, rec.players || []);
      } else {
        bodyEl.innerHTML = `<div style="white-space:pre-wrap;">${escapeHtml(replay || '（本局暂无回放内容）')}</div>`;
      }
      bodyEl.scrollTop = 0;
    };
    tabBtns.forEach(b => b.addEventListener('click', () => renderTab(b.dataset.tab)));
    renderTab('replay');
  }

