  function renderBoard() {
    const cfg = loadConfig();
    const promptPreview = escapeHtml(getActiveWolfPrompt(cfg).slice(0, 120) + '...');
    const promptModeLabel = cfg.wolfPromptMode === 'fair' ? '⚖️ 绝对公平版' : '🎭 角色人设版';
    const tokenSaveOn = cfg.wolfTokenSave !== false;
    const rpmNow = getWolfRpm();
    const settingsCard = `
      <div style="background:var(--ubp-card-2);border-radius:12px;padding:12px 14px;margin-bottom:12px;border:1px solid var(--ubp-line);">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;">
          <div style="min-width:0;">
            <div style="font-size:13px;font-weight:600;color:var(--ubp-text);">⚙️ 狼人杀设置</div>
            <div style="font-size:11px;color:var(--ubp-text-3);margin-top:2px;line-height:1.5;">提示词：${promptModeLabel}（人设版/公平版两套）· 💾 节约Token：${tokenSaveOn ? '已开启' : '已关闭（RPM=' + rpmNow + '，并发逐条请求）'}</div>
          </div>
          <button data-ubp-act="edit-prompt" class="ubp-btn" style="flex:none;padding:5px 12px;font-size:12px;">打开设置</button>
        </div>
      </div>`;
    const currentBoardSize = cfg.wolfBoardSize || 6;
    const currentBoardTab = (currentBoardSize === 7 || currentBoardSize === 8) ? 9
      : (currentBoardSize === 10 && cfg.wolfBoardVariant === 'hunter10') ? 9
      : currentBoardSize;
    if ([6, 9, 10, 12].indexOf(wolfBoardTab) === -1) wolfBoardTab = currentBoardTab;
    const currentBoardVariant = currentBoardSize === 7 ? 'onecut'
      : currentBoardSize === 8 ? 'ent8'
      : currentBoardSize === 10
      ? ((cfg.wolfBoardVariant === 'wwknight') ? 'wwknight' : (cfg.wolfBoardVariant === 'hunter10' ? 'hunter10' : 'beauty10'))
      : (currentBoardSize === 12 && cfg.wolfBoardVariant === 'wwknight') ? 'wwknight'
      : (currentBoardSize === 6 && cfg.wolfBoardVariant === 'guard6') ? 'guard6'
      : ((cfg.wolfBoardVariant === 'beauty' && currentBoardSize === 12) ? 'beauty' : 'classic');
    const boardSel = (size, variant) => currentBoardSize === size && currentBoardVariant === variant;
