          const name = el.dataset.beautyPick;
          sel = (sel && isNameMatch(sel, name)) ? '' : name;
          renderContent();
        });
      });
      ov.querySelector('[data-beauty-act="close"]')?.addEventListener('click', () => { ov.remove(); renderPositions(); });
      ov.querySelector('[data-beauty-act="confirm"]')?.addEventListener('click', () => {
        game.wolfBeautyTeammateName = sel;
        normalizeIdentityCardState();
        ov.remove();
        renderPositions();
        showToast(sel ? ('💗 已选择 ' + sel + ' 作为狼美人队友') : '已取消狼美人队友');
      });
    };
    renderContent();
    sheet.appendChild(ov);
  }

  // 对局中显示的观战席条
  function renderSpectatorStripHTML() {
