        if (mates.length > 0) {
          myRoleInfo += `\n【你的狼队友】：${mates.map(m => `${m.position}号位 ${m.name}（${m.role}，${m.alive ? '存活' : '已出局'}）`).join('、')}`;
        } else {
          myRoleInfo += `\n【你的狼队友】：无（你是孤狼）`;
        }
        if (player.role === '狼美人') {
