    }).catch(err => {
      if (!isSessionValid(session) || game.phase !== 'vote') return;
      handleAiFailure('警长归票发言', err, (attemptNo || 1), (n) => generateSheriffVoteLead(callback, n), () => {
        addHiddenThought('（归票发言连续5次生成失败，按默认归票处理）', sheriff.position);
        addGameLog('🗣️ [警长归票] ' + sheriff.name + '（' + sheriff.position + '号位）: <speech>请大家看清局势，跟我把票归到最可疑的号位，不要分票。</speech>', true, sheriff.position);
        saveGameRecord();
        if (typeof callback === 'function') callback();
      });
    });
  }

  function startVote() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'vote';
    game.isPkVote = false;
    game.pkCandidates = null;
    game.pickMode = null;
    game.pick = { idx: null };
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 🗳️ 投票`;
    const alive = game.players.filter(p => p.alive);
    if (alive.length <= 1) { endGame(); return; }
    saveGameRecord();
    const continuesVote = () => {
      if (!isSessionValid(session) || game.phase !== 'vote') return;
      // 用户操作后置：先让全部 AI 思考并投票，AI 投完后才轮到用户投票
      if (game.aiVotesDone) { promptUserVoteOrFinish(); return; }
      simulateAIVotes();
    };
    // 有警长时：先请求 AI 警长进行归票思考并发表归票发言，再开始投票
    const leadSheriff = (game.sheriffPos && !game.sheriffBadgeTorn) ? game.players.find(p => p.position === game.sheriffPos) : null;
    if (leadSheriff && leadSheriff.alive && !leadSheriff.isUser && !game.sheriffLeadDone) {
      game.sheriffLeadDone = true;
      saveGameRecord();
      generateSheriffVoteLead(continuesVote);
      return;
    }
    continuesVote();
  }

  function startPkVote() {
    const session = game?.session;
    if (!isSessionValid(session)) return;
    game.phase = 'vote';
    game.isPkVote = true;
    game.pickMode = null;
    game.pick = { idx: null };
    // 进入 PK 决选投票：清空上一轮票型，避免平票玩家上一轮旧票被重复计入
    // （断点恢复：AI 已投完票时不重复清空，保留 AI 的投票结果）
    if (!game.aiVotesDone) game.players.forEach(p => { if (p.alive) p.votedFor = null; });
    const statusEl = sheet?.querySelector('#game-status-text');
    if (statusEl) statusEl.textContent = `🐺 第${game.day}天 · 🗳️ PK投票`;

    const user = game.players[game.userIndex];
    const pkCands = game.pkCandidates || [];
    const isUserTied = user && user.alive && pkCands.some(cp => cp.position === user.position);
    // 除平票玩家外已无任何可投票的存活玩家：直接流票入夜，避免进度卡死
    const eligibleVoters = game.players.filter(p => p.alive && !pkCands.some(cp => cp.position === p.position));
    saveGameRecord();
    if (!eligibleVoters.length) {
      addJudgeLog('⚖️ 场上除平票玩家外已无可投票的存活玩家，本轮直接流票，无人出局。', true);
      setControlArea('');
      finishVote();
      return;
    }
    renderGameUI();
    // 用户操作后置：先让全部 AI 重新思考并投票，AI 投完后才轮到用户
    if (game.aiVotesDone) { promptUserVoteOrFinish(); return; }
    simulateAIVotes();
  }

  // 用户投票（后置）：AI 全部投完后，轮到存活且非平票玩家时弹出用户投票；否则直接结算
  function promptUserVoteOrFinish() {
    const session = game?.session;
    if (!isSessionValid(session) || game.phase !== 'vote') return;
    const user = game.players[game.userIndex];
    const isPk = !!game.isPkVote;
    const pkCands = game.pkCandidates || [];
    const isUserTied = user && user.alive && pkCands.some(cp => cp.position === user.position);
    if (user && user.alive && user.role === '愚者' && user.foolFlipped) {
      addGameLog('🃏 你已翻牌，本局永久失去投票权，本轮无法投票。', false);
      renderGameUI();
      finishVote();
      return;
    }
    if (user && user.alive && !(isPk && isUserTied)) {
      addGameLog(isPk ? '🗳️ PK决选投票：平票玩家不可投票。请点击平票候选人头像进行投票，或选择弃票' : '🗳️ 投票环节：请点击玩家头像选择投票对象（可投自己或点击弃票）', false);
      game.pickMode = 'vote';
      game.pick.idx = null;
      renderGameUI();
      setControlArea('');
      return;
    }
    if (isPk && isUserTied) {
      addGameLog('⚖️ 你作为平票玩家，本轮失去投票权，等待其他玩家投票...', false);
    }
    renderGameUI();
    finishVote();
  }

  // 统一分批规则：排除用户后的名单按人数对半；奇数时前一批多 1 位（同一批并行请求）
  function splitAiBatches(list) {
    const arr = (list || []).slice();
    const half = Math.ceil(arr.length / 2);
    return [arr.slice(0, half), arr.slice(half)];
  }

  // ===== 狼人杀请求调度：按「节约Token」开关选择批量方式 =====
  // 开启（默认）：沿用现有“对半分两批并行”的请求方式，与旧版行为完全一致。
  // 关闭：所有“多名玩家一次性批量思考”的请求改为按 RPM 设置并发上限逐条请求：
  //       例如除用户外 11 人思考上警、RPM=3 时同时只挂 3 个请求，任意 1 人返回后立刻补发第 4 人，始终保证在途请求数=3。
  // 注：夜间行动与发言环节的请求不受影响（仍按原逻辑逐一顺序请求）。
  function getWolfRpm() {
    let n = 3;
    try { n = parseInt(loadConfig().wolfRpm, 10); } catch (e) { /* ignore */ }
    if (!Number.isFinite(n) || n < 1) n = 3;
    return Math.max(1, Math.min(20, n));
  }
  function wolfRunBatch(session, list, worker, onAllDone) {
    const arr = (list || []).slice();
    // 始终回调（各调用方自行校验会话/阶段），保证批量进行中标记能被清除、流程不会被卡死
    const doneAll = () => { if (typeof onAllDone === 'function') onAllDone(); };
    if (!arr.length) { doneAll(); return; }
    let tokenSave = true;
    try { tokenSave = loadConfig().wolfTokenSave !== false; } catch (e) { /* ignore */ }
    if (tokenSave) {
      const waves = splitAiBatches(arr);
      const runWave = (items) => (items && items.length)
        ? Promise.all(items.map(it => Promise.resolve().then(() => worker(it)).catch(() => {})))
        : Promise.resolve();
      runWave(waves[0]).then(() => runWave(waves[1])).then(() => doneAll());
      return;
    }
    const rpm = getWolfRpm();
    let next = 0, active = 0, finished = 0;
    const total = arr.length;
    const pump = () => {
      if (!isSessionValid(session)) return;
      while (active < rpm && next < total) {
        const item = arr[next++];
        active++;
        Promise.resolve().then(() => worker(item)).catch(() => {}).then(() => {
          active--;
          finished++;
          if (finished >= total) doneAll();
          else if (isSessionValid(session)) pump();
        });
      }
    };
    pump();
  }

  // 信息边界铁律（所有狼人杀请求统一附加：只允许使用自己身份与公开信息，严禁开天眼）
  function getInfoBoundaryRule() {
    return `\n${WOLF_INFO_BOUNDARY_TEXT}`;
  }

  // 当前生效的狼人杀提示词（按设置中选定的版本返回）
  function getActiveWolfPrompt(cfg) {
    const c = cfg || loadConfig();
    if (c.wolfPromptMode === 'fair') return c.promptFair || DEFAULT_PROMPT_FAIR;
    return c.prompt || DEFAULT_PROMPT;
  }
  // ========== 警长竞选环节（10/12人场 · 首日白天） ==========
  let sheriffBadgeResolver = null;
  // 批量AI请求进行中标记（仅运行时）：防止界面重入/流程被重复驱动时同一批请求被并发重复发起与重复推进
  const wolfBatchGuard = { signup: false, withdraw: false, sheriffVote: false, dayVote: false, wolfNight: false };
  function resetWolfBatchGuard() {
    wolfBatchGuard.signup = false;
    wolfBatchGuard.withdraw = false;
    wolfBatchGuard.sheriffVote = false;
    wolfBatchGuard.dayVote = false;
    wolfBatchGuard.wolfNight = false;
    sheriffBadgeResolver = null;
  }
  function sheriffAliveVoters() {
    const cands = game.sheriffCandidates || [];
    return game.players.filter(p => p.alive && cands.indexOf(p.position) === -1);
  }
  function sheriffRemainingCandidates() {
    const cands = game.sheriffCandidates || [];
    const out = game.sheriffWithdrawn || [];
    return cands.filter(pos => out.indexOf(pos) === -1);
  }
  // 断点恢复：按警长竞选当前阶段续跑
  function resumeSheriffStage() {
    if (!game) return;
    const stage = game.sheriffStage;
    if (stage === 'signup') {
      // 用户决策后置：先让全部 AI 表态，AI 全部完成后才轮到用户决定是否上警
      askAiSheriffSignups();
    } else if (stage === 'speech') {
      if (game.sheriffSpeechIdx >= (game.sheriffSpeechQueue || []).length) { finishSheriffSpeeches(); return; }
      runNextSheriffSpeaker();
    } else if (stage === 'withdraw') {
      // 用户决策后置：先让全部 AI 退水表态，完成后再轮到用户
      runNextSheriffWithdraw();
    } else if (stage === 'pk') {
      if (game.sheriffPkIdx >= (game.sheriffPkQueue || []).length) { finishSheriffPkSpeeches(); return; }
      runNextSheriffPkSpeaker();
    } else if (stage === 'vote') {
      // 用户投票后置：先让全部 AI 投完警长票，再轮到用户
      askAiSheriffVotes();
    } else {
      beginDaySpeeches();
    }
  }

  function startSheriffElection() {
