    const isPk = !!(rivals && rivals.length);
    const rivalsStr = isPk ? rivals.map(pos => { const t = game.players.find(x => x.position === pos); return t ? (t.position + '号位 ' + t.name) : (pos + '号位'); }).join('、') : '';
    const config = loadConfig();
    const overview = getGamePublicOverview(player);
    const history = getPlayerHistoryContext(player);
