    const reqs = isPk
      ? '\n\n【平票 PK 发言要求】：\n1. 警长选举出现平票：你和【' + rivalsStr + '】票数相同，现在轮到你发表 PK 辩解发言。你必须针对TA的发言与逻辑漏洞进行反驳质疑，同时向其余有投票权的玩家重新拉票。\n2. 必须完全代入角色人设与口癖；狼人上警时要按你的战术（悍跳/冲锋/倒钩）演好戏。\n3. 这只是朋友间狼人杀桌游，严禁真实死亡或流血描写。\n4. 【防全知铁律】只能依据公开信息与自己的底牌发言，严禁开天眼使用任何未公开信息。\n5. 【严格输出格式】只输出两个完整闭合的标签：'
      : '\n\n【竞选发言要求】：\n1. 向全场拉票，说明你为什么适合当警长：可以适度表露身份视角与推理、给出警徽流思路（比如第一验谁、第二验谁）、点出你怀疑的对象。\n2. 必须完全代入角色人设与口癖，结合人际关系；狼人上警时要按你的战术（悍跳/冲锋/倒钩）演好戏。\n3. 这只是朋友间狼人杀桌游，严禁真实死亡或流血描写。\n4. 【防全知铁律】只能依据公开信息与自己的底牌发言，严禁开天眼使用任何未公开信息。\n5. 【严格输出格式】只输出两个完整闭合的标签：';
    const prompt = '你正在第1天白天的警长竞选环节发表' + (isPk ? '平票 PK 辩解' : '竞选') + '发言（' + player.position + '号位 ' + player.name + '）。' + overview + getPlayerIdentitySystemContext(player) + getSheriffSpeechOrderNote() + getInfoBoundaryRule() + '\n\n【场上历史公开发言与公告】：\n' + history + wolfNote + reqs + '\n<thinking>' + (isPk ? 'PK发言的内部思考（怎么反驳对手、怎么重新拉票）' : '竞选发言的内部思考（战术意图、拉票策略、怎么取信于人）') + '</thinking>\n<speech>真正说出口的完整' + (isPk ? 'PK辩解' : '竞选') + '发言（语义完整、自然收尾，严禁半句截断）</speech>';
    apiChat([
      { role: 'system', content: applyBoardIntro(getActiveWolfPrompt(config)) },
      { role: 'user', content: prompt }
    ], config, { maxTokens: 3000, timeout: 70000 }).then(res => {
      if (!isSessionValid(session) || (isPk ? game.sheriffStage !== 'pk' : game.sheriffStage !== 'speech')) return;
      const parsedSp = parseWolfSpeechResponse(res);
      let thought = parsedSp.thought;
      let speech = completeWolfSpeechLine(parsedSp.speech, 'day');
      if (!speech) speech = isPk ? '我和TA票数相同，我重申我的逻辑与身份，请把警长票投给我。' : '我上警竞选警长，我会认真梳理场上逻辑，带好人找狼，请大家投我一票。';
      if (!thought) thought = isPk ? '平票PK中必须反驳对手并重新争取票数。' : '我上警是为了争夺警徽与1.5票归票权，必须用发言争取大家的信任。';
      addHiddenThought(thought, player.position);
      addGameLog('🗣️ [' + (isPk ? 'PK发言' : '竞选发言') + '] ' + player.name + '（' + player.position + '号位）: <speech>' + speech + '</speech>', true, player.position);
      saveGameRecord();
