    }).catch(err => {
      if (!isSessionValid(session)) return;
      handleAiFailure((isPk ? 'PK发言' : '竞选发言') + '生成', err, (attemptNo || 1), (n) => generateSheriffSpeech(player, callback, rivals, n), () => {
        const fb = isPk ? '我和TA票数相同，我重申我的逻辑与身份，请把警长票投给我。' : '我上警竞选警长，请大家观察我的发言，把警长票投给我。';
        addGameLog('🗣️ [' + (isPk ? 'PK发言' : '竞选发言') + '] ' + player.name + '（' + player.position + '号位）: <speech>' + fb + '</speech>', true, player.position);
        if (isPk) { game.sheriffPkIdx = (game.sheriffPkIdx || 0) + 1; saveGameRecord(); runNextSheriffPkSpeaker(); }
        else { game.sheriffSpeechIdx = (game.sheriffSpeechIdx || 0) + 1; saveGameRecord(); runNextSheriffSpeaker(); }
