    });
  }

  // 警长竞选平票：平票角色依次 PK 发言，之后其余玩家重新思考投票
  function runNextSheriffPkSpeaker() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'pk') return;
    if (game.knightManualDuel) return;
    const q = game.sheriffPkQueue || [];
    if (game.sheriffPkIdx >= q.length) { finishSheriffPkSpeeches(); return; }
    const pos = q[game.sheriffPkIdx];
    const cand = game.players.find(p => p.position === pos);
    if (!cand || !cand.alive) { game.sheriffPkIdx++; runNextSheriffPkSpeaker(); return; }
    if (cand.isUser) {
      addGameLog('🚨 轮到你发表平票 PK 发言（针对其他平票候选人反驳并重新拉票）：', false);
      setControlArea('<div id="sheriff-pk-area" style="display:flex;gap:4px;margin:6px 0;"><input id="sheriff-pk-input" class="ubp-fieldinput" type="text" placeholder="输入你的PK发言..." style="flex:1;min-width:0;"><button data-ubp-act="sheriff-pk-speak" class="ubp-btn primary" style="padding:0 10px;">发言</button><button data-ubp-act="sheriff-pk-speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button></div>');
      const input = sheet && sheet.querySelector('#sheriff-pk-input');
      if (input) input.focus();
      return;
    }
    setControlArea('<div style="text-align:center;padding:6px;color:#fff;">' + cand.name + ' 正在准备平票 PK 发言...</div>');
    const myIdx = game.sheriffPkIdx;
    generateSheriffSpeech(cand, () => {
      if (!isSessionValid(session) || game.sheriffStage !== 'pk') return;
      if (game.sheriffPkIdx !== myIdx) return; // 防重复/过期回调导致跳过下一位
      game.sheriffPkIdx = (game.sheriffPkIdx || 0) + 1;
      saveGameRecord();
      runNextSheriffPkSpeaker();
    }, (game.sheriffPkCandidates || []).filter(p2 => p2 !== pos));
  }
  function finishSheriffPkSpeeches() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'pk') return;
    if (game.knightManualDuel) return;
    setControlArea('');
    game.sheriffStage = 'vote';
    game.sheriffVotes = {};
    game.sheriffUserVoted = 0;
    game.sheriffVotedDecided = [];
    game.sheriffVotesRevealed = false;
    game.sheriffVoteLines = [];
    const voters = sheriffAliveVoters();
    game.sheriffVoterQueue = voters.filter(p => !p.isUser).map(p => p.position);
    game.sheriffVoterIdx = 0;
    addGameLog('🚨 平票 PK 发言结束，请其余玩家结合PK发言【重新思考】投谁当警长（只能投平票候选人）。', true);
    saveGameRecord();
    renderGameUI();
    // 用户投票后置：先让全部 AI 重新投票，完成后再轮到用户
    askAiSheriffVotes();
  }

  function runNextSheriffSpeaker() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'speech') return;
    if (game.knightManualDuel) return;
    const q = game.sheriffSpeechQueue || [];
    if (game.sheriffSpeechIdx >= q.length) { finishSheriffSpeeches(); return; }
    const pos = q[game.sheriffSpeechIdx];
    const cand = game.players.find(p => p.position === pos);
    if (!cand || !cand.alive) { game.sheriffSpeechIdx++; runNextSheriffSpeaker(); return; }
    if (cand.isUser) {
      addGameLog('🗣️ 轮到你发表竞选发言：', false);
      setControlArea('<div id="sheriff-speak-area" style="display:flex;gap:4px;margin:6px 0;"><input id="sheriff-speak-input" class="ubp-fieldinput" type="text" placeholder="输入你的竞选发言..." style="flex:1;min-width:0;"><button data-ubp-act="sheriff-speak" class="ubp-btn primary" style="padding:0 10px;">发言</button><button data-ubp-act="sheriff-speak-skip" class="ubp-btn" style="padding:0 10px;">跳过</button></div>');
      const input = sheet && sheet.querySelector('#sheriff-speak-input');
      if (input) input.focus();
      return;
