    const myIdx = game.sheriffSpeechIdx;
    generateSheriffSpeech(cand, () => {
      if (!isSessionValid(session) || game.sheriffStage !== 'speech') return;
      if (game.sheriffSpeechIdx !== myIdx) return; // 防重复/过期回调导致跳过下一位
      game.sheriffSpeechIdx++;
      saveGameRecord();
      runNextSheriffSpeaker();
    });
  }
  function finishSheriffSpeeches() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'speech') return;
    if (game.knightPromptActive) return;
    if (game.knightManualDuel) return;
    if (!game.knightSheriffPromptDone) {
      const knight = game.players.find(p => p.role === '骑士');
      if (knight && knight.alive && !game.knightDuelUsed) {
        maybeStartKnightPrompt('sheriff', () => completeKnightPrompt('sheriff'));
        return;
      }
    }
    game.knightSheriffPromptDone = true;
    proceedFinishSheriffSpeeches();
  }

  function proceedFinishSheriffSpeeches() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'speech') return;
    game.knightPromptActive = false;
    game.knightPromptContext = '';
    game.knightPromptIsAi = false;
    setControlArea('');
    game.sheriffStage = 'withdraw';
    game.sheriffWithdrawQueue = (game.sheriffCandidates || []).slice();
    game.sheriffWithdrawIdx = 0;
    game.sheriffWithdrawnDecided = [];
    game.sheriffUserWithdrawDecided = false;
    addJudgeLog('🚨 竞选发言结束。上警玩家开始思考是否退水（退水玩家不再参与警长角逐且失去警长选举投票权）。', true);
    saveGameRecord();
    renderGameUI();
    // 用户决策后置：先让全部 AI 上警玩家思考退水，完成后再轮到用户决定
    runNextSheriffWithdraw();
  }

  function runNextSheriffWithdraw() {
    const session = game?.session;
    if (!isSessionValid(session) || game.sheriffStage !== 'withdraw') return;
    if (wolfBatchGuard.withdraw) return; // 该批AI请求已在途，防止重复发起
    const done = game.sheriffWithdrawnDecided || (game.sheriffWithdrawnDecided = []);
