  function aiSheriffBadgeDecide(session, dead, attemptNo, reason = 'death') {
    return new Promise(resolve => {
      try {
        const alive = game.players.filter(p => p.alive && p.position !== dead.position);
        if (!alive.length) { resolve({ tear: true }); return; }
        const config = loadConfig();
        const overview = getGamePublicOverview(dead);
        const history = getPlayerHistoryContext(dead);
        const targetList = alive.map(p => p.position + '号位(' + p.name + (p.isUser ? '，主角本人' : '') + ')').join('、');
        setControlArea('<div style="text-align:center;padding:6px;color:#fff;">🎖️ ' + dead.name + ' 正在思考把警徽移交给谁...</div>');
        const reasonIntro = reason === 'fool'
          ? '你作为愚者警长刚刚被公投放逐并翻牌，技能让你留在场上；现在决定把警徽移交给一名存活玩家，或者放弃警徽（本局不再有警长）。'
          : reason === 'wwk'
            ? '你作为白狼王警长刚刚主动自爆出局；现在决定把警徽移交给一名存活玩家，或者撕毁警徽（本局不再有警长）。'
            : reason === 'wwkTarget'
              ? '你作为警长刚刚被白狼王自爆带走出局；现在决定把警徽移交给一名存活玩家，或者撕毁警徽（本局不再有警长）。'
              : '你作为警长刚刚出局；现在决定把警徽移交给一名存活玩家，或者撕毁警徽（本局不再有警长）。';
        const prompt = reasonIntro + overview + getPlayerIdentitySystemContext(dead) + getInfoBoundaryRule() + '\n\n【场上历史公开发言与公告】：\n' + history + '\n\n可移交对象：' + targetList + '\n\n【警徽移交决策指引】：\n1. 优先把警徽交给最可信、最能让你的阵营获益的存活玩家（好人交给明好/强神职；狼人交给狼队友或伪装好的同伴）。\n2. 若你认为场上无人可信、警徽会被狼人夺走，也可以选择撕毁警徽。\n3. 【严禁开天眼】只能依据自己的底牌与公开信息推理。\n4. 在<thinking>中输出完整思考，然后按格式输出：GIVE: [号位] 表示移交；TEAR 表示撕毁。\n\n输出格式必须为：\n<thinking>警徽去向思考...</thinking>\n<SHERIFF_BADGE>\nSHERIFF_BADGE: [GIVE: 号位 或 TEAR]\n</SHERIFF_BADGE>';
        apiChat([
          { role: 'system', content: '你是狼人杀警长，正在决定警徽去向。必须代入角色人设与底牌立场思考，严格输出思考与警徽格式。' },
          { role: 'user', content: prompt }
        ], config, { maxTokens: 3000 }).then(res => {
          if (!isSessionValid(session)) { resolve(null); return; }
          const parsedB = parseWolfSpeechResponse(res);
          if (parsedB.thought) addHiddenThought(parsedB.thought, dead.position);
          const text = String(res || '');
          const mTear = /SHERIFF_BADGE[：:]?[\s\S]*?TEAR/i.test(text);
          const mGive = text.match(/GIVE[：:]?\s*[\[【（(]?\s*(\d{1,2}|[一二三四五六七八九十]{1,3})/i);
          let decision = null;
          if (mGive && mGive[1]) {
            const pos = wolfPosFromStr(mGive[1]);
            const t = game.players.find(p => p.position === pos && p.alive);
            if (t) decision = { pos: t.position };
          }
          if (!decision && !mTear) {
            const rnd = alive[Math.floor(Math.random() * alive.length)];
            decision = { pos: rnd.position };
          }
          if (!decision) decision = { tear: true };
          setControlArea('');
          resolve(decision);
        }).catch(err => {
          setControlArea('');
          const fallback = () => {
            try {
              const alive2 = game.players.filter(p => p.alive);
              resolve(alive2.length ? { pos: alive2[Math.floor(Math.random() * alive2.length)].position } : { tear: true });
            } catch (e) { resolve({ tear: true }); }
          };
          if (!isSessionValid(session)) { resolve(null); return; }
          handleAiFailure('AI警徽去向思考', err, (attemptNo || 1), (n) => { aiSheriffBadgeDecide(session, dead, n, reason).then(resolve); }, fallback);
        });
      } catch (e) { resolve(null); }
    });
  }
