      aiSmoke: e.aiSmoke,
      aiJammer: e.aiJammer,
      playerJammer: e.playerJammer,
      log: e.log
    };
  }

  function bsHydrateBattleship(e, s) {
    if (!s) return;
    e.phase = s.phase || 'setup';
    e.playerBoard = s.playerBoard || e.playerBoard;
    e.aiBoard = s.aiBoard || e.aiBoard;
    e.playerShips = s.playerShips || [];
    e.aiShips = s.aiShips || [];
    e.playerAttacks = s.playerAttacks || e.playerAttacks;
    e.aiAttacks = s.aiAttacks || e.aiAttacks;
    e.aiSunkCells = s.aiSunkCells || {};
    e.aiSunkSizes = s.aiSunkSizes || [];
    e.playerBlocked = s.playerBlocked || e.playerBlocked;
    e.aiBlocked = s.aiBlocked || e.aiBlocked;
    e.playerRemain = s.playerRemain || e.playerRemain;
    e.aiRemain = s.aiRemain || e.aiRemain;
    e.playerSkills = s.playerSkills || [];
    e.aiSkills = s.aiSkills || [];
    e.playerSkillUsed = s.playerSkillUsed || {};
    e.aiSkillUsed = s.aiSkillUsed || {};
