      <div style="display:flex;justify-content:space-between;align-items:center;padding-top:6px;border-top:1px solid var(--ubp-line);flex-none;">
        <div style="font-size:12px;color:var(--ubp-text-2);">已选 <span id="spy-invite-count" style="color:#F59E0B;font-weight:bold;">0</span> / ${max}<span style="color:var(--ubp-text-3);">（不足时开局由内置角色补位）</span></div>
        <button data-spy-act="confirm-invite" class="ubp-btn primary" style="padding:6px 18px;font-size:13px;border-radius:6px;min-width:96px;background:#F59E0B;border:none;" disabled>确认邀请</button>
