  function renderSpyPositions() {
    if (!spyGame) return;
    const left = spyGame.players.slice(0, 3);
    const right = spyGame.players.slice(3, 6);

    const renderLeftPositionPlayer = (p) => {
      const avatar = p.avatar || (p.isUser ? getMainCharAvatar() : getCharacterAvatarByName(p.name));
