        <button data-ddz-act="ddz-start" class="ubp-btn primary" style="width:100%;padding:12px;font-size:14px;background:#DC2626;border:none;margin-bottom:12px;">${pn.length === 2 ? '🎮 开始对局（' + escapeHtml(pn[0]) + ' · ' + escapeHtml(pn[1]) + '）' : '🎮 开始对局（未邀请将自动补位）'}</button>

