              ${av ? `<img src="${av}" style="width:100%;height:100%;object-fit:cover;">` : `<span style="display:flex;width:100%;height:100%;align-items:center;justify-content:center;color:#fff;font-weight:bold;font-size:15px;">${escapeHtml(c.name.slice(0, 1))}</span>`}
            </div>
            <div style="flex:1;min-width:0;">
              <div style="font-size:13.5px;font-weight:600;color:var(--ubp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(c.name)} ${isSelected ? `<span style="font-size:11px;color:#DC2626;">(${idx === 0 ? '座位1' : '座位2'})</span>` : ''}</div>
