    dirA.addEventListener('click', () => { direction = 'target_is_owner'; syncDir(); });
    dirB.addEventListener('click', () => { direction = 'owner_is_target'; syncDir(); });
    syncDir();
    ov.querySelectorAll('.rel-type-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        selType = (selType === btn.dataset.type) ? '' : btn.dataset.type;
        ov.querySelectorAll('.rel-type-btn').forEach(b => {
