    ov.querySelector('#rel-target').addEventListener('change', refreshPreview);
    ov.querySelector('#rel-custom').addEventListener('input', refreshPreview);
    ov.querySelector('#rel-cancel').addEventListener('click', () => ov.remove());
    ov.addEventListener('click', (e) => { if (e.target === ov) ov.remove(); });
    ov.querySelector('#rel-save').addEventListener('click', () => {
      const target = (ov.querySelector('#rel-target')?.value || '').trim();
      const custom = (ov.querySelector('#rel-custom')?.value || '').trim();
      const state = (ov.querySelector('#rel-state')?.value || '').trim();
      const type = custom || selType;
      if (!target) { showToast('⚠️ 请选择关系对象'); return; }
      if (!type) { showToast('⚠️ 请选择分类快捷类型或填写自定义关系'); return; }
      const a = direction === 'target_is_owner' ? ownerName : target;
      const b = direction === 'target_is_owner' ? target : ownerName;
      if (!addCustomRelation(a, b, type, state)) { showToast('⚠️ 相同的关系已存在，无需重复添加'); return; }
      ov.remove();
      showToast('✅ 已添加关系：' + relationTextForName({ a: a, b: b, type: type, state: state }, ownerName));
      if (typeof onSaved === 'function') onSaved(ownerName);
    });
    sheet.appendChild(ov);
