    g.phase = 'play';
    g.cards = gen.cards;
    g.towers = gen.towers;
    g.gridCols = gen.cols;
    g.gridRows = gen.rows;
    g.slot = [];
    g.history = [];
    g.items = { move: 1, undo: 1, shuffle: 1 };
    g.reviveUsed = false;
    g.banner = { text: '第 ' + L + ' 关', sub: L === 1 ? '新手关：点掉没被压住的牌，凑 3 张相同自动消除' : '多层堆叠 · 共 ' + gen.total + ' 张 · 每种图案数量都是 3 的倍数', t: 1.8 };
    g.parts = [];
    g.floats = [];
    yangFillClouds(g);
    g.cardMap = {};
    for (const c of g.cards) g.cardMap[c.id] = c;
  }

  // ---- 遮挡与点击 ----
  function yangTopCard(g, cell) {
    let top = null;
    for (const c of g.cards) {
      if (c.st === 'field' && c.cell === cell && (!top || c.layer > top.layer)) top = c;
    }
    return top;
  }
  function yangClickable(g, card) {
    return !!card && card.st === 'field' && yangTopCard(g, card.cell) === card;
  }
  function yangFieldCount(g) {
    let n = 0;
    for (const c of g.cards) if (c.st === 'field') n += 1;
    return n;
  }
  function yangLiveCount(g) {
    let n = 0;
    for (const c of g.cards) if (c.st !== 'gone') n += 1;
    return n;
  }
  function yangSlotPatCounts(g) {
    const m = {};
    for (const id of g.slot) {
      const c = g.cardMap[id];
      if (c) m[c.pat] = (m[c.pat] || 0) + 1;
    }
    return m;
  }
  function yangSlotHasTriple(g) {
    const m = yangSlotPatCounts(g);
    for (const k in m) if (m[k] >= 3) return true;
    return false;
  }
  function yangCheckTriples(g) {
    const m = yangSlotPatCounts(g);
    for (const pat in m) {
      if (m[pat] < 3) continue;
      const ids = [];
      for (const id of g.slot) {
        const c = g.cardMap[id];
        if (c && c.pat === pat) ids.push(id);
        if (ids.length === 3) break;
      }
      for (const id of ids) {
        const c = g.cardMap[id];
        if (c) c.st = 'gone';
        const si = g.slot.indexOf(id);
        if (si >= 0) g.slot.splice(si, 1);
        for (const h of g.history) if (h.id === id) h.cleared = true;
      }
      gfxFloat(g, g.W / 2, g.H - 96, '✨ ' + pat + ' ×3 消除！', '#FDE047', 1.25);
      gfxBurst(g, g.W / 2, g.H - 74, '#FDE047', 14);
      g.shake = Math.min(5, g.shake + 2);
    }
  }
  function yangReturnToField(g, card) {
    let maxLayer = -1;
    for (const c of g.cards) {
      if (c.st === 'field' && c.cell === card.cell && c.layer > maxLayer) maxLayer = c.layer;
    }
    card.layer = maxLayer + 1;
    card.st = 'field';
  }
  function yangPostMove(g) {
    if (g.phase !== 'play') return;
    if (yangFieldCount(g) === 0 && g.slot.length === 0) { yangClear(g); return; }
    if (yangFieldCount(g) === 0) { yangFail(g, '场上已经没有可点的牌了，卡槽里还压着 ' + g.slot.length + ' 张……'); return; }
    if (g.slot.length >= YANG_SLOT_CAP && !yangSlotHasTriple(g)) { yangFail(g, '卡槽 7 格全满，凑不出 3 张相同图案！'); return; }
  }
  function yangClickCard(g, card) {
    if (!g || g.phase !== 'play' || !yangClickable(g, card)) return;
    card.st = 'slot';
    g.slot.push(card.id);
    g.history.push({ id: card.id, cleared: false });
    const layout = yangLayout(g);
    const p = yangTowerXY(g, card.cell, layout);
    gfxBurst(g, p.x + Math.min(card.layer, 9) * 2, p.y - Math.min(card.layer, 9) * 2, '#FDE047', 6);
    yangCheckTriples(g);
    yangUpdateHud(g);
    yangPostMove(g);
  }

  // ---- 道具与复活（每局各 1 次） ----
  function yangItemMove() {
    const g = yangGame;
    if (!g || g.phase !== 'play') return;
    if (g.items.move <= 0) { showToast('📤 移出道具本局已经用过了'); return; }
    if (g.slot.length === 0) { showToast('卡槽是空的，暂时不用移出'); return; }
    g.items.move -= 1;
    const pick = yangShuffle(g.slot.slice());
    const n = Math.min(3, pick.length);
    const layout = yangLayout(g);
    for (let i = 0; i < n; i++) {
      const id = pick[i];
      const c = g.cardMap[id];
      if (!c) continue;
      const si = g.slot.indexOf(id);
      if (si >= 0) g.slot.splice(si, 1);
      yangReturnToField(g, c);
      const p = yangTowerXY(g, c.cell, layout);
      gfxBurst(g, p.x, p.y - c.layer * 2, '#38BDF8', 8);
    }
    g.history = g.history.filter(h => g.slot.indexOf(h.id) >= 0);
    showToast('📤 已移出 ' + n + ' 张回场上');
    gfxFloat(g, g.W / 2, g.H - 96, '📤 移出 ' + n + ' 张', '#38BDF8', 1.2);
    yangUpdateHud(g);
    yangPostMove(g);
  }
  function yangItemUndo() {
    const g = yangGame;
    if (!g || g.phase !== 'play') return;
    if (g.items.undo <= 0) { showToast('↩️ 撤回道具本局已经用过了'); return; }
    const last = g.history[g.history.length - 1];
    if (!last || last.cleared || g.slot.indexOf(last.id) < 0) { showToast('↩️ 上一步无法撤回（已经三消或不在卡槽里）'); return; }
    const c = g.cardMap[last.id];
    if (!c || c.st !== 'slot') { showToast('↩️ 上一步无法撤回'); return; }
    g.items.undo -= 1;
    const si = g.slot.indexOf(last.id);
    if (si >= 0) g.slot.splice(si, 1);
    yangReturnToField(g, c);
    g.history.pop();
    const layout = yangLayout(g);
    const p = yangTowerXY(g, c.cell, layout);
    gfxBurst(g, p.x, p.y - c.layer * 2, '#A78BFA', 10);
    gfxFloat(g, p.x, p.y - 30, '↩️ 已撤回', '#A78BFA', 1.1);
    showToast('↩️ 已撤回上一张');
    yangUpdateHud(g);
  }
  function yangItemShuffle() {
    const g = yangGame;
    if (!g || g.phase !== 'play') return;
    if (g.items.shuffle <= 0) { showToast('🔀 洗牌道具本局已经用过了'); return; }
    const fields = g.cards.filter(c => c.st === 'field');
    if (fields.length < 2) { showToast('场上牌太少，不用洗牌啦'); return; }
    g.items.shuffle -= 1;
    const tuples = fields.map(c => ({ cell: c.cell, layer: c.layer }));
    yangShuffle(tuples);
    for (let i = 0; i < fields.length; i++) {
      fields[i].cell = tuples[i].cell;
      fields[i].layer = tuples[i].layer;
    }
    const layout = yangLayout(g);
    for (const c of fields) {
      const p = yangTowerXY(g, c.cell, layout);
      gfxBurst(g, p.x, p.y, '#22D3EE', 3);
    }
    gfxFloat(g, g.W / 2, g.H * 0.4, '🔀 洗牌完成！', '#22D3EE', 1.4);
    showToast('🔀 场上卡牌已重新打乱');
    yangUpdateHud(g);
  }
  function yangRevive() {
    const g = yangGame;
    if (!g || g.phase !== 'over') return;
    if (g.reviveUsed) { showToast('🐑 本局复活次数已经用过了'); return; }
    g.reviveUsed = true;
    const ids = g.slot.slice();
    g.slot = [];
    for (const id of ids) {
      const c = g.cardMap[id];
      if (c && c.st === 'slot') yangReturnToField(g, c);
    }
    g.history = [];
    g.phase = 'play';
    const stage = sheet ? sheet.querySelector('#yang-stage') : null;
    if (stage) stage.querySelectorAll('.yang-overlay').forEach(el => el.remove());
    g.banner = { text: '🐑 复活！', sub: '卡槽已清空，卡牌全部放回场上', t: 1.6 };
    showToast('🐑 复活成功，继续加油！');
    yangUpdateHud(g);
  }

  // ---- 通关 / 失败 ----
  function yangClear(g) {
    if (g.phase === 'cleared' || g.phase === 'over') return;
    g.phase = 'cleared';
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('羊了个羊'); } } catch (e) { /* ignore */ }
    const perfect = !g.reviveUsed && g.items.move === 1 && g.items.undo === 1 && g.items.shuffle === 1;
    const gain = perfect ? 2 : 1;
    g.pointsEarned += gain;
    addPoints(gain);
    yangSaveBest(g.level);
    yangClearSave();
    const pl = sheet ? sheet.querySelector('#yang-points-label') : null;
    if (pl) pl.innerHTML = pointsLabelHTML();
    const bl = sheet ? sheet.querySelector('#yang-best-label') : null;
    if (bl) bl.textContent = '🏆 最高第 ' + yangBest() + ' 关';
    gfxStagePanel('#yang-stage', 'yang-overlay', `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #22C55E;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">${perfect ? '🏆' : '🎉'}</div>
        <div style="font-size:15.5px;font-weight:700;color:#22C55E;margin-bottom:8px;">第 ${g.level} 关 全清！${perfect ? '（完美）' : ''}</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          场上 ${g.cards.length} 张卡牌全部消除<br>
          ${perfect ? '<b style="color:#F59E0B;">✨ 完美通关（没用道具也没复活）：积分 +2</b>' : '通关积分 <b style="color:#F59E0B;">+1</b>（不用道具、不复活可以拿 +2 哦）'}<br>
          本局累计积分：<b style="color:#F59E0B;">+${g.pointsEarned}</b>（当前 💎 ${loadPoints()}）
        </div>
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="yang-next" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#22C55E;border:none;color:#fff;border-radius:10px;cursor:pointer;">🐑 下一关</button>
          <button data-ubp-act="yang-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">下一关卡牌更多、堆得更深（每种图案仍是 3 的倍数）· 点返回大厅会保存「第 ${g.level + 1} 关」进度</div>
      </div>
    `);
  }
  function yangFail(g, reason) {
    if (g.phase === 'cleared' || g.phase === 'over') return;
    g.phase = 'over';
    try { if (!g.__slotChanceGranted) { g.__slotChanceGranted = true; grantSlotChance('羊了个羊'); } } catch (e) { /* ignore */ }
    yangClearSave();
    gfxBurst(g, g.W / 2, g.H / 2, '#F87171', 24);
    gfxStagePanel('#yang-stage', 'yang-overlay', `
      <div style="background:var(--ubp-card, #1c1c20);border:1.5px solid #EF4444;border-radius:14px;padding:20px 16px;width:100%;max-width:280px;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,0.6);">
        <div style="font-size:38px;margin-bottom:4px;">💀</div>
        <div style="font-size:15.5px;font-weight:700;color:#F87171;margin-bottom:8px;">羊群炸了！</div>
        <div style="font-size:13px;color:var(--ubp-text);line-height:1.9;margin-bottom:12px;">
          ${reason}<br>
          到达：第 <b style="color:#FDE047;">${g.level}</b> 关 · 还剩 <b style="color:#F87171;">${yangLiveCount(g)}</b> 张没消<br>
          本局积分奖励：<b style="color:#F59E0B;">+${g.pointsEarned}</b>（当前 💎 ${loadPoints()}）<br>
          最高纪录：第 <b style="color:#F59E0B;">${yangBest()}</b> 关
        </div>
        ${g.reviveUsed
          ? '<div style="font-size:10.5px;color:var(--ubp-text-3);margin-bottom:8px;">本局复活机会已经用过了</div>'
          : '<button data-ubp-act="yang-revive" class="ubp-btn primary" style="width:100%;padding:10px 0;font-size:13px;font-weight:700;background:#0E7490;border:none;color:#fff;border-radius:10px;cursor:pointer;margin-bottom:8px;">🐑 复活一次（卡槽的牌放回场上，继续玩）</button>'}
        <div style="display:flex;gap:8px;">
          <button data-ubp-act="yang-restart" class="ubp-btn primary" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;background:#EF4444;border:none;color:#fff;border-radius:10px;cursor:pointer;">🔄 再来一局</button>
          <button data-ubp-act="yang-exit" class="ubp-btn" style="flex:1;padding:10px 0;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;">🏠 返回大厅</button>
        </div>
        <div style="font-size:10.5px;color:var(--ubp-text-3);margin-top:10px;">提示：先看一眼每个牌堆的「顶牌」，排队贪多容易把卡槽塞爆</div>
      </div>
    `);
  }

  // ---- 存档 / 恢复 ----
  function yangSaveGame(g) {
    try {
      if (!g || g.phase !== 'play') return false;
      localStorage.setItem(YANG_SAVE_KEY, JSON.stringify({
        v: 1, mode: 'run',
        level: g.level,
        cards: g.cards.map(c => ({ id: c.id, pat: c.pat, cell: c.cell, layer: c.layer, st: c.st })),
        slot: g.slot.slice(),
        history: g.history.map(h => ({ id: h.id, cleared: !!h.cleared })),
        items: { move: g.items.move, undo: g.items.undo, shuffle: g.items.shuffle },
        reviveUsed: !!g.reviveUsed,
        pointsEarned: g.pointsEarned,
        towers: g.towers
      }));
      return true;
    } catch (e) { return false; }
  }
  function yangSaveCheckpoint(g) {
    try {
      localStorage.setItem(YANG_SAVE_KEY, JSON.stringify({ v: 1, mode: 'checkpoint', level: g.level + 1, pointsEarned: g.pointsEarned }));
      return true;
    } catch (e) { return false; }
  }
  function yangResumeGame() {
    let data = null;
    try { const raw = localStorage.getItem(YANG_SAVE_KEY); data = raw ? JSON.parse(raw) : null; } catch (e) { data = null; }
    if (!data || !data.v) { yangOpenGame(null); return; }
    yangOpenGame(data);
    if (data.mode === 'checkpoint') showToast('🔖 已恢复进度：从第 ' + (data.level || 1) + ' 关继续');
    else showToast('🔖 已恢复进度：第 ' + (data.level || 1) + ' 关');
  }
  function yangNormalizeCards(arr) {
    if (!Array.isArray(arr) || arr.length < 3 || arr.length > 300) return null;
    const out = [];
    const usedOid = {};
    for (const c of arr) {
      if (!c || typeof c !== 'object') return null;
      const pat = YANG_POOL.indexOf(c.pat) >= 0 ? c.pat : YANG_POOL[0];
      const cell = Math.round(gfxNum(c.cell, 0, 0, 29));
      const layer = Math.round(gfxNum(c.layer, 0, 0, 40));
      const st = (c.st === 'slot' || c.st === 'gone') ? c.st : 'field';
      const oid = Math.round(gfxNum(c.id, out.length + 1, 0, 1e9));
      let uid = oid;
      while (usedOid[uid]) uid += 1;
      usedOid[uid] = 1;
      out.push({ oid: uid, pat: pat, cell: cell, layer: layer, st: st });
    }
    return out;
  }
  function yangRestoreRun(g, saveData) {
    try {
      const level = Math.round(gfxNum(saveData.level, 1, 1, 9999));
      const norm = yangNormalizeCards(saveData.cards);
      if (!norm) return false;
      const tws = [];
      if (Array.isArray(saveData.towers)) {
        for (const t of saveData.towers.slice(0, 30)) {
          if (!t || typeof t !== 'object') return false;
          tws.push({ col: Math.round(gfxNum(t.col, 0, 0, 4)), row: Math.round(gfxNum(t.row, 0, 0, 8)) });
        }
      }
      if (tws.length < 1) return false;
      for (const c of norm) if (c.cell >= tws.length) return false;
      const cols = tws.reduce((m, t) => Math.max(m, t.col + 1), 1);
      const rows = tws.reduce((m, t) => Math.max(m, t.row + 1), 1);
      const idMap = {};
      norm.forEach((c, i) => { idMap[c.oid] = i + 1; });
      const slot = [];
      const savedSlot = Array.isArray(saveData.slot) ? saveData.slot : [];
      for (const sid of savedSlot) {
        const nid = idMap[Math.round(gfxNum(sid, 0, 0, 1e9))];
        if (nid === undefined) continue;
        if (slot.indexOf(nid) >= 0) continue;
        if (norm[nid - 1].st !== 'slot') continue;
        slot.push(nid);
        if (slot.length >= YANG_SLOT_CAP) break;
      }
      const cards = [];
      const used = {};
      for (let i = 0; i < norm.length; i++) {
        const c = norm[i];
        let st = c.st;
        if (st === 'slot' && slot.indexOf(i + 1) < 0) st = 'field';
        let layer = c.layer;
        if (st === 'field') {
          let key = c.cell + ':' + layer;
          let guard = 0;
          while (used[key] && guard++ < 60) { layer += 1; key = c.cell + ':' + layer; }
          used[key] = 1;
        }
        cards.push({ id: i + 1, pat: c.pat, cell: c.cell, layer: layer, st: st });
      }
      if (!cards.some(c => c.st === 'field')) return false; // 场上无牌可点的「进行中」存档异常 → 交由上层重开该关
      const history = [];
      if (Array.isArray(saveData.history)) {
        for (const h of saveData.history.slice(0, 300)) {
          if (!h || typeof h !== 'object') continue;
          const nid = idMap[Math.round(gfxNum(h.id, 0, 0, 1e9))];
          if (nid === undefined) continue;
          if (slot.indexOf(nid) < 0) continue;
          history.push({ id: nid, cleared: !!h.cleared });
        }
      }
      const it = saveData.items && typeof saveData.items === 'object' ? saveData.items : {};
      g.items = {
        move: Math.round(gfxNum(it.move, 1, 0, 1)),
        undo: Math.round(gfxNum(it.undo, 1, 0, 1)),
        shuffle: Math.round(gfxNum(it.shuffle, 1, 0, 1))
      };
      g.reviveUsed = !!saveData.reviveUsed;
      g.level = level;
      g.phase = 'play';
      g.cards = cards;
      g.towers = tws;
      g.gridCols = cols;
      g.gridRows = rows;
      g.slot = slot;
      g.history = history;
      g.cardMap = {};
      for (const c of cards) g.cardMap[c.id] = c;
      g.banner = { text: '第 ' + level + ' 关', sub: '继续消除！还剩 ' + yangLiveCount(g) + ' 张', t: 1.2 };
      yangFillClouds(g);
      return true;
    } catch (e) { return false; }
  }

  // ---- 开局 / 退出 ----
  function yangOpenGame(saveData) {
    if (yangGame) yangTeardown();
    if (!sheet) { renderAdGameLobby(); return; }
    const g = {
      level: 1, phase: 'play',
      cards: [], towers: [], gridCols: 3, gridRows: 2,
      slot: [], cardMap: {}, history: [],
      items: { move: 1, undo: 1, shuffle: 1 }, reviveUsed: false,
      pointsEarned: 0,
      banner: { text: '', sub: '', t: 0 }, time: 0, shake: 0,
      parts: [], floats: [], clouds: [],
      hudCache: '',
      yangSky: null, yangGlow: null, yangGradKey: '',
      canvas: null, rafId: 0, lastTs: 0, W: 324, H: 480
    };
    if (saveData && saveData.v === 1 && saveData.mode === 'checkpoint') {
      g.level = Math.round(gfxNum(saveData.level, 1, 1, 9999));
      g.pointsEarned = Math.round(gfxNum(saveData.pointsEarned, 0, 0, 1e9));
      yangStartLevel(g, g.level);
    } else if (saveData && saveData.v === 1 && saveData.mode === 'run') {
      if (!yangRestoreRun(g, saveData)) yangStartLevel(g, Math.max(1, Math.round(gfxNum(saveData.level, 1, 1, 9999))));
      else g.pointsEarned = Math.round(gfxNum(saveData.pointsEarned, 0, 0, 1e9));
    } else {
      yangStartLevel(g, 1);
    }
    yangGame = g;
    yangRenderUI();
    g.lastTs = performance.now();
    g.rafId = gfxRaf(yangLoop);
  }
  function yangTeardown() {
    const g = yangGame;
    if (g) {
      if (g.rafId) gfxCaf(g.rafId);
      g.rafId = 0;
      g.canvas = null;
    }
    yangGame = null;
  }
  function yangExitToLobby() {
    const g = yangGame;
    let saved = false;
    if (g) {
      if (g.phase === 'cleared') saved = yangSaveCheckpoint(g);
      else if (g.phase !== 'over') saved = yangSaveGame(g);
    }
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    yangTeardown();
    renderAdGameLobby();
    if (g && g.phase === 'cleared') showToast(saved ? ('🔖 已保存进度，下次从第 ' + (g.level + 1) + ' 关继续') : '🚪 已返回广告游戏复刻大厅');
    else showToast(saved ? '🔖 已保存进度，下次进入可继续' : '🚪 已返回广告游戏复刻大厅');
  }
  function yangQuitToCenter() {
    yangClearSave();
    if (typeof contactsVoiceStopAll === 'function') contactsVoiceStopAll();
    yangTeardown();
    renderSetup();
    showToast('🚪 已结束本局羊了个羊');
  }
  function yangNextLevel() {
    const g = yangGame;
    if (!g || g.phase !== 'cleared') return;
    const nl = g.level + 1;
    const points = g.pointsEarned;
    yangTeardown();
    yangOpenGame({ v: 1, mode: 'checkpoint', level: nl, pointsEarned: points });
    showToast('🐑 第 ' + nl + ' 关，加油！');
  }

  // ---- 布局 / 输入 ----
  function yangLayout(g) {
    const cols = Math.max(1, g.gridCols);
    const rows = Math.max(1, g.gridRows);
    const areaW = Math.max(60, g.W - 16);
    const areaH = Math.max(80, g.H - 62 - 64);
    const spacingX = Math.min(60, areaW / cols);
    const spacingY = Math.min(60, Math.max(34, areaH / rows));
    const originX = (g.W - cols * spacingX) / 2;
    const originY = 56;
    const size = Math.max(26, Math.min(46, spacingX - 12, spacingY - 10));
    return { spacingX: spacingX, spacingY: spacingY, originX: originX, originY: originY, size: size };
  }
  function yangTowerXY(g, ti, layout) {
    const t = g.towers[ti];
    if (!t) return { x: g.W / 2, y: 90 };
    return { x: layout.originX + (t.col + 0.5) * layout.spacingX, y: layout.originY + (t.row + 0.5) * layout.spacingY };
  }
  function yangHitTest(g, x, y) {
    const layout = yangLayout(g);
    const limit = layout.size / 2 + 8;
    let best = null;
    let bestD = Infinity;
    for (const c of g.cards) {
      if (c.st !== 'field' || !yangClickable(g, c)) continue;
      const p = yangTowerXY(g, c.cell, layout);
      const off = Math.min(c.layer, 9) * 2;
      const dx = Math.abs(x - (p.x + off));
      const dy = Math.abs(y - (p.y - off));
      if (dx <= limit && dy <= limit) {
        const d = dx + dy;
        if (d < bestD) { bestD = d; best = c; }
      }
    }
    return best;
  }
  function yangBindInput(g) {
    const cv = g.canvas;
    if (!cv) return;
    cv.addEventListener('contextmenu', (e) => e.preventDefault());
    const handle = (cx, cy) => {
      if (g.phase !== 'play') return;
      try {
        const r = cv.getBoundingClientRect();
        const card = yangHitTest(g, cx - r.left, cy - r.top);
        if (card) yangClickCard(g, card);
      } catch (err) { /* ignore */ }
    };
    if (typeof window.PointerEvent !== 'undefined') {
      cv.addEventListener('pointerdown', (e) => { e.preventDefault(); handle(e.clientX, e.clientY); });
    } else {
      cv.addEventListener('touchstart', (e) => { if (e.touches[0]) { e.preventDefault(); handle(e.touches[0].clientX, e.touches[0].clientY); } });
      cv.addEventListener('mousedown', (e) => handle(e.clientX, e.clientY));
    }
  }

  // ---- 循环 / HUD ----
  function yangLoop(ts) {
    const g = yangGame;
    if (!g) return;
    if (!g.canvas || !g.canvas.isConnected) { yangTeardown(); return; }
    const now = ts || performance.now();
    const dt = Math.min(0.05, Math.max(0.001, (now - g.lastTs) / 1000 || 0.016));
    g.lastTs = now;
    yangUpdate(g, dt);
    yangDraw(g);
    g.rafId = gfxRaf(yangLoop);
  }
  function yangUpdate(g, dt) {
    g.time += dt;
    if (g.banner.t > 0) g.banner.t -= dt;
    if (g.shake > 0) g.shake = Math.max(0, g.shake - dt * 30);
    gfxUpdateFx(g, dt);
  }
  function yangUpdateHud(g) {
    if (!sheet) return;
    const remain = yangLiveCount(g);
    const sig = [remain, g.slot.length, g.level, g.items.move, g.items.undo, g.items.shuffle, g.reviveUsed, g.phase].join('|');
    if (sig === g.hudCache) return;
    g.hudCache = sig;
    const set = (id, txt) => { const el = sheet.querySelector('#' + id); if (el) el.textContent = txt; };
    set('yang-remain', String(remain));
    set('yang-slot-count', g.slot.length + '/' + YANG_SLOT_CAP);
    set('yang-level', String(g.level));
    const itemBtn = (sel, n) => {
      const el = sheet.querySelector(sel);
      if (!el) return;
      el.style.opacity = n > 0 ? '1' : '0.45';
      const cnt = el.querySelector('.yang-item-n');
      if (cnt) cnt.textContent = '×' + n;
    };
    itemBtn('#yang-btn-move', g.items.move);
    itemBtn('#yang-btn-undo', g.items.undo);
    itemBtn('#yang-btn-shuffle', g.items.shuffle);
    const rv = sheet.querySelector('#yang-revive-flag');
    if (rv) rv.textContent = g.reviveUsed ? '已用' : '可用';
  }

  // ---- UI ----
  function yangRenderUI() {
