  // ---- 绘制 ----
  function yangDraw(g) {
    const cv = g.canvas;
    if (!cv) return;
    const cssW = cv.clientWidth || 0;
    const cssH = cv.clientHeight || 0;
    if (cssW <= 0 || cssH <= 0) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const bw = Math.round(cssW * dpr);
    const bh = Math.round(cssH * dpr);
    if (cv.width !== bw || cv.height !== bh) { cv.width = bw; cv.height = bh; }
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    g.W = cssW;
    g.H = cssH;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.lineCap = 'butt';
    ctx.lineJoin = 'miter';
    ctx.clearRect(0, 0, cssW, cssH);
    // 白天草地背景（渐变缓存）
    const gradKey = cssW + 'x' + cssH;
    if (!g.yangSky || g.yangGradKey !== gradKey) {
      const sky = ctx.createLinearGradient(0, 0, 0, cssH);
      sky.addColorStop(0, '#A7D8FF');
      sky.addColorStop(0.5, '#DDF3C8');
      sky.addColorStop(1, '#BFE6A0');
      const glow = ctx.createRadialGradient(cssW * 0.3, cssH * 0.12, 6, cssW * 0.3, cssH * 0.12, cssW);
      glow.addColorStop(0, 'rgba(255,251,214,0.55)');
      glow.addColorStop(1, 'rgba(255,251,214,0)');
      g.yangSky = sky;
      g.yangGlow = glow;
      g.yangGradKey = gradKey;
    }
    ctx.fillStyle = g.yangSky;
    ctx.fillRect(0, 0, cssW, cssH);
    // 云
    for (const c of g.clouds) {
      const cx = ((c.x + g.time * 0.012 * c.s) % 1.2 - 0.1) * (cssW + 120) - 60;
      const cy = c.y * cssH * 0.55;
      ctx.globalAlpha = 0.75;
      ctx.fillStyle = '#FFFFFF';
      ctx.beginPath();
      ctx.ellipse(cx, cy, 30 * c.s, 12 * c.s, 0, 0, Math.PI * 2);
      ctx.ellipse(cx + 20 * c.s, cy - 6 * c.s, 20 * c.s, 10 * c.s, 0, 0, Math.PI * 2);
      ctx.ellipse(cx - 22 * c.s, cy - 3 * c.s, 17 * c.s, 9 * c.s, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.fillStyle = g.yangGlow;
    ctx.fillRect(0, 0, cssW, cssH);
    ctx.save();
    if (g.shake > 0) ctx.translate((Math.random() - 0.5) * g.shake, (Math.random() - 0.5) * g.shake);
    const layout = yangLayout(g);
    // 塔底座
    for (let ti = 0; ti < g.towers.length; ti++) {
      const p = yangTowerXY(g, ti, layout);
      const s = layout.size;
      ctx.fillStyle = 'rgba(31,94,52,0.16)';
      gfxRoundRect(ctx, p.x - s / 2 - 4, p.y - s / 2 + 5, s + 8, s + 8, 10);
      ctx.fill();
      ctx.strokeStyle = 'rgba(31,94,52,0.22)';
      ctx.lineWidth = 1;
      gfxRoundRect(ctx, p.x - s / 2 - 4, p.y - s / 2 + 5, s + 8, s + 8, 10);
      ctx.stroke();
    }
    // 卡牌（同一塔自下而上；被压住的暗罩）
    const pulse = 0.5 + 0.5 * Math.sin(g.time * 3);
    const fields = g.cards.filter(c => c.st === 'field');
    fields.sort((a, b) => a.layer - b.layer || a.cell - b.cell);
    for (const c of fields) yangDrawCard(ctx, g, c, layout, pulse);
    // 卡槽
    yangDrawSlot(ctx, g);
    // 粒子
    for (const p of g.parts) {
      ctx.globalAlpha = Math.max(0, Math.min(1, p.life / 0.5));
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // 飘字
    ctx.textAlign = 'center';
    for (const f of g.floats) {
      const a = Math.max(0, Math.min(1, f.life / 0.9));
      ctx.globalAlpha = a;
      ctx.font = '700 ' + Math.round(13 * f.scale) + 'px ' + GAME_FONT;
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 3;
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x, f.y);
    }
    ctx.globalAlpha = 1;
    // 关卡横幅
    if (g.banner.t > 0) {
      const a = Math.min(1, g.banner.t / 0.5);
      ctx.globalAlpha = a;
      ctx.textAlign = 'center';
      ctx.font = '800 24px ' + GAME_FONT;
      ctx.strokeStyle = 'rgba(0,0,0,0.55)';
      ctx.lineWidth = 5;
      ctx.strokeText(g.banner.text, cssW / 2, cssH * 0.3);
      ctx.fillStyle = '#0F766E';
      ctx.fillText(g.banner.text, cssW / 2, cssH * 0.3);
      if (g.banner.sub) {
        ctx.font = '600 12px ' + GAME_FONT;
        ctx.strokeText(g.banner.sub, cssW / 2, cssH * 0.3 + 22);
        ctx.fillStyle = '#134E4A';
        ctx.fillText(g.banner.sub, cssW / 2, cssH * 0.3 + 22);
      }
      ctx.globalAlpha = 1;
    }
    ctx.textAlign = 'left';
    ctx.restore();
  }
  function yangDrawCard(ctx, g, c, layout, pulse) {
    const p = yangTowerXY(g, c.cell, layout);
    const off = Math.min(c.layer, 9) * 2;
    const s = layout.size;
    const x = p.x + off - s / 2;
    const y = p.y - off - s / 2;
    const idx = Math.max(0, YANG_POOL.indexOf(c.pat));
    const clickable = yangClickable(g, c);
    ctx.fillStyle = 'rgba(0,0,0,0.14)';
    gfxRoundRect(ctx, x + 2, y + 3, s, s, 8);
    ctx.fill();
    ctx.fillStyle = YANG_FILL[idx] || '#E5E7EB';
    gfxRoundRect(ctx, x, y, s, s, 8);
    ctx.fill();
    if (clickable) {
      ctx.lineWidth = 2.6;
      ctx.strokeStyle = 'rgba(255,255,255,' + (0.5 + 0.5 * pulse).toFixed(2) + ')';
      gfxRoundRect(ctx, x - 1, y - 1, s + 2, s + 2, 9);
      ctx.stroke();
    }
    ctx.lineWidth = 1.6;
    ctx.strokeStyle = YANG_LINE[idx] || '#9CA3AF';
    gfxRoundRect(ctx, x, y, s, s, 8);
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.font = Math.round(s * 0.52) + 'px ' + GAME_FONT;
    ctx.globalAlpha = clickable ? 1 : 0.6;
    ctx.fillStyle = '#111827';
    ctx.fillText(c.pat, x + s / 2, y + s * 0.68);
    ctx.globalAlpha = 1;
    if (!clickable) {
      ctx.fillStyle = 'rgba(30,41,59,0.26)';
      gfxRoundRect(ctx, x, y, s, s, 8);
      ctx.fill();
    }
    ctx.textAlign = 'left';
  }
  function yangDrawSlot(ctx, g) {
    const n = YANG_SLOT_CAP;
    const y = g.H - 34;
    const cw = (g.W - 16) / n;
    const s = Math.min(38, cw - 4);
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    gfxRoundRect(ctx, 4, y - s / 2 - 6, g.W - 8, s + 12, 12);
    ctx.fill();
    for (let i = 0; i < n; i++) {
      const x = 8 + i * cw + (cw - s) / 2;
      const id = g.slot[i];
      if (id === undefined) {
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = 'rgba(15,118,110,0.45)';
        ctx.lineWidth = 1.5;
        gfxRoundRect(ctx, x, y - s / 2, s, s, 7);
        ctx.stroke();
        ctx.setLineDash([]);
      } else {
        const c = g.cardMap[id];
        const idx = c ? Math.max(0, YANG_POOL.indexOf(c.pat)) : 0;
        ctx.fillStyle = YANG_FILL[idx] || '#E5E7EB';
        gfxRoundRect(ctx, x, y - s / 2, s, s, 7);
        ctx.fill();
        ctx.strokeStyle = YANG_LINE[idx] || '#9CA3AF';
        ctx.lineWidth = 1.6;
        gfxRoundRect(ctx, x, y - s / 2, s, s, 7);
        ctx.stroke();
        if (c) {
          ctx.textAlign = 'center';
          ctx.font = Math.round(s * 0.52) + 'px ' + GAME_FONT;
          ctx.fillStyle = '#111827';
          ctx.fillText(c.pat, x + s / 2, y + s * 0.18);
          ctx.textAlign = 'left';
        }
      }
    }
  }
  // __YANG_ENGINE_END__
    // ============================================================
    // ========== 挣钱小游戏：挣钱大厅 + 股市模拟（移植自「瑟瑟小手机功能扩展」股市模块）==========
    // 悬浮圆环 / 游戏大厅「挣钱小游戏」→ 挣钱大厅（含股市模拟 / 星田小铺 / 老虎机 / 资金互通 / 去棋牌大厅）
    // 联动：棋牌筹码 ⇄ 股市资金 ⇄ 积分 ⇄ 星田小铺农场金币 自由兑换（1 筹码 = 10万 资金；100 筹码 = 1 积分）
    // ============================================================
  // ========== 挣钱小游戏 · 资金互通核心（股市资金 ⇄ 棋牌筹码 ⇄ 积分 ⇄ 农场金币） ==========
  // 股市资金为「元」：1 筹码 = THG_FUND_PER_CHIP（10万）资金；积分沿用 1 积分 = 100 筹码。
  // 依赖外层闭包：localStorage / loadPoints / savePoints / getChips / setChips / CHIP_PER_POINT
  const THG_FUND_KEY = 'werewolf_extension_stock_wallet';
  const THG_FUND_PER_CHIP = 100000;
  const THG_FUND_START = 30000000;
  const THG_CHIP_GAMES = ['zjh', 'blackjack', 'holdem', 'mahjong', 'doudizhu'];
  const THG_CHIP_NAMES = { zjh: '炸金花', blackjack: '21点', holdem: '德州扑克', mahjong: '麻将', doudizhu: '斗地主' };

  function thgFundRead() {
    try {
      const raw = localStorage.getItem(THG_FUND_KEY);
      if (raw) {
        const p = JSON.parse(raw);
        if (p && typeof p === 'object') {
          return { v: Math.max(0, Math.round(Number(p.v) || 0)), init: !!p.init };
        }
      }
    } catch (e) { /* ignore */ }
    return { v: 0, init: false };
  }

  function thgFundWrite(obj) {
    try {
      localStorage.setItem(THG_FUND_KEY, JSON.stringify({ v: Math.max(0, Math.round(Number(obj && obj.v) || 0)), init: !!(obj && obj.init) }));
    } catch (e) { /* ignore */ }
    return thgFundRead();
  }

  function thgFundGet() { return thgFundRead().v; }

  function thgFundSet(v) {
    const cur = thgFundRead();
    return thgFundWrite({ v: v, init: cur.init }).v;
  }

  // 股市模块的资金扣款 / 入账接口（treasuryAdjust(delta, note, source)）
  function thgFundAdjust(delta, note, source) {
    const d = Math.round(Number(delta) || 0);
    if (!d) return true;
    const cur = thgFundRead();
    if (d < 0 && cur.v + d < 0) return false;
    thgFundWrite({ v: cur.v + d, init: cur.init });
    return true;
  }

  // 首次进入股市模拟：发放启动资金（= 300 筹码）
  function thgStockEnsureStartFund() {
    const cur = thgFundRead();
    if (cur.init) return false;
    thgFundWrite({ v: Math.max(cur.v, THG_FUND_START), init: true });
    return true;
  }

  function thgFmtMoney(n) {
    let v = Math.round(Number(n) || 0);
    const neg = v < 0;
    v = Math.abs(v);
    const trim = x => { const t = String(x); return t.indexOf('.') >= 0 ? t.replace(/0+$/, '').replace(/\.$/, '') : t; };
    let s;
    if (v >= 1e8) {
      s = trim(Math.round((v / 1e8) * 100) / 100) + '亿';
    } else if (v >= 1e4) {
      const w = Math.round((v / 1e4) * 100) / 100;
      s = w >= 10000 ? (trim(Math.round((v / 1e8) * 100) / 100) + '亿') : (trim(w) + '万');
    } else {
      s = String(v);
    }
    return (neg ? '-' : '') + s;
  }

  // —— 农场金币（星田小铺）在资金互通里的读写接口 ——
  function thgFarmBalance() {
    try { return (typeof sfarmPeekCoins === 'function') ? Math.max(0, Math.floor(Number(sfarmPeekCoins()) || 0)) : 0; } catch (e) { return 0; }
  }
  function thgFarmAdjust(delta) {
    try { return (typeof sfarmCoinAdjust === 'function') ? !!sfarmCoinAdjust(delta) : false; } catch (e) { return false; }
  }
  // 统一增减任意兑换币种（兑换所使用；负数不足则失败）
  function thgAdjustForExchange(k, delta) {
    const d = Math.round(Number(delta) || 0);
    if (!d) return true;
    if (k === 'farm') return thgFarmAdjust(d);
    if (k === 'fund') {
      if (d < 0 && thgFundGet() + d < 0) return false;
      thgFundSet(thgFundGet() + d);
      return true;
    }
    if (k === 'points') {
      const v = loadPoints();
      if (d < 0 && v + d < 0) return false;
      savePoints(v + d);
      return true;
    }
    const c = getChips(k);
    if (d < 0 && c + d < 0) return false;
    setChips(k, c + d);
    return true;
  }

  // —— 兑换数学：非农场币种一切换算经由「筹码」中转；农场金币按星田小铺汇率直接换算 ——
  function thgSrcBalance(src) {
    if (src === 'fund') return thgFundGet();
    if (src === 'points') return loadPoints();
    if (src === 'farm') return thgFarmBalance();
    return getChips(src);
  }

  function thgSrcName(src) {
    if (src === 'fund') return '股市资金';
    if (src === 'points') return '积分';
