            <div class="sfarm-side">${[3, 4, 5].map(i => sfarmHiveHTML(g, i, now)).join('')}</div>
          </div>
          <div class="sfarm-big-actions">
            <button data-sfarm-act="shop" class="sfarm-bigbtn shop"><span class="sfarm-bigicon">🏪</span><span class="sfarm-bigtext"><b>种子商店</b><small>12 种作物 · 工具 · 地块</small></span></button>
            <button data-sfarm-act="market" class="sfarm-bigbtn market"><span class="sfarm-bigicon">🛒</span><span class="sfarm-bigtext"><b>集市</b><small>按品质卖出 · 一键清仓</small></span></button>
          </div>
        </div>
      </div>`;
  }
  function sfarmUpdatePlotDom(g, i) {
    if (!sheet || !sheet.querySelector) return;
    const p = g.plots[i];
    if (!p || !p.crop) return;
    const def = sfarmCropDef(p.crop.type);
    if (!def) return;
    const ratio = sfarmClamp(p.crop.growth / sfarmCropMs(p.crop.type), 0, 1);
    const stage = sfarmCropStage(p.crop);
    const mature = sfarmIsMature(p.crop);
    const water = sfarmClamp(p.crop.water, 0, 100);
    const card = sheet.querySelector('#sfarm-card-' + i);
    if (card) card.classList.toggle('mature', mature);
    const prog = sheet.querySelector('#sfarm-prog-' + i);
    if (prog) prog.style.width = (ratio * 100).toFixed(1) + '%';
    const w = sheet.querySelector('#sfarm-water-' + i);
    if (w) w.style.width = water.toFixed(1) + '%';
    const st = sheet.querySelector('#sfarm-stage-' + i);
    if (st) st.textContent = sfarmStageLabel(stage);
    const cropEl = sheet.querySelector('#sfarm-crop-' + i);
    if (cropEl) {
      cropEl.className = 'sfarm-crop stage-' + stage;
      if (cropEl.dataset.stage !== String(stage)) {
        cropEl.dataset.stage = String(stage);
        cropEl.innerHTML = sfarmCropVisualHTML(p.crop.type, stage);
      }
    }
    const mult = sfarmBeeSpeed(g, 1, sfarmNow(g.timeMode));
    const remainSec = Math.max(0, Math.ceil((sfarmCropMs(p.crop.type) - p.crop.growth) / 1000 / mult));
    const hint = sheet.querySelector('#sfarm-hint-' + i);
    if (hint) {
      hint.textContent = mature ? '✨ 点击收割' : (water <= 0 ? '💧 缺水 · 点击浇水' : (water < 100 ? '🌿 ' + remainSec + 's · 💧' : '🌿 ' + remainSec + 's'));
    }
  }
  function sfarmUpdateHud(g) {
    if (!g || !sheet || !sheet.querySelector) return;
    const q = sel => sheet.querySelector(sel);
    const set = (sel, text) => { const el = q(sel); if (el) el.textContent = text; };
    set('#sfarm-coins', String(g.coins));
    for (let i = 0; i < SFARM_GRID; i++) sfarmUpdatePlotDom(g, i);
    const now = sfarmNow(g.timeMode);
    for (let i = 0; i < 6; i++) {
      const el = q('#sfarm-hive-' + i);
      if (el) el.className = 'sfarm-hive ' + sfarmHiveState(g, i, now);
      const time = q('#sfarm-hive-time-' + i);
      const b = g.beeBoxes[i];
      if (time) time.textContent = b && b.box && b.beeExpiresAt > now ? sfarmFmtCountdown(b.beeExpiresAt - now) : '';
    }
    const auto = q('[data-sfarm-act="autowater"]');
    if (auto) {
      const owned = !!g.upgrades.autoWater;
      auto.className = 'sfarm-tool ' + (!owned ? 'locked' : (g.batteryMs > 0 ? 'on' : 'off'));
      set('#sfarm-auto-status', !owned ? '商店购买 · 自动浇水' : (g.batteryMs > 0 ? ('自动浇水中 · 电池 ' + sfarmFmtCountdown(g.batteryMs)) : ('缺电池 · 点击安装（电池 ' + g.batteries + '）')));
    }
    const bag = q('[data-sfarm-act="beebag"]');
    if (bag) {
      const live = sfarmLiveBagBees(g, now);
      bag.className = 'sfarm-tool ' + (live.length ? 'on' : 'off');
      const nearest = live.length ? Math.min(...live.map(b => b.expiresAt)) : 0;
      set('#sfarm-beebag-status', live.length ? ('背包蜜蜂 ×' + live.length + ' · 最快 ' + sfarmFmtCountdown(nearest - now) + ' 飞走') : '背包无蜜蜂 · 点击商店');
    }
  }
  function sfarmRender(g) {
    if (!g || !sheet) return;
    let top = 0;
    try { const sc = sheet.querySelector('.sfarm-scroll'); if (sc) top = sc.scrollTop || 0; } catch (e) { /* ignore */ }
    sheet.innerHTML = sfarmPageHTML(g);
    try { const sc2 = sheet.querySelector('.sfarm-scroll'); if (sc2) sc2.scrollTop = top; } catch (e) { /* ignore */ }
    sfarmUpdateHud(g);
  }

  // ---- 商店 / 设置 / 兑换 / 集市弹层 ----
  function sfarmSeedCardHTML(g, type) {
    const d = sfarmCropDef(type);
    const owned = g.seeds[type] || 0;
    return `<div class="sfarm-shop-card"><div class="sfarm-shop-icon">${d.icon}</div><div class="sfarm-shop-main"><div class="sfarm-shop-name">${d.name}种子 <span style="font-size:9px;color:#8b7862;">拥有 ${owned}</span></div><div class="sfarm-shop-desc">成熟 ${sfarmFmtGrow(d.growSec)} · 基础售价 🪙${d.sell} · 需水 ${sfarmFmtGrow(d.waterSec)}<br>可出品质：铜★ 银★ 金★ 彩♥</div></div><button data-sfarm-panel="buy-seed" data-seed="${type}" class="sfarm-btn primary">🪙 ${d.cost}</button></div>`;
  }
  function sfarmToolCardHTML(g, key) {
    const t = SFARM_TOOLS[key];
    const owned = (key === 'autoWater' && g.upgrades.autoWater) || (key === 'windmill' && g.upgrades.decor);
    const count = key === 'battery' ? g.batteries : (key === 'beehive' ? g.beehives : (key === 'bee' ? sfarmLiveBagBees(g).length : 0));
    let extra = t.desc;
    if (owned) extra += ' · 已拥有';
    if (key === 'battery') extra += ' · 背包 ' + count;
    if (key === 'beehive') extra += ' · 背包 ' + count;
    if (key === 'bee') extra += ' · 背包 ' + count + ' 只';
    return `<div class="sfarm-shop-card"><div class="sfarm-shop-icon">${t.icon}</div><div class="sfarm-shop-main"><div class="sfarm-shop-name">${t.name}</div><div class="sfarm-shop-desc">${extra}</div></div><button data-sfarm-panel="buy-tool" data-tool="${key}" class="sfarm-btn ${owned ? 'soft' : 'gold'}" ${owned ? 'disabled' : ''}>${owned ? '已拥有' : '🪙 ' + t.price}</button></div>`;
  }
  function sfarmShopBody(g) {
    const tabs = `<div class="sfarm-tabs">
      <button data-sfarm-panel="tab" data-tab="seeds" class="sfarm-tab ${sfarmShopTab === 'seeds' ? 'on' : ''}">🌱 种子</button>
      <button data-sfarm-panel="tab" data-tab="tools" class="sfarm-tab ${sfarmShopTab === 'tools' ? 'on' : ''}">🛠 工具</button>
      <button data-sfarm-panel="tab" data-tab="plots" class="sfarm-tab ${sfarmShopTab === 'plots' ? 'on' : ''}">🟫 地块</button>
    </div>`;
    let body = '';
    if (sfarmShopTab === 'tools') {
      body = ['autoWater', 'battery', 'beehive', 'bee', 'windmill'].map(k => sfarmToolCardHTML(g, k)).join('');
    } else if (sfarmShopTab === 'plots') {
      body = g.plots.map((p, i) => {
        const cost = SFARM_PLOT_COSTS[i] || 0;
        return `<div class="sfarm-shop-card"><div class="sfarm-shop-icon">${p.unlocked ? '🟫' : '🔒'}</div><div class="sfarm-shop-main"><div class="sfarm-shop-name">地块 ${i + 1}</div><div class="sfarm-shop-desc">${p.unlocked ? '已解锁，可翻土种植' : '解锁费用 🪙 ' + cost}</div></div><button data-sfarm-panel="unlock" data-idx="${i}" class="sfarm-btn ${p.unlocked ? 'soft' : 'primary'}" ${p.unlocked ? 'disabled' : ''}>${p.unlocked ? '已解锁' : '解锁'}</button></div>`;
      }).join('');
    } else {
      sfarmShopTab = 'seeds';
      body = `<div class="sfarm-note" style="margin-bottom:6px;">收割品质：${sfarmQualityLegendHTML()}<br>品质越稀有，集市售价越高；风车再额外 +10%。</div>` + SFARM_CROP_ORDER.map(t => sfarmSeedCardHTML(g, t)).join('');
    }
    return tabs + body;
  }
  function sfarmSettingsBody(g) {
    const now = sfarmNow(g.timeMode);
    const activeBees = sfarmActiveBeeCount(g, now);
    const bagBees = sfarmLiveBagBees(g, now).length;
    const boxes = g.beeBoxes.filter(b => b.box).length;
    const unlocked = g.plots.filter(p => p.unlocked).length;
    return `
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">⏱ 时间来源</div><div class="sfarm-settings-line">默认内置时间：本机真实时间，离线会补生长。数据库时间：读取全局数据表日期/天，三份扩展共享农场存档与时钟偏移，剧情跨天会补生长。</div><div style="display:flex;gap:6px;margin-top:6px;"><button data-sfarm-panel="set-time" data-mode="local" class="sfarm-btn ${g.timeMode === 'local' ? 'primary' : 'soft'}" style="flex:1;">⏱ 内置时间</button><button data-sfarm-panel="set-time" data-mode="db" class="sfarm-btn ${g.timeMode === 'db' ? 'primary' : 'soft'}" style="flex:1;">🗄 数据库时间</button></div><div class="sfarm-settings-line" style="margin-top:4px;">当前：<b>${sfarmTimeLabel(g)}</b></div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🌿 农场状态</div><div class="sfarm-settings-line">金币：🪙 ${g.coins} · 已解锁地块：${unlocked}/9 · 已收割：${g.stats.harvested || 0} · 已售出：🪙 ${g.stats.sold || 0}<br>自动浇水器：${g.upgrades.autoWater ? (g.batteryMs > 0 ? '工作中 · 电池 ' + sfarmFmtCountdown(g.batteryMs) : '缺电池') : '未购买'} · 电池：${g.batteries}<br>蜂箱：${boxes}/6 · 工作蜜蜂：${activeBees} · 背包蜜蜂：${bagBees} · 蜂箱库存：${g.beehives}<br>风车：${g.upgrades.decor ? '已拥有 · 售价 +10%' : '未购买'} · 已播种：${g.stats.planted || 0} · 蜜蜂自动播种：${g.stats.autoPlanted || 0}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">⭐ 品质概率 / 售价倍率</div><div class="sfarm-legend">${sfarmQualityLegendHTML()}</div><div class="sfarm-settings-line">每次收割会随机品质；品质倍率按作物基础售价计算，风车再额外 +10%。</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🌱 作物表</div><table class="sfarm-crop-table"><tbody>${SFARM_CROP_ORDER.map(t => { const d = sfarmCropDef(t); return `<tr><td>${d.icon} ${d.name}</td><td>🪙${d.cost}</td><td>售🪙${d.sell}</td><td>${sfarmFmtGrow(d.growSec)}</td><td>水${sfarmFmtGrow(d.waterSec)}</td></tr>`; }).join('')}</tbody></table></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">📖 玩法说明</div><div class="sfarm-settings-line">1. 点击荒地翻土，选种子后点击已翻土地块播种，再点一次浇水。<br>2. 作物只在有水时生长，水耗尽会暂停；成熟后点击地块收割，随机获得品质。<br>3. 自动浇水器需要电池：商店买电池后点击自动浇水器安装；电池没电会停止并显示禁止图标。<br>4. 农田两侧各 3 格蜂箱：先买蜂箱放在空格，再买蜜蜂放入；背包蜜蜂 3 分钟会飞走，蜂箱蜜蜂工作 10 分钟。<br>5. 有蜜蜂的蜂箱可接收拖入的种子自动播种；每只工作蜜蜂 +5% 生长速度，最多 +30%。<br>6. 农场金币是小铺独立货币，可在 💱 兑换所与其他游戏资金 / 积分按比例兑换。<br>7. 三份扩展共用农场存档与数据库时钟；X 离开会自动保存。</div></div>`;
  }
  function sfarmExchangeBody(g) {
    const fundName = sfarmGlobalFundName();
    const fund = sfarmGlobalFundBalance();
    const pts = sfarmPointsBalance();
    const quick = (dir, amounts) => `<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:5px;">${amounts.map(a => `<button data-sfarm-panel="exchange" data-dir="${dir}" data-amt="${a[0]}" class="sfarm-btn soft">${a[1]}</button>`).join('')}</div>`;
    return `<div class="sfarm-settings-card"><div class="sfarm-settings-title">💰 当前余额</div><div class="sfarm-settings-line">农场金币：🪙 ${g.coins}<br>${fundName}：${sfarmFmtNum(fund)}<br>积分：💎 ${pts}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🪙 农场金币 → ${fundName}</div><div class="sfarm-settings-line">1 农场金币 = ${sfarmFmtNum(SFARM_FUND_PER_COIN)} ${fundName}${quick('farm-fund', [[10, '10'], [50, '50'], [100, '100'], [-1, '全部']])}</div></div>
