      <div class="sfarm-settings-card"><div class="sfarm-settings-title">🪙 农场金币 → 💎 积分</div><div class="sfarm-settings-line">${SFARM_POINTS_PER_COIN} 农场金币 = 1 积分${quick('farm-points', [[5000, '5000'], [10000, '1万'], [20000, '2万'], [-1, '全部']])}</div></div>
      <div class="sfarm-settings-card"><div class="sfarm-settings-title">💎 积分 → 🪙 农场金币</div><div class="sfarm-settings-line">1 积分 = ${SFARM_COINS_PER_POINT} 农场金币${quick('points-farm', [[1, '1'], [5, '5'], [10, '10'], [-1, '全部']])}</div></div>
      <div class="sfarm-note">兑换立即生效；农场金币为小铺独立货币，不影响棋牌筹码 / 股市资金 / 小金库的原有规则。</div>`;
  }
  function sfarmMarketBody(g) {
    const total = sfarmBagValue(g);
    const rows = SFARM_CROP_ORDER.filter(t => sfarmCropValue(g, t) > 0).map(t => {
      const d = sfarmCropDef(t);
      const inv = g.inventory[t];
      const badges = SFARM_QUALITY_KEYS.map(k => { const n = inv[k] || 0; return n > 0 ? (sfarmQualityBadgeHTML(k, n) + '<span style="font-size:8.5px;color:#8b7862;margin-right:4px;">🪙' + sfarmSellValue(g, t, n, k) + '</span>') : ''; }).join('');
      const count = SFARM_QUALITY_KEYS.reduce((s, k) => s + (inv[k] || 0), 0);
      const val = sfarmCropValue(g, t);
      return `<div class="sfarm-market-row"><div class="sfarm-shop-icon">${d.icon}</div><div class="sfarm-market-main"><div class="sfarm-market-name">${d.name} ×${count}</div><div class="sfarm-legend">${badges}</div><div class="sfarm-market-val">可卖 🪙 ${val}</div></div><button data-sfarm-panel="sell" data-crop="${t}" class="sfarm-btn gold">卖</button></div>`;
    }).join('');
