  function sfarmOverlayContent(g, type) {
    const titles = { shop: '🏪 种子商店', settings: '⚙️ 农场设置', exchange: '💱 资金兑换', market: '🛒 集市' };
    let body = '';
    if (type === 'shop') body = sfarmShopBody(g);
    else if (type === 'settings') body = sfarmSettingsBody(g);
    else if (type === 'exchange') body = sfarmExchangeBody(g);
    else body = sfarmMarketBody(g);
    return `<div class="sfarm-panel"><div class="sfarm-panel-head"><span class="sfarm-panel-title">${titles[type] || '星田小铺'} <span style="font-size:11px;opacity:.75;">🌼</span></span><span class="sfarm-coin-pill">🪙 <b>${g.coins}</b></span><button data-sfarm-panel="close" class="sfarm-icon-btn" style="width:28px;height:28px;font-size:16px;">✕</button></div><div class="sfarm-panel-scroll">${body}</div></div>`;
  }
  function sfarmOpenOverlay(type, tab) {
    if (!sheet || !sfarmGame) return;
    const old = sheet.querySelector('.sfarm-overlay');
    if (old) old.remove();
    sfarmOverlayType = type;
    if (type === 'shop' && tab) sfarmShopTab = tab;
    const ov = document.createElement('div');
    ov.className = 'sfarm-overlay';
    ov.innerHTML = sfarmOverlayContent(sfarmGame, type);
    ov.addEventListener('click', sfarmOverlayClick);
    sheet.appendChild(ov);
  }
  function sfarmRefreshOverlay() {
    if (!sheet || !sheet.querySelector || !sfarmGame || !sfarmOverlayType) return;
    const ov = sheet.querySelector('.sfarm-overlay');
    if (!ov) return;
    let top = 0;
    try { const sc = ov.querySelector('.sfarm-panel-scroll'); if (sc) top = sc.scrollTop || 0; } catch (e) { /* ignore */ }
    ov.innerHTML = sfarmOverlayContent(sfarmGame, sfarmOverlayType);
    try { const sc2 = ov.querySelector('.sfarm-panel-scroll'); if (sc2) sc2.scrollTop = top; } catch (e) { /* ignore */ }
  }
  function sfarmCloseOverlay() {
    if (!sheet || !sheet.querySelector) return;
    const ov = sheet.querySelector('.sfarm-overlay');
    if (ov) ov.remove();
    sfarmOverlayType = null;
    if (sfarmGame) sfarmRender(sfarmGame);
  }
  function sfarmOverlayClick(e) {
    if (!e || !e.target) return;
    const g = sfarmGame;
    if (!g) return;
    const ov = sheet && sheet.querySelector ? sheet.querySelector('.sfarm-overlay') : null;
    if (e.target === ov) { if (e.preventDefault) e.preventDefault(); sfarmCloseOverlay(); return; }
    const el = e.target.closest ? e.target.closest('[data-sfarm-panel]') : null;
    if (!el) return;
    if (e.preventDefault) e.preventDefault();
    const act = el.dataset.sfarmPanel;
    if (act === 'close') { sfarmCloseOverlay(); return; }
    if (act === 'tab') { sfarmShopTab = el.dataset.tab || 'seeds'; sfarmRefreshOverlay(); return; }
    if (act === 'buy-seed') { sfarmBuySeed(g, el.dataset.seed); sfarmRefreshOverlay(); return; }
    if (act === 'buy-tool') { sfarmBuyTool(g, el.dataset.tool); sfarmRefreshOverlay(); return; }
    if (act === 'unlock') { sfarmTryUnlock(g, parseInt(el.dataset.idx, 10), true); sfarmRefreshOverlay(); return; }
    if (act === 'set-time') { sfarmSetTimeMode(g, el.dataset.mode); sfarmRefreshOverlay(); return; }
    if (act === 'exchange') { sfarmExchange(g, el.dataset.dir, parseInt(el.dataset.amt, 10)); sfarmRefreshOverlay(); return; }
    if (act === 'sell-all') { sfarmSellAll(g); sfarmRefreshOverlay(); return; }
    if (act === 'sell') { sfarmSellCrop(g, el.dataset.crop); sfarmRefreshOverlay(); return; }
  }

  // ---- 主界面点击 / 拖拽 ----
  function sfarmClick(e) {
    if (!e || !e.target) return;
    const el = e.target.closest ? e.target.closest('[data-sfarm-act]') : null;
    if (!el) return;
    const g = sfarmGame;
    if (!g) return;
    const act = el.dataset.sfarmAct;
    if (e.preventDefault) e.preventDefault();
    if (act === 'back') { sfarmExitToLobby(); return; }
    if (act === 'close') { sfarmQuitToCenter(); return; }
    if (act === 'settings') { sfarmOpenOverlay('settings'); return; }
    if (act === 'exchange') { sfarmOpenOverlay('exchange'); return; }
    if (act === 'shop') { sfarmOpenOverlay('shop', 'seeds'); return; }
    if (act === 'market') { sfarmOpenOverlay('market'); return; }
    if (act === 'seed') {
      const type = el.dataset.seed;
      if (!sfarmCropDef(type)) return;
      g.selectedSeed = type;
      sfarmUpdateHud(g);
      sfarmRender(g);
      if ((g.seeds[type] || 0) <= 0) showToast('🌰 ' + sfarmCropDef(type).name + '种子不足，点击商店购买');
      return;
    }
    if (act === 'plot') { sfarmPlotAction(g, parseInt(el.dataset.idx, 10)); return; }
    if (act === 'hive') {
      const idx = parseInt(el.dataset.idx, 10);
      if (!Number.isFinite(idx)) return;
      sfarmHiveAction(g, idx);
      return;
    }
    if (act === 'autowater') { sfarmInstallBattery(g); return; }
    if (act === 'beebag' || act === 'windmill') { sfarmOpenOverlay('shop', 'tools'); return; }
  }
  function sfarmDragStart(e) {
    const el = e.target && e.target.closest ? e.target.closest('[data-sfarm-drag-seed]') : null;
