    sfarmDragSeed = el.dataset.sfarmDragSeed || el.dataset.seed || null;
    if (sfarmDragSeed && e.dataTransfer) {
      try { e.dataTransfer.setData('text/plain', sfarmDragSeed); e.dataTransfer.effectAllowed = 'copy'; } catch (err) { /* ignore */ }
    }
  }
  function sfarmDragOver(e) {
    const el = e.target && e.target.closest ? e.target.closest('[data-sfarm-drop]') : null;
    if (!el) return;
    if (e.preventDefault) e.preventDefault();
    if (e.dataTransfer) { try { e.dataTransfer.dropEffect = 'copy'; } catch (err) { /* ignore */ } }
  }
  function sfarmDrop(e) {
    const el = e.target && e.target.closest ? e.target.closest('[data-sfarm-drop]') : null;
    if (!el) return;
    if (e.preventDefault) e.preventDefault();
    const idx = parseInt(el.dataset.idx, 10);
    let seed = '';
    try { seed = e.dataTransfer ? e.dataTransfer.getData('text/plain') : ''; } catch (err) { seed = ''; }
    seed = seed || sfarmDragSeed || '';
    sfarmDragSeed = null;
    if (sfarmGame && sfarmCropDef(seed)) sfarmBeeSow(sfarmGame, idx, seed);
  }

  // ---- 生命周期 ----
  function sfarmOpenGame() {
    sfarmStop();
    if (!sheet) { renderEarnLobby(); return; }
    let g = sfarmLoad();
    if (!g) g = sfarmInitialState();
    const off = sfarmApplyOffline(g);
    sfarmEnsurePlayable(g);
    const now = sfarmNow(g.timeMode);
    g.lastTick = now;
    sfarmGame = g;
    sfarmSave(g);
    sfarmRender(g);
    sfarmClickHandler = (e) => sfarmClick(e);
    sfarmDragHandlers = [
      [(el, ev, fn) => el.addEventListener(ev, fn), 'dragstart', sfarmDragStart],
      [(el, ev, fn) => el.addEventListener(ev, fn), 'dragover', sfarmDragOver],
      [(el, ev, fn) => el.addEventListener(ev, fn), 'drop', sfarmDrop]
    ];
    try {
      sheet.addEventListener('click', sfarmClickHandler);
      sheet.addEventListener('dragstart', sfarmDragStart);
      sheet.addEventListener('dragover', sfarmDragOver);
      sheet.addEventListener('drop', sfarmDrop);
    } catch (e) { /* ignore */ }
    sfarmTimer = setInterval(sfarmTick, 1000);
    sfarmUpdateHud(g);
    if (off.battery) showToast('🔋 自动浇水器电池已耗尽，需要重新购买并安装');
    if (off.bag > 0 || off.box > 0) showToast('🐝 离线期间有蜜蜂飞走了，记得补充蜜蜂');
  }
  function sfarmTick() {
    const g = sfarmGame;
    if (!g) return;
    if (!sheet || !sheet.querySelector || !sheet.querySelector('.sfarm-page')) { sfarmCommit(g); sfarmStop(); return; }
    const now = sfarmNow(g.timeMode);
    const last = Number(g.lastTick) || now;
    const elapsed = now - last;
    const batteryBefore = g.batteryMs;
    if (elapsed > 0) sfarmGrow(g, elapsed, last);
    g.lastTick = now;
    const exp = sfarmExpire(g, now, true);
    if (g.upgrades.autoWater && batteryBefore > 0 && g.batteryMs <= 0) showToast('🔋 自动浇水器电池没电了，自动浇水已停止');
    g.saveTick = (g.saveTick || 0) + 1;
    if (g.saveTick >= 5) sfarmSave(g);
    sfarmUpdateHud(g);
    if ((exp.bag > 0 || exp.box > 0 || (batteryBefore > 0 && g.batteryMs <= 0)) && (sfarmOverlayType === 'settings' || sfarmOverlayType === 'shop')) {
      sfarmRefreshOverlay();
    }
  }
  function sfarmStop() {
    if (sfarmTimer) { try { clearInterval(sfarmTimer); } catch (e) { /* ignore */ } sfarmTimer = null; }
    if (sfarmClickHandler && sheet) { try { sheet.removeEventListener('click', sfarmClickHandler); } catch (e) { /* ignore */ } }
    if (sheet) {
      try { sheet.removeEventListener('dragstart', sfarmDragStart); } catch (e) { /* ignore */ }
      try { sheet.removeEventListener('dragover', sfarmDragOver); } catch (e) { /* ignore */ }
      try { sheet.removeEventListener('drop', sfarmDrop); } catch (e) { /* ignore */ }
    }
    sfarmClickHandler = null;
    sfarmDragHandlers = null;
    sfarmOverlayType = null;
    sfarmGame = null;
  }
  function sfarmExitToLobby() {
