  // ========== 挣钱小游戏 · 老虎机（完成任意游戏 +1 次抽奖机会） ==========
  // 规则：钻石→积分；⭐→抽奖次数；其余图案全部折算成股市资金；每完成任意一局游戏获得 1 次抽奖机会。
  // ---- 股市资金（小游戏机 · 股市/资金钱包） ----
  function slotFundBalance() {
    try { return (typeof thgFundGet === 'function') ? Math.max(0, Math.round(Number(thgFundGet()) || 0)) : 0; } catch (e) { return 0; }
  }
  function slotFundAdjust(delta, note, source) {
    try { return (typeof thgFundAdjust === 'function') ? !!thgFundAdjust(delta, note, source) : false; } catch (e) { return false; }
  }
  function slotFmtMoney(n) {
    try { return (typeof thgFmtMoney === 'function') ? thgFmtMoney(n) : String(Math.round(Number(n) || 0)); } catch (e) { return String(Math.round(Number(n) || 0)); }
  }

  const SLOT_SYMBOLS = [
    { key: 'cherry', icon: '🍒', name: '樱桃', weight: 12, itemType: '零食', itemDesc: '老虎机摇出的水果奖励' },
