    { key: 'star', icon: '⭐', name: '星星', weight: 5, itemType: '杂物', itemDesc: '据说能实现小愿望的星星' },
    { key: 'diamond', icon: '💎', name: '钻石', weight: 4, itemType: '收藏', itemDesc: '亮晶晶的钻石' },
    { key: 'coin', icon: '🪙', name: '金币', weight: 3, itemType: '收藏', itemDesc: '沉甸甸的金币' },
    { key: 'heart', icon: '❤️', name: '爱心', weight: 8, itemType: '甜品', itemDesc: '甜到心跳加速的爱心' },
    { key: 'seven', icon: '7️⃣', name: '幸运七', weight: 2, itemType: '护符', itemDesc: '老虎机头奖的象征' }
  ];
  const SLOT_SYMBOL_MAP = {};
  for (const _s of SLOT_SYMBOLS) SLOT_SYMBOL_MAP[_s.key] = _s;
  let slotMachine = { reels: ['cherry', 'lemon', 'bell'], spinning: false, last: null };
  let slotAnimTimer = null;

  function slotSymbolByKey(key) {
    return SLOT_SYMBOL_MAP[key] || SLOT_SYMBOLS[0];
  }
  function slotLoadChances() {
    try {
      const n = parseInt(localStorage.getItem(SLOT_CHANCE_KEY), 10);
      return Number.isFinite(n) && n > 0 ? n : 0;
    } catch (e) { return 0; }
  }
  function slotSaveChances(n) {
    try { localStorage.setItem(SLOT_CHANCE_KEY, String(Math.max(0, Math.round(Number(n) || 0)))); } catch (e) { /* ignore */ }
    return slotLoadChances();
  }
  function slotLoadStats() {
    const empty = { draws: 0, wins: 0, points: 0, money: 0, energy: 0, spins: 0, items: 0, best: 0 };
    try {
      const d = JSON.parse(localStorage.getItem(SLOT_STATS_KEY) || '{}');
      if (!d || typeof d !== 'object') return empty;
      for (const k of Object.keys(empty)) empty[k] = Math.max(0, Math.round(Number(d[k]) || 0));
      return empty;
    } catch (e) { return empty; }
  }
  function slotSaveStats(s) {
    try { localStorage.setItem(SLOT_STATS_KEY, JSON.stringify(s || {})); } catch (e) { /* ignore */ }
  }
  function slotLoadPendingEnergy() {
    try { const n = parseInt(localStorage.getItem(SLOT_PENDING_ENERGY_KEY), 10); return Number.isFinite(n) && n > 0 ? n : 0; } catch (e) { return 0; }
  }
  function slotSavePendingEnergy(n) {
    try { localStorage.setItem(SLOT_PENDING_ENERGY_KEY, String(Math.max(0, Math.round(Number(n) || 0)))); } catch (e) { /* ignore */ }
  }
  function slotLoadPendingItems() {
    try {
      const arr = JSON.parse(localStorage.getItem(SLOT_PENDING_ITEMS_KEY) || '[]');
      return Array.isArray(arr) ? arr.filter(x => x && x.name) : [];
    } catch (e) { return []; }
  }
  function slotSavePendingItems(list) {
    try { localStorage.setItem(SLOT_PENDING_ITEMS_KEY, JSON.stringify((list || []).slice(-30))); } catch (e) { /* ignore */ }
  }

  // 完成一局游戏 → +1 次老虎机机会（由 onGameFinished 与各小游戏结算点调用）
  function grantSlotChance(source) {
    const n = slotLoadChances() + 1;
    slotSaveChances(n);
    try { showToast('🎰 完成「' + (source || '游戏') + '」，获得 1 次老虎机抽奖机会（当前 ' + n + ' 次）'); } catch (e) { /* ignore */ }
    return n;
  }

  // ---- 第二个文件（瑟瑟小手机）数据库：主角信息表 · 瑟瑟能量 ----
  // 说明：股市模块里的 getLedgerApi/exportTables/readCol 位于其独立 IIFE 内，老虎机必须使用自己的取数器。
  function slotGetDBAPI() {
    const cands = [];
    try { cands.push(window.SeseLedgerAPI, window.AutoCardUpdaterAPI); } catch (e) { /* ignore */ }
    try { const pw = window.parent; cands.push(pw && pw.SeseLedgerAPI, pw && pw.AutoCardUpdaterAPI); } catch (e) { /* ignore */ }
    try { const tw = window.top; cands.push(tw && tw.SeseLedgerAPI, tw && tw.AutoCardUpdaterAPI); } catch (e) { /* ignore */ }
    let fallback = null;
    for (const cand of cands) {
      let api = cand;
      if (!api) continue;
      try { if (api.__legacyFace) api = api.__legacyFace; } catch (e) { /* ignore */ }
      if (!api || typeof api.exportTableAsJson !== 'function') continue;
      if (!fallback) fallback = api;
      if (typeof api.updateCell === 'function' || typeof api.updateRow === 'function' || typeof api.executeSqlMutation === 'function' || typeof api.insertRow === 'function') return api;
    }
    return fallback;
  }
  function slotExportTables() {
    const api = slotGetDBAPI();
    if (!api) return null;
    try {
      const t = api.exportTableAsJson();
      if (t && typeof t === 'object') return t;
    } catch (e) { /* ignore */ }
    return null;
  }
  function slotReadCol(sheet, rowIdx, colName) {
    try {
      if (sheet && sheet.content && sheet.content[rowIdx]) {
        const colIdx = (sheet.content[0] || []).indexOf(colName);
        if (colIdx >= 0) {
          const v = sheet.content[rowIdx][colIdx];
          if (v != null) { const str = String(v).trim(); return (str === '无' || str === '-') ? '' : str; }
        }
      }
    } catch (e) { /* ignore */ }
    return '';
  }
  function slotReadEnergy() {
    try {
      const tables = slotExportTables();
      if (!tables) return null;
      for (const key of Object.keys(tables)) {
        if (key.indexOf('sheet_') !== 0) continue;
        const sh = tables[key];
        if (!sh || sh.name !== '主角信息表' || !Array.isArray(sh.content)) continue;
        const n = parseInt(slotReadCol(sh, 1, '瑟瑟能量'), 10);
        return Number.isFinite(n) ? n : 0;
      }
    } catch (e) { /* ignore */ }
    return null;
  }
  function slotWriteEnergyRaw(delta) {
    return new Promise(function (resolve) {
      try {
        const api = slotGetDBAPI();
        if (!api || typeof api.updateCell !== 'function') { resolve(false); return; }
        const cur = slotReadEnergy();
        if (cur === null) { resolve(false); return; }
        const next = Math.max(0, cur + Math.round(Number(delta) || 0));
        function viaUpdateCell() {
          return new Promise(function (res) {
            try {
              let ret;
              try { ret = api.updateCell('主角信息表', 1, '瑟瑟能量', String(next)); }
              catch (e1) {
                try { ret = api.updateCell({ tableName: '主角信息表', rowIndex: 1, colName: '瑟瑟能量', value: String(next) }); }
                catch (e2) { res(false); return; }
              }
              Promise.resolve(ret).then(function (ok) { res(ok !== false); }, function () { res(false); });
            } catch (e) { res(false); }
          });
        }
        function viaSql() {
          return new Promise(function (res) {
            if (typeof api.executeSqlMutation !== 'function') { res(false); return; }
            try {
              const ret = api.executeSqlMutation('UPDATE zhujuexinxibiao SET ero_power = ? WHERE row_id = 1', [next]);
              Promise.resolve(ret).then(function (r) {
                res(r === true || (r && (r.success === true || Number(r.changes) === 1)));
              }, function () { res(false); });
            } catch (e) { res(false); }
          });
        }
        viaUpdateCell().then(function (ok) { if (ok) resolve(true); else viaSql().then(resolve); });
      } catch (e) { resolve(false); }
    });
  }
  function slotAddEnergy(n) {
    const d = Math.round(Number(n) || 0);
    if (!d) return Promise.resolve(true);
    return slotWriteEnergyRaw(d).then(function (ok) {
      if (!ok) slotSavePendingEnergy(slotLoadPendingEnergy() + d);
      return ok;
    });
  }
  function slotFlushPendingEnergy() {
    const pending = slotLoadPendingEnergy();
    if (!pending) return;
    slotWriteEnergyRaw(pending).then(function (ok) {
      if (!ok) return;
      slotSavePendingEnergy(0);
      try { showToast('❤️ 已补发 ' + pending + ' 点瑟瑟能量'); } catch (e) { /* ignore */ }
      slotRefreshEnergy();
    });
  }
  function slotRefreshEnergy() {
    if (!sheet) return;
    const el = sheet.querySelector('#slot-energy-val');
    if (!el) return;
    const n = slotReadEnergy();
    el.textContent = n === null ? '—' : String(n);
    el.title = n === null ? '未检测到主角信息表·瑟瑟能量' : '来自第二个文件：主角信息表 · 瑟瑟能量';
  }

  // ---- 物品表写入（其余图案奖励按物品分配） ----
  function slotQueueItem(item) {
    if (!item || !item.name) return;
    const list = slotLoadPendingItems();
    list.push({ name: item.name, type: item.type || '杂物', qty: Math.max(1, Math.round(Number(item.qty) || 1)), desc: item.desc || '老虎机奖励' });
    slotSavePendingItems(list);
  }
  function slotInsertItem(item) {
    return new Promise(function (resolve) {
      try {
        const api = slotGetDBAPI();
        if (!api) { resolve(false); return; }
        const qty = Math.max(1, Math.round(Number(item.qty) || 1));
        const type = item.type || '杂物';
        const desc = item.desc || '老虎机奖励';
        const data = { '物品名称': item.name, '类型': type, '数量': String(qty), '描述': desc };
        function viaSql() {
          if (typeof api.executeSqlMutation !== 'function') { resolve(false); return; }
          try {
            const sql = 'INSERT INTO wupinbiao (row_id, item_name, item_type, quantity, description) VALUES ((SELECT COALESCE(MAX(row_id), 0) + 1 FROM wupinbiao), ?, ?, ?, ?)';
            const ret = api.executeSqlMutation(sql, [item.name, type, String(qty), desc], { targetSheetKeys: ['sheet_inventory'] });
            Promise.resolve(ret).then(function (r) {
              resolve(r === true || (r && (r.success === true || Number(r.changes) === 1)));
            }, function () { resolve(false); });
          } catch (e) { resolve(false); }
        }
        if (typeof api.insertRow !== 'function') { viaSql(); return; }
        let ret;
        try { ret = api.insertRow('物品表', data); }
        catch (e1) {
          try { ret = api.insertRow({ tableName: '物品表', data: data }); }
          catch (e2) { viaSql(); return; }
        }
        Promise.resolve(ret).then(function (ok) { if (ok !== false) resolve(true); else viaSql(); }, function () { viaSql(); });
      } catch (e) { resolve(false); }
    });
  }
  function slotAddItem(item) {
    return slotInsertItem(item).then(function (ok) {
      if (!ok) slotQueueItem(item);
      return ok;
    });
  }
  function slotFlushPendingItems() {
    const list = slotLoadPendingItems();
    if (!list.length) return;
    const remaining = [];
    let chain = Promise.resolve();
    for (const item of list) {
      chain = chain.then(function () {
        return slotInsertItem(item).then(function (ok) { if (!ok) remaining.push(item); });
      });
    }
    chain.then(function () {
      slotSavePendingItems(remaining);
      if (remaining.length < list.length) {
        try { showToast('🎁 已补发 ' + (list.length - remaining.length) + ' 件老虎机物品'); } catch (e) { /* ignore */ }
      }
    });
  }

  // ---- 抽奖概率与倍率 ----
  function slotPickSymbol() {
    let total = 0;
    for (const s of SLOT_SYMBOLS) total += s.weight;
    let r = Math.random() * total;
    for (const s of SLOT_SYMBOLS) { r -= s.weight; if (r <= 0) return s; }
    return SLOT_SYMBOLS[0];
  }
  function slotItemForSymbol(sym, qty) {
    const meta = {
      cherry: { name: '樱桃', type: '零食', desc: '老虎机水果奖励' },
      lemon: { name: '柠檬', type: '零食', desc: '酸酸甜甜的老虎机水果' },
      bell: { name: '铃铛', type: '饰品', desc: '叮当作响的小铃铛' },
      star: { name: '许愿星', type: '杂物', desc: '据说能实现小愿望的星星' }
    }[sym.key];
    if (!meta) return null;
    return { name: meta.name, type: meta.type, qty: Math.max(1, qty || 1), desc: meta.desc };
  }
  function slotMergeItems(list) {
    const out = [];
    const map = {};
    for (const it of (Array.isArray(list) ? list : [])) {
      if (!it || !it.name) continue;
      if (map[it.name]) { map[it.name].qty += Math.max(1, Math.round(Number(it.qty) || 1)); }
      else {
        const copy = { name: it.name, type: it.type || '杂物', qty: Math.max(1, Math.round(Number(it.qty) || 1)), desc: it.desc || '老虎机奖励' };
        map[it.name] = copy;
        out.push(copy);
      }
    }
    return out;
  }
  function slotResolve(reels) {
    const keys = reels.map(function (s) { return s.key; });
    const counts = {};
    for (const k of keys) counts[k] = (counts[k] || 0) + 1;
    const uniq = Object.keys(counts);
    let kind = '';
    let hit = '';
    if (uniq.length === 1) { kind = 'triple'; hit = uniq[0]; }
    else if (uniq.length === 2) { kind = 'pair'; hit = uniq.find(function (k) { return counts[k] === 2; }) || ''; }

    // 三个图案全不同：无奖励
    if (!kind) {
      return { tier: '未中奖', multiplier: 0, title: '🙈 差一点…', rewards: { points: 0, money: 0, energy: 0, spins: 0, items: [] } };
    }

    const PAIR = {
      diamond: { points: 10 }, star: { spins: 5 },
      seven: { money: 3000000 }, coin: { money: 1000000 }, bell: { money: 500000 },
      heart: { money: 200000 }, cherry: { money: 100000 }, lemon: { money: 50000 }
    };
    const TRIPLE = {
      diamond: { points: 20 }, star: { spins: 10 },
      seven: { money: 10000000 }, coin: { money: 5000000 }, bell: { money: 2000000 },
      heart: { money: 1000000 }, cherry: { money: 500000 }, lemon: { money: 200000 }
    };
    const titles = {
      pair: { seven: '🔔 双七！', diamond: '💎 双钻！', coin: '🪙 双金币！', heart: '❤️ 双爱心！', star: '⭐ 双星！', cherry: '🍒 双樱桃！', lemon: '🍋 双柠檬！', bell: '🔔 双铃铛！' },
