  // ---------- 数据库（主项目 瑟瑟灵感 数据库） ----------
  function getLedgerApi() {
    var cands = [];
    try { cands.push(window.SeseLedgerAPI, window.AutoCardUpdaterAPI); } catch (e) {}
    try { var pw = getParentWin(); cands.push(pw.SeseLedgerAPI, pw.AutoCardUpdaterAPI); } catch (e) {}
    for (var i = 0; i < cands.length; i++) {
      var api = cands[i];
      if (!api) continue;
      try { if (api.__legacyFace) api = api.__legacyFace; } catch (e) {}
      if (api && typeof api.exportTableAsJson === 'function') return api;
    }
    return null;
  }
  function exportTables() {
    var api = getLedgerApi();
    if (!api) return null;
    try {
      var t = api.exportTableAsJson();
      if (t && typeof t === 'object') return t;
    } catch (e) {}
    return null;
  }
  function listTables() {
    var t = exportTables();
    var out = [];
    if (!t) return out;
    for (var key in t) {
      if (!Object.prototype.hasOwnProperty.call(t, key)) continue;
      if (key.indexOf('sheet_') !== 0) continue;
      var sh = t[key];
      if (!sh || typeof sh !== 'object' || !Array.isArray(sh.content)) continue;
      out.push({ key: key, name: String(sh.name || key), content: sh.content });
    }
    return out;
  }
  function readCol(sheet, rowIdx, colName) {
    try {
      if (sheet && sheet.content && sheet.content[rowIdx]) {
        var colIdx = (sheet.content[0] || []).indexOf(colName);
        if (colIdx >= 0) {
          var v = sheet.content[rowIdx][colIdx];
          if (v != null) { var s = String(v).trim(); return (s === '无' || s === '-') ? '' : s; }
        }
      }
    } catch (e) {}
    return '';
  }
  function readRelationMap() {
    var love = {}, important = {};
    var tables = listTables();
    for (var i = 0; i < tables.length; i++) {
      var sh = tables[i];
      var target = null;
      if (sh.name === '恋爱对象表') target = love;
      else if (sh.name === '重要角色表') target = important;
      if (!target) continue;
      for (var r = 1; r < sh.content.length; r++) {
        var name = readCol(sh, r, '姓名');
        if (!name) continue;
        target[name] = sh.name;
      }
    }
    return { love: love, important: important };
  }

  // ---------- 股市资金（小游戏机 · 与棋牌筹码互通；1 筹码 = 10万 资金） ----------
  function getTreasury() {
    var bal = 0;
    try { bal = (typeof thgFundGet === 'function') ? thgFundGet() : 0; } catch (e) { bal = 0; }
    return { ok: true, host: null, id: 'thgame-fund', name: '股市资金', balance: Math.max(0, Math.round(Number(bal) || 0)), currencies: [], reason: '' };
  }
  function treasuryBalance() { var t = getTreasury(); return t.ok ? t.balance : 0; }
  function treasuryAdjust(delta, note, source) {
    var d = Math.round(Number(delta) || 0);
    if (!d) return true;
    try { return (typeof thgFundAdjust === 'function') ? !!thgFundAdjust(d, note, source) : false; } catch (e) { return false; }
  }

  // ---------- 状态存储 ----------
  var storeKeyCache = '';
  function currentStoreKey() {
    var sid = getChatStorageId();
    var key = sid ? (STORE_PREFIX + '_' + sid.slice(0, 32)) : STORE_PREFIX;
    return key;
  }
  var state = defaultState();
  function defaultState() {
    return {
      apiUrl: '', apiKey: '', model: '', jailbreak: '',
      timeEnabled: false, floorEnabled: false, everyMinutes: 30, everyFloors: 5, contextFloors: 12,
      lastStoryTime: '', lastStoryMin: null,
      companies: [], lastUpdateTs: 0, lastUpdateMesId: -1, seq: 1
    };
  }
  function cfgFields() { return ['apiUrl', 'apiKey', 'model', 'jailbreak', 'timeEnabled', 'floorEnabled', 'everyMinutes', 'everyFloors', 'contextFloors']; }
  function normalizeState(s) {
    if (!s || typeof s !== 'object') s = {};
    var d = defaultState();
    s.apiUrl = typeof s.apiUrl === 'string' ? s.apiUrl : d.apiUrl;
    s.apiKey = typeof s.apiKey === 'string' ? s.apiKey : d.apiKey;
    s.model = typeof s.model === 'string' ? s.model : d.model;
    s.jailbreak = typeof s.jailbreak === 'string' ? s.jailbreak.slice(0, 600) : d.jailbreak;
    // 新旧格式迁移：旧 updateMode 单选 → 新双开关（剧情时间 / 楼层 可同时开启）
    s.timeEnabled = s.timeEnabled === true;
    s.floorEnabled = s.floorEnabled === true;
    if (!s.timeEnabled && !s.floorEnabled) {
      if (s.updateMode === 'time') s.timeEnabled = true;
      else if (s.updateMode === 'floor') s.floorEnabled = true;
    }
    delete s.updateMode;
    s.everyMinutes = Math.round(clampNum(s.everyMinutes, 1, 1440, d.everyMinutes));
    s.everyFloors = Math.round(clampNum(s.everyFloors, 1, 200, d.everyFloors));
    s.contextFloors = Math.round(clampNum(s.contextFloors, 0, 200, d.contextFloors));
    s.lastStoryTime = typeof s.lastStoryTime === 'string' ? s.lastStoryTime : '';
    var lsm = Number(s.lastStoryMin);
    s.lastStoryMin = (s.lastStoryMin === null || s.lastStoryMin === undefined || s.lastStoryMin === '' || !isFinite(lsm)) ? null : lsm;
    s.lastUpdateTs = isFinite(Number(s.lastUpdateTs)) ? Number(s.lastUpdateTs) : 0;
    s.lastUpdateMesId = isFinite(Number(s.lastUpdateMesId)) ? Number(s.lastUpdateMesId) : -1;
    s.tradeNet = Math.round(clampNum(s.tradeNet, -1e15, 1e15, 0));
    s.lastUpdateSnapshot = (s.lastUpdateSnapshot && typeof s.lastUpdateSnapshot === 'object' && Array.isArray(s.lastUpdateSnapshot.companies)) ? s.lastUpdateSnapshot : null;
    s.seq = Math.round(clampNum(s.seq, 1, 999999, 1));
    var list = Array.isArray(s.companies) ? s.companies : [];
    s.companies = [];
    for (var i = 0; i < list.length; i++) {
      var c = normalizeCompany(list[i]);
      if (c) s.companies.push(c);
    }
    return s;
  }
  function normalizeHolders(raw) {
    var out = [];
    if (!Array.isArray(raw)) return out;
    for (var i = 0; i < raw.length && out.length < 20; i++) {
      var h = raw[i];
      if (!h || typeof h !== 'object') continue;
      var nm = String(h.name || '').trim().slice(0, 30);
      if (!nm) continue;
      out.push({ name: nm, pct: round2(clampNum(parseNumberLike(h.pct), 0, 100, 0)), role: String(h.role || '').slice(0, 14) });
    }
    return out;
  }
  function normalizeCompany(raw) {
    if (!raw || typeof raw !== 'object') return null;
    var name = String(raw.name || '').trim().slice(0, 40);
    if (!name) return null;
    var code = String(raw.code || '').trim().toUpperCase().slice(0, 12);
    var hist = Array.isArray(raw.history) ? raw.history : [];
    var history = [];
    for (var i = 0; i < hist.length && history.length < MAX_HISTORY; i++) {
      var v = Number(hist[i]);
      if (isFinite(v) && v > 0) history.push(round2(v));
    }
    var price = Number(raw.price);
    if (!isFinite(price) || price <= 0) price = history.length ? history[history.length - 1] : 100;
    price = round2(price);
    if (history.length === 0) history.push(price);
    var basePrice = Number(raw.basePrice);
    if (!isFinite(basePrice) || basePrice <= 0) basePrice = history[0];
    var co = {
      id: String(raw.id || uid('co')),
      code: code || ('STK' + String(Math.floor(Math.random() * 900) + 100)),
      name: name,
      desc: String(raw.desc || '').trim().slice(0, 80),
      owner: String(raw.owner || '').trim().slice(0, 30),
      ownerKind: (raw.ownerKind === 'love' || raw.ownerKind === 'important') ? raw.ownerKind : '',
      mine: !!raw.mine,
      price: price,
      basePrice: round2(basePrice),
      history: history,
      streakDown: Math.round(clampNum(raw.streakDown, 0, 99, 0)),
      bankrupt: !!raw.bankrupt,
      shares: Math.round(clampNum(raw.shares, 0, 999999999, 0)),
      avgCost: round2(clampNum(raw.avgCost, 0, 999999999, 0)),
      myInvested: Math.round(clampNum(parseNumberLike(raw.myInvested), 0, 1e15, 0)),
      totalShares: Math.round(clampNum(raw.totalShares, 0, 1e12, 0)),
      loveStake: !!raw.loveStake,
      holderShares: Math.round(clampNum(raw.holderShares, 0, 999999999, 0)),
      isHolder: !!raw.isHolder,
      holderGranted: !!raw.holderGranted || !!raw.isHolder || !!raw.loveStake,
      userBoss: !!raw.userBoss,
      holders: normalizeHolders(raw.holders),
      coFounded: !!raw.coFounded,
      lastReason: String(raw.lastReason || '').slice(0, 60),
      createdAt: Number(raw.createdAt) || nowTs(),
      updatedAt: Number(raw.updatedAt) || nowTs()
    };
    if (!(co.totalShares > 0)) { co.totalShares = 1e8; fitSharesToCap(co); }
    if (co.isHolder && !(co.holderShares > 0) && !co.holderGranted) co.holderShares = Math.max(1, Math.round(co.totalShares * HOLDER_INIT_PCT / 100));
    return co;
  }
  function readJSONKey(k) {
    try { var r = localStorage.getItem(k); if (!r) return null; var v = JSON.parse(r); return (v && typeof v === 'object') ? v : null; } catch (e) { return null; }
  }
  function loadState(force) {
    var key = currentStoreKey();
    if (!force && key === storeKeyCache && state && state.__loaded) return state;
    storeKeyCache = key;
    // 配置（API/破限词/自动更新等）独立键保存：更新文件/行情数据过大时设置不丢失
    var data = readJSONKey(key);
    var cfg = readJSONKey(CFG_KEY);
    var merged = data || {};
    if (cfg) {
      var f = cfgFields();
      for (var i = 0; i < f.length; i++) {
        if (Object.prototype.hasOwnProperty.call(cfg, f[i])) merged[f[i]] = cfg[f[i]];
      }
    }
    state = normalizeState(merged);
    state.__loaded = true;
    if (state.companies.length) applyHolderOnLoad();
    return state;
  }
  function saveState() {
    // ① 配置先落盘（独立小键，确保设置永远保存成功）
    try {
      var cfg = {}, f = cfgFields();
      for (var i = 0; i < f.length; i++) cfg[f[i]] = state[f[i]];
      localStorage.setItem(CFG_KEY, JSON.stringify(cfg));
    } catch (e) {}
    // ② 数据落盘；超出上限时逐级瘦身（去掉撤回快照 → 截短走势链）
    var key = storeKeyCache || currentStoreKey();
    try {
      localStorage.setItem(key, JSON.stringify(state));
      return;
    } catch (e) {}
    try {
      var slim = JSON.parse(JSON.stringify(state));
      slim.lastUpdateSnapshot = null;
      localStorage.setItem(key, JSON.stringify(slim));
      return;
    } catch (e) {}
    try {
      var slim2 = JSON.parse(JSON.stringify(state));
      slim2.lastUpdateSnapshot = null;
      for (var c = 0; c < slim2.companies.length; c++) {
        var h = slim2.companies[c].history;
        if (h && h.length > 40) slim2.companies[c].history = h.slice(-40);
      }
      localStorage.setItem(key, JSON.stringify(slim2));
    } catch (e) { try { console.warn(LOG + ' 行情数据保存失败（超出存储上限），设置已独立保存'); } catch (e2) {} }
  }

  // ---------- 股价辅助 ----------
  function prevPriceOf(c) {
    if (c.history && c.history.length >= 2) return c.history[c.history.length - 2];
    return c.basePrice;
  }
  function changePctOf(c) {
    var p = prevPriceOf(c);
    if (!p) return 0;
    return ((c.price - p) / p) * 100;
  }
  function findCompany(codeOrId) {
    for (var i = 0; i < state.companies.length; i++) {
      var c = state.companies[i];
      if (c.id === codeOrId || (c.code && c.code === codeOrId)) return c;
    }
    return null;
  }
  function portfolioValue() {
    var v = 0;
    for (var i = 0; i < state.companies.length; i++) {
      var c = state.companies[i];
      if (c.shares > 0 && !c.bankrupt) v += c.shares * c.price;
    }
    return Math.round(v);
  }
  function totalDownStreakFromChain(chain) {
    var streak = 0;
    for (var i = chain.length - 1; i >= 1; i--) {
      if (chain[i] < chain[i - 1]) streak++;
      else break;
    }
    return streak;
  }
  function applyChain(c, chain) {
    var hist = [];
    for (var i = 0; i < chain.length && hist.length < MAX_HISTORY; i++) {
      var v = parseNumberLike(chain[i]);
      if (isFinite(v) && v > 0) hist.push(round2(v));
    }
    if (!hist.length) return;
    c.history = hist;
    c.price = hist[hist.length - 1];
    c.basePrice = hist[0];
    c.updatedAt = nowTs();
    var streak = totalDownStreakFromChain(hist);
    c.streakDown = Math.min(streak, BANKRUPT_STREAK);
    if (streak >= BANKRUPT_STREAK) { c.bankrupt = true; c.shares = 0; c.avgCost = 0; c.holderShares = 0; c.isHolder = false; }
  }
  function applyPriceUpdate(c, newPrice, reason) {
    if (!c || c.bankrupt) return null;
    var price = Number(newPrice);
    if (!isFinite(price) || price <= 0) return null;
    // 单次波动限制 ±20%（相对最新价）
    var prev = c.price;
    var lo = prev * 0.8, hi = prev * 1.2;
    price = round2(Math.max(lo, Math.min(hi, price)));
    c.history.push(price);
    while (c.history.length > MAX_HISTORY) c.history.shift();
    c.price = price;
    c.updatedAt = nowTs();
    if (typeof reason === 'string' && reason.trim()) c.lastReason = reason.trim().slice(0, 60);
    var result = 'flat';
    if (price < prev) {
      c.streakDown = Math.min(BANKRUPT_STREAK, c.streakDown + 1);
      result = 'down';
      if (c.streakDown >= BANKRUPT_STREAK) {
        c.bankrupt = true;
        c.shares = 0;
        c.avgCost = 0;
        c.holderShares = 0;
        c.isHolder = false;
        result = 'bankrupt';
      }
    } else if (price > prev) {
      c.streakDown = 0;
      result = 'up';
    }
    return result;
  }
  function genCode(name) {
    var pool = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
    var seed = 0;
    for (var i = 0; i < name.length; i++) seed = (seed * 31 + name.charCodeAt(i)) >>> 0;
    var letters = pool.charAt(seed % pool.length) + pool.charAt((seed >> 5) % pool.length);
    var num = String((seed % 9000) + 1000);
    return letters + num;
  }
  function uniqueCode(name) {
    var base = genCode(name);
    var code = base, n = 1;
    var exists = function (s) { for (var i = 0; i < state.companies.length; i++) if (state.companies[i].code === s) return true; return false; };
    while (exists(code)) { code = base.slice(0, 2) + String((parseInt(base.slice(2), 10) + n) % 10000).padStart(4, '0'); n++; if (n > 9999) break; }
    return code;
  }
  function fallbackChain(base, seedStr) {
    var seed = 0; var s = String(seedStr || 'x');
    for (var i = 0; i < s.length; i++) seed = (seed * 33 + s.charCodeAt(i)) >>> 0;
    var rnd = function () { seed = (seed * 1103515245 + 12345) >>> 0; return seed / 4294967296; };
    var chain = [round2(base)];
    var cur = base;
    for (var k = 0; k < 10; k++) {
      var pct = (rnd() * 0.14 - 0.06);
      cur = Math.max(1, round2(cur * (1 + pct)));
      chain.push(cur);
    }
    return chain;
  }

  // ---------- 市值 / 总股本（市值 = 实时股价 × 总股本，AI 生成公司限 1亿~100亿） ----------
  var CAP_MIN = 1e8, CAP_MAX = 1e10, HOLDER_INIT_PCT = 20, HOLDER_KEEP_PCT = 10;
  function marketCapOf(c) {
    if (!c) return 0;
    return round2((Number(c.price) || 0) * (Number(c.totalShares) || 0));
  }
  function fitSharesToCap(c) {
    if (!c) return;
    var p = Number(c.price);
    if (!isFinite(p) || p <= 0) p = 100;
    var sh = Math.round(clampNum(c.totalShares, 0, 1e12, 0));
    if (sh <= 0) sh = 1e8;
    var cap = p * sh;
    if (cap < CAP_MIN) sh = Math.ceil(CAP_MIN / p);
    else if (cap > CAP_MAX) sh = Math.max(1, Math.floor(CAP_MAX / p));
    c.totalShares = sh;
  }

  // ---------- 股东身份（股东权益与散户持股分开；恋人企业 / 与主角有血缘的重要角色公司自动 20%） ----------
  function holderThreshold(c) { return Math.max(1, Math.round((Number(c.totalShares) || 0) * HOLDER_KEEP_PCT / 100)); }
  var userNameCache = { t: 0, v: '' };
  function getUserName() {
    var now = nowTs();
    if (userNameCache.v && now - userNameCache.t < 30000) return userNameCache.v;
    var v = '';
    try {
      var tables = listTables();
      for (var pass = 0; pass < 2 && !v; pass++) {
        var target = pass === 0 ? '主角信息表' : '全局数据表';
        for (var i = 0; i < tables.length; i++) {
          if (tables[i].name === target) { v = readCol(tables[i], 1, '姓名'); break; }
        }
      }
    } catch (e) {}
    if (!v) {
      try {
        var TH = getTH();
        if (TH && typeof TH.substitudeMacros === 'function') {
          var t = String(TH.substitudeMacros('{{user}}') || '').trim();
          if (t && t !== '{{user}}') v = t;
        }
      } catch (e) {}
    }
    userNameCache = { t: now, v: v };
    return v;
  }
  // 角色是否与主角（用户）在人物关系表中有血缘关系
  function isBloodWithUser(name) {
    if (!name) return false;
    var u = getUserName();
    if (!u) return false;
    var parts = splitNames(name);
    var pairs = getBloodPairs(false);
    for (var i = 0; i < parts.length; i++) {
      for (var j = 0; j < pairs.length; j++) {
        var p = pairs[j];
        if ((p.a === u && p.b === parts[i]) || (p.b === u && p.a === parts[i])) return true;
      }
    }
    return false;
  }
  // 公司是否适用股东机制：除自家公司外的所有上市公司（普通公司按我的持股计算，无股东权益）
  function holderApplies(c) {
    if (!c || c.bankrupt || c.mine) return false;
    return true;
  }
  // 是否随股东身份自动获得 20% 股东权益：仅恋爱对象表角色公司、及与主角有血缘的重要角色公司
  function holderGrantsEquity(c) {
    if (!c) return false;
    if (c.ownerKind === 'love') return true;
    if (c.ownerKind === 'important') return isBloodWithUser(c.owner);
    return false;
  }
  function ensureInitialHolder(c) {
    if (!c || !holderGrantsEquity(c) || c.holderGranted || c.bankrupt) return false;
    c.holderGranted = true;
    c.isHolder = true;
    c.holderShares = Math.max(1, Math.round((Number(c.totalShares) || 0) * HOLDER_INIT_PCT / 100));
    var tag = c.ownerKind === 'important' ? '血缘关联' : '恋人企业';
    c.lastReason = (tag + '：主角自动成为股东（股东权益 ' + HOLDER_INIT_PCT + '%）').slice(0, 60);
    c.updatedAt = nowTs();
    return true;
  }
  function updateHolderStatus(c, notify) {
    if (!c || !holderApplies(c)) return '';
    var threshold = holderThreshold(c);
    var own = Math.max(0, Math.round(c.shares || 0));
    var hold = Math.max(0, Math.round(c.holderShares || 0));
    if (c.isHolder) {
      if (own + hold < threshold) {
        c.isHolder = false;
        // 股东权益保留（按当前权益来），仅失去股东身份
        var keepTxt = hold > 0 ? '（权益保留）' : '';
        c.lastReason = ('总持股低于总股本 ' + HOLDER_KEEP_PCT + '%，失去股东身份' + keepTxt).slice(0, 60);
        c.updatedAt = nowTs();
        if (notify && uiHooks.onToast) uiHooks.onToast('⚠ ' + c.name + '：总持股低于总股本 ' + HOLDER_KEEP_PCT + '%，已失去该公司股东身份' + keepTxt);
        return 'lose';
      }
    } else {
      if (own >= threshold) {
        c.isHolder = true;
        c.holderGranted = true;
        // 只恢复股东身份，不重新授予 20% 权益——按当前权益来（普通公司按我的持股计算）
        var eqTxt = c.holderShares > 0 ? ('（权益按当前 ' + c.holderShares + ' 股计）') : '（按我的持股计算）';
        c.lastReason = ('持股达到总股本 ' + HOLDER_KEEP_PCT + '%，恢复股东身份' + eqTxt).slice(0, 60);
        c.updatedAt = nowTs();
        if (notify && uiHooks.onToast) uiHooks.onToast('✅ ' + c.name + '：持股达到总股本 ' + HOLDER_KEEP_PCT + '%，恢复该公司股东身份' + (c.holderShares > 0 ? '（权益按当前 ' + fmtShares(c.holderShares) + ' 计）' : '（按我的持股计算）'));
        return 'gain';
      }
    }
    return '';
  }
  // 主角持有占比（散户持股 + 股东权益）/ 总股本
  function userRatio(c) {
    if (!c) return 0;
    var t = Number(c.totalShares) || 0;
    if (t <= 0) return 0;
    return ((Number(c.shares) || 0) + (Number(c.holderShares) || 0)) / t;
  }
  // 主角占比 > 50% → 成为公司老板，原老板转为股东
  function updateBossStatus(c, notify) {
    if (!c || c.mine || c.bankrupt) return '';
    var orig = c.owner || '';
    var r = userRatio(c);
    if (r > 0.5 && !c.userBoss) {
      c.userBoss = true;
      var holders = c.holders || (c.holders = []);
      var origNames = splitNames(orig);
      for (var oi = 0; oi < origNames.length; oi++) {
        var found = null;
        for (var i = 0; i < holders.length; i++) if (holders[i].name === origNames[oi]) { found = holders[i]; break; }
        if (found) { if (!found.role || found.role === '所属角色') found.role = '原老板'; }
        else holders.push({ name: origNames[oi], pct: 10, role: '原老板' });
      }
