    var nums = [];
    var re = /(\d{1,6})/g, m;
    while ((m = re.exec(str)) !== null && nums.length < 6) nums.push(parseInt(m[1], 10));
    if (!nums.length) return null;
    var hour = null, minute = 0, day = 0;
    if (nums.length >= 5) { day = nums[1] * 31 + nums[2]; hour = nums[3]; minute = nums[4]; }
    else if (nums.length === 4) { day = nums[0] * 31 + nums[1]; hour = nums[2]; minute = nums[3]; }
    else if (nums.length === 3) { day = nums[0]; hour = nums[1]; minute = nums[2]; }
    else if (nums.length === 2) { hour = nums[0]; minute = nums[1]; }
