      var ownerKind = '';
      for (var on = 0; on < ownerNames.length; on++) {
        if (rel.love[ownerNames[on]]) { ownerKind = 'love'; break; }
        if (!ownerKind && rel.important[ownerNames[on]]) ownerKind = 'important';
      }
      var holders = []; // 股东固定为所属角色（owner）与主角；AI 指定的其他人不计入
      var base = parseNumberLike(item.base);
