      if (Array.isArray(item.chain)) {
        for (var k = 0; k < item.chain.length && chain.length < MAX_HISTORY; k++) {
          var v = parseNumberLike(item.chain[k]);
          if (isFinite(v) && v > 0) chain.push(round2(v));
        }
      }
      if (chain.length < 2) chain = fallbackChain(base, name);
      if (Math.abs(chain[0] - base) > 0.01) { base = chain[0]; }
      var rawShares = Math.round(clampNum(parseNumberLike(item.shares), 0, 1e12, 0));
      var code = String(item.code || '').trim().toUpperCase().slice(0, 12);
