      }
      if (existing) {
        // 前后对应：已有公司不改写历史走势链，只把本次最新价续接到原走势链末尾
        applyPriceUpdate(existing, chain[chain.length - 1]);
        fitSharesToCap(existing);
        if (owner && !existing.owner) { existing.owner = owner; existing.ownerKind = ownerKind; }
        if (item.desc && !existing.desc) existing.desc = String(item.desc).slice(0, 80);
        expandOwnersBlood(existing);
