        desc: String(item.desc || '').slice(0, 80), owner: owner, ownerKind: ownerKind,
        mine: false, price: chain[chain.length - 1], basePrice: chain[0], history: chain,
        streakDown: 0, bankrupt: false, shares: 0, avgCost: 0,
        totalShares: rawShares || 1e8, loveStake: false,
        holders: holders, coFounded: false,
        lastReason: '上市（' + sourceLabel + '）', createdAt: nowTs(), updatedAt: nowTs()
      });
      if (!co) continue;
      if (co.code && co.code.length) {
        var dupCode = false;
        for (var d = 0; d < state.companies.length; d++) if (state.companies[d].code === co.code) dupCode = true;
        if (dupCode) co.code = uniqueCode(co.name);
      }
      applyChain(co, chain);
      fitSharesToCap(co);
      expandOwnersBlood(co);
      recomputeOwnerKind(co, rel);
      ensureOwnerHolders(co);
      if (ensureInitialHolder(co)) { /* 恋人企业：主角自动成为股东 20% */ }
      updateHolderStatus(co, false);
      updateBossStatus(co, false);
      state.companies.push(co);
