  function doBuy(companyId, qty) {
    var co = findCompany(companyId);
    if (!co) return { ok: false, msg: '找不到该公司' };
    if (co.bankrupt) return { ok: false, msg: '该公司已破产退市，无法买入' };
    qty = Math.round(clampNum(qty, 1, 999999, 0));
    if (qty <= 0) return { ok: false, msg: '请输入买入数量' };
    var cost = Math.round(co.price * qty);
    if (cost <= 0) cost = 1;
    var t = getTreasury();
    if (!t.ok) return { ok: false, msg: t.reason || '未检测到股市资金' };
    if (t.balance < cost) return { ok: false, msg: '股市资金余额不足：需要 ' + fmtNum(cost) + '，当前 ' + fmtNum(t.balance) };
    if (!treasuryAdjust(-cost, '买入 ' + co.name + '×' + qty + ' @' + fmtNum(co.price), 'stock-buy')) {
      return { ok: false, msg: '股市资金扣款失败' };
    }
    var totalCost = co.avgCost * co.shares + cost;
    co.shares += qty;
    co.avgCost = co.shares > 0 ? round2(totalCost / co.shares) : 0;
    co.myInvested = Math.round((Number(co.myInvested) || 0) + cost);
    co.updatedAt = nowTs();
    state.tradeNet = Math.round((Number(state.tradeNet) || 0) - cost);
    var hs = updateHolderStatus(co, true);
    var bs = updateBossStatus(co, true);
    saveState();
    return { ok: true, msg: '买入成功：' + co.name + ' ×' + qty + '，花费 ' + fmtNum(cost) + (hs === 'gain' ? '；已达到总股本 ' + HOLDER_KEEP_PCT + '%，恢复股东身份' : '') + (bs === 'boss' ? '；持股占比超过 50%，你成为公司老板' : '') };
  }
  function doSell(companyId, qty) {
    var co = findCompany(companyId);
