    if (co.bankrupt) return { ok: false, msg: '该公司已破产退市，持股已清零' };
    if (co.shares <= 0) return { ok: false, msg: '你没有该公司的股票' };
    qty = Math.round(clampNum(qty, 1, co.shares, 0));
    if (qty <= 0) return { ok: false, msg: '请输入卖出数量' };
    var revenue = Math.round(co.price * qty);
