  function showToast(msg, isErr) {
    var host = uiHost();
    if (!host) return;
    try {
      var old = host.querySelector('.ubp-stk-toast');
      if (old) old.remove();
      var el = DOC.createElement('div');
      el.className = 'ubp-stk-toast' + (isErr ? ' err' : '');
      el.textContent = msg;
      host.appendChild(el);
      if (toastTimer) clearTimeout(toastTimer);
      toastTimer = setTimeout(function () { try { el.remove(); } catch (e) {} }, isErr ? 4200 : 3000);
    } catch (e) {}
  }
