  // ---------- 执行流程 ----------
  function readNumInput(sel, dft) {
    var el = modalEl ? modalEl.querySelector(sel) : null;
    var n = el ? Number(el.value) : NaN;
    if (!isFinite(n)) return dft;
    return n;
  }
  function readNoteInput() {
    var el = modalEl ? modalEl.querySelector('[data-stk-note]') : null;
    return el ? String(el.value || '').trim().slice(0, 300) : '';
  }
  function doSaveSettings(silent) {
    var s = API.state();
    var q = function (k) { var el = appEl ? appEl.querySelector('[data-stk-in="' + k + '"]') : null; return el ? el.value : undefined; };
    var v;
    v = q('apiUrl'); if (v !== undefined) s.apiUrl = String(v).trim();
    v = q('apiKey'); if (v !== undefined) s.apiKey = String(v).trim();
    v = q('model'); if (v !== undefined) s.model = String(v).trim();
    v = q('jailbreak'); if (v !== undefined) s.jailbreak = String(v).trim().slice(0, 600);
    v = q('everyMinutes'); if (v !== undefined && isFinite(Number(v))) s.everyMinutes = Math.round(Math.min(1440, Math.max(1, Number(v))));
    v = q('everyFloors'); if (v !== undefined && isFinite(Number(v))) s.everyFloors = Math.round(Math.min(200, Math.max(1, Number(v))));
    v = q('contextFloors'); if (v !== undefined && isFinite(Number(v))) s.contextFloors = Math.round(Math.min(200, Math.max(0, Number(v))));
    API.saveState();
    if (!silent) showToast('✅ 设置已保存');
  }
  function runUpdateFlow(label, note) {
    if (API.isBusy()) { showToast('正在处理中，请稍候'); return; }
    genBar(true, note ? '正在按你的要求生成股市变化…' : '正在生成股市变化…');
    API.setBusy(true);
    API.runUpdatePrices(label || '手动', note || '').then(function (r) {
      API.setBusy(false);
      genBar(false);
      render();
      if (!r.applied && r.rawCount) {
        showToast('⚠ AI 返回了 ' + r.rawCount + ' 条行情，但未匹配到任何公司（请检查更新内容或重试）', true);
        return;
      }
      var msg = '✅ 更新完成：' + r.applied + ' 家变动（涨 ' + r.ups + ' / 跌 ' + r.downs + '），可点「↩ 撤回」撤销本场';
      if (r.bankrupt && r.bankrupt.length) msg += '；' + r.bankrupt.join('、') + ' 连续下跌 ' + API.BANKRUPT_STREAK + ' 次破产退市';
      showToast(msg);
    }, function (err) {
      API.setBusy(false);
      genBar(false);
      showToast('❌ ' + (err && err.message ? err.message : err), true);
    });
  }
  function runTextGen(companyId) {
    var from = Math.round(readNumInput('[data-stk-from]', 0));
    var to = Math.round(readNumInput('[data-stk-to]', 0));
    if (from < 0) from = 0;
    if (to < 0) to = 0;
    var note = readNoteInput();
    closeModal();
    genBar(true, companyId ? '正在读取正文生成该公司股价…' : '正在读取正文生成公司…');
    API.setBusy(true);
    var p = companyId ? API.runGenerateForCompany(companyId, 'text', from, to, 0, 0, note) : API.runGenerateFromText(from, to, note);
    p.then(function (r) {
      API.setBusy(false);
      genBar(false);
      render();
      if (companyId) showToast('✅ 股价已更新：' + r.company.name + ' → ' + fmtNum(r.company.price));
      else showToast('✅ 生成完成：新增 ' + r.added + ' 家' + (r.updated ? '，重估 ' + r.updated + ' 家' : '') + (r.coFound ? '，血缘共同开设 ' + r.coFound + ' 家' : '') + '公司');
    }, function (err) {
      API.setBusy(false);
      genBar(false);
      showToast('❌ ' + (err && err.message ? err.message : err), true);
    });
  }
  function runDbGen(companyId) {
    var note = readNoteInput();
    var cEl = modalEl ? modalEl.querySelector('[data-stk-cfrom]') : null;
    var cEl2 = modalEl ? modalEl.querySelector('[data-stk-cto]') : null;
    var chron = (cEl || cEl2) ? [Math.round(Number(cEl ? cEl.value : 0) || 0), Math.round(Number(cEl2 ? cEl2.value : 0) || 0)] : null;
    closeModal();
    genBar(true, companyId ? '正在读取数据库生成该公司股价…' : '正在读取数据库生成公司…');
    API.setBusy(true);
    var p = companyId ? API.runGenerateForCompany(companyId, 'db', 0, 0, 0, 0, note, chron) : API.runGenerateFromDb(note, chron);
    p.then(function (r) {
      API.setBusy(false);
      genBar(false);
      render();
      if (companyId) showToast('✅ 股价已更新：' + r.company.name + ' → ' + fmtNum(r.company.price));
      else showToast('✅ 生成完成：新增 ' + r.added + ' 家' + (r.updated ? '，重估 ' + r.updated + ' 家' : '') + (r.coFound ? '，血缘共同开设 ' + r.coFound + ' 家' : '') + '公司');
    }, function (err) {
      API.setBusy(false);
      genBar(false);
      showToast('❌ ' + (err && err.message ? err.message : err), true);
    });
  }
  function runListMine() {
    var m = modalEl;
    if (!m) return;
    var name = (m.querySelector('[data-stk-name]') || {}).value || '';
    var code = (m.querySelector('[data-stk-code]') || {}).value || '';
    var desc = (m.querySelector('[data-stk-cdesc]') || {}).value || '';
    var price = Number((m.querySelector('[data-stk-price]') || {}).value);
    var r = API.doListCompany(name, code, desc, price);
    if (!r.ok) { showToast('❌ ' + r.msg, true); return; }
    closeModal();
    view.page = 'detail';
    view.code = r.company.id;
    render();
    showToast('✅ ' + r.msg);
  }
  function loadModels() {
    var m = appEl;
    if (!m) return;
    var urlEl = m.querySelector('[data-stk-in="apiUrl"]');
    var keyEl = m.querySelector('[data-stk-in="apiKey"]');
    var statusEl = m.querySelector('[data-stk-modelstatus]');
    var listEl = m.querySelector('[data-stk-modellist]');
    if (!statusEl || !listEl) return;
    var apiUrl = urlEl ? urlEl.value.trim() : '';
    var apiKey = keyEl ? keyEl.value.trim() : '';
    if (!apiUrl) { statusEl.textContent = '⚠️ 请先填写 API 地址'; return; }
    statusEl.textContent = '⏳ 加载模型列表中…';
    listEl.style.display = 'none';
    listEl.innerHTML = '';
    var endpoints = [apiUrl.replace(/\/+$/, '') + '/v1/models', apiUrl.replace(/\/+$/, '') + '/models'];
    var models = [];
    var finish = function () {
      if (!models.length) { statusEl.textContent = '❌ 未能获取模型列表，请检查 API 地址和密钥'; return; }
      statusEl.textContent = '✅ 找到 ' + models.length + ' 个模型，点击选择';
      listEl.style.display = 'block';
      listEl.innerHTML = models.map(function (mm) {
        return '<div class="mi" data-stk-model="' + escAttr(mm) + '">' + esc(mm) + '</div>';
      }).join('');
    };
    var tryNext = function (i) {
      if (i >= endpoints.length) { finish(); return; }
      fetch(endpoints[i], { headers: apiKey ? { 'Authorization': 'Bearer ' + apiKey } : {} })
        .then(function (resp) { if (!resp.ok) throw new Error('http'); return resp.json(); })
        .then(function (data) {
          if (data && data.data && Array.isArray(data.data)) models = data.data.map(function (it) { return it.id; }).filter(function (id) { return typeof id === 'string'; });
          else if (data && Array.isArray(data.models)) models = data.models.map(function (it) { return it.id; }).filter(function (id) { return typeof id === 'string'; });
          if (models.length) finish();
          else tryNext(i + 1);
        })
        .catch(function () { tryNext(i + 1); });
    };
    tryNext(0);
  }

  // ---------- 打开 / 关闭（渲染进游戏大厅本体界面） ----------
  function detachStockUI() {
    closeModal();
    lpUp();
    if (overlay) { try { overlay.remove(); } catch (e) {} }
    overlay = null;
    appEl = null;
  }
  function openStockApp() {
    var D = DOC;
    if (!D || !D.body) return;
    if (typeof sheet === 'undefined' || !sheet) {
      try { if (typeof openGameApp === 'function') openGameApp(); } catch (e) {}
    }
    if (typeof sheet === 'undefined' || !sheet) return;
    detachStockUI();
    sheet.innerHTML = '';
    try { sheet.scrollTop = 0; } catch (e) {}
    var ov = DOC.createElement('div');
    ov.className = 'ubp-stk-overlay';
    ov.style.cssText = 'flex:1;min-height:0;border-radius:12px;overflow-y:auto;overflow-x:hidden;box-sizing:border-box;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column;background:var(--ubp-bg,#101014);';
    var app = DOC.createElement('div');
    app.className = 'ubp-stk-root';
    ov.appendChild(app);
    sheet.appendChild(ov);
    overlay = ov;
    appEl = app;
    view.page = 'list';
    view.tab = 'all';
    view.code = '';
    lastRenderedPage = '';
    ensureCss(D);
    ov.addEventListener('click', handleActClick);
    ov.addEventListener('pointerdown', lpDown);
    ov.addEventListener('pointerup', lpUp);
    ov.addEventListener('pointercancel', lpUp);
    ov.addEventListener('pointerleave', lpUp);
    render();
  }
  function closeStockApp() {
    detachStockUI();
    // 返回挣钱大厅（游戏大厅本体界面）
    try { if (typeof renderEarnLobby === 'function') renderEarnLobby(); } catch (e) {}
  }

  // ---------- 长按「更新行情」= 自定义输入 ----------
  var lpState = { timer: null, fired: false };
  function lpDown(e) {
    var t = e.target;
    if (!t || !t.closest) return;
    var btn = t.closest('[data-stk-act="refresh"], [data-stk-act="update-now"]');
    if (!btn) return;
    lpState.fired = false;
    if (lpState.timer) clearTimeout(lpState.timer);
    lpState.timer = setTimeout(function () {
      lpState.timer = null;
      lpState.fired = true;
      openUpdateNote();
      // 防止个别无 pointerdown 的点击路径被误吞：1.5 秒后自动解除
      setTimeout(function () { lpState.fired = false; }, 1500);
    }, 550);
  }
  function lpUp() {
    if (lpState.timer) { clearTimeout(lpState.timer); lpState.timer = null; }
  }

  // ---------- 事件处理 ----------
  function handleActClick(e) {
    var t = e.target;
    if (!t || !t.closest) return;
    var closeBtn = t.closest('[data-stk-mclose]');
    if (closeBtn) { closeModal(); return; }
    var modelItem = t.closest('[data-stk-model]');
    if (modelItem) {
      var mi = modelItem.getAttribute('data-stk-model') || '';
      var inp = appEl ? appEl.querySelector('[data-stk-in="model"]') : null;
      if (inp) inp.value = mi;
      var s = API.state();
      s.model = mi;
      API.saveState();
      var st = appEl.querySelector('[data-stk-modelstatus]');
      if (st) st.textContent = '已选择：' + mi;
      var l = appEl.querySelector('[data-stk-modellist]');
      if (l) l.style.display = 'none';
      return;
    }
    var tblItem = t.closest('[data-stk-tbl]');
    if (tblItem && modalEl) {
      var idx = Math.round(Number(tblItem.getAttribute('data-stk-tbl')) || 1);
      var fEl = modalEl.querySelector('[data-stk-tfrom]');
      var tEl = modalEl.querySelector('[data-stk-tto]');
      if (fEl && tEl) {
        var f = Math.round(Number(fEl.value) || 0), tt = Math.round(Number(tEl.value) || 0);
        if (!f || !tt || f === tt) { fEl.value = Math.min(f || idx, idx); tEl.value = Math.max(tt || idx, idx); }
        else { fEl.value = idx; tEl.value = idx; }
        var items = modalEl.querySelectorAll('.ubp-stk-titem');
        var fv = Math.round(Number(fEl.value) || 1), tv = Math.round(Number(tEl.value) || 1);
        for (var i = 0; i < items.length; i++) {
          var cur = Math.round(Number(items[i].getAttribute('data-stk-tbl')) || 0);
          items[i].classList.toggle('on', cur >= Math.min(fv, tv) && cur <= Math.max(fv, tv));
        }
      }
      return;
    }
    var actEl = t.closest('[data-stk-act]');
    var openEl = t.closest('[data-stk-open]');
    if (actEl) {
      var act = actEl.getAttribute('data-stk-act');
      var id = actEl.getAttribute('data-id') || '';
      if (act === 'back') {
        if (view.page !== 'list') {
          if (view.page === 'settings') doSaveSettings(true); // 离开设置自动保存，避免重开丢失
          view.page = 'list'; view.code = ''; render();
        } else closeStockApp();
        return;
      }
      if (act === 'settings') { doSaveSettings(true); view.page = 'settings'; render(); return; }
      if (act === 'ai-menu') { openAiMenu(); return; }
      if (act === 'ai-from-text') { closeModal(); openTextRange(''); return; }
      if (act === 'ai-from-db') { closeModal(); openDbRange(''); return; }
      if (act === 'tab') { view.tab = actEl.getAttribute('data-tab') || 'all'; render(); return; }
      if (act === 'refresh') {
        if (lpState.fired) { lpState.fired = false; return; }
        doSaveSettings(true); runUpdateFlow('手动'); return;
      }
      if (act === 'undo-market') {
        var ur = API.doUndoMarket();
        showToast((ur.ok ? '✅ ' : '❌ ') + ur.msg, !ur.ok);
        if (ur.ok) render();
        return;
      }
      if (act === 'inject-open') { closeModal(); openInject(id); return; }
      if (act === 'iqty') {
        var iq = modalEl ? modalEl.querySelector('[data-stk-iqty]') : null;
        if (iq) iq.value = actEl.getAttribute('data-q') || '1';
        return;
      }
      if (act === 'do-inject') {
        var iq2 = modalEl ? modalEl.querySelector('[data-stk-iqty]') : null;
        var qv = iq2 ? Math.round(Number(iq2.value) || 0) : 0;
        var ir = API.doInject(id, qv);
        closeModal();
        showToast((ir.ok ? '✅ ' : '❌ ') + ir.msg, !ir.ok);
        if (ir.ok) render();
        return;
      }
      if (act === 'invite-open') { closeModal(); openInvite(id); return; }
      if (act === 'allot-open') { closeModal(); openAllot(id); return; }
      if (act === 'do-allot') {
        var allotList = [];
        if (modalEl) {
          var apInputs = modalEl.querySelectorAll('[data-stk-apct]');
          for (var ai = 0; ai < apInputs.length; ai++) allotList.push({ name: apInputs[ai].getAttribute('data-stk-apct'), pct: Number(apInputs[ai].value) });
        }
        var ar = API.doAllotHolders(id, allotList);
        if (ar.ok) closeModal();
        showToast((ar.ok ? '✅ ' : '❌ ') + ar.msg, !ar.ok);
        if (ar.ok) render();
        return;
      }
      if (act === 'invite-pick') {
        if (!modalEl) return;
        var iname = actEl.getAttribute('data-stk-invite') || '';
        modalEl.__stkInvite = iname;
        var its = modalEl.querySelectorAll('[data-stk-invite]');
        for (var ii = 0; ii < its.length; ii++) its[ii].classList.toggle('on', its[ii].getAttribute('data-stk-invite') === iname);
        return;
      }
      if (act === 'do-invite') {
        var pctEl = modalEl ? modalEl.querySelector('[data-stk-ipct]') : null;
        var pctV = pctEl ? Number(pctEl.value) : 5;
        var iname2 = modalEl ? modalEl.__stkInvite : '';
        if (!iname2) { showToast('请先在列表中选择要邀请的角色', true); return; }
        var ivr = API.doInviteHolder(id, iname2, pctV);
        closeModal();
        showToast((ivr.ok ? '✅ ' : '❌ ') + ivr.msg, !ivr.ok);
        if (ivr.ok) render();
        return;
      }
      if (act === 'run-update-note') {
        var unEl = modalEl ? modalEl.querySelector('[data-stk-note-update]') : null;
        var un = unEl ? String(unEl.value || '').trim().slice(0, 300) : '';
        closeModal();
        doSaveSettings(true);
        runUpdateFlow('手动', un);
        return;
      }
      if (act === 'list-mine') { openListMine(); return; }
      if (act === 'run-list-mine') { runListMine(); return; }
      if (act === 'range-quick') {
        if (modalEl) {
          var fEl2 = modalEl.querySelector('[data-stk-from]');
          var tEl2 = modalEl.querySelector('[data-stk-to]');
          if (fEl2) fEl2.value = actEl.getAttribute('data-from') || 0;
          if (tEl2) tEl2.value = actEl.getAttribute('data-to') || 0;
        }
        return;
      }
      if (act === 'chron-quick') {
        if (modalEl) {
          var cfEl = modalEl.querySelector('[data-stk-cfrom]');
          var ctEl = modalEl.querySelector('[data-stk-cto]');
          if (cfEl) cfEl.value = actEl.getAttribute('data-from') || 0;
          if (ctEl) ctEl.value = actEl.getAttribute('data-to') || 0;
        }
        return;
      }
      if (act === 'run-text-gen') { runTextGen(id); return; }
      if (act === 'run-db-gen') { runDbGen(id); return; }
      if (act === 'qty') {
        var qEl = appEl ? appEl.querySelector('[data-stk-qty]') : null;
        if (qEl) qEl.value = actEl.getAttribute('data-q') || '1';
        return;
      }
      if (act === 'buy' || act === 'sell') {
        var co = API.findCompany(id);
        if (!co) return;
        var qIn = appEl ? appEl.querySelector('[data-stk-qty]') : null;
        var qty = qIn ? Math.round(Number(qIn.value) || 0) : 0;
        var r = act === 'buy' ? API.doBuy(id, qty) : API.doSell(id, qty);
        showToast((r.ok ? '✅ ' : '❌ ') + r.msg, !r.ok);
        if (r.ok) render();
        return;
      }
      if (act === 'own-ai-text') { openTextRange(id); return; }
      if (act === 'own-ai-db') { openDbRange(id); return; }
      if (act === 'remove-company') {
        var co2 = API.findCompany(id);
        openConfirm('移除公司', '确定把「' + (co2 ? co2.name : '') + '」从股市移除吗？该操作不可撤销。', 'do-remove-company', id);
        return;
      }
      if (act === 'do-remove-company') {
        var r2 = API.doRemoveCompany(id);
        closeModal();
        showToast((r2.ok ? '✅ ' : '❌ ') + r2.msg, !r2.ok);
        if (r2.ok) { view.page = 'list'; view.code = ''; render(); }
        return;
      }
      if (act === 'chk-mode') {
        doSaveSettings(true);
        var cmode = actEl.getAttribute('data-mode') || 'off';
        var sc = API.state();
        if (cmode === 'off') { sc.timeEnabled = false; sc.floorEnabled = false; }
        else if (cmode === 'time') { sc.timeEnabled = !sc.timeEnabled; }
        else if (cmode === 'floor') { sc.floorEnabled = !sc.floorEnabled; }
        if (sc.floorEnabled && sc.lastUpdateMesId < 0) {
          var lmf = API.getLastMesId();
          if (lmf >= 0) sc.lastUpdateMesId = lmf;
        }
        API.saveState();
        if (appEl) {
          var boxes = appEl.querySelectorAll('.ubp-stk-check');
          for (var bi = 0; bi < boxes.length; bi++) {
            var bm = boxes[bi].getAttribute('data-mode') || '';
            var bon = bm === 'time' ? sc.timeEnabled : (bm === 'floor' ? sc.floorEnabled : (!sc.timeEnabled && !sc.floorEnabled));
            boxes[bi].classList.toggle('on', bon);
          }
        }
        var modeTxt = (sc.timeEnabled && sc.floorEnabled) ? '已勾选：剧情时间 + 楼层（同时生效）'
          : (sc.timeEnabled ? '已勾选：按剧情时间自动更新' : (sc.floorEnabled ? '已勾选：按楼层自动更新' : '已关闭自动更新'));
        showToast(modeTxt);
        return;
      }
      if (act === 'seg-mode') {
        doSaveSettings(true);
        var mode = actEl.getAttribute('data-mode') || 'off';
        var s2 = API.state();
        s2.timeEnabled = mode === 'time';
        s2.floorEnabled = mode === 'floor';
        if (s2.floorEnabled) { var lm = API.getLastMesId(); if (lm >= 0) s2.lastUpdateMesId = lm; }
        if (s2.timeEnabled) { s2.lastStoryTime = ''; s2.lastStoryMin = null; s2.lastUpdateTs = Date.now(); }
        API.saveState();
        render();
        showToast(mode === 'off' ? '已关闭自动更新' : (mode === 'time' ? '已开启：按剧情时间自动更新（以主项目「当前时间」为基准）' : '已开启：按楼层自动更新'));
        return;
      }
      if (act === 'save-settings') { doSaveSettings(false); return; }
      if (act === 'load-models') { doSaveSettings(true); loadModels(); return; }
      if (act === 'update-now') {
        if (lpState.fired) { lpState.fired = false; return; }
        doSaveSettings(true); runUpdateFlow('手动'); return;
      }
      if (act === 'clear-data') {
        var settle = API.previewClearSettle();
        var settleTxt = settle > 0
          ? ('清空时将返还 ' + fmtNum(settle) + ' 至股市资金（你在股市为净支出）。')
          : (settle < 0 ? ('清空时将从股市资金扣除 ' + fmtNum(-settle) + '（你在股市为净收益）。') : '本次清空无需资金结算。');
        openConfirm('清空股市数据', '将删除本聊天下所有上市公司、股价链、股东与持仓记录。' + settleTxt + ' 确定继续吗？', 'do-clear-data');
        return;
      }
      if (act === 'do-clear-data') {
        var cr = API.doClearMarket();
        closeModal();
        showToast((cr.ok ? '✅ ' : '❌ ') + cr.msg, !cr.ok);
        if (cr.ok) render();
        return;
      }
      return;
    }
    if (openEl) {
      view.page = 'detail';
      view.code = openEl.getAttribute('data-stk-open') || '';
      render();
    }
  }

  // ---------- 初始化 ----------
