(() => {
  'use strict';

  const BADGE_CLASS = 'th-floor-body-count';
  const STYLE_ID = 'th-floor-body-count-style';
  const WAND_CONTAINER_ID = 'th-floor-body-count-wand-container';
  const WAND_ITEM_ID = 'th-floor-body-count-wand-item';
  const MODAL_ID = 'th-floor-body-count-modal';
  const SETTINGS_KEY = 'floorBodyCounter';
  const parentDocument = window.parent.document;
  const singleFloorTimers = new Map();
  let allFloorsTimer = null;
  let wandWatchTimer = null;
  let currentSettings = null;
  let modalViewportCleanup = null;

  const ALWAYS_IGNORED_TAGS = ['script', 'style', 'svg', 'head'];
  const MAX_TAGS = 32;
  const MAX_TAG_LENGTH = 64;
  const MAX_TAG_INPUT_LENGTH = 2048;
  const DEFAULT_SETTINGS = Object.freeze({
    mode: 'exclude',
    tags: [
      'think',
      'thinking',
      'analysis',
      'reasoning',
      'details',
      'status',
      'statusbar',
      'statusblock',
      'statebar',
      'stateblock',
      'updatevariable',
    ],
  });

  function cloneDefaultSettings() {
    return { mode: DEFAULT_SETTINGS.mode, tags: [...DEFAULT_SETTINGS.tags] };
  }

  function escapeRegExp(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function parseTagList(input) {
    const text = String(input ?? '').slice(0, MAX_TAG_INPUT_LENGTH);
    const angleTags = [...text.matchAll(/<\s*\/?\s*([\p{L}_][\p{L}\p{N}_.:-]*)\b[^>]*>/gu)].map(
      match => match[1],
    );
    const plainTags = text
      .replace(/<[^>]*>/g, ' ')
      .split(/[\s,，、;；]+/u)
      .map(tag => tag.trim())
      .filter(tag => /^[\p{L}_][\p{L}\p{N}_.:-]*$/u.test(tag));

    return [...new Set([...angleTags, ...plainTags].map(tag => tag.toLowerCase()))]
      .filter(tag => tag.length <= MAX_TAG_LENGTH)
      .slice(0, MAX_TAGS);
  }

  function sanitizeSettings(value) {
    const mode = value?.mode === 'extract' ? 'extract' : 'exclude';
    const tags = Array.isArray(value?.tags) ? parseTagList(value.tags.join('\n')) : [];
    return { mode, tags };
  }

  function loadSettings() {
    try {
      const data = getVariables({ type: 'script', script_id: getScriptId() });
      if (!data?.[SETTINGS_KEY]) return cloneDefaultSettings();
      return sanitizeSettings(data[SETTINGS_KEY]);
    } catch (error) {
      console.warn('[楼层正文计数器] 读取设置失败，已使用默认设置。', error);
      return cloneDefaultSettings();
    }
  }

  function saveSettings(settings) {
    const sanitized = sanitizeSettings(settings);
    const data = getVariables({ type: 'script', script_id: getScriptId() });
    data[SETTINGS_KEY] = sanitized;
    replaceVariables(data, { type: 'script', script_id: getScriptId() });
    currentSettings = sanitized;
