.ball:hover .ball-face { transform: scale(1.05); }
.ball:active .ball-face, .ball.is-dragging .ball-face { transform: scale(1.08); box-shadow: 0 0 0 2px #fff, 0 0 0 3.5px var(--rose), 0 18px 34px -8px rgba(110, 52, 74, 0.55); }
