}

/* --- 隐藏思维链标题背景 by kemvnni --- */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_header {
  position: relative;
  width: 100%;
  min-width: 0;
  height: max(20px, 4cqw);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--wd-page-color);
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_header::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--wd-reasoning-image) center / 100% auto no-repeat;
  pointer-events: none;
}

/* --- 自定义思维链标题 by Nakari --- */
/* 图片替代可见标题；原文字保留为可访问名称。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_header_title {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* --- 隐藏思维链下拉箭头 by hy --- */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_arrow {
  display: none;
}

/* 04.2 思维链操作：收起、复制与编辑位于入口右下方。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_actions {
  position: absolute;
  top: 9cqw;
  left: auto;
  right: -14cqw;
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: 8px;
  margin: 0;
  color: var(--wd-page-color);
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_actions .mes_button,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning_actions .edit_button {
  color: var(--wd-page-color);
  opacity: 1;
}

/* 04.3 正文与思维链内容：沿用主题字色、字号，允许长文本换行。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_text,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  margin: 0;
  padding: 0;
  line-height: 1.8;
  overflow-wrap: anywhere;
  background: transparent;
}

/* --- 思维链可滑动容器 by 决 --- */
/* 滚动与强调边框应用于本主题实际使用的 .mes_reasoning 节点。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_reasoning {
  /* 🦋 思维链最大高度；超长内容在框内滚动。 */
  --wd-reasoning-max-height: 200px;
  max-height: var(--wd-reasoning-max-height);
  min-height: 0;
  overflow: auto;
  margin-top: 8px;
  padding: 12px clamp(12px, 2cqw, 16px);
  border: 1px solid rgba(151, 174, 198, 0.7);
  border-left: 3px solid #8FAAC1;
  border-radius: 0 8px 8px 0;
  background: linear-gradient(135deg,
    rgba(255, 255, 255, 0.72) 0%,
    rgba(235, 242, 250, 0.66) 55%,
    rgba(204, 220, 237, 0.64) 100%);
}

/* 04.4 行内代码、引用、链接与长内容 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) :is(.mes_text, .mes_reasoning) code:not(pre code) {
  background: rgba(255, 255, 255, 0.3);
  border: 1px solid #FFFFFF;
  border-radius: 0;
  color: inherit;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
  background: #E2EDF8;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) :is(.mes_text, .mes_reasoning) q {
  background: linear-gradient(to right, rgba(107, 129, 158, 0.6), rgba(107, 129, 158, 0.3));
  padding: 0.05em 0.2em;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) :is(.mes_text, .mes_reasoning) a {
  text-decoration: underline;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) :is(.mes_text, .mes_reasoning) pre {
  max-width: 100%;
  overflow-x: auto;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) :is(.mes_text, .mes_reasoning) img {
  max-width: 100%;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) :is(.edit_textarea, .reasoning_edit_textarea) {
  box-sizing: border-box;
  width: 100%;
  min-height: 8em;
  background: #EDF2F8;
  border: 1px solid #A7B8CA;
  border-radius: 4px;
}

/* --- 分割线自定义图片样式 by hy --- */
/* 04.5 分割线：单张居中，35px 高度内等比显示。 */
hr {
  height: 35px !important;
  background-image: url("https://qianqianqiu.date/file/studio/yqxZW0CDkm8TWp1s.png") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  border: none !important;
  margin: 5px 0 !important;
  background-color: transparent !important;
  opacity: 1 !important;
}

/* ===== 05 | 顶栏背景与导航图标 ===== */

/* 05.1 云蓝背景与向下渐隐蒙版 */
/* 背景独立延伸，不占按钮布局空间，也不接收点击。 */
#top-bar,
body.no-blur #top-bar {
  /* 🦋 顶栏背景素材 */
  --wd-top-background: url("https://qianqianqiu.date/file/studio/g2lRbv6gUNVnmFxX.png");
  /* 🦋 渐变距离与透明度曲线 */
  --wd-top-fade-reach: clamp(60px, calc(var(--sheldWidth) / 10), 100px);
  --wd-top-fade: linear-gradient(
    to top,
    transparent 0,
    rgba(0, 0, 0, 0.02) calc(var(--wd-top-fade-reach) * 0.06),
    rgba(0, 0, 0, 0.12) calc(var(--wd-top-fade-reach) * 0.18),
    rgba(0, 0, 0, 0.37) calc(var(--wd-top-fade-reach) * 0.35),
    rgba(0, 0, 0, 0.68) calc(var(--wd-top-fade-reach) * 0.55),
    rgba(0, 0, 0, 0.90) calc(var(--wd-top-fade-reach) * 0.75),
    rgba(0, 0, 0, 0.98) calc(var(--wd-top-fade-reach) * 0.90),
    #000 var(--wd-top-fade-reach),
    #000 100%
  );
  height: calc(var(--topBarBlockSize) + var(--wd-top-fade-reach));
  background: #D5DFEC var(--wd-top-background) center / max(calc(100% * var(--wd-top-scale)), calc((var(--topBarBlockSize) + var(--wd-top-fade-reach)) * 4.894737)) auto no-repeat !important;
  border: 0;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  -webkit-mask-image: var(--wd-top-fade);
  mask-image: var(--wd-top-fade);
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  mask-mode: alpha;
  pointer-events: none;
}

/* 05.2 导航按钮尺寸与焦点颜色 */
/* 十个按钮按可用宽度限幅；每只蝴蝶的大小、位置与倾角在下方分别设置。 */
#top-settings-holder {
  --wd-top-icon-box-size: min(var(--topBarBlockSize), calc(var(--sheldWidth) / 10));
  --wd-top-active-color: #576C85;
  background: transparent !important;
