}

/* 5 · 用户设置 */
#top-settings-holder > .drawer:nth-of-type(5) {
  --wd-top-icon: url("https://qianqianqiu.date/file/studio/Y5u9Z9WEdWNas1Me.png");
  --wd-top-icon-size: 72%;
  --wd-top-icon-x: 52%;
  --wd-top-icon-y: 57%;
  --wd-top-icon-tilt: 6deg;
}

/* 6 · 背景 */
#top-settings-holder > .drawer:nth-of-type(6) {
  --wd-top-icon: url("https://qianqianqiu.date/file/studio/agkUWvvMDfm3ZE5l.png");
  --wd-top-icon-size: 68%;
  --wd-top-icon-x: 50%;
  --wd-top-icon-y: 48%;
